P.entries["item:steelgrill-s-tools"] = {n="贝尔丁的工具",s="贝尔丁的工具是为钢架补给站的首席技师贝尔丁·钢架专门征集的机械维修工具。贝尔丁以将攻城引擎及其自身设备的性能压榨到极限而闻名，他经常损坏装备，因此需要依赖附近的卡拉诺斯运送补给来维持车间的运转。",h="贝尔丁的工具是为钢架补给站的首席技师贝尔丁·钢架专门征集的机械维修工具。贝尔丁以将攻城引擎及其自身设备的性能压榨到极限而闻名，他经常损坏装备，因此需要依赖附近的卡拉诺斯运送补给来维持车间的运转。",kw={"贝尔丁","补给站","卡拉诺斯","棘齿城","攻城引擎","扳手","钢架","工具"},ang={["profession:Engineering"]="每一位工程师都能理解贝尔丁的困境，因为对沉重的攻城引擎进行高扭矩修理通常会损耗弧光扳手和精密扳手。",["race:Dwarf"]="维护联盟的装甲攻城引擎是矮人的骄傲，确保贝尔丁的补给充足能让铁炉堡的装甲先锋队随时保持战斗状态。"},sec={{t="笨手笨脚的工匠",b="贝尔丁·钢架被公认为丹莫罗最优秀的攻城引擎技师之一，但他那粗暴的修理风格在当地商贩中可谓臭名昭著。贝尔丁在装甲坦克和机械装置上没日没夜地工作，他摧毁精密设备的速度几乎和设备制造出来的速度一样快。从扭断弧光扳手到磨坏齿轮棘轮，这位技师不断地在卡拉诺斯下达新的订单，以保证他的修理台上有充足的工具。"},{t="让引擎转动起来",b="这批工具对于维持铁炉堡的战争机器运转至关重要。在卡拉诺斯东北部的补给站里，贝尔丁正在积极地为像驾驶员迪恩·石轮这样经验丰富的驾驶员修理战斗载具。如果没有及时供应扳手和棘轮，关键的攻城引擎只能在雪地里半拆解地搁置着，导致补给站和当地的防御陷入停滞。"}},faq={{q="贝尔丁的工具是用来做什么的？",a="它们是交付给钢架补给站的贝尔丁·钢架的替换机械工具。贝尔丁需要这些工具来检修沉重的矮人机械，特别是属于驾驶员迪恩·石轮的那台受损的攻城引擎。",al={"这些工具是什么","贝尔丁的工具用途"}},{q="为什么贝尔丁·钢架消耗这么多工具？",a="贝尔丁是一位异常粗暴的技师，他会将装备的使用推向极限。据卡拉诺斯的供应商称，他折断弧光扳手和弄坏齿轮棘轮的速度，几乎比当地工匠制造的速度还要快。",al={"为什么工具会损坏","为什么贝尔丁需要工具"}},{q="这箱工具是从哪里来的？",a="这批货物是在附近的卡拉诺斯定居点组装并发出的，随后交由前往东北方向钢架补给站的旅人携带。",al={"我在哪里能获得工具","工具货物的来源"}},{q="贝尔丁·钢架是谁？",a="贝尔丁是一位矮人首席技师，他拥有并经营着位于卡拉诺斯东北部的钢架补给站。他被认为是该地区首屈一指的攻城引擎技师。",al={"贝尔丁是谁","贝尔丁·钢架背景故事"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="钢齿土狼的肋骨",s="钢齿土狼的肋骨是取自千针石林中凶残的鬣狗钢齿土狼尸体的一件冷酷战利品。被带回雷霆崖后，它作为实物证明，标志着一只被视为游离于大地母亲祝福之外的生物已被除掉。",h="钢齿土狼的肋骨是取自千针石林中凶残的鬣狗钢齿土狼尸体的一件冷酷战利品。被带回雷霆崖后，它作为实物证明，标志着一只被视为游离于大地母亲祝福之外的生物已被除掉。",kw={"伊索克营地","猎人高地","鬣狗","梅洛·石蹄","钢齿土狼","钢齿土狼的肋骨","千针石林","雷霆崖"},ang={["class:Hunter"]="取走顶级兽群领袖的肋骨，是对猎人追踪危险猎物以及剔除破坏荒野平衡的威胁能力的考验。",["race:Tauren"]="对于牛头人来说，带回这件战利品是为了履行对大地母亲的职责，即铲除一只其残忍行径破坏了神圣平衡的生物。"},sec={{t="一场在祝福之外的狩猎",b="大多数牛头人的狩猎都是为了维持生计、For Honor或寻求与自然的和谐。然而，钢齿土狼代表着另一种猎物。这只凶残的鬣狗首领徘徊在伊索克营地以南的千针石林峡谷底部，恐吓着宁静的野生动物，并集结成群的低等掠食者进行毫无意义的杀戮。当猎人高地上的狩猎大师梅洛·石蹄标记了钢齿土狼并要求将其击杀时，他索要一根沉重的骨头——钢齿土狼的肋骨——作为无可辩驳的证据，以确认这个暴君已被诛杀，峡谷已洗净其祸害。"}},faq={{q="钢齿土狼的肋骨有什么用？",a="这根肋骨需要带给雷霆崖猎人高地上的梅洛·石蹄，以完成钢齿土狼的狩猎任务。它是这只凶残鬣狗已被击败的有力证明。",al={"钢齿土狼的肋骨任务","谁想要钢齿土狼的肋骨","钢齿土狼的肋骨怎么用"}},{q="我在哪里能找到钢齿土狼以获得肋骨？",a="钢齿土狼在千针石林的西北部游荡，经常在伊索克营地以南的峡谷底部漫步，身边通常有忠诚的同伙。",al={"钢齿土狼位置","钢齿土狼在哪里","寻找钢齿土狼"}},{q="梅洛·石蹄为什么要杀掉钢齿土狼？",a="梅洛认为钢齿土狼是一个游离于大地母亲祝福之外的非自然暴君。与为了生存而捕猎的普通掠食者不同，钢齿土狼在平静的野兽中散布无端的流血和恐惧，因此必须将其消灭。",al={"为什么要杀钢齿土狼","梅洛·石蹄的目的","钢齿土狼背景故事"}},{q="梅洛·石蹄是谁？",a="梅洛·石蹄是一位驻扎在雷霆崖猎人高地上的资深牛头人猎人，他指派有抱负的追踪者在卡利姆多各地追踪危险的野兽。",al={"梅洛是谁","梅洛·石蹄位置","猎人高地梅洛"}}},fp="15,188,27.407.0,33.104.0,42.121.0,47.182.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="被偷走的银币",s="“被偷走的银币”是一个失而复得的保险箱，里面装有原本用于十字路口卫兵驻军的部落钱币。令人难以置信的是，它竟被贫瘠之地的凶猛迅猛龙带入了荒野，这让该哨所的监管者们感到匪夷所思。",h="“被偷走的银币”是一个失而复得的保险箱，里面装有原本用于十字路口卫兵驻军的部落钱币。令人难以置信的是，它竟被贫瘠之地的凶猛迅猛龙带入了荒野，这让该哨所的监管者们感到匪夷所思。",kw={"贫瘠之地薪水","十字路口","加兹罗格","迅猛龙巢穴","银制保险箱","被偷走的银币","阳鳞迅猛龙"},ang={["faction:Horde"]="十字路口是部落在贫瘠之地驻扎的战略核心。找回这笔薪水能确保当地的士兵有饭吃、有薪水拿，并随时准备好坚守阵线，抵御半人马和联盟的入侵。"},sec={{t="野兽的劫案",b="贫瘠之地广袤的荒野时刻威胁着补给线，但很少有人料到当地的阳鳞迅猛龙竟然会盯上金属货币的保险箱。当一批原本作为十字路口驻军薪水的银币从岗哨塔被偷走后，迅猛龙将保险箱拖回了棘齿城南部的迅猛龙巢穴。对于像加兹罗格这样的监管者来说，这次盗窃显示出这些掠食者拥有令人不安的狡猾程度，它们显然对闪闪发光的小玩意情有独钟，或者表现出了远超普通野兽的智慧。"}},faq={{q="什么是“被偷走的银币”？",a="这是一个沉重的保险箱，里面装满了原本用于支付十字路口卫兵薪水的银币。它被迅猛龙从十字路口的岗哨塔偷走，并被带到了它们的筑巢地。",al={"什么是被偷走的银币","银币是什么"}},{q="迅猛龙为什么要偷装钱的保险箱？",a="这些掠食者的动机即使对像加兹罗格这样经验丰富的战士来说也是一个谜。虽然动物通常是为了寻找食物，但贫瘠之地的迅猛龙以非同寻常的狡猾著称，这些野兽是被吸引并把闪闪发光的金属箱拖进了它们巢穴深处。",al={"迅猛龙为什么想要银币","迅猛龙的智慧","为什么是银币"}},{q="银币被带到哪里去了？",a="迅猛龙将保险箱拖到了迅猛龙巢穴，那是一个位于贫瘠之地东部、棘齿城南部的崎岖峡谷巢穴。",al={"被偷走的银币位置","银币在哪里"}},{q="谁在寻找“被偷走的银币”？",a="驻扎在十字路口的兽人加兹罗格正在寻找这个箱子。这笔资金是该哨所饱受压力的防御者们一个月的全额薪水。",al={"谁想要银币","谁会接收被偷走的银币"}}},fp="13,175,15.431.0,26.160.0,41.182.0,27.117.0,37.144.0"}
P.entries["item:stone-of-relu"] = {n="雷鲁之石",s="雷鲁之石是从湿地挖掘出的一件古代考古遗物。考古学家弗拉冈特认为它是解锁原始化石中潜藏力量的关键，但在他被当地迅猛龙伏击时遗失了。",h="雷鲁之石是从湿地挖掘出的一件古代考古遗物。考古学家弗拉冈特认为它是解锁原始化石中潜藏力量的关键，但在他被当地迅猛龙伏击时遗失了。",kw={"考古学家弗拉冈特","探险者协会","化石","斑点迅猛龙","勘察员维尔加","雷鲁之石","湿地"},ang={["faction:Alliance"]="米奈希尔港的联盟探险队依靠像雷鲁之石这样回收的文物，来证明在危险的湿地进行艰苦挖掘的合理性。",["race:Dwarf"]="对于探险者协会来说，雷鲁之石是拼凑古代生命起源和世界被遗忘的遗产的重要工具。"},sec={{t="古代遗物的钥匙",b="雷鲁之石是在探险者协会的行动中被发现的，据信它拥有破解来自卡利姆多和东部王国的史前化石所需的破译能力。考古学家弗拉冈特认为该文物是揭开他自己的湿地标本以及勘察员雷姆塔维尔在黑海岸挖掘出的化石秘密所需的催化剂。"},{t="迷失在沼泽中",b="当弗拉冈特在湿地的道路上前往与勘察员维尔加汇合时，一群斑点迅猛龙伏击了他。在混乱中，遗物被弄丢并被其中一只贪婪的野兽吞下，这迫使协会招募冒险者去猎杀沼泽迅猛龙，并将这块古老的石头从它们的喉咙中取出来。"}},faq={{q="什么是雷鲁之石？",a="雷鲁之石是考古学家弗拉冈特正在寻找的一件古代文物。他认为它是一种能够解锁史前化石中潜藏的神秘力量和秘密的密码或催化剂。",al={"雷鲁之石","这块石头是什么","雷鲁文物"}},{q="这块石头是怎么进到迅猛龙肚子里的？",a="考古学家弗拉冈特带着这件遗物沿湿地道路前往会见勘察员维尔加时，遭到了斑点迅猛龙的袭击。在混乱中，石头被弄丢并被其中一只食腐野兽吞掉了。",al={"为什么迅猛龙有它","谁弄丢了石头","它怎么丢失的"}},{q="弗拉冈特打算用这块石头做什么？",a="弗拉冈特打算将这块石头与他回收的化石以及勘察员雷姆塔维尔在黑海岸发现的化石结合使用，利用该遗物来解读并释放它们潜藏的魔法秘密。",al={"弗拉冈特想要什么","雷鲁之石的用途"}}},fp="13,150,23.277.0,19.287.0,26.160.0,41.179.0,48.168.0"}
P.entries["item:stonetalon-sap"] = {n="石爪苔液",s="石爪苔液是一种粘稠而强效的物质，直接采集自徘徊在石爪山脉崎岖高地上的笨重树脂兽。它是暗矛巫医金吉尔的一味关键试剂，金吉尔利用其原始的森林特性来调制一种恶毒的药水。",h="石爪苔液是一种粘稠而强效的物质，直接采集自徘徊在石爪山脉崎岖高地上的笨重树脂兽。它是暗矛巫医金吉尔的一味关键试剂，金吉尔利用其原始的森林特性来调制一种恶毒的药水。",kw={"金吉尔","玛拉卡金","暗色湖","树脂兽","石爪峰","石爪苔液"},ang={["race:NightElf"]="部落巫医亵渎石爪的自然元素来毒害被囚禁的精灵，这是对自然和艾露恩的暴行。",["race:Troll"]="巫医金吉尔展示了暗矛巨魔将敌人的挚爱环境转化为致命巫毒工具的天赋。"},sec={{t="苦涩的收割",b="这种浓稠的液体滴落自暗色湖和石爪峰附近的树栖树脂兽身上，蕴含着山脉古老植物群的精华。虽然在自然状态下处于休眠时它是无害的，但这种树脂在经验丰富的炼金术士或巫医手中很容易变成更黑暗的东西。玛拉卡金的金吉尔觊觎它，并将其戏称为“森林魔法”来调制——这是一种致命的药剂，旨在用囚禁的暗夜精灵们珍视的荒野本质来折磨他们。"}},faq={{q="什么生物携带石爪苔液？",a="它是从树脂兽身上采集的，这是一种奇怪的林地生物，出没于暗色湖附近以及通往石爪峰的斜坡高处。",al={"哪里可以获得石爪苔液","谁掉落石爪苔液","树脂兽"}},{q="巫医金吉尔用这种苔液做什么？",a="金吉尔将苔液与迅猛龙之眼、暮光胡须和一片灵龙的鳞片混合，调制出一种剧毒药水，用来折磨他囚禁的暗夜精灵俘虏。",al={"金吉尔为什么想要苔液","金吉尔的森林魔法配方"}},{q="去哪里找树脂兽最好？",a="树脂兽栖息在暗色湖周围的树林，以及通往石爪峰的郁郁葱葱的小径上。",al={"树脂兽位置","暗色湖的树脂兽"}},{q="这种苔液本身有魔力吗？",a="它天生就充满了石爪高地的原始生命力，但需要巨魔巫毒和特定的试剂才能将其扭曲为致命的毒药。",al={"石爪苔液有魔力吗","石爪苔液的属性"}}},fx={b24da591={q="什么是石爪苔液？",a="石爪苔液是一种黏稠的天然树脂，采自石爪山脉中游荡的树液兽，尤其是暗色湖和石爪峰附近的树液兽。它质地浓稠，蕴含着原始的自然精华，是调制药剂和巫毒酿剂的理想材料，能借助当地荒野的奇特魔力。",al={"什么是石爪苔液","石爪苔液物品","关于石爪苔液"}},["7615d27b"]={q="石爪苔液来自哪里？",a="这种琥珀色的树液直接采自石爪山脉森林和湖岸间游荡的活体树液兽。它并非由凡人匠人制造或蒸馏而成，而是由这些古怪的原始植物生物自然分泌的。",al={"石爪苔液的来源","哪里能获得树液"}}},fp="14,161,16.265.1,36.94.0,47.141.1,43.96.0,30.127.0"}
P.entries["item:stormpike-banner"] = {n="雷矛军旗",s="雷矛军旗是一面藏在奥特兰克山谷中险恶的冰翼洞穴深处的军旗。联盟新兵必须勇敢地面对野蛮的鹰身人，将其找回作为入门试炼，以证明他们有资格佩戴雷矛的徽记。",h="雷矛军旗是一面藏在奥特兰克山谷中险恶的冰翼洞穴深处的军旗。联盟新兵必须勇敢地面对野蛮的鹰身人，将其找回作为入门试炼，以证明他们有资格佩戴雷矛的徽记。",kw={"奥特兰克山谷","丹巴达尔","哈格丁","冰翼洞穴","徽记","试炼场","雷矛军旗"},ang={["faction:Alliance"]="找回军旗标志着你正式加入了雷矛卫队，使你有权携带他们的战斗徽记对抗霜狼氏族。",["race:Dwarf"]="这面军旗代表了铁炉堡的主权要求，以及雷矛氏族在整个山谷中发掘其过去遗物的神圣使命。"},sec={{t="入门仪式",b="为了正式加入奥特兰克山谷的雷矛远征军，准新兵们必须在与霜狼氏族的兽人交战前证明自己的勇气。哈格丁中尉会将刚抵达的联盟士兵派往位于丹巴达尔西南方的冰翼洞穴。雷矛军旗被插在这个冰冷的地下巢穴深处，作为一块试金石：任何有胆量面对当地鹰身人、夺取军旗并活着带回来的人，都能获得雷矛卫队新兵的军衔和徽记。"}},faq={{q="雷矛军旗在哪里？",a="军旗被插在奥特兰克山谷内丹巴达尔西南方的一个冰封洞穴系统——冰翼洞穴的深处。",al={"军旗位置","雷矛军旗在哪里","如何找到军旗"}},{q="为什么新兵必须找回军旗？",a="哈格丁中尉要求所有联盟新兵在加入前线战斗之前展示他们的勇气。从危险且布满鹰身人的洞穴中带回军旗，将使新兵获得最初的雷矛徽记。",al={"试炼场考验","为什么要获取军旗","哈格丁任务"}},{q="洞穴里有什么威胁在守护着军旗？",a="冰翼洞穴由凶残的当地鹰身人严密防守，她们会猛烈攻击任何寻找军旗的入侵者。",al={"军旗附近的怪物","冰翼洞穴敌人"}},{q="找到军旗后我该交给谁？",a="将找回的军旗交给哈格丁中尉，他是驻扎在奥特兰克山脉入口处的联盟军官。",al={"交付军旗","军旗上交"}}},fx={["27f01085"]={q="什么是雷矛军旗？",a="雷矛军旗是代表雷矛卫队的军旗。雷矛卫队是一支正在奥特兰克山谷征战的矮人远征军。军旗插在丹巴达尔西南方危机四伏、遍布 harpy 的冰翼洞穴深处，作为考验的标记。新兵必须深入冰封的洞穴，勇敢面对潜伏其中的凶兽，并取回军旗，以证明自己的勇气和佩戴雷矛徽记的资格。",al={"什么是雷矛军旗","雷矛军旗的背景","关于雷矛军旗"}}},fp="16,160,19.299.0,38.96.0,44.169.0,46.84.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="卡尔·雷矛的订单",s="“卡尔·雷矛的订单”是巡山人卡尔·雷矛从洛克莫丹的山区发往暴风城的一份书面委托。这封信请求铸甲大师弗伦·长须打造一面拥有无可比拟的矮人品质的定制盾牌。",h="“卡尔·雷矛的订单”是巡山人卡尔·雷矛从洛克莫丹的山区发往暴风城的一份书面委托。这封信请求铸甲大师弗伦·长须打造一面拥有无可比拟的矮人品质的定制盾牌。",kw={"铁匠","丹莫罗","dwarven district","弗伦·长须","订单","盾牌","雷矛","暴风城"},ang={["profession:Blacksmithing"]="这份请求是铸甲大师声誉的证明，表明了优秀的矮人锻造手艺能够吸引整个王国的顾客。",["race:Dwarf"]="对于矮人来说，携带这份请求维护了守护Khaz Modan的巡山人与居住在人类城市中的工匠之间的氏族纽带与技艺传承。"},sec={{t="一份来自北方的委托",b="当驻扎在遥远北方的洛克莫丹时，巡山人卡尔·雷矛需要一面坚固的新盾牌来抵御矮人边境的危险。他没有信任普通的铁匠，而是坚持委托弗伦·长须，因为他极度推崇这位铸甲师的传奇手艺。由于弗伦现在居住在遥远的南方，身处暴风城的矮人区，与人类生活在一起——巡山人雷矛推测，他定是被重金诱惑而离开了铁炉堡——因此，这位巡山人只能依靠往来的冒险者将他的正式请求送往各个王国。"},{t="雷矛家族",b="将这封信送到人头攒动的暴风城矮人区，就等于是将订单直接交到了弗伦·长须那双能工巧匠的手中。作为一个在整个Khaz Modan都以尚武精神和巨额财富而闻名的骄傲矮人氏族，雷矛家族的委托自然分量十足。弗伦很高兴能收到来自北方故乡的消息和生意，他同意完成这份订单，并着手开始锻造这位巡山人的盾牌。"}},faq={{q="什么是“卡尔·雷矛的订单”？",a="这是由巡山人卡尔·雷矛从洛克莫丹寄出的一份书面订单，请求铸甲大师弗伦·长须为他打造一面高质量的盾牌。",al={"这封信是什么","雷矛订单物品","卡尔·雷矛的订单"}},{q="这封信是谁写的？",a="它是由巡山人卡尔·雷矛所写，他是一位防守洛克莫丹山口的矮人哨兵，对弗伦·长须的锻造手艺深感钦佩。",al={"谁寄出了卡尔·雷矛的订单","谁写的","巡山人卡尔·雷矛"}},{q="这封信需要送到哪里？",a="信的收件人是弗伦·长须，他在暴风城的矮人区里经营着自己的铁匠铺。",al={"我该把卡尔·雷矛的订单带去哪","谁会收到这封信","运送卡尔·雷矛的订单"}},{q="为什么雷矛要雇佣一个远在暴风城的铁匠？",a="巡山人卡尔·雷矛认为弗伦的技术无人能及，拒绝接受任何其他护甲商，即使弗伦选择了离开铁炉堡，到南方的人类社会去经营他的生意。",al={"为什么是弗伦","为什么不在铁炉堡锻造","为什么寄往暴风城"}}},fp="19,100,21.422.0,18.312.0,28.87.0,22.131.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="暴风城护甲标记",s="暴风城护甲标记是颁发给协助本王国的冒险者的官方军事征用凭证。它可以在受权工匠处进行兑换，例如东谷伐木场的萨拉·迪博雷恩，以换取新制作的装备。",h="暴风城护甲标记是颁发给协助本王国的冒险者的官方军事征用凭证。它可以在受权工匠处进行兑换，例如东谷伐木场的萨拉·迪博雷恩，以换取新制作的装备。",kw={"护甲标记","布甲和皮甲","东谷伐木场","艾尔文森林","征用","萨拉·迪博雷恩","暴风城护甲标记"},ang={["faction:Alliance"]="该标记代表了将东谷伐木场这样的边境定居点与暴风城军事指挥部直接联系起来的后勤纽带。"},sec={{t="军事征用",b="维护艾尔文森林各地的法律与秩序使本王国的资源捉襟见肘。指挥官们有时会颁发一种称为护甲标记的官方凭证，而不是直接从军事哨所分发标准装备。这些征用凭条证明持有人已为暴风城立下英勇功勋，并授权当地受雇工匠为其提供量身定制的护甲。"},{t="东谷补给",b="这些标记的一个主要去处是位于艾尔文东部边境的东谷伐木场。在那里，像萨拉·迪博雷恩这样的工匠受暴风城军队委托，将当地的材料制成防护性的布甲和皮甲。出示标记可以为新兵提供定制的防御装备，以帮助他们保卫周边的林地。"}},faq={{q="暴风城护甲标记有什么用？",a="它作为颁发给协助暴风城卫兵的冒险者的官方军事凭证。该代币证明了你的贡献，并允许你从一名军队受雇工匠那里领取一件防护护甲。",al={"什么是护甲标记","标记用途","暴风城标记使用"}},{q="谁接受这个标记？",a="萨拉·迪博雷恩在东谷伐木场接受该标记，那里位于艾尔文森林穿过河流的东侧。她受雇于暴风城军队，负责提供定制的布甲和皮甲装备。",al={"谁接受标记","在哪里上交标记","萨拉·迪博雷恩标记"}},{q="为什么暴风城使用标记而不是直接分发护甲？",a="偏远的哨所通常缺乏在现场为新兵装备所需的存储空间或锻造与裁缝设施。通过颁发征用凭证，前线指挥官将装备工作委派给了像萨拉·迪博雷恩这样拥有专用工坊的当地工匠。",al={"为什么用凭证代替护甲","为什么要有军队标记","艾尔文军事凭证"}},{q="这种标记提供什么样的装备？",a="持有人凭此凭证可以选择由受雇军队供应商按订单制作的新款布甲或皮甲部件。",al={"我能获得什么护甲","标记奖励","布甲还是皮甲"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="斯托曼的回信",s="《斯托曼的回信》是一份从哨兵岭送到湖畔镇的公文。格里安·斯托曼在信中语气沉重地告知所罗门镇长，陷入苦战的人民民兵无法抽调哪怕一名士兵去保卫赤脊山。",h="《斯托曼的回信》是一份从哨兵岭送到湖畔镇的公文。格里安·斯托曼在信中语气沉重地告知所罗门镇长，陷入苦战的人民民兵无法抽调哪怕一名士兵去保卫赤脊山。",kw={"格里安","湖畔镇","信件","所罗门镇长","前往西部荒野的信使","人民民兵","赤脊山","所罗门","斯托曼","西部荒野"},ang={["faction:Alliance"]="携带这封信揭示了麻痹联盟核心的政治腐败：偏远定居点必须互相哀求援助，而首都却扣留着自己的部队。",["race:Human"]="对于人类守卫者来说，这份公文是一个严峻的提醒：像西部荒野和赤脊山这样的乡村腹地，在没有暴风城皇家卫队的情况下，正面临着同样的绝望生存斗争。"},sec={{t="被拒绝的请求",b="面对黑石兽人和豺狼人无休止的压力，湖畔镇的所罗门镇长向哨兵岭求援，希望西部荒野的当地武装能派来增援。格里安·斯托曼的书面回复带来了一个苦涩的消息。斯托曼在对湖畔镇的损失表示哀悼的同时，解释说西部荒野也深陷自己的战争泥潭。正是因为王室撤走了驻军，只留下农民和志愿者独自对抗迪菲亚潜行者，人民民兵才在绝望中应运而生。斯托曼解释说，他自己的部队已是伤亡惨重、捉襟见肘，无法抽调人力去解救另一个被遗弃的边境地区。"},{t="王国的忽视",b="这封通信凸显了25 ADP年人类南部领土共同的悲剧。赤脊山和西部荒野都发现自己被暴风城的王室法庭彻底遗弃了。在瓦里安·乌瑞恩国王依然下落不明，王国的常备军神秘地远离省界的情况下，偏远城镇只能自行组建志愿者守卫队，否则就只能灭亡。当所罗门收到那封盖有火漆的回复时，他意识到这两个城镇谁也救不了谁；整个王国都在瓦解，而首都却保持着沉默。"}},faq={{q="斯托曼的回信中写了什么？",a="格里安·斯托曼解释说，西部荒野正深陷与迪菲亚潜行者的残酷战争中，而且和赤脊山一样，被暴风城的军队所抛弃。他表达了对牺牲的守卫者的哀悼，但坚决拒绝了所罗门镇长的军事增援请求。",al={"信里写了什么","斯托曼信件内容","斯托曼的回信内容"}},{q="为什么所罗门一开始要向西部荒野求助？",a="湖畔镇正遭受豺狼人和黑石兽人的猛烈攻击，他向暴风城的马库斯·乔纳森将军发出的请求至今未带来任何援军。在缺乏官方支持的情况下，所罗门镇长越过艾尔文森林向人民民兵求助，希望能从同为边境的守卫者那里获得援军。",al={"为什么要向西部荒野求助","所罗门向斯托曼求助","为什么湖畔镇请求民兵支援"}},{q="为什么人民民兵无法抽调任何部队？",a="人民民兵是一支志愿者军队，勉强在哨兵岭及周边平原抵抗着迪菲亚潜行者。随着伤亡人数与日俱增，且缺乏正规军支持，如果派战士去湖畔镇，西部荒野将彻底失去防御。",al={"为什么民兵不提供帮助","西部荒野能帮助赤脊山吗","为什么拒绝所罗门"}},{q="为什么暴风城军队不保护这些城镇？",a="这两个城镇里没有人知道。斯托曼只写道，暴风城撤走了军队，使西部荒野处于毫无防御的状态。所罗门镇长不禁纳闷，究竟是什么行动如此重要，以至于要将暴风城的军队从人民身边调走。这两个乡村地区只能靠当地志愿者自生自灭。",al={"暴风城军队在哪里","为什么暴风城不提供帮助","暴风城的抛弃"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="怪味粉末",s="怪味粉末是在调查洛克莫丹周围可疑的破坏活动时发现的一种神秘残留物。人们担心这是一种不稳定的爆破剂，促使总工程师欣德维尔派出一名紧急信使前往北方，寻找一位爆破专家。",h="怪味粉末是在调查洛克莫丹周围可疑的破坏活动时发现的一种神秘残留物。人们担心这是一种不稳定的爆破剂，促使总工程师欣德维尔派出一名紧急信使前往北方，寻找一位爆破专家。",kw={"黑暗的威胁正在逼近","阿什兰·暗石","丹莫德","欣德维尔","洛克莫丹","怪味粉末","萨多尔大桥"},ang={["profession:Engineering"]="工程师们会认出那些硫磺味、不稳定的爆破混合物的气味，这些气味与联盟采矿前哨站使用的标准配方不符。",["race:Dwarf"]="对于矮人来说，保护洛克莫丹的石构建筑和水库至关重要，因此任何敌方爆炸物的迹象对该族群来说都是一场迫在眉睫的危机。"},sec={{t="一次易燃易爆的发现",b="这种奇怪的粉末是在威胁洛克莫丹基础设施的破坏迹象中发现的，它立刻引起了总工程师欣德维尔的警觉。其刺鼻的气味和细腻的质地表明这是一种精心研制的爆破化合物，而非标准的采矿爆破粉。由于不确定该混合物的化学性质或来源，欣德维尔不敢亲自处理它，因为他知道哪怕是一点点火星都可能引发灾难。"},{t="北行之路",b="由于矮人工程师对不稳定的试剂从不掉以轻心，欣德维尔将粉末样本通过奥加兹大门送往湿地。在那里，驻扎在萨多尔大桥附近丹莫德的资深爆破专家阿什兰·暗石受命对这些颗粒进行检查，以确定破坏者正在准备何种灾难性的爆炸。"}},faq={{q="什么是怪味粉末？",a="这是在洛克莫丹调查当地破坏活动时回收的一种可疑化学残留物。其刺鼻的恶臭和成分使矮人工程师怀疑它是一种爆炸剂。",al={"怪味粉末是什么","这个粉末是什么","洛克莫丹粉末"}},{q="为什么总工程师欣德维尔要对它进行检查？",a="欣德维尔怀疑这种粉末是一种特殊的爆炸物。为了了解威胁洛克莫丹的阴谋规模和危险程度，他需要一位精通重型爆破的专业人士进行分析。",al={"为什么要检查粉末","欣德维尔的粉末","谁需要这个粉末"}},{q="谁能鉴定这种粉末？",a="总工程师欣德维尔指示旅行者将样本带给阿什兰·暗石，这是一位驻扎在遥远北方萨多尔大桥附近丹莫德军营的爆破专家。",al={"谁来鉴定粉末","我该把粉末带到哪里","粉末专家"}},{q="为什么运输这种粉末很危险？",a="除了未知爆破剂固有的挥发性外，携带该样本还需要冒险穿越奥加兹大门，踏上湿地沼泽般危险的道路。",al={"粉末危险吗","为什么危险"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="有奇怪标记的箱子",s="有奇怪标记的箱子是黑海岸沿岸死海龟身上挽具里发现的一件货物。其神秘的外表刻有蛇形纳迦的符文脚本，这为暗夜精灵学者提供了证据，证明这些海洋生物并非意外搁浅。",h="有奇怪标记的箱子是黑海岸沿岸死海龟身上挽具里发现的一件货物。其神秘的外表刻有蛇形纳迦的符文脚本，这为暗夜精灵学者提供了证据，证明这些海洋生物并非意外搁浅。",kw={"奥伯丁","马车","黑海岸","灰雾鱼人","温尼斯·布莱葛","纳迦","海龟","有奇怪标记的箱子"},ang={["class:Priest"]="从岸边回收文物有助于奥伯丁Temple of the Moon的学者们保护海岸免受海洋腐蚀的侵害。",["race:NightElf"]="在黑海岸发现绑在当地海龟身上的纳迦补给箱，警告卡多雷，他们古老且变异的亲族正在有系统地从无尽之海向岸上推进。"},sec={{t="深海战利品",b="当几只巨型海龟和海洋生物在黑海岸雾气缭绕的海滩上搁浅时，另一些生物则讲述了一个更加令人不安的故事。散落的尸体上带有破碎的骑乘挽具残骸，还有直接绑在它们壳上的废弃车厢。在这些扭曲的装置废墟中，存放着密封的容器，上面覆盖着陌生而蜿蜒的符文。拾荒的灰雾鱼人经常在空洞的肋骨和破碎的马车中定居，啃食尸体并守卫着留下的任何残留物。"},{t="纳迦扩张的证据",b="当这些箱子被带到奥伯丁，交给代表Temple of the Moon的研究员温尼斯·布莱葛时，上面的标记揭示了它们真正的起源。这些脚本和捆绑的马车属于纳迦，纳迦利用巨型海龟作为驮兽，将后勤物资和战争装备运送到陆地上。这些补给箱的发现证实了纳迦正在北海岸蓄意行动，并且可能正在将坐骑驱赶向南，前往灰谷，这促使奥伯丁的祭司们将这些文物直接运往达纳苏斯进行进一步研究。"}},faq={{q="在哪里可以找到有奇怪标记的箱子？",a="这种箱子是从黑海岸沿岸搁浅海龟尸体背壳上捆绑的废弃马车中回收的。这些尸体周围通常有以腐肉为食的灰雾鱼人驻守并进行防御。",al={"哪里可以找到有奇怪标记的箱子","箱子位置","海龟马车箱子"}},{q="谁制造了有奇怪标记的箱子？",a="该箱子及其铭文是由纳迦制造的。他们将货运马车固定在活的海龟背上，以便将补给、武器和装备从深海运送到卡利姆多的海岸上。",al={"谁制造了箱子","箱子上的标记","箱子符文","标记是什么"}},{q="谁在奥伯丁需要这个箱子？",a="温尼斯·布莱葛，一位代表Temple of the Moon在奥伯丁工作的研究员，收集该箱子是为了分析奇怪的搁浅现象，并了解日益严重的纳迦威胁。",al={"该交给谁","箱子交付","谁需要这个箱子"}},{q="为什么海龟要携带这些箱子？",a="纳迦驯化或奴役了巨型海龟作为驮兽，将挽具和马车绑在它们的背上，用于战斗并将物资运送到陆地。温尼斯怀疑其中一只海龟在前往更南边，或许是前往灰谷的途中被杀死了。",al={"为什么海龟背着箱子","海龟马车","为什么要捆绑海龟"}},{q="把箱子交给温尼斯后会怎样？",a="温尼斯·布莱葛将箱子和其余的海岸调查结果上报给达纳苏斯的Temple of the Moon，以便暗夜精灵的领导层研究纳迦入侵的程度。",al={"箱子去哪儿了","箱子被送到达纳苏斯"}}},fp="20,166,20.333.0,26.406.1,40.167.0,34.173.0,32.145.0,46.234.0,52.166.0"}
P.entries["item:strigid-owl-feather"] = {n="巨翼枭的羽毛",s="猫头鹰羽毛采集自泰达希尔枝叶间筑巢的野生横纹猫头鹰。虽然它们只是森林里的自然羽毛，但却受到那些为秘密交易搜寻原材料的可疑人物的觊觎。",h="猫头鹰羽毛采集自泰达希尔枝叶间筑巢的野生横纹猫头鹰。虽然它们只是森林里的自然羽毛，但却受到那些为秘密交易搜寻原材料的可疑人物的觊觎。",kw={"多兰纳尔","试剂","横纹猫头鹰","巨翼枭的羽毛","尖叫猫头鹰","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="德鲁伊非常敬重泰达希尔的鸟类猎手，因此看到它们的羽毛在虚假的借口下被收集作为可疑试剂，令人感到不安。",["race:NightElf"]="泰达希尔的猫头鹰被认为是艾露恩的生物，因此像赛恩·腐蹄这样的残留萨特对它们的利用，是对这片神圣森林的侮辱。"},sec={{t="森林羽毛与黑暗交易",b="泰达希尔的树冠是横纹猫头鹰和尖叫猫头鹰的家园，这些原生猛禽在整个Crown of the Earth（大地之冠）捕猎。尽管它们的绒毛和羽毛是林地中常见的遗留物，但偶尔也会引起那些寻找有机试剂的从业者的注意。在多兰纳尔外，叛变的萨特赛恩·腐蹄利用从幽影谷出发前往该地的缺乏经验的旅行者，欺骗他们去收集横纹猫头鹰羽毛，连同蛛丝和夜刃豹牙齿，用于他自己的阴暗勾当。"}},faq={{q="我在哪里可以找到横纹猫头鹰羽毛？",a="这些羽毛收集自多兰纳尔周边以及整个泰达希尔林地中栖息的横纹猫头鹰和尖叫猫头鹰。",al={"羽毛位置","横纹猫头鹰羽毛哪里掉落","猫头鹰羽毛刷怪点"}},{q="谁需要横纹猫头鹰羽毛？",a="一名潜伏在通往多兰纳尔小径上的萨特，名叫赛恩·腐蹄，他诱骗天真的冒险者去获取这些羽毛，同时还要收集蛛丝和夜刃豹牙齿。",al={"谁需要猫头鹰羽毛","猫头鹰羽毛上交","赛恩猫头鹰羽毛"}},{q="赛恩·腐蹄把这些羽毛用来做什么？",a="赛恩声称这是他在森林中进行秘密生意所需的试剂，尽管他主要是以欺骗毫无戒心的招募者来替他做脏活为乐。",al={"为什么赛恩想要羽毛","赛恩试剂用途"}}},fp="19,121,32.314.1,38.133.0,31.125.0,45.158.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="结实的龙喉胫骨",s="坚固的龙喉胫骨是从湿地叛变的龙喉兽人身上搜集到的耐用骨质战利品。幽暗城的护甲制造师维罗拉·奈特雷需要这些材料，它们可作为定制战士护甲的加固支柱。",h="坚固的龙喉胫骨是从湿地叛变的龙喉兽人身上搜集到的耐用骨质战利品。幽暗城的护甲制造师维罗拉·奈特雷需要这些材料，它们可作为定制战士护甲的加固支柱。",kw={"怒牙营地","龙喉胫骨","护腿","结实的龙喉胫骨","幽暗城","维罗拉·奈特雷","湿地"},ang={["class:Warrior"]="通过徒手获取和测试这些致密的兽人骨骼，不仅能证明战士的身体力量，还能为定制护甲搜集框架零件。",["race:Undead"]="维罗拉·奈特雷代表了典型的被遗忘者实用主义，将敌人的骨头重新利用，制成供黑暗女王拥护者使用的功能性装备。"},sec={{t="骨架之骨",b="在为前线战士锻造粗犷的护腿时，铁匠需要能够承受严酷考验的原始构件。在幽暗城，维罗拉·奈特雷非常看重盘踞在湿地中部怒牙营地的叛变龙喉兽人的骨骼密度。龙喉兽人以其厚实坚固的骨架而闻名，这使得他们的小腿骨非常适合作为结构支撑。然而，并非所有搜集到的骨头都能承受压力；战士必须徒手测试每一块骨头，并丢弃那些在压力下折断的样本。"}},faq={{q="为什么这些胫骨比普通的胫骨更坚固？",a="龙喉兽人天生骨架粗壮，但细微的骨折或脆弱的骨质会使许多样本无法用于铸造护甲。为了确认骨头是否坚固，战士需要徒手弯折原始骨头；只有那些能够承受折力而不碎裂的才被认为足够强壮，可以作为护腿的骨架。",al={"为什么需要坚固的胫骨","龙喉兽人骨骼强度","测试胫骨"}},{q="谁需要坚固的龙喉胫骨？",a="位于幽暗城的护甲商维罗拉·奈特雷正在寻找这些材料。她在为有前途的部落战士制造粗犷护腿时，会将其用作核心框架支柱。",al={"谁需要胫骨","维罗拉·奈特雷 骨头","上交龙喉胫骨"}},{q="这些骨头是在哪里搜集的？",a="它们取自阿拉希高地以南的湿地中占领该地区的叛变龙喉兽人，特别是萨多尔大桥西南方山丘中的怒牙营地。",al={"哪里可以找到龙喉胫骨","龙喉胫骨位置","怒牙营地骨头"}},{q="为什么维罗拉·奈特雷使用兽人骨头制作护甲？",a="被遗忘者的手艺经常将骨骼、筋腱和金属融合在一起，制成既恐怖又极其耐用的战争装备。龙喉氏族依然敌视萨尔的部落，这使得他们的遗骸成为了被遗忘者铁匠寻找坚韧、耐用制造材料的绝佳来源。",al={"为什么使用兽人骨头","被遗忘者骨质护甲","维罗拉骨质制造"}}},fp="25,165,19.301.0,58.176.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="苏利·巴鲁的信",s="苏利·巴鲁的信是一封从萨多尔大桥下沉没的矮人战士遗骸上找到的被水浸透、饱含深情的信件。这封信寄给他在铁炉堡的妻子萨拉，它代表了卡兹莫丹宏大冲突之下那段静谧却个人的悲剧。",h="苏利·巴鲁的信是一封从萨多尔大桥下沉没的矮人战士遗骸上找到的被水浸透、饱含深情的信件。这封信寄给他在铁炉堡的妻子萨拉，它代表了卡兹莫丹宏大冲突之下那段静谧却个人的悲剧。",kw={"阿拉希高地","铁炉堡","信","萨拉·巴鲁","苏利·巴鲁","萨多尔大桥","被水浸透的信封","湿地"},ang={["faction:Alliance"]="递交这封信提供了一个庄重而富有同情心的时刻，确保了一位阵亡战士最后的思念能够送达给他的遗孀，而不是被遗忘在桥下。",["race:Dwarf"]="对于矮人来说，这封信代表了普通的登山者和士兵为了守护卡兹莫丹的高架桥和山口所做出的令人心碎的牺牲。"},sec={{t="波涛下的最后告别",b="在连接湿地与阿拉希高地的萨多尔大桥那巨大的石柱之下，躺着一具被急流深深困住的矮人骸骨。他手中紧紧攥着一个脆弱且被水浸透的信封，里面装着这封信。这封信写于他生命最后的日子或小时里，极其用心，开篇便是令人心酸的“亲爱的萨拉……”。尽管羊皮纸因长时间浸泡而受损，但墨迹依然留存着一位未能回到铁炉堡的矮人守卫那永恒的爱。"},{t="送往铁炉堡",b="将这封信带给铁炉堡的萨拉·巴鲁会带来一种沉重而毁灭性的结局。萨拉居住在矮人主城中，承受着许多亲人奔赴战场的人们所共有的那种痛苦的未知。读到丈夫苏利最后的遗言，证实了她最坏的恐惧——他死在了离家遥远的地方，冰冷的北侧渡口水流之下——但这也跨越死亡保留了他的深情。"}},faq={{q="苏利·巴鲁的信在哪里可以找到？",a="这封信是从萨多尔大桥下方水底一具被淹没的矮人骸骨手中找到的，那个位置被水浸透，大桥隔开了湿地与阿拉希高地。",al={"信件位置","苏利的信在哪里","如何找到苏利·巴鲁的信"}},{q="苏利·巴鲁是谁？",a="苏利·巴鲁是一名矮人战士，他在保卫重要北侧渡口期间在萨多尔大桥附近丧生，遗体被困在河道水流之下。",al={"苏利·巴鲁是谁","苏利·巴鲁背景故事","苏利发生了什么"}},{q="这封信是寄给谁的？",a="这封信是寄给萨拉·巴鲁夫人的，她是苏利悲痛欲绝的妻子，居住在伟大的矮人山中城市铁炉堡。",al={"谁会收到这封信","萨拉·巴鲁是谁","苏利的信去哪交"}},{q="把信交给萨拉·巴鲁会发生什么？",a="收到信后，萨拉·巴鲁得知丈夫死在冰冷的水下，悲痛万分，但她很珍惜能读到他充满爱意写下的最后遗言的机会。",al={"萨拉·巴鲁的反应","提交信件","苏利的信任务完成"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sunscorched-shell"] = {n="晒焦的蛋壳",s="晒焦的蛋壳是采集自千针石林风巢栖木下的双足飞龙蛋的坚硬残余物。经过严酷的沙漠烈日烘烤，它们变得极为坚硬，被熟练的护甲制造者所珍视，可以将其制成一种用于锁甲的保护性漆料。",h="晒焦的蛋壳是采集自千针石林风巢栖木下的双足飞龙蛋的坚硬残余物。经过严酷的沙漠烈日烘烤，它们变得极为坚硬，被熟练的护甲制造者所珍视，可以将其制成一种用于锁甲的保护性漆料。",kw={"达纳苏斯","弗伦·长须","风巢","锁甲","马西尔","晒焦的蛋壳","千针石林","双足飞龙"},ang={["class:Warrior"]="寻求定制锁甲保护的战士们协助马西尔收集这些耐用的蛋壳，以制作加固后的护甲。",["profession:Blacksmithing"]="这些蛋壳展示了聪明的铁匠如何将目光投向普通矿石之外，将天然的矿物涂层转化为锁甲的保护性漆料。"},sec={{t="沙漠之卵",b="风巢的双足飞龙栖息在卡利姆多南部的平顶山针岩之上，它们产下的蛋经受着无情的沙漠烈日和灼热狂风的考验。被丢弃的蛋壳碎片堆积在栖木之下，在干旱气候的烘烤下变得极其坚硬。虽然对于漫不经心的漫游者来说，它们似乎只是脆弱的废物，但这些被太阳灼烧过的残余物拥有一种天然的结构韧性，这使得它们成为专业工匠眼中极具吸引力的试剂。"},{t="工匠的漆料",b="在达纳苏斯，护甲商马西尔正在研究由他的同行，矮人铁匠弗伦·长须所开创的锻造方法。马西尔对弗伦的发现很感兴趣，便利用这些蛋壳制造出一种能够加固锁甲的优质漆料。在经过适当的加工和涂抹后，这种富含矿物质的涂层会粘附在金属链环上，在不给穿戴者增加过多负担的同时，显著增强其韧性。"}},faq={{q="在哪里可以找到晒焦的蛋壳？",a="它们散落在千针石林西部，从峡谷底部拔地而起的平顶山高地——风巢的双足飞龙巢穴下方的地面上。",al={"晒焦的蛋壳位置","在哪里找到蛋壳","风巢蛋壳"}},{q="这些蛋壳来自什么生物？",a="它们是栖息在千针石林高原顶部的风巢双足飞龙破碎的蛋壳。",al={"什么生物产下了这些蛋","双足飞龙蛋","蛋壳来源"}},{q="为什么马西尔需要晒焦的蛋壳？",a="马西尔试图测试由弗伦·长须发现的护甲锻造技术。他将变硬的蛋壳加工成一种坚韧的漆料，用来涂抹并加固锁甲的链环。",al={"马西尔蛋壳","蛋壳的用途","护甲漆料"}},{q="弗伦·长须是谁，他参与了什么？",a="弗伦·长须是马西尔在暴风城Dwarven District的铁器加工同行。他对非传统试剂和硬化技术的实验启发了马西尔，使后者开始尝试双足飞龙蛋壳漆料的实验。",al={"弗伦的关联","弗伦·长须蛋壳"}}},fp="17,157,15.252.0,21.258.0,35.126.0,40.102.0,41.151.0,46.212.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="超级收割机6000型的设计图",s="超级收割机6000型的设计图是荆棘谷地精在石爪山脉部署的一种巨型机械伐木机的技术蓝图。这些设计图是在侏儒工程师格伦佐·扳鸣的监督下完成的，但他那些心怀不满的哥布林竞争对手对这些图纸垂涎三尺。",h="超级收割机6000型的设计图是荆棘谷地精在石爪山脉部署的一种巨型机械伐木机的技术蓝图。这些设计图是在侏儒工程师格伦佐·扳鸣的监督下完成的，但他那些心怀不满的哥布林竞争对手对这些图纸垂涎三尺。",kw={"设计图","格伦佐","斯布特瓦夫","石爪山脉","超级收割机6000型","荆棘谷地精","狂风峭壁","兹兹·菲兹克斯"},ang={["profession:Engineering"]="这些设计图体现了一种粗犷的哥布林企业力量与缜密的侏儒机械设计之间奇异的融合，其中包含的技术蓝图令普通技工感到困惑。",["race:Gnome"]="格伦佐·扳鸣的设计图证明了即使是像荆棘谷地精这样冷酷无情的哥布林财团，最终也必须依赖侏儒的独创性来建造复杂的重型机械。"},sec={{t="狂风峭壁的工业间谍活动",b="荆棘谷地精在狂风峭壁进行的无情滥砍滥伐行动依赖于一种被称为“超级收割机”的巨型机械伐木机。令传统的哥布林工程师们极度沮丧的是，公司竟指派了一名名为格伦佐的侏儒来负责超级收割机6000型的设计。这些设计图包含了该装置的技术参数，由在峭壁各处操作机械的荆棘谷地精雇员携带。当哥布林工程师兹兹·菲兹克斯被踢出该行动后，他迅速被斯布特瓦夫雇佣去窃取这些设计图。然而，解读格伦佐那密集且古怪的侏儒技术注释，其难度几乎与强行夺取设计图不相上下。"}},faq={{q="什么是超级收割机6000型？",a="这是一种专为荆棘谷地精在石爪山脉的滥砍滥伐行动而开发的巨型机械伐木设备，旨在以冷酷的工业效率砍伐并处理木材。",al={"什么是超级收割机","超级收割机设备"}},{q="谁设计了超级收割机6000型？",a="这些图纸是在侏儒工程师格伦佐·扳鸣的主持下起草的，他是被荆棘谷地精雇佣来领导他们在狂风峭壁的机械工作的，这令当地的哥布林机械师们十分恼火。",al={"谁制作了设计图","谁设计了超级收割机"}},{q="为什么兹兹·菲兹克斯想要这些设计图？",a="兹兹被荆棘谷地精解雇，随即被斯布特瓦夫雇佣。窃取超级收割机的设计图是兹兹向他的新老板证明自己价值和机械天赋的投名状。",al={"为什么兹兹想要图纸","谁想要设计图"}},{q="谁在狂风峭壁持有这些设计图？",a="这些物理设计图由在狂风峭壁各处监管机械和进行滥砍滥伐的荆棘谷地精雇员携带。",al={"设计图在哪里掉落","谁掉落设计图"}}},fp="28,277,38.564.0,30.135.0,35.217.0,43.156.0,43.116.0"}
P.entries["item:supplies-for-sven"] = {n="斯温的货物",s="斯温的货物是一捆在夜色镇打包，准备送往斯温·约根隐蔽营地的关键补给品。斯温和他的小队被暮色森林的恐怖所包围，他们依靠像卡瑞文一家这样富有同情心的镇民来维持他们对阴影的守望。",h="斯温的货物是一捆在夜色镇打包，准备送往斯温·约根隐蔽营地的关键补给品。斯温和他的小队被暮色森林的恐怖所包围，他们依靠像卡瑞文一家这样富有同情心的镇民来维持他们对阴影的守望。",kw={"营地","卡瑞文","夜色镇","暮色森林","补给品","斯温的货物","斯温·约根"},ang={["class:Paladin"]="斯温对暮色森林中黑暗的坚定反抗被虔诚之士视为圣光的真正事业，这使得这些补给品成为了对信仰兄弟的一项重要服务。",["faction:Alliance"]="由于守夜人忙于保卫夜色镇，人手捉襟见肘，联盟的旅行者通常是像斯温营地这样孤立哨所唯一可靠的信使。"},sec={{t="营地的生命线",b="带着生存装备和基本必需品穿过暮色森林绝非易事。斯温·约根和他的少数追随者在森林西北部的荒野扎营，远离夜色镇的安全区。他们的人数太过稀少，且警戒任务繁重，以至于无法抽调哪怕一名战士前往镇上。这个包裹代表了卡瑞文一家送出的生命线，确保这个孤立的营地有足够的食物、绷带和物资来坚守阵地。"}},faq={{q="是谁送来了这些物资？",a="这些物资是由夜色镇的卡瑞文一家送出的。他们意识到了斯温·约根在荒野中面临的绝望斗争，因此安排了这些补给品来支援他的营地。",al={"谁送了斯温的货物","谁打包了斯温的货物","卡瑞文一家的物资"}},{q="为什么斯温不能自己来取物资？",a="斯温的队伍人手过于短缺。由于只有少数幸存的同伴在暮色森林西北部驻守营地以抵御野兽和亡灵，他们无法抽出任何人走上通往夜色镇的危险道路。",al={"为什么斯温不自己取食物","为什么要给斯温送货","为什么要物资"}},{q="斯温的营地在哪里？",a="斯温的营地位于暮色森林的西北边缘，坐落在远离守夜人直接保护范围的山丘中。",al={"斯温·约根在哪里","斯温营地位置","在暮色森林寻找斯温"}},{q="斯温·约根是谁？",a="斯温·约根是一位边境拓荒者，也是圣光的虔诚信徒，他曾是一名在暮色森林务农的农夫。在悲剧降临到他的家园后，他在边境建立了一个武装营地，以反击困扰该地区的黑暗势力。",al={"斯温是谁","斯温·约根背景故事"}}},fx={["0c0166a3"]={q="什么是斯温的货物？",a="这些货物是为斯温·约根及其在暮色森林坚守的一小队追随者准备的补给。卡雷文家族定期筹备这类援助，让这些忠诚的十字军能继续为圣光效力，对抗黑暗森林中的恐怖之物，不必放弃他们的守望。",al={"斯温的货物是什么","斯温的货物","斯温的货物物品"}}},fp="17,169,23.310.0,24.132.0,38.196.0,29.114.0,19.227.0"}
P.entries["item:surena-s-choker"] = {n="苏伦娜的项圈",s="苏伦娜的项圈是一条附魔的血石项链，由黑暗缚灵者加科因赠予他昔日的学徒苏伦娜·卡莱登。在苏伦娜背叛加科因并逃往迪菲亚潜行者阵营后，这位术士大师派遣渴望进步的信徒前去强行收回此物。",h="苏伦娜的项圈是一条附魔的血石项链，由黑暗缚灵者加科因赠予他昔日的学徒苏伦娜·卡莱登。在苏伦娜背叛加科因并逃往迪菲亚潜行者阵营后，这位术士大师派遣渴望进步的信徒前去强行收回此物。",kw={"血石颈环","布莱克威尔南瓜田","埃兰·德鲁格摩尔","黑暗缚灵者加科因","slaughtered lamb","苏伦娜·卡莱登","苏伦娜的项圈"},ang={["class:Warlock"]="从苏伦娜·卡莱登手中找回这条项圈是人类和侏儒术士的一项基础试炼，旨在证明在追求恶魔力量的过程中，感性毫无立足之地。"},sec={{t="大师的失败投资",b="黑暗缚灵者加科因一直在暴风城Slaughtered Lamb的地下暗中活动，他曾收苏伦娜·卡莱登为徒，认为她在黑暗魔法方面极具潜力。加科因被她青春的魅力和魔法天赋所吸引，赠予她一条珍贵的血石颈环以助其修行。然而，苏伦娜放弃了训练，并与迪菲亚潜行者的盗贼埃兰·德鲁格摩尔私奔了。加科因不愿让这种强大的神器落入叛徒之手，于是派遣那些寻求虚空力量掌控权的信徒前往布莱克威尔南瓜田追踪苏伦娜，收回项圈，并以此证明真正的忠诚。"}},faq={{q="为什么黑暗缚灵者加科因想要收回苏伦娜的项圈？",a="加科因在苏伦娜还是他学徒的时候，将这条血石颈环赠予了她。当她放弃修行并与一名迪菲亚潜行者成员私奔后，加科因拒绝让叛徒保留这件珍贵的黑暗魔法神器。",al={"为什么加科因想要项圈","加科因 苏伦娜 项圈","为什么要收回项圈"}},{q="苏伦娜·卡莱登是谁？",a="苏伦娜·卡莱登是暴风城的一名术士学徒，在黑暗缚灵者加科因的教导下展现出了过人的天赋。她背弃了导师，与埃兰·德鲁格摩尔私奔，并藏匿于艾尔文森林的迪菲亚暴徒之中。",al={"苏伦娜是谁","苏伦娜·卡莱登背景故事","谁拿着项圈"}},{q="在哪里可以找到这个项圈？",a="这个项圈就在苏伦娜·卡莱登本人身上，她正躲藏在艾尔文森林东部布莱克威尔南瓜田的迪菲亚强盗之中。",al={"苏伦娜在哪里","项圈位置","苏伦娜·卡莱登在哪里"}},{q="项圈被找回后有什么用途？",a="收回项圈证明了信徒对黑暗缚灵者加科因的冷酷和忠诚。加科因从未说过他会如何处置项圈；他只是为苏伦娜那被浪费的天赋感到惋惜，并希望他在新学生身上的投资能有不同的结果。",al={"加科因如何处置项圈","项圈用途","术士为什么要找回项圈"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="猛鹫的胃",s="猛鹫的胃是从莫高雷上空翱翔的掠食鸟类身上采集的器官。它在传统民间疗法中备受追捧，是清除致命毒素的关键原料。",h="猛鹫的胃是从莫高雷上空翱翔的掠食鸟类身上采集的器官。它在传统民间疗法中备受追捧，是清除致命毒素的关键原料。",kw={"血蹄村","胃","茂尔·祈雨","马兹拉纳切","莫高雷","疗法","猛鹫"},ang={["race:Tauren"]="对于牛头人猎人和萨满祭司来说，收集这些部件是对利用莫高雷野生动物的每一部分来维持和治愈部族这一传统的致敬。"},sec={{t="一种稀有的民间药材",b="猛鹫是莫高雷平原和台地上土生土长的掠食性鸟类，以敏锐的视力和食腐习性而闻名。虽然它们的羽毛和肉对牛头人来说有日常用途，但它们的内脏——特别是胃——却受到草药师和治疗者的珍视。当这种致密的肌肉器官与平原狮的腿骨和草原狼的心脏等其他强效动物遗骸结合使用时，有助于中和动物毒液造成的咬伤，并阻止感染的系统性扩散。"},{t="治疗马兹拉纳切咬伤的良方",b="在血蹄村，药师茂尔·祈雨成为了传说中的平原陆行鸟马兹拉纳切的猎物，肩膀受了严重的毒伤。在蔓延的毒素导致的谵妄中，茂尔依靠猛鹫的胃，辅以草原狼的心脏、平原狮的腿骨和平原陆行鸟的鳞片，调配出一种能够驱除野兽致命毒液的药膏。"}},faq={{q="猛鹫的胃有什么用途？",a="它是血蹄村的茂尔·祈雨所需的一种重要药材。与其他三种动物部件结合后，可以制成一种能够清除凶猛的平原陆行鸟马兹拉纳切所造成的毒性感染的疗法。",al={"猛鹫的胃用途","为什么需要猛鹫的胃","猛鹫器官的用途"}},{q="猛鹫的胃从哪里来？",a="它们是从滑翔在莫高雷平原上的各种猛鹫身上采集的，包括普通的猛鹫、强壮的猛鹫和利爪猛鹫。",al={"哪里可以找到猛鹫的胃","什么掉落猛鹫的胃","狩猎猛鹫"}},{q="茂尔·祈雨为什么需要这种特定的部件？",a="茂尔被马兹拉纳切咬伤了，这是一只异常凶猛的平原陆行鸟，它的咬伤会产生毒液，导致高烧和噩梦。传统的牛头人医学利用强效的动物成分——包括胃——来中和在他血管中蔓延的特定毒素。",al={"茂尔的疗法","为什么是胃","马兹拉纳切的解药"}},{q="这种胃除了用于茂尔的治疗外还有其他用途吗？",a="没有。除了血蹄村茂尔·祈雨的特殊民间疗法外，猛鹫的胃没有标准的烹饪、炼金或制作用途。",al={"猛鹫的胃的其他用途","烹饪猛鹫的胃","猛鹫的胃炼金"}}},fp="13,114,22.349.0,31.337.0,33.225.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:tablet-of-verga"] = {n="维尔加石板",s="维尔加石板是一块刻有恶魔符文的奥术石碑，对于束缚黑暗实体至关重要。邪恶的火刃氏族窃取了它，并将其带到了骷髅石内的巢穴深处。找回这件文物可以帮助奥格瑞玛的黑暗修行者破译束缚虚空行者所需的仪式。",h="维尔加石板是一块刻有恶魔符文的奥术石碑，对于束缚黑暗实体至关重要。邪恶的火刃氏族窃取了它，并将其带到了骷髅石内的巢穴深处。找回这件文物可以帮助奥格瑞玛的黑暗修行者破译束缚虚空行者所需的仪式。",kw={"火刃氏族","cleft of shadow","杜隆塔尔","甘鲁尔·血眼","骷髅石","维尔加石板","虚空行者"},ang={["class:Warlock"]="对于在奥格瑞玛训练的术士来说，找回这块石板标志着向部落证明其实力的一个关键里程碑，同时也解锁了束缚防御型虚空行者仆从所需的秘密。",["faction:Horde"]="火刃氏族在距离奥格瑞玛大门如此之近的地方活动，这对萨尔建立的年轻国家构成了持续的威胁；从他们手中夺回被窃的遗物是对该邪教影响力的有力回击。"},sec={{t="失窃的遗物",b="维尔加石板上记载着召唤并令虚空生物屈服于主人意志所需的特定仪式符文。当火刃氏族成功窃取这块石板后，他们将其藏在了奥格瑞玛以东，骷髅石内的一个隐秘宝箱里。对于在大断崖阴影中秘密工作的术士来说，夺回这件遗物至关重要——不仅是为了研究上面记载的召唤虚空行者的古老符号，也是为了剥夺那些狂热的邪教徒所拥有的黑暗优势。"}},faq={{q="维尔加石板在哪里？",a="石板存放在骷髅石内的一个火刃藏宝箱中。骷髅石是一个位于杜隆塔尔，奥格瑞玛以东的洞穴群，里面布满了邪教徒。",al={"维尔加石板位置","哪里寻找维尔加石板","维尔加石板在哪里"}},{q="谁想要找回维尔加石板？",a="甘鲁尔·血眼，一位居住在奥格瑞玛下方大断崖的大术士，他委派初学者去取回这块石板，以便教授他们如何召唤更强大的仆从。",al={"谁需要维尔加石板","把维尔加石板交给谁","甘鲁尔石板"}},{q="这块石板包含什么力量？",a="这块石头上刻有完成召唤和束缚虚空行者仪式所需的古老符文，虚空行者是一种从扭曲虚空中拉出来的生物。",al={"石板有什么用","维尔加石板背景","维尔加石板符文"}},{q="火刃氏族为什么要偷它？",a="火刃氏族不知疲倦地致力于破坏部落并扩张他们自己的恶魔力量。剥夺奥格瑞玛修行者关键的仪式文本，并将这些知识据为己有，直接服务于他们的目标。",al={"为什么火刃氏族有石板","火刃氏族维尔加"}}},fp="15,114,14.381.0,37.148.0,40.163.0,35.112.0,35.191.0"}
P.entries["item:tainted-heart"] = {n="被污染的心脏",s="被污染的心脏是从泰达希尔受到腐化的植物中提取出的枯萎花朵核心。植物学家德纳兰将其交给冒险者，需要通过魔法和营养净化来去除其残留的邪恶能量。",h="被污染的心脏是从泰达希尔受到腐化的植物中提取出的枯萎花朵核心。植物学家德纳兰将其交给冒险者，需要通过魔法和营养净化来去除其残留的邪恶能量。",kw={"净化","腐化","德纳兰","奥拉密斯湖","种植槽","被污染的心脏","泰达希尔"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，致力于净化被污染的心脏，可以让他们直接深入了解威胁这棵年轻世界之树健康的蔓延腐化。",["profession:Herbalism"]="草药师和植物学家能够欣赏德纳兰在混合特制营养土壤方面的技艺，这些土壤能够从活的植物物质中提取出非自然的腐烂。"},sec={{t="腐化核心",b="泰达希尔的自然平衡正遭受一种非自然的疾病侵害，导致其原生的植物和野兽发生扭曲。在清理掉附着在枯萎生长物上的恶臭苔藓后，德纳兰拿出了这个残留的核心：被污染的心脏。虽然它已经摆脱了外层的腐烂，但黑暗仍然渗透在组织中。德纳兰试图探索特制的富含营养的土壤是否能够抵消残留的污秽，并使腐化的部分恢复生机。"},{t="德纳兰的疗法",b="当被放入德纳兰的附魔种植槽中时，这颗心脏表现出一种奇怪且持久的活力。它急切地钻进肥沃的土壤中，吸收其中的治疗养分。片刻之内，土壤便烧掉了腐化部分，净化后的心脏重新焕发生机，跳动着纯净的能量，渴望保护那些治愈它的人。"}},faq={{q="什么是被污染的心脏？",a="它是泰达希尔上发现的一种受到腐化的植物的内核。植物学家德纳兰剥去了外层的恶臭苔藓，但在净化之前，心脏本身仍然深陷于腐化之中。",al={"什么是被污染的心脏","被污染的心脏物品"}},{q="谁来净化被污染的心脏？",a="德纳兰指引冒险者将其种植在位于奥拉密斯湖的他特制的种植槽内。营养丰富的土壤会自然地净化这颗心脏，洗去其非自然的腐化。",al={"谁来净化它","如何净化被污染的心脏"}},{q="种植后会发生什么？",a="这颗心脏会主动钻进种植槽的土壤中。片刻后，它会重新破土而出，完全被净化并充满活力，准备好与治愈它的人建立羁绊。",al={"心脏会发生什么","种植后的心脏结果"}},{q="为什么心脏最初会被腐化？",a="一种奇怪的枯萎病正在世界之树泰达希尔上蔓延，腐化了整棵大树上的原生植物、树人以及野生生物。",al={"为什么被腐化","泰达希尔腐化心脏"}}},fp="13,186,16.335.0,16.285.1,26.171.0,31.179.0,33.144.1,46.137.0"}
P.entries["item:tainted-keg"] = {n="被污染的酒桶",s="被污染的酒桶是一桶被药剂师林度恩掺入了致命被遗忘者药剂的被盗矮人黑啤酒。它以慰问品的名义被送给塔伦米尔的被囚禁人类农夫，以此作为皇家药剂师协会研发中的毒药的残酷实地测试。",h="被污染的酒桶是一桶被药剂师林度恩掺入了致命被遗忘者药剂的被盗矮人黑啤酒。它以慰问品的名义被送给塔伦米尔的被囚禁人类农夫，以此作为皇家药剂师协会研发中的毒药的残酷实地测试。",kw={"药剂师林度恩","被俘的农夫","丹加洛克","苦痛药剂","掘金者黑啤酒","被污染的酒桶","塔伦米尔"},ang={["race:Human"]="用掺毒的麦芽酒屠杀被俘的农村劳工，显示了希尔斯布莱德各地生者残余所面临的痛苦且冷酷的战术。",["race:Undead"]="对于皇家药剂师协会来说，被污染的黑啤酒是在研制能够根除人类的生物武器方面的一个实际里程碑。"},sec={{t="致命佳酿",b="这桶酒原本是一桶“掘金者黑啤酒”，是从驻扎在丹加洛克的矮人火枪手那里掠夺来的。药剂师林度恩并没有喝掉它，而是用他新精炼的“苦痛药剂”污染了这种浓郁的麦芽酒。通过在普通饮料中投毒，被遗忘者制造了一种旨在避开怀疑的阴险媒介，将生者熟悉的慰藉变成了迅捷的死刑判决。"},{t="在囚犯身上进行的测试",b="几名人类农夫被关押在塔伦米尔旅店的楼上，此前高级执行官达萨利亚怀疑有一名暴风城的军事战略家隐藏在他们之中。当消息传来称那名战略家已死在别处时，这些被俘的劳工就成了弃子。达萨利亚将他们交给了林度恩，林度恩把那桶毒酒放在他们关押室的地毯上，策划了一场残忍的庆祝活动。口渴且绝望的囚犯们开怀畅饮，证明了这种药剂即时且致命的效力。"}},faq={{q="被污染的酒桶里有什么？",a="它里面装的是“掘金者黑啤酒”——一种从丹加洛克偷来的浓郁矮人麦芽酒——并混合了药剂师林度恩在塔伦米尔制造的实验性毒药“苦痛药剂”。",al={"被污染的酒桶内容物","桶里是什么毒药","木桶里有什么"}},{q="这种麦芽酒最初来自哪里？",a="作为基酒的啤酒是从占据丹加洛克的矮人山地猎人和火枪手那里夺取的，丹加洛克是一座位于希尔斯布莱德丘陵东南部的重兵把守的矮人堡垒。",al={"谁酿造的麦芽酒","黑啤酒是从哪里偷来的","掘金者黑啤酒来源"}},{q="谁喝了这桶酒？",a="一群被关押在塔伦米尔旅店楼上房间里的人类农夫喝了这桶酒，他们几乎立刻就因喝下被污染的啤酒而倒地身亡。",al={"谁喝了它","被污染的酒桶受害者","被俘的农夫"}},{q="为什么这些农夫会被囚禁？",a="高级执行官达萨利亚逮捕了他们，怀疑暴风城的联盟军事战略家隐藏在他们之中。当那名战略家被证实死于瘟疫之地后，这些被俘的农夫就被认为毫无用处，转而被交给了药剂师。",al={"为什么囚禁农夫","为什么达萨利亚要抓农夫","为什么农夫会在塔伦米尔"}}},fx={fd5e0197={q="什么是被污染的酒桶？",a="被污染的酒桶里装着被盗来的矮人掘地工烈酒，其中掺入了被遗忘者调制的致命混合物。药剂师林度恩配制了这批致命的污染酒，作为他持续进行的炼金研究中的实用试验。",al={"什么是被污染的酒桶","被污染的酒桶物品","这个酒桶是什么"}},["5c778a45"]={q="药剂师林度恩为什么要使用被污染的酒桶？",a="药剂师林度恩想让人把酒桶送去，以测试他刚刚完成的苦楚精华药剂是否有效。高级执行官达萨利亚已将抓获的人类农夫交由他处置，而向他们提供毒酒，能让皇家药剂师协会方便地亲眼观察毒素的致命效果。",al={"为什么要使用被污染的酒桶","林度恩为什么要被污染的酒桶","被污染的酒桶的用途"}}},fp="11,232,16.285.0,24.469.1,31.167.0,39.141.0,24.127.1,41.262.0"}
P.entries["item:tainted-letter"] = {n="被污染的信件",s="被污染的信件是一封隐秘送达的传唤函，上面盖有杜希拉·拉萨雷的印章，她是一位潜伏在北郡修道院边缘的术士训练师。信件指引人类黑暗艺术的求道者向她报到，以便在远离监视目光的地方接受专门的教导。",h="被污染的信件是一封隐秘送达的传唤函，上面盖有杜希拉·拉萨雷的印章，她是一位潜伏在北郡修道院边缘的术士训练师。信件指引人类黑暗艺术的求道者向她报到，以便在远离监视目光的地方接受专门的教导。",kw={"杜希拉·拉萨雷","艾尔文森林","北郡修道院","被污染的信件","扭曲虚空","术士"},ang={["class:Warlock"]="被污染的信件标志着你正式进入了暴风城王国境内的阴影技艺，确定了对虚空的掌控需要时刻保持警惕和谨慎。",["race:Human"]="人类社会普遍崇尚圣光，这使得黑暗魔法的修行者只能在北郡修道院等地点的边缘隐秘地进行他们的入会仪式和训练。"},sec={{t="一份秘密传唤",b="当牧师、圣骑士和普通士兵在北郡修道院整洁的草坪上公开训练时，邪能魔法的修行者必须以更加谨慎的方式行事。这封信被交给从附近狗头人营地返回的见习者，上面带有杜希拉·拉萨雷的个人徽记。这封信件带有黑暗诡计的细微痕迹，指示新晋术士在当地城镇卫兵和教士对他们所走的禁忌道路产生怀疑之前，在修道院附近隐秘地寻找他们的导师。"},{t="野心的代价",b="与杜希拉会面后，人们便会明白采取这种秘密措施的必要性。术士被艾尔文森林的普通民众视为极度不信任的对象，这迫使导师们徘徊在边缘地带，以避开爱打探的哨兵。杜希拉利用这封送达的信件开启了关于纪律的重要一课：奥术和虚空魔法会招致无情的腐化，要求修行者在与扭曲虚空的居民交流时，用耐心的自制力来磨练他们激增的野心。"}},faq={{q="谁寄出了被污染的信件？",a="这封信是由杜希拉·拉萨雷撰写并封印的，她是驻扎在北郡修道院大厅外的一位当地术士训练师。",al={"谁写了被污染的信件","杜希拉的信","被污染的信件的寄件人"}},{q="为什么这封信被认为是“被污染的”？",a="这封信件上带有邪能的底色，并盖有恶魔艺术修行者的徽记，散发着一种不同于普通信件的黑暗魔法气息。",al={"为什么它是被污染的","是什么使这封信被污染","被污染的印章"}},{q="为什么北郡的卫兵在监视杜希拉·拉萨雷？",a="北郡修道院的卫兵和教士不信任邪能魔法和恶魔召唤。杜希拉必须在修道院的边缘保持低调，以避免激怒那些密切监视嫌疑修行者的世俗权威。",al={"杜希拉与卫兵","为什么卫兵怀疑杜希拉","躲藏在北郡的术士"}},{q="杜希拉在阅读这封信后给出了什么建议？",a="杜希拉告诫见习者，与来自扭曲虚空的实体打交道会招致强烈的诱惑和腐化。她指示学生们要行使自制力和审慎，同时不要让谨慎熄灭他们个人的野心。",al={"杜希拉的建议","杜希拉说了什么","杜希拉的训练"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="被污染的备忘录",s="被污染的备忘录是发给在寒脊山谷开始冒险的新手侏儒术士的一张隐秘便条。它由术士训练师阿拉玛尔·格里姆撰写，敦促读者摒弃传统道路，寻求黑暗艺术所提供的真正力量。",h="被污染的备忘录是发给在寒脊山谷开始冒险的新手侏儒术士的一张隐秘便条。它由术士训练师阿拉玛尔·格里姆撰写，敦促读者摒弃传统道路，寻求黑暗艺术所提供的真正力量。",kw={"阿拉玛尔·格里姆","安威玛尔","寒脊山谷","侏儒术士","诺莫瑞根","被污染的备忘录"},ang={["class:Warlock"]="这张便条标志着你正式开始在阿拉玛尔·格里姆指导下进行术士训练，它将黑暗召唤描述为对控制力和力量的必要追求。",["race:Gnome"]="格里姆的信息利用了侏儒对于失去诺莫瑞根的怨恨，以及他们作为寄人篱下的难民在矮人领地中的处境。"},sec={{t="隐秘的召唤",b="在寒冷的矮人前哨站安威玛尔，邪能魔法的修行者既不受赞扬，也不被广泛信任。对于涉足禁忌艺术的年轻侏儒来说，被污染的备忘录是来自阿拉玛尔·格里姆的邀请。这条信息拒绝依赖圣光或世俗的兵器，转而以诺莫瑞根的沦陷为例，证明传统方法和修补匠的技艺已经辜负了他们的人民。对格里姆来说，依赖矮人的施舍是一条死胡同；如果侏儒希望保障自己的未来，就必须掌握无可置疑的力量并召唤绝对服从的仆从。"}},faq={{q="谁撰写了被污染的备忘录？",a="这份备忘录由阿拉玛尔·格里姆撰写，他是驻扎在寒脊山谷安威玛尔内部的侏儒术士训练师。",al={"被污染的备忘录作者","谁发送了被污染的备忘录","阿拉玛尔·格里姆的便条"}},{q="为什么这份备忘录被认为是“被污染的”？",a="它直接涉及禁忌的术士魔法。这个标题反映了在丹莫罗，围绕着恶魔和邪能力量的不信任感与污名，在这里，修行者们被他们的矮人主人敬而远之。",al={"为什么被污染","被污染的信件背景故事"}},{q="阿拉玛尔·格里姆是如何看待诺莫瑞根的？",a="格里姆对侏儒首都的陷落感到苦涩，他指责传统的奥术魔法和鲁莽的修补技艺导致他们的种族濒临灭绝。他认为矮人将侏儒视为二等公民，并敦促术士们寻找属于自己的绝对力量，而不是等待联盟的援助。",al={"阿拉玛尔·格里姆诺莫瑞根","阿拉玛尔·格里姆的观点"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="堕落护符",s="堕落护符是一件邪恶的恶魔饰品，由萨特Xabraxxis用来毒害Darkshore的Blackwood熊怪的心智。它被保存在萨特的个人袋中，作为一个魔法媒介，将这个部族束缚在邪能疯狂之中。",h="堕落护符是一件邪恶的恶魔饰品，由萨特Xabraxxis用来毒害Darkshore的Blackwood熊怪的心智。它被保存在萨特的个人袋中，作为一个魔法媒介，将这个部族束缚在邪能疯狂之中。",kw={"奥伯丁","blackwood","darkshore","熊怪","萨特","堕落护符","thundris windweaver","xabraxxis"},ang={["class:Druid"]="德鲁伊们视像护符这样的装置为对自然秩序的直接歪曲，将神圣的野兽扭曲成Burning Legion残余爪牙的野性棋子。",["race:NightElf"]="对于奥伯丁的Kaldorei来说，找回护符是将其世袭的熊怪盟友从恶魔堕落中解放出来并治愈这片土地的关键一步。"},sec={{t="疯狂的媒介",b="奥伯丁的暗夜精灵们一直苦于无法理解Blackwood熊怪为何会如此激进地攻击他们曾经的盟友。Thundris Windweaver发现，这个部族的堕落并非自然发生，而是由萨特精心策划的蓄意破坏。利用像这样的护符，恶魔特工将腐蚀性的魔法投射到荒野中，污染食物来源，并将宁静的森林之魂扭曲成狂暴的野兽。通过直接引导邪能魔法穿过这些装置，萨特们牢牢控制着当地部族的心智和意志。"},{t="打破束缚",b="为了引出幕后的萨特，冒险者必须使用祝福过的月井水净化熊怪的食物样本，净化营地足够长的时间以激怒其监工。击杀Xabraxxis可以打破他直接的控制，并获得他的恶魔袋，护符就在其中。将护符交给奥伯丁的Thundris Windweaver，可以让Kaldorei中和其散发的邪恶气息，并研究如何永久消除困扰森林的恶魔折磨。"}},faq={{q="什么是堕落护符？",a="这是一件由萨特Xabraxxis使用的恶魔装置，用于引导邪恶魔法并腐蚀Darkshore的Blackwood熊怪的思想和食物来源。",al={"什么是堕落护符","护符的作用","护符有什么用"}},{q="谁携带着这个护符？",a="它被保存在Xabraxxis携带的恶魔袋中，Xabraxxis是一位监管壁泉河附近北部Blackwood熊怪营地的萨特。",al={"谁掉落堕落护符","在哪里可以找到堕落护符","如何获得护符"}},{q="你如何引出护符的主人？",a="你必须收集熊怪的水果、谷物和坚果样本，将它们与月井水在净化碗中混合，并将祭品放置在河边的篝火旁。净化熊怪会激怒Xabraxxis，促使他发动攻击。",al={"如何召唤xabraxxis","如何找到xabraxxis","召唤darkshore萨特"}},{q="护符被找回后会怎样？",a="它会被交给奥伯丁的Thundris Windweaver。他会将该神器妥善保管以待销毁，并研究如何永久将熊怪从恶魔腐蚀中解放出来。",al={"我应该把护符交给谁","交付堕落护符","thundris windweaver的护符"}}},fp="22,205,20.427.0,17.356.1,35.130.0,25.124.0,46.211.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="塔隆凯的珠宝",s="塔隆凯的珠宝是一颗从泰达希尔上一件附魔德鲁伊法器中被窃走的闪光翡翠。这颗珠宝被熊怪秘法师“梦境吞噬者”费罗卡斯视为珍宝，它是修复翡翠摄梦符所必需的关键核心。",h="塔隆凯的珠宝是一颗从泰达希尔上一件附魔德鲁伊法器中被窃走的闪光翡翠。这颗珠宝被熊怪秘法师“梦境吞噬者”费罗卡斯视为珍宝，它是修复翡翠摄梦符所必需的关键核心。",kw={"多兰纳尔","翡翠摄梦符","梦境吞噬者费罗卡斯","蓟皮秘法师","星风村","塔隆凯·捷根","塔隆凯的珠宝"},ang={["class:Druid"]="这颗翡翠是一种特制的德鲁伊组件，旨在与翡翠梦境产生共鸣，因此被腐蚀的熊怪滥用它是对自然平衡的亵渎。",["race:NightElf"]="取回珠宝有助于恢复泰达希尔的秩序，因为它将神圣的工艺品从入侵的蓟皮熊怪手中夺回。"},sec={{t="被窃的核心",b="塔隆凯·捷根从班奈希尔兽穴的德鲁伊守护者Gaerolas Talvethen那里得到了翡翠摄梦符，这是一种可以从翡翠梦境中汲取能量的强大法器。当他的护身符受损时，中央那颗光芒四射的翡翠被撬了下来，并被带到了泰达希尔东部的荒野中。这颗珠宝落入了“梦境吞噬者”费罗卡斯的手中，这是一位被腐蚀的蓟皮熊怪领袖，他将这颗闪耀的宝石做成了自己的项链。虽然这颗绿色宝石在幽暗的森林中投下了一道诡异的光芒，但其真正的和谐共鸣对这只熊怪来说完全毫无用处，在被取回之前，它仅仅是作为一个战利品存在。"}},faq={{q="什么是塔隆凯的珠宝？",a="它是一颗附魔的闪光翡翠，是翡翠摄梦符的核心部件，翡翠摄梦符是由Gaerolas Talvethen送给多兰纳尔的塔隆凯·捷根的德鲁伊法器。",al={"什么是珠宝","塔隆凯的珠宝背景"}},{q="是谁偷走了塔隆凯的珠宝？",a="它是由“梦境吞噬者”费罗卡斯偷走的，他是居住在星风村北部的被腐蚀的蓟皮熊怪秘法师中的领袖。",al={"谁拥有珠宝","谁偷了它","谁拿走了塔隆凯的珠宝"}},{q="蓟皮熊怪能使用这颗珠宝的力量吗？",a="不能。虽然费罗卡斯把这颗翡翠戴在脖子上作为发光的装饰品，但塔隆凯指出，这块宝石的德鲁伊力量对这只被腐蚀的熊怪来说毫无用处。",al={"费罗卡斯能用它吗","蓟皮翡翠力量"}},{q="珠宝被取回后去了哪里？",a="宝石被送回了位于多兰纳尔上层的塔隆凯·捷根手中，他用它来完全修复和补好受损的翡翠摄梦符。",al={"珠宝的下落","修复摄梦符"}}},fp="17,163,13.592.0,26.166.0,28.119.0,49.113.0,46.137.0"}
P.entries["item:taming-rod"] = {n="驯兽棒",s="驯兽棒是训练师交给新手猎人的一种教学工具。它被注入了简单的束缚魔法，可以让学生暂时安抚并指挥当地的野生生物，从而掌握驯服野兽的基础知识。",h="驯兽棒是训练师交给新手猎人的一种教学工具。它被注入了简单的束缚魔法，可以让学生暂时安抚并指挥当地的野生生物，从而掌握驯服野兽的基础知识。",kw={"装甲蝎虫","恐鬃野猪","猎人宠物","剃刀岭","驯兽棒","taming the beast","索塔尔"},ang={["class:Hunter"]="驯兽棒是每位年轻猎人成年礼的基石，在他们拥有与野生野兽建立终身纽带的天生意志力之前，它起着辅助训练的作用。",["faction:Horde"]="在杜隆塔尔和莫高雷，像索塔尔这样的训练师使用这些木棒来测试年轻的新兵是否有能力驾驭卡利姆多严酷的野生生物。"},sec={{t="引导者的训练器具",b="新手猎人还无法立刻施展将野兽永久束缚在自己意志之下的精神力量。为了弥补这一差距，老练的训练师会发放特制的驯兽棒。在剃刀岭等地，像索塔尔这样的导师会给立志成为猎人的兽人和巨魔提供这些附魔器具，用来制服区域内的掠食者——例如恐鬃野猪和装甲蝎虫。驯兽棒会暂时安抚野兽，让驯兽师在练习发布命令和与动物伙伴并肩作战时，无需担心过早形成牢不可破的原始纽带而带来危险。"},{t="迈向精通的一步",b="驯兽棒提供的控制力转瞬即逝，通常在魔法消退前只能持续很短的时间。每根驯兽棒都调和了特定类型的野生野兽，作为通过后续考验的垫脚石。一旦新手证明了自己可以指挥各种性情的野兽——从温顺的觅食者到凶猛的毒液猎手——驯兽棒就会被交还给训练师。在展示了正确的技巧后，学生最终会学习驯服、召唤和遣散终身伙伴的天赋艺术，而无需借助法器。"}},faq={{q="驯兽棒有什么用？",a="驯兽棒是职业训练师发给年轻猎人的一种训练器具。它能暂时安抚并魅惑目标野兽，这样学生就可以练习在战斗中指挥动物。",al={"驯兽棒的作用","驯兽棒的使用","为什么我有驯兽棒"}},{q="我能保留用驯兽棒驯服的宠物吗？",a="不能。用驯兽棒驯服的生物仅为了训练目的而受到暂时的影响。一旦驯兽棒的附魔失效，或者你把驯兽棒交还给训练师，纽带就会结束。只有在完成所有考验后，你才能学会永久驯服自己的同伴。",al={"宠物是永久的吗","我能保留野猪吗","我能保留蝎虫吗"}},{q="我可以用任何驯兽棒对付任何动物吗？",a="不能。每根驯兽棒都专门为训练的特定阶段附魔，并与特定的目标生物相调和，例如恐鬃野猪或装甲蝎虫。",al={"驯兽棒对任何东西都有效吗","驯兽棒的目标"}},{q="完成训练后我可以保留驯兽棒吗？",a="不能。完成任务后，驯兽棒必须归还给你的猎人训练师。作为你在最终考验后归还它的交换，训练师会教你如何独自驯服、召唤和遣散野兽。",al={"保留驯兽棒","我可以保存木棒吗"}}},fp="10,173,28.452.0,21.407.0,30.162.0,38.190.0,39.138.0,56.172.0"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="塔拉加曼的心脏",s="塔拉加曼的心脏是从坐镇在怒焰裂谷深处的地狱卫士身上取下的可怕战利品。尼鲁·火刃要求得到这颗邪恶的器官，以此证明奥格瑞玛地下的恶魔威胁已经被清除。",h="塔拉加曼的心脏是从坐镇在怒焰裂谷深处的地狱卫士身上取下的可怕战利品。尼鲁·火刃要求得到这颗邪恶的器官，以此证明奥格瑞玛地下的恶魔威胁已经被清除。",kw={"地狱卫士","心脏","饥饿者","尼鲁·火刃","奥格瑞玛","怒焰裂谷","灼热之刃","塔拉加曼"},ang={["class:Warlock"]="与尼鲁·火刃打交道并处理收集到的恶魔残骸对于术士来说并不陌生，他们了解在暗影裂口中上演的阴影与欺骗的微妙网络。",["faction:Horde"]="净化奥格瑞玛下方的隧道可以保护这座年轻的首都免于从内部腐化，这使得这颗被切下的野兽心脏成为了部落警惕性的象征。"},sec={{t="欺诈的战利品",b="这颗从饥饿者塔拉加曼胸腔中挖出的还在冒热气的恶魔心脏，是这个蛮兽死亡的物理证明。尼鲁·火刃向萨尔和急切的冒险者们声称，塔拉加曼是潜伏在怒焰裂谷中的灼热之刃邪教徒的幕后主使。将这颗心脏交给尼鲁，表面上满足了酋长保卫奥格瑞玛免受恶魔腐蚀的要求，但将一个残暴的地狱卫士作为该邪教真正的幕后主使，却巧妙地掩盖了在城市地下运作的更深层的凡人网络。"}},faq={{q="谁需要塔拉加曼的心脏？",a="居住在奥格瑞玛暗影裂口的兽人术士尼鲁·火刃，要求冒险者将这颗心脏带给他，以此证明恶魔已被击杀。",al={"谁需要塔拉加曼的心脏","塔拉加曼的心脏上交","谁想要心脏"}},{q="我在哪里获得这颗心脏？",a="这颗心脏可以直接从位于奥格瑞玛下方怒焰裂谷中心岩浆室里的高大地狱卫士饥饿者塔拉加曼的尸体上拾取。",al={"如何获得塔拉加曼的心脏","塔拉加曼的心脏从哪掉落","塔拉加曼的心脏位置"}},{q="萨尔会看到这颗心脏吗？",a="不会。你会直接把心脏交给尼鲁·火刃，他声称会妥善处理这些恶魔残骸，并代你向萨尔酋长通报这次胜利。",al={"萨尔会得到心脏吗","把心脏交给萨尔","萨尔 塔拉加曼的心脏"}},{q="塔拉加曼真的是灼热之刃的领袖吗？",a="尼鲁·火刃指认这名地狱卫士是灼热之刃的领袖，并坚称击杀他并带回他的心脏会让萨尔感到满意。",al={"塔拉加曼是领袖吗","谁领导灼热之刃","塔拉加曼真正的头目"}}},fx={a71e3ad9={q="什么是饥饿者塔拉加曼的心脏？",a="这是饥饿者塔拉加曼被剖出的心脏。塔拉加曼是一只体型巨大的恶魔卫士，潜伏在奥格瑞玛下方怒焰裂谷的熔岩深处。冒险者将心脏从洞穴中带出，作为证据，证明被尼鲁·火刃称为灼热之刃首领的恶魔已被击败。",al={"什么是塔拉加曼的心脏","饥饿者塔拉加曼的心脏","塔拉加曼的心脏背景"}},d8388abb={q="饥饿者塔拉加曼的心脏从何而来？",a="这颗心脏是从饥饿者塔拉加曼的胸膛中剜出的。他是一只驻守在怒焰裂谷深处的巨型恶魔卫士。灼热之刃教徒在奥格瑞玛下方的地下隧道中召唤并藏匿了塔拉加曼，因此这颗心脏成了侵蚀城市地下深处的恶魔腐化的有机遗物。",al={"塔拉加曼的心脏的来历","这颗心脏从哪里来","谁制作了塔拉加曼的心脏"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="破损的手稿",s="破损的手稿由从唯一的《阴谋之书》副本上撕下的零散、被破坏的书页组成。这份残缺的文本被隐藏在卡利姆多南部的尘土深处，其中蕴含着术士们想要掌握恶魔猎犬所需的奥术秘密。",h="破损的手稿由从唯一的《阴谋之书》副本上撕下的零散、被破坏的书页组成。这份残缺的文本被隐藏在卡利姆多南部的尘土深处，其中蕴含着术士们想要掌握恶魔猎犬所需的奥术秘密。",kw={"恶魔猎犬","约拉·安尼森","克罗姆·粗臂","发霉的书籍","裂蹄堡","破损的手稿","千针石林","阴谋之书"},ang={["class:Warlock"]="取回这份手稿是术士学徒必经的重要试炼，它赋予了术士将掠食性的恶魔猎犬驯服并为己所用的知识。"},sec={{t="一本被破坏的魔典",b="《阴谋之书》曾经是一本完整且独一无二的典籍，被保存在已陨落的洛丹伦王国中。在某个时刻，一位不知名的亵渎者将这本论著的一半直接从装订处撕了下来。当幸存的书脊和书的其余部分——现在被称为发霉的书籍——被运往南方的卡兹莫丹并在海上遗失时，这些撕下的羊皮纸书页跨越了无尽之海，漂流到了卡利姆多，最终落入了裂蹄堡内加拉克半人马的手中。"},{t="收回文字",b="这份手稿被保存在裂蹄堡错综复杂的洞穴深处的一个破旧箱子里，历经了千针石林严酷干旱的狂风。尽管它脆弱且破损，但黑魔法的修行者们——无论是与铁炉堡的克罗姆·粗臂合作的联盟术士，还是协助幽暗城中约拉·安尼森的部落术士——都勇敢地面对好斗的半人马，将这些遗失的书页与发霉的书籍重新合为一体。一旦结合，这本完整的论著就包含了召唤并奴役恶魔猎犬所需的黑暗仪式。"}},faq={{q="什么是破损的手稿？",a="它是一系列撕裂的羊皮纸书页，构成了《阴谋之书》的大约一半内容，这是一本关于恶魔学识的传奇且独一无二的魔典。",al={"破损的手稿背景故事","什么是手稿","阴谋之书书页"}},{q="这些书页是怎么流落到千针石林的？",a="在这本魔典于洛丹伦被破坏后，被撕下的书页不知何故跨过了海洋，落入了加拉克半人马手中，他们将其藏在了裂蹄堡内的一个箱子里。",al={"为什么在裂蹄堡","半人马与书籍","千针石林手稿"}},{q="这份手稿有什么用？",a="术士必须将破损的手稿与浸过水的发霉的书籍重新组合，以还原完整的《阴谋之书》，从而解锁召唤恶魔猎犬的仪式。",al={"为什么需要手稿","恶魔猎犬任务书页"}},{q="是谁撕毁了原书？",a="罪魁祸首仍然下落不明。铁炉堡的克罗姆·粗臂和幽暗城的约拉·安尼森都对这种破坏行为感到痛心，他们不解究竟是谁会对一部独一无二的学术著作做出这种事。",al={"谁撕毁了书籍","谁破坏了阴谋之书"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="塔赞的背包",s="塔赞的背包是一个上锁的袋子，由巨魔Tazan携带，他在棘齿城附近与海盗勾结。它装有Shattered Hand垂涎的机密情报，这个潜行者秘密公会位于奥格瑞玛的地下。",h="塔赞的背包是一个上锁的袋子，由巨魔Tazan携带，他在棘齿城附近与海盗勾结。它装有Shattered Hand垂涎的机密情报，这个潜行者秘密公会位于奥格瑞玛的地下。",kw={"贫瘠之地","cleft of shadow","gamon","棘齿城","shattered hand","tazan","塔赞的背包","therzok"},ang={["class:Rogue"]="获得背包并从Gamon那里夺取钥匙，是部落潜行者获得Shattered Hand认可的必经之路。",["faction:Horde"]="对背包的追寻突显了奥格瑞玛内部的紧张局势，Shattered Hand寻求秘密优势，而大酋长Thrall则采取了更审慎的方针。"},sec={{t="贫瘠之地的秘密",b="在贫瘠之地那被烈日炙烤的荒原上，一个名叫Tazan的巨魔与在棘齿城附近海岸驻扎的海盗进行着非法交易。这些私底下的勾当引起了Therzok的敏锐注意，他是位于影之裂口(Cleft of Shadow)阴暗地底下的Shattered Hand的公会会长。为了在不被大酋长Thrall那谨慎的外交政策所干涉的情况下建立隐秘的力量，Shattered Hand决定除掉Tazan，夺取他背包里那些宝贵的情报。"},{t="一把复杂的锁",b="对有抱负的潜行者来说，找回背包只是试炼的一半。背包使用了复杂的锁定机制，无法在野外轻易强行打开。Tazan将钥匙交给了他的同伙Gamon，一个在奥格瑞玛的酒馆里常年醉酒的常客。有抱负的新手必须考验他们的手法，在不惊动任何人的情况下直接从Gamon的口袋里偷走钥匙，从而最终揭开Tazan的日志。"}},faq={{q="这个背包属于谁？",a="这个背包属于Tazan，一个在贫瘠之地活动，并与棘齿城附近海盗进行秘密交易的巨魔。",al={"tazan是谁","tazan的物品","背包的主人"}},{q="为什么Shattered Hand想要塔赞的背包？",a="Therzok和Shattered Hand试图扩大他们的情报网络，并从阴影中重拾尚武的荣耀。Tazan与沿海海盗的交易掌握着潜行者们想要利用的宝贵信息。",al={"therzok为什么想要这个","shattered hand的背包","为什么要偷背包"}},{q="打开背包的钥匙在哪里？",a="Tazan并没有随身携带钥匙；相反，他把它托付给了他的同伙，一个在奥格瑞玛酒馆里的醉汉Gamon。",al={"如何打开背包","tazan的钥匙","钥匙在哪里"}},{q="塔赞的背包里有什么？",a="上锁的背包里放着Tazan的日志，详细记录了他与沿海海盗的秘密贸易和勾结。",al={"背包里的东西","包里有什么","tazan的日志"}}},fp="15,142,22.319.0,14.274.1,32.89.0,49.163.0,37.85.1,31.109.1"}
P.entries["item:tear-of-the-moons"] = {n="众月之泪",s="众月之泪是一块神秘而闪耀的水晶，由矮人挖掘者在南贫瘠之地的巴尔莫丹发掘出土。尽管矮人探险队视其为珍宝，但这块水晶却蕴含着不稳定的腐蚀力量，直接导致了痴迷、放逐和流血冲突。",h="众月之泪是一块神秘而闪耀的水晶，由矮人挖掘者在南贫瘠之地的巴尔莫丹发掘出土。尽管矮人探险队视其为珍宝，但这块水晶却蕴含着不稳定的腐蚀力量，直接导致了痴迷、放逐和流血冲突。",kw={"巴尔莫丹","巴尔丹城堡","贫瘠之地","挖掘","feegly","众月之泪","穴居人","twinbraid"},ang={["faction:Horde"]="潜入巴尔丹城堡夺回遗物，是对侵入牛头人祖地的铁炉堡军事力量的一次沉重打击。",["race:Dwarf"]="Feegly的悲惨命运是对巴尔丹探险队在卡利姆多地底深处唤醒危险的严厉警告。"},sec={{t="出土遗物",b="这块水晶是在巴尔莫丹的初期发掘过程中被发现的，被誉为该发掘点首个重大胜利。它奇异的光芒吸引了矿工们，而Feegly受到的影响最为强烈。Feegly声称这件遗物赋予了他强大的力量，从而沉迷其中。探险队指挥官Twinbraid将军担心这件神器的黑暗影响，并对Feegly对待同伴时日益不稳定的行为感到担忧，于是宣布这块石头被诅咒了。Twinbraid没收了遗物，将其严密锁在巴尔丹城堡内他个人的保险箱里，并将Feegly逐出了贫瘠之地荒原。"},{t="痴迷的代价",b="被放逐的Feegly无法克制对水晶力量的渴求，便转而求助于路过的部落旅行者，试图攻破矮人堡垒并从Twinbraid的保险库中将其夺回。在拿到水晶并摩擦它时，Feegly开始发出奇怪的呼噜声。众月之泪从他手中滑落并在地上摔碎；随后他变成了一只穴居人并很快死去。"}},faq={{q="众月之泪从何而来？",a="这块水晶是由矮人勘探员和挖掘者在位于南贫瘠之地深处的巴尔莫丹考古挖掘点发掘出土的。",al={"众月之泪起源","众月之泪发现地点","众月之泪背景"}},{q="为什么要把水晶锁在巴尔丹城堡里？",a="在Feegly开始对水晶产生痴迷并与同行的矿工为敌后，Twinbraid将军认定这件神器受到了诅咒。为了保护探险队，Twinbraid将其锁入了自己的保险箱。",al={"为何被锁住","twinbraid保险箱中的众月之泪","twinbraid为何将其没收"}},{q="当Feegly拿回众月之泪后会发生什么？",a="Feegly急切地接过水晶并开始摩擦它。接下来就是他故事的结局，详情见剧透保护部分。",al={"feegly变成穴居人","feegly的结局"}},{q="众月之泪可以被挽救或修复吗？",a="这件遗物的最终命运在Feegly拿到它时便已揭晓。任务中并没有提到之后有人修复了它。",al={"可以保留众月之泪吗","破碎的众月之泪","修复众月之泪"}}},fp="17,197,17.475.0,22.353.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="蒂罗亚之泪",s="蒂罗亚之泪是一种精致、苍白的花朵，生长在暮色森林的阴影之中。由于其强大的炼金特性，它常被人搜寻，这种花静静地生长在夜色镇附近米斯曼特尔（Mistmantle）庄园那杂草丛生的土地上。",h="蒂罗亚之泪是一种精致、苍白的花朵，生长在暮色森林的阴影之中。由于其强大的炼金特性，它常被人搜寻，这种花静静地生长在夜色镇附近米斯曼特尔（Mistmantle）庄园那杂草丛生的土地上。",kw={"贵族药剂","夜色镇","mistmantle","stalvan","蒂罗亚之泪","tilloa","wishock","zardeth"},ang={["class:Warlock"]="这种看似无害的花朵受到首都地下潜伏的隐秘特工的垂涎，它是用来配制毒药以让那些多管闲事的贵族闭嘴的珍贵试剂。",["profession:Herbalism"]="蒂罗亚之泪是一种稀有的植物奇观，它之所以能生存下来，是因为暮色森林独特的枯萎微气候，而非通常的茂密田野。"},sec={{t="幽暗之中的花园",b="蒂罗亚之泪扎根于夜色镇外那片受到枯萎病侵蚀的树林中，就在斯塔文·米斯曼特尔（Stalvan Mistmantle）的庄园地界内。尽管暮色森林的土壤已经变得不再适合健康植物生长，但这种白色小花却在阴影笼罩的土地上顽强生存了下来。它稀少的生长量和隐蔽的地理位置，使其成为那些寻求在正规市场上难以寻获的稀有试剂的人们所追逐的目标。"},{t="贵族们的药剂",b="在暴风城繁华的街道之下，蒂罗亚之泪有着更为隐秘的用途。黑爪加尔德斯寻找这种花是为了酿造一种针对Wishock领主的特殊药剂。Wishock是暴风城贵族议会的一员，他威胁要对首都之下的暗影行动展开调查。将这种植物与巨石水坝下的麝鼠根混合，可以加工成一种旨在干扰并使Wishock失去能力的药剂，从而阻止官方调查的进行。"}},faq={{q="蒂罗亚之泪生长在哪里？",a="这种花发现于暮色森林的夜色镇郊外，隐藏在属于米斯曼特尔（Mistmantle）家族庄园那杂草丛生的花园中。",al={"蒂罗亚之泪位置","蒂罗亚之泪在哪里","蒂罗亚地点"}},{q="谁想要蒂罗亚之泪？",a="在暴风城下秘密活动的黑爪加尔德斯需要这种花来配制一种特殊的药剂。",al={"谁需要蒂罗亚之泪","蒂罗亚之泪任务发放者","谁想要它"}},{q="这种花有什么用途？",a="它与麝鼠根一起是炼金术的重要原料。两者结合能形成一种强效的药剂，用于使Wishock领主失去行动能力，并压制他调查首都之下黑暗交易的呼声。",al={"蒂罗亚之泪用途","蒂罗亚之泪有什么用","贵族药剂之花"}},{q="谁是Wishock领主？",a="Wishock领主是暴风城贵族议会中的一名成员，他察觉到了城下的颠覆性行动，并开始游说议会进行全面调查。",al={"wishock","谁是wishock","wishock领主"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="尖端机器人的存储器核心",s="尖端机器人的存储器核心是发条大工匠欧沃斯巴克机械助手“尖端机器人”的极化中央存储库。它从诺莫瑞根腐化深处那台故障的自动装置中被回收，其中包含着欧沃斯巴克希望能用来扭转这台机器负电子行为的关键数据。",h="尖端机器人的存储器核心是发条大工匠欧沃斯巴克机械助手“尖端机器人”的极化中央存储库。它从诺莫瑞根腐化深处那台故障的自动装置中被回收，其中包含着欧沃斯巴克希望能用来扭转这台机器负电子行为的关键数据。",kw={"大脑","诺莫瑞根","存储器核心","负电子","欧沃斯巴克","正电子","尖端机器人","tinker town"},ang={["profession:Engineering"]="工程师们可以理解正电子极化带来的离奇危险，仅仅一次电气短路就可能彻底颠覆一个自动装置的逻辑程序。",["race:Gnome"]="对侏儒而言，尖端机器人是诺莫瑞根陷落的又一悲剧性牺牲品，代表了精湛的和平时期工程学在混乱的废墟中消逝。"},sec={{t="极化的大脑",b="在迫使侏儒流亡的灾难发生前，尖端机器人曾是发条大工匠欧沃斯巴克及其发明家同僚不可或缺的助手，它装载了无数小玩意和百科全书般的数据。诺莫瑞根陷落时，一道迷途的电流击中了这个自动装置，将其正电子大脑逆转为了敌对的负电子状态。由于这种逆转而陷入疯狂，尖端机器人现在徘徊在城市受污染的大厅中，攻击视野内的一切目标。找回它的存储器核心是欧沃斯巴克分析故障并让这件心爱的作品恢复理智的唯一希望。"}},faq={{q="什么是尖端机器人的存储器核心？",a="这是由发条大工匠欧沃斯巴克制造的自动装置——尖端机器人的主要数据存储和计算中心。它保存着这台机器的知识，并记录了导致其在诺莫瑞根陷落期间行为腐化的电气故障。",al={"尖端机器人的存储器核心","尖端机器人大脑物品","什么是尖端机器人核心"}},{q="谁需要尖端机器人的存储器核心？",a="发条大工匠欧沃斯巴克正在寻找这个核心。在与流亡的侏儒同胞一起在铁炉堡的Tinker Town避难后，他请求勇敢的冒险者进入诺莫瑞根，使尖端机器人瘫痪，并将核心带回来，以便他尝试进行修理。",al={"谁需要尖端机器人的存储器核心","谁回收尖端机器人核心","我该把尖端机器人核心交给谁"}},{q="尖端机器人为什么会狂暴？",a="在诺莫瑞根陷落期间，一道迷途的电火花击中了尖端机器人的正电子大脑。这种突如其来的电涌导致该机制极化，使其变成了负电子，并彻底逆转了该自动装置的个性和协议，从乐于助人变成了暴力狂乱。",al={"为什么尖端机器人是敌对的","尖端机器人发生了什么","尖端机器人疯了"}},{q="在哪里可以获得这个核心？",a="该核心是从尖端机器人本身回收的，它被发现徘徊在丹莫罗诺莫瑞根陷落之城的上层机械走廊和入口处。",al={"在哪里获得尖端机器人的存储器核心","尖端机器人位置","如何获得尖端机器人的大脑"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="望远镜片",s="望远镜片是加兹鲁维进口的一种精密光学组件，用于完成棘齿城天文台的建造。这块易碎的玻璃在沿岸运输途中被南海海盗拦截，必须在镇子南边的营地找回它，港口的巨型望远镜才能观测天空。",h="望远镜片是加兹鲁维进口的一种精密光学组件，用于完成棘齿城天文台的建造。这块易碎的玻璃在沿岸运输途中被南海海盗拦截，必须在镇子南边的营地找回它，港口的巨型望远镜才能观测天空。",kw={"板条箱","加兹鲁维","天文台","棘齿城","南海自由海盗","被盗战利品","望远镜片"},ang={["profession:Engineering"]="对于工程师来说，这片精密镜片代表了高超的光学工艺，它是让远程观测机制在没有球面像差的情况下对焦所必需的。",["race:Gnome"]="侏儒技师可能会嘲笑地精的火箭技术，但加兹鲁维对光学天文学的专注证明了地精工程学并非仅仅关乎高爆炸药。"},sec={{t="仰望星空",b="棘齿城以无情的商业贸易港口而闻名，但其首席工程师兼监管者加兹鲁维却怀揣着更宏大的机械雄心。他的天文台高耸于港口之上，旨在容纳一架强大的望远镜，以监视海上交通和天文现象。虽然较大的镜片通过杜隆塔尔的陆路商队安全抵达，但至关重要的较小镜片却是海运的——这使得它成了在贫瘠之地海岸线外肆虐商道的南海自由海盗眼中容易得手的猎物。"},{t="海盗掠夺物",b="当自由海盗袭击运输船时，他们搬走了所有有价值的东西，并将这件精细的光学仪器装进了一个标有“易碎品——请勿跌落”的板条箱里。这些海盗无法欣赏这件精湛的工艺品，或者只是不知道如何变卖它，便将镜片随手扔在了棘齿城南边海滩营地的杂物堆中。加兹鲁维指望勇敢的冒险者们去对抗那些割喉者，夺回完好无损的玻璃，最终让他的观测平台重新对焦。"}},faq={{q="加兹鲁维为什么要这个镜片？",a="加兹鲁维需要它来完成棘齿城天文台的望远镜。天文台需要两个镜片才能运作；较大的一个已从杜隆塔尔陆路安全送达，但较小的望远镜片却在海上丢失了。",al={"加兹鲁维 镜片","镜片用途","为什么要望远镜片"}},{q="谁偷走了望远镜片？",a="它被南海自由海盗掠走了，这是一伙在商旅海岸附近猎食商船的投机主义人类和地精海盗。他们把它存放在棘齿城南边海滩营地的一个标记过的板条箱里。",al={"谁拿走了镜片","谁拥有镜片","望远镜片位置"}},{q="这个镜片最初是从哪里来的？",a="它是通过海运运往棘齿城的，与从杜隆塔尔陆路运来的另一个镜片不同。进入该港口的货物通常来自无尽之海彼岸或像藏宝海湾这样的南方地精据点。",al={"镜片产地","镜片来源","加兹鲁维在哪订购的镜片"}},{q="尽管被偷了，镜片有损坏吗？",a="奇迹般的是，没有。镜片被安全地保存在一个贴有“易碎品——请勿跌落”标签的板条箱内，保护了精密玻璃免受南海海盗粗暴对待的影响。",al={"镜片坏了吗","易碎品请勿跌落板条箱"}}},fp="15,183,15.397.0,14.379.0,32.170.0,30.228.0,40.219.0,43.150.0"}
P.entries["item:teronis-journal"] = {n="泰洛尼斯的日记",s="《泰洛尼斯的日记》是一本从灰谷的一位暗夜精灵侦察兵遗骸中找到的野外笔记。它与被杀害的调查员一同被发现，记录了他对一颗神秘宝石的搜寻过程，并为阿斯特兰纳的哨兵提供了至关重要的证据。",h="《泰洛尼斯的日记》是一本从灰谷的一位暗夜精灵侦察兵遗骸中找到的野外笔记。它与被杀害的调查员一同被发现，记录了他对一颗神秘宝石的搜寻过程，并为阿斯特兰纳的哨兵提供了至关重要的证据。",kw={"灰谷","阿斯特兰纳","发光的宝石","莱恩·狼行者","莱恩的净化","哨兵","泰洛尼斯","泰洛尼斯的日记"},ang={["faction:Alliance"]="将泰洛尼斯的野外笔记带回阿斯特兰纳，有助于驻军协调救援并收回他们阵亡侦察兵的遗骸。",["race:NightElf"]="这本日记代表了暗夜精灵侦察兵为保护灰谷古老林地免受腐蚀侵袭而承担的危险职责。"},sec={{t="一名侦察兵的最后记录",b="作为莱恩·狼行者的多年好友，泰洛尼斯曾协助哨兵部队，并冒险进入灰谷的荒野，寻找一颗用于制造法杖的宝石，他相信这根法杖能延缓熊怪对他族人的攻击。他的任务在野外戛然而止，他在岸边被凶猛的生物包围并倒下。这本日记从他的个人遗物中被找回，尽管他死状凄惨，但日记却保存得相当完好。它概述了他关于那颗曾是法杖一部分的璀璨宝石的发现，为阿斯特兰纳的守卫者们提供了继续完成他未竟使命所需的关键线索。"}},faq={{q="这本日记的主人是谁？",a="这本日记属于泰洛尼斯，他是阿斯特兰纳的莱恩·狼行者的一位暗夜精灵朋友，当时正在灰谷寻找减缓熊怪攻击的方法。他在带回调查结果之前就死在了荒野中。",al={"谁写了这本日记","泰洛尼斯是谁","泰洛尼斯背景故事"}},{q="这本日记是在哪里找到的？",a="这本日记是在灰谷的荒野中，靠近当地鱼人聚居的岸边，通过搜寻泰洛尼斯的遗体找到的。",al={"在哪里找到日记","泰洛尼斯的日记位置","如何获得日记"}},{q="将日记带回阿斯特兰纳的目的是什么？",a="将日记交还给莱恩·狼行者可以告知阿斯特兰纳泰洛尼斯的死讯，并为哨兵部队提供完成他搜寻法杖任务所需的笔记，他曾希望用那根法杖来延缓熊怪的攻击。",al={"为什么要将日记带给莱恩","我应该把日记交给谁","日记上交"}},{q="根据他的任务，泰洛尼斯在寻找什么物品？",a="泰洛尼斯正在寻找一颗发光的宝石，这是死去的法师达尔托所制法杖的碎片之一。他的调查显示，附近的鱼人可能搜刮走了这件神器。",al={"泰洛尼斯在寻找什么","他在寻找什么宝石","泰洛尼斯的宝石"}}},fx={["5fb93f8f"]={q="什么是泰洛尼斯的日记？",a="泰洛尼斯的日记是暗夜精灵斥候泰洛尼斯留下的私人笔记。在灰谷，他的遗体旁发现了这本日记和他的其他遗物。日记记载了他的任务，以及他受命寻找一块奇异宝石时最初进行的侦察工作，之后他不幸殒命。",al={"泰洛尼斯的日记是什么","泰洛尼斯的日记物品","关于泰洛尼斯的日记"}}},fp="16,120,22.472.0,31.224.0,27.149.0,57.185.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="萨瑞尔祖恩的头颅",s="这个令人毛骨悚然的战利品是萨瑞尔祖恩的头颅，他是盘踞在石堡的黑石兽人先遣队的首领。治安官马瑞斯要求将其作为不可辩驳的证据，证明那个恐吓赤脊山周边地区的指挥官已经被击毙。",h="这个令人毛骨悚然的战利品是萨瑞尔祖恩的头颅，他是盘踞在石堡的黑石兽人先遣队的首领。治安官马瑞斯要求将其作为不可辩驳的证据，证明那个恐吓赤脊山周边地区的指挥官已经被击毙。",kw={"黑石先遣队","湖畔镇","治安官马瑞斯","石堡","石堡要塞","萨瑞尔祖恩","萨瑞尔祖恩的头颅"},ang={["faction:Alliance"]="每击杀一名黑石酋长，都能减轻饱受折磨的湖畔镇的压力，该镇在没有暴风城官方增援的情况下仍在为生存而战。"},sec={{t="石堡的战利品",b="盘踞在石堡要塞内的黑石兽人对湖畔镇施加了残酷的压力，他们袭击农场并伏击道路上的旅行者。这些袭击小队的先锋是由萨瑞尔祖恩所指挥的黑石先遣队。由于湖畔镇的守军无法承担仅凭谣言或部分胜利就采取行动的风险，治安官马瑞斯要求提供这位首领已死的确凿证据。带回萨瑞尔祖恩的头颅将证明从要塞发起的协调伏击行动遭受了重大打击。"}},faq={{q="萨瑞尔祖恩是谁？",a="萨瑞尔祖恩是一位狡诈而凶残的黑石兽人指挥官，驻扎在石堡要塞。他领导着黑石先遣队，与那些流亡者一起在湖畔镇和要塞之间不断发动伏击。",al={"萨瑞尔祖恩背景故事","萨瑞尔祖恩是谁","萨瑞尔祖恩首领"}},{q="为什么治安官马瑞斯想要他的头颅？",a="由于暴风城没有向赤脊山提供主要的军事援助，治安官马瑞斯和湖畔镇的卫兵只能依靠雇佣兵来铲除关键威胁。马瑞斯需要绝对的证据来确认萨瑞尔祖恩的死亡，以确保先遣队的指挥系统被彻底摧毁。",al={"为什么萨瑞尔祖恩的头颅","马瑞斯头颅证据","马瑞斯赏金"}},{q="萨瑞尔祖恩在哪里？",a="萨瑞尔祖恩占据着赤脊山东部山丘中的石堡要塞，周围环绕着黑石兽人和豺狼人。",al={"萨瑞尔祖恩位置","萨瑞尔祖恩在哪里","找到萨瑞尔祖恩"}},{q="取下萨瑞尔祖恩的头颅就能终结黑石氏族的威胁吗？",a="不能。虽然击杀萨瑞尔祖恩能干扰先遣队的伏击行动，但黑石氏族在石堡要塞和整个赤脊山仍维持着庞大的驻军。",al={"兽人离开了吗","我们拯救了赤脊山吗","萨瑞尔祖恩之后"}}},fx={a015b31b={q="什么是萨瑞尔祖恩的头颅？",a="这颗被砍下的头颅证明了萨瑞尔祖恩已被杀死。萨瑞尔祖恩是指挥黑石兽人在石堡要塞周边伏击的首领。它被带回湖畔镇后，向疲惫不堪的镇卫兵表明，赤脊山最危险的黑石氏族前线首领之一再也无法威胁道路了。",al={"萨瑞尔祖恩的头颅物品","萨瑞尔祖恩头颅的背景"}},f673cecf={q="萨瑞尔祖恩的头颅来自哪里？",a="它直接取自萨瑞尔祖恩的尸体。萨瑞尔祖恩是盘踞在石堡要塞废墟中的重要黑石兽人首领。在被你或湖畔镇的守军击败后，它的头颅被取下，作为确凿的战利品和证明其死亡的明证。",al={"谁取下了萨瑞尔祖恩的头颅","萨瑞尔祖恩头颅的来历","萨瑞尔祖恩的头颅来自哪里"}}},fp="17,162,20.425.0,19.188.0,38.256.0,26.111.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="萨纳瑞恩的希望",s="萨纳瑞恩的希望是由暗夜精灵萨纳瑞恩·绿树在黑海岸制作的一种特殊陷阱。该装置旨在安抚染病的野生动物而非伤害它们，它能投射出一种柔和的光芒，用以驯服狂暴的蓟熊，以便对它们进行检查以寻找治愈方法。",h="萨纳瑞恩的希望是由暗夜精灵萨纳瑞恩·绿树在黑海岸制作的一种特殊陷阱。该装置旨在安抚染病的野生动物而非伤害它们，它能投射出一种柔和的光芒，用以驯服狂暴的蓟熊，以便对它们进行检查以寻找治愈方法。",kw={"黑海岸","瘟疫之地","狂暴的蓟熊","萨纳瑞恩","萨纳瑞恩的希望","蓟熊","陷阱"},ang={["class:Druid"]="这个陷阱体现了塞纳里奥议会保护而非灭绝的理想，展示了在仍有救赎机会时拒绝猎杀受腐蚀野兽的态度。",["race:NightElf"]="黑海岸心爱的蓟熊的退化冲击着卡多雷与自然联系的核心，使得该装置成为绝望怜悯的一个深刻象征。"},sec={{t="温柔的诱捕",b="随着一种神秘的痛苦在黑海岸蔓延，当地的蓟熊变得越来越疯狂和狂暴。德鲁伊萨纳瑞恩·绿树并没有批准对受感染的野生动物进行扑杀，而是制作了这个独特的陷阱，希望能借此研究并治愈这种疾病。当放置在地面上时，萨纳瑞恩的希望会发出一种舒缓的光芒。任何踩过陷阱光芒的狂暴蓟熊，其狂乱状态都会被暂时打破，使这头野兽变得温顺，足以跟随冒险者回到萨纳瑞恩的营地接受治疗。"},{t="难以捉摸的疗法",b="虽然陷阱成功在不流血的情况下制服了发狂的野兽，但其背后的腐蚀力量却比预想的要恶毒得多。当萨纳瑞恩将他的治疗魔法灌注到被捕获的熊身上时，恢复力量与致命的感染发生了剧烈的冲突，导致受感染的生物崩溃并死亡。尽管他的初步试验以令人心碎的失败告终，但萨纳瑞恩坚持认为，在查明森林疾病的真正本质之前，他的决心绝不会动摇。"}},faq={{q="萨纳瑞恩的希望有什么作用？",a="它是一种附魔的地面陷阱，旨在安抚狂暴的蓟熊。将其放置在森林地面上会产生一个光场，暂时平静穿过其范围的熊，从而使这头野兽能够被和平地引导回萨纳瑞恩·绿树处。",al={"萨纳瑞恩的希望用途","陷阱如何运作","这是什么陷阱"}},{q="为什么萨纳瑞恩想要活捉一头熊？",a="萨纳瑞恩相信困扰黑海岸野生动物的疾病是可以治愈的，而不是通过屠杀来终结。他需要一个活的实验对象来直接测试他的净化疗法。",al={"为什么要捕获蓟熊","为什么要抓狂暴的熊","萨纳瑞恩想要什么"}},{q="如果弄丢了陷阱，还能再拿一个吗？",a="是的。萨纳瑞恩向旅行者保证，他的希望是永恒的。如果陷阱白白触发或在野外丢失，回到他那里可以获得另一个装置来完成任务。",al={"丢失萨纳瑞恩的希望","失败的陷阱","陷阱消失了"}},{q="当熊被带回来后会发生什么？",a="熊被带回来后，萨纳瑞恩会施放一个治疗附魔来清除腐蚀。可悲的是，那邪恶的疾病根深蒂固；魔法压倒了这头野兽，它在片刻之后便死去了。",al={"熊能活下来吗","萨纳瑞恩能治好熊吗","熊在萨纳瑞恩处死亡"}}},fp="17,155,14.418.0,18.410.1,31.184.0,46.170.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="乌尔之书",s="《乌尔之书》是一部由达拉然已故法师乌尔所著的学术性魔法论著，详细记录了他对奇特异维度实体的研究。这本书被遗留在影牙城堡中，后来落入了阿鲁高大法师之手，并引起了幽暗城中被遗忘者研究员们的浓厚兴趣。",h="《乌尔之书》是一部由达拉然已故法师乌尔所著的学术性魔法论著，详细记录了他对奇特异维度实体的研究。这本书被遗留在影牙城堡中，后来落入了阿鲁高大法师之手，并引起了幽暗城中被遗忘者研究员们的浓厚兴趣。",kw={"apothecarium","阿鲁高","乌尔之书","达拉然","看守者贝尔杜加","影牙城堡","银松森林","乌尔"},ang={["class:Mage"]="乌尔的著作清楚地提醒着人们，达拉然曾向其他领域进行过多么深远的学术探索——以及像阿鲁高这样野心勃勃的法师滥用这些禁忌知识时会带来多么致命的后果。",["race:Undead"]="获得乌尔的研究成果将直接帮助Apothecarium里黑暗女王的学者们，将一位已故人类法师谨慎的研究转化为被遗忘者的实用力量。"},sec={{t="达拉然的法师",b="在达拉然沦陷于天灾军团之前，乌尔就因对其他位面和异界生物的深奥研究而在肯瑞托中享有盛名。尽管他对异界魔法充满着迷，但乌尔始终保持着谨慎和道德底线，宁愿将自己的发现记录在案，也不愿鲁莽地打破世界之间的隔阂。遗憾的是，当天灾军团袭击这座紫罗兰之城时，他的魔法造诣和道德顾虑并没能拯救他。"},{t="被遗忘者的野心",b="乌尔死后，他的手稿落入了阿鲁高大法师手中，后者利用这些研究将可怕的狼人召唤到了银松森林。这本典籍如今静静地躺在影牙城堡的书架上。它的存在引起了幽暗城Apothecarium里看守者贝尔杜加的注意。与原本的作者不同，被遗忘者在使用危险且无拘无束的魔法以确保生存和征服方面，没有任何心理负担。"}},faq={{q="乌尔是谁？",a="乌尔是第三次战争前达拉然的一位杰出人类法师。他广泛研究了其他维度和异位面生物，尽管他因这些生物带来的巨大危险而拒绝召唤它们。",al={"谁写了乌尔之书","乌尔达拉然法师"}},{q="《乌尔之书》位于何处？",a="这本书位于银松森林的影牙城堡内的一处书架上，具体来说，是在巨大野兽芬鲁斯所在的房间里。",al={"乌尔之书位置","乌尔之书在哪里"}},{q="看守者贝尔杜加为什么要这本书？",a="看守者贝尔杜加代表幽暗城的利益相关方收集乌尔的著作。被遗忘者认为乌尔的道德良知限制了他获得真正的力量，他们寻求在没有任何道德束缚的情况下利用他的异位面研究，以增强自身的力量。",al={"看守者贝尔杜加乌尔之书","幽暗城为什么想要这本书"}},{q="这本书是如何落入影牙城堡的？",a="乌尔在达拉然沦陷期间去世后，阿鲁高大法师获得了他的研究成果。为了抵御天灾军团而被迫采取孤注一掷的手段，阿鲁高将这些笔记带到了银松森林，并利用乌尔的召唤理论将狼人引向了艾泽拉斯。",al={"阿鲁高和乌尔之书","阿鲁高如何得到这本书"}}},fx={["62a01830"]={q="什么是乌尔之书？",a="乌尔之书是一部学术典籍，收录了达拉然杰出法师乌尔的奥秘研究。书中详述了他对其他世界和危险奥术现象的深入研究。这些知识力量强大，后来大法师阿鲁高利用乌尔的著作，将可怕的狼人召唤到了银松森林。",al={"乌尔之书是什么","乌尔之书的背景"}},["905bb2c4"]={q="乌尔之书来自哪里？是谁写的？",a="在天灾军团摧毁达拉然后，这本书被留在了这座魔法王国中。此前，法师乌尔曾在达拉然执笔撰写此书，记录他的奥术理论和对其他维度的探索。乌尔在达拉然沦陷期间身亡后，这项研究便被搁置了。",al={"谁写了乌尔之书","乌尔之书的来历","乌尔之书来自哪里"}}},fp="14,195,19.393.0,17.356.1,11.166.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="收货人的交易日程表",s="《收货人的交易日程表》是一份手写的行程表，详细记录了从艾尔文森林的矿井中开采出的非法黄金运输的日期和时间。该文件是从当地豺狼人手中缴获的，揭示了一位只被称为“收货人”的神秘人物正在布莱克威尔南瓜田附近协调这项行动。",h="《收货人的交易日程表》是一份手写的行程表，详细记录了从艾尔文森林的矿井中开采出的非法黄金运输的日期和时间。该文件是从当地豺狼人手中缴获的，揭示了一位只被称为“收货人”的神秘人物正在布莱克威尔南瓜田附近协调这项行动。",kw={"布莱克威尔","收货人","杜汉","艾尔文","黄金","闪金镇","矿井","日程表"},ang={["faction:Alliance"]="这份日程表暴露了暴风城对领土的掌控力已变得多么薄弱，未经授权的行动者正在首都外掠夺着王国的自然资源。",["profession:Mining"]="该文件证明，尽管有报道称艾尔文森林的矿井处于休眠状态，但丰富的金脉实际上正在被积极开采并运走。"},sec={{t="被盗的黄金与秘密运输",b="这份日程表提供了令人担忧的证据，表明有组织活动正在暴风城卫戍部队的眼皮底下进行。尽管由于强盗和生物入侵，王国已经有数月未正式开采艾尔文森林的矿井，但矿石仍在被系统性地开采并运走。该便条列出了被称为“收货人”的接货人接收货物的具体日期和时间，指向了艾尔文森林东部布莱克威尔南瓜田附近的一个营地。当向治安官杜汉出示这份文件时，他认出了“收货人”这个名字，但那个为被盗黄金买单的真正幕后黑手依然隐藏在阴影中。"}},faq={{q="什么是《收货人的交易日程表》？",a="这是一份缴获的文件，详细列出了从艾尔文森林废弃矿井运出黄金的时间表，以及运送给被称为“收货人”的操作人员的相关信息。",al={"这个便条是什么","收货人的交易日程表物品","黄金日程表"}},{q="这份日程表是从哪里来的？",a="该便条是由盘踞在艾尔文森林河岸和山坡上的豺狼人携带的，这表明他们要么拦截了一名信使，要么以某种方式参与了黄金的运输。",al={"谁掉落日程表","哪里可以找到日程表"}},{q="收货人是谁？",a="收货人是一名驻扎在艾尔文森林东部布莱克威尔南瓜田附近的代理人。经典的日程表中提到了迪菲亚潜行者及其位于西部荒野的总部，尽管治安官杜汉表示他尚不清楚收货人为谁效力。",al={"收货人是谁","收货人身份"}},{q="为什么治安官杜汉对这份日程表感到担忧？",a="由于安全威胁，暴风城已经数月没有正式的矿工在艾尔文森林的矿井工作了。发现仍有大量的黄金被运出，揭示了在王国边境之内正存在着一个有组织、非法的采矿行动。",al={"杜汉为何关心此事","艾尔文矿井黄金"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="藏尸者的心脏",s="藏尸者的心脏是一件邪恶的圣物，在那埋藏于暮色森林深处的Eliza亡灵尸骸中跳动着。它曾属于一位被称为“藏尸者”的悲伤炼金术士，这颗心脏通过黑暗魔法被移植到他亡妻的遗体中试图复活她，从此成为了他扭曲力量的主要源头。",h="藏尸者的心脏是一件邪恶的圣物，在那埋藏于暮色森林深处的Eliza亡灵尸骸中跳动着。它曾属于一位被称为“藏尸者”的悲伤炼金术士，这颗心脏通过黑暗魔法被移植到他亡妻的遗体中试图复活她，从此成为了他扭曲力量的主要源头。",kw={"藏尸者的新娘","夜色镇","暮色森林","eliza","ello ebonlocke","藏尸者的心脏","藏尸者"},ang={["class:Warlock"]="将一颗仍在跳动的灵魂绑定器官移植出去以锚定死灵生命，是一项大胆甚至混乱的血肉与灵魂操纵工程。",["race:Human"]="这位仁慈炼金术士的悲剧堕落，成为了暮色森林苦难人民口中流传的一则严酷警示故事。"},sec={{t="一段违逆死亡的爱",b="据夜色镇的民间传说，藏尸者曾是一位善良的炼金术士，在爱妻Eliza去世后精神崩溃。为了不惜一切代价将她从坟墓中夺回，他诉诸邪恶的巫术，挖出了自己的心脏，放入了Eliza冰冷的胸腔。尽管这种邪恶的输送成功让她的遗骸重获“新生”，但复活过程也使她扭曲成了一个渴望鲜活人肉的饥饿怪物，迫使这位陷入恐惧的炼金术士只能将她再次埋入土中。"},{t="夜色镇的护盾",b="尽管已被挖出胸腔，这颗心脏依然是藏尸者持续不断的黑暗力量之源，并继续在Eliza的墓中跳动。Ello Ebonlocke镇长意识到，摧毁这具复活的新娘遗骸并夺取那颗搏动的心脏，是剥夺藏尸者巫术的唯一途径。夜色镇的领导者们希望能在心脏还在跳动时将其夺回，利用其中蕴含的邪恶魔力反制其主，作为抵御他恐怖阴影的保护性结界。"}},faq={{q="为什么Eliza会有藏尸者的心脏？",a="藏尸者在妻子Eliza死后悲痛欲绝，便使用禁忌魔法将自己跳动的心脏移植到她的尸体中试图复活她。仪式虽然让她复活，却也诅咒她对人肉产生了无法满足的渴望。",al={"为什么eliza有那颗心脏","eliza体内的藏尸者心脏","谁把心脏放进了eliza体内"}},{q="为什么Ebonlocke镇长想要把心脏带回夜色镇？",a="Ello Ebonlocke镇长打算利用那颗仍在搏动的心脏中回荡的黑暗魔法，在夜色镇上空建立一道防御结界，用以抵消藏尸者的力量，并将这股邪力转化为守护城镇的屏障。",al={"为什么ello想要心脏","ebonlocke的心脏计划","夜色镇如何利用心脏"}},{q="藏尸者没有心脏是如何活下来的？",a="通过他所修习的黑暗巫术，藏尸者将自己的生命力和力量直接与移植的心脏绑定，这使他即便在心脏于妻子埋骨之地跳动时，也能继续存活。",al={"藏尸者还活着吗","藏尸者没心脏怎么活"}},{q="心脏在哪里可以找到？",a="这颗心脏位于Eliza的体内，她依然被埋藏在暮色森林中一处隐秘的墓地。只有通过面对并击败那饥渴的复活新娘才能将其夺取。",al={"藏尸者的心脏在哪里","eliza的墓地位置","如何获得藏尸者的心脏"}}},fx={cac9cdef={q="什么是藏尸者的心脏？",a="它就是叛变炼金术师“藏尸者”那颗在魔法维持下仍不断跳动的心脏。藏尸者因妻子伊莉莎之死而悲痛欲狂，挖出自己的心脏并放入她的尸体中，试图让她复生。即便离开了胸腔，这颗心脏仍是他死灵力量的容器和媒介，维持着伊莉莎受诅咒的不死状态，也维系着他自身邪恶的活力。",al={"藏尸者的心脏是什么","藏尸者心脏的背景","藏尸者的心脏"}}},fp="20,176,24.408.0,22.361.1,41.173.0,66.113.0,48.156.0,29.167.0"}
P.entries["item:the-general-s-response"] = {n="将军的回信",s="“将军的回信”是一份由暴风城卫队指挥官马库斯·乔纳森将军所写的正式军事公文。这封信旨在回复湖畔镇的所罗门镇长，承认了赤脊山对于援助的请求，但同时也透露出暴风城目前无法——或不愿——立即派遣皇家援军。",h="“将军的回信”是一份由暴风城卫队指挥官马库斯·乔纳森将军所写的正式军事公文。这封信旨在回复湖畔镇的所罗门镇长，承认了赤脊山对于援助的请求，但同时也透露出暴风城目前无法——或不愿——立即派遣皇家援军。",kw={"马库斯·乔纳森将军","湖畔镇","所罗门镇长","去暴风城的信使","赤脊山","暴风城","将军的回信"},ang={["faction:Alliance"]="这封回信突显了联盟边缘正在分崩离析：像湖畔镇这样的边陲定居点正在流血，而暴风城的宫廷却对他们的困境表现得异常冷漠。",["race:Human"]="对于南部王国的人类来说，这段停滞的通信显示出那些在地方为了生存而战的平民与隐居在Stormwind Keep的贵族之间，裂痕正在不断扩大。"},sec={{t="外交僵局",b="当所罗门镇长绝望地向暴风城求援，希望获得部队以抵御在赤脊山集结的黑石兽人氏族和豺狼人战帮时，他的求援信直接送达了最高指挥部。马库斯·乔纳森将军的回信提供了一份冷淡的安慰：虽然求援请求已经上呈至王座，但目前并没有派兵。将军受困于规章制度与政治考量之间，下令将信件送回湖畔镇，这让所罗门感到不安，并怀疑暴风城的领导层正陷入某种深重的隐疾之中。"}},faq={{q="“将军的回信”中写了什么？",a="马库斯·乔纳森将军对死者表示哀悼，并承诺会将湖畔镇的情况告知国王。他希望能带来援军，并私下透露国王近期深居简出，举止异常。",al={"信件内容","信里说了什么","将军的信"}},{q="为什么马库斯·乔纳森将军无法向湖畔镇派遣部队？",a="乔纳森将军在做出援军承诺前必须等待国王的回复。他私下告诉所罗门，国王近期深居简出，举止异常。",al={"为何没有援军","为什么暴风城不援助湖畔镇","为何没有支援"}},{q="所罗门镇长对这封信有何反应？",a="所罗门镇长对这份公文感到非常不安。他认为在湖畔镇面临可怕威胁的情况下，暴风城的迟缓令人费解，断定王国内部一定出了大问题，并担心这种忽视预示着更严重的灾难即将来临。",al={"所罗门的反应","所罗门怎么想","所罗门的回应"}}},fp="22,235,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-lich-s-spellbook"] = {n="巫妖的法术书",s="《巫妖的法术书》是一本存放在澈水湖岛屿上的箱子里的死灵法术典籍。它是为幽暗城的比索·埃斯沙德寻回的，这本书揭示了一位居住在被遗忘者首都北部的隐居亡灵巫妖的真实身份和强大的魔法力量。",h="《巫妖的法术书》是一本存放在澈水湖岛屿上的箱子里的死灵法术典籍。它是为幽暗城的比索·埃斯沙德寻回的，这本书揭示了一位居住在被遗忘者首都北部的隐居亡灵巫妖的真实身份和强大的魔法力量。",kw={"比索·埃斯沙德","澈水湖","冈瑟尔·阿坎努斯","巫妖","死灵法术","法术书","提瑞斯法林地","幽暗城"},ang={["class:Mage"]="这本法术书代表了经典达拉然魔法和黑暗死灵法术之间非凡的桥梁，展示了凡人施法者在屈服于亡灵状态后是如何极大地扩展了他们的技艺。",["race:Undead"]="这本典籍证明了并非所有从巫妖王那里获得自由的亡灵都立即加入了被遗忘者，这凸显了散布在提瑞斯法林地的那些流亡亡灵幸存者之间挥之不去的怀疑。"},sec={{t="一位隐居大师的典籍",b="在澈水湖的一座孤岛上，站着一位被骷髅守卫包围的神秘巫妖。尽管拥有自由意志，但这位法师不信任外面的世界，他将所有其他的亡灵都误认为是天灾军团的奴仆，并命令他的爪牙摧毁任何靠近的人。比索·埃斯沙德为了寻找有天赋的死灵法师来加强希尔瓦娜斯·风行者女王麾下的被遗忘者队伍，派遣了一名特使潜入该岛营地以寻回巫妖的法术书。通过研究它，比索希望能够辨别这位大师的魔法天赋，并找出他在死亡降临洛丹伦之前是谁。"},{t="揭开冈瑟尔·阿坎努斯的真面目",b="在翻开这本寻回的法术书那发光的书页后，比索·埃斯沙德有了惊人的发现：这位隐居者竟是他第三次战争前的一位老朋友和战友，冈瑟尔·阿坎努斯。冈瑟尔生前就已经是一位死灵法术天才，而他的著作显示，他在死后，其技艺变得更加可怕。比索意识到，如果能争取到冈瑟尔的效忠，被遗忘者将获得一位宝贵的黑暗艺术大师，前提是有人能让这位多疑的巫妖相信被遗忘者确实已经摆脱了巫妖王的控制。"}},faq={{q="在哪里可以找到《巫妖的法术书》？",a="这本法术书存放在一个名为“冈瑟尔的书籍”的容器里，位于提瑞斯法林地北部澈水湖中央岛屿的营地中。",al={"书的位置","法术书位置","冈瑟尔的书籍"}},{q="这本法术书的主人是谁？",a="它属于澈水湖岛上的那位隐居的、拥有自由意志的巫妖。比索·埃斯沙德希望通过研究书页能揭示其主人的身份和天赋。",al={"这本书是谁的","巫妖的身份","谁写的法术书"}},{q="为什么比索·埃斯沙德想要这本书？",a="比索·埃斯沙德寻找这本书是为了推断出这位神秘巫妖的身份，并评估他对死灵法术的掌握程度，希望能将这位隐居者招募到希尔瓦娜斯女士和被遗忘者的麾下。",al={"为什么要获取这本书","比索的任务动机","为什么幽暗城想要这个"}},{q="为什么这个巫妖会攻击他岛上的访客？",a="这位巫妖认为该地区所有其他的亡灵仍然是被天灾军团精神控制的奴隶。由于多疑，他命令手下的爪牙攻击任何冒险靠近他圣所的人。",al={"为什么冈瑟尔充满敌意","为什么爪牙会攻击","澈水湖的敌对势力"}},{q="比索希望了解关于作者的什么信息？",a="比索希望发现这位隐居的巫妖生前是谁，以及他的死灵法术知识是否能帮助被遗忘者。",al={"比索会了解到什么","对巫妖作者的研究","比索对法术书的研究"}}},fp="20,148,26.473.0,25.437.1,36.140.0,24.154.1,39.143.0,48.149.0,48.117.1"}
P.entries["item:the-state-of-lakeshire"] = {n="湖畔镇的现状",s="《湖畔镇的现状》是一份由所罗门镇长起草的紧急书面报告，详细描述了正困扰着湖畔镇的绝望军事危机。这份文件直接呈交给了暴风城的马库斯·乔纳森将军，恳求首都在赤脊山定居点沦陷前部署皇家军队增援。",h="《湖畔镇的现状》是一份由所罗门镇长起草的紧急书面报告，详细描述了正困扰着湖畔镇的绝望军事危机。这份文件直接呈交给了暴风城的马库斯·乔纳森将军，恳求首都在赤脊山定居点沦陷前部署皇家军队增援。",kw={"公文","所罗门镇长","马库斯·乔纳森","赤脊山","增援","报告","湖畔镇的现状","暴风城"},ang={["faction:Alliance"]="这份报告展示了外围定居点的脆弱性，并突显了目前阻碍首都提供军事援助的政治惰性。",["race:Human"]="对于王国的人类而言，携带这份文件更加深了人们对赤脊山的平民与遥远的暴风城王室之间日益疏远的联系的认识。"},sec={{t="求援的呼声",b="在赤脊山遭受猛烈攻击期间，所罗门镇长起草了《湖畔镇的现状》，概述了威胁该城镇的严峻形势。湖畔镇正遭到敌对的黑石兽人和豺狼人的围攻，当地缺乏足够的人力来长期守卫其边界。这份公文被托付给值得信赖的信使，让他们沿着道路向西前往艾尔文森林，其中包含了所罗门请求暴风城军队介入并保卫王国东部地区的正式请求。"},{t="官僚主义与僵局",b="当文件被送到暴风城大门口的马库斯·乔纳森将军手中时，将军认可了所罗门镇长的崇高地位以及这份报告的重要性。然而，乔纳森无法单方面调动军队。军事部署需要王室的明确许可，这迫使湖畔镇的紧急请求不得不等待与年轻的国王以及摄政王Bolvar Fordragon进行高层商议。"}},faq={{q="什么是《湖畔镇的现状》？",a="这是一份由所罗门镇长撰写的官方书面公文，详细描述了湖畔镇面临的军事危机，并恳求暴风城派遣军队增援。",al={"湖畔镇的现状文件","这个报告是什么","所罗门的信息"}},{q="这份公文应该交给谁？",a="这份报告直接呈交给了驻扎在暴风城门口的暴风城卫队及皇家军队指挥官马库斯·乔纳森将军。",al={"谁接收报告","送给谁","马库斯·乔纳森报告"}},{q="为什么湖畔镇需要皇家军队的增援？",a="该定居点面临着黑石兽人、影牙豺狼人和当地鱼人的不断围攻，使得当地城镇卫队的防御能力已达极限。",al={"为什么湖畔镇处于危险之中","什么威胁着赤脊山"}},{q="马库斯·乔纳森将军会立即派遣援助吗？",a="不会。虽然将军也认为危机十分严重，但他不能在没有国王正式批准的情况下调动军队，这意味着该请求必须先经过王室审核。",al={"暴风城会提供帮助吗","乔纳森会派兵吗"}}},fx={["629511cc"]={q="湖畔镇的现状来自哪里？是谁写的？",a="湖畔镇的民政首领兼法官所罗门镇长起草了这份重要报告。面对包围城镇的敌对势力不断施压，所罗门亲自写下这份公文，正式说明赤脊山岌岌可危的局势，并请求暴风城最高指挥部立即提供军事援助。",al={"谁写了湖畔镇的现状","谁撰写了湖畔镇的现状","湖畔镇现状报告的作者"}},["09d61feb"]={q="为什么急需湖畔镇的现状报告？",a="湖畔镇一直遭到围困，所罗门镇长知道，没有王室援军，镇子无法独自坚守。马库斯·乔纳森将军需要这份正式报告作为派遣部分暴风城军队的依据，并将湖畔镇的危急处境直接呈报给国王和伯瓦尔·弗塔根公爵。",al={"为什么需要湖畔镇的现状报告","为什么要送交湖畔镇的现状报告","马库斯·乔纳森为什么想要湖畔镇的现状报告"}}},fp="22,191,13.311.0,24.305.0,31.151.0,41.150.0,45.157.0,51.164.0"}
P.entries["item:theramore-medal"] = {n="塞拉摩徽章",s="塞拉摩徽章是驻扎在北方城堡的联盟守军所佩戴的军事徽章。这些徽章上印有塞拉摩的标志，是守卫商旅海岸前哨站的海军陆战队员和军官们的服役证明。",h="塞拉摩徽章是驻扎在北方城堡的联盟守军所佩戴的军事徽章。这些徽章上印有塞拉摩的标志，是守卫商旅海岸前哨站的海军陆战队员和军官们的服役证明。",kw={"贫瘠之地","captain fairmount","商旅海岸","北方城堡","沙罗萨斯船长","塞拉摩徽章"},ang={["faction:Alliance"]="对于联盟的忠诚者来说，看到塞拉摩的徽章被当作血腥赏金收集起来，是一个残酷的提醒，让他们意识到北方城堡在卡利姆多的边境上变得多么孤立和具有侵略性。",["faction:Horde"]="部落冒险者将这些徽章视为联盟军事力量不断增长、直接侵入贫瘠之地海岸线的实证。"},sec={{t="北方城堡的信物",b="在北方城堡服役的海军陆战队员、神射手、突击队员和军官们都佩戴着这种刻印徽章，以此表明对吉安娜·普罗德摩尔的塞拉摩王国的军事效忠。对于驻扎在俯瞰贫瘠之地的悬崖上的人类士兵来说，它们代表着在敌对边境上的合法服役和主权权威。然而在局外人看来，这些徽章只是一个过度狂热的外国守军的战利品，这支守军将沿岸驶来的每一艘船只都视为致命威胁。"},{t="海盗的复仇",b="北方城堡的炮台对航行在商旅海岸的海上交通构成了致命威胁，经常轰击私掠船和商船。为了回应损失的船只，棘齿城的私掠者沙罗萨斯船长寻求获得这些徽章，作为北方城堡那些喜欢乱开火的士兵为击沉他的船只而付出血的代价的证据。"}},faq={{q="什么是塞拉摩徽章？",a="这是部署在北方城堡的塞拉摩军事人员所佩戴的徽章。它能证明佩戴者是正在贫瘠之地为联盟守军服役的现役海军陆战队员、水手或军官。",al={"塞拉摩徽章","什么是塞拉摩徽章","北方城堡徽章"}},{q="谁持有这些徽章？",a="它们由北方城堡沿商旅海岸的士兵持有，包括海军陆战队员、神射手、甲板水手、突击队员以及守军的高级炮手和军官。",al={"谁持有塞拉摩徽章","谁掉落塞拉摩徽章","塞拉摩徽章从哪里来"}},{q="为什么沙罗萨斯船长需要它们？",a="北方城堡的炮台一直在轰击过往船只，包括属于沙罗萨斯船长舰队的船只。他要求获得这些徽章，作为应负责任的士兵已被处死以示报复的无可辩驳的证据。",al={"为什么棘齿城需要徽章","沙罗萨斯徽章","为什么要收集塞拉摩徽章"}},{q="为什么北方城堡要攻击过往船只？",a="北方城堡的守军在部落领地的边缘处于高度偏执的状态。他们的炮手变得鲁莽且喜欢乱开火，向几乎所有靠近其沿海据点的船只开火。",al={"为什么北方城堡要射击船只","北方城堡的侵略行为","为什么北方城堡攻击棘齿城"}}},fp="15,204,20.467.0,16.383.0,26.206.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="厚熊皮",s="厚熊皮是一种珍贵的毛皮，采集自丹莫罗雪堆中那些适应了严寒的熊。由于其卓越的保暖性，它常被旅行的侦察兵和士兵用来制作隔热材料和温暖的寝具，以抵御寒冷的高山冻气。",h="厚熊皮是一种珍贵的毛皮，采集自丹莫罗雪堆中那些适应了严寒的熊。由于其卓越的保暖性，它常被旅行的侦察兵和士兵用来制作隔热材料和温暖的寝具，以抵御寒冷的高山冻气。",kw={"贝隆·风箱","丹莫罗","灰色洞穴","冰爪熊","喷气蒸汽号","钢架补给站","厚熊皮"},ang={["class:Hunter"]="深入寒冷的灌木丛追踪丹莫罗的熊，能让年轻的猎人学会如何应对危险的山中野兽，并从荒野中获取耐用的材料。",["race:Gnome"]="像贝隆·风箱这样在钢架补给站周边行动的攻城坦克驾驶员，必须依靠实用的矮人国度狩猎技巧，才能确保他们的机器在漫长的高山部署中维持生存能力。"},sec={{t="抵御高山严寒的温暖",b="徘徊在丹莫罗山脊上的熊忍受着东部王国最恶劣的雪原环境。它们厚实且坚韧的皮毛提供了抵御暴风雪的重要保护，使这种毛皮成为了当地人和旅行者眼中的宝贵资源。这些厚重的皮毛不会被当作废料丢弃，而是经常被猎人采集，用来缝制衣物、为通风的哨所提供隔热，以及填充冰冷的睡袋。"},{t="攻城小队的寝具",b="当驾驶员贝隆·风箱在钢架补给站为他的攻城坦克“喷气蒸汽号”进行装备时，他面临着要在野外执行长达一个月的攻城小队任务的严酷前景。由于冰冷的铁皮在高海拔的积雪中无法提供任何舒适感，他委托当地的侦察兵收集灰色洞穴以南雪原上的厚熊皮，为他的驾驶舱制作温暖的寝具。"}},faq={{q="厚熊皮从哪里获得？",a="厚熊皮采集自丹莫罗的原生熊类，特别是幼年黑熊和冰爪熊。它们常出没在灰色洞穴以南的雪地苔原和松树林中。",al={"厚熊皮获取地点","厚熊皮掉落来源","熊皮位置"}},{q="为什么驾驶员贝隆·风箱需要这种毛皮？",a="驾驶员贝隆·风箱正在为他的坦克“喷气蒸汽号”进行装备，以执行一项代表攻城小队、为期一个月的长期任务。他需要厚重的毛皮来在金属底盘内铺设温暖的寝具，以熬过寒冷的山区夜晚。",al={"贝隆·风箱的毛皮","为什么贝隆·风箱需要毛皮","喷气蒸汽号储藏毛皮"}},{q="丹莫罗的哪些生物会掉落这种毛皮？",a="无论是幼年黑熊，还是徘徊在高地雪原上更庞大、更凶猛的冰爪熊，都拥有制作厚重冬季寝具和隔热材料所需的浓密毛皮。",al={"哪些熊掉落毛皮","丹莫罗的熊种类"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thistlenettle-s-badge"] = {n="希斯耐特的徽章",s="希斯耐特的徽章是矮人探险者协会的官方标志，曾经由工头希斯耐特骄傲地携带进入死亡矿井的深处。在一场灾难性的塌方和盗贼入侵之后，这枚徽章成了证实这位工头悲惨命运，并交还给他身在暴风城的幸存兄弟的唯一遗物。",h="希斯耐特的徽章是矮人探险者协会的官方标志，曾经由工头希斯耐特骄傲地携带进入死亡矿井的深处。在一场灾难性的塌方和盗贼入侵之后，这枚徽章成了证实这位工头悲惨命运，并交还给他身在暴风城的幸存兄弟的唯一遗物。",kw={"死亡矿井","探险者协会","月溪镇","噢，兄弟","希斯耐特","希斯耐特的徽章","西部荒野","维尔德"},ang={["faction:Alliance"]="寻回这枚徽章为居住在暴风城Dwarven District的一位悲伤的矮人带来了慰藉。",["race:Dwarf"]="工头希斯耐特带着探险者协会的旗帜和徽章进入了西部荒野；收回他的徽章，确保了这位倒下的铁炉堡之子不会被黑暗所遗忘。"},sec={{t="死亡矿井里的探险者协会",b="在迪菲亚潜行者封锁月溪镇及其下方的蜿蜒隧道之前，隶属于铁炉堡探险者协会的矮人勘探者们曾深入西部荒野的旧金矿。工头希斯耐特和他的工队在地下深处作业，直到一次突如其来的隧道坍塌将他们分开了。虽然他的兄弟维尔德·蓟草设法逃到了暴风城，但工头和几名劳工却被困在了地下的黑暗之中。"},{t="残酷的确认",b="工头希斯耐特没能找到光荣的安息之地或逃生路线，而是屈服于未封锁隧道中滋生的黑暗危险，在主铸造厂外的倒塌矿道中变成了一个毫无理智的亡灵怪物。他的探险者协会徽章依然紧紧抓在他身上，当被寻回并交给他悲痛欲绝的兄弟时，成为了他死亡的唯一确凿证据。"}},faq={{q="这枚徽章属于谁？",a="这枚徽章属于工头希斯耐特，他是一位矮人矿工，也是探险者协会的成员，在西部荒野的一次突发隧道坍塌中被困于地下深处。",al={"希斯耐特的徽章属于谁","希斯耐特的徽章持有者"}},{q="这枚徽章在哪里可以找到？",a="它由死亡矿井怪物出没的上层走廊里的工头希斯耐特携带，位于迪菲亚潜行者要塞的正门外。",al={"徽章位置","如何获得希斯耐特的徽章","哪里可以找到希斯耐特"}},{q="谁想要希斯耐特的徽章？",a="这枚徽章要带给工头希斯耐特的兄弟，维尔德·蓟草，他目前居住在暴风城的Dwarven District，等待着他亲人命运的消息。",al={"谁要希斯耐特的徽章","谁提交噢，兄弟任务","维尔德·蓟草的位置"}},{q="为什么蓟草兄弟会在死亡矿井？",a="在敌对的盗贼和结构坍塌毁掉他们的探险之前，这对兄弟在探险者协会的支持下，一直在测量和勘探月溪镇下方广阔且矿产丰富的洞穴。",al={"为什么矮人在死亡矿井","希斯耐特死亡矿井任务"}}},fp="21,86,38.379.0,19.256.1,30.169.0,25.149.0,32.146.0,53.168.0"}
P.entries["item:thresher-eye"] = {n="蛇颈龙的眼球",s="蛇颈龙的眼球是从徘徊在黑海岸沿海水域的蛇颈龙身上采集到的有机样本。古怪的侏儒工程师维兹班恩·曲针为了维修他的自动野外装置（即嗡嗡盒）而寻求这些东西。",h="蛇颈龙的眼球是从徘徊在黑海岸沿海水域的蛇颈龙身上采集到的有机样本。古怪的侏儒工程师维兹班恩·曲针为了维修他的自动野外装置（即嗡嗡盒）而寻求这些东西。",kw={"奥伯丁","嗡嗡盒411","黑海岸","黑海岸蛇颈龙","蛇颈龙的眼球","维兹班恩·曲针"},ang={["profession:Engineering"]="维兹班恩依赖原始动物部位来修复复杂的机械中继装置，这提供了一个令人困惑却又幽默的非正统侏儒装置的研究案例。",["race:Gnome"]="维兹班恩·曲针代表了侏儒创造力中更为狂野的一面，他在杯中斟满爬行者之酒的同时，在卡利姆多的荒野中修补着野外机械。"},sec={{t="用于侏儒小玩意的生态样本",b="在黑海岸烟雾缭绕的海岸外，被称为黑海岸蛇颈龙的水生掠食者在浪花和外围浅滩中捕食。虽然它们对当地的渔民和旅行者来说很危险，但这些野兽拥有巨大的视觉器官，引起了维兹班恩·曲针的特殊兴趣。这位驻扎在附近且酷爱爬行者之酒的侏儒工程师要求将这些眼球作为修复嗡嗡盒411的重要组件，这是他的一种远距离通信机器，位于奥伯丁以北的海滩上。"},{t="眼球的用途",b="维兹班恩从未完全解释过黏糊糊的海兽眼球是如何修复精密机械装置的，不管是作为粗糙的光学透镜、化学试剂，还是深奥的生物齿轮。尽管这种工程逻辑令人怀疑，但将三个采集到的眼球放入嗡嗡盒411的维护舱口确实能成功恢复机器的通信链路，使维兹班恩能够通过充满静电干扰的传输发送奖励。"}},faq={{q="蛇颈龙的眼球从哪里来？",a="蛇颈龙的眼球是从黑海岸海岸外海洋水域中游泳的黑海岸蛇颈龙和年长的黑海岸蛇颈龙身上采集的，尤其是在奥伯丁附近。",al={"蛇颈龙的眼球掉落地点","如何获得蛇颈龙的眼球","蛇颈龙的眼球来源"}},{q="为什么维兹班恩·曲针需要蛇颈龙的眼球？",a="维兹班恩声称需要这些眼球来修理嗡嗡盒411，这是一个位于奥伯丁以北海岸线上的侏儒装置。将它们插入机器的舱口可以重新激活其系统。",al={"为什么需要蛇颈龙的眼球","嗡嗡盒411眼球","蛇颈龙的眼球有什么用"}},{q="眼球是如何修理机器的？",a="侏儒工程学往往违背常规逻辑，尤其是在维兹班恩·曲针醉醺醺的计划指导下更是如此。无论他是利用视网膜进行光学聚焦，还是仅仅将有机部件整合到他古怪的设计中，该装置都能接受它们并重新启动。",al={"为什么机器需要眼球","侏儒机器生物部件"}},{q="什么是嗡嗡盒411？",a="嗡嗡盒411是维兹班恩·曲针在黑海岸各地部署的多种通信和监控装置之一。一旦装入所需的材料，它就能让维兹班恩进行远程通信并分发补给。",al={"嗡嗡盒411用途","谁制造了嗡嗡盒411"}}},fp="12,143,38.358.0,23.312.0,33.128.0,48.158.0,30.214.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="图勒的头颅",s="“图勒的头颅”是被遗忘者所要求的残酷证据，用以确认芬里斯岛上的天灾军团指挥官——图勒·鸦爪已经死亡。将这件可怕的战利品带回瑟伯切尔交给高级执行官哈德瑞克，将巩固被遗忘者对银松森林的控制。",h="“图勒的头颅”是被遗忘者所要求的残酷证据，用以确认芬里斯岛上的天灾军团指挥官——图勒·鸦爪已经死亡。将这件可怕的战利品带回瑟伯切尔交给高级执行官哈德瑞克，将巩固被遗忘者对银松森林的控制。",kw={"芬里斯","哈德瑞克","死灵法师","鸦爪","天灾军团","瑟伯切尔","图勒"},ang={["faction:Horde"]="消灭图勒·鸦爪巩固了银松森林的东部边界，保护了新获得的部落领土免受天灾军团的入侵。",["race:Undead"]="对于被遗忘者而言，砍下图勒的头颅既是一场军事胜利，也是对巫妖王控制洛丹伦的个人复仇。"},sec={{t="芬里斯岛的战利品",b="芬里斯岛是巫妖王的天灾军团在银松森林的主要堡垒。死灵法师图勒·鸦爪在芬里斯城堡深处指挥着他的腐皮军团和亡灵爪牙，直接威胁着瑟伯切尔等被遗忘者的据点。高级执行官哈德瑞克要求绝对确认这位黑暗指挥官已经倒下，他拒绝接受任何除了图勒的头颅以外的证词。鸦爪死时爆发出的狂暴黑暗魔法在整片森林中都能感受到，但他的头颅依然是哈德瑞克宣布芬里斯岛被攻破所需的实质证据。"}},faq={{q="谁需要“图勒的头颅”？",a="高级执行官哈德瑞克是驻扎在银松森林瑟伯切尔的被遗忘者军事行动指挥官，他要求得到图勒的头颅以确认这位天灾军团首领已被消灭。",al={"谁需要图勒的头颅","谁上交了图勒的头颅","谁收走图勒的头颅"}},{q="图勒·鸦爪是谁？",a="图勒·鸦爪是一位强大的死灵法师，指挥着芬里斯岛上的天灾军团。他在芬里斯城堡中心策划对被遗忘者的袭击，并施展诸如“鸦爪妖术”之类的邪恶魔法。",al={"图勒背景故事","图勒是谁","图勒·鸦爪背景"}},{q="为什么被遗忘者一定要他的头颅？",a="被遗忘者无法承受银松森林中残留的天灾军团威胁。由于死灵法师以欺诈和黑暗复活手段而臭名昭著，高级执行官哈德瑞克只接受图勒已被彻底消灭的实质性、无可辩驳的证明。",al={"为什么需要图勒的头颅","为什么他们想要他的头颅"}},{q="图勒·鸦爪被杀后会发生什么？",a="图勒战败后，一股狂暴的死灵能量会辐射到整个地区，其威力之大，甚至让远在瑟伯切尔的被遗忘者学者和药剂师都能感受到那股魔法冲击波。",al={"图勒死后发生了什么","图勒释放的能量"}}},fp="12,217,21.435.1,23.154.0,24.198.0,49.197.0,43.167.1"}
P.entries["item:thunder-lizard-blood"] = {n="雷霆蜥蜴的血液",s="雷霆蜥蜴的血液是取自漫步在南贫瘠之地的巨型雷霆蜥蜴的生命精华。它是能够证明在卡利姆多某些最具压迫力的陆地野兽面前幸存下来的英勇战利品。",h="雷霆蜥蜴的血液是取自漫步在南贫瘠之地的巨型雷霆蜥蜴的生命精华。它是能够证明在卡利姆多某些最具压迫力的陆地野兽面前幸存下来的英勇战利品。",kw={"贫瘠之地","陶拉祖营地","乔恩·天视","风暴兽皮兽","风暴口鼻兽","雷霆蜥蜴的血液","雷霆兽"},ang={["class:Hunter"]="战胜一只雷霆蜥蜴需要稳健的站位和敏捷的反应；带回它们的血液证明了征服草原上最庞大野兽的实力。",["race:Tauren"]="对于从陶拉祖营地出发的牛头人猎人来说，对抗雷霆蜥蜴是与家园中这些可怕的巨人并存的一项传统生存考验。"},sec={{t="狩猎战利品",b="雷霆蜥蜴，在平原上也被称为风暴口鼻兽、风暴兽皮兽和雷霆兽，是巨大的野兽，它们沉重的脚步会让大地颤抖。狩猎它们是一场关于脚下危险的考验，因为它们惊人的体重可以轻易地压扁不留神的潜行者。带回它们的血液不仅证明了狩猎技巧，更体现了在它们雷霆般的足下幸存所需的超强耐力。"}},faq={{q="哪些生物会掉落这种血液？",a="这种血液是从漫步在南贫瘠之地陶拉祖营地周围草原上的成年雷霆蜥蜴身上采集的，特别是风暴口鼻兽、风暴兽皮兽和雷霆兽。",al={"谁掉落雷霆蜥蜴的血液","在哪里获得雷霆蜥蜴的血液","哪些雷霆蜥蜴"}},{q="为什么要搜寻雷霆蜥蜴的血液？",a="陶拉祖营地的乔恩·天视要求猎人们收集这些血液，作为贫瘠之地考验的一部分。完好无损地带回血液，证明了一名猎人有能力面对卡利姆多最庞大的踏地巨兽。",al={"谁需要雷霆蜥蜴的血液","雷霆蜥蜴的血液的用途"}},{q="这些雷霆蜥蜴通常在哪里出没？",a="它们漫步在陶拉祖营地北部、东部和南部的草原上，与南贫瘠之地的其他大型动物一起觅食。",al={"雷霆蜥蜴的位置","风暴口鼻兽在哪里"}}},fp="20,146,18.296.0,34.152.0,41.186.0,46.142.0"}
P.entries["item:thunder-lizard-horn"] = {n="雷霆蜥蜴的角",s="雷霆蜥蜴的角是一种坚硬的战利品，可以从徘徊在贫瘠之地的那些与闪电共鸣的巨大雷霆蜥蜴身上获取。棘齿城的酿酒师德罗恩正在寻找这种不同寻常的试剂，以重现传说中由陈·风暴烈酒最初调配出的佳酿。",h="雷霆蜥蜴的角是一种坚硬的战利品，可以从徘徊在贫瘠之地的那些与闪电共鸣的巨大雷霆蜥蜴身上获取。棘齿城的酿酒师德罗恩正在寻找这种不同寻常的试剂，以重现传说中由陈·风暴烈酒最初调配出的佳酿。",kw={"贫瘠之地","酿酒师德罗恩","陈·风暴烈酒","奥瓦坦卡","棘齿城","风暴鼻祖","风暴烈酒","雷霆蜥蜴的角","雷霆头领"},ang={["class:Hunter"]="在开阔的草原上追踪雷霆蜥蜴需要格外小心，因为它们天生的闪电放电能力使它们比普通的贫瘠之地科多兽或平原陆行鸟致命得多。",["profession:Cooking"]="烹饪冒险家们经常对酿酒师德罗恩那不同寻常的配方感到惊奇，他将平原陆行鸟的器官、捕食者的獠牙和野兽的角结合在一起，酿造出一种醉人的饮品。"},sec={{t="强力的酿造试剂",b="雷霆蜥蜴漫步在贫瘠之地干燥的平原上，它们长着冠状突起的身体上闪烁着原始而局部的电弧。虽然猎人们偶尔会寻找它们厚实的皮革，但棘齿城的酿酒师德罗恩却出于完全不同的目的而珍视它们的角。这份风暴烈酒的配方是由一位从云游四方的熊猫人酿酒大师陈·风暴烈酒那里学到技艺的导师传下来的，它需要用到一些不同寻常且强力的本地材料。雷霆蜥蜴的角能为这种传奇饮品提供令人触电般的刺激感，赋予其火热且令人难忘的口感。"}},faq={{q="这种角有什么用？",a="这种角被棘齿城的酿酒师德罗恩用作重现陈·风暴烈酒那款以其名命名的著名佳酿的必备材料，该酒以其强劲的后劲而闻名。",al={"雷霆蜥蜴的角用途","什么东西需要雷霆蜥蜴的角","为什么需要雷霆蜥蜴的角"}},{q="哪种野兽会掉落雷霆蜥蜴的角？",a="贫瘠之地各处的雷霆蜥蜴品种都会掉落这种角，包括雷霆头领、风暴鼻祖、雷霆践踏者、风暴外壳，以及难以捉摸的野兽奥瓦坦卡。",al={"在哪里获得雷霆蜥蜴的角","谁掉落雷霆蜥蜴的角","雷霆蜥蜴的角来源"}},{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩是一位在地精港口棘齿城经营的酿酒师。他以前的导师曾直接从著名的云游者陈·风暴烈酒那里学到了风暴烈酒的配方，并将其传授给了他。",al={"德罗恩是谁","酿酒师德罗恩背景故事","德罗恩 棘齿城"}},{q="猎取雷霆蜥蜴的角有危险吗？",a="雷霆蜥蜴是强大的野兽，被激怒时会自然释放闪电并发出雷鸣般的践踏，这使得对于孤身旅行者来说，获取它们的角是一项危险的任务。",al={"雷霆蜥蜴有多强","狩猎雷霆蜥蜴"}}},fp="19,98,24.320.0,26.99.0,41.111.0,24.130.0,54.121.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="雷鹰的唾液腺",s="雷鹰的唾液腺是一种强效的生物试剂，可以从翱翔于贫瘠之地的大雷鹰身上获取。棘齿城的酿酒师德罗恩将其视为酿造陈·风暴烈酒那烈性穴居人麦酒必不可少的原料。",h="雷鹰的唾液腺是一种强效的生物试剂，可以从翱翔于贫瘠之地的大雷鹰身上获取。棘齿城的酿酒师德罗恩将其视为酿造陈·风暴烈酒那烈性穴居人麦酒必不可少的原料。",kw={"贫瘠之地","德罗恩","腺体","小桶","棘齿城","唾液","雷鹰","穴居人麦酒"},ang={["faction:Horde"]="在贫瘠之地猎杀凶猛的雷鹰，是年轻的战士穿越卡利姆多时的试炼场。",["profession:Cooking"]="烹饪纯粹主义者可能会对使用唾液腺感到皱眉，但富有创造力的酿酒师却将这些奇特的动物精华视为获得无与伦比的风味和功效的关键捷径。"},sec={{t="狂野的原料",b="贫瘠之地的干旱草原是雷鹰的家园，这种长着翅膀的蛇类以能驾驭风暴而闻名。在它们的种群中，年长且更危险的大雷鹰会产生一种蕴含原始自然力量的唾液腺。普通旅人通常会避开这些致命的野兽，但经验丰富的酿酒师却能看出这种器官作为异域风味配方绝佳基底的稀有特性。"},{t="陈的秘方",b="随着传奇的游学者酿酒大师陈·风暴烈酒在卡利姆多的游历，酿酒师德罗恩在棘齿城外定居下来，潜心钻研这位熊猫人的精妙酿造技术。德罗恩需要新鲜的雷鹰的唾液腺，辅以风暴兽的闪电腺和科多兽的肝脏，才能酿造出穴居人麦酒。这种烈酒口感火辣，能给坚韧的冒险者带来无比的提神效果。"}},faq={{q="在哪里可以找到雷鹰的唾液腺？",a="它们是从在贫瘠之地的开阔草原上捕猎的大雷鹰身上采集到的。",al={"雷鹰的唾液腺掉落","哪里可以获得唾液腺","雷鹰腺体位置"}},{q="唾液腺有什么用途？",a="它被送到棘齿城外的酿酒师德罗恩那里，作为酿造穴居人麦酒的关键材料，这是一份陈·风暴烈酒留下的强效配方。",al={"唾液腺用途","雷鹰的唾液腺是用来做什么的","雷鹰的唾液用途"}},{q="酿酒师德罗恩是谁？",a="德罗恩是一位居住在棘齿城港口附近的酿酒师。他从游历者陈·风暴烈酒那里学到了异域酿造艺术，并用强效麦酒与愿意为了食材而挑战当地野生动物的冒险者们进行交易。",al={"德罗恩 棘齿城","德罗恩是谁","酿酒师德罗恩背景故事"}},{q="什么是穴居人麦酒？",a="穴居人麦酒是由陈·风暴烈酒构思的一种烈性饮品。酿酒师德罗恩通过将大雷鹰的唾液腺、闪电腺和科多兽的肝脏混合在一起，酿造出这种提神的酒液。",al={"穴居人麦酒背景故事","什么是穴居人麦酒","陈的穴居人麦酒"}}},fp="24,141,17.312.0,21.342.0,45.111.0,34.112.0,24.195.0,18.166.0"}
P.entries["item:thunderhawk-wings"] = {n="雷鹰的翅膀",s="雷鹰的翅膀是从盘旋在贫瘠之地中部和南部上空的凶猛风蛇身上取下的带羽毛战利品。将其交给陶拉祖营地的乔恩·天空之眼，它们就成了证明猎人在追踪这片稀树草原最雄伟的掠食者之一时所展现出的力量、狡黠和耐力的确凿证据。",h="雷鹰的翅膀是从盘旋在贫瘠之地中部和南部上空的凶猛风蛇身上取下的带羽毛战利品。将其交给陶拉祖营地的乔恩·天空之眼，它们就成了证明猎人在追踪这片稀树草原最雄伟的掠食者之一时所展现出的力量、狡黠和耐力的确凿证据。",kw={"贫瘠之地","陶拉祖营地","乔恩·天空之眼","塞格拉·黑棘","雷鹰","风蛇","翅膀"},ang={["class:Hunter"]="夺取翱翔的雷鹰的翅膀代表了一种通过仪式，证明了你面对敏捷的空中野兽时的追踪能力、耐心和枪法。",["race:Tauren"]="对于陶拉祖的猎人们来说，采集这些翅膀是对稀树草原之灵的致敬，也展现了对大地母亲的凶猛生物的尊重。"},sec={{t="狩猎战利品",b="风蛇，也就是当地猎人口中的雷鹰，是能够从空中迅速发动攻击的强悍带翼爬行动物。对于驻扎在陶拉祖营地的猎人们来说，采集一对完整的雷鹰的翅膀远不止是收集生物残骸；它代表着在贫瘠之地进行的艰苦狩猎试炼的巅峰。通过在广阔的平原上追踪这些空中掠食者并在战斗中夺取它们的翅膀，新兵证明了自己已做好准备踏上一位资深猎人的终身之路。"}},faq={{q="雷鹰的翅膀在哪里可以找到？",a="雷鹰的翅膀是从在贫瘠之地中部和南部的山脊和平原上滑翔的雷鹰身上采集的，特别是在陶拉祖营地周围的土地上。",al={"如何获得翅膀","雷鹰的翅膀位置","如何获取雷鹰的翅膀"}},{q="谁需要这些翅膀？",a="驻扎在陶拉祖营地的资深牛头人猎人乔恩·天空之眼，要求获得这些翅膀作为新兵已掌握稀树草原狩猎仪式的证明。",al={"谁需要雷鹰的翅膀","上交雷鹰的翅膀","乔恩·天空之眼 翅膀"}},{q="夺取翅膀意味着什么？",a="将翅膀带回给乔恩·天空之眼标志着一项充满挑战的通过仪式的完成，确认了猎人拥有面对顶级空中掠食者所需的力量、勇气和耐心。",al={"为什么要猎杀雷鹰","翅膀的用途","雷鹰狩猎的意义"}}},fp="17,218,18.398.0,34.145.0,22.154.0,37.168.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="雷角之井净化图腾",s="雷角之井净化图腾是穆尔·雷角在血蹄村制作的一件神圣仪式法器。它被注入了先祖魔法，用于净化雷角水井中被腐化的水。",h="雷角之井净化图腾是穆尔·雷角在血蹄村制作的一件神圣仪式法器。它被注入了先祖魔法，用于净化雷角水井中被腐化的水。",kw={"血蹄","净化","莫高雷","穆尔","仪式","雷角","图腾","水井"},ang={["class:Shaman"]="萨满祭司明白，净化图腾是安抚不安的自然之灵并恢复元素能量失衡之地的媒介。",["race:Tauren"]="对于牛头人而言，净化先祖水井不仅仅是一项杂务，更是对地球母亲以及守护着莫高雷的氏族先祖们的神圣职责。"},sec={{t="净化雷角水井",b="在莫高雷的草海平原上，大地的命脉正受到某种不可见的腐蚀之力的侵扰。牛头人部落挖掘的先祖水井为兽群和狩猎场提供了至关重要的滋养，但邪恶的势力玷污了这些水源。受长者穆尔·雷角的委托，冒险者携带着这件制备好的图腾前往血蹄村的北方，驱逐笼罩在雷角氏族圣泉上的污秽。通过仪式的召唤，图腾平息了不安的水元素之灵，并净化了这片先祖之地。"}},faq={{q="雷角之井净化图腾的用途是什么？",a="该图腾是专门为净化雷角水井中被腐化的水而准备的，水井位于血蹄村以北。使用它可以驱散污染水井的邪恶力量，并安抚守护水井的先祖之魂。",al={"图腾的作用","为什么要使用雷角图腾","净化图腾的目的"}},{q="谁制作了该图腾？",a="该图腾由穆尔·雷角制作并授予，他是一位居住在血蹄村的长者，负责守护大地的健康并与先祖沟通。",al={"谁制作了该图腾","谁提供了雷角图腾","穆尔·雷角的图腾"}},{q="必须在何处使用该图腾？",a="该图腾必须直接在雷角水井处使用，水井位于莫高雷中部，血蹄村以北。",al={"在哪里使用图腾","图腾位置","雷角水井在哪里"}},{q="仪式完成后会发生什么？",a="净化水井能为雷角氏族的先祖之魂带来安宁。穆尔·雷角会在梦中获得先祖感激的幻象，并向净化了这片土地的人给予赞赏和先祖的馈赠。",al={"净化水井之后","仪式结果","先祖的反应"}}},fp="27,155,30.362.0,55.202.0,22.158.0,29.91.0,43.188.1"}
P.entries["item:thurman-s-remains"] = {n="萨尔曼的遗骸",s="萨尔曼的遗骸是萨尔曼·阿加曼德的肉身残骸，从提瑞斯法林地北部的家族破败磨坊中寻回。萨尔曼曾是一位富有的磨坊主，他曾说服工人反抗天灾军团，但最终还是死于瘟疫，并作为一名亡灵奴仆在他曾经的庄园中徘徊。",h="萨尔曼的遗骸是萨尔曼·阿加曼德的肉身残骸，从提瑞斯法林地北部的家族破败磨坊中寻回。萨尔曼曾是一位富有的磨坊主，他曾说服工人反抗天灾军团，但最终还是死于瘟疫，并作为一名亡灵奴仆在他曾经的庄园中徘徊。",kw={"阿加曼德","阿加曼德磨坊","库勒曼·法席恩","家族死亡","萨尔曼·阿加曼德","萨尔曼的遗骸","提瑞斯法林地"},ang={["race:Undead"]="对于被遗忘者来说，回收这些遗骸是对那些傲慢的贵族主人们的一笔残酷清算，正是他们的傲慢将劳工们直接推向了天灾军团的魔爪。"},sec={{t="毁灭的遗产",b="第三次战争前，阿加曼德家族是提瑞斯法林地最富有的地主，经营着大型磨坊并雇佣了数十名当地工人。当天灾军团席卷洛丹伦时，萨尔曼·阿加曼德和他的亲属固守庄园，而非选择逃离。他们坚信自己的财富和坚固的磨坊足以抵御猛攻，于是说服忠诚的劳工与他们并肩作战。然而防御彻底失败了，阿加曼德家族和他们的工人都被屠杀，并被转化为巫妖王的无脑仆从。如今，库勒曼·法席恩——一名已复活为被遗忘者的前雇员——要求摧毁他曾经的主人，并寻求萨尔曼的遗骸，以此证明这位愚蠢的族长已为他害死全家人的行为付出了代价。"}},faq={{q="萨尔曼·阿加曼德是谁？",a="萨尔曼·阿加曼德是富有的阿加曼德家族的重要成员，该家族拥有位于提瑞斯法林地北部的阿加曼德磨坊。当天灾军团袭击洛丹伦时，他的傲慢导致他劝说劳工留下战斗，这一选择最终导致庄园内的所有人被屠杀并复活成了亡灵。",al={"萨尔曼·阿加曼德","萨尔曼是谁","萨尔曼曾是谁"}},{q="库勒曼·法席恩为什么要萨尔曼的遗骸？",a="库勒曼·法席恩曾是一名磨坊工人，他信任阿加曼德家族，并死于保卫其庄园的战斗中。现在作为一名被遗忘者，库勒曼对曾经的主人怀有深深的怨恨，因为他们将劳工推向了不死之路，他寻求萨尔曼的遗骸是为了复仇。",al={"为什么库勒曼想要遗骸","库勒曼·法席恩的动机","为什么要杀死萨尔曼"}},{q="萨尔曼被消灭时拥有自由意志吗？",a="没有。与幽暗城的被遗忘者不同，萨尔曼·阿加曼德死后仍处于天灾军团的精神控制之下，一直作为一名行尸走肉般的爪牙，直到在磨坊被消灭。",al={"萨尔曼有自由意志吗","萨尔曼是天灾军团吗","萨尔曼是被遗忘者吗"}},{q="还有哪些阿加曼德家族成员被列为目标？",a="除了萨尔曼之外，库勒曼·法席恩还寻求消灭并回收格雷戈尔·阿加曼德和尼萨·阿加曼德的遗骸，以终结这个曾经统治磨坊的血脉。",al={"其他的阿加曼德成员","阿加曼德家族成员","家族死亡任务目标"}}},fp="17,200,16.686.0,24.264.0,49.216.0,49.189.0,51.169.0"}
P.entries["item:thurman-s-sewing-kit"] = {n="萨尔曼的针线包",s="萨尔曼的针线包是一个小袋子，里面装着暴风城一名裁缝学徒所需的针和剪刀。这东西属于萨尔曼·斯涅德，他为了逃避漫长而枯燥的裁缝工作，特意把它留在了家里运河边的房子里。",h="萨尔曼的针线包是一个小袋子，里面装着暴风城一名裁缝学徒所需的针和剪刀。这东西属于萨尔曼·斯涅德，他为了逃避漫长而枯燥的裁缝工作，特意把它留在了家里运河边的房子里。",kw={"裁缝店","mage quarter","雷玛·施涅德","针线包","暴风城运河","萨尔曼·斯涅德","萨尔曼的针线包"},ang={["profession:Tailoring"]="每一位裁缝都记得学徒初期的枯燥艰辛，但很少有人像年轻的萨尔曼·斯涅德那样，为了逃避工作而把剪刀“弄丢”。"},sec={{t="不情愿的学徒工具",b="这个针线包里装着一名裁缝学徒的日常工具：针、剪刀和线。它属于年轻的萨尔曼·斯涅德，他在暴风城法师区的法师塔附近的一家裁缝店学习裁缝手艺。雷玛·施涅德知道她儿子没有这些工具就无法完成工作，于是请求运河旁好心的路人把针线包送到店里。萨尔曼收到工具后的反应表明，他把剪刀和针忘在家里绝非偶然，而是为了偷懒而蓄意策划的一次失败的逃避劳动的尝试。"}},faq={{q="萨尔曼的针线包里有什么？",a="这个包里装着裁缝工作所需的必备工具，主要是剪刀和针。萨尔曼·斯涅德需要这些工具来完成他在裁缝店的日常学徒任务。",al={"包里有什么","针线包内容物","萨尔曼的剪刀"}},{q="这个针线包属于谁？",a="它属于萨尔曼·斯涅德，一名在暴风城法师区工作的年轻学徒。",al={"谁拥有这个包","萨尔曼的物品","萨尔曼是谁"}},{q="为什么针线包被落在了萨尔曼的家里？",a="虽然他的母亲雷玛认为他是出门匆忙才落下的，但萨尔曼其实是故意把针线包留在家里，希望没有工具就能以此为借口逃避当天的裁缝店杂务。",al={"萨尔曼为什么忘了带包","萨尔曼是故意忘记的吗","为什么要留下针线包"}},{q="这个包需要送到哪里？",a="必须把它送到裁缝店，那是一家位于暴风城法师区深处，靠近法师塔的店铺。",al={"我该把包送到哪去","裁缝店位置","萨尔曼的位置"}}},fp="20,191,30.450.0,36.101.0,35.124.0,46.139.0,41.87.0"}
P.entries["item:timberling-seed"] = {n="林精的种子",s="林精的种子是从泰达希尔那些焦躁不安的植物元素生物身上采集到的植物内核。博物学家和德鲁伊们研究这些种子，试图找出森林中的植物生命变得异常具有攻击性的原因。",h="林精的种子是从泰达希尔那些焦躁不安的植物元素生物身上采集到的植物内核。博物学家和德鲁伊们研究这些种子，试图找出森林中的植物生命变得异常具有攻击性的原因。",kw={"腐蚀","达纳苏斯","德纳兰","奥拉密斯湖","雷利亚·绿火","泰达希尔","林精","林精的种子"},ang={["class:Druid"]="受污染的种子发出了早期预警信号，表明某种非自然的腐蚀正在泰达希尔的植物元素生物中蔓延，这对塞纳里奥区的保护者来说是一个至关重要的问题。",["profession:Herbalism"]="对于植物学家和草药采集者来说，研究这些种子突显了土壤条件和环境腐蚀对野生植物群落的巨大影响。"},sec={{t="躁动森林的种子",b="泰达希尔的林精是自然元素生物，它们的性情反映了世界之树的平衡。最近，这些生物变得具有敌意且暴躁，困扰着照料树枝的暗夜精灵。像奥拉密斯湖的德纳兰那样的草药师认为问题出在土壤里，于是他们从野生林精身上收集种子，希望能通过在受控的、纯净的环境中培育它们，长出温顺的后代。"},{t="根源性的腐蚀",b="培育温顺林精的努力面临着严峻的现实。当达纳苏斯的塞纳里奥区学者，例如雷利亚·绿火（Rellian Greenspyre），检查这些样本种子时，更深层的问题浮现出来。这些种子携带了其被腐蚀的亲本的污秽，这表明泰达希尔的植物之灵的不安不仅仅是因为生长不良，而是一种正在这棵伟大之树的生态系统中蔓延的深层腐蚀。"}},faq={{q="什么是林精的种子？",a="林精的种子是林精的繁殖内核。林精是一种在泰达希尔各地都能发现的类植物自然元素生物。博物学家们收集这些种子来研究林精的生长和生态。",al={"林精的种子","什么是林精的种子"}},{q="这些种子是在哪里收集的？",a="它们是从在泰达希尔奥拉密斯湖岸边和浅滩游荡的野生林精和沼泽兽身上收集的。",al={"去哪里获取种子","林精的种子掉落","谁掉落林精的种子"}},{q="为什么德纳兰想要林精的种子？",a="德纳兰怀疑是由于土壤不适导致林精变得狂暴。他希望能将这些野生种子种植在特制的土壤中，看看是否能培育出温顺、未受腐蚀的林精。",al={"德纳兰的目的","为什么要收集种子","德纳兰的计划"}},{q="雷利亚·绿火对这些种子有什么发现？",a="雷利亚发现林精体内已经扎下了腐蚀的根，且种子携带了其亲本的污秽。他发现自己无力净化这些种子，只能寄希望于德纳兰的园艺实验。",al={"雷利亚的种子研究","雷利亚发现了什么","种子受污染了吗"}}},fp="15,186,26.382.0,19.283.1,26.185.0,31.97.0,39.160.0,54.173.1"}
P.entries["item:timberling-sprout"] = {n="林精的新芽",s="林精的新芽是泰达希尔奥拉密斯湖岸边扎根的年幼、初生的植物元素。即便是处于生长的初期，这些新芽也表现出了腐蚀的迹象，促使暗夜精灵守望者在它们成长为好斗的林精之前将其拔除。",h="林精的新芽是泰达希尔奥拉密斯湖岸边扎根的年幼、初生的植物元素。即便是处于生长的初期，这些新芽也表现出了腐蚀的迹象，促使暗夜精灵守望者在它们成长为好斗的林精之前将其拔除。",kw={"奥达希尔","腐蚀","奥拉密斯湖","幽影谷","泰达希尔","林精","林精的新芽"},ang={["class:Druid"]="对于那些与卡利姆多的植物生命和元素协调一致的德鲁伊来说，看到自然的林地之灵从土壤中萌发时就已经被腐蚀，这是泰达希尔未来的一个不祥之兆。",["race:NightElf"]="在幽影谷开始训练的年轻暗夜精灵的任务就是清除这些新芽，以保护他们新的林地家园。"},sec={{t="枯萎的幼苗",b="林精是与泰达希尔自然生命力紧密相连的植物之灵，但沿奥拉密斯湖生长出的幼苗却令当地的暗夜精灵感到担忧。它们并没有健康地生长并与荒野和谐共存，而是从萌芽开始就已受到腐蚀并具有攻击性。由于这些幼小的新芽似乎无法被净化或自然治愈，奥拉密斯湖的看护者必须将它们收集并摧毁，以防止敌对的林精在新种植的世界之树脆弱的枝桠上不受控制地蔓延。"}},faq={{q="林精的新芽在哪里可以找到？",a="林精的新芽生长在泰达希尔多兰纳尔以南，奥拉密斯湖岸边的水际附近。",al={"新芽位置","林精的新芽在哪里","寻找新芽"}},{q="为什么暗夜精灵要将林精的新芽从地里拔出来？",a="这些新芽从一开始萌发时就是被腐蚀的。如果不加抑制，它们会成长为威胁泰达希尔安全与平衡的暴力林精。因为它们被认为已无法挽救，看护者们趁它们还小时就将其清除。",al={"为什么要杀死新芽","林精的新芽用途","为什么要摧毁新芽"}},{q="是什么导致新芽受到腐蚀？",a="一种神秘的疾病已经开始影响泰达希尔的野生动物和植物元素。虽然腐蚀的确切来源对植物学家德纳兰来说仍是一个未解之谜，但它从幼年林精扎根的那一刻起就对其产生了影响。",al={"为什么林精被腐蚀了","是什么在腐蚀它们","新芽疾病"}},{q="是谁要求收集林精的新芽？",a="照料奥拉密斯湖的植物学家德纳兰要求冒险者收集并清除湖畔的新芽，以保持土地的纯净。",al={"谁想要新芽","新芽任务发布者","林精的新芽交任务"}}},fp="17,154,18.420.0,35.99.0,63.206.0,46.185.0,48.139.0"}
P.entries["item:tirisfal-pumpkin"] = {n="提瑞斯法南瓜",s="提瑞斯法南瓜生长在索利丹农场的耕地里，由那些在被瘟疫侵蚀的林地中苦苦求生的幸存人类照料。被遗忘者经常突袭这些田地，为皇家药剂师学会提供用于其化学混合物的有机材料。",h="提瑞斯法南瓜生长在索利丹农场的耕地里，由那些在被瘟疫侵蚀的林地中苦苦求生的幸存人类照料。被遗忘者经常突袭这些田地，为皇家药剂师学会提供用于其化学混合物的有机材料。",kw={"药剂师乔汉","布瑞尔","亡灵卫兵希米尔","悲伤之田","南瓜","试剂","索利丹农场","提瑞斯法南瓜"},ang={["faction:Alliance"]="索利丹农场种植的南瓜代表了洛丹伦幸存民众在被遗忘者不断入侵的情况下，为养活自己而做出的绝望努力。",["race:Undead"]="袭击索利丹农场有双重目的：既剥夺了剩余活人的食物，又为药剂师乔汉提供了用于被遗忘者黑暗研究的实验材料。"},sec={{t="瘟疫之地的收成",b="尽管洛丹伦被腐蚀所笼罩，但布瑞尔以西的田野里依然长出了庄稼。在索利丹农场，活着的人类农夫坚守着他们的土地，在附近的血色十字军的严密守卫下，种植着巨大的橙色南瓜。对于这些凡人来说，收获是维持生命的必需品。然而，对于附近布瑞尔的被遗忘者来说，这些南瓜既是破坏发泄的目标，也是药剂师乔汉进行实验所需的原始有机试剂。"},{t="药剂师试剂",b="亡灵卫兵希米尔指派年轻的被遗忘者潜入这些充满争夺的田地，在农夫眼皮底下偷取南瓜。这些蔬菜并非用来喂养亡灵，而是被送进了皇家药剂师学会沸腾的坩埚里。药剂师们经常测试自然植物如何对他们的瘟疫和实验性药剂产生反应，从而将洛丹伦仅存的农作物转化为对付活人的武器。"}},faq={{q="在哪里可以找到提瑞斯法南瓜？",a="它们生长在提瑞斯法林地的索利丹农场里，位于布瑞尔以西、丧钟镇以北。",al={"南瓜位置","哪里有南瓜","索利丹农场南瓜"}},{q="为什么被遗忘者想要这些南瓜？",a="亡灵卫兵希米尔下令偷取这些南瓜，一方面是为了剥夺幸存人类和血色十字军的资源，另一方面是将其作为原始有机试剂送往布瑞尔交给药剂师乔汉，用于药剂研究。",al={"为什么偷南瓜","乔汉南瓜","南瓜的用途"}},{q="玩家可以食用或用提瑞斯法南瓜烹饪吗？",a="不能。它们被严格收集为皇家药剂师学会的任务试剂，对冒险者没有任何烹饪用途。",al={"提瑞斯法南瓜可以吃吗","南瓜烹饪材料"}},{q="目前是谁在种植它们？",a="活着的人类农夫仍在索利丹农场耕种，并受到驻扎在附近哨塔的血色十字军的松散保护。",al={"谁拥有农场","索利丹农夫"}}},fp="16,148,26.356.0,19.346.0,37.95.0,42.196.0,47.108.0,30.134.0"}
P.entries["item:token-of-thievery"] = {n="偷窃技能证明物",s="偷窃技能证明物是新手盗贼在赤脊山训练期间获取的一项技能证明。它被放置在奥瑟尔伐木场一个受兽人威胁的锁住的行李箱内，是经验丰富的盗贼卢修斯设置的最终测试，旨在展示开锁技巧的精通程度。",h="偷窃技能证明物是新手盗贼在赤脊山训练期间获取的一项技能证明。它被放置在奥瑟尔伐木场一个受兽人威胁的锁住的行李箱内，是经验丰富的盗贼卢修斯设置的最终测试，旨在展示开锁技巧的精通程度。",kw={"奥瑟尔伐木场","偷窃技能认证书","湖畔镇","开锁","卢修斯","赤脊山","盗贼工具","偷窃技能证明物"},ang={["class:Rogue"]="偷窃技能证明物标志着联盟盗贼一个关键的成年仪式，证明他们能够有效地使用开锁工具，同时在敌军巡逻的废墟中避免被发现。"},sec={{t="技巧的试炼",b="并非每个无赖都天生具有摆弄锁芯和悄无声息地解开锁扣的天赋。在湖畔镇，盗贼导师卢修斯通过在实地测试他们的智慧和工具，对有前途的特工进行严格训练。卢修斯并没有将他的试炼局限于安静的小巷，而是将偷窃技能证明物藏在奥瑟尔伐木场废墟中一个坚固的锁箱里，那里正处于黑石兽人入侵的必经之路上。取回证明物证明了初学者可以在致命危险的压力下开启一个安全装置，从而获得他们正式的偷窃技能认证书。"}},faq={{q="什么是偷窃技能证明物？",a="这是一个由卢修斯锁在奥瑟尔伐木场的教学证明物。盗贼初学者必须打开他箱子上的锁才能将其取回，证明他们已经掌握了在危险条件下开锁所需的技巧。",al={"偷窃技能证明物用途","什么是偷窃技能证明物","卢修斯的证明物"}},{q="谁把证明物放进锁箱的？",a="卢修斯，一位在湖畔镇活动的经验丰富的盗贼导师，将其作为他为年轻盗贼制定的长期培训计划的一部分放置在那里。",al={"谁拥有证明物","卢修斯的锁箱所有者","谁藏了证明物"}},{q="为什么箱子被放在奥瑟尔伐木场？",a="奥瑟尔伐木场位于湖畔镇上方，由于黑石兽人的出没，那里已经变成了一个危险区域。卢修斯利用这个地点让他的学员学会如何在穿过敌对领地时快速且安静地进行开锁。",al={"为什么选奥瑟尔伐木场","伐木场锁箱的原因","伐木场的危险"}},{q="用证明物可以换取什么？",a="将证明物交给卢修斯，盗贼就能获得他们的偷窃技能认证书，以承认他们完成了开锁的基础训练。",al={"证明物奖励","卢修斯会给你什么","偷窃技能认证书"}}},fp="17,174,17.303.0,30.138.0,34.124.0,41.177.0,46.126.0"}
P.entries["item:tome-of-the-cabal-quest-item"] = {n="Tome of the Cabal (quest item)",s="“卡巴尔法典”是一本由斯坦哈德·法尔杉在俯瞰棘齿城的悬崖上交给术士的魔法书。它记载了将饥饿的邪犬从扭曲虚空中拉出，并将其束缚在召唤者意志之下的危险咒语。",h="“卡巴尔法典”是一本由斯坦哈德·法尔杉在俯瞰棘齿城的悬崖上交给术士的魔法书。它记载了将饥饿的邪犬从扭曲虚空中拉出，并将其束缚在召唤者意志之下的危险咒语。",kw={"邪犬","棘齿城","斯坦哈德·法尔杉","召唤法阵","束缚","卡巴尔法典"},ang={["class:Warlock"]="每一位寻求驾驭恶魔魔法的黑暗艺术修行者，都必须掌握这本法典才能获得他们的邪犬同伴。"},sec={{t="通往虚空之门",b="邪犬是原产于混乱的扭曲虚空的凶残、吞噬法力的野兽。征服一头邪犬是资深术士的成人礼，而撕开通往这种野兽的路径所需的仪式都记载在《卡巴尔法典》的页面中。在棘齿城活动的经验丰富的施法者斯坦哈德·法尔杉，只有在学徒证明自己有能力收集驱动其魔法所需的稀有且危险的材料后，才会提供这本书。"},{t="召唤仪式",b="使用法典进行召唤绝非个人的努力。斯坦哈德在他的圣所内建立了主要的召唤法阵，而他的侍僧则使用引导法杖构建了一个更大的防护结界。术士随后必须诵读法典中精确的咒语将邪犬拖入我们的世界，并立即与这头饥饿的恶魔战斗并将其制服，以巩固对其的统治。"}},faq={{q="《卡巴尔法典》有什么用途？",a="这本法典包含了从扭曲虚空将一头邪犬召唤到棘齿城内一个特制法阵中所必需的仪式咒语，使术士能够面对并束缚这只恶魔。",al={"卡巴尔法典的作用","卡巴尔法典的用途","法典 邪犬"}},{q="谁提供了《卡巴尔法典》？",a="居住在贫瘠之地棘齿城上方山丘中的术士导师斯坦哈德·法尔杉，会在修行者完成艰巨的准备工作后提供这本书。",al={"谁提供卡巴尔法典","在哪里获得卡巴尔法典","斯坦哈德 书"}},{q="完成仪式后，你可以保留这本法典吗？",a="不可以。一旦召唤出来的邪犬被击败，并且证明了你的掌握能力，你就必须将《卡巴尔法典》归还给斯坦哈德·法尔杉，作为你成功的证明。",al={"我可以保留这本书吗","卡巴尔法典奖励","保留卡巴尔法典"}},{q="你可以在世界上的任何地方召唤邪犬吗？",a="不可以。咒语必须在棘齿城上方斯坦哈德·法尔杉的圣所内诵读，在那里，他和他的侍僧维持着邪犬降临时所需的更大和较小的召唤法阵以将其禁锢。",al={"在任何地方召唤邪犬","在哪里阅读法典","法典仪式地点"}}},fp="30,206,23.376.0,20.323.0,39.175.0,35.157.0,49.145.0,51.193.0"}
P.entries["item:top-of-gelkak-s-key"] = {n="基尔卡克钥匙的头部",s="基尔卡克钥匙的头部是机械钥匙的三块碎片之一，这把钥匙属于遭遇海难的侏儒基尔卡克·旋杆。在他的船于黑海岸附近失事后，这块锯齿状的黄铜部件被附近森林中游荡的一头巨型陆行鸟叼走了。",h="基尔卡克钥匙的头部是机械钥匙的三块碎片之一，这把钥匙属于遭遇海难的侏儒基尔卡克·旋杆。在他的船于黑海岸附近失事后，这块锯齿状的黄铜部件被附近森林中游荡的一头巨型陆行鸟叼走了。",kw={"黑海岸","大副","陆行鸟","基尔卡克","旋杆","钥匙","海盗","寻回"},ang={["profession:Engineering"]="这把钥匙旨在给发条自动装置上发条并激活它，展现了侏儒工匠典型的巧妙且坚固的机械工艺。",["race:Gnome"]="看到一位侏儒同胞凭借纯粹的古怪个性和发条装置在灾难性的海难中幸存下来，是一种既熟悉又令人心生好感的景象。"},sec={{t="破碎的机关",b="当基尔卡克·旋杆的船在黑海岸附近遭到贪婪的利齿鱼袭击并沉没时，这位侏儒被冲上岸，手中紧紧抓着为他的机械大副准备的上发条钥匙。海难的撞击使得这件仪器碎成了三段。还没等这位晕头转向的海盗回过神来，当地的野兽就开始在残骸中搜寻，其中一头巨型陆行鸟叼着这个华丽的顶部部件跑进了迷雾森林。"},{t="修复大副",b="这把钥匙对于给基尔卡克的机械大副上发条并激活它至关重要，这位困在岛上的侏儒打算利用这个自动装置向当地的野生动物复仇。找回这个碎片，再加上被岸边的鱼人和礁石蟹偷走的中部和底部，旋杆就能把装置重新组装起来，并让他的构装体活过来。"}},faq={{q="基尔卡克钥匙的头部有什么用？",a="它是遭遇海难的侏儒海盗基尔卡克·旋杆修复他机械发条钥匙所需的三个破碎部件之一。一旦组装完成，这把钥匙将被用于重新激活他的机械大副。",al={"基尔卡克钥匙的作用","基尔卡克钥匙的头部用途","基尔卡克钥匙的目标"}},{q="陆行鸟是怎么得到这把钥匙的碎片的？",a="当基尔卡克遭遇海难并被冲上黑海岸的海滩时，他的钥匙在岩石上撞碎了。好奇的野兽立即在残骸中翻找，一头巨型陆行鸟吞下或叼走了这个黄铜制成的顶部部件，并把它带到了海岸东北方向的森林里。",al={"为什么陆行鸟有这把钥匙","谁拿走了基尔卡克钥匙的头部","陆行鸟如何获得钥匙"}},{q="钥匙的其他部分在哪里？",a="中部碎片被附近沉船处的灰雾鱼人抢走了，而底部碎片则被在潮汐线觅食的螃蟹带走了。",al={"钥匙的其他部分在哪里","基尔卡克钥匙的中部和底部","基尔卡克钥匙碎片"}},{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是一位古怪的侏儒海盗，在利齿鱼撞沉了他的船后，他发现自己被困在了黑海岸的岸边。他孤身一人，满腔怒火，正密谋向海岸上的生物复仇。",al={"基尔卡克是谁","基尔卡克·旋杆背景故事"}}},fp="19,189,21.376.0,24.303.1,41.179.0,50.201.0,38.126.0,23.163.0"}
P.entries["item:torch-of-the-dormant-flame"] = {n="眠炎火炬",s="眠炎火炬是年轻的部落萨满在杜隆塔尔与火焰交流时所携带的仪式器具。在山顶击败火焰显灵后，它将作为容器，用以在眠炎圣殿捕获原始的元素之火。",h="眠炎火炬是年轻的部落萨满在杜隆塔尔与火焰交流时所携带的仪式器具。在山顶击败火焰显灵后，它将作为容器，用以在眠炎圣殿捕获原始的元素之火。",kw={"call of fire","杜隆塔尔","火焰灵契","萨满","眠炎圣殿","泰尔夫·祖拉姆","眠炎火炬"},ang={["class:Shaman"]="这支沉睡的火炬代表了试炼者未受考验的状态；只有通过征服活生生的火焰显灵，萨满才能点燃它，并获得召唤火焰图腾的权利。"},sec={{t="觉醒之器",b="寻求火焰青睐的萨满在攀登杜隆塔尔山峰前会被授予一支未点燃的眠炎火炬。在喝下揭示灵魂的火焰灵契后，萨满会看到并挑战山顶上的火焰次级显灵。击杀这个元素之灵会获得一枚余烬，将其放入眠炎圣殿风化的火盆中。用沉睡火炬的头部接触由此产生的炽热大火，便能唤醒木材，将其转化为元素掌控的燃烧象征。"}},faq={{q="眠炎火炬有什么用途？",a="这是一支未点燃的仪式火炬，授予正在进行Call of Fire试炼的萨满。一旦火焰显灵被击败并将其余烬放入圣殿的火盆中，萨满便将火炬浸入炽热的火焰中，以元素力量将其点燃。",al={"什么是眠炎火炬","为什么我有这支未点燃的火炬","这支火炬有什么作用"}},{q="这支火炬在哪里点燃？",a="它在杜隆塔尔泰尔夫·祖拉姆附近的山顶上点燃，具体是在眠炎圣殿的火盆处，必须在击败火焰次级显灵之后立即进行。",al={"在哪里点燃眠炎火炬","眠炎圣殿火炬","如何点燃沉睡火炬"}},{q="谁提供了这支未点燃的火炬？",a="居住在十字路口北部的萨满卡纳尔·菲斯会将火炬交给试炼者，并指引他们前往眠炎圣殿的守护者泰尔夫·祖拉姆处，后者会将此视为尝试驾驭火焰的标志。",al={"谁给予了眠炎火炬","沉睡火炬来源","call of fire火炬提供者"}}},fp="26,180,19.432.0,54.247.0,30.165.0,29.231.0"}
P.entries["item:torn-fin-eye"] = {n="碎鳍鱼人的眼球",s="碎鳍鱼人的眼球是从希尔斯布莱德丘陵海岸边徘徊的碎鳍鱼人身上采集到的眼部器官。它们是皇家药剂师学会研究新型瘟疫这一严酷炼金课题时必不可少的反应原料。",h="碎鳍鱼人的眼球是从希尔斯布莱德丘陵海岸边徘徊的碎鳍鱼人身上采集到的眼部器官。它们是皇家药剂师学会研究新型瘟疫这一严酷炼金课题时必不可少的反应原料。",kw={"药剂师林度恩","苦痛药剂","希尔斯布莱德丘陵","鱼人","皇家药剂师学会","碎鳍","碎鳍鱼人的眼球","幽暗城"},ang={["faction:Horde"]="收集这些沿海试剂有助于部落在希尔斯布莱德丘陵的战争努力，加强了被遗忘者对抗南海镇敌对联盟入侵的据点。",["race:Undead"]="获取像碎鳍鱼人的眼球这样的有机催化剂，直接推进了皇家药剂师学会的终极目标：完善一种能够消灭天灾军团和生者的瘟疫。"},sec={{t="毁灭的试剂",b="皇家药剂师学会在开发被遗忘者的新瘟疫时，从不浪费任何邪恶的生物成分。从希尔斯布莱德丘陵西部海岸徘徊的、布满盐渍的鱼人身上采集到的碎鳍鱼人的眼球，具有激活不稳定炼金化合物所需的特殊有机特性。当与刺喉纳迦鳞片、恢复类巨魔药剂以及豺狼人淤泥结合时，这些眼部组织有助于稳定并触发旨在向敌方领土散布死亡的毒性混合物。"},{t="酿造苦痛",b="在幽暗城的Apothecarium中，炼金大师们发现，要在泥头花水混合物中添加腐烂胶体，需要只能在希尔斯布莱德海岸线上找到的催化剂。塔伦米尔的药剂师林度恩依靠这些采集来的眼球来催化他那臭名昭著的苦痛药剂。这种合剂是被遗忘者在邻近人类定居点眼皮底下制造毁灭性生物武器的不懈实验之一。"}},faq={{q="碎鳍鱼人的眼球有什么用途？",a="碎鳍鱼人的眼球是皇家药剂师学会所追求的一种炼金催化剂。塔伦米尔的药剂师林度恩将它们与刺喉鳞片和强效巨魔之血药剂一起使用，以激活不稳定的泥头花水中的污染剂，推进他关于新型致命瘟疫的研究。",al={"碎鳍鱼人的眼球用途","为什么要收集碎鳍鱼人的眼球","碎鳍鱼人的眼球目的"}},{q="在哪里可以找到碎鳍鱼人的眼球？",a="它们是从栖息在希尔斯布莱德丘陵西部海岸的碎鳍鱼人身上采集的，该区域位于南海镇人类城镇西侧的海岸线上。",al={"在哪里获得碎鳍鱼人的眼球","碎鳍鱼人的眼球位置","谁掉落碎鳍鱼人的眼球"}},{q="是谁下令收集这些眼球的？",a="幽暗城的被遗忘者研究员和驻扎在塔伦米尔的药剂师林度恩需要它们来完成被称为苦痛药剂的合剂。",al={"谁需要碎鳍鱼人的眼球","碎鳍鱼人的眼球任务发布者"}},{q="皇家药剂师学会为什么需要鱼人部位？",a="该学会的研究人员不断地用当地奇异的动物进行实验，以发现能够激活或增强毒性污染物的化合物。碎鳍鱼人的生理结构产生的眼液能够催化不稳定的瘟疫原型。",al={"为什么需要鱼人眼球","药剂师 鱼人"}}},fp="12,144,18.443.0,13.345.1,32.276.0,32.133.0,39.120.0,56.184.0"}
P.entries["item:torn-murloc-fin"] = {n="破损的鱼人鳞片",s="撕裂的鱼人鳍是暴风城军队在艾尔文森林东部对敌对两栖生物悬赏任务的完成证明。这些鳍从河岸边的觅食者和潜伏者身上收割而来，证明当地的水道正在被系统性地清理。",h="撕裂的鱼人鳍是暴风城军队在艾尔文森林东部对敌对两栖生物悬赏任务的完成证明。这些鳍从河岸边的觅食者和潜伏者身上收割而来，证明当地的水道正在被系统性地清理。",kw={"鱼人悬赏","艾尔文森林的鱼人","卫兵托马斯","鱼人的鳍","鱼人觅食者","鱼人潜伏者","石碑湖","破损的鱼人鳞片"},ang={["faction:Alliance"]="清理艾尔文森林东部的水道可以确保连接闪金镇、湖畔镇和暴风城的重要旅行路线的安全。",["race:Human"]="当地的人类当局越来越依赖雇佣兵来保护家园和河岸，使其免受好战鱼人定居点的侵扰。"},sec={{t="悬赏威胁",b="随着艾尔文森林东部溪流和湖泊中的鱼人数量激增，暴风城军队授权进行直接悬赏以削减其数量。驻守在东部河流大桥上的卫兵托马斯负责收集这些被割下的鳍来核实击杀数量。由于暴风城的军事力量在应对内部动乱和地区威胁时捉襟见肘，地方当局严重依赖旅行冒险者带回清理营地的实物证明。"}},faq={{q="谁在收购或收集撕裂的鱼人鳍？",a="卫兵托马斯代表治安官杜汉和暴风城军队在艾尔文森林的东部大桥收集这些物品。",al={"谁需要鱼人鳍","交纳鱼人鳍","卫兵托马斯鱼人鳍"}},{q="携带这些鳍的鱼人位于何处？",a="它们取自聚集在北部的石碑湖以及艾尔文东部边界附近南部溪流叉口的鱼人觅食者和潜伏者。",al={"去哪里刷鱼人鳍","鱼人鳍位置","鱼人鳍掉落"}},{q="为什么暴风城需要鳍作为证明？",a="鳍可以提供明确且易于携带的已击杀鱼人的实物证据，确保赏金猎人在领取军队报酬前能获得相应的功绩确认。",al={"为什么需要鳍","鱼人击杀证明","赏金证明"}},{q="为什么暴风城军队要为击杀鱼人支付报酬？",a="在军队力量被其他事务牵制时，鱼人村落沿水道迅速扩张，威胁到了旅行者、渔民和当地基础设施。",al={"为什么悬赏鱼人","艾尔文森林的鱼人问题"}}},fp="15,108,17.368.0,38.116.0,50.142.0,41.127.0,50.168.0"}
P.entries["item:totem-of-hawkwind"] = {n="鹰风图腾",s="鹰风图腾是年轻的牛头人在离开纳拉其营地时携带的雕刻信物。将其呈交给血蹄村的贝恩·血蹄，即证明携带者已完成了初步试炼，并准备好进行大地母亲仪式剩余的部分。",h="鹰风图腾是年轻的牛头人在离开纳拉其营地时携带的雕刻信物。将其呈交给血蹄村的贝恩·血蹄，即证明携带者已完成了初步试炼，并准备好进行大地母亲仪式剩余的部分。",kw={"贝恩·血蹄","血蹄村","纳拉其营地","鹰风酋长","鹰风","大地母亲仪式","图腾"},ang={["race:Tauren"]="携带这枚图腾标志着从红云台地的童年生活中走出，进入莫高雷广阔部落领地这一决定性的成人礼。"},sec={{t="酋长的背书",b="这枚木制图腾由鹰风酋长在红云台地亲手雕刻，作为成年的年轻牛头人的一份介绍信和通行证明。在牛头人的传统中，正式文书很少使用；取而代之的是，富有意义的象征符号和熟悉的部落工艺传达着领袖的意图。当一名满怀抱负的年轻人完成了他们在纳拉其营地的初步试炼后，鹰风酋长会制作这一标志，将他们送上前往莫高雷广阔大地的道路。独特的雕刻图案向贝恩·血蹄表明了携带者的身份，示意他们已拥有面对接下来试炼的精神与力量，并去寻求雷霆崖最终的祝福。"}},faq={{q="鹰风图腾有什么用途？",a="它作为一种通行信物。年轻的牛头人将其从纳拉其营地带到血蹄村，向贝恩·血蹄证明鹰风酋长已认为他们准备好继续进行大地母亲仪式了。",al={"鹰风图腾有什么用","鹰风图腾的目的","为什么我会有这个图腾"}},{q="谁制作了这枚图腾？",a="图腾是由红云台地定居点的领袖，鹰风酋长亲自雕刻的。其独特的雕刻图案会被莫高雷各地的盟友酋长们一眼认出。",al={"谁雕刻了图腾","图腾制作者","鹰风图腾起源"}},{q="谁会收到鹰风图腾？",a="它会被带给凯恩·血蹄之子贝恩·血蹄，他负责管理红云台地以东的血蹄村。",al={"我该把图腾交给谁","图腾接收者","图腾要送到哪里"}},{q="为什么使用图腾而不是信件？",a="牛头人的文化非常依赖口头传统、实体艺术和祖先象征。雕刻的图腾承载着塑造它的酋长的个人触感与精神，在部落领袖中比羊皮纸上的墨水更有分量。",al={"为什么不用信件","牛头人信物传统"}}},fp="17,243,25.574.0,39.222.0,19.124.0,35.120.0,36.201.0"}
P.entries["item:tough-wolf-meat"] = {n="硬狼肉",s="硬狼肉是从徘徊在北郡山谷和寒脊山谷的森林狼和幼狼身上获取的生肉。虽然口感粗糙、纤维多，但它却是艾尔文森林的伊根·派斯基恩和丹莫罗的矮人补给员等饥肠辘辘的当地人的主食。",h="硬狼肉是从徘徊在北郡山谷和寒脊山谷的森林狼和幼狼身上获取的生肉。虽然口感粗糙、纤维多，但它却是艾尔文森林的伊根·派斯基恩和丹莫罗的矮人补给员等饥肠辘辘的当地人的主食。",kw={"丹莫罗","伊根·派斯基恩","艾尔文森林","北郡修道院","森林狼","硬狼肉","幼狼"},ang={["race:Dwarf"]="寒脊山谷的矮人经常猎杀褴褛的森林狼来获取肉类，以帮助当地补给员在出发穿越丹莫罗之前补充物资。",["race:Human"]="对于北郡山谷的新兵来说，为伊根·派斯基恩收集狼肉是他们在修道院宁静的回廊之外所要完成的最早的生存任务之一。"},sec={{t="边境口粮",b="徘徊在北郡山谷和丹莫罗边缘的狼群对当地定居点构成了持续的威胁，但它们也提供了一种耐嚼的食物来源。与上等的野味相比，硬狼肉以多筋和难嚼著称，但资源匮乏的边境居民依然对其趋之若鹜。在北郡修道院外，伊根·派斯基恩虽然厌恶这些野兽的凶残，却乐于将它们的肉烹制成乡村牛排，并渴望用基本补给和装备来交换那些愿意猎杀狼群的人带回来的肉。"}},faq={{q="硬狼肉从哪里来？",a="它是在艾尔文森林的北郡山谷猎杀幼狼和森林狼，以及在丹莫罗的寒脊山谷猎杀褴褛的狼所获得的。",al={"硬狼肉来源","如何获得硬狼肉","哪里刷硬狼肉"}},{q="在艾尔文森林里，谁需要收集这种肉？",a="驻扎在北郡修道院外的伊根·派斯基恩会收集这种肉。尽管他憎恨狼，但他很喜欢烤狼排，并且会用多余的装备来交换那些为他带来八块狼肉的新兵。",al={"谁需要狼肉","伊根·派斯基恩的狼肉","狼肉交接"}},{q="这种肉在人类领土之外有用吗？",a="有的。在寒冷的丹莫罗地区，矮人补给员也会接受从寒脊山谷的狼身上获取的硬狼肉，以保持补给充足。",al={"丹莫罗狼肉","矮人狼肉","矮人补给员狼肉"}},{q="硬狼肉会用于普通的烹饪配方吗？",a="不会。硬狼肉严格来说是为伊根·派斯基恩和寒脊山谷补给员等当地边境居民收集的任务奖励，而不是用于标准营地烹饪配方的食材。",al={"硬狼肉能烹饪吗","硬狼肉配方"}}},fp="15,231,16.376.0,37.157.0,48.186.0,43.127.0,50.165.0"}
P.entries["item:tourmaline-phial"] = {n="红玉瓶",s="红玉瓶是一种由宝石精制而成的容器，由科瑞萨斯·月怒分发给泰达希尔的旅行者。它被用于从阿里斯瑞恩之池旁的月亮井中汲取受祝福的井水，作为监测和安抚世界之树枝桠的持续仪式的一部分。",h="红玉瓶是一种由宝石精制而成的容器，由科瑞萨斯·月怒分发给泰达希尔的旅行者。它被用于从阿里斯瑞恩之池旁的月亮井中汲取受祝福的井水，作为监测和安抚世界之树枝桠的持续仪式的一部分。",kw={"科瑞萨斯·月怒","crown of the earth","多兰纳尔","月亮井","阿里斯瑞恩之池","泰达希尔","红玉瓶"},ang={["class:Druid"]="携带专门的宝石瓶来收集月亮井水，是年轻的暗夜精灵德鲁伊在学习照料泰达希尔脆弱生态系统时一项重要的礼仪职责。",["race:NightElf"]="像红玉瓶这样容器中所收集的井水，代表了暗夜精灵在泰达希尔努力对抗腐蚀的过程中，对艾露恩的恩典与德鲁伊式警惕的依赖。"},sec={{t="阿里斯瑞恩之皿",b="科瑞萨斯·月怒提供了红玉瓶，以协助围绕世界之树进行的仪式。多兰纳尔的德鲁伊使用这种专门的宝石瓶来安全地从泰达希尔各地收集纯净的月亮井水。这个特定的瓶子是为阿里斯瑞恩之池岸边的月亮井准备的，位于通往To Darnassus的道路东南方，该地区正日益受到敌对的Gnarlpine furbolgs的侵扰。"}},faq={{q="红玉瓶有什么用途？",a="这个瓶子用于从位于阿里斯瑞恩之池的月亮井中收集圣水。装满后，它必须作为Crown of the Earth仪式的一部分交还给多兰纳尔的科瑞萨斯·月怒。",al={"红玉瓶有什么作用","红玉瓶的目的","使用红玉瓶"}},{q="谁提供了红玉瓶？",a="驻扎在多兰纳尔镇的暗夜精灵德鲁伊科瑞萨斯·月怒会将空瓶托付给冒险者。",al={"谁给予红玉瓶","在哪里获得红玉瓶"}},{q="这个瓶子对应的月亮井在哪里？",a="月亮井位于阿里斯瑞恩之池的岸边，在通往To Darnassus的主入口东南方。",al={"阿里斯瑞恩之池月亮井","在哪里装满红玉瓶"}}},fp="16,105,20.352.0,38.185.0,34.83.0,37.93.0"}
P.entries["item:toxic-fogger"] = {n="剧毒粮草",s="剧毒粮草是一种装满致命毒素的特制扩散装置，由被遗忘者皇家药剂师学会配制。它的设计目的是为了污染石爪山脉中荆棘谷地精的空中运输作业。",h="剧毒粮草是一种装满致命毒素的特制扩散装置，由被遗忘者皇家药剂师学会配制。它的设计目的是为了污染石爪山脉中荆棘谷地精的空中运输作业。",kw={"药剂师扎玛","直升机停机坪","峭壁湖","航空港","石爪山脉","剧毒粮草","荆棘谷地精"},ang={["race:Tauren"]="虽然依赖致命蒸汽可能会考验传统的牛头人荣誉准则，但荆棘谷地精所造成的毁灭性工业破坏，使得雷霆崖的许多人都容忍了扎玛的严酷手段。",["race:Undead"]="剧毒粮草代表了皇家药剂师学会的经典野外战略：用气溶胶毒素破坏敌人的供应链，同时向盟友展示黑暗手段也能产生不可否认的战果。"},sec={{t="被遗忘者的解决方案",b="剧毒粮草装载着由塔伦米尔的药剂师林度恩调制、并由雷霆崖的药剂师扎玛派发的毒素，它是直接针对荆棘谷地精露天采矿作业的生物破坏手段。扎玛推测这些地精依靠信使飞行器在石爪山脉和其总部之间往返运输信息和轻型货物，因此她将这种毒素装置发送过去，以便在其飞行器降落和加油的地方释放毒气。被遗忘者的方法并非与无尽的雇佣兵队伍进行旷日持久的冲突，而是打击其作业的后勤命脉，确保毒素直接传回企业领导层。"},{t="峭壁湖的破坏行动",b="剧毒粮草的目标是修建在峭壁湖附近的隐蔽直升机停机坪。该停机坪高耸于被砍伐的丘陵之上，由企业雇佣兵守卫，是远程作业人员与外部枢纽之间的空中连接点。部署该装置后，大片的有毒蒸汽会覆盖整个停机坪，让回航的飞行员措手不及。虽然部落内部有些人对使用毒素感到反感，但扎玛敦促她的特工抛弃负罪感，声称只要能战胜剥削者，没有哪条路是过于黑暗的。"}},faq={{q="剧毒粮草是做什么用的？",a="剧毒粮草用于毒化荆棘谷地精位于石爪山脉峭壁湖的航空港，以此污染运回其总部的轻型货物和信使。",al={"剧毒粮草的作用","粮草的目的","为什么要用剧毒粮草"}},{q="谁制造了剧毒粮草？",a="其中的毒素是由塔伦米尔的药剂师林度恩用无辜者的血液调制而成。随后，驻扎在雷霆崖下方预见之池的皇家药剂师学会特使药剂师扎玛将其送出进行投递。",al={"谁制造了粮草","剧毒粮草的创造者","药剂师扎玛的毒药"}},{q="剧毒粮草需要被放置在哪里？",a="它必须被放置在石爪山脉峭壁湖附近、大型水车以南的一处高地上的荆棘谷地精直升机停机坪顶端。",al={"我该把粮草放在哪里","直升机停机坪的位置","航空港的位置"}},{q="为什么部落会对荆棘谷地精使用毒素？",a="荆棘谷地精的伐木和采矿作业严重破坏了石爪山脉的土地。药剂师扎玛认为常规战斗效率太低，她主张部落必须采取无情的手段，在造成不可挽回的损害之前彻底铲除这些地精。",al={"为什么要毒杀地精","部落允许使用毒药吗","被遗忘者在石爪山脉的手段"}}},fx={["3a36a6bd"]={q="什么是剧毒粮草？",a="剧毒粮草是一种特殊的散播装置，里面装有被遗忘者调制的致命药剂。它被设计成启动后释放有毒云雾，是一种用于破坏的工具，旨在污染荆棘谷地精的后勤网络，扰乱他们在石爪山的行动。",al={"什么是剧毒粮草","剧毒粮草物品","剧毒粮草装置"}},bbff0049={q="药剂师扎玛为什么要部署剧毒粮草？",a="药剂师扎玛打算直接打击荆棘谷地精的补给线。将剧毒粮草部署在他们的小型飞艇港后，毒剂便能覆盖起飞的飞行器和货物，再被带回地精总部，让他们为肆无忌惮的掠夺付出惨痛代价。",al={"为什么使用剧毒粮草","为什么想要剧毒粮草","为什么需要剧毒粮草"}}},fp="12,191,19.497.0,25.448.1,34.196.0,29.204.0,46.146.0,70.223.0"}
P.entries["item:translated-letter"] = {n="翻译好的信件",s="在夜色镇，希拉·沃宁迪为市长埃罗·埃博诺克翻译亚伯克隆比的信。这封信揭示了隐士与镇民之间的往来。",h="在夜色镇，希拉·沃宁迪为市长埃罗·埃博诺克翻译亚伯克隆比的信。这封信揭示了隐士与镇民之间的往来。",kw={"亚伯克隆比","夜色镇","写给艾尔罗的信","艾尔罗·埃伯洛克公爵","希拉·沃宁迪","翻译好的信件"},ang={["faction:Alliance"]="这封信标志着暮色森林的联盟旅行者经历了一个毁灭性的清算时刻，证明了即使是纯粹的意图也可能被用作对抗夜色镇脆弱守卫者的武器。"},sec={{t="可怕的真相",b="最初只是为了帮助乌鸦岭一位看似无助的隐士，但这卷羊皮纸却让事情变得阴暗起来。这封写得难以辨认的信件，在交给希拉·沃宁迪翻译之前，对于艾尔罗·埃伯洛克公爵来说一直是个谜。破译后的文字揭露了这位隐士作为缝合怪制造者的真实身份。亚伯克隆比并非在过着与世无争的生活，他利用旅行者送来的补给，制造出了名为缝合怪的恐怖憎恶，并将这个庞然大物释放出来，在夜色镇横行肆虐，屠杀镇民。"},{t="善意的代价",b="当把这封翻译好的信件呈交给艾尔罗·埃伯洛克公爵时，镇长的脸色瞬间变得惨白。虽然旅行者提供帮助是出于真心实意，但这封信证明了亚伯克隆比一直在愚弄他们，利用他们的劳动来制造杀戮机器。当镇议会手忙脚乱地召集守夜人部队时，这封被破译的信件成了令人不寒而栗的证明：在暮色森林那闹鬼的道路上，仁慈是多么容易被扭曲成毁灭的灾难。"}},faq={{q="翻译好的信件上写了什么？",a="它包含了一封来自亚伯克隆比发给艾尔罗·埃伯洛克公爵的惊人信息。当这封翻译好的信件在夜色镇被交付时，其完整内容将会揭晓。",al={"信件文本","亚伯克隆比写了什么","上面写了什么"}},{q="是谁翻译了这封信？",a="希拉·沃宁迪，一位居住在夜色镇的学者，她翻译了亚伯克隆比那些晦涩难懂的字迹，并提醒你尽快带着这些令人震惊的消息回去找埃伯洛克公爵。",al={"谁翻译的","谁破译了信件","希拉·沃宁迪的信"}},{q="埃伯洛克读完信后会发生什么？",a="埃伯洛克对翻译的内容感到非常震惊。把它带给他，了解这对夜色镇意味着什么。",al={"埃伯洛克的反应","上交翻译好的信件","翻译后会发生什么"}},{q="任务完成后我可以丢弃翻译好的信件吗？",a="可以。一旦艾尔罗·埃伯洛克公爵检查了羊皮纸并推进了城镇的防御工作，这封信就会留在你的背包里作为纪念品，不再具有任何功能性用途。",al={"删除翻译好的信件安全吗","我可以摧毁翻译好的信件吗","保留翻译好的信件"}}},fx={ad927ea8={q="什么是翻译好的信件？",a="翻译好的信件是一封阴森的信，由隐士亚伯克隆比写下，再由希拉·沃宁迪解译。信中揭露了亚伯克隆比在乌鸦岭实施阴谋所造成的可怕后果，并直接警告夜色镇的居民，迫近的灾难即将降临。",al={"翻译好的信件","什么是翻译好的信件","关于翻译好的信件"}},["7688c5ef"]={q="艾尔罗·埃伯洛克公爵为什么需要翻译好的信件？",a="夜色镇镇长艾尔罗·埃伯洛克公爵必须读懂解译后的内容，才能了解他的城镇正面临的严重威胁。信件揭露了亚伯克隆比所作所为的可怕真相，也让镇民提前得知，一只庞然怪物正直奔他们的城门而来。",al={"为什么要把翻译好的信件交给艾尔罗","艾尔罗为什么想要翻译好的信件","谁需要翻译好的信件"}}},fp="17,150,21.549.1,28.489.1,36.156.1,26.158.0,40.96.1,55.163.1"}
P.entries["item:treshala-s-pendant"] = {n="塔莎拉的坠饰",s="塔莎拉的坠饰是居住在达纳苏斯的暗夜精灵塔莎拉·静水的一件珍贵的定情传家宝。她的丈夫赫尔拉斯带着它前往卡利姆多南部，在他弥留之际，这件坠饰被剃刀沼泽的野猪人夺走了。",h="塔莎拉的坠饰是居住在达纳苏斯的暗夜精灵塔莎拉·静水的一件珍贵的定情传家宝。她的丈夫赫尔拉斯带着它前往卡利姆多南部，在他弥留之际，这件坠饰被剃刀沼泽的野猪人夺走了。",kw={"达纳苏斯","赫尔拉斯·静水","弥留之际","野猪人","剃刀沼泽","塔莎拉·静水","塔莎拉的坠饰"},ang={["faction:Alliance"]="将这枚信物带回达纳苏斯，能为这位哀悼牺牲探险者的联盟遗孀带来一丝沉重的慰藉。",["race:NightElf"]="找回这枚坠饰是对这位卡多雷同胞悲剧性临终时刻的纪念，他死在了远离泰达希尔庇护的地方。"},sec={{t="忠贞信物",b="这枚坠饰象征着塔莎拉与赫尔拉斯·静水之间深厚的婚姻誓约。在踏上离开泰达希尔的危险旅程之前，赫尔拉斯一直贴身携带这条定情项链，作为对家乡和爱人的纪念。"},{t="迷失荆棘",b="当赫尔拉斯冒险深入剃刀沼泽的多刺深处时，凶残的野猪人袭击了他的小队。在他痛苦的弥留时刻，这枚坠饰被一名长牙的守卫夺走。随着他的生命逐渐流逝，赫尔拉斯临终的遗愿是希望有位冒险者能从杀手手中夺回这件纪念品，并将坠饰和他不幸遭遇的悲伤消息带回达纳苏斯。"}},faq={{q="什么是塔莎拉的坠饰？",a="这是属于塔莎拉·静水的一枚个人定情坠饰，由她的丈夫赫尔拉斯带着作为他们结合的纪念，后来他在剃刀沼泽迎来了生命的终点。",al={"该物品是什么","定情坠饰","坠饰的主人是谁"}},{q="这枚坠饰是如何流落到剃刀沼泽的？",a="赫尔拉斯·静水在前往剃刀沼泽探险时随身携带了它。当野猪人伏击并致他于死地时，其中一头野兽从他身上抢走了这条项链。",al={"为什么在剃刀沼泽","如何丢失的"}},{q="谁请求寻回这枚坠饰？",a="赫尔拉斯·静水本人在剃刀沼泽濒死时，恳求路过的冒险者寻回被盗的坠饰，并请求将它和他的死讯一起带回达纳苏斯交给他的妻子。",al={"任务发布者","谁希望找回坠饰"}},{q="寻回坠饰后应该交给谁？",a="这枚坠饰将被送往赫尔拉斯悲痛欲绝的遗孀塔莎拉·静水手中，她居住在泰达希尔之巅的暗夜精灵主城达纳苏斯。",al={"坠饰交付地点","塔莎拉是谁"}}},fx={["1ac8940a"]={q="为什么要寻找塔莎拉的坠饰？",a="濒死的暗夜精灵赫尔拉斯·静水在剃刀沼泽中奄奄一息，他最后的愿望是找回这件被盗的纪念品。这是他的妻子塔莎拉送给他的信物。在他孤独地死于野猪人要塞之前，他希望你能从夺走坠饰的暴徒手中把它取回，并将坠饰和他去世的噩耗一并送到达纳苏斯交给他的妻子。",al={"为什么要寻找塔莎拉的坠饰","赫尔拉斯为什么想要坠饰","塔莎拉的坠饰的用途"}}},fp="18,214,17.191.0,18.335.1,27.153.0,45.168.0,41.167.0,46.128.0"}
P.entries["item:trogg-stone-tooth"] = {n="穴居人的石牙",s="穴居人的石牙是一种粗糙的矿化牙齿，取自侵扰洛克莫丹群山的碎石穴居人。矮人守卫将这些牙齿作为实物证据，证明流浪的冒险者正在减少南部边境一带的穴居人数量。",h="穴居人的石牙是一种粗糙的矿化牙齿，取自侵扰洛克莫丹群山的碎石穴居人。矮人守卫将这些牙齿作为实物证据，证明流浪的冒险者正在减少南部边境一带的穴居人数量。",kw={"洛克莫丹","拉格弗斯","碎石","穴居人的威胁","穴居人","穴居人的石牙"},ang={["faction:Alliance"]="响应拉格弗斯上尉的悬赏，可以直接缓解连接矮人王国与更广阔联盟的关键贸易路线上的压力。",["race:Dwarf"]="每一颗回收的牙齿都有助于保卫卡兹莫丹，因为铁炉堡的主力部队目前正部署在海外执行联盟的任务。"},sec={{t="南部大门的悬赏",b="随着铁炉堡预备役被调往联盟前线，当地的矮人驻军在卡兹莫丹各地兵力吃紧。在洛克莫丹的南门岗哨，拉格弗斯上尉无法抽调士兵离开岗位，去对潜伏的碎石穴居人进行进攻性巡逻。因此，他发布了一项常驻任务，号召志愿者去附近的群山中猎杀这些生物。为了确认威胁正在被击退，拉格弗斯要求以穴居人的石牙作为每一头被杀野兽的原始且无可辩驳的证据。"}},faq={{q="谁需要这些穴居人的石牙？",a="驻扎在洛克莫丹边界南侧岗哨的拉格弗斯上尉收集这些牙齿，以此作为旅行者正在猎杀碎石穴居人的证明。",al={"谁在收集穴居人的石牙","拉格弗斯 牙齿","谁需要石牙"}},{q="为什么牙齿是石头做的？",a="穴居人拥有土属性的地下生理结构，这反映了他们古老的岩石起源，使他们的獠牙和牙齿呈现出类似于原岩的沉重矿化成分。",al={"为什么是石牙","穴居人解剖学 牙齿","穴居人的牙齿是岩石吗"}},{q="为什么矮人驻军不能自己去猎杀穴居人？",a="铁炉堡预备役已经被动员去参加更广泛的联盟战争，导致当地哨所人手不足。拉格弗斯上尉的部队被限制在守卫南门，无法冒险让他们的防御工事无人把守。",al={"拉格弗斯为什么需要帮助","为什么矮人不亲自对抗穴居人","铁炉堡预备役"}},{q="哪些穴居人带有这种牙齿？",a="它们可以从漫游在洛克莫丹群山和挖掘场中的任何碎石穴居人身上收集到，从普通的挖掘工和斥候，到碎骨战士和地卜师，应有尽有。",al={"在哪里获取穴居人的石牙","谁掉落石牙"}}},fp="17,187,27.438.0,34.132.0,32.137.0,58.202.0,31.155.0"}
P.entries["item:troll-charm"] = {n="巨魔符咒",s="巨魔符咒是暗矛巨魔随身携带的神圣精神护身符。最近，在灰谷北部边缘的一次伏击中，敌对的蓟皮熊怪掠夺了一批符咒。",h="巨魔符咒是暗矛巨魔随身携带的神圣精神护身符。最近，在灰谷北部边缘的一次伏击中，敌对的蓟皮熊怪掠夺了一批符咒。",kw={"灰谷","暗矛","米苏瓦","thistlefur hold","蓟皮村","巨魔符咒","佐拉姆加前哨站"},ang={["faction:Horde"]="收回这些被盗物品既能削弱好战的蓟皮部族，又能为在灰谷险恶小径上遇害的部落旅行者复仇。",["race:Troll"]="对于暗矛巨魔来说，让神圣的符咒落在野蛮的熊怪手中，是对阵亡族人记忆和灵魂的无法容忍的侮辱。"},sec={{t="暗矛的神圣饰品",b="对于部落的巨魔而言，精神符咒不仅仅是装饰品。正如斥候米苏瓦所言，没有符咒的巨魔，就如同没有战痕的兽人一般，被认为是不完整的。当一群暗矛族人穿过灰谷茂密的丛林前往佐拉姆加前哨站时，他们遭到了堕落的蓟皮熊怪的伏击并被屠杀。当他们的灵魂被托付给来世时，这些熊怪洗劫了死者，并将他们的神圣符咒作为战利品带走，藏在蓟皮村深处的箱子里。"}},faq={{q="巨魔符咒有什么用途？",a="巨魔符咒是暗矛巨魔神圣的文化和精神守护物。携带这些护身符是他们族人个人尊严和精神尊严的重要标志。",al={"巨魔符咒的用途","巨魔符咒背景","为什么巨魔要携带符咒"}},{q="这些符咒在哪里可以找到？",a="它们被锁在蓟皮村后面的洞穴系统——Thistlefur Hold——中散落的箱子里，该洞穴位于灰谷北部。",al={"巨魔符咒在哪里","如何找到巨魔符咒","巨魔宝箱位置"}},{q="为什么熊怪会有这些符咒？",a="一群暗矛旅行者在安全到达佐拉姆加前哨站之前，遭到了蓟皮部族的伏击和杀害。这些熊怪洗劫了他们的财物并留下了这些符咒。",al={"为什么熊怪会有这些符咒","谁偷了符咒"}},{q="谁想要回这些符咒？",a="驻扎在佐拉姆海岸的佐拉姆加前哨站的暗矛巨魔米苏瓦，希望能找回它们，以恢复他遇害族人的荣誉。",al={"谁拿走了符咒","米苏瓦任务"}}},fx={["5fe70fe7"]={q="什么是巨魔符咒？",a="巨魔符咒是暗矛巨魔随身携带的神圣部族护符。这些符咒对巨魔而言具有深远的个人和精神意义，被视为身份与地位的重要凭证——以至于没有符咒的巨魔，在同族眼中就像没有战痕的兽人一样。",al={"什么是巨魔符咒","巨魔符咒物品","神圣的巨魔符咒"}},["6d34290e"]={q="巨魔护符来自哪里？是谁制作的？",a="这些护符由途经灰谷、前往佐拉姆加前哨站的暗矛巨魔制作并随身携带。不幸的是，旅人们在路上遭到敌对的Thistlefur熊怪伏击并被杀害，神圣的物品也被劫走，锁在Thistlefur Hold深处的箱子里。",al={"巨魔护符的来历","巨魔护符是谁制作的","巨魔护符来自哪里"}},["77137dd7"]={q="米苏瓦为什么想要取回巨魔护符？",a="佐拉姆加前哨站的米苏瓦为遇难的旅人哀悼，但她接受他们终将在来世重聚的事实。然而，任由粗野凶恶的熊怪占有这些神圣遗物，被视为对巨魔传统无法容忍的侮辱。找回护符，便能让死者的记忆重获尊严。",al={"为什么要获取巨魔护符","米苏瓦为什么想要护符","为什么要找巨魔护符"}}},fp="11,184,32.450.0,31.92.0,29.120.0,38.141.0,26.130.0"}
P.entries["item:trophy-swoop-quill"] = {n="猛鹫的羽毛",s="猛鹫的羽毛是一种珍贵的狩猎信物，是从盘旋在莫高雷平原上空的猛禽身上拔下来的。在牛头人之中，收集这些羽毛证明了敏锐的视力、耐心以及狩猎技巧。",h="猛鹫的羽毛是一种珍贵的狩猎信物，是从盘旋在莫高雷平原上空的猛禽身上拔下来的。在牛头人之中，收集这些羽毛证明了敏锐的视力、耐心以及狩猎技巧。",kw={"血蹄村","哈肯·风之图腾","莫高雷","猛鹫狩猎","猛鹫羽毛","利爪猛鹫","猛鹫的羽毛","瘦削的猛鹫"},ang={["class:Hunter"]="在开阔的平原上追踪空中的猎物，是对追踪术、耐心和射术基础的考验。",["race:Tauren"]="捕猎猛鹫并带回它们的羽毛是莫高雷各地考验耐心与智慧的传统追求，既是对猎人的尊荣，也是对氏族的尊荣。"},sec={{t="狩猎信物",b="猛鹫是莫高雷本土的一种狡猾的禽类掠食者，以乘着高空热气流飞行而闻名，并且在草原上极难追踪。对于那些想要在血蹄村证明自己的年轻牛头人猎人和旅行者来说，从这些鸟身上获取一根猛鹫的羽毛是考验智慧与决心的传统仪式。将这些羽毛呈献给哈肯·风之图腾等长者，不仅是对猎人氏族的尊重，也标志着此人拥有在平原上生存所需的敏锐感官。"}},faq={{q="猛鹫的羽毛有什么用？",a="猛鹫的羽毛是作为狩猎功绩的证明，收集起来呈交给血蹄村的哈肯·风之图腾。带给他这些羽毛证明了你的决心和敏锐的观察力，并能提升你在当地牛头人中的地位。",al={"猛鹫羽毛有什么用","谁需要猛鹫羽毛","猛鹫羽毛用途"}},{q="猛鹫的羽毛来自哪里？",a="这些羽毛取自各种猛鹫——包括普通猛鹫、瘦削的猛鹫和利爪猛鹫——它们在莫高雷的草海平原上空翱翔。",al={"哪里获得猛鹫羽毛","谁掉落猛鹫的羽毛","猛鹫位置"}},{q="为什么说猛鹫很难捕猎？",a="正如哈肯·风之图腾所描述的那样，猛鹫是狡猾的鸟类，它们在草地上空高高盘旋，在地形中快速移动，需要敏锐的眼睛才能发现它们，并且需要迅速的步伐才能追上。",al={"为什么要捕猎猛鹫","猛鹫很难杀吗"}}},fp="18,159,17.325.0,38.204.0,39.119.0,44.192.0"}
P.entries["item:twilight-pendant"] = {n="暮光坠饰",s="暮光坠饰是暮光之锤的教徒在黑暗深渊深处所佩戴的徽记。对于银色黎明来说，这些黑暗护身符是该邪教在灰谷海岸进行颠覆活动的铁证。",h="暮光坠饰是暮光之锤的教徒在黑暗深渊深处所佩戴的徽记。对于银色黎明来说，这些黑暗护身符是该邪教在灰谷海岸进行颠覆活动的铁证。",kw={"银月守卫玛纳杜斯","灰谷","黑暗深渊","古神","暮光降临","暮光坠饰","暮光之锤"},ang={["faction:Alliance"]="将这些战利品带给达纳苏斯的银月守卫玛纳杜斯，证明了联盟正在积极支持银色黎明在卡利姆多北部对抗隐藏邪恶的远征。",["race:NightElf"]="黑暗深渊曾经是一座受人尊敬且强大的月亮井的所在地，对其的亵渎使得回收这些腐化的象征成为了卡多雷眼中一件神圣的大事。"},sec={{t="古神的信物",b="在黑暗深渊的淹没废墟中，暮光之锤的成员与纳迦聚集在一起，举行邪恶的仪式以崇拜混乱的古神。教徒们——从暗影法师和水术师，到掠夺者和博学者——佩戴这些坠饰，作为他们对暗影主子忠诚的象征。由于该邪教在曾经的暗夜精灵神殿下方秘密运作，回收这些装饰品是外界观察者衡量邪教规模并挫败其阴谋的少数途径之一。"},{t="银色黎明的守望",b="达纳苏斯的银月守卫玛纳杜斯积极寻求这些坠饰，作为对抗侵蚀黑暗并取得成功的证据。黑暗深渊曾拥有一口原始月亮井，其被邪恶的虚空崇拜者所亵渎，这对卡利姆多构成了严重威胁。收集这些坠饰证实了该邪教在灰谷的立足点正在被拆除，从而阻止他们的暗影主子散布更大的恐怖。"}},faq={{q="什么是暮光坠饰？",a="暮光坠饰是暮光之锤邪教成员在黑暗深渊内运作时佩戴的身份护身符。它是对古神及其黑暗仪式忠诚的切实证明。",al={"暮光坠饰信息","什么是暮光坠饰"}},{q="为什么银月守卫玛纳杜斯需要这些坠饰？",a="驻扎在达纳苏斯代表银色黎明的银月守卫玛纳杜斯，寻求这些坠饰作为证据，证明暮光之锤在黑暗深渊的势力正在被打击，使其邪恶计划无法成熟。",al={"谁想要暮光坠饰","为什么要收集暮光坠饰"}},{q="谁佩戴这些坠饰？",a="它们由黑暗深渊水下神殿内的各种教徒携带，包括暮光侍僧、水术师、暗影法师、博学者、元素师和掠夺者。",al={"谁掉落暮光坠饰","暮光坠饰来自哪里"}},{q="暮光之锤在黑暗深渊构成了什么威胁？",a="暮光之锤与纳迦结盟，旨在复兴对古神的崇拜，亵渎了一座古老的暗夜精灵月亮井，并准备进行可能在整个卡利姆多散布恐怖的仪式。",al={"暮光之锤在黑暗深渊做什么","为什么教徒在灰谷"}}},fp="16,170,22.425.0,24.370.0,27.159.0,50.164.0,25.130.0,65.168.0"}
P.entries["item:twilight-whisker"] = {n="夜行虎须",s="夜行虎须是从石爪山脉北侧高地潜行的夜行虎身上采集而来。在玛拉卡金定居点，巫医金吉尔渴望得到它们，将其作为一种残忍、剧毒的混合药剂的配料，并嘲讽地将其命名为丛林魔法。",h="夜行虎须是从石爪山脉北侧高地潜行的夜行虎身上采集而来。在玛拉卡金定居点，巫医金吉尔渴望得到它们，将其作为一种残忍、剧毒的混合药剂的配料，并嘲讽地将其命名为丛林魔法。",kw={"丛林魔法","玛拉卡金","石爪山脉","石爪峰","夜行虎","夜行虎须","巫医金吉尔"},ang={["race:NightElf"]="亵渎夜行虎和灵龙这类神圣的林地生物来毒害暗夜精灵俘虏，充分体现了卡利姆多森林中正在进行的残酷冲突。",["race:Troll"]="金吉尔对当地野兽试剂的使用反映了典型的暗矛巨魔巫毒传统，他将森林的自然精华扭曲用来对付他的敌人。"},sec={{t="巫医的试剂",b="石爪峰附近的崇山峻岭是夜行虎的栖息地，这些掠食性猫科动物与古老树林深处的阴影相伴而生。虽然猎人们看重它们的毛皮，但玛拉卡金的巫医金吉尔却为了一个更加黑暗的目的搜寻它们坚硬的胡须。为了向曾经保卫过这片林地的被俘暗夜精灵复仇，金吉尔收集了森林的各类素材——树脂、无数只眼睛、灵龙的鳞片以及夜行虎须，意图酿造一种致命的药水来羞辱和毒杀他的俘虏。"}},faq={{q="在哪里可以找到夜行虎须？",a="它们是从在石爪山脉北部的石爪峰斜坡上潜行的夜行虎身上采集的。",al={"夜行虎须位置","谁掉落夜行虎须","在哪里获得夜行虎须"}},{q="为什么巫医金吉尔想要这些东西？",a="巫医金吉尔将它们与树脂、粗鬃兽的眼睛以及灵龙的鳞片一起使用，酿造出一种致命的药水，用来毒杀他在玛拉卡金囚禁的暗夜精灵。",al={"金吉尔虎须","为什么金吉尔想要夜行虎须","金吉尔丛林魔法配料"}},{q="金吉尔得到虎须后会发生什么？",a="一旦获得了这些配料，金吉尔就会在他的洞穴中施放这种药水。这种混合药剂会迅速杀掉被关在笼子里的暗夜精灵囚犯，释放出的灵魂会化作小精灵飘散而去。",al={"丛林魔法结果","囚犯们的下场"}}},fx={["15466f07"]={q="什么是夜行虎须？",a="夜行虎须是从徘徊于石爪山脉高处的暮光奔行者身上采集的坚硬须毛。对大多数人而言，它不过是野兽的残渣；但对巫毒和炼金术的研习者来说，它是一种强效试剂，蕴含着当地掠食者的野性精华。",al={"什么是夜行虎须","夜行虎须介绍","夜行虎须是什么"}},["8f61da64"]={q="夜行虎须来自哪里？",a="夜行虎须取自暮光奔行者，这种掠食性猫科动物原生于石爪山脉。它们并非由凡人之手制作，而是直接从石爪峰附近出没的野兽身上拔取的。",al={"夜行虎须的来历","哪里能获得夜行虎须","谁会掉落夜行虎须"}}},fp="16,163,24.415.0,34.114.0,40.163.0,49.166.1"}
P.entries["item:twitching-antenna"] = {n="颤抖的触角",s="颤抖的触角是从入侵南贫瘠之地的其拉虫群身上采集到的断裂感知附肢。陶拉祖营地的牛头人战士鲁迦·狂暴图腾正在收集这些触角，它们能证明年轻战士在触角残留的神经颤动消失前的速度与战斗能力。",h="颤抖的触角是从入侵南贫瘠之地的其拉虫群身上采集到的断裂感知附肢。陶拉祖营地的牛头人战士鲁迦·狂暴图腾正在收集这些触角，它们能证明年轻战士在触角残留的神经颤动消失前的速度与战斗能力。",kw={"触角","贫瘠之地","陶拉祖营地","巨人旷野","鲁迦·狂暴图腾","其拉虫","颤抖的触角"},ang={["class:Hunter"]="在严格的时间限制内追踪、击杀并采集刚被杀死的其拉虫，是考验猎人速度、荒野追踪能力和战场杀伤力的经典试炼。",["race:Tauren"]="陶拉祖营地的猎人们认为，其拉虫的突然出现是对平原自然平衡的严重破坏，需要年轻的勇士们保持警惕。"},sec={{t="狩猎的证明",b="这些触角直接从其拉虫幼虫、虫群卫士和收割者的头部切下，即便在脱离身体后仍保留着残留的神经反射。一旦切断与昆虫宿主的联系，它们猛烈的抽搐并不会持续太久。正因为这种短暂的生命力，带回依然在颤抖的触角是对速度的严格考验，要求申请者在南部荒野狩猎野兽，并在触角停止抽动前冲回灌木丛林。"},{t="南部的威胁",b="这些触角不仅仅是成年礼的一部分，更是令人不安的预兆。其拉虫并非贫瘠之地的原生物种，它们最近在巨人旷野挖掘出的土丘令陶拉祖营地的猎人们深感不安。鲁迦·狂暴图腾要求收集这些样本，既是为了研究这一新出现的威胁，同时也是为了让部落的勇士们做好准备，应对步步紧逼的外来威胁。"}},faq={{q="哪些生物会掉落颤抖的触角？",a="它们是从滋扰南贫瘠之地的其拉虫身上采集的，包括栖息在巨人旷野巨大化石骨架周围的其拉虫幼虫、收割者、虫群卫士和爬行者。",al={"颤抖的触角哪里掉落","颤抖的触角是谁掉落的","其拉虫触角来源"}},{q="为什么触角必须是颤抖的？",a="持续的颤动证明这些样本是刚刚采集到的。鲁迦·狂暴图腾利用这种快速的生命力衰竭来测试申请者在野外地形中的战斗效率和速度。",al={"为什么要颤抖的","为什么要急着收集触角","巨人旷野试炼时限"}},{q="谁在寻找这些触角？",a="驻扎在南贫瘠之地陶拉祖营地的牛头人战士鲁迦·狂暴图腾，他需要这些触角作为巨人旷野试炼的一部分。",al={"谁需要颤抖的触角","谁接收触角"}},{q="巨人旷野在哪里？",a="巨人旷野位于贫瘠之地陶拉祖营地的正南方，那里有从地表突出的巨大骨骸，以及周围涌现出的奇异其拉虫巢穴，非常容易辨认。",al={"巨人旷野在哪里","巨人旷野位置"}}},fp="17,208,17.398.0,23.324.0,39.121.0,41.168.0,34.130.0,29.147.0"}
P.entries["item:ukor-s-burden"] = {n="乌克尔的货物",s="乌克尔的货物是一个沉重的口粮包，由一名好心的兽人苦工从剃刀岭运出。本意是为试炼谷中饥饿的新兵提供食物，但这些不受欢迎的补给必须在荒野的蝎卵虫和迅猛龙闻到气味之前运回去。",h="乌克尔的货物是一个沉重的口粮包，由一名好心的兽人苦工从剃刀岭运出。本意是为试炼谷中饥饿的新兵提供食物，但这些不受欢迎的补给必须在荒野的蝎卵虫和迅猛龙闻到气味之前运回去。",kw={"杜隆塔尔","格罗斯克","苦工","口粮","剃刀岭","乌克尔","试炼谷"},ang={["faction:Horde"]="这个差事体现了萨尔的部落在杜隆塔尔强制执行的严格的生存主义文化：即使是简单的善意也必须服从于磨练新兵所需的严酷试炼。"},sec={{t="一个出于好心的错误",b="兽人苦工很少会主动采取行动，这使得乌克尔的差事显得不同寻常。他背负着从剃刀岭旅店打包的沉重补给，冒着杜隆塔尔的红尘和具有攻击性的野生动物，试图帮助在试炼谷训练的年轻新兵。令他沮丧的是，监工和教官拒绝了他——他们认为艰苦和饥饿才能锻造出真正的战士。被困在峡谷口外，又害怕着尾随在返回路上的野兽，乌克尔将货物托付给过往的旅人，希望将其送回给旅店老板格罗斯克。"}},faq={{q="乌克尔的货物里有什么？",a="这是一个沉重的包裹，装满了从剃刀岭旅店拿走的食物和补给。乌克尔收集这些口粮是希望能喂饱正在进行入伍训练的年轻兽人和巨魔，却不知道训练场刻意限制外部的物资供应。",al={"背包里有什么","乌克尔的货物内容物","是什么食物"}},{q="为什么试炼谷拒绝了这些食物？",a="负责试炼谷的监工认为，耐力和匮乏能磨练年轻战士的性格。正如旅店老板格罗斯克所说，让受训的新兵挨饿可以磨练精神，因此外界的施舍是不受欢迎的。",al={"为什么试炼谷拒绝食物","为什么他们不想要这些食物","为什么不需要这些食物"}},{q="货物需要被送到哪里？",a="这些补给应该回到剃刀岭旅店的货架上。你必须直接把背包交给旅店老板格罗斯克，他会安全地把补给重新放回库存，并为把货物运回来的好心人提供一杯饮料。",al={"我该把乌克尔的货物带到哪里","谁想要乌克尔的货物","乌克尔的货物运送"}}},fp="13,102,26.491.0,29.184.0,45.182.0,33.157.0"}
P.entries["item:uncloven-satyr-hoof"] = {n="完整的萨特之蹄",s="完整的萨特之蹄是一种肿胀、坚硬的蹄子，取自潜伏在灰谷的萨特。这些残酷的战利品因吸取了古老森林中腐化的魔法能量而变得饱和，成为了暗矛巨魔护甲匠们强有力的制造材料。",h="完整的萨特之蹄是一种肿胀、坚硬的蹄子，取自潜伏在灰谷的萨特。这些残酷的战利品因吸取了古老森林中腐化的魔法能量而变得饱和，成为了暗矛巨魔护甲匠们强有力的制造材料。",kw={"灰谷","杜隆塔尔","护手","蹄子","萨特","森金","尤拉莱克","完整的"},ang={["class:Warrior"]="寻求声望的年轻战士被部落训练师指引去森金村定制护甲，通过猎杀灰谷的萨特来证明他们的勇武。",["race:Troll"]="像尤拉莱克这样的暗矛工匠擅长将黑暗或敌对的能量转化为功能性装备，从恶魔敌人身上汲取力量，而不是任其浪费。"},sec={{t="汲取的能量",b="萨特出没于灰谷东北部腐化的树林中，直接吞噬古老森林的魔法纯净。当它们沉溺于这种精华时，腐化会扭曲它们恶魔般的生理结构，导致它们的蹄子肿胀并失去原本的分叉。这些坚硬、完整的蹄子变成了密集的能量蓄水池，蕴含着不稳定的力量，可以被技艺精湛的萨满和制皮师所利用。"},{t="打造残酷护甲",b="在杜隆塔尔沿海的森金村，巨魔护甲匠尤拉莱克知道如何将恶魔的腐化转化为部落勇士的力量。通过获取这些饱食的萨特的蹄子，他汲取出封存在其中的森林魔法，将窃取来的力量注入到残酷护手的手工锻造中，旨在保护面对卡利姆多严酷考验的年轻战士们。"}},faq={{q="为什么这些萨特之蹄是完整的？",a="灰谷的萨特不断地吞噬森林的神圣魔法，腐化并汲取其力量。那些贪婪吞噬了最多精华的萨特，其蹄子会严重肿胀并失去分叉，将浓缩的、窃取来的能量封存在内。",al={"为什么它们没有分叉","完整的蹄子含义","肿胀的蹄子"}},{q="去哪里可以找到完整的萨特之蹄？",a="它们收集自栖息在灰谷东北部腐化废墟和受污染树林中的萨特，例如萨提纳尔和夜道谷。",al={"哪里刷蹄子","萨特之蹄位置","哪些萨特掉落蹄子"}},{q="在杜隆塔尔有谁需要这些蹄子？",a="尤拉莱克，一位住在杜隆塔尔南海岸森金村的工匠，需要七个蹄子来提取其中储存的魔法。",al={"谁需要萨特之蹄","萨特之蹄任务发布者","蹄子怎么用"}},{q="这些蹄子被用来制作什么？",a="尤拉莱克从蹄子中抽出腐化的森林之力，用于附魔并锻造一副坚固的、注入魔法的残酷护手。",al={"它们有什么用处","蹄子制造奖励","残酷护手材料"}}},fp="19,174,13.343.0,25.332.0,36.215.0,41.140.0,34.131.0,34.110.0"}
P.entries["item:underbelly-whelp-scale"] = {n="雏龙的腹鳞",s="腹部幼龙鳞片采集自漫游在赤脊山的黑龙军团的幼崽。由于其坚韧而柔软的质地，它们受到工匠们的青睐，是当地手艺人之间珍贵的易货材料。",h="腹部幼龙鳞片采集自漫游在赤脊山的黑龙军团的幼崽。由于其坚韧而柔软的质地，它们受到工匠们的青睐，是当地手艺人之间珍贵的易货材料。",kw={"阿古斯","黑龙幼崽","湖畔镇","赤脊山","怒焰","腹部鳞片","雏龙的腹鳞","弗纳·奥斯古"},ang={["faction:Alliance"]="湖畔镇孤立的守军严重依赖与艾尔文森林的物资交换，这使得诸如龙鳞这类危险的当地悬赏成为维持城镇补给的关键。",["profession:Blacksmithing"]="像阿古斯这样的工匠看重这些鳞片，因为这种奇异的爬行动物外皮可以被加工成衬里、握把和特殊的防护配件，其强度远超普通的牛皮。"},sec={{t="一种稀有的贸易商品",b="龙皮和龙鳞拥有传奇般的耐久度，但成年的黑龙对普通人来说过于致命。因此，机智的边境居民和工匠们将目光投向了止水湖南方的天空，那里有幼年黑龙在岩架上筑巢。虽然幼龙的背板质地脆弱或粗糙，但其柔软腹部的鳞片在灵活性与防御力之间达到了理想的平衡。因此，这些腹部鳞片在区域贸易中具有相当高的价值，既是高端制作材料，也是可靠的债务抵押物。"},{t="弗纳的债务",b="在湖畔镇，当金币短缺或贸易路线受阻时，治安官手下的工匠们往往不得不依靠以物易物。当地的铁匠弗纳·奥斯古因一批从闪金镇运来的马蹄铁而欠下了铁匠阿古斯一大笔债。由于知道阿古斯对稀有贸易品情有独钟，弗纳依靠过往的冒险者采集腹部幼龙鳞片来偿还债务，以维持他的工坊正常运转。"}},faq={{q="腹部幼龙鳞片来自哪里？",a="它们采集自黑龙幼崽和诸如“怒焰”之类的成熟幼龙，这些生物栖息在赤脊山湖畔镇南方的岩石悬崖和山丘中。",al={"谁掉落腹部幼龙鳞片","在哪里获得幼龙鳞片","如何找到幼龙鳞片"}},{q="为什么弗纳·奥斯古需要这些鳞片？",a="弗纳欠闪金镇铁匠阿古斯一笔进口马蹄铁的债。阿古斯接受龙鳞作为付款，而任何多余的鳞片都能为弗纳提供制作坚韧防护装备所需的原材料。",al={"为什么弗纳需要鳞片","弗纳·奥斯古 腹部鳞片"}},{q="为什么腹部鳞片比普通的龙鳞更受青睐？",a="幼龙的腹部鳞片足够柔软，可以进行切割、塑形并缝制成实用的护甲或加固装备，而背部鳞片往往过于坚硬、厚重或扭曲，不适合标准的制皮和锻造工艺。",al={"为什么选择腹部鳞片","腹部鳞片有什么特别之处"}},{q="为什么赤脊山会有黑龙幼崽？",a="黑龙军团在燃烧平原与赤脊山接壤的焦灼山峰和岩架上一直保持着活动，利用高耸且难以到达的悬崖来孵化和抚养后代。",al={"为什么赤脊山有龙","赤脊山 黑龙幼崽"}}},fx={["4599dc10"]={q="什么是雏龙的腹鳞？",al={"什么是雏龙的腹鳞","雏龙的腹鳞物品","雏龙鳞片背景"}}},fp="22,185,22.427.0,13.421.0,43.209.0,41.209.0,63.226.0,47.189.0"}
P.entries["item:unidentified-ore"] = {n="未经化验的矿石",s="未经化验的矿石是荆棘谷地精在石爪山脉的峭壁中开采时发现的一种奇特矿物样本。它由心怀不满的劳工匹兹尼克收集，被偷偷运走，交由地精技师吉兹·菲兹克斯进行分析，随后又被转交给锈水财阀的工程师。",h="未经化验的矿石是荆棘谷地精在石爪山脉的峭壁中开采时发现的一种奇特矿物样本。它由心怀不满的劳工匹兹尼克收集，被偷偷运走，交由地精技师吉兹·菲兹克斯进行分析，随后又被转交给锈水财阀的工程师。",kw={"匹兹尼克","石爪山脉","锈水财阀","未经化验的矿石","荆棘谷地精","狂风峭壁","吉兹·菲兹克斯"},ang={["profession:Engineering"]="地精科技依赖于发现具有独特反应性能的原始化合物，因此从荒野峭壁中获得的未分类矿石是创新技师的首选研究材料。",["profession:Mining"]="在狂风峭壁进行挖掘的矿工随处可见普通的矿脉，但这种奇特的矿物样本却超出了常见的贸易常识，连锈水财阀最优秀的鉴定师也对其深感好奇。"},sec={{t="狂风峭壁的奇特矿脉",b="荆棘谷地精在狂风峭壁进行的无情滥砍滥伐和露天采矿作业深深地破坏了石爪山脉的岩层，从而暴露出了异常的矿层。该采矿点的现任主管格伦佐·扳手哨下令开采大量的一种奇异的金绿色矿石，而遭到降职的地精工人匹兹尼克，因为依然效忠于被解雇的前任主管吉兹·菲兹克斯，在谋划逃离该组织时私藏了一块样本。样本被转交给一位前往峭壁西侧山脊的旅人，最终落入吉兹·菲兹克斯之手。他计划将这一战利品运回锈水财阀进行研究，同时截留一小块据为己有，以谋取私人利益。"}},faq={{q="什么是未经化验的矿石？",a="这是在狂风峭壁的荆棘谷地精作业期间挖掘出的一种未分类的地质标本。其成分非常神秘，足以引起技师吉兹·菲兹克斯以及锈水财阀采矿工程师的好奇。",al={"这种矿石是什么","未经化验的矿石背景故事","这是什么石头"}},{q="是谁发现了这种矿石？",a="驻扎在狂风峭壁的荆棘谷地精匹兹尼克回收了这个样本。由于担心近期事故后遭到公司主管的报复，他利用这块矿石作为逃跑和寻求新工作的筹码。",al={"是谁挖掘出来的","谁提供了矿石","匹兹尼克的矿石"}},{q="是谁试图研究这个样本？",a="驻扎在狂风峭壁西侧边缘的进取型地精吉兹·菲兹克斯接收了这种矿物。他打算将大部分矿石转交给锈水财阀的工程师，同时自己截留一小部分。",al={"谁想要这种矿石","谁在分析它","吉兹·菲兹克斯的矿石"}},{q="为什么锈水财阀关心这块石头？",a="地精一直在寻找新的爆炸物、冶金原料或可燃材料。在卡利姆多的古老山脉中挖掘出的奇异矿物，对贸易财阀而言具有巨大的工业和商业潜力。",al={"锈水财阀的兴趣","为什么地精想要它"}}},fx={["4673b3b7"]={q="未经化验的矿石来自哪里？",a="这份样本来自石爪山脉狂风峭壁的荆棘谷地精矿坑。矿坑的新头目格伦佐·扳钳命令大量开采一种奇异的金绿色矿石。匹兹尼克仍忠于被解雇的前任老板齐兹·菲兹克斯，于是偷偷开采了一份样本，准备交给齐兹。",al={"未经化验的矿石的来历","在哪里发现未经化验的矿石","矿石来自哪里"}}},fp="16,153,29.538.0,29.185.0,18.203.0,35.184.0,41.195.0"}
P.entries["item:unrefined-ore-sample"] = {n="未精炼的矿石样本",s="未精炼的矿石样本是一种不寻常的原始矿物，由居住在千针石林的碎石狗头人开采。陶拉祖营地的武器大师塔特纳克·钢炉正在寻找这种矿石，以评估其是否能被锻造成适合萨尔酋长军队的精良武器。",h="未精炼的矿石样本是一种不寻常的原始矿物，由居住在千针石林的碎石狗头人开采。陶拉祖营地的武器大师塔特纳克·钢炉正在寻找这种矿石，以评估其是否能被锻造成适合萨尔酋长军队的精良武器。",kw={"陶拉祖营地","吉布斯尼克","碎石","狗头人","矿石","塔特纳克·钢炉","千针石林","未精炼的矿石样本"},ang={["faction:Horde"]="卡利姆多南部每一处新的矿脉都代表着萨尔建立的新兴国家在巩固边疆时实现军事自给自足的潜力。",["profession:Blacksmithing"]="铁匠们理解塔特纳克的挫败感；分析新矿石的韧性和耐用性对于为战士们装备在战斗中不会碎裂的利刃至关重要。"},sec={{t="害虫开采",b="在贫瘠之地以南，千针石林的峡谷峭壁之中，一个被称为碎石的狗头人氏族正在岩石和泥土中无休止地挖掘。穿过贫瘠之地向北的旅行者带回了消息，声称在被杀死的害虫身上发现了一种奇怪的矿物——一种与卡利姆多各地常见的矿脉截然不同的未精炼的矿石。尽管这些旅行者拒绝将他们的战利品交给部落，但千针石林的地下挖掘者和勘探者们正直接从挖掘现场携带这种矿石的原始矿块。"},{t="为酋长锻造",b="在陶拉祖营地，武器大师塔特纳克·钢炉直接在萨尔酋长的命令下工作，为部落开发更强大的军械。塔特纳克对那些隐瞒矿藏信息的旅行者感到愤怒，认为这是对部落战争努力的侮辱。通过获得矿石的原始样本，钢炉旨在测试其抗拉强度和韧性，希望能将其熔炼并打造出一把足以获得奥格瑞玛认可的原型利刃。"}},faq={{q="这种未精炼的矿石来自哪里？",a="这种矿石由碎石狗头人携带，包括挖掘者、勘探者以及他们的首领吉布斯尼克，他们居住在贫瘠之地以南的千针石林峡谷深处。",al={"矿石位置","在哪里获得未精炼的矿石样本","谁掉落未精炼的矿石"}},{q="为什么塔特纳克·钢炉想要一个样本？",a="塔特纳克正在执行酋长的指令，以改善部落的武器装备。他希望检查并熔炼这种矿石，以确定其强度是否足以锻造出新的部落武器。",al={"为什么塔特纳克想要矿石","矿石在陶拉祖的用途","矿石是用来做什么的"}},{q="为什么旅行者不愿将其交出？",a="从千针石林穿越而来的部落旅行者在狗头人身上发现了这种矿石，并将其作为战利品或稀奇之物保留了下来，即使在被要求为部落的锻造事业做出贡献时也拒绝出售。",al={"旅行者是谁","旅行者 矿石 贫瘠之地"}},{q="在贫瘠之地的任何地方能找到这种矿石吗？",a="不能。虽然请求来自南贫瘠之地的陶拉祖营地，但矿石本身必须从更南边的千针石林的狗头人那里获得。",al={"贫瘠之地的矿石","你能在贫瘠之地采矿吗"}}},fp="20,190,19.361.0,24.384.0,40.159.0,45.162.0,49.189.0,42.124.0"}
P.entries["item:ur-s-treatise-on-shadow-magic"] = {n="乌尔的暗影魔法研究论文",s="《乌尔的暗影魔法研究论文》是一本危险的奥术典籍，由达拉然著名的法师乌尔所著。这本被施了魔法的书最初由暴风城的法师们负责保管，后来被叛逃的术士摩根斯窃取，并藏在了伊尔加拉之塔中。",h="《乌尔的暗影魔法研究论文》是一本危险的奥术典籍，由达拉然著名的法师乌尔所著。这本被施了魔法的书最初由暴风城的法师们负责保管，后来被叛逃的术士摩根斯窃取，并藏在了伊尔加拉之塔中。",kw={"安多玛斯","达拉然","伊尔加拉","摩根斯","赤脊山","密室","暗影魔法","典籍","论文","乌尔"},ang={["class:Mage"]="对于暴风城的法师们来说，收回乌尔的论文是为了进行遏制，在其中一人屈服于黑暗诱惑后，维护密室的安全。",["faction:Alliance"]="摩根斯在赤脊山的存在威胁着王国的东部边境，因此收回这件强大的神器对暴风城的安全至关重要。"},sec={{t="危险的遗产",b="这篇论文由达拉然学者乌尔所著，深入探讨了暗影魔法微妙且具有腐蚀性的本质。由于钻研此类魔法会给未经训练者带来厄运和毁灭，暴风城巫师密室的法师们在书上施加了保护封印，禁止任何人阅读其中的内容。然而，当术士摩根斯堕入黑暗魔法并被驱逐出城市的法师圈子后，他偷走了这本典籍，带着它向东逃往赤脊山，躲进了他在伊尔加拉之塔的据点中。"},{t="被封印的秘密",b="高阶法师安多玛斯担心摩根斯可能会掌握乌尔所保存的黑暗知识，于是派遣冒险者突袭伊尔加拉之塔，夺回这本被窃的著作。尽管摩根斯野心勃勃并深深陷入了禁忌魔法之中，但暴风城法师圈子所施加的封印依然牢不可破，确保了在收回之前，这篇论文从未被打开过。"}},faq={{q="乌尔是谁？",a="乌尔是一位来自达拉然的受人尊敬的法师和学者，他将大部分研究精力都用于探索位面生物、黑暗艺术和深奥魔法，包括暗影技艺。",al={"谁写了这本书","达拉然的乌尔","乌尔是谁"}},{q="为什么这篇论文如此危险？",a="正如高阶法师安多玛斯所警告的那样，暗影魔法的秘密并不适合未经训练的人。探究其禁忌的深渊很容易腐蚀施法者，并招致厄运与毁灭。",al={"为什么这本书很危险","这本书有什么作用","暗影魔法的危险"}},{q="是谁偷走了《乌尔的暗影魔法研究论文》？",a="摩根斯，暴风城法师组织的前成员，在屈服于黑暗魔法的诱惑而被放逐后，他偷走了这本典籍并退守至赤脊山的伊尔加拉之塔。",al={"谁偷了这本书","摩根斯偷走的书","谁拿走了论文"}},{q="摩根斯读过这篇论文吗？",a="没有。暴风城法师们在典籍上施加的保护封印坚固无比，在典籍被收回之前，摩根斯无法将其打开。",al={"摩根斯读过它吗","封印有效吗","书被打开过吗"}},{q="这和《乌尔之书》是同一部作品吗？",a="它们是同一作者创作的紧密相关的作品。虽然《乌尔之书》是一部保存在影牙城堡废墟中的综合性魔典，但《暗影魔法研究论文》似乎是一篇摘录或专门针对暗影技艺的专业著作。",al={"与乌尔之书的区别","影牙城堡的乌尔之书","这是乌尔之书吗"}}},fp="29,167,18.397.0,18.299.1,11.140.0,33.143.0,40.147.0,41.113.1,40.218.0"}
P.entries["item:urgent-message"] = {n="紧急信件",s="紧急信件是一份由卫兵穆赫·月角撰写的密封公文，警告乱风岗在千针石林日益严重的半人马暴力活动。这封信由前往峡谷的旅行者携带，提醒牛头人驻军他们的补给线和侦察队正面临直接威胁。",h="紧急信件是一份由卫兵穆赫·月角撰写的密封公文，警告乱风岗在千针石林日益严重的半人马暴力活动。这封信由前往峡谷的旅行者携带，提醒牛头人驻军他们的补给线和侦察队正面临直接威胁。",kw={"卫兵穆赫·月角","半人马","峭壁卫兵图林·长角","乱风岗","升降梯","grimtotem","千针石林","紧急信件"},ang={["faction:Horde"]="该信强调了部落在卡利姆多南部补给线的脆弱性，那里孤立的前哨站依赖于信使和勇士在充满敌意的地形中生存。",["race:Tauren"]="对于牛头人来说，这封信是对他们与半人马之间古老血仇的痛苦提醒，同时也让他们对自己的Grimtotem族人日益感到不安。"},sec={{t="来自高处的警告",b="这份紧急信件由在升降梯附近（从贫瘠之地通往千针石林）的卫兵穆赫·月角撰写，代表了穿越边境的旅行者的第一道防线。月角监视着下方的锯齿状峡谷，好战的半人马部族在那里恢复了对部落交通线的无情突袭。这封信寄给了乱风岗顶部的峭壁卫兵图林·长角，对那些在关键道路附近进行危险攻击的胆大妄为的袭击者发出了警报，敦促当地驻军为持续的冲突做好准备，并防范像不可预测的Grimtotem氏族这样的次要威胁。"},{t="峡谷底部的流血事件",b="当信件被送达乱风岗高耸平顶之上的峭壁卫兵图林·长角手中时，它证实了该定居点最担心的恐惧。半人马的袭击已经不仅仅是边境冲突了；袭击者伏击了一支穿越峡谷底部的关键补给车队，屠杀了整个车队。这份公文迫使牛头人领导层立即从防御性的警惕转为积极的报复，触发有组织的还击，以便在乱风岗完全与卡利姆多其余地区隔绝之前平定这些掠夺成性的部族。"}},faq={{q="紧急信件里写了什么？",a="信中详细描述了千针石林半人马突袭活动的急剧增加，警告旅行队伍和道路正处于迫在眉睫的危险之中，并敦促乱风岗为战争做好准备。",al={"信里说了什么","紧急信件内容","信件内容是什么"}},{q="这封信是谁写的，谁收到了它？",a="它是由驻扎在从贫瘠之地通往千针石林的升降梯处的卫兵穆赫·月角起草的，并直接寄给乱风岗的指挥官峭壁卫兵图林·长角。",al={"谁写了紧急信件","紧急信件发送者","谁收到了紧急信件"}},{q="为什么半人马要攻击补给车队？",a="半人马部族长期以来一直在卡利姆多中部与牛头人争夺干旱的土地。他们突袭峡谷底部的车队，以掠夺重要的补给物资，并阻止部落在千针石林的安全通行。",al={"为什么半人马要袭击","千针石林半人马动机","为什么半人马要掠夺"}},{q="侦察兵关于Grimtotem给出了什么警告？",a="卫兵穆赫·月角告诫任何携带该公文的信使要避开附近的Grimtotem氏族，并指出他们的战士对其他牛头人的态度越来越冷漠和可疑。",al={"grimtotem警告","为什么要避开grimtotem","grimtotem举止异常"}}},fx={d8ee5ef2={q="什么是紧急信件？",a="紧急信件是一封由卫兵穆赫·月角在千针石林边境附近写下并封好的信函。信中报告了峡谷底部半人马的敌意骤然加剧，提醒牛头人当局，威胁当地旅人和补给线的危险正在不断扩大。",al={"什么是紧急信件","紧急信件物品","紧急公文"}},["1e5b60e5"]={q="为什么需要把紧急信件送到乱风岗？",a="峭壁卫兵图林·长角负责乱风岗的防御，需要立即掌握敌人的动向。这封信警告他，半人马劫掠者的袭击愈发频繁，好让他及时采取果断行动，避免更多补给车队和巡逻队遭到伏击和屠杀。",al={"为什么要递送紧急信件","谁需要紧急信件","峭壁卫兵图林·长角为什么需要信件"}}},fp="14,302,26.615.0,29.548.1,38.187.0,43.160.0,46.218.0,57.211.0"}
P.entries["item:valdred-s-hands"] = {n="瓦德雷的手掌",s="瓦德雷的手掌是瓦德雷·莫雷被截断的肢体，是在他死于银松森林南部后被取下的。幽暗城的拉林夫·安迪恩想要得到它们，将其作为一件令人毛骨悚然的战利品，以此证明他为妻子的遇害复了仇。",h="瓦德雷的手掌是瓦德雷·莫雷被截断的肢体，是在他死于银松森林南部后被取下的。幽暗城的拉林夫·安迪恩想要得到它们，将其作为一件令人毛骨悚然的战利品，以此证明他为妻子的遇害复了仇。",kw={"丈夫的复仇","迪莉娅","格雷迈恩之墙","拉林夫·安迪恩","银松森林","瓦德雷","瓦德雷·莫雷","瓦德雷的手掌"},ang={["race:Undead"]="对瓦德雷的手掌的需求体现了被遗忘者冷酷、复仇的本性，他们经常将自己无法感受传统悲伤的能力转化为持久的、偏执的怨恨。"},sec={{t="一个可怕的背叛纪念品",b="在瘟疫吞噬洛丹伦之前，瓦德雷·莫雷和拉林夫·安迪恩曾是挚友。当瓦德雷谋杀了拉林夫的妻子迪莉娅后，这份情谊彻底破裂。尽管拉林夫在死后作为一名被遗忘者复生——声称自己无法再产生真正的悲伤——但那种对复仇的渴望从未从他心中消散。当瓦德雷试图逃往南方，越过格雷迈恩之墙进入吉尔尼斯时，拉林夫派遣了一名使者去终结他这位前挚友的逃亡，并要求带回他的断手作为大功告成的确凿证据。"},{t="苦涩的回忆",b="在收到断手后，拉林夫交出了他亡妻的刻字戒指，将其视为毫无意义的小饰品。因为迪莉娅对他而言已经死去太久了，他从那些过去伤感的纪念物中找不到任何慰藉。相反，他保留了瓦德雷的手掌，作为一种持久而冰冷的背叛提醒和复仇终结的象征。"}},faq={{q="瓦德雷·莫雷是谁？",a="瓦德雷·莫雷生前曾是拉林夫·安迪恩的挚友。他背叛了这份友谊，谋杀了拉林夫的妻子迪莉娅，随后试图向南逃往吉尔尼斯。",al={"谁是瓦德雷","瓦德雷·莫雷背景故事","瓦德雷的故事"}},{q="为什么拉林夫·安迪恩特别想要瓦德雷的手掌？",a="拉林夫想要这双手，因为它们曾是勒死或杀害他妻子的凶器。以被遗忘者的方式，他将它们作为他朋友背叛以及他所执行复仇的实物战利品保存下来。",al={"为什么是手掌","为什么是瓦德雷的手掌","拉林夫的手掌战利品"}},{q="瓦德雷·莫雷在哪里？",a="瓦德雷位于银松森林南部，徘徊在格雷迈恩之墙高耸的门边，试图逃入孤立的王国吉尔尼斯。",al={"瓦德雷在哪里","瓦德雷位置","瓦德雷·莫雷刷新点"}},{q="将手掌带到幽暗城后会发生什么？",a="拉林夫将这些手掌保存在幽暗城，作为他复仇完成的永久纪念，同时丢弃了他亡妻的戒指，视其为无用的饰品。",al={"拉林夫怎么处理手掌","交付瓦德雷的手掌"}}},fp="15,181,29.443.0,20.253.1,22.163.0,59.188.0,29.101.0,59.146.1"}
P.entries["item:velinde-s-journal"] = {n="维林德的日记",s="《维林德的日记》是暗夜精灵牧师维林德·星歌所保留的个人记录，存放于达纳苏斯的哨兵宿舍中。日记中记载了她职责的关键记录，以及她离开这座城市时周围发生的神秘状况。",h="《维林德的日记》是暗夜精灵牧师维林德·星歌所保留的个人记录，存放于达纳苏斯的哨兵宿舍中。日记中记载了她职责的关键记录，以及她离开这座城市时周围发生的神秘状况。",kw={"达纳苏斯","哨兵","塞恩提尔·刃纹","贸易区","维林德·星歌","维林德的日记","维林德的钥匙","维林德的储物柜"},ang={["class:Priest"]="维林德·星歌是一位成就斐然的牧师，她隐藏的职责和随后的失踪揭示了The Sisterhood of Elune所面临的令人不安的考验。",["race:NightElf"]="一位受人尊敬的艾露恩姐妹的神秘离去触动了达纳苏斯的高层，引发了守卫卡多雷首都的哨兵们的担忧。"},sec={{t="牧师的记录",b="当维林德·星歌牧师离开达纳苏斯时，她的私人物品被锁在了贸易区的哨兵宿舍内的一个储物箱里。在她存放的物品中，有一本她的个人日记，记录了她在悄然离去之前的责任和职责。虽然哨兵们非常敬重维林德，并认为她只是有私事要处理，但日记的内容表明，她那无法解释的失踪比最初想象的要令人担忧得多。"}},faq={{q="《维林德的日记》在哪里？",a="这本日记位于达纳苏斯贸易区哨兵宿舍内维林德的箱子里。进入该建筑需要穿过与锁甲商铺相连的上层桥梁。",al={"日记位置","维林德的日记在哪里","维林德的储物柜位置"}},{q="维林德·星歌是谁？",a="维林德·星歌是一位受人尊敬的暗夜精灵牧师，深受哨兵们的信任。她在悄无声息的情况下突然离开了达纳苏斯，留下了她的储物柜和物品。",al={"维林德是谁","维林德背景故事"}},{q="为什么哨兵们关心她的日记？",a="哨兵们起初以为维林德因自己的正当理由离开了达纳苏斯，并且会回来。然而，通过她的文字发现关于她离去的线索后，揭示了她的失踪带有更令人不安的意味，需要进一步调查。",al={"为什么哨兵想要日记","日记里有什么"}},{q="谁让你去取回这本日记？",a="在得知《梅尔珊德里斯之书》中的信息后，达纳苏斯的哨兵塞恩提尔·刃纹会允许你并提供开启维林德箱子的钥匙。",al={"谁给予任务","塞恩提尔·刃纹是谁"}}},fp="17,174,20.425.0,33.179.0,25.169.0,44.217.0,37.174.0"}
P.entries["item:velinde-s-key"] = {n="维林德的钥匙",s="维林德的钥匙是一把由达纳苏斯的塞恩提尔·刃纹委托给冒险者的小钥匙。它能打开哨兵宿舍内的一个个人储物柜，里面存放着维林德·星歌女祭司在神秘失踪前留下的文字记录。",h="维林德的钥匙是一把由达纳苏斯的塞恩提尔·刃纹委托给冒险者的小钥匙。它能打开哨兵宿舍内的一个个人储物柜，里面存放着维林德·星歌女祭司在神秘失踪前留下的文字记录。",kw={"达纳苏斯","储物柜","哨兵宿舍","塞恩提尔·刃纹","维林德·星歌","维林德的遗物","维林德的日记","维林德的钥匙"},ang={["class:Priest"]="调查维林德遗物的祭司们追寻着这位忠诚的艾露恩姐妹的足迹，她的道路却走向了孤独和令人不安的方向。",["race:NightElf"]="对于暗夜精灵来说，处理维林德的物品是一件敏感的事情，因为她曾是一位受人尊敬的女祭司，她对艾露恩和她族人的忠诚是不容置疑的。"},sec={{t="信任的信物",b="这把简单的钥匙由达纳苏斯的塞恩提尔·刃纹保管，用于存放维林德·星歌女祭司的个人物品。维林德在未发出警告的情况下离开了暗夜精灵的领地，她的人世财物被安全地存放在贸易区上方的哨兵宿舍内的一个小柜子里。刃纹只会将钥匙交给那些能够提供合法证据（例如在梅尔·珊瑞斯之书揭露的启示）的人，以证明他们真正关心这位女祭司的命运。"},{t="解开过去",b="这把钥匙可以打开维林德的储物箱，里面保存着记录她职责和困扰思绪的日记。虽然哨兵们长期以来一直认为维林德只是因为私事而离开，总有一天会回来，但被这把钥匙锁住的文字开始揭开围绕她那次灾难性远征的更黑暗、更令人困惑的谜团。"}},faq={{q="维林德的钥匙可以打开什么？",a="它能打开维林德的储物柜。那是一个位于达纳苏斯哨兵宿舍内的箱子，在贸易区穿过一座桥后的楼上。",al={"维林德的钥匙在哪里使用","维林德的储物柜","这个箱子能打开什么"}},{q="谁会给你这把钥匙？",a="在调查维林德失踪案期间，驻扎在达纳苏斯的哨兵塞恩提尔·刃纹会将这把钥匙委托给你。",al={"谁有维林德的钥匙","到哪里获取维林德的钥匙"}},{q="维林德·星歌是谁？",a="维林德·星歌是一位受哨兵信任的受人尊敬的暗夜精灵女祭司。她突然因私事离开，将财物留在了达纳苏斯。",al={"维林德是谁","维林德的背景故事"}},{q="在她锁住的箱子里发现了什么？",a="储物柜里放着维林德的日记，这是一份关于她职责的个人记录，揭示了是什么迫使她离开了暗夜精灵的领地。",al={"维林德的储物柜里有什么","维林德储物柜的内容"}}},fp="13,176,15.443.0,18.300.1,29.155.0,22.137.0,24.161.0,38.128.0"}
P.entries["item:venomtail-antidote"] = {n="毒尾蝎解毒剂",s="毒尾蝎解毒剂是一种专门调制的药剂，用于中和杜隆塔尔毒尾蝎的致命毒素。它由奥格瑞玛的考格汉配制，是用来救治林纳格的紧急药物，林纳格是一位被困在杜隆塔尔西北边界附近的巨魔斥候。",h="毒尾蝎解毒剂是一种专门调制的药剂，用于中和杜隆塔尔毒尾蝎的致命毒素。它由奥格瑞玛的考格汉配制，是用来救治林纳格的紧急药物，林纳格是一位被困在杜隆塔尔西北边界附近的巨魔斥候。",kw={"解毒剂","cleft of shadow","治疗","杜隆塔尔","考格汉","奥格瑞玛","林纳格","蝎子","毒尾蝎"},ang={["faction:Horde"]="即使在杜隆塔尔的核心地带，这片无情的沙漠也在考验着年轻的部落冒险者，这需要荒野斥候和城市药剂师之间进行快速配合。",["race:Troll"]="巨魔的自尊心根深蒂固，林纳格宁愿冒着独自死在荒野的风险，也不愿因为被蝎子打败而面对森金村的公开嘲笑。"},sec={{t="与毒素赛跑",b="杜隆塔尔的荒芜大地遍布着危险的野生生物，其中对粗心的流浪者来说，当地的蝎子最为致命。被毒尾蝎深深蛰伤后会注入一种剧毒，足以在不到一小时内杀死一名成年战士。当巨魔林纳格在西北边界附近远离援助的地方中毒时，他唯一的生存希望就是从考格汉那里获得专门的药物，考格汉是一位隐居在奥格瑞玛地下的暗影裂口深处的药剂师。"},{t="考格汉的药方",b="要获得这种解毒剂，必须深入奥格瑞玛的下层地带找到考格汉。考格汉精通沙漠毒素和各种强效药方，他配制了这种药剂以在毒素致命前将其清除。药剂送达后，能阻止毒素扩散，让林纳格免于在荒野中屈辱地死去——尽管考格汉要求这位斥候进行更多的试炼和狩猎，以补偿他的大意。"}},faq={{q="毒尾蝎解毒剂有什么用？",a="这种解毒剂可以中和毒尾蝎造成的致命毒素。它是专门为救治林纳格而寻得的，这位中毒的巨魔被困在杜隆塔尔西北边界，生命垂危。",al={"解毒剂用途","谁需要毒尾蝎解毒剂","毒尾蝎解毒剂的作用"}},{q="谁酿制了毒尾蝎解毒剂？",a="这种解毒剂由考格汉配制，他居住在奥格瑞玛下方的暗影裂口。他了解杜隆塔尔蝎子的毒性，知道如何抵消它们的蛰伤。",al={"谁制作了这种解毒剂","在哪获取毒尾蝎解毒剂","考格汉的解毒剂"}},{q="为什么获取解毒剂的时间如此紧迫？",a="毒尾蝎的毒素会迅速随血液扩散，林纳格从被蛰那一刻起剩下的生命不到一小时。获取解毒剂并火速赶回杜隆塔尔是防止他死亡的唯一途径。",al={"为什么需要抓紧时间","林纳格还有多少时间","毒尾蝎毒素计时器"}},{q="为什么林纳格不愿去森金村寻求帮助？",a="林纳格承认被普通的蝎子蛰伤是件非常丢脸的事。他害怕以虚弱的状态回到森金村，认为族人会嘲笑他的粗心和愚蠢。",al={"为什么不去森金村","林纳格的自尊","为什么躲在杜隆塔尔"}}},fp="18,191,24.249.0,15.342.0,40.168.0,33.136.0,52.144.0,55.158.0"}
P.entries["item:venomtail-poison-sac"] = {n="毒尾蝎的毒囊",s="毒尾蝎的毒囊是一种从杜隆塔尔干旱荒原原生的蝎虫身上采集到的生物器官。虽然它含有足以让粗心大意的猎人丧失行动能力的剧毒，但它同时也是酿制特效解毒剂的关键原料。",h="毒尾蝎的毒囊是一种从杜隆塔尔干旱荒原原生的蝎虫身上采集到的生物器官。虽然它含有足以让粗心大意的猎人丧失行动能力的剧毒，但它同时也是酿制特效解毒剂的关键原料。",kw={"解毒剂","杜隆塔尔","考格汉","毒药","林纳格","囊","蝎虫","毒尾蝎"},ang={["class:Hunter"]="林纳格的不幸遭遇为猎人们敲响了警钟：在不了解野兽毒性或未携带相应解药的情况下追捕危险生物，极易让追踪者付出生命的代价。",["faction:Horde"]="在杜隆塔尔学习残酷生存法则的部落年轻冒险者很快就会发现，想要活下去就必须了解野生生物，因为当地的毒素能轻易夺去那些冒失地闯入赤色荒原之人的生命。"},sec={{t="剧毒与解药",b="在杜隆塔尔的赤色石地带游荡的蝎虫——主要是毒尾蝎，以及像腐化蝎虫和臭名昭著的死亡剥皮者这样的变异品种——能分泌一种起效迅速且会造成衰弱的毒素。这种毒液储存在特殊的尾囊中，如果得不到治疗，即使是经验丰富的战士也会很快被击倒。具有讽刺意味的是，正是这些能释放致命一刺的毒囊中，包含了合成解毒剂所需的主要化合物。当猎人林纳格在奥格瑞玛外被蛰伤时，当地的炼金术士需要四个新鲜的毒囊来调配出中和其体内毒素的解药。"}},faq={{q="哪些生物带有这些毒囊？",a="它们是从杜隆塔尔的蝎虫身上采集到的，主要是出没在奥格瑞玛郊外的毒尾蝎，以及腐化蝎虫和稀有的死亡剥皮者。",al={"谁掉落毒尾蝎的毒囊","哪里获得毒尾蝎的毒囊","哪些蝎虫有毒囊"}},{q="毒囊有什么用途？",a="这些毒囊会被带到奥格瑞玛的考格汉那里，用于蒸馏出一种特殊的解毒剂。这种解药对于治疗猎人林纳格来说迫在眉睫，他因为在没有做好充分准备的情况下进行狩猎而被蛰伤中毒。",al={"毒尾蝎毒囊用途","为什么我需要毒尾蝎的毒囊"}},{q="谁能用这些毒囊酿制解毒剂？",a="位于奥格瑞玛的考格汉掌握着正确的方法，能将四个完整毒囊中的原生毒液提炼成治疗药剂，从而在毒发身亡前挽救生命。",al={"谁酿制解毒剂","哪里上交毒尾蝎毒囊","考格汉 毒尾蝎"}}},fp="20,127,29.453.0,39.142.0,32.176.0,42.131.0"}
P.entries["item:venture-co-documents"] = {n="风险投资公司文件",s="这些紧紧捆绑在一起的文件是在莫高雷东部一辆被破坏的货车的木箱中找到的。它们详细记录了荆棘谷地精的行动，证实了这个掠夺成性的卡特尔组织在牛头人家园内进行的非法露天采矿活动。",h="这些紧紧捆绑在一起的文件是在莫高雷东部一辆被破坏的货车的木箱中找到的。它们详细记录了荆棘谷地精的行动，证实了这个掠夺成性的卡特尔组织在牛头人家园内进行的非法露天采矿活动。",kw={"摩林·云行者","莫高雷采矿","被破坏的货车","风险投资公司文件","荆棘谷地精"},ang={["profession:Mining"]="这些文件被发现与原始矿石样本装在一起，证明了山麓地区蕴藏着丰富的、有待挖掘的矿脉。",["race:Tauren"]="大地之母神圣的土地正受到地精机械的玷污。递交这些文件有助于长者确认亵渎的程度，并展开反击。"},sec={{t="剥削的证据",b="这些文件在被洗劫一空的货车残骸中，被压在开采出的矿石和矿物之上，揭露了荆棘谷地精侵入莫高雷的规模。这个地精领导的卡特尔组织以残酷的毁林和无节制的挖掘在卡利姆多臭名昭著，他们已悄然在东部山麓建立了钻探和采矿前哨站。摩林·云行者和牛头人斥候依靠这些缴获的账本来评估对他们神圣祖先平原的威胁，并召集猎人将这些入侵者赶走。"}},faq={{q="风险投资公司文件里有什么内容？",a="这叠文件概述了荆棘谷地精在莫高雷东部的采矿和开采工作，揭示了该地精企业正在积极开采并运走该地区的自然矿产资源。",al={"风险投资公司文件内容","什么是风险投资公司文件","文件写了什么"}},{q="这些文件是在哪里发现的？",a="它们是从血蹄村以东的被破坏的货车遗址中，在一辆被洗劫的货车残骸里发现的一个密封的风险投资公司木箱中找回的。",al={"我在哪里可以找到文件","风险投资公司文件位置","被破坏的货车木箱"}},{q="谁需要看这些文件？",a="它们必须被送到摩林·云行者手中，他是一位驻扎在血蹄村以东主干道旁的牛头人猎人，负责守护莫高雷的安全。",al={"我应该把文件交给谁","提交风险投资公司文件","摩林·云行者文件"}},{q="为什么荆棘谷地精要在莫高雷采矿？",a="荆棘谷地精纯粹是为了利润而运作，他们寻找富含矿脉和未经开发的领土，掠夺宝贵的矿石，完全无视原住民条约、精神习俗或环境。",al={"为什么地精在莫高雷","风险投资公司在莫高雷的目标","为什么风险投资公司要挖掘"}}},fp="21,185,24.464.0,42.176.0,38.145.0,30.149.0,46.194.0"}
P.entries["item:venture-co-engineering-plans"] = {n="风险投资公司工程计划书",s="风险投资公司工程计划书是存放在狂风峭壁地精伐木场中的机械蓝图。联盟特工在回收这些蓝图后发现，它们详细记录了正在破坏石爪山脉的重型机械的内部构造。",h="风险投资公司工程计划书是存放在狂风峭壁地精伐木场中的机械蓝图。联盟特工在回收这些蓝图后发现，它们详细记录了正在破坏石爪山脉的重型机械的内部构造。",kw={"秘密行动","峭壁湖","工程计划书","加克希姆·尘链","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["profession:Engineering"]="荆棘谷地精那些粗暴且贪婪的资源掠夺装置或许缺乏精致感，但它们的机械蓝图却包含着关于重型工业机械的宝贵见解。",["race:Gnome"]="对侏儒修理工来说，夺取竞争对手地精的设计图既是一场智力上的胜利，也是一个充满可供改良的工业点子的宝库。"},sec={{t="工业机密",b="狂风峭壁烟雾缭绕，到处都是荆棘谷地精用来掠夺石爪山脉森林的伐木机械。这些工程蓝图藏在峭壁湖南岸的伐木场内，详细展示了他们专用的伐木装置的构造、优势和缺陷。"},{t="侏儒间谍活动",b="侏儒工程师加克希姆·尘链策划了一次秘密行动，旨在破坏荆棘谷地精的伐木作业并获取这些文件。虽然安放炸药可以带来即时的破坏，但获得这些蓝图能让联盟工匠系统性地利用地精装备的结构弱点，并将他们的创新设计改良用于联盟的项目中。"}},faq={{q="风险投资公司工程计划书位于哪里？",a="这些计划书存放在位于石爪山脉狂风峭壁、峭壁湖南岸的荆棘谷地精主要伐木场内。",al={"工程计划书在哪里找到","石爪山脉计划书位置","计划书在哪里"}},{q="谁需要这些工程计划书？",a="加克希姆·尘链，一位在石爪山脉协调秘密行动的联盟侏儒，派遣特工前去回收它们。",al={"谁需要计划书","谁交付工程计划书","加克希姆·尘链计划书"}},{q="为什么这些蓝图对联盟很重要？",a="这些设计图揭示了荆棘谷地精伐木机械的关键设计缺陷，使特工能更有效地将其拆解，同时也为联盟侏儒提供了可以融入其自身发明的工业设计。",al={"为什么要偷计划书","计划书有什么用"}},{q="偷窃这些计划书与什么行动有关？",a="获取这些计划书是“秘密行动——阿尔法”的主要目标。虽然任务包括在整个场地安放雷管，但带回这些蓝图才标志着行动的真正成功。",al={"秘密行动阿尔法目标","这是什么任务的物品"}}},fx={["605bae91"]={q="什么是风险投资公司工程计划书？",al={"什么是风险投资公司工程计划书","风险投资公司工程计划书","风险投资公司计划书"}},a84a85f7={q="风险投资公司工程计划书从何而来？",a="这些计划书源自风险投资公司在狂风峭壁的工业活动。公司工程师和操作员为监督伐木与机械建造而制定了这些计划，并将其妥善保存在峭壁湖以南不远处的主伐木场内，之后成为联盟秘密行动人员的目标。",al={"工程计划书从何而来","谁制作了风险投资公司工程计划书","风险投资公司计划书来源"}}},fp="29,160,18.274.0,17.295.1,52.157.0,34.127.0,51.184.0,47.175.0"}
P.entries["item:venture-co-letters"] = {n="风险投资公司函件",s="“风险投资公司函件”是从石爪山脉的狂风矿洞中缴获的内部通讯。在爆炸造成的混乱掩护下，这些信件被窃取出来，为暗夜精灵哨兵部队提供了关于该地区地精工业运作的关键情报。",h="“风险投资公司函件”是从石爪山脉的狂风矿洞中缴获的内部通讯。在爆炸造成的混乱掩护下，这些信件被窃取出来，为暗夜精灵哨兵部队提供了关于该地区地精工业运作的关键情报。",kw={"凯拉·影矛","哨兵","石爪山脉","风险投资公司","风险投资公司函件","狂风峭壁","狂风矿洞"},ang={["faction:Alliance"]="联盟侦察兵协调针对荆棘谷地精的秘密行动，以保护石爪山脉的暗夜精灵领地免受掠夺性的工业开发。",["race:NightElf"]="地精伐木机对石爪山脉的亵渎直击卡利姆多荒野的核心，使得关于荆棘谷地精阴谋的情报对哨兵部队而言至关重要。"},sec={{t="工业情报",b="狂风峭壁已被荆棘谷地精占领，他们的伐木机和露天采矿作业正在摧毁古老的林地。为了揭露该财阀的全部野心，联盟特工展开了秘密破坏行动，通过制造混乱潜入了狂风矿洞。这些缴获的信件包含了详细记录该公司当地活动的私人通讯和后勤档案，让哨兵指挥官能够洞察这些污染者是如何组织其劳动力和补给线的。"},{t="交给哨兵",b="一旦从矿洞深处获取这些信件，它们就会被迅速送回给哨兵指挥官凯拉·影矛。面对石爪山脉中来自地精污染者和部落入侵的双重压力，哨兵部队依靠这些窃取的信件来预判荆棘谷地精的下一步行动，并保护这片神圣山脉中幸存的部分。"}},faq={{q="什么是“风险投资公司函件”？",a="它们是荆棘谷地精保存在石爪山脉狂风矿洞中的内部运营文件和通讯记录。",al={"风险投资公司函件","什么是这些信件","石爪山脉信件"}},{q="这些信件在哪里可以找到？",a="它们位于狂风峭壁东端狂风矿洞内所存放的“风险投资公司文件”之中。",al={"信件在哪里","信件位置","狂风矿洞信件"}},{q="谁想要这些信件？",a="侏儒特工加克希姆·尘链负责监督窃取这些信件的秘密行动，它们最终会被交给领导当地暗夜精灵哨兵部队的凯拉·影矛。",al={"谁获得了这些信件","谁想要它们","上交信件"}},{q="为什么哨兵需要这些通讯记录？",a="哨兵部队正在努力阻止石爪山脉遭到肆无忌惮的滥砍滥伐和挖掘。这些信件揭示了荆棘谷地精的后勤规划和运营重点，帮助守卫者制定针对他们的战略。",al={"为什么哨兵想要信件","哨兵的兴趣"}}},fx={["52f3029e"]={q="风险投资公司函件从何而来？是谁写的？",al={"风险投资公司函件来源","谁写了风险投资公司函件","这些函件从何而来"}}},fp="19,203,23.392.0,25.311.1,33.146.0,28.104.0,24.157.0,46.169.0"}
P.entries["item:verdant-note"] = {n="绿色便笺",s="绿色便笺是一份送达纳拉其营地新手牛头人德鲁伊的传唤令。它由德鲁伊导师加尔特·迷雾行者发出，指示年轻的入门者前去报到，开始学习大地母亲的仪式。",h="绿色便笺是一份送达纳拉其营地新手牛头人德鲁伊的传唤令。它由德鲁伊导师加尔特·迷雾行者发出，指示年轻的入门者前去报到，开始学习大地母亲的仪式。",kw={"纳拉其营地","德鲁伊","大地母亲","加尔特·迷雾行者","莫高雷","红云台地","绿色便笺"},ang={["class:Druid"]="这张羊皮纸标志着你正式被牛头人德鲁伊教派接纳，开始了你与大地母亲沟通的终生旅程。",["race:Tauren"]="对于舒哈鲁人来说，德鲁伊之道是一种与治愈莫高雷神圣狩猎场的平衡直接相关的先祖召唤。"},sec={{t="召唤之路",b="在红云台地开始试炼后不久，展现出与自然精神契合度的年轻牛头人就会收到绿色便笺。这封简短的信函由加尔特·迷雾行者派遣的信使携带，指示入门者前往纳拉其营地向导师报到。躁动的灵魂和变幻的元素已经开始困扰莫高雷，使得教导新德鲁伊成为长老们的一项紧迫任务。"},{t="大地母亲的教诲",b="在回应便笺后，入门者将被引入自然共鸣的深层奥秘之中。加尔特·迷雾行者告诫年轻的德鲁伊，虽然暗夜精灵与荒野有着共同的纽带，但他们古老的傲慢使他们保持疏远且不那么友好。牛头人德鲁伊教义严格专注于对大地母亲的崇敬，引导入门者倾听土地上躁动的先祖之声，并作为她的活体工具为她服务。"}},faq={{q="什么是绿色便笺？",a="这是一份送达纳拉其营地初出茅庐的牛头人德鲁伊的书面传唤令，指示他们去寻找当地的训练师加尔特·迷雾行者，以正式开始他们的精神教育。",al={"绿色便笺物品","这个便笺是什么"}},{q="谁发送了绿色便笺？",a="这封便笺是由一名信使代表加尔特·迷雾行者发送的，他是驻扎在红云台地纳拉其营地的德鲁伊训练师。",al={"谁发送了绿色便笺","谁写了绿色便笺"}},{q="为什么加尔特·迷雾行者要召唤德鲁伊入门者？",a="莫高雷及周边地区的先祖之灵变得异常躁动。加尔特需要新觉醒的德鲁伊尽快受训，以便他们能与荒野之灵沟通，并治愈受到干扰的土地。",al={"为什么加尔特要找我","加尔特·迷雾行者的理由"}},{q="加尔特关于暗夜精灵对德鲁伊说了什么？",a="加尔特警告说，尽管暗夜精灵与自然有着神圣的纽带，但他们非常傲慢，不太可能欢迎牛头人加入他们的圈子。他建议入门者将注意力集中在大地母亲的教诲上。",al={"暗夜精灵与牛头人德鲁伊","关于暗夜精灵"}}},fp="12,158,18.328.0,28.329.0,25.135.0,27.126.0,51.162.0,53.189.0"}
P.entries["item:verdant-sigil"] = {n="绿色符记",s="绿色符记是一枚镌刻过的德鲁伊信物，颁发给在幽影谷开始训练的暗夜精灵德鲁伊新手。这枚信物作为德鲁伊导师玛丹特·硬木的召唤令，标志着新学员正式进入奥达希尔枝叶下的塞纳里奥教义学习。",h="绿色符记是一枚镌刻过的德鲁伊信物，颁发给在幽影谷开始训练的暗夜精灵德鲁伊新手。这枚信物作为德鲁伊导师玛丹特·硬木的召唤令，标志着新学员正式进入奥达希尔枝叶下的塞纳里奥教义学习。",kw={"奥达希尔","德鲁伊","翡翠梦境","ilthalaine","玛丹特·硬木","幽影谷","泰达希尔","绿色符记"},ang={["class:Druid"]="对于年轻的暗夜精灵德鲁伊来说，收到绿色符记是传统的成人礼，它架起了从基础森林护理到严谨的塞纳里奥教导之间的桥梁。",["race:NightElf"]="这枚符记在奥达希尔的树冠下颁发，代表了卡多雷将个人的灵魂与自然世界以及泰达希尔的守护者们相协调的悠久传统。"},sec={{t="通往之路的召唤",b="在幽影谷受庇护的树枝间，感受到荒野召唤的年轻暗夜精灵会从管理员伊尔萨莱恩那里收到绿色符记。这枚信物由导师玛丹特·硬木派信使送达，指引新手攀登至大树奥达希尔的枝干上。携带这枚符记意味着正式受邀放下基础杂务，开始认真学习如何与自然之灵交流，并钻研翡翠梦境的深奥谜团。"},{t="迈入梦境的第一步",b="将符记交给玛丹特·硬木，年轻的德鲁伊便开启了他们终身的修行。虽然新手尚未准备好进入翡翠梦境的沉睡幻象，但确认这枚符记标志着师徒关系的开始。在玛丹特的指导下，学员们学习解读荒野的低语，并掌握初步的变形术和治疗艺术，以服务于泰达希尔。"}},faq={{q="绿色符记有什么用途？",a="绿色符记是发给幽影谷暗夜精灵德鲁伊新手的入门信物。它充当了训练师玛丹特·硬木的正式召唤，指引新德鲁伊前往奥达希尔树中寻找他，以开始他们的正规教育。",al={"绿色符记有什么用","我为什么有绿色符记","绿色符记的使用"}},{q="谁分发绿色符记？",a="管理员伊尔萨莱恩在萌芽期的德鲁伊们开始协助他处理幽影谷的事务后不久，就会转交玛丹特·硬木送来的口信，并将符记交给他们。",al={"谁给予绿色符记","我从哪里获得绿色符记"}},{q="收到符记后我该去哪里？",a="你需要将符记带给位于幽影谷中心的大树奥达希尔的内部密室中的德鲁伊训练师玛丹特·硬木。",al={"我该把绿色符记带到哪里","谁会收取绿色符记","绿色符记上交"}},{q="将符记交给玛丹特·硬木后会发生什么？",a="玛丹特会收下符记，正式欢迎你成为他的学生。他将确立自己作为你掌握自然共鸣的向导，并承诺随着你力量的增长，将为你准备好应对翡翠梦境中错综复杂的挑战。",al={"玛丹特用符记做什么","绿色符记之后做什么"}}},fp="13,116,21.387.0,29.365.0,41.133.0,32.119.0,44.127.0,61.185.0"}
P.entries["item:verna-s-westfall-stew-recipe"] = {n="弗娜的杂味炖肉食谱",s="“弗娜的杂味炖肉食谱”是一份手写的烹饪指南，由弗娜·法布隆在准备逃离西部荒野时所写。它被托付给前往寻找萨尔玛·萨丁的旅行者，在乡村日益崩溃的环境中保留了一道丰盛的地方主食。",h="“弗娜的杂味炖肉食谱”是一份手写的烹饪指南，由弗娜·法布隆在准备逃离西部荒野时所写。它被托付给前往寻找萨尔玛·萨丁的旅行者，在乡村日益崩溃的环境中保留了一道丰盛的地方主食。",kw={"烹饪","法布隆","食谱","萨丁农场","萨尔玛·萨丁","弗娜·法布隆","杂味炖肉"},ang={["faction:Alliance"]="这份食谱代表了忠诚的联盟农户因无法无天的环境而被驱逐的悲惨流离，同时也反映了暴风城在维护统治力方面的困境。",["profession:Cooking"]="对于烹饪爱好者来说，这份手写文件是一件珍贵的当地传说，即使在农场纷纷倒闭的情况下，它也守护了西部荒野的饮食遗产。"},sec={{t="一份告别礼物",b="随着迪菲亚兄弟会在西部荒野横行霸道，失控的收割机人四处肆虐，像弗娜和农夫法布隆这样的老住户被迫放弃了他们的土地。在等待修理马车以便逃往暴风城的同时，弗娜写下了她钟爱的杂味炖肉配方。她不愿让这份食谱随着他们的离去而消失，于是将其托付给过往的旅行者，请他们转交给她的邻居兼好友萨尔玛·萨丁，以确保那些留下来的人们依然能享受到这份温暖而熟悉的慰藉。"}},faq={{q="为什么弗娜要送出她的炖肉食谱？",a="弗娜和她的丈夫正在逃离西部荒野，因为他们的田地已经被强盗和失控的机器所占领。由于知道自己必须离开农田，她希望她的朋友萨尔玛·萨丁能继续为留下来的人们制作这道炖肉。",al={"为什么弗娜给出食谱","为什么是杂味炖肉食谱","弗娜食谱的目的"}},{q="这份食谱是给谁的？",a="这份食谱是写给萨尔玛·萨丁的，她就住在萨丁农场道路岔路口之外的地方。",al={"谁收到这份食谱","我要把食谱交给谁","炖肉食谱要去哪里"}},{q="法布隆一家计划去哪里？",a="法布隆一家正在等待修理他们的马车，以便逃往暴风城寻求安全，远离威胁着乡村的混乱和匪患。",al={"法布隆一家要去哪里","弗娜去哪里","法布隆目的地"}},{q="是什么让杂味炖肉在这一地区如此特别？",a="杂味炖肉是当地的一种主食，其食材源于当地的农业和猎物。在食物短缺、农场被废弃的困难时期，分享这种丰盛的食谱有助于幸存的农户家庭共渡难关。",al={"什么是杂味炖肉","为什么杂味炖肉很重要","杂味炖肉传说"}}},fp="28,152,15.463.0,41.219.0,28.106.0,39.167.0,47.172.0"}
P.entries["item:verner-s-note"] = {n="弗纳的便笺",s="“弗纳的便笺”是一份由湖畔镇的铁匠弗纳·奥斯古亲笔书写的征用函，被送往闪金镇的铁匠阿古斯手中。便笺中详细说明了赤脊山铁矿严重短缺的情况，并请求这位艾尔文森林的铁匠紧急支援一些马蹄铁。",h="“弗纳的便笺”是一份由湖畔镇的铁匠弗纳·奥斯古亲笔书写的征用函，被送往闪金镇的铁匠阿古斯手中。便笺中详细说明了赤脊山铁矿严重短缺的情况，并请求这位艾尔文森林的铁匠紧急支援一些马蹄铁。",kw={"闪金镇","马蹄铁","湖畔镇","赤脊山","铁匠阿古斯","马蹄铁的代价","弗纳·奥斯古","弗纳的便笺"},ang={["faction:Alliance"]="这份便笺强调了暴风城农村基础设施所承受的压力，说明了像湖畔镇这样的边境城镇必须与腹地村庄协调，才能维持供应线的运转。",["profession:Blacksmithing"]="这封信件凸显了边境战争的后勤状况：当武器和盔甲消耗了所有的金属锭时，像马蹄铁这样的日常必需品就必须从像闪金镇这样更安全的定居点进口。"},sec={{t="钢铁的请求",b="维持湖畔镇的防御需要耗费大量的金属加工制品。由于驻扎在镇上的暴风城卫兵在抵御入侵的豺狼人和当地威胁时捉襟见肘，弗纳·奥斯古几乎耗尽了他所有的铁储备来为士兵们提供武器和护甲。结果，湖畔镇的马厩因缺乏基本的马蹄铁而逐渐荒废。这封信代表了弗纳放下自尊，请求闪金镇的铁匠阿古斯提供一批预制好的马蹄铁，以维持镇上马匹的正常使用。"}},faq={{q="弗纳的便笺上写了什么？",a="这份便笺向铁匠阿古斯解释说，弗纳为了给湖畔镇的暴风城卫兵装备武器已经耗尽了所有的金属储备。由于他没有多余的铁来为当地的马匹锻造马蹄铁，因此他请求从闪金镇直接运送一批马蹄铁过来。",al={"弗纳的便笺内容","便笺上说了什么","弗纳的便笺信息"}},{q="弗纳·奥斯古是谁？",a="弗纳·奥斯古是在赤脊山的湖畔镇经营铁匠铺的当地铁匠。他负责为镇上的防御者配备装备，并确保工作用具和牲畜得到蹄铁护理。",al={"弗纳是谁","赤脊山的弗纳·奥斯古"}},{q="谁收到了这封便笺？",a="这封便笺被沿着大路向西送到了铁匠阿古斯手中，他是在艾尔文森林的闪金镇打铁铺外挥舞铁锤的城镇铁匠。",al={"谁收到了弗纳的便笺","我应该把便笺带到哪里","铁匠阿古斯是谁"}},{q="为什么弗纳不能自己制作马蹄铁？",a="由于豺狼人和其他地区威胁的侵扰，湖畔镇正处于危机之中。弗纳将他所有的时间和生铁都投入到了为暴风城卫兵锻造武器和进行维修的工作中，导致马厩那边没有任何存货可用。",al={"为什么湖畔镇需要马蹄铁","为什么要向闪金镇索要马蹄铁"}}},fx={["486dfee9"]={q="弗纳的便笺是什么？",a="这是一封由湖畔镇当地铁匠弗纳·奥斯古亲笔写的信，收信人是闪金镇的铁匠阿古斯。信中说明，为了装备当地的暴风城卫兵以应对日益加剧的地区威胁，湖畔镇的铁匠铺已经耗尽了铁料，因此无力为镇上马厩里的马匹打造马掌。这封信是一份正式的申请，请求阿古斯提供一箱马掌以解燃眉之急。",al={"弗纳的便笺","这张便笺是什么","弗纳便笺的用途"}},b8effef9={q="弗纳的便笺来自哪里？是谁写的？",a="这封便笺由弗纳·奥斯古亲自在赤脊山湖畔镇的铁匠铺写下。周边的豺狼人和兽人不断来犯，镇卫队疲于应对，弗纳也因此承受着不断增加的武器需求。他写下这封信，向艾尔文森林的同行安排一批紧急物资。",al={"谁写了弗纳的便笺","弗纳的便笺来自哪里","弗纳便笺的来源"}},c0af4e8d={q="为什么有人需要弗纳的便笺？",a="便笺向铁匠阿古斯说明弗纳·奥斯古的铁料短缺，并请求借用五十对马掌，直到弗纳收到下一批铁料。送达便笺后，阿古斯便能为湖畔镇的马厩安排援助。",al={"阿古斯为什么需要弗纳的便笺","谁需要弗纳的便笺","为什么要送弗纳的便笺"}}},fp="13,171,15.434.0,33.215.0,21.159.0,23.120.0,45.168.0"}
P.entries["item:verog-s-head"] = {n="维罗戈的头颅",s="维罗戈的头颅是从科卡尔半人马的重要领袖——狂风维罗戈身上取下的恐怖战利品，他负责统领死水绿洲周边的部队。兽人雷加·死门搜寻此物，以此作为该首领丧命的证明，并以此打击那些威胁着贫瘠之地的激进科卡尔部族。",h="维罗戈的头颅是从科卡尔半人马的重要领袖——狂风维罗戈身上取下的恐怖战利品，他负责统领死水绿洲周边的部队。兽人雷加·死门搜寻此物，以此作为该首领丧命的证明，并以此打击那些威胁着贫瘠之地的激进科卡尔部族。",kw={"贫瘠之地","半人马","科卡尔","雷加·死门","死水绿洲","维罗戈","狂风维罗戈","维罗戈的头颅"},ang={["faction:Horde"]="铲除维罗戈并取得他的头颅，保障了十字路口与贫瘠之地南部地区之间的部落路线免受半人马的侵袭。",["race:Tauren"]="击败科卡尔首领对牛头人有着深远的影响，因为他们的族人世世代代都在忍受着卡利姆多半人马部族的残酷战争。"},sec={{t="绿洲的战利品",b="科卡尔半人马对贫瘠之地北部的部落旅行者和补给路线构成了无休止的威胁。狂风维罗戈以行踪不定而闻名，他在荒凉的灌木丛中游荡时，死水绿洲的指挥帐篷就会处于防守空虚的状态。为了引他现身，部落的特工会攻击他凉亭附近的部队，直至警报拉响。一旦维罗戈赶回营地进行防守，他就会被击杀并斩首。将他被砍下的头颅交给雷加·死门，是另一个危险的科卡尔首领被铲除的关键证据，这颗头颅随后会被陈列在巴拉克·科多班的头颅旁边。"}},faq={{q="狂风维罗戈是谁？",a="狂风维罗戈是盘踞在贫瘠之地死水绿洲的科卡尔半人马的机动军阀。他因经常在干旱的平原上四处游荡而闻名，并负责指挥驻扎在绿洲指挥帐篷周边的敌对半人马部队。",al={"维罗戈是谁","维罗戈背景故事","狂风维罗戈"}},{q="谁想要维罗戈的头颅？",a="这颗头颅由驻扎在十字路口以西营地的老兵兽人雷加·死门索要。雷加收集被杀死的科卡尔军阀的战利品，以此摧毁他们战团的实力和士气。",al={"谁收走维罗戈的头颅","雷加·死门 维罗戈","上交维罗戈的头颅"}},{q="在哪里可以找到维罗戈？",a="维罗戈的营地和指挥帐篷位于十字路口东南方的死水绿洲。他并不会一直待在凉亭里等待，只有杀掉守卫岗位的半人马并拉响警报，才能将他引回来。",al={"维罗戈在哪里","维罗戈位置","死水绿洲帐篷"}},{q="上交头颅后会发生什么？",a="雷加·死门将维罗戈的头颅与巴拉克·科多班的头颅放在一起，将这些可怕的残骸作为战利品展示，标志着部落对科卡尔领袖的系统性打击行动。",al={"雷加如何处理头颅","半人马头颅展示"}}},fp="12,202,21.496.0,26.172.0,23.179.0,21.175.0,47.122.0"}
P.entries["item:vial-of-innocent-blood"] = {n="无辜者之血",s="无辜者之血是一种阴森的炼金试剂，由潜伏在敦霍尔德城堡废墟中的辛迪加暗影法师收集。塔伦米尔的皇家药剂师协会对其趋之若鹜，它是酿制实验性毒素的关键催化剂。",h="无辜者之血是一种阴森的炼金试剂，由潜伏在敦霍尔德城堡废墟中的辛迪加暗影法师收集。塔伦米尔的皇家药剂师协会对其趋之若鹜，它是酿制实验性毒素的关键催化剂。",kw={"药剂师林度恩","敦霍尔德城堡","希尔斯布莱德丘陵","无辜者之血","辛迪加暗影法师","塔伦米尔"},ang={["faction:Horde"]="获取这种试剂有助于部落在石爪山脉对抗荆棘谷地精滥伐森林的更广泛领土行动。",["race:Undead"]="皇家药剂师协会很少会因为道德问题而对某种成分退避三舍，他们乐于从人类法外之徒那里搜刮材料，以推动他们的炼金术进步。"},sec={{t="一种可怕的试剂",b="在敦霍尔德城堡坍塌的城墙内，辛迪加堕落的人类贵族们进行着黑暗而邪恶的勾当。在他们之中，一些暗影法师为了自己的神秘仪式，有系统地收割无辜者的血液。这种恐怖的行径引起了塔伦米尔的药剂师林度恩的强烈关注。由于需要纯净的血液来酿制一种旨在消灭石爪山脉的荆棘谷地精的实验性镇静剂，这位被遗忘者药剂师将辛迪加的阴森库存视为他工作的便捷捷径。"}},faq={{q="无辜者之血有什么用？",a="塔伦米尔的药剂师林度恩利用这些血液酿制一种特殊的毒素，旨在抑制在石爪山脉给部落制造麻烦的荆棘谷地精的攻击性。",al={"无辜者之血用途","无辜者之血是做什么用的","无辜者血液的用途"}},{q="谁携带着这些药剂瓶？",a="它们由驻扎在希尔斯布莱德丘陵东南部敦霍尔德城堡废墟周围的辛迪加暗影法师携带。",al={"谁掉落无辜者之血","哪里可以获得无辜者之血","辛迪加暗影法师"}},{q="为什么辛迪加暗影法师会有无辜者之血？",a="辛迪加的人类强盗和堕落贵族雇佣了暗影施法者，收割并保存无辜者的血液，用于他们自己黑暗且邪恶的魔法实验。",al={"为什么辛迪加有血液","辛迪加血液仪式"}},{q="为什么药剂师林度恩需要无辜者的血液？",a="林度恩指出，来自无辜者的血液拥有特定的稀有属性，这是配制一种能够消除受害者暴力倾向并使其变得温顺的药剂所必需的。",al={"为什么要用无辜者之血","药剂师林度恩的血液"}}},fp="22,176,18.377.0,44.168.0,24.124.0,50.139.0,52.136.0"}
P.entries["item:vial-of-phlogiston"] = {n="燃素",s="燃素是一种炼金物质，大师级护甲匠人常用它来淬炼异常坚韧的锁甲。它被严密地保存在剃刀沼泽的野猪人要塞中，是联盟和部落的铁匠锻造专门用于有前途的战士的战斗护甲时梦寐以求的材料。",h="燃素是一种炼金物质，大师级护甲匠人常用它来淬炼异常坚韧的锁甲。它被严密地保存在剃刀沼泽的野猪人要塞中，是联盟和部落的铁匠锻造专门用于有前途的战士的战斗护甲时梦寐以求的材料。",kw={"残暴护甲","烈焰锁甲","弗伦·长须","燃素","剃刀沼泽","roogug","thun'grim firegaze"},ang={["class:Warrior"]="获得燃素是赢取标志性淬火护甲的重要里程碑，证明了一名战士有能力攻克剃刀沼泽。",["profession:Blacksmithing"]="燃素代表了高级专业冶金术，是淬炼传奇锁甲的关键助熔剂。"},sec={{t="锻造精华",b="燃素是一种极易挥发、蕴含火焰能量的物质，在深奥的冶金术中极为珍贵。暴风城的矮人铁匠弗伦·长须和贫瘠之地近乎失明的兽人护甲匠人Thun'grim Firegaze都认为它是将战士护甲硬化至超越常理极限的不可或缺的材料。没有这种炼金药剂，锻造烈焰锁甲或部落的残暴护甲所需的特殊锻造技术就无法完成。"},{t="从荆棘中取回",b="要获得燃素，必须深入位于贫瘠之地南端的剃刀沼泽的纠缠丛林。这种燃素被地卜师Roogug保存在充满尖刺的堡垒深处。无论是为暴风城的弗伦·长须取回，还是带着它穿过尘土交给Thun'grim Firegaze的铁砧，这种物质都需要冒险进入充满敌意的野猪人领地。"}},faq={{q="燃素有什么用途？",a="大师级铁匠将燃素用作炼金淬火催化剂。它能提供将粗制的锁甲和铁锭硬化成异常坚固的战士护甲所需的极度浓缩的热量。",al={"燃素用途","燃素有什么用","为什么需要燃素"}},{q="谁持有燃素？",a="燃素由地卜师Roogug持有，他居住在南贫瘠之地剃刀沼泽那充满荆棘的隧道深处。",al={"谁掉落燃素","燃素掉落","燃素哪里获取"}},{q="哪些铁匠需要这种材料？",a="暴风城的弗伦·长须和贫瘠之地的Thun'grim Firegaze都需要燃素，以便为经验丰富的战士锻造独特的硬化护甲套装。",al={"谁需要燃素","燃素任务","哪些任务需要燃素"}}},fx={["3ab06e7f"]={q="燃素是什么？",a="燃素是一种极其稀有的炼金物质，以其高热和淬火特性而闻名，深受高级护甲匠重视。联盟和部落中专门从事锻造的铁匠都在寻求这种物质。它是一种关键催化剂，可用于打造坚韧、经过淬火的锁甲，供久经沙场的战士穿戴。",al={"燃素是什么","燃素的背景","燃素物品"}}},fp="18,178,20.391.0,27.322.0,28.155.0,35.121.0,35.148.0"}
P.entries["item:vial-of-purest-water"] = {n="一瓶最纯净的水",s="一瓶最纯净的水是一个圣洁的容器，由南贫瘠之地深处的隐士Brine所祝福。它被托付给了一位萨满学徒，其中净化的内容物是调配出感知那些难以捉摸的元素之灵所需的药剂的关键。",h="一瓶最纯净的水是一个圣洁的容器，由南贫瘠之地深处的隐士Brine所祝福。它被托付给了一位萨满学徒，其中净化的内容物是调配出感知那些难以捉摸的元素之灵所需的药剂的关键。",kw={"贫瘠之地","brine","call of water","水之先知伊斯伦","银松森林","一瓶最纯净的水","water sapta"},ang={["class:Shaman"]="获得并交付这瓶纯净的水，标志着你距离与水之灵沟通并领取你的水之图腾又近了一步。",["faction:Horde"]="围绕着这瓶水的试炼将年轻的部落萨满送往卡利姆多和东部王国各地，以加深他们与元素的羁绊。"},sec={{t="一份净化的祭品",b="在Brine的指导下，通过耐心和净化的试炼锻造而成，这瓶密封的水代表了未受腐蚀的元素本质。它被运送穿过贫瘠之地干旱的荒原，带回到水之先知伊斯伦守望的孤寂海岸，这瓶水是酿造Water Sapta的重要成分。没有它那纯净无瑕的特质，萨满就无法与那些远离太阳炙烤平原、居住在偏远之地的精神守护者进行沟通。"},{t="水之图腾的道路",b="伊斯伦不仅用这祝福过的液体来考验修行者的奉献精神，还用它来开启他们感知隐藏元素的感官。一部分水被混合进药剂中，以显现驻扎在银松森林远方神龛的灵魂，而剩余的几滴则被保留用于对抗和净化其他地方的流浪元素。携带这瓶水是抱负远大的神秘主义者从执行卑微杂务转向直接面对元素现实的转折点。"}},faq={{q="一瓶最纯净的水有什么用途？",a="这瓶水包含了交给萨满学徒的、经过精心净化和祝福过的水。水之先知伊斯伦利用这种液体来酿造Water Sapta，这是一种能赋予感知水元素所需的灵视的药剂，同时也用于获得水之图腾所需的后续仪式试炼。",al={"一瓶最纯净的水用途","这瓶水有什么用","最纯净的水的使用"}},{q="是谁准备了瓶中的水？",a="这些水是由萨满在Brine的指导下采集的，Brine是一位居住在南贫瘠之地深处的兽人萨满隐士。在通过各种试炼采集到水后，Brine会对这些纯净的水进行祝福并将其密封在瓶中以供运送。",al={"谁制作了这瓶水","谁装满了这瓶水","brine的水"}},{q="这瓶水需要被送到哪里？",a="这瓶水必须带回给水之先知伊斯伦，她居住在贫瘠之地的东海岸，棘齿城南面，俯瞰着无尽之海。",al={"我应该把水瓶交给谁","水瓶交付地点","上交最纯净的水"}},{q="交付水瓶后，仪式将指向何处？",a="一旦水之先知伊斯伦收到水瓶并酿造出药剂，她就会派遣萨满横跨海洋前往东部王国，具体地点是银松森林中位于幽暗城南边的一座神龛。",al={"我接下来要去哪里","水瓶之后的下一步","银松森林水之神龛"}}},fp="20,168,19.387.0,23.412.1,42.245.0,39.216.0,37.119.0,53.182.0"}
P.entries["item:vial-of-spider-venom"] = {n="瓶装蜘蛛毒液",s="瓶装蜘蛛毒液中蕴含着从肆虐暮色森林幽暗丛林的蛛形纲生物身上提取的强效坏死毒素。夜色镇的伊瓦夫人利用这种危险的萃取物，结合亡灵遗骸来制作抵御伤害的防护结界。",h="瓶装蜘蛛毒液中蕴含着从肆虐暮色森林幽暗丛林的蛛形纲生物身上提取的强效坏死毒素。夜色镇的伊瓦夫人利用这种危险的萃取物，结合亡灵遗骸来制作抵御伤害的防护结界。",kw={"夜色镇","暮色森林","伊瓦夫人","纳拉克西斯","隐蛛","蜘蛛毒液","惩罚图腾","瓶装蜘蛛毒液"},ang={["class:Rogue"]="虽然潜行者擅长酿造毒药并将其涂抹在刀刃上来进行暗杀，但这种未经提纯的原生蜘蛛毒液是用于神秘护盾，而非直接暗杀。",["faction:Alliance"]="对于在暮色森林阴暗道路上穿行的联盟冒险者来说，帮助伊瓦夫人制作她的防护图腾有助于保护旅行者免受森林恐怖生物的侵害。"},sec={{t="暮色森林的剧毒威胁",b="暮色森林阴影笼罩的灌木丛中栖息着可怕的蛛形纲生物——从飞速爬行的侏儒毒网蜘蛛、绿隐蛛，到黑寡妇以及臭名昭著的纳拉克西斯。这些生物能通过毒牙喷射出令人作呕且强效的毒液，其威力足以让旅者瘫痪并使血肉腐烂。敢于猎杀这些恐怖生物的冒险者可以提取出完好的黏稠毒液瓶。"},{t="制作惩罚图腾",b="在夜色镇，占卜师伊瓦夫人为踏入黑暗世界的旅者感知到了不祥的征兆。为了制作惩罚结界，她需要五瓶这种原生毒液，再配合食尸鬼毒牙和骷髅手指。经过她的技艺引导，毒液那种掠夺性、侵蚀性的本质被反转，凝结成惩罚图腾，将伤害反弹给任何攻击其持有者的人。"}},faq={{q="这种蜘蛛毒液来自哪里？",a="它采集自潜伏在暮色森林各处的各种掠食性蜘蛛，包括毒网蜘蛛、食腐隐蛛、绿隐蛛、黑寡妇幼蛛以及可怕的蛛母纳拉克西斯。",al={"蜘蛛毒液来源","谁掉落蜘蛛毒液","暮色森林蜘蛛毒液获取地点"}},{q="谁需要瓶装蜘蛛毒液？",a="夜色镇的驻地占卜师伊瓦夫人需要五瓶蜘蛛毒液，以及骷髅手指和食尸鬼毒牙来制作一种魔法结界。",al={"谁需要蜘蛛毒液","暮色森林蜘蛛毒液交任务","伊瓦夫人毒液"}},{q="这种毒液被用来制作什么？",a="伊瓦夫人将毒液与亡灵遗骸混合，附魔成惩罚图腾，这是一种旨在利用魔法对攻击者造成伤害的防御护身符。",al={"伊瓦制作什么","惩罚图腾材料","为什么要收集蜘蛛毒液"}},{q="为什么伊瓦夫人需要用危险的毒液来制作防护结界？",a="伊瓦的技艺经常运用同类相吸的魔法，利用森林掠食者和亡灵那致命的报复性特质，制作出能将暴力反作用于侵略者身上的护身符。",al={"为什么结界需要毒液","伊瓦图腾材料背景"}}},fx={cd5271e6={q="瓶装蜘蛛毒液是什么？",a="这是一小瓶从暮色森林肆虐的巨型蜘蛛身上采集的强烈腐蚀性毒液。它虽触之即毙，却深受当地秘术师和乡野女巫珍视；她们会用这种阴暗而剧毒的物质施展诅咒，或为护符附魔，使攻击者的恶意反噬自身。",al={"什么是蜘蛛毒液","瓶装蜘蛛毒液的背景","瓶装蜘蛛毒液是什么"}}},fp="20,143,26.258.0,32.352.0,39.177.0,32.129.0,32.136.0,63.143.0"}
P.entries["item:vicious-night-web-spider-venom"] = {n="邪恶夜行蜘蛛的毒液",s="邪恶夜行蜘蛛的毒液是一种强效的天然毒素，采集自盘踞在提瑞斯法林地东部的蛛形纲生物。皇家药剂师协会非常看重它，因为它具有一种奇特的能够携带并保存历史致病菌株的能力，这使其成为被遗忘者研发The New Plague的关键试剂。",h="邪恶夜行蜘蛛的毒液是一种强效的天然毒素，采集自盘踞在提瑞斯法林地东部的蛛形纲生物。皇家药剂师协会非常看重它，因为它具有一种奇特的能够携带并保存历史致病菌株的能力，这使其成为被遗忘者研发The New...",kw={"药剂师乔汉","布瑞尔","the new plague","蜘蛛毒液","提瑞斯法林地","毒蛛峡谷","邪恶夜行蜘蛛"},ang={["class:Rogue"]="熟悉处理天然神经毒素的潜行者们，可以理解皇家药剂师协会是如何将危险的野生毒液重新改造为工程生物武器的。",["race:Undead"]="对于被遗忘者来说，采集这种毒液是为希尔瓦娜斯女士的最高指令做出的直接贡献：研发出足以击败阿尔萨斯及其天灾军团的瘟疫。"},sec={{t="一种被保存的传染物",b="根据药剂师乔汉在布瑞尔进行的研究，古代文献记载了一场毁灭性的历史瘟疫，曾夺去了数以千计无辜受害者的生命。奇怪的是，那场被遗忘的爆发背后的传染媒介竟然通过寄宿在当地夜行蜘蛛的毒液中，存活了数个世纪。通过狩猎潜伏在血色修道院以南毒蛛峡谷中的邪恶物种，药剂师们提取出这种被保存的毒性，作为他们持续进行的炼金实验中的重要催化剂。"},{t="推动The New Plague",b="被遗忘者寻求一种对抗天灾军团和生者的武器。乔汉将这种毒液作为他实验药剂的最后一种成分加入其中，希望它所保存的传染性元素能与混合物发挥作用。"}},faq={{q="这种毒液与普通的蜘蛛毒液相比，有何独特之处？",a="皇家药剂师协会研究的学术著作记录道，一种古代瘟疫的病原体在生物学上被保存在夜行蜘蛛血统的毒腺内，将它们的毒液变成了一个天然的传染性病原体库。",al={"为什么需要这种毒液","夜行蜘蛛毒液的传说","蜘蛛毒液与瘟疫"}},{q="在哪里可以找到携带这种毒液的蜘蛛？",a="邪恶的夜行蜘蛛主要栖息在毒蛛峡谷，那是一个位于提瑞斯法林地东部、血色修道院南侧的被蛛网覆盖的峡谷。",al={"哪里寻找蜘蛛毒液","邪恶夜行蜘蛛的位置","毒蛛峡谷蜘蛛"}},{q="在布瑞尔，谁需要这种毒液？",a="药剂师乔汉，一位驻扎在布瑞尔东侧的炼金术士，需要多个样本来完成他关于一种针对被遗忘者的新型传染媒介的研究。",al={"谁需要蜘蛛毒液","药剂师乔汉的毒液","谁在使用这种毒液"}},{q="这种毒液在被遗忘者的研究中起什么作用？",a="乔汉要求将这种毒液作为他实验的最后一种成分。他查阅的古籍中描述了一种通过邪恶夜行蜘蛛的毒液保存下来的古代瘟疫，他想测试其传染性元素是否能与他的新药剂产生反应。",al={"药剂师毒液研究","the new plague成分","被遗忘者蜘蛛毒液"}}},fp="30,206,21.341.0,22.198.1,63.192.0,51.114.0,30.120.0,52.213.0"}
P.entries["item:vile-familiar-head"] = {n="邪灵劣魔的头颅",s="邪灵劣魔的头颅是从试炼谷火刃集会所附近栖息的野性小鬼生物身上收集来的恐怖战利品。年轻的部落术士在鲁赞的指导下收集这些头颅，以此证明他们已准备好战斗，并以此作为学习召唤第一个恶魔仆从之前的考验。这些头颅是对纪律的一次残酷测试，表明学徒了解他们打算召唤的生物有多么致命。",h="邪灵劣魔的头颅是从试炼谷火刃集会所附近栖息的野性小鬼生物身上收集来的恐怖战利品。年轻的部落术士在鲁赞的指导下收集这些头颅，以此证明他们已准备好战斗，并以此作为学习召唤第一个恶魔仆从之前的考验。这些头颅是对纪律的一次残酷测...",kw={"火刃集会所","杜隆塔尔","小鬼","鲁赞","试炼谷","邪灵劣魔","邪灵劣魔的头颅","术士任务"},ang={["class:Warlock"]="收集这些头颅标志着术士通往掌握虚空力量的第一步，使他们获得召唤并奴役一个小鬼的资格。",["faction:Horde"]="即便是在杜隆塔尔的训练场，术士们也在边缘地带练习他们的技艺，因为他们深知部落正带着挥之不去的猜疑注视着他们的恶魔崇拜行为。"},sec={{t="一堂恶魔学的残酷课程",b="在试炼谷阳光炙烤的峡谷中，术士训练师鲁赞要求那些寻求学习召唤术的新手收集六个邪灵劣魔的头颅。徘徊在火刃集会所外的邪灵劣魔是凶残的火焰小鬼，它们矮小的身材下隐藏着危险的元素狡诈。鲁赞要求未来的召唤者在战斗中面对这些恶魔并砍下它们的头颅，以证明他们能够征服和驾驭恶魔生命，而不是被其反噬。由于术士在萨尔的部落中勉强被容忍，训练需要极其小心；那些因自己的召唤而丧命的鲁莽新手只会加深外界对黑暗艺术修行者的不耻与猜疑。"}},faq={{q="邪灵劣魔的头颅有什么用？",a="它们是试炼谷新手术士武艺的证明。训练师鲁赞要求获得六个这样的头颅，才会指导学徒进行召唤第一个小鬼仆从的仪式。",al={"邪灵劣魔的头颅用途","这些头颅有什么用","鲁赞任务物品"}},{q="邪灵劣魔从哪里来？",a="它们聚集在试炼谷东北部一个洞穴的入口和内部，该营地窝藏着神秘而邪恶的火刃集会所。",al={"邪灵劣魔位置","在哪里可以找到邪灵劣魔","火刃集会所洞穴"}},{q="为什么鲁赞要年轻的术士收集这些头颅？",a="鲁赞认为，没有人应该召唤他们无法在战斗中战胜的生物。由于小鬼善于欺诈且投掷挥发性火焰，与它们面对面交战能确保术士学徒理解他们试图驾驭的恶魔实体所带来的威胁。",al={"为什么要收集头颅","鲁赞的动机","为什么要先击杀劣魔"}},{q="部落如何看待收集这种战利品的术士？",a="术士在现代部落中只是被容忍，而非受到欢迎。过去与邪能相关的背叛行径留下了深刻的猜疑，这迫使像鲁赞这样的训练师必须确保学徒在学习时守纪且低调。",al={"术士被接受吗","部落术士声望","不受信任的术士"}}},fp="18,302,31.545.0,38.148.0,34.156.0,55.210.0,59.192.0"}
P.entries["item:vile-fin-scale"] = {n="邪鳍鱼人的鳞片",s="邪鳍鱼人的鳞片是从徘徊在提瑞斯法林地的水道和北海岸的鱼人部落中采集而来的。在布瑞尔，皇家药剂师协会正在利用这些具有韧性的生物样本，致力于研究制造一种具有毁灭性的新瘟疫。",h="邪鳍鱼人的鳞片是从徘徊在提瑞斯法林地的水道和北海岸的鱼人部落中采集而来的。在布瑞尔，皇家药剂师协会正在利用这些具有韧性的生物样本，致力于研究制造一种具有毁灭性的新瘟疫。",kw={"新瘟疫","药剂师乔汉","布瑞尔","鱼人","皇家药剂师协会","提瑞斯法林地","邪鳍鱼人的鳞片"},ang={["faction:Horde"]="清理具有攻击性的沿海鱼人定居点有助于保障提瑞斯法林地外围区域的安全，方便部落信使和旅行者通行。",["race:Undead"]="收集到的每一片邪鳍鱼人鳞片，都直接助力于皇家药剂师协会的神圣职责，即制造一种确保被遗忘者在面对生者和天灾军团时能够生存下去的武器。"},sec={{t="药剂试剂",b="皇家药剂师协会不断钻研，试图制造出一种足以消灭生者与天灾军团的致命枯萎病。简单的毒素很容易酿造，但要制造出一种能在种群中轻易传播的传染性疾病，就需要特殊的炼金特性。布瑞尔的药剂师乔汉专门研究邪鳍鱼人的鳞片，以了解它们天然的抗性和粘液涂层如何帮助稳定和传播他的实验性传染病。"},{t="海岸的威胁",b="邪鳍部落盘踞在提瑞斯法林地的北岸和西部浅滩，威胁着过往的旅人，并侵蚀着被遗忘者的领地。收集它们的鳞片对幽暗城有着双重作用：既能遏制野性难驯的鱼人种群，又能为乔汉的实验室提供用于生化武器试验的新鲜有机成分。"}},faq={{q="药剂师乔汉为什么需要这些鳞片？",a="药剂师乔汉正在为皇家药剂师协会开发一种新瘟疫。他发现普通的毒药缺乏传播力，因此他利用鱼人鳞片独特的生物特性来帮助他的实验性配方有效地传播。",al={"乔汉如何处理鳞片","为什么要邪鳍鱼人的鳞片","乔汉 瘟疫 鳞片"}},{q="在哪里可以找到邪鳍鱼人？",a="邪鳍鱼人栖息在提瑞斯法林地的海岸线上，主要聚集在北部的海岸线以及与澈水湖和大海接壤的西部水域。",al={"邪鳍鱼人在哪里","提瑞斯法鱼人位置","如何获得鳞片"}},{q="新瘟疫计划对被遗忘者为什么如此重要？",a="被遗忘者寻求一种足以消灭他们宿敌的武器——无论是毫无思想的天灾军团，还是将他们视为怪物的活着的种族。乔汉在布瑞尔的工作代表了实现这一王国宏愿最初的基层实验。",al={"为什么要有新瘟疫","被遗忘者瘟疫目标","药剂师乔汉在研究什么"}},{q="具体是哪些生物带有这些鳞片？",a="这些鳞片可以从提瑞斯法林地的邪鳍部落成员身上获得，包括邪鳍低阶神谕者、淤泥潜伏者和水洼跳跃者。",al={"谁掉落邪鳍鱼人鳞片","哪些鱼人掉落鳞片"}}},fp="14,221,19.414.0,20.324.0,45.257.0,36.141.0,60.197.0,44.109.0"}
P.entries["item:voodoo-charm"] = {n="巫毒咒符",s="巫毒咒符是一种神秘的护身符，在泰达希尔的兽穴中使用，用来解除一种邪恶的附魔。它由奥本·怒爪的灵魂交给冒险者，能让他那被腐蚀、受人操控的肉身得到彻底解脱，使他的灵魂得以在翡翠梦境中安息。",h="巫毒咒符是一种神秘的护身符，在泰达希尔的兽穴中使用，用来解除一种邪恶的附魔。它由奥本·怒爪的灵魂交给冒险者，能让他那被腐蚀、受人操控的肉身得到彻底解脱，使他的灵魂得以在翡翠梦境中安息。",kw={"利爪德鲁伊","蓟皮","奥本·怒爪","泰达希尔","沉睡的德鲁伊","巫毒咒符"},ang={["class:Druid"]="对于在泰达希尔训练的年轻德鲁伊来说，利用护身符来慈悲地终结并释放一位利爪德鲁伊同胞，凸显了在穿梭于翡翠梦境时将肉身留在外面的悲剧性脆弱。",["race:NightElf"]="这个护身符的存在揭示了蓟皮熊怪堕落到了何种地步，竟然将神圣的暗夜精灵兽穴变成了亵渎的灵魂囚笼。"},sec={{t="斩断黑暗羁绊",b="在泰达希尔的蓟皮兽穴深处，熊怪转而使用邪恶的魔法来控制沉睡的神圣暗夜精灵守护者。德鲁伊奥本·怒爪发现自己的灵魂与肉体分离，他的躯壳受到蓟皮部族巫术的奴役。在检查过这个受过附魔的护身符后，奥本意识到仅仅通过传统的祈祷无法驱散束缚他躯体的黑暗力量。相反，这个护身符是达成最终解脱的工具：一旦他那失去灵魂的躯体被打倒，就必须引导护身符的魔法覆盖在他倒下的遗体上，以彻底清除熊怪的控制，释放他游荡的灵魂，使其永远前往翡翠梦境。"}},faq={{q="巫毒咒符的用途是什么？",a="这个护身符用于打破蓟皮熊怪对奥本·怒爪的魔法控制。在击倒奥本那失去灵魂、被奴役的躯体后，必须直接在遗体上使用该护身符，以斩断黑暗附魔并释放他的灵魂。",al={"巫毒咒符有什么用","巫毒咒符的使用","如何使用巫毒咒符"}},{q="谁会给你巫毒咒符？",a="奥本·怒爪的灵魂会在“利爪德鲁伊”任务中把护身符交给你。在检查过护身符后，他会指导你如何使用它，以便将他从蓟皮部族的巫术中解放出来。",al={"在哪里获得巫毒咒符","谁给予护身符","奥本的护身符"}},{q="为什么在暗夜精灵的领地里它被称为巫毒咒符？",a="自腐蚀开始渗透进大树以来，泰达希尔的蓟皮熊怪已经屈服于腐化和怪异的部落魔法。这个护身符代表了熊怪部族所使用的外来或扭曲的神秘魔法，用于诱捕并操控那些正在沉睡的德鲁伊的身体。",al={"为什么泰达希尔会有巫毒","这是巨魔巫毒吗"}},{q="使用护身符后会发生什么？",a="一旦护身符打破了他身上的附魔，奥本·怒爪最终得以摆脱蓟皮部族的控制。随着他的肉身安息，他的灵魂将离开泰达希尔，永远平静地居住在翡翠梦境中。",al={"奥本会发生什么","奥本幸存了吗"}}},fp="12,111,24.525.1,40.219.0,31.170.0,51.265.0,37.205.1"}
P.entries["item:wailing-essence"] = {n="哀嚎香精",s="哀嚎香精是一种奇怪的浓缩物质，存在于游荡在哀嚎洞穴深处的粘液怪体内。人们怀疑它正是导致贫瘠之地的动植物发生诡异变异的元凶，这引起了投机取巧的炼金术士们的注意，他们急于将其强大的特性装瓶出售。",h="哀嚎香精是一种奇怪的浓缩物质，存在于游荡在哀嚎洞穴深处的粘液怪体内。人们怀疑它正是导致贫瘠之地的动植物发生诡异变异的元凶，这引起了投机取巧的炼金术士们的注意，他们急于将其强大的特性装瓶出售。",kw={"粘液","麦伯克·米希瑞克斯","棘齿城","聪明饮料","哀嚎洞穴","哀嚎香精"},ang={["class:Druid"]="这种香精的存在直接指向了哀嚎洞穴深处的腐化影响，强调了净化梦境腐蚀的迫切需要。"},sec={{t="一种不稳定的混合物",b="贫瘠之地中心地带下方的地底洞穴中，充斥着浓郁的异常能量，导致野兽发生扭曲，并产生了胶状的粘液怪。这些渗出的生物体内聚集着一种被称为哀嚎香精的粘稠物质。当地的德鲁伊们怀着日益增长的恐惧观察着这些水域，而地精企业家们看到的却仅仅是纯粹的商业机遇。在棘齿城的港口，一位古怪的炼金术士麦伯克·米希瑞克斯认为，这种香精是他的一系列旨在提高消费者智力的“聪明饮料”中缺失的活性成分，他完全不关心这种物质可能潜藏着噩梦般的腐化。"}},faq={{q="哀嚎香精从哪里来？",a="它采集自哀嚎洞穴内的粘液怪，包括吞噬粘液怪、进化粘液怪和梦魇粘液怪。",al={"哀嚎香精掉落","在哪里获得哀嚎香精","什么怪掉落哀嚎香精"}},{q="谁想要这种香精？",a="麦伯克·米希瑞克斯，一位身处棘齿城的地精实验者，他寻求这种香精来调制他那种提高智力的“聪明饮料”的新配方。",al={"谁需要哀嚎香精","谁收购哀嚎香精","哀嚎香精交任务"}},{q="人们怀疑这种香精对贫瘠之地造成了什么影响？",a="麦伯克怀疑这种香精是贫瘠之地各地观察到的野生动物迅速变异和植物反常过度生长的根本原因。",al={"哀嚎香精有什么用","哀嚎香精有危险吗","哀嚎香精背景故事"}},{q="饮用哀嚎香精真的安全吗？",a="考虑到它是从受诅咒洞穴深处那些被梦魇腐化的粘液怪身上提取出来的，将其作为商业饮料饮用至少可以说是鲁莽的，尽管这完全符合地精的企业家标准。",al={"可以喝哀嚎香精吗","聪明饮料安全吗"}}},fx={["387b8d38"]={q="哀嚎香精是什么？",a="哀嚎香精是一种奇异而强效的物质，藏于哀嚎洞穴深处。它聚集在洞穴中四处游荡的游荡的鬼魂和黏液怪体内。当地观察者怀疑，它正是导致周围贫瘠之地的植物和野生动物发生奇异变异的非自然催化剂。",al={"哀嚎香精是什么","哀嚎香精信息","关于哀嚎香精"}}},fp="15,312,21.630.0,37.149.0,23.139.0,54.156.0,42.206.0"}
P.entries["item:warsong-axe-shipment"] = {n="一箱战歌之斧",s="一箱战歌之斧是一个沉重的木箱，里面装满了新锻造的斧头，正静候在荆棘谷藏宝海湾的码头上。这批货物由战歌氏族订购，旨在维持他们在灰谷的伐木行动，是部落海外供应链中至关重要的一环。",h="一箱战歌之斧是一个沉重的木箱，里面装满了新锻造的斧头，正静候在荆棘谷藏宝海湾的码头上。这批货物由战歌氏族订购，旨在维持他们在灰谷的伐木行动，是部落海外供应链中至关重要的一环。",kw={"灰谷","斧头","藏宝海湾","洛克·奥卡尔","碎木岗哨","一箱战歌之斧","战歌补给品","码头管理员罗兹基尔"},ang={["faction:Horde"]="尽管面临灰谷敌对势力的持续压力，获得这个木箱对于保持战歌伐木营地的装备与生产力至关重要。",["race:Orc"]="对于战歌氏族来说，锋利的斧头意味着能为日益壮大的奥格瑞玛和杜隆塔尔提供更多的木材。"},sec={{t="跨海的长途跋涉",b="维持战歌伐木营地的伐木作业需要持续供应耐用的工具，而这些工具并非总能在前线锻造。为了保证伐木工人的物资供应，订单会被送往无尽之海彼岸的中立地精港口藏宝海湾。这个木箱存放在码头管理员罗兹基尔附近，里面装有磨得锋利的斧头，准备运往碎木岗哨。这凸显了部落在维持偏远边境营地的武装与运作方面所面临的后勤难题。"}},faq={{q="一箱战歌之斧在哪里？",a="这个木箱直接放置在地精港口藏宝海湾的码头上，位于荆棘谷的最南端。",al={"斧头货物位置","斧头货物在哪里","藏宝海湾斧头木箱"}},{q="为什么灰谷的货物会远在藏宝海湾？",a="黑水强盗和热砂港负责处理无尽之海上的商贸运输。藏宝海湾是连接遥远大陆的主要贸易枢纽，因此成为了部落订购的大宗硬件和工具的中转站。",al={"为什么在藏宝海湾","为什么在荆棘谷","藏宝海湾的战歌之斧"}},{q="谁需要这些斧头？",a="驻扎在灰谷碎木岗哨的斥候洛克·奥卡尔需要这些斧头来补充战歌伐木营地日益减少的库存。",al={"谁需要这些斧头","这些货物是给谁的","洛克·奥卡尔的斧头"}},{q="谁负责藏宝海湾的交付工作？",a="码头管理员罗兹基尔负责管理藏宝海湾繁忙码头上的海运货物，这批货物正停靠在那里，等待运往卡利姆多。",al={"谁拥有这批货物","码头管理员罗兹基尔","藏宝海湾码头管理员"}}},fx={["445f7bbf"]={q="一箱战歌之斧是什么？",a="这是一批装箱运送的重型伐木斧，发往战歌氏族在灰谷的伐木作业点。兽人伐木工在砍伐卡利姆多的古老森林时，工具磨损得很快，因此定期运送新锻造的伐木斧，对于保障伐木场和伐木队的工具供应至关重要。",al={"一箱战歌之斧是什么","一箱战歌之斧的身份","灰谷的斧头箱"}}},fp="20,166,29.447.0,42.84.0,62.173.0,21.133.0,39.108.0"}
P.entries["item:warsong-oil"] = {n="战歌之油",s="战歌之油是一种至关重要的工业润滑剂，专供灰谷的战歌伐木营地的机械使用。一批关键的补给品在运输途中遭到了当地萨特劫掠，它们将这些燃油带回了自己腐化的林地避难所，用于某种邪恶的仪式。",h="战歌之油是一种至关重要的工业润滑剂，专供灰谷的战歌伐木营地的机械使用。一批关键的补给品在运输途中遭到了当地萨特劫掠，它们将这些燃油带回了自己腐化的林地避难所，用于某种邪恶的仪式。",kw={"灰谷","洛克·奥卡尔","夜道谷","萨提纳尔","碎木岗哨","战歌之油","战歌补给品","萨维亚"},ang={["faction:Horde"]="部落在杜隆塔尔和贫瘠之地的全部立足点都依赖于灰谷的木材；将机械用油输送给崇拜恶魔的萨特，这威胁到了他们新兴城市的建设。",["profession:Engineering"]="工程师们非常清楚，如果缺少持续的润滑油供应，精密的地精伐木机关节和电锯在伐木作业数小时后就会烧毁。"},sec={{t="被窃的机械燃料",b="战歌氏族在灰谷的伐木工作极其依赖重型机械、地精工程学伐木机以及大型锯木厂。维持这些工业设备的运转需要稳定的特种润滑油供应。一旦失去这些油料，氏族的木材开采工作可能被迫突然中止，从而导致奥格瑞玛建设以及杜隆塔尔和贫瘠之地各处部落据点加固急需的木材供应中断。"},{t="萨特的仪式",b="最近的一批战歌之油在运往碎木岗哨和伐木营地的途中遭到了盘踞在森林中的萨特的伏击。这些恶魔爪牙并没有丢弃这种精炼液体，而是将油桶搬运到了他们腐化的据点中——包括夜道谷、萨提纳尔和萨维亚——并将这种易燃的润滑剂用于他们黑暗而可憎的仪式。"}},faq={{q="战歌之油有什么用途？",a="它是一种工业润滑剂，旨在维持战歌伐木营地的重型伐木机、锯子和伐木机械的正常运转。",al={"战歌之油的用途","为什么需要燃油","它有什么用"}},{q="为什么萨特会得到这些燃油？",a="一支前往碎木岗哨的补给车队在灰谷的道路上遭到了伏击。萨特抢走了燃油，并将其用于他们在废墟聚居地里进行的可憎黑暗仪式。",al={"谁偷了燃油","为什么萨特有这些油","燃油去哪了"}},{q="在哪里可以找到战歌之油？",a="这种燃油的容器散布在灰谷被萨特控制的区域内，主要分布在夜道谷、萨提纳尔和萨维亚各处。",al={"战歌之油位置","在哪找到战歌之油","燃油位置"}},{q="谁需要回收这些燃油？",a="碎木岗哨的洛克·奥卡尔需要这些燃油，以及锯片、绳索和斧头，以支援处境艰难的战歌伐木行动。",al={"谁想要燃油","战歌之油任务发布者"}}},fx={["7f00f21d"]={q="战歌之油是什么？",a="战歌之油是为部落在灰谷的伐木机械提供的重要润滑剂和燃料。它用于确保战歌伐木营地的重型机械和锯片顺畅运转，是维持氏族伐木作业、抵御荒野环境损耗不可或缺的资源。",al={"战歌之油是什么","这种油是什么","战歌之油信息"}}},fp="11,146,21.310.0,20.258.0,29.104.0,31.145.0,31.112.0,28.131.0"}
P.entries["item:warsong-outrider-update"] = {n="战歌侍从的报告",s="“战歌侍从的报告”是一份由驻扎在灰谷东部边境的战歌侦查骑兵撰写的军事情报快报。它被托付给部落的信使，提供了对于保障通往艾萨拉的道路以及加强兽人势力以抵御暗夜精灵抵抗至关重要的前线观察结果。",h="“战歌侍从的报告”是一份由驻扎在灰谷东部边境的战歌侦查骑兵撰写的军事情报快报。它被托付给部落的信使，提供了对于保障通往艾萨拉的道路以及加强兽人势力以抵御暗夜精灵抵抗至关重要的前线观察结果。",kw={"灰谷","艾萨拉","贫瘠之地","卡德拉克","碎木岗哨","战歌侦查骑兵","战歌侍从的报告"},ang={["faction:Horde"]="来自前线的每一份侦察报告都能保护贫瘠之地和灰谷之间重要的补给路线，直接保障了扩建奥格瑞玛所需的木材供应。",["race:Orc"]="战歌氏族依靠警惕的侦察兵和敏捷的信使来维护荣誉和领土，抵御那些对他们的伐木主张提出异议的凶猛暗夜精灵哨兵。"},sec={{t="边境情报",b="沿着经过碎木岗哨通往艾萨拉古代遗迹的东部道路延伸，灰谷的边界仍然是一个不稳定的前线。“战歌侍从的报告”汇编了骑在这一带巡逻的兽人先锋队的战术观察、巡逻动向和资源评估。这些战地笔记被送回贫瘠之地边境守望塔的卡德拉克手中，使部落指挥官能够清晰地评估敌军兵力集中情况以及潜伏在森林树冠下的领土威胁。"}},faq={{q="这份报告的目的是什么？",a="它作为一份关于灰谷东部通往艾萨拉道路上的暗夜精灵活动和前线状况的状态报告。卡德拉克依靠这份情报来协调部落军队的部署，并加强贫瘠之地北部的防线。",al={"战歌侍从的报告目的","为何需要侍从报告","这份报告是什么"}},{q="谁携带并递送这份快报？",a="一名在碎木岗哨和艾萨拉边界之间公路巡逻的战歌侦查骑兵会移交这份文件，以换取来自卡德拉克的新战略指令。",al={"谁撰写了侍从报告","侍从报告来自哪里"}},{q="这份报告需要送到哪里？",a="报告必须直接交给卡德拉克，他负责监管连接贫瘠之地和灰谷南入口的北部守望塔。",al={"我该把侍从报告带到哪里","谁需要侍从报告"}},{q="为什么战歌氏族如此执着于灰谷？",a="战歌氏族大量采伐灰谷的古老森林，为奥格瑞玛提供木材和建筑材料。这种激进的资源采集使他们与进行防御的暗夜精灵和银翼要塞陷入了无休止的冲突。",al={"为什么兽人在灰谷","战歌在灰谷的利益"}}},fp="23,299,21.471.0,35.230.0,39.187.0,34.139.0,45.209.0"}
P.entries["item:warsong-runner-update"] = {n="战歌信使的报告",s="《战歌信使的报告》是一份军事快报，包含了来自灰谷西海岸佐拉姆加前哨站的战况观察。这份报告被送往位于贫瘠之地边界的部落指挥官卡德拉克手中，协助协调战歌氏族针对暗夜精灵的持续军事行动。",h="《战歌信使的报告》是一份军事快报，包含了来自灰谷西海岸佐拉姆加前哨站的战况观察。这份报告被送往位于贫瘠之地边界的部落指挥官卡德拉克手中，协助协调战歌氏族针对暗夜精灵的持续军事行动。",kw={"灰谷","卡德拉克","贫瘠之地","战歌报告","战歌氏族","战歌信使的报告","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="这份报告强调了在充满敌意的暗夜精灵领土上维持遥远前哨站的后勤难度，这需要依靠信使来保持灰谷与贫瘠之地之间的通讯畅通。",["race:Orc"]="战歌斥候和信使在茂密的森林中冒着生命危险，将战术数据直接传达给卡德拉克，以推进氏族的领土主张。"},sec={{t="西线视点",b="驻守在佐拉姆海岸边缘的战歌信使在佐拉姆加前哨站监视着沿海水域和灰谷西部的潜在威胁。这份报告包含了从前线哨兵处收集的关键情报，记录了当地的动向并确保了补给线的安全。这份快报被送回了位于贫瘠之地边界的卡德拉克的了望塔，为部落领导层提供了巩固阵地所需的清晰局势，并以此规划后续在古老精灵森林深处的行动。"}},faq={{q="什么是《战歌信使的报告》？",a="这是一份由驻守在灰谷西部佐拉姆加前哨站的战歌信使所写的军事快报，旨在向位于贫瘠之地边界的部落领导层报告前线观察情况。",al={"信使报告","什么是战歌信使的报告","战歌报告 佐拉姆"}},{q="这份快报来自哪里？",a="它来自驻守在佐拉姆加前哨站的战歌信使，该哨站位于灰谷最西端的海岸附近，靠近佐拉姆海岸。",al={"信使位置","战歌信使在哪里","谁提供信使报告"}},{q="谁接收这份报告？",a="这份报告会被送往卡德拉克手中，他是驻扎在北部贫瘠之地边界了望塔的战歌指挥官。",al={"我该把这个交给谁","卡德拉克报告","递交信使报告"}},{q="为什么卡德拉克需要这份快报？",a="卡德拉克负责协调战歌氏族向灰谷推进的军事行动。来自像佐拉姆加这样前哨站的战地快报能让他及时了解敌人的抵抗情况、海军动向以及当地领土的控制情况。",al={"为什么需要信使报告","战歌报告的用途"}}},fp="21,93,25.360.0,34.193.0,35.120.0,25.103.0,35.198.0"}
P.entries["item:warsong-saw-blades"] = {n="战歌锯条",s="战歌锯条是专门定制的工业切割工具，旨在供应部落在灰谷进行的皆伐作业。它们通过地精后勤网络运送，对于维持战歌伐木营地的木材加工机械正常运转至关重要。",h="战歌锯条是专门定制的工业切割工具，旨在供应部落在灰谷进行的皆伐作业。它们通过地精后勤网络运送，对于维持战歌伐木营地的木材加工机械正常运转至关重要。",kw={"灰谷伐木","洛克·奥卡尔","皮克希尔","碎木岗哨","战歌伐木营地","战歌锯条"},ang={["faction:Horde"]="部落在整个卡利姆多中部的扩张依赖于灰谷的木材，这使得战歌磨坊设备的保存和维护成为一项关键的战略重点。",["race:NightElf"]="每一箱地精锻造的锯条都代表着对灰谷古老树冠的持续亵渎，以及对神圣林地灵魂的屠戮。"},sec={{t="工业林业",b="战歌氏族在灰谷的伐木工作极其依赖由地精工程提供并维护的重型机械。仅靠标准斧头无法满足部落对卡利姆多木材的巨大需求，因此需要蒸汽机和圆锯来不断切削原木。由于灰谷的古老硬木会迅速使普通刀片变钝断裂，因此不断运送替换用的锯条对于维持战歌伐木营地磨坊的运转至关重要。"},{t="确保运输",b="在争议领土深处获取机械零件一直是个棘手的后勤难题。虽然其他伐木物资经常被敌对的熊怪或萨特截获，但锯条的运输是由碎木岗哨的皮克希尔等地精联系人经手的。收集这些锯条以及绳索、燃油和斧头，使得伐木大师洛克·奥卡尔能够让营地在当地守军不断的破坏下继续运作。"}},faq={{q="战歌锯条是用来做什么的？",a="它们是用于灰谷东南部战歌伐木营地运行的重型机械木材粉碎机和磨坊的替换圆锯组件。",al={"锯条用途","锯条的使用","它们是干什么用的"}},{q="谁向部落提供这些锯条？",a="这些锯条由地精商人和后勤人员处理。驻扎在碎木岗哨的地精皮克希尔负责监管这批机械物资为战歌氏族运抵。",al={"谁制造了锯条","锯条来源","锯条供应商"}},{q="为什么部落需要这么多锯条？",a="灰谷茂密、古老的树木会迅速磨损切削刃，而部落需要大量的木材来在杜隆塔尔和贫瘠之地的干旱平原上建造定居点。持续的伐木使机械的磨损速度超过了当地铁匠修复它们的速度。",al={"为什么需要这么多锯条","战歌伐木需求","为什么需要锯子"}},{q="谁在收集伐木物资？",a="负责监督从碎木岗哨出发的补给运输的兽人洛克·奥卡尔，负责组织回收锯条以及燃油、绳索和斧头，并将它们运送到伐木营地。",al={"谁需要锯条","谁拿走了锯条","洛克·奥卡尔任务"}}},fx={["12f75673"]={q="什么是战歌锯条？",a="这些坚固耐用的金属锯条是战歌氏族用于工业伐木机械的重要部件。兽人严重依赖机械化伐木来采伐灰谷古老而茂密的木材，但粗壮的树木会很快磨损锯齿。若没有稳定供应的锋利耐用锯条，战歌氏族的伐木作业就会停摆。",al={"什么是战歌锯条","战歌锯条物品","什么是锯条"}}},fp="18,187,19.405.0,21.375.0,41.126.0,43.140.0,43.262.0,39.162.0"}
P.entries["item:warsong-scout-update"] = {n="战歌斥候的报告",s="“战歌斥候的报告”是一份书面简报，包含了从灰谷的碎木岗哨收集到的战场侦察情报。它由战歌氏族的一名前线斥候收集，为卡德拉克指挥官提供了巩固部落在暗夜精灵抵抗面前立足点所需的关键情报。",h="“战歌斥候的报告”是一份书面简报，包含了从灰谷的碎木岗哨收集到的战场侦察情报。它由战歌氏族的一名前线斥候收集，为卡德拉克指挥官提供了巩固部落在暗夜精灵抵抗面前立足点所需的关键情报。",kw={"灰谷","贫瘠之地","卡德拉克","报告","斥候","碎木岗哨","战歌"},ang={["faction:Horde"]="战歌简报是部落向灰谷扩张的生命线，使前线营地能与贫瘠之地的补给基地保持联系。",["race:Orc"]="战歌氏族承担了灰谷伐木战役的大部分重任，依靠敏捷的斥候来守住他们来之不易的森林哨站。"},sec={{t="远古森林之眼",b="当部落试图在灰谷开采木材并建立补给路线时，战歌氏族的斥候在敌后深处进行巡逻。“战歌斥候的报告”汇编了来自碎木岗哨这一防御营地的当地观察结果，追踪暗夜精灵哨兵和领土动向。这份文件被交给传递常规命令的信使，让身处贫瘠之地与灰谷交界处的卡德拉克能够评估部队的备战状态，并协调这片争夺激烈的林地中的后勤工作。"}},faq={{q="什么是“战歌斥候的报告”？",a="这是一份由驻扎在灰谷东部碎木岗哨的战歌斥候编写的实地报告，旨在为边境的指挥官总结当地的监视情况。",al={"斥候报告","斥候情报","战歌斥候简报"}},{q="谁需要这份报告？",a="卡德拉克，那位驻扎在守卫贫瘠之地北部与灰谷边界的瞭望塔上的部落军官，需要它来规划部落的军事行动。",al={"谁需要这个","卡德拉克报告","谁接收报告"}},{q="战歌斥候在哪里？",a="这名斥候驻扎在碎木岗哨内，这是位于穿过灰谷东部主干道旁的主要部落据点。",al={"斥候在哪里","斥候位置","寻找战歌斥候"}},{q="为什么这些简报对部落如此重要？",a="灰谷正受到暗夜精灵的顽强防守。书面的斥候报告会向部落领导层预警敌人的伏击和部队调动，确保补给线和伐木营地的安全。",al={"为什么要关注","战歌后勤","灰谷情报"}}},fp="20,91,26.396.0,33.139.0,25.163.0,35.116.0,51.157.0"}
P.entries["item:water-of-the-seers"] = {n="先知之水",s="先知之水是给予在血蹄村进行部族试炼的年轻牛头人的一种圣饮。在部族篝火旁饮用这种圣水可以开启通往精神世界的心智，召唤空灵的Plains Vision来指引朝圣者踏上他们的精神旅程。",h="先知之水是给予在血蹄村进行部族试炼的年轻牛头人的一种圣饮。在部族篝火旁饮用这种圣水可以开启通往精神世界的心智，召唤空灵的Plains Vision来指引朝圣者踏上他们的精神旅程。",kw={"血蹄村","平原幻象","幻象仪式","先知奥萨迪·智慧行者","部族篝火","先知之水"},ang={["class:Shaman"]="体验这种药水的效果可以让人初步洞察如何与精神世界交流，展示了仪式性物质如何能够稀释物质世界与先祖领域之间的面纱。",["race:Tauren"]="先知之水是年轻舒哈鲁教育中的一种基础圣饮，将古老的萨满习俗与部族成年礼联系在一起。"},sec={{t="精神的载体",b="先知之水由部族神秘主义者调制，是古老的幻象仪式的重要组成部分。为了穿透物质现实与先祖指引之间的面纱，祈求者必须在血蹄村的中央部族篝火前饮用这种圣水。一旦饮下，这种强效药水便能赋予精神视觉，使被称为Plains Vision的幽灵向导从余烬中显现，并引领其前往先知奥萨迪·智慧行者处。"}},faq={{q="饮用先知之水后会发生什么？",a="在村子的部族篝火旁摄入这种圣水可以开启你的精神感官。片刻之后，一个化身为幽灵之狼的先祖之魂，即Plains Vision，将从火焰中走出，指引你穿越莫高雷。",al={"先知之水的作用","饮用先知之水","平原幻象之水"}},{q="应该在哪里饮用这种水？",a="这种药水必须直接在位于血蹄村的大型部族篝火前饮用，就在当地萨满长者们的北边。",al={"在哪里饮用先知之水","先知之水的位置","部族篝火位置"}},{q="幻象会将你引导至谁那里？",a="幽灵般的Plains Vision会引领朝圣者向西北方向进入莫高雷的山麓，到达先知奥萨迪·智慧行者等待着解读你旅程的洞穴。",al={"幽灵之狼去往何处","平原幻象的目的地","先知是谁"}}},fp="18,188,23.278.0,51.154.0,35.114.0,33.134.0"}
P.entries["item:water-pitcher"] = {n="水罐",s="这是一个简单的容器，用于从红云台地的当地水井中运送清澈的泉水。鹰风酋长的母亲指引年轻的牛头人将它运回纳拉其营地，旨在培养他们谦逊、服务和尊重部落长者的美德。",h="这是一个简单的容器，用于从红云台地的当地水井中运送清澈的泉水。鹰风酋长的母亲指引年轻的牛头人将它运回纳拉其营地，旨在培养他们谦逊、服务和尊重部落长者的美德。",kw={"谦逊的任务","纳拉其营地","鹰风酋长","鹰风酋长的母亲","莫高雷的水井","红云台地","水罐"},ang={["race:Tauren"]="对于在红云台地成年的年轻牛头人来说，搬运水罐是他们上的第一课，让他们明白尊敬长者和帮助社区才是力量的真正基石。"},sec={{t="谦逊的课程",b="尽管水罐的设计朴实无华，但它却是纳拉其营地的年轻人学习的重要工具。它静置在营地东南平原的水井旁，象征着维持社区运转所需的日常劳动。通过让一名新手装满并搬运这个沉重的水罐给鹰风酋长，鹰风酋长的母亲可以考验他们的品格。这项苦差事证明了对于部落的守护者来说，没有什么职责是低微的，同时也提醒年轻的勇士们，照料族人的日常需求与在狩猎中使用武器同样至关重要。"}},faq={{q="水罐有什么用途？",a="它用于将清澈的井水运回纳拉其营地。穿过平原搬运它是一项传统的差事，旨在考验年轻的冒险者是否愿意为部落的利益从事日常劳动。",al={"水罐的用途","为什么要搬运水罐","水罐的谦逊任务"}},{q="在哪里可以找到水罐？",a="水罐就在位于红云台地纳拉其营地东南方的一口水井旁，靠近鹰风酋长的母亲处理日常事务的地方。",al={"水罐位置","水罐在哪里","在莫高雷寻找水罐"}},{q="是谁让你去取水罐的？",a="鹰风酋长的母亲会让年轻的旅行者去取水罐。由于年事已高，行走对她来说非常困难，所以她将这项任务交给热心的年轻人，以测试他们的活力与谦逊。",al={"谁发布水罐任务","鹰风酋长的母亲与水罐"}},{q="水罐装满后交给谁？",a="水罐会被直接带给纳拉其营地的鹰风酋长，他将此举视为搬运者拥有为部落服务所需的心志与奉献精神的证明。",al={"谁接收水罐","运送水罐","把水罐交给谁"}}},fp="13,217,20.334.0,35.178.0,36.135.0,40.169.0,49.154.0"}
P.entries["item:webwood-egg"] = {n="树林蜘蛛的卵",s="树林蜘蛛的卵是一种尚未孵化的样本，采集自黑丝洞内的孵化巢穴，位于幽影谷。研究泰达希尔腐蚀现象的博物学家们会寻找这些有活力的卵，以便在安全的实验室条件下研究新孵化的蛛形纲生物。",h="树林蜘蛛的卵是一种尚未孵化的样本，采集自黑丝洞内的孵化巢穴，位于幽影谷。研究泰达希尔腐蚀现象的博物学家们会寻找这些有活力的卵，以便在安全的实验室条件下研究新孵化的蛛形纲生物。",kw={"奥达希尔","基尔沙兰","幽影谷","黑丝洞","蜘蛛卵","泰达希尔","树林蜘蛛的卵"},ang={["class:Druid"]="了解树林蜘蛛在受腐蚀后的繁殖和行为方式，为德鲁伊治愈泰达希尔受破坏的自然平衡提供了重要的线索。",["race:NightElf"]="对于保卫泰达希尔神圣枝干的年轻卡多雷来说，获取这些卵有助于学者们调查在世界之树原生野生动物中蔓延的非自然腐蚀。"},sec={{t="受控样本",b="驯服或制服一只完全长大的毒性树林蜘蛛是一项危险的任务，绝非孤身一人的研究者所能及。学者们，比如基尔沙兰·风行者，宁愿收集那些藏在黑丝洞阴暗角落里的未孵化的卵，也不愿与成年捕食者搏斗。获得未孵化的卵可以让博物学家安全地运输这些生物，并在其孵化时控制住幼蛛，从而在不必面对成年野兽致命毒牙的情况下，获得可供研究的活体样本。"},{t="运往达纳苏斯",b="困扰泰达希尔原生野生动物的反常攻击性和腐蚀现象引起了树冠上学者们的警惕。这些收集到的卵和毒液一旦在奥达希尔被保护起来，就会被送往位于树下的首都达纳苏斯。研究人员希望通过在受控环境中饲养和检查这些蜘蛛，能为在这棵世界之树的枝干上蔓延的黑暗折磨提供有价值的见解。"}},faq={{q="在哪里可以找到树林蜘蛛的卵？",a="树林蜘蛛的卵位于黑丝洞潮湿的隧道深处，那里位于幽影谷的西北部。",al={"树林蜘蛛的卵位置","哪里有树林蜘蛛的卵","寻找树林蜘蛛的卵"}},{q="谁需要树林蜘蛛的卵？",a="位于奥达希尔的研究者基尔沙兰·风行者要求提供这种卵，以便继续他对困扰幽影谷的攻击性蛛形纲生物的科学研究。",al={"谁需要树林蜘蛛的卵","卵上交","基尔沙兰的卵"}},{q="为什么要收集卵而不是捕捉蜘蛛？",a="成熟的树林蜘蛛太过危险且体型巨大，难以轻易捕捉和收容。获取未孵化的卵可以提供一种活体样本，能够在孵化前被安全地运输并放入封闭的围场中。",al={"为什么选卵","为什么不抓活的蜘蛛"}},{q="卵被收集后会发生什么？",a="基尔沙兰会安排将卵和提取出的蜘蛛毒液送到达纳苏斯，学者们可以在那里对这些生物进行深入研究，远离野外的直接危险。",al={"卵送往何处","卵的目的地"}}},fp="11,151,20.355.0,22.353.0,29.104.0,26.118.0,49.178.0,46.163.0"}
P.entries["item:webwood-ichor"] = {n="树林蜘蛛的脓液",s="树林蜘蛛的脓液是从泰达希尔四处游荡的树林蜘蛛身上采集到的一种液体。迪兰妮亚·月光需要它，以及风信子蘑菇和月瓣百合，来为中毒的埃沃隆酿制解毒剂。",h="树林蜘蛛的脓液是从泰达希尔四处游荡的树林蜘蛛身上采集到的一种液体。迪兰妮亚·月光需要它，以及风信子蘑菇和月瓣百合，来为中毒的埃沃隆酿制解毒剂。",kw={"解毒剂","迪兰妮亚·月光","埃沃隆","幽影谷","黑丝洞","泰达希尔","树林蜘蛛的脓液","树林蜘蛛"},ang={["race:NightElf"]="对于保卫奥达希尔的年轻暗夜精灵来说，采集树林蜘蛛的脓液教导了他们自然界中严酷的平衡之道：泰达希尔最致命的毒药往往也孕育着自身的解药。"},sec={{t="剧毒解药",b="出没于幽影谷的树林蜘蛛携带的毒液足以让埃沃隆病入膏肓。迪兰妮亚·月光请求从这些蜘蛛身上获取脓液，并收集风信子蘑菇和月瓣百合，来调制解毒剂。"}},faq={{q="树林蜘蛛的脓液有什么用途？",a="位于幽影谷的迪兰妮亚·月光需要树林蜘蛛的脓液、风信子蘑菇和月瓣百合，来为中毒的暗夜精灵埃沃隆调制解毒剂。",al={"树林蜘蛛的脓液用途","树林蜘蛛的脓液有什么作用","为什么要获取脓液"}},{q="树林蜘蛛的脓液来自哪里？",a="它采集自居住在幽影谷西北部的树林蜘蛛的尸体，尤其是那些居住在黑丝洞附近及洞内的蜘蛛。",al={"去哪里寻找树林蜘蛛的脓液","如何获得树林蜘蛛的脓液","树林蜘蛛的脓液掉落"}},{q="为什么要用蜘蛛的体液来治疗蜘蛛咬伤？",a="迪兰妮亚请求使用树林蜘蛛的脓液作为埃沃隆解毒剂的配料之一。她并没有解释这种脓液是如何在混合物中发挥作用的。",al={"蜘蛛毒液解药","为什么用毒液制作解毒剂"}}},fp="13,178,12.183.0,31.155.0,35.122.0,43.129.0"}
P.entries["item:webwood-spider-silk"] = {n="树林蜘蛛丝",s="树林蜘蛛丝是从泰达希尔森林中出没的树林潜伏者身上采集而来的纤细、粘稠的丝线。虽然蜘蛛丝有许多工艺用途，但这种特殊的丝线却是世界之树枝干上某些可疑人物所渴求的物品。",h="树林蜘蛛丝是从泰达希尔森林中出没的树林潜伏者身上采集而来的纤细、粘稠的丝线。虽然蜘蛛丝有许多工艺用途，但这种特殊的丝线却是世界之树枝干上某些可疑人物所渴求的物品。",kw={"多兰纳尔","蜘蛛丝","泰达希尔","树林潜伏者","树林蜘蛛丝","赛恩·腐蹄","赛恩的差遣"},ang={["profession:Tailoring"]="虽然纺织工经常寻找蜘蛛丝，但这些特定的丝绸与黑暗的萨特交易有关，而非标准的织机工艺。",["race:NightElf"]="离开幽影谷的年轻暗夜精灵们被告诫要小心他们狩猎的生物，尤其是当他们受到就在心腹之地附近出没的独行萨特的诱导时。"},sec={{t="可疑的试剂",b="树林蜘蛛丝由盘踞在多兰纳尔周围的树林潜伏者吐丝而成，它质地轻盈、异常坚韧，且采集过程非常危险。潜伏在林间道路上的萨特赛恩·腐蹄，雇佣年轻的冒险者去采集这种丝线，以及夜刃豹獠牙和枭兽羽毛。他声称这些只是他进行森林贸易所需的稀有试剂，并利用新人的天真来获取这些野生材料，而不让他们质疑他那腐化的本质或真正的动机。"}},faq={{q="在哪里可以找到树林蜘蛛丝？",a="树林蜘蛛丝是从栖息在泰达希尔荒野中的树林潜伏者及相关的蜘蛛野兽身上采集的，尤其是在多兰纳尔定居点周围。",al={"树林蜘蛛丝位置","谁掉落树林蜘蛛丝","哪里获取树林蜘蛛丝"}},{q="谁需要这种丝绸？",a="萨特赛恩·腐蹄，他将自己的交易隐藏在幽影谷和多兰纳尔之间的小路以北，他要求获得这种丝绸，以及枭兽羽毛和掠食者獠牙。",al={"谁需要树林蜘蛛丝","树林蜘蛛丝任务发布者","赛恩·腐蹄的丝绸"}},{q="为什么赛恩·腐蹄想要树林蜘蛛丝？",a="赛恩声称需要这些丝绸作为他森林贸易的试剂，但他对贸易的具体细节守口如瓶。",al={"赛恩·腐蹄的动机","为什么赛恩需要丝绸"}},{q="玩家能用树林蜘蛛丝进行裁缝吗？",a="不能。尽管它确实是真正的蜘蛛丝，但这种特定的采集物是任务试剂，而非普通的裁缝布料。",al={"树林蜘蛛丝是裁缝材料吗","树林蜘蛛丝制作"}}},fp="19,211,17.371.0,39.119.0,20.176.0,48.99.1,50.114.0"}
P.entries["item:webwood-venom-sac"] = {n="树林蜘蛛的毒囊",s="树林蜘蛛的毒囊是从栖息在泰达希尔幽影谷的巨大蛛形纲生物身上采集到的器官。博物学者们收集这些样本，是为了探究这棵新世界之树的反常生长是如何改变当地野生动物的。",h="树林蜘蛛的毒囊是从栖息在泰达希尔幽影谷的巨大蛛形纲生物身上采集到的器官。博物学者们收集这些样本，是为了探究这棵新世界之树的反常生长是如何改变当地野生动物的。",kw={"奥达希尔","基尔沙兰·风行者","幽影谷","黑丝洞","泰达希尔","毒液","树林蜘蛛","树林蜘蛛的毒囊"},ang={["class:Druid"]="对于那些与自然平衡相协调的德鲁伊来说，这些毒囊中蕴含的腐化力量提供了令人担忧的物理证据，证明泰达希尔的枝头并非一切安好。",["race:NightElf"]="幽影谷的年轻暗夜精灵冒险者们常被委派去收集这些样本，以协助那些试图了解他们这片树冠家园奇异新生态的学者们。"},sec={{t="泰达希尔生长状况的症状",b="生活在黑丝洞内外及周边的树林蜘蛛，是其他地方可见的一种小型蜘蛛的远亲。它们体型突变和掠夺性的攻击行为引起了暗夜精灵研究者们的担忧。像基尔沙兰·风行者这样的博物学者研究这些毒囊中所含的毒液，旨在分析其效力和成分，希望能了解泰达希尔那迅速且未受祝福的生长是如何扭曲了栖息在其枝干上的生物。"}},faq={{q="在哪里可以找到树林蜘蛛的毒囊？",a="它们是从盘踞在幽影谷北部，特别是黑丝洞内外及周边的树林蜘蛛身上收集而来的。",al={"掉落位置","树林蜘蛛的毒囊位置","蜘蛛毒液位置"}},{q="谁需要这些毒囊？",a="驻扎在幽影谷奥达希尔的暗夜精灵研究员基尔沙兰·风行者收集这些毒囊，以便在最终返回达纳苏斯之前研究这些蜘蛛的生物学特征。",al={"谁需要毒囊","基尔沙兰·风行者任务"}},{q="为什么树林蜘蛛会变得这么大？",a="研究人员认为，新世界之树泰达希尔的出现和迅速生长对当地野生动物产生了深远且扭曲的影响，导致普通的蛛形纲物种生长成了体型巨大、极具攻击性的掠食者。",al={"为什么蜘蛛这么大","树林蜘蛛体型"}},{q="这种毒液会被用来制作解毒剂吗？",a="基尔沙兰收集这些毒囊纯粹是为了进行对比研究。然而，该地区的蜘蛛毒液是一种已知的危害，需要埃沃隆的解毒剂等药物来救治那些在森林中被咬伤的人。",al={"这是用来做解药的吗","解毒剂配方"}}},fp="17,211,32.416.0,35.108.0,27.151.0,37.149.0,39.180.0"}
P.entries["item:well-stone"] = {n="水井石",s="水井石是采集自莫高雷水井岸边及周围的小型矿石。它们富含微妙的土元素能量，是牛头人传统成人仪式中酿造先知之水的重要成分。",h="水井石是采集自莫高雷水井岸边及周围的小型矿石。它们富含微妙的土元素能量，是牛头人传统成人仪式中酿造先知之水的重要成分。",kw={"琥珀玉米","血蹄村","莫高雷","幻象仪式","先知之水","水井石","扎尔曼·双月"},ang={["class:Shaman"]="萨满祭司将水井石理解为土与水魔法的自然锚点，将潜在的灵魂力量汇聚成一种具有转化意义的仪式混合物。",["race:Tauren"]="收集水井石是证明与大地沟通的重要步骤，它教会每一位年轻的牛头人，大地的物理元素是如何促进精神启蒙的。"},sec={{t="土元素能量之容器",b="水井石自然地沉睡在莫高雷水井周围松软的土地中，吸收着平原及其下方水脉的精神共鸣。像扎尔曼·双月这样的萨满祭司和先知并不把这些石头看作普通的河卵石，而是视其为重要的魔法容器。当它们与平原巨树下沉淀的琥珀玉米结合时，其矿物特性能够调和出一种药剂，用以唤醒正在经历神圣幻象仪式的年轻牛头人的幻象沉思状态。"}},faq={{q="水井石有什么用途？",a="水井石与琥珀玉米混合后可以酿造先知之水。在部落篝火前饮下这种药剂后，它会为寻求证明自己精神成熟的初学者提供指引幻象。",al={"水井石用途","水井石是用来做什么的","为什么要收集水井石"}},{q="在哪里可以找到水井石？",a="它们散落在莫高雷各地公共水井周围的地面上，就在平原赐予生命的湿润触碰土壤的地方。",al={"哪里可以找到水井石","水井石位置","莫高雷水井石"}},{q="谁需要这些石头？",a="血蹄村备受尊敬的神秘主义者扎尔曼·双月会指导初学者收集这些石头，作为幻象仪式的一部分。",al={"谁需要水井石","扎尔曼的水井石","幻象仪式的石头"}}},fp="10,150,26.452.0,30.197.0,28.144.0,26.130.0"}
P.entries["item:wendigo-mane"] = {n="雪怪的鬃毛",s="雪怪的鬃毛是厚实而蓬松的皮毛，是从漫游在丹莫罗冰冷山脊的凶猛雪怪身上采集而来的。这种粗糙的兽皮因其能极好地抵御刺骨的高山寒气而备受青睐，其坚韧程度足以用作铺设小屋地面或矮人战争机器的铁制舱室衬垫。",h="雪怪的鬃毛是厚实而蓬松的皮毛，是从漫游在丹莫罗冰冷山脊的凶猛雪怪身上采集而来的。这种粗糙的兽皮因其能极好地抵御刺骨的高山寒气而备受青睐，其坚韧程度足以用作铺设小屋地面或矮人战争机器的铁制舱室衬垫。",kw={"丹莫罗","毛皮","灰色洞穴","卡拉诺斯","鬃毛","兽皮","石轮","巨魔犁","雪怪"},ang={["profession:Engineering"]="在丹莫罗操作矮人机器意味着要应对冰冷的金属驾驶舱，因此像雪怪皮毛这样具备隔热衬里的材料是一种非常实用的舒适性改造。",["race:Dwarf"]="猎杀灰色洞穴的雪怪是年轻矮人向卡拉诺斯的资深人士证明自己坚韧程度的一项久经考验的试炼。"},sec={{t="铁炉堡工坊的温暖需求",b="丹莫罗的山脉严酷而无情，当地人不得不充分利用那些潜伏在雪堆里的顶级掠食者。雪怪粗糙的皮毛能提供浓密的保护，抵御严寒的穿堂风。驻扎在卡拉诺斯城外的驾驶员迪恩·石轮派遣冒险者前往附近的灰色洞穴收集这些沉重的鬃毛。这位古怪的驾驶员并不打算用它们来制作冬装或斗篷，而是想把它们编织成一张厚实、保暖的地毯，铺在自己珍贵的矮人攻城机器“巨魔犁”的内舱地板上。"}},faq={{q="什么生物会掉落雪怪的鬃毛？",a="这种鬃毛可以从任何栖息在丹莫罗雪地里的雪怪身上采集到。包括普通的幼年雪怪、成年雪怪，以及像瓦加什、嚎叫者伊丹和老冰须这样著名的头目野兽。",al={"雪怪的鬃毛哪里掉落","谁掉落雪怪的鬃毛","雪怪的鬃毛来源"}},{q="为什么驾驶员迪恩·石轮想要这些鬃毛？",a="驾驶员迪恩·石轮想要这些鬃毛是为了给他驾驶的攻城机器“巨魔犁”的内舱地板制作一张隔热地毯。驾驶巨大的钢铁机器穿过冰冻的地形时，内部会变得异常寒冷，而这种厚实的皮毛有助于保持驾驶舱温暖舒适。",al={"为什么石轮需要鬃毛","驾驶员石轮的地毯","鬃毛的用途"}},{q="去哪里寻找雪怪以获取鬃毛最好？",a="驾驶员迪恩·石轮推荐的主要巢穴是灰色洞穴，这是一个直接位于卡拉诺斯西侧山脉中的洞穴系统。洞穴及其周围的山坡上到处都是雪怪。",al={"灰色洞穴位置","去哪里狩猎雪怪","丹莫罗的雪怪洞穴"}},{q="猎杀雪怪危险吗？",a="危险。雪怪是野蛮且极具领地意识的掠食者，拥有粗暴的体力和厚实的皮囊。矮人训练师认为，勇闯它们的巢穴是证明登山者勇气和战斗韧性的一种早期试炼。",al={"雪怪难杀吗","与雪怪战斗"}}},fp="12,133,24.300.0,36.170.0,42.199.0,57.151.0,31.198.0"}
P.entries["item:whitestone-oak-lumber"] = {n="白石橡木",s="白石橡木是一种坚固的工艺木材，产自月溪镇地下的隐秘船坞。因其强度高而备受珍视，是联盟大师级铁匠锻造神圣武器时必不可少的柄部材料。",h="白石橡木是一种坚固的工艺木材，产自月溪镇地下的隐秘船坞。因其强度高而备受珍视，是联盟大师级铁匠锻造神圣武器时必不可少的柄部材料。",kw={"死亡矿井","地精木雕师","乔丹·斯迪威尔","圣骑士战锤","圣洁之锤试炼","白石橡木"},ang={["class:Paladin"]="从迪菲亚潜行者的地下船坞中获取这种木材是乔丹·斯迪威尔的圣洁之锤试炼的核心要求，最终会锻造出一柄为圣光捍卫者准备的神圣战锤。",["profession:Blacksmithing"]="斯迪威尔的武器设计蓝图将致密的白石橡木与精炼矿石和宝石工艺相结合，以平衡重量、耐用性和形而上的共鸣。"},sec={{t="神圣的柄",b="在铁炉堡大门外，铁匠乔丹·斯迪威尔需要白石橡木来打造一件适合圣光真正勇士的武器。将这种木材与净化过的科尔宝石和精炼金属结合，能提供圣洁之锤试炼期间引导神圣能量所需的平衡且坚固的柄部。"},{t="码头下的木材",b="白石橡木深藏于西部荒野的死亡矿井迷宫之中，由地精木雕师在为迪菲亚潜行者建造秘密战舰时进行加工。其纹理致密且富有弹性，非常适合承受结构压力和高强度的磨损，这使得那些需要比普通白蜡木或松木更优秀的材料来进行礼仪和军事制作的资深武器匠们对其产生了浓厚兴趣。"}},faq={{q="白石橡木在哪里可以找到？",a="它产自西部荒野月溪镇地下，那些在死亡矿井深处劳作的地精木雕师手中，迪菲亚潜行者正是在那里建造他们的秘密战舰。",al={"哪里获得白石橡木","白石橡木位置","谁掉落白石橡木"}},{q="谁在使用这种木材？",a="在丹莫罗铁炉堡大门附近工作的熟练铁匠乔丹·斯迪威尔需要这种木材，为新兴的圣骑士制作特殊的武器。",al={"谁需要白石橡木","白石橡木交还"}},{q="这种木材是用来制造什么的？",a="乔丹·斯迪威尔将这种坚韧的木材用作大师级双手神圣战锤的柄，作为完成圣洁之锤试炼的奖励。",al={"白石橡木用途","乔丹·斯迪威尔锻造什么"}},{q="为什么地精木材适合用于神圣武器？",a="迪菲亚潜行者采购的是致密的高等级木材，能够支撑战舰。乔丹·斯迪威尔认为这种结构用材提供了承受强大神圣力量所必需的物理韧性。",al={"为何使用地精木材","为何使用死亡矿井的木材"}}},fp="21,150,13.284.1,25.279.1,37.158.1,21.134.0,30.148.0,48.145.0"}
P.entries["item:wildmane-cleansing-totem"] = {n="蛮鬃之井净化图腾",s="蛮鬃之井净化图腾是一件经过圣化的仪式器具，专为净化莫高雷北部的几口水井而制。它被托付给这片土地的年轻保卫者，是驱逐地精企业所留下的毒素污染的最后一件法器。",h="蛮鬃之井净化图腾是一件经过圣化的仪式器具，专为净化莫高雷北部的几口水井而制。它被托付给这片土地的年轻保卫者，是驱逐地精企业所留下的毒素污染的最后一件法器。",kw={"血蹄村","地精毒素","莫高雷","穆尔·雷角","牛头人","蛮鬃之井净化图腾","蛮鬃水井"},ang={["class:Shaman"]="通过雕刻出的图腾引导精神净化，是修复被鲁莽工业所腐蚀的受创水灵的基础。",["race:Tauren"]="修复蛮鬃水井是对大地母亲庄严的义务，清除外来的工业毒素以保护你们的祖居之地。"},sec={{t="净化圣井",b="当地精企业开始毒害这片土地，并污染莫高雷稀缺的水源时，牛头人转向神圣的仪式以扭转灾祸。在净化了冬蹄和雷角水井后，穆尔·雷角制作了这个最后的图腾，以清除雷霆崖北部蛮鬃水井中残留的污染。图腾注入了自然之灵的力量，净化了污浊的井水，让纯净的生命之源得以再次滋养这片平原。"}},faq={{q="蛮鬃之井净化图腾的用途是什么？",a="该图腾被用于牛头人的净化仪式中，以中和污染了雷霆崖北部蛮鬃水井的毒素和有害径流，恢复土地的纯净。",al={"图腾的作用","蛮鬃图腾的使用","为什么要净化水井"}},{q="谁制作了蛮鬃之井净化图腾？",a="在你协助穆尔·雷角收集必要材料并净化了莫高雷各地的其他受污染水井后，他会提供这个图腾。",al={"谁给了我这个图腾","穆尔·雷角图腾","我在哪里获得净化图腾"}},{q="为什么莫高雷的水井会被下毒？",a="入侵的地精将有害毒素和破坏性的工业径流引入了当地的地下水层，威胁着牛头人部族以及平原的自然平衡。",al={"谁毒害了这些水井","为什么水井有毒","地精毒害莫高雷"}},{q="这个图腾需要在哪里使用？",a="它必须被带到位于雷霆崖大断崖北侧草海平原上的蛮鬃水井处使用。",al={"蛮鬃水井位置","蛮鬃水井在哪里","我该把图腾带到哪里"}}},fp="24,176,26.406.0,52.139.0,41.121.0,44.151.0,38.65.0"}
P.entries["item:wiley-s-note"] = {n="威利的便笺",s="威利的便笺是一封由湖畔镇潜行者黑衣威利所写的机密信函，旨在偿还他欠格里安·斯托曼的人情。信中的内容揭露了迪菲亚潜行者所组成的令人担忧的联盟，并将暴风城的军情七处卷入了调查之中。",h="威利的便笺是一封由湖畔镇潜行者黑衣威利所写的机密信函，旨在偿还他欠格里安·斯托曼的人情。信中的内容揭露了迪菲亚潜行者所组成的令人担忧的联盟，并将暴风城的军情七处卷入了调查之中。",kw={"迪菲亚潜行者","格里安·斯托曼","mathias shaw","哨兵岭","军情七处","石匠工会","黑衣威利","威利的便笺"},ang={["class:Rogue"]="这封信件经由两名交易中臭名昭著的人物之手传递：黑衣威利，一名街头潜行者；以及马迪亚斯·肖尔大师，神秘的军情七处首领。",["faction:Alliance"]="该便笺代表了一个关键的转折点，标志着西部荒野当地的边境土匪行径被确认为威胁暴风城本身稳定的有组织阴谋。"},sec={{t="危险的账目",b="这封由黑衣威利在赤脊山写下的潦草信件，是为了偿还他欠格里安·斯托曼的一个旧人情而交给他的。威利在信中揭露了他所知道的关于迪菲亚潜行者的秘密野心。他的情报显示，该兄弟会并非孤军奋战：他们已经与该地区的豺狼人、狗头人和地精特工建立了联盟，以进一步扩大他们在整个王国的行动。"},{t="石匠兄弟会的联系",b="除了记录雇佣兵协议外，威利还无意中透露了一个关键线索，将迪菲亚辛迪加与第二次战争后重建暴风城的石匠工会联系了起来。斯托曼预感到了这一细节所蕴含的爆炸性政治影响，便将便笺直接转交到了马迪亚斯·肖尔大师——军情七处的间谍大师手中，从而将暴风城的情报机构直接拉入了调查。"}},faq={{q="谁写了威利的便笺？",a="它是由黑衣威利所写，他是一名常驻赤脊山湖畔镇、道德可疑的同伙。他提供这份便笺是为了偿还他欠人民民兵格里安·斯托曼的一份人情。",al={"威利的便笺作者","谁是威利","黑衣威利的便笺"}},{q="便笺中包含了什么信息？",a="便笺警告说，迪菲亚潜行者正在策划一场巨大的阴谋，并已与豺狼人、狗头人和地精结盟。斯托曼正在针对信中更敏感的内容寻求进一步的建议。",al={"威利的便笺内容","便笺写了什么","迪菲亚便笺信息"}},{q="便笺需要被送到哪里？",a="它首先被送到西部荒野哨兵岭的格里安·斯托曼手中。阅读后，斯托曼下令将其送到暴风城军情七处总部的马迪亚斯·肖尔大师手中。",al={"谁收到威利的便笺","上交威利的便笺","我该把便笺带到哪里"}},{q="为什么格里安·斯托曼要把便笺送到军情七处？",a="格里安怀疑该便笺指向了一个比简单的土匪行径更为深层的阴谋。他将其发送给暴风城情报主管马迪亚斯·肖尔，以进行调查。",al={"为什么要给马迪亚斯·肖尔看","为什么要给肖尔便笺","军情七处威利的便笺"}}},fp="12,218,18.283.0,25.292.1,23.141.0,39.183.0,41.169.0,49.160.0"}
P.entries["item:william-s-shipment"] = {n="威廉的货物",s="威廉的货物是一批精心打包的蜡烛，采集自艾尔文森林中那些讨厌的狗头人。这批货物由威廉·匹斯特在闪金镇打包，旨在运往他兄弟摩根在暴风城Trade District经营的炼金生意。",h="威廉的货物是一批精心打包的蜡烛，采集自艾尔文森林中那些讨厌的狗头人。这批货物由威廉·匹斯特在闪金镇打包，旨在运往他兄弟摩根在暴风城Trade District经营的炼金生意。",kw={"蜡烛","闪金镇","狗头人蜡烛","摩根·匹斯特","匹斯特药店","暴风城","trade district","威廉·匹斯特","威廉的货物"},ang={["faction:Alliance"]="清理艾尔文森林矿洞的狗头人对联盟有双重贡献，既保护了当地的基础设施，又为首都的商店提供了炼金原材料。",["race:Human"]="这次运送展示了像闪金镇这样的乡村聚落与暴风城首府之间紧密的经济联系。"},sec={{t="一项家族贸易",b="匹斯特兄弟在闪金镇和首都之间维持着一条稳定的商业往来。威廉在艾尔文森林通过本地投机者和冒险者收集材料，而摩根则在暴风城的Trade District照看家族的店面：匹斯特药店。因为威廉无法离开自己的岗位前往北方，他只能依靠信使将这包封好的蜡和蜡烛送进城里。"},{t="狗头人蜡烛",b="这批货物里装的是狗头人蜡烛，是从出没于艾尔文森林矿洞的那些生物身上搜刮来的。威廉收集这些大型蜡烛并提取蜡，打包送给他兄弟摩根的匹斯特药店。通过威廉的努力，这些回收的矿洞废料成为了首都炼金交易中有用的库存。"}},faq={{q="威廉的货物里装的是什么？",a="这批货物包含了从艾尔文森林矿洞的狗头人身上搜集来的蜡烛。威廉·匹斯特从过往的冒险者那里收集它们，并将它们打包用作他家族炼金商店的原材料。",al={"货物内容","箱子里装的是什么","威廉寄送了什么"}},{q="威廉把这个包裹寄给谁？",a="它是寄给威廉的兄弟摩根·匹斯特的，他在暴风城的Trade District经营着匹斯特药店。",al={"谁接收货物","运送给谁","货物目的地"}},{q="药剂师为什么需要这么多蜡烛？",a="威廉说他和他的兄弟需要这些大蜡烛来获取蜡。他并没有描述他们具体会用它来制作什么制剂。",al={"炼金为什么需要蜡烛","匹斯特如何使用蜡烛","蜡烛的用途"}},{q="为什么威廉不亲自递送这个包裹？",a="威廉忙于在闪金镇打理事务和采购货物，没有时间长途跋涉前往暴风城，因此他雇佣了前往首都的旅行者。",al={"威廉为何不能亲自前往","威廉为何需要信使"}}},fp="18,118,16.286.0,10.217.0,34.192.0,39.121.0,44.117.0,48.185.0"}
P.entries["item:wine-ticket"] = {n="酒票",s="酒票是暴风城发放的一种促销凭证，旨在为加林纳酒庄招揽生意。将其交给家族店铺的苏泽塔·加林纳，即可获赠一瓶黑皮诺。",h="酒票是暴风城发放的一种促销凭证，旨在为加林纳酒庄招揽生意。将其交给家族店铺的苏泽塔·加林纳，即可获赠一瓶黑皮诺。",kw={"加林纳酒庄","黑皮诺","雷纳多·加林纳","暴风城运河","苏泽塔·加林纳","trade district","酒票"},ang={["profession:Cooking"]="用这张酒票换取的一瓶好酒——黑皮诺，与在东部王国各地收集的丰盛肉类和奶酪搭配起来非常合适。"},sec={{t="推广家族佳酿",b="在暴风城这样繁忙的大都市经营一家精品葡萄酒商店需要精明的营销手段。雷纳多·加林纳会在Trade District附近分发这些印好的酒票，以吸引口渴的顾客前往位于附近运河旁的加林纳酒庄。通过承诺赠送一瓶他们著名的黑皮诺作为品鉴，加林纳家族希望能将好奇的过路人和初来乍到的冒险者转化为忠实的终身客户。"}},faq={{q="我该如何使用酒票？",a="把酒票带给位于暴风城Trade District运河旁的加林纳酒庄的苏泽塔·加林纳。她会很乐意为你兑换一瓶免费的黑皮诺。",al={"酒票用途","如何使用酒票","我该把酒票带到哪里"}},{q="谁在分发这些酒票？",a="雷纳多·加林纳将它们作为促销凭证进行分发，旨在将潜在客户从Trade District繁忙的街道吸引到他家族的葡萄酒商店。",al={"谁提供酒票","哪里获得酒票"}},{q="酒票能换取什么样的葡萄酒？",a="兑换该凭证可以获得一瓶黑皮诺，这是加林纳家族引以为傲的佳酿，也是王国中最好的葡萄酒之一。",al={"酒票奖励","我能得到什么葡萄酒"}}},fp="11,157,28.333.0,34.170.0,28.106.0,41.111.0"}
P.entries["item:winterhoof-cleansing-totem"] = {n="冰蹄之井净化图腾",s="冰蹄之井净化图腾是穆尔·雷角在血蹄村制作的一件神圣仪式法器。它的雕刻旨在消除荆棘谷地精入侵者散布的毒素与污染，引导大地母亲的力量来净化被污染的冰蹄水井。",h="冰蹄之井净化图腾是穆尔·雷角在血蹄村制作的一件神圣仪式法器。它的雕刻旨在消除荆棘谷地精入侵者散布的毒素与污染，引导大地母亲的力量来净化被污染的冰蹄水井。",kw={"血蹄村","净化","莫高雷","穆尔·雷角","图腾","荆棘谷地精","水井","冰蹄"},ang={["class:Shaman"]="使用净化图腾体现了萨满教的核心原则，即运用土与水的元素和谐来驱逐人造的腐蚀。",["race:Tauren"]="淡水资源的亵渎打击了牛头人与大地母亲纽带的核心，使得该图腾的仪式成为捍卫家园的重要手段。"},sec={{t="净化泉水",b="当荆棘谷地精的工程队侵入莫高雷平原时，他们的工业作业迅速玷污了这片土地宝贵的地下水位。作为回应，穆尔·雷角准备了冰蹄之井净化图腾，为雕刻的木材注入了旨在清除外来毒素的保护魔法。图腾被带过敌对地精卫兵的防线，来到冰蹄水井边，通过一场专注的仪式驱散了污染，为平原上的游牧兽群和原住民部落恢复了纯净的饮用水。"}},faq={{q="冰蹄之井净化图腾有什么用途？",a="它被带到血蹄村东南部的冰蹄水井，用来执行净化仪式，洗刷掉荆棘谷地精向含水层倾倒的工业污染物。",al={"净化图腾用途","冰蹄图腾使用","图腾的作用"}},{q="是谁制作了这个图腾？",a="穆尔·雷角，一位受人尊敬的血蹄村牛头人居民，专门雕刻并准备了这个图腾，以修复冰蹄水井所遭受的破坏。",al={"谁制作了冰蹄图腾","净化图腾的制造者","穆尔的图腾"}},{q="为什么冰蹄水井会被污染？",a="荆棘谷地精在泉水周围建立了一个营地，用他们采伐和采矿机械产生的废水、废料和化学污泥玷污了天然的水源地。",al={"谁毒害了冰蹄之井","水井污染原因","为什么水井很脏"}},{q="净化仪式完成后会发生什么？",a="浑浊、被玷污的水再次变得清澈、健康，使当地的平原动物和迁徙的牛头人兽群能够再次安全地饮用井水。",al={"使用图腾后","水井净化的结果","水井会修复吗"}}},fp="26,132,20.464.0,48.142.0,23.133.0,43.172.0,51.128.0"}
P.entries["item:witchwing-talon"] = {n="巫翼鹰身人的爪子",s="巫翼鹰身人的爪子是一种从居住在贫瘠之地西北部峡谷的具有攻击性的鹰身人身上切下的利爪。它们被作为猎杀掠夺者的血腥证明而收集，十字路口的部落侦察兵们急需这些爪子来确保关键商道的安全。",h="巫翼鹰身人的爪子是一种从居住在贫瘠之地西北部峡谷的具有攻击性的鹰身人身上切下的利爪。它们被作为猎杀掠夺者的血腥证明而收集，十字路口的部落侦察兵们急需这些爪子来确保关键商道的安全。",kw={"贫瘠之地","商队","十字路口","达索克·快刀","鹰身人","爪子","巫翼"},ang={["class:Rogue"]="达索克·快刀欣赏安静、割喉般的精准，他将这些锋利的爪子视为针对空中捕食者的专业屠戮标志。",["faction:Horde"]="商队是连接卡利姆多各地部落前哨站的命脉，因此血腥铲除鹰身人巢穴是必不可少的边境安全措施。"},sec={{t="巢穴中的战利品",b="巫翼鹰身人栖息在十字路口西北部的峭壁和沟壑中，经常俯冲而下，掠夺穿越荒原的部落补给车队。为了应对这一威胁，侦察兵达索克·快刀协调了针对该族群层级的打击行动。达索克并不满足于简单的报告，他要求提供每一名死亡拾荒者的物理证据。收集这些锋利的爪子是掠夺者喉咙已被切开的具体证据，在侦察兵敢于对更高级别的指挥链发起打击之前，先消灭这些鹰身人的底层成员。"}},faq={{q="谁需要巫翼鹰身人的爪子，为什么？",a="驻扎在十字路口的兽人侦察兵达索克·快刀负责收集这些物品。他正在策划一场系统性的战役来清理巫翼族群，并需要八只爪子作为他们的前线掠夺者已被击杀的证据。",al={"谁需要爪子","巫翼鹰身人的爪子任务发布者","达索克·快刀 爪子"}},{q="哪些鹰身人携带这些爪子？",a="它们几乎可以从贫瘠之地西北部的任何巫翼鹰身人身上切下，特别是那些在悬崖和干旱山脊上筑巢的普通鹰身人和巫翼游羽鹰身人。",al={"什么掉落巫翼鹰身人的爪子","哪些鹰身人有爪子"}},{q="为什么要针对巫翼鹰身人？",a="巫翼族群变得越来越猖獗，经常袭击在贫瘠之地移动的部落补给线和商队。达索克的攻势旨在削减其下层阶级，然后再对她们的副官和主母发动攻击。",al={"为什么要杀巫翼鹰身人","鹰身人掠夺者目的"}}},fp="15,168,24.365.0,35.193.0,33.159.0,45.199.0"}
P.entries["item:wolf-heart-sample"] = {n="狼心样本",s="狼心样本是一份经过防腐处理的染病狼肉包裹，从洛丹伦枯萎的林地运往卡利姆多。它是受皇家药剂师学会之托运送的，为研究北方瘟疫如何影响贫瘠之地的动物群提供了至关重要的材料。",h="狼心样本是一份经过防腐处理的染病狼肉包裹，从洛丹伦枯萎的林地运往卡利姆多。它是受皇家药剂师学会之托运送的，为研究北方瘟疫如何影响贫瘠之地的动物群提供了至关重要的材料。",kw={"药剂师赫布瑞姆","药剂师伦弗利尔","贫瘠之地","十字路口","洛丹伦","皇家药剂师学会","毒素","狼心样本"},ang={["faction:Horde"]="将研究试剂跨海运输，凸显了连接幽暗城与贫瘠之地部落前哨站之间的后勤与科学合作。",["race:Undead"]="此次样本的运送展示了皇家药剂师学会不断扩展的科学触角，通过卡利姆多的异域生态来测试北方的配方。"},sec={{t="剧毒出口",b="这份心样本采集自游荡在洛丹伦废墟的染病狼群，最初是由药剂师伦弗利尔收集的，随后被打包运往无尽之海。被遗忘者的皇家药剂师学会不断寻求扩大对毒素、枯萎病和生物试剂的掌控。该包裹通过信使运往贫瘠之地的十字路口，代表了幽暗城化学研究的深远影响，将饱受创伤的东部王国的实验直接与卡利姆多的前哨站联系了起来。"},{t="赫布瑞姆的研究",b="样本抵达十字路口后，被交到了药剂师赫布瑞姆手中。赫布瑞姆的实地研究重点在于观察诞生于洛丹伦天灾军团蹂躏之地的强效毒素，是如何影响卡利姆多本土野生动物或使其产生适应的。通过研究这些狼心中保存的毒性，赫布瑞姆希望能发现新的特性，从而改进和强化被遗忘者远在他乡的毒药与药剂。"}},faq={{q="什么是狼心样本？",a="这是一份从洛丹伦枯萎的狼身上提取的防腐组织标本。它携带着北方瘟疫残留的毒性，被皇家药剂师学会用于研究剧毒。",al={"狼心样本","什么是样本","包裹里有什么"}},{q="是谁把这个样本送到贫瘠之地的？",a="幽暗城的药剂师金格送来的，这些狼心是药剂师伦弗利尔从银松森林寄给她的。",al={"谁寄送了狼心","谁给我的这个","狼心样本的来源"}},{q="药剂师赫布瑞姆为什么需要它？",a="赫布瑞姆正在调查来自洛丹伦的毒素如何影响卡利姆多的本土野兽。他打算分析该样本的毒性，以推进被遗忘者的炼金术和毒药合成研究。",al={"赫布瑞姆为什么需要它","赫布瑞姆的研究","狼心的用途"}},{q="这个样本需要送到哪里？",a="它必须被送到位于贫瘠之地心脏地带的部落主要据点——十字路口，交给药剂师赫布瑞姆。",al={"将狼心带到哪里","赫布瑞姆在哪里","运送地点"}}},fp="17,205,14.444.0,18.298.0,30.196.0,36.124.0,36.185.0,43.111.0"}
P.entries["item:wolf-heart-samples"] = {n="狼心样本",s="狼心样本是采集自银松森林中受腐蚀狼群的奇异有机样本。尽管具有致命的毒性，但这些心脏却在活着的生物体内跳动而不致其死亡，这引起了皇家药剂师协会浓厚的科研兴趣。",h="狼心样本是采集自银松森林中受腐蚀狼群的奇异有机样本。尽管具有致命的毒性，但这些心脏却在活着的生物体内跳动而不致其死亡，这引起了皇家药剂师协会浓厚的科研兴趣。",kw={"药剂师伦弗利尔","药剂师金格","皇家药剂师协会","银松森林","毒素","幽暗城","狼心样本"},ang={["race:Undead"]="皇家药剂师协会对致命试剂的不懈追求，为被遗忘者针对生者和亡灵敌人的生存与防御提供了保障。"},sec={{t="毒性的悖论",b="在检查银松森林的尸体时，药剂师伦弗利尔发现某些狼的心脏中含有一种致命的化合物。奇怪的是，组织中存在的毒素水平本应轻易毒死这些狼。伦弗利尔认识到这种在致命毒性饱和状态下依然能存活的生理机能具有独特的价值，于是留下了组织样本，准备直接送往幽暗城。对于被遗忘者来说，研究天生具有韧性或有毒的生物，是掌握生物战和合成新型试剂的关键一步。"},{t="托运至幽暗城",b="这些样本被托付给前往洛丹伦废墟地底深处的信使，并被送往位于幽暗城药剂区内皇家药剂师协会总部的药剂师金格手中。金格和她的同事们视新奇的毒素为至宝。通过解剖这些受污染的组织并进行实验，协会试图分离出剧毒化合物，并揭开这些野兽是如何在毒素中存活的奥秘，希望能将这些原理应用到他们自己的炼金项目中。"}},faq={{q="为什么这些狼心对被遗忘者如此重要？",a="这些样本中含有强烈的、无法解释的毒性，按理说足以毒死宿主狼。皇家药剂师协会对这种剧毒本身以及允许生物体存活的生物机制都非常着迷。",al={"为什么狼心很重要","是什么让这些心脏很特别","为什么药剂师想要狼心"}},{q="是谁请求收集这些样本的？",a="药剂师伦弗利尔在研究银松森林的狼群后收集了这些样本。他指示一名信使将它们直接送到幽暗城协会总部，交给他同事药剂师金格。",al={"谁想要这些狼心","是谁寄出的样本","是谁接收了样本"}},{q="药剂师金格会用它们做什么？",a="药剂师金格会对样本进行炼金实验和解剖。皇家药剂师协会不断地编目和将新奇毒素武器化，以开发出供希尔瓦娜斯女王使用的新型瘟疫和药剂。",al={"金格用这些心脏做什么","金格的实验","药剂师金格的研究"}},{q="这些狼来自哪里？",a="这些狼是在银松森林受污染的荒野中捕获的，该地区深受黑魔法、腐朽和奇异腐蚀的影响，导致当地动物发生了变异。",al={"这些狼来自哪里","银松森林的狼","狼的位置"}}},fp="18,168,15.383.0,24.357.0,54.186.0,27.205.0,40.167.0,31.132.0"}
P.entries["item:wood-pulp"] = {n="木浆",s="木浆是一种纤维状材料，由驻扎在南贫瘠之地巴尔莫丹的矮人人员携带。虽然它本身无害，却是拜尔丹探险队用来稳定液体炸药的关键吸收基质。",h="木浆是一种纤维状材料，由驻扎在南贫瘠之地巴尔莫丹的矮人人员携带。虽然它本身无害，却是拜尔丹探险队用来稳定液体炸药的关键吸收基质。",kw={"巴尔莫丹","拜尔丹","贫瘠之地","加恩·石塔","硝化甘油","加恩的复仇","硝酸钠","木浆"},ang={["profession:Engineering"]="任何工程师都能认出这种混合物：将木屑或木浆与硝化甘油和硝酸盐氧化剂混合，是将不稳定的液体化合物稳定为耐用炸药的经典方法。",["race:Tauren"]="对于石塔部族来说，用入侵者的工业军火来对付巴尔莫丹，是对他们祖居之地所受破坏的一种诗意正义。"},sec={{t="一份不稳定的配方",b="驻扎在巴尔莫丹的铁炉堡矮人使用重型土方设备和化学炸药，在牛头人祖传的狩猎场上开凿大地。液态硝化甘油本身极其不稳定；为了使其能用于挖掘和战斗，矮人工程师将其与硝酸钠一同吸附进多孔的木浆中，从而制成稳定的炸药。矮人火枪手、士兵和军官手头都备有这种纤维材料，用于爆破作业和野战军火。"},{t="矛头对准要塞",b="在勘探员卡兹戈姆倒下后，流离失所的牛头人战士加恩·石塔找回了矮人的爆破图纸。加恩不想让挖掘场继续侵蚀他部族的土地，于是他将这些工程技术反过来用在了入侵者身上。通过从拜尔丹驻军那里回收木浆、硝化甘油和硝酸盐，加恩将它们混合成一种特制的炸药，意图摧毁巴尔莫丹的飞行机器。"}},faq={{q="在巴尔莫丹，木浆有什么用处？",a="在矮人的军火制造中，木浆起到了吸收基质的作用。纯硝化甘油极其不稳定，容易发生意外爆炸，但将其浸入木浆等有机物质中，可以让工兵安全地运输和处理强力爆破炸药。",al={"为什么矮人有木浆","木浆的用途","木浆的作用"}},{q="在贫瘠之地，是谁携带了木浆？",a="木浆由驻扎在南贫瘠之地巴尔莫丹的矮人部队携带，包括拜尔丹士兵、火枪手、军官以及他们的指挥官，赛瑞克·黑炉。",al={"去哪里获取木浆","谁掉落木浆","木浆位置"}},{q="加恩·石塔为什么要这些木浆？",a="加恩·石塔计划将矮人的破坏性技术反过来对付他们。他按照矮人的爆破图纸，将木浆与回收的硝化甘油和硝酸钠混合，制造出一种足以摧毁巴尔莫丹飞行机器的炸药。",al={"谁需要木浆","加恩·石塔 木浆","为什么要收集木浆"}},{q="木浆本身会爆炸吗？",a="不会。粗木浆只是粉碎的木纤维。只有当它与硝化甘油等挥发性化学物质和硝酸钠等氧化剂结合时，才会变得危险。",al={"木浆是炸药吗","木浆会爆炸吗"}}},fp="9,195,17.376.0,23.357.1,41.196.0,37.176.0,45.264.0,33.167.0"}
P.entries["item:wooden-key"] = {n="木制钥匙",s="木制钥匙是一把简单的雕刻钥匙，由徘徊在灰谷北部靠近费伍德森林边缘的疯狂古树携带。它用于解锁一个隐藏的箱子，里面装着达图尔的变形魔棒的一件残骸，那是一件古老的暗夜精灵圣物。",h="木制钥匙是一把简单的雕刻钥匙，由徘徊在灰谷北部靠近费伍德森林边缘的疯狂古树携带。它用于解锁一个隐藏的箱子，里面装着达图尔的变形魔棒的一件残骸，那是一件古老的暗夜精灵圣物。",kw={"灰谷","疯狂古树","达图尔的变形魔棒","费伍德森林","铁杆","莎尔蒂恩","枯萎的古树","木制钥匙"},ang={["class:Druid"]="持有这把钥匙的扭曲古树，反映了恶魔枯萎病正在毒害灰谷与费伍德森林之间的塞纳里奥树林，其影响令人悲痛。",["race:NightElf"]="看到卡利姆多备受爱戴的古树陷入疯狂，并紧握着遗失的圣物徘徊在费伍德森林的道路上，这对任何星之子来说都是令人悲伤的景象。"},sec={{t="疯手中的钥匙",b="木制钥匙由徘徊在林中树居以北阴影小径上的疯狂古树和枯萎的古树持有。莎尔蒂恩曾经了解当地的树人，但现在她形容它们的本质已被腐化扭曲。其中一只古树带着一把钥匙，可以打开装有达图尔的变形魔棒部件的箱子。"},{t="解锁变形魔棒",b="树妖莎尔蒂恩委托冒险者取回这把钥匙，以打开位于费伍德森林道路以西一小片林间空地中隐藏的破旧箱子。里面放着铁杆，这是重建达图尔的变形魔棒并对抗正在毒害神圣森林的蔓延腐化所需的关键组件之一。"}},faq={{q="木制钥匙能解锁什么？",a="木制钥匙可以打开一个藏在通往费伍德森林北向大路西侧一小片空地里的破旧箱子。箱子里装着铁杆，这是重铸达图尔的变形魔棒所需的部件。",al={"木制钥匙开启什么","木制钥匙箱子","在哪里使用木制钥匙"}},{q="谁携带木制钥匙？",a="这把钥匙由徘徊在林中树居以北、靠近费伍德森林边界森林里的疯狂古树和枯萎的古树携带。",al={"谁掉落木制钥匙","哪里找到木制钥匙","木制钥匙掉落"}},{q="为什么古树会有这把钥匙？",a="莎尔蒂恩说，费伍德森林附近被腐化的树人之一携带着这把钥匙。她没有说明它是如何落入树人手中的。",al={"为什么树人有钥匙","古树钥匙背景故事"}},{q="是谁派你去取回木制钥匙？",a="莎尔蒂恩是一位在灰谷照料净化月亮井的树妖，她指引冒险者取回钥匙，作为重组达图尔的变形魔棒努力的一部分。",al={"木制钥匙任务给予者","谁需要木制钥匙"}}},fx={ebbbe3a2={q="木制钥匙是什么？",a="木制钥匙是一把简单的雕刻钥匙，由在灰谷北部、费伍德森林附近游荡的堕落树人携带。它是用来锁住一只隐秘宝箱的，箱中藏着已故暗夜精灵达图尔的一件遗物。",al={"木制钥匙信息","木制钥匙是什么","关于木制钥匙"}},a6fc69e1={q="莎尔蒂恩为什么想要木制钥匙？",a="莎尔蒂恩需要这把钥匙，这样你就能打开费伍德森林边界附近林间空地中的那只破旧宝箱。里面有一根铁杆，是重新组装达图尔之杖并净化这片土地所必需的关键部件。",al={"为什么需要木制钥匙","为什么要取回木制钥匙","为什么有人想要木制钥匙"}}},fp="10,161,18.255.0,17.257.1,32.168.0,27.122.0,34.137.0,41.150.0"}
P.entries["item:worn-parchment"] = {n="破旧的羊皮纸",s="破旧的羊皮纸是散落在黑海岸北部的奥萨拉克斯之塔周围的邪教徒所携带的残缺仪式文书。这些破烂的纸片被侦察兵收集起来，为识别聚集在废墟中的邪恶教派提供了首批具体的线索。",h="破旧的羊皮纸是散落在黑海岸北部的奥萨拉克斯之塔周围的邪教徒所携带的残缺仪式文书。这些破烂的纸片被侦察兵收集起来，为识别聚集在废墟中的邪恶教派提供了首批具体的线索。",kw={"奥萨拉克斯","巴苏尔·影击","黑滩","黑海岸","狂热者","破旧的羊皮纸"},ang={["class:Warlock"]="黑滩教派携带的文书揭示了一个在暗夜精灵领地上秘密活动的组织，他们在远离联盟和部落视线的地方操纵着邪能和暗影。",["race:NightElf"]="在像奥萨拉克斯这样的古老遗迹附近出现黑暗施法者和恶魔腐蚀，是对黑海岸神圣荒野的严重亵渎。"},sec={{t="邪恶阴谋的碎片",b="在黑海岸薄雾笼罩的海岸以北，黑暗施法者及其狂热的追随者占领了荒废的奥萨拉克斯之塔。在塔外巡逻的步兵，被称为黑滩狂热者，他们随身携带着破旧的羊皮纸残片。虽然单看碎片似乎只是零碎的涂鸦和深奥的符号，但将多个碎片拼凑在一起，就揭示了一个此前未知的组织的存在：黑滩教派。"},{t="揭露邪教",b="巴苏尔·影击，一名在附近高地监视着这座塔的侦察兵，利用这些收集到的羊皮纸为净化者德尔格伦和奥伯丁的哨兵评估威胁。将这些文本拼凑起来证实，塔中的术士并非独立的流浪者，而是一个组织严密的邪教，其计划尚不为人所知。"}},faq={{q="谁携带着这些破旧的羊皮纸？",a="这些羊皮纸由黑滩狂热者携带，他们是驻扎在黑海岸北部奥萨拉克斯之塔外围的邪教步兵。",al={"谁掉落破旧的羊皮纸","在哪里获得破旧的羊皮纸","破旧的羊皮纸来源"}},{q="羊皮纸上写了什么？",a="它们单独来看是仪式笔记和命令的隐晦片段。一旦收集起来并由巴苏尔·影击破译，它们就揭示了黑滩教派的名称和存在。",al={"破旧的羊皮纸上写了什么","破旧的羊皮纸内容","羊皮纸的含义"}},{q="为什么巴苏尔·影击要收集它们？",a="巴苏尔受净化者德尔格伦之托监视奥萨拉克斯之塔。他需要这些文书来破译为何术士们会聚集在废墟中，并在汇报之前评估对黑海岸的危险。",al={"谁需要破旧的羊皮纸","巴苏尔任务","为什么要收集羊皮纸"}},{q="黑滩教派是什么？",a="他们是一群在奥萨拉克斯废墟中活动的秘密邪教徒和术士组织。即使是像巴苏尔·影击这样经验丰富的侦察兵，在发现这些文书之前也从未遇到过他们的教团。",al={"黑滩教派","谁是黑滩教派"}}},fp="14,114,28.404.0,18.313.1,34.152.0,34.183.0,45.201.0,36.221.0"}
P.entries["item:worn-stone-token"] = {n="用旧的石雕",s="用旧的石雕是达拉然的人员和法师在奥特兰克山脉随身携带的小型魔法护身符。虽然它们所蕴含的魔法能量大多已经消散，但它们最初是为了帮助肯瑞托束缚并号令元素仆从而制作的。",h="用旧的石雕是达拉然的人员和法师在奥特兰克山脉随身携带的小型魔法护身符。虽然它们所蕴含的魔法能量大多已经消散，但它们最初是为了帮助肯瑞托束缚并号令元素仆从而制作的。",kw={"奥特兰克山脉","达拉然","元素","看守者贝瓦里尔","虚空之光法师","石雕信物","塔伦米尔","用旧的石雕"},ang={["class:Mage"]="法师们认为这些信物是肯瑞托在野外保持召唤出的元素稳定和顺从时所使用的实用法术焦点物品。",["faction:Horde"]="获取这些信物有助于塔伦米尔的被遗忘者研究奥特兰克境内敌对的肯瑞托势力的奥术防御和惯例。"},sec={{t="元素掌握的信物",b="达拉然的法师们长期以来一直拥有对元素实体的强大支配力，他们使用特殊的护身符来迫使这些来自异界的生物服从自己的意志。用旧的石雕代表了这些工具能量耗尽或枯竭后的状态。不仅是神学家和召唤师，就连驻扎在奥特兰克废墟和收容所周围的达拉然劳工和卫兵也会随身携带，这说明了元素束缚之术在达拉然的日常运作中是如何根深蒂固的。"},{t="被遗忘者的好奇心",b="被遗忘者在塔伦米尔的前哨站里密切监视着附近的法师。虚空之光法师试图寻找这些信物的样本，以破译达拉然束缚元素的方法。看守者贝瓦里尔指示特工们先收集那些陈旧、无活性的信物，以便让这位法师在尝试研究更强大、更不稳定的导能器之前，能够安全地分析其基础的附魔技术。"}},faq={{q="这些信物有什么用途？",a="达拉然的法师们使用这些魔法石雕来号令并束缚从其他位面召唤而来的元素，让它们充当劳工、卫兵和防御者。",al={"用旧的石雕用途","什么是石雕信物","为什么达拉然人携带信物"}},{q="为什么这些信物被描述为“用旧的”？",a="它们所激活的附魔效果随着时间的推移和频繁的使用已经消退了。看守者贝瓦里尔认为这些失去活性的样本对于虚空之光法师进行达拉然束缚仪式的初步研究来说更加安全。",al={"为什么用旧了","信物有魔法吗","无活性的信物"}},{q="谁会携带这些信物？",a="在奥特兰克山脉南部活动的各类达拉然人员身上都能发现这些信物，从高级召唤师和神学家，到普通的劳工、持盾卫兵，以及收容所的贝拉穆尔典狱官。",al={"谁掉落用旧的石雕","在哪里获得信物","达拉然信物掉落"}},{q="为什么被遗忘者想要这些东西？",a="虚空之光法师希望研究达拉然控制元素的奥术技术，试图揭开他们召唤和奴役艺术背后的秘密。",al={"为什么贝瓦里尔想要信物","虚空之光法师信物"}}},fx={["4cdbd814"]={q="用旧的石雕是什么？",a="用旧的石雕是一件褪色的魔法神器，由达拉然法师制作。这些附魔石块是奥术器具，用来束缚、命令和控制从其他位面召唤来的元素仆从。随着时间流逝或经过频繁使用，其中蕴含的魔力已经减弱，变得毫无生气，但它们仍保留着达拉然元素技艺的结构奥秘。",al={"用旧的石雕是什么","用旧的石雕","石雕"}},["2e06b1f4"]={q="用旧的石雕从哪里来？由谁制作？",a="这些石雕由达拉然的法师和工匠制作。达拉然是一个以精通异次元魔法而闻名的法师政权。你会发现驻扎在奥特兰克山脉各处的达拉然部队携带着它们，其中包括召唤师、神官、盾卫、工人，以及附近收容所的典狱官贝拉摩尔。",al={"用旧的石雕由谁制作","石雕的来源","石雕从哪里来"}}},fp="16,188,27.379.0,18.329.0,32.156.0,37.186.0,25.188.0,32.122.0"}
P.entries["item:woven-wand"] = {n="狼人魔杖",s="狼人魔杖是一件独特的附魔圣物，很久以前由三位达拉然的法师学徒为了誓结兄弟情谊而共同制作。在洛丹伦沦陷以及创造者之间发生惨痛背叛后，这根魔杖被藏在了芬里斯城堡，直到后来被遗忘者发现。",h="狼人魔杖是一件独特的附魔圣物，很久以前由三位达拉然的法师学徒为了誓结兄弟情谊而共同制作。在洛丹伦沦陷以及创造者之间发生惨痛背叛后，这根魔杖被藏在了芬里斯城堡，直到后来被遗忘者发现。",kw={"阿拉里克","比索·埃斯沙德","达拉然","芬里斯城堡","冈瑟尔·阿坎努斯","magic quarter","瑟尔·拉文克劳","狼人魔杖"},ang={["class:Mage"]="狼人魔杖体现了达拉然学徒的古老传统，他们经常尝试融合个人导管，以集中他们的集体奥术潜力。",["race:Undead"]="这件神器是对那些在天灾中丧生的凡人生命的苦涩纪念，将两位幸存的遗忘者对堕落同伴疯狂行径的记忆联结在了一起。"},sec={{t="隐秘壁龛",b="尽管瑟尔在堕入黑暗后开始厌恶这根魔杖所代表的感伤情绪，但他始终无法狠心将其摧毁或交给昔日的同伴。相反，他带着这件神器前往银松森林，并将其深藏在芬里斯城堡的一个壁龛中。多年后，随着瑟尔的巢穴被攻破，他的仆从阿拉里克指引部落特工找到了这个藏身处，这件圣物得以完好无损地取回。由于这位死灵法师从未唤醒过魔杖中沉睡的附魔，这根魔杖最终被送到了幽暗城Magic Quarter的比索·埃斯沙德手中。"},{t="破碎的羁绊",b="在达拉然仍培训北方年轻法师的日子里，三位立志成为法师的学徒——比索·埃斯沙德、冈瑟尔·阿坎努斯和瑟尔·拉文克劳——将各自的学徒魔杖编织成了一枚护身符。这根狼人魔杖既是他们共同魔法力量的导管，也是他们持久友谊的象征。然而，当亡灵天灾席卷洛丹伦时，这份情谊彻底破碎了。瑟尔·拉文克劳选择向巫妖王效忠，转而投身于邪恶的死灵法术。与此同时，亡灵瘟疫夺走了比索和冈瑟尔的生命，最终彻底切断了他们与达拉然的联系。"}},faq={{q="谁制作了狼人魔杖？",a="这根魔杖由三位达拉然的法师学徒共同制作：比索·埃斯沙德、冈瑟尔·阿坎努斯和瑟尔·拉文克劳。他们将三根独立的学徒魔杖合为一件共同的神器，以象征他们的友谊。",al={"谁制作了狼人魔杖","狼人魔杖的创造者","魔杖制造者"}},{q="为什么魔杖会被藏在芬里斯城堡？",a="在瑟尔背叛同伴转而效忠巫妖王后，他开始厌恶这件神器以及它所代表的羁绊。然而，他无法割舍或摧毁它，于是将其藏在自己在芬里斯城堡的巢穴里的一个秘密壁龛中。",al={"瑟尔为什么要藏起魔杖","在哪里找到狼人魔杖","为什么在芬里斯城堡"}},{q="为什么比索·埃斯沙德认为魔杖已经遗失了？",a="比索以为当他们的友谊破裂、瘟疫蹂躏大地时，魔杖就已经彻底遗失了。他还指出瑟尔从未敢唤醒其中的魔法能量；如果瑟尔使用了它，比索凭借他们之间残留的魔法连接，定能感知到那股涌动的魔力。",al={"比索怎么说这根魔杖","比索对魔杖的反应"}},{q="魔杖是如何被找回的？",a="部落的冒险者为了击败瑟尔·拉文克劳而袭击了芬里斯城堡。在拉文克劳的前仆从阿拉里克那颗被砍下但依然能说话的头颅指引下，他们找到了藏有魔杖的隐蔽壁龛，并将它从废墟中带了出来。",al={"谁找到了魔杖","如何获得狼人魔杖"}}},fp="10,185,17.501.1,15.439.1,27.162.1,39.206.0,48.212.0,27.152.1"}
P.entries["item:xavian-water-sample"] = {n="克萨维亚水样",s="一瓶纯净的、注入了魔法的水，取自萨维亚古老精灵遗迹中最高瀑布的底部。奥格瑞玛的部落法师们寻找它，是为了揭开保存在灰谷最古老圣地中的潜在奥术力量。",h="一瓶纯净的、注入了魔法的水，取自萨维亚古老精灵遗迹中最高瀑布的底部。奥格瑞玛的部落法师们寻找它，是为了揭开保存在灰谷最古老圣地中的潜在奥术力量。",kw={"灰谷","迪诺","奥格瑞玛","萨特","碎木岗哨","水样","萨维亚"},ang={["class:Mage"]="取回样本是部落法师的一项基本实地考验，测试他们驾驭天然奥术源泉以及在充满敌意、受恶魔污染的土地上行动的能力。",["faction:Horde"]="随着部落在灰谷围绕碎木岗哨建立更稳固的立足点，采集萨维亚的古老奥术资源为奥格瑞玛的学者们提供了至关重要的知识。"},sec={{t="古城之水",b="萨维亚是一座传说中的古老精灵城市，关于它古老知识的传说在学者中广为人知。即使是在废墟之中，据说其水域也蕴含着巨大的魔法力量。奥格瑞玛的奥术导师迪诺派遣初露头角的法师深入灰谷，从萨维亚最高瀑布下的水潭中直接采集新鲜样本。获取它需要勇闯危险的领地，因为这些遗迹现在由腐化的萨特严密守卫，他们对任何闯入的施法者都充满敌意。"}},faq={{q="水样是在哪里采集的？",a="它是通过在萨维亚遗迹内最高瀑布下方的水潭中灌满迪诺的瓶子来采集的。该地点位于灰谷东北部，穿过碎木岗哨和萨提纳尔之外的湖泊向北走即可到达。",al={"萨维亚水样获取地点","萨维亚瀑布位置","如何获取萨维亚水样"}},{q="迪诺为什么要这种水？",a="迪诺是一位驻扎在奥格瑞玛Valley of Spirits的奥术导师。她研究强大而不同寻常的魔法源，以教育年轻的部落从业者，寻找保存在萨维亚宁静水域中的古老魔法精华。",al={"谁需要萨维亚水样","为什么要采集萨维亚的水","迪诺的目的"}},{q="什么威胁守卫着萨维亚的水域？",a="这些古老的精灵遗迹居住着萨特，这些恶魔生物憎恨入侵者，并拼命捍卫自己的领地，抵御好奇的法师。周围的水道也是鳄鱼等攻击性野兽的栖息地。",al={"萨维亚有什么敌人","谁住在萨维亚","萨维亚的危险"}},{q="样本被带回奥格瑞玛后会发生什么？",a="迪诺立即开始研究样本的奥术特性，利用收集到的魔法来推进她的研究，并辅助部落法师的训练和指导。",al={"萨维亚水样交还","水有什么用途"}}},fx={ff7d6737={q="克萨维亚水样是什么？",a="这是一只装满水的瓶子，水取自克萨维亚废墟最高瀑布的底部。据说这座古老暗夜精灵聚居地的水蕴含着强大的魔力，引起了部落学者的浓厚兴趣。",al={"克萨维亚水样是什么","克萨维亚水样","克萨维亚水瓶"}},["27a4db96"]={q="克萨维亚水样从哪里来？由谁制作？",a="这些水取自克萨维亚中心的天然瀑布。克萨维亚是一座古老的精灵城市，深藏于灰谷东部。没有凡人匠人制作过它；清澈的水流经浸透古老暗夜精灵魔法、并残留着如今占据此地的萨特腐化之力的废墟。",al={"克萨维亚的水从哪里来","克萨维亚水样由谁制作","克萨维亚水的来源"}}},fp="19,166,26.432.0,36.181.0,31.235.0,40.178.0,54.183.0"}
P.entries["item:young-crocolisk-skin"] = {n="小鳄鱼皮",s="小鳄鱼皮是从湿地各处幼年鳄鱼身上剥下的一种柔韧爬行动物皮。这种皮深受米奈希尔港的詹姆斯·哈洛兰等当地制皮师的喜爱，经过鞣制后会被出口到艾泽拉斯各地的港口。",h="小鳄鱼皮是从湿地各处幼年鳄鱼身上剥下的一种柔韧爬行动物皮。这种皮深受米奈希尔港的詹姆斯·哈洛兰等当地制皮师的喜爱，经过鞣制后会被出口到艾泽拉斯各地的港口。",kw={"鳄鱼","詹姆斯·哈洛兰","皮革","米奈希尔港","皮","制皮","湿地"},ang={["class:Hunter"]="在湿地泥泞的边缘潜行搜寻鳄鱼皮，是为米奈希尔港繁忙的皮革贸易提供供应的追踪者们的日常工作。"},sec={{t="沼泽地的制皮与贸易",b="米奈希尔港是卡兹莫丹西海岸一个繁忙的商业枢纽，将沼泽特产出口到遥远的港口。该镇最赚钱的出口商品之一，就是港口驻地制皮师詹姆斯·哈洛兰加工的鞣制皮革。虽然成年鳄鱼的皮厚且鳞片坚硬，但幼年鳄鱼的皮更加柔软，更易于加工。由于这些幼年鳄鱼皮质地细腻且需求量大，哈洛兰依靠当地猎人和过往旅客在镇外泥泞的沼泽中搜寻，以确保证他的鞣皮架上有充足的库存。"}},faq={{q="为什么詹姆斯·哈洛兰特别需要幼年鳄鱼的皮？",a="与完全长成的鳄鱼相比，幼年鳄鱼的皮显著更柔软。虽然成年野兽拥有厚实、坚硬的鳞片，但幼崽的皮更容易加工和鞣制成柔韧的商品，这些商品在海上贸易航线上需求量很大。",al={"为什么需要小鳄鱼皮","哈洛兰的皮革","为什么需要柔软的皮革"}},{q="在哪里可以找到幼年鳄鱼？",a="幼年湿地鳄鱼栖息在米奈希尔港外围的湿地西部的水道、沼泽和泥塘中。",al={"幼年鳄鱼的位置","去哪里找幼年鳄鱼","湿地鳄鱼"}},{q="还有谁为港口猎杀这些鳄鱼？",a="一位名叫Einar的当地猎人经常为詹姆斯·哈洛兰的制皮生意带回鳄鱼皮，尽管需求往往超过了一个追踪者所能供应的数量。",al={"谁在猎杀鳄鱼","猎人einar","米奈希尔的制皮猎人"}},{q="这些鞣制好的皮革被运往哪里？",a="哈洛兰的成品会被装上离开米奈希尔港的商船，运往东部王国乃至更远地区的主要港口和市场。",al={"鳄鱼皮贸易","米奈希尔的皮革出口","皮革运往哪里"}}},fx={["2363e64c"]={q="小鳄鱼皮是什么？",a="这是从湿地沼泽中游荡的幼年鳄鱼身上剥取的生皮，质地柔软。由于幼兽还没有长出成年鳄鱼那种厚实坚硬的鳞片，它们的皮更柔韧，深受当地制皮匠人青睐。",al={"小鳄鱼皮是什么","小鳄鱼皮物品","鳄鱼皮的含义"}},a9554702={q="小鳄鱼皮从哪里来？",a="这些皮直接取自栖居在米奈希尔港周边湿润沼泽中的小鳄鱼。它们不是加工制品，而是从猎杀的野兽身上剥下的天然兽皮，之后再经过鞣制加工成优质皮革。",al={"小鳄鱼皮的来源","去哪里获取小鳄鱼皮","小鳄鱼皮由谁制作"}}},fp="20,169,32.472.0,70.175.0,36.120.0,47.148.0,36.153.0"}
P.entries["item:yowler-s-paw"] = {n="犹勒的爪子",s="犹勒的爪子是从犹勒身上取下的可怕战利品，它是威胁湖畔镇上方山丘的豺狼人凶猛的首领。将其交给城镇工匠弗纳·奥斯古，就是那个统领当地豺狼人族群的野兽已被消灭的铁证。",h="犹勒的爪子是从犹勒身上取下的可怕战利品，它是威胁湖畔镇上方山丘的豺狼人凶猛的首领。将其交给城镇工匠弗纳·奥斯古，就是那个统领当地豺狼人族群的野兽已被消灭的铁证。",kw={"豺狼人族群首领","山丘上的嚎叫","湖畔镇","赤脊山豺狼人","赤脊山","弗纳·奥斯古","犹勒","犹勒的爪子"},ang={["class:Hunter"]="追踪赤脊山豺狼人的首领并取回他的爪子，是对抗危险掠食者时对荒野追踪和野兽驯服技巧的考验。",["faction:Alliance"]="在暴风城的军队因兵力分散而无法保护其东部边境之际，击败犹勒并找回他的爪子有助于稳定赤脊山的局势。"},sec={{t="族群首领的战利品",b="赤脊山的豺狼人长期以来一直恐吓着止水湖周围的高地，它们令人毛骨悚然的嚎叫声回荡在湖畔镇的定居点里。在它们之中，最令人恐惧的莫过于犹勒，这个冷酷的阿尔法正驱使着它们的扩张。由于豺狼人的耳朵和爪子在人类领地通常被视为悬赏任务的证明，弗纳·奥斯古便请求勇敢的冒险者带回犹勒的爪子。割下爪子不仅标志着这只异常狡猾的掠食者的死亡，更是为了摧毁他那乌合之众般的追随者之间的指挥链而采取的有计划的行动。"},{t="一个被遗弃的城镇",b="带回犹勒的爪子凸显了湖畔镇严峻的局势。暴风城军队正全神贯注于应对盘踞在石堡要塞周围的黑石兽人威胁，迫使当地政务官员和镇民不得不雇佣路过的雇佣兵来进行防御。在没有正规皇家驻军的情况下，获取像犹勒的爪子这样的证明，是像弗纳·奥斯古这样的定居者确保当地道路能维持基本的贸易与通行安全的唯一途径。"}},faq={{q="谁要求获得犹勒的爪子？",a="弗纳·奥斯古，湖畔镇的一位杰出商人和居民，请求获得这只爪子。他想要证明那只恐吓山丘的危险豺狼人首领已经被彻底解决。",al={"谁想要犹勒的爪子","弗纳·奥斯古 爪子任务","犹勒的爪子任务交付"}},{q="谁是犹勒？",a="犹勒是赤脊山豺狼人族群的凶猛首领。与普通的杂种豺狼人不同，他拥有集结多个族群所需的蛮力和狡诈，这使他成为对附近镇民的迫切威胁。",al={"谁是犹勒","犹勒背景故事","赤脊山豺狼人首领"}},{q="为什么湖畔镇依靠悬赏而不是暴风城的士兵？",a="暴风城军队正忙于应付在赤脊山东部石堡要塞中设防的黑石兽人威胁，已无暇分身。由于抽不出援军，像弗纳·奥斯古这样的镇民必须依靠自由冒险者来猎杀像犹勒这样的威胁。",al={"为什么没有暴风城卫兵","暴风城军队在哪里","为什么弗纳要雇佣雇佣兵"}},{q="犹勒死后会发生什么？",a="杀死犹勒会破坏统领这些好斗豺狼人的领导核心，导致他的族群四散奔逃到荒野中，从而为湖畔镇的居民争取到暂时的喘息空间。",al={"犹勒死后会发生什么","犹勒死后的豺狼人","山丘上的嚎叫结局"}}},fx={["5e9f7255"]={q="犹勒的爪子是什么？",a="犹勒的爪子是赤脊山豺狼人首领被斩下的爪子，用来作为他毙命的实物证据。湖畔镇的弗纳·奥斯古请求冒险者猎杀这头凶残的首领并取回爪子，以确认这个暴徒终于被杀死。",al={"犹勒的爪子是什么","犹勒的爪子物品","犹勒的爪子"}},c7fb7fcc={q="犹勒的爪子从哪里来？",a="这不是加工制成的物品，而是犹勒本人的断肢。犹勒统领着在湖畔镇上方丘陵中游荡的凶悍豺狼人，比那些威胁赤脊山的普通杂种更加凶猛狡诈。",al={"去哪里获取犹勒的爪子","犹勒的爪子由谁制作","犹勒的爪子来源"}},["034bdc4c"]={q="弗纳·奥斯古为什么想要犹勒的爪子？",a="弗纳·奥斯古要求拿到爪子，以此作为这名凶恶豺狼人首领已死的确凿证据。暴风城的军队正全力应对黑石兽人，湖畔镇只能依靠路过的冒险者清除当地的猛兽；弗纳必须先看到证据，才会给你报酬。",al={"为什么有人想要犹勒的爪子","弗纳为什么想要犹勒的爪子","犹勒的爪子悬赏"}}},fp="12,155,25.445.0,22.398.0,26.181.0,14.148.0,66.225.0,35.170.0"}
P.entries["item:zalazane-s-head"] = {n="扎拉赞恩的头颅",s="扎拉赞恩的头颅是交给加德林大师的一件残酷战利品，用以确认叛徒巫医扎拉赞恩的覆灭。它的取回标志着将回音群岛从控制暗矛巨魔家园的黑暗魔法中解放出来，迈出了关键的一步。",h="扎拉赞恩的头颅是交给加德林大师的一件残酷战利品，用以确认叛徒巫医扎拉赞恩的覆灭。它的取回标志着将回音群岛从控制暗矛巨魔家园的黑暗魔法中解放出来，迈出了关键的一步。",kw={"暗矛部族","回音群岛","加德林","受妖术影响的巨魔","森金村","巫毒巨魔","扎拉赞恩","扎拉赞恩的头颅"},ang={["faction:Horde"]="除掉扎拉赞恩可以为部落确保杜隆塔尔南海岸的安全，防止黑暗魔法破坏萨尔刚刚建立的领地。",["race:Troll"]="对于暗矛巨魔来说，夺取扎拉赞恩的头颅是对那个将他们驱逐出家园并奴役他们兄弟的叛徒进行的一场深刻的复仇与正义之举。"},sec={{t="叛徒末路的证明",b="当巫医扎拉赞恩背叛暗矛巨魔时，他利用奴役心灵的妖术夺取了他们的岛屿家园，将沃金的族人驱赶到了杜隆塔尔的沿海地区。扎拉赞恩不断从回音群岛向外派遣受妖术控制的奴隶，跨越水域去抓捕更多的受害者。为了让森金村焦虑的难民们相信暴君的恐怖统治已经终结，加德林大师要求必须提供他死亡的实证。带回这颗被砍下的头颅不仅确认了扎拉赞恩在战斗中的失败，还为流离失所的部族带来了一丝难得的安宁，以及有朝一日收复被窃岛屿的希望。"}},faq={{q="谁想要扎拉赞恩的头颅？",a="居住在杜隆塔尔南海岸森金村的巫医加德林大师要求冒险者带回扎拉赞恩的头颅，作为他已被击杀的证明。",al={"谁想要扎拉赞恩的头颅","扎拉赞恩任务发放者","加德林与扎拉赞恩"}},{q="为什么要针对扎拉赞恩？",a="扎拉赞恩曾是暗矛巨魔中受人尊敬的巫师，但对力量的渴望驱使他利用控制心灵的魔法奴役了自己的族人。他将部族赶出了回音群岛，并不断突袭大陆，抓捕更多的暗矛巨魔来扩充他的奴隶大军。",al={"为什么要杀扎拉赞恩","扎拉赞恩做了什么","扎拉赞恩背景故事"}},{q="扎拉赞恩在哪里？",a="扎拉赞恩盘踞在杜隆塔尔东南海岸外的回音群岛中最大的一座岛上，周围环绕着被妖术控制并束缚于他麾下的巫毒巨魔。",al={"扎拉赞恩在哪","扎拉赞恩位置","回音群岛扎拉赞恩"}},{q="带回头颅能收复回音群岛吗？",a="虽然杀死扎拉赞恩消除了他突袭带来的直接威胁，并让森金村得以喘息，但回音群岛依然危险重重，且到处都是他残留的巫毒奴隶，导致暗矛巨魔大部分时间仍立足于大陆。",al={"巨魔能收复回音群岛吗","回音群岛收复了吗","回音群岛安全吗"}}},fp="15,136,26.524.0,29.143.0,26.232.0,24.143.0,46.223.0"}
P.entries["item:zamah-s-note"] = {n="扎玛的便笺",s="扎玛的便笺是一封从雷霆崖的扎玛寄往塔伦米尔的药剂师林度恩的信件。信中提出了一个紧急请求，希望能获得一种炼金药剂，以便在不直接诉诸流血冲突的情况下解决石爪山脉的荆棘谷地精问题。",h="扎玛的便笺是一封从雷霆崖的扎玛寄往塔伦米尔的药剂师林度恩的信件。信中提出了一个紧急请求，希望能获得一种炼金药剂，以便在不直接诉诸流血冲突的情况下解决石爪山脉的荆棘谷地精问题。",kw={"希尔斯布莱德丘陵","林度恩","石爪山脉","塔伦米尔","雷霆崖","幽暗城","荆棘谷地精","扎玛"},ang={["faction:Horde"]="这封信的送达突显了部落在卡利姆多与东部王国之间遥远首都之间的后勤合作与资源共享。",["race:Undead"]="这份便笺强调了外部盟友对皇家药剂师协会专业化学知识的日益依赖，以解决复杂的危机。"},sec={{t="跨越无尽之海的请求",b="荆棘谷地精的行动已在石爪山脉根深蒂固，他们正在砍伐森林并破坏这片神圣的土地。扎玛为了寻找一种无需引发大规模屠杀的特殊解决方案，向被遗弃者皇家药剂师协会寻求帮助。这封便笺是正式的通信，向身处洛丹伦希尔斯布莱德丘陵塔伦米尔的同事药剂师林度恩详细说明了石爪山脉的严峻局势。"},{t="药剂师间的联系",b="携带这封密封的信件需要跨越大陆进行长途跋涉，指引卡利姆多的旅行者乘坐飞艇前往幽暗城，再穿过银松森林进入希尔斯布莱德。在收到扎玛的便笺后，林度恩对她的具体要求产生了浓厚兴趣，他为远在重洋之外的消息能传到自己手中感到自豪，并准备为解决地精问题研制一种炼金药剂。"}},faq={{q="什么是扎玛的便笺？",a="这是一封由雷霆崖的扎玛亲笔书写并密封的信件，寄给塔伦米尔的药剂师林度恩，请求对方提供一种炼金配方，以将荆棘谷地精赶出石爪山脉。",al={"这个物品是什么","扎玛的便笺","给林度恩的信"}},{q="为什么扎玛需要塔伦米尔的帮助？",a="扎玛寻求一种非传统的、不流血的解决方案来驱逐那些正在破坏石爪山脉的地精。她向药剂师林度恩求助，因为被遗弃者炼金师拥有专门用于此类微妙破坏行动的化学药剂。",al={"为什么要寄往希尔斯布莱德","为什么要联系林度恩","为什么是塔伦米尔"}},{q="这封信需要送到哪里？",a="它必须送到位于洛丹伦希尔斯布莱德丘陵、由被遗弃者控制的塔伦米尔镇，交给药剂师林度恩。",al={"谁收到了便笺","扎玛的便笺上交","我该把便笺带去哪里"}},{q="便笺中提到的荆棘谷地精是谁？",a="荆棘谷地精是一个冷酷无情的地精采矿与伐木组织，他们因在卡利姆多各地砍伐森林、掠夺自然资源并污染土地而臭名昭著，包括石爪山脉的神圣山峰。",al={"石爪山脉的荆棘谷地精","荆棘谷地精是谁","荆棘谷地精"}}},fp="12,191,27.383.0,22.323.0,21.167.0,42.180.0,41.93.0,49.208.0"}
P.entries["item:zargh-s-meats"] = {n="扎尔夫的肉品",s="扎尔夫的肉品是居住在十字路口的兽人扎尔夫精心准备的一包上等鲜肉。这份包裹是送给奥格瑞玛旅店老板格雷什卡的私人礼物，同时也旨在向年轻的部落旅人们介绍该地区的双足飞龙航线网络。",h="扎尔夫的肉品是居住在十字路口的兽人扎尔夫精心准备的一包上等鲜肉。这份包裹是送给奥格瑞玛旅店老板格雷什卡的私人礼物，同时也旨在向年轻的部落旅人们介绍该地区的双足飞龙航线网络。",kw={"十字路口","迪弗拉克","格雷什卡","肉品","奥格瑞玛","valley of strength","双足飞龙","扎尔夫"},ang={["profession:Cooking"]="这些鲜肉深受旅店老板格雷什卡的喜爱，展现了兽人在烹饪上对直接取自贫瘠之地野生野兽、只需极少烹饪的红肉的偏爱。",["race:Orc"]="将扎尔夫的精选肉品送到格雷什卡手中，能引导年轻的兽人找到他们主城的中心——力量谷，并让他们明白通过双足飞龙进行空中旅行的必要性。"},sec={{t="信使的货物",b="这份包裹由扎尔夫准备，他是一位驻扎在贫瘠之地十字路口的屠夫兼猎人，包裹里装着打算送往奥格瑞玛力量谷旅店老板格雷什卡的精选鲜肉。由于新鲜的猎物在稀树草原干燥炎热的气候下很快就会腐烂，扎尔夫会将包裹托付给前往十字路口飞行点的信使。在那里，双足飞龙管理员迪弗拉克会安排迅捷的空中坐骑，直接将旅客送往奥格瑞玛的天空之墙，省去了穿越杜隆塔尔的艰苦跋涉。"},{t="通往心扉的路径",b="虽然这看似只是一次普通的补给运送，但这批货物却承载着深厚的个人情谊。在收到包裹后，格雷什卡立刻就注意到了扎尔夫通过优质猎物博取女士欢心的技巧，并急切地准备将这些稀有肉块煎熟，提供给旅店的常客和宾客。对于刚抵达的兽人和巨魔冒险者来说，运送这些肉品也是一次了解卡利姆多部落定居点之间长距离飞行交通的重要入门经历。"}},faq={{q="谁准备了扎尔夫的肉品？",a="这些肉是由扎尔夫采集并包装的，他是一位驻扎在贫瘠之地十字路口哨所的兽人。",al={"谁制作了扎尔夫的肉品","扎尔夫是谁","肉从哪里来"}},{q="肉品的接收者是谁？",a="这些肉块被送往格雷什卡，她是奥格瑞玛力量谷主旅店的经营者。",al={"谁收到肉","格雷什卡是谁","我在哪里递交扎尔夫的肉品"}},{q="为什么必须用双足飞龙运送这些肉？",a="新鲜肉类在贫瘠之地和杜隆塔尔的酷热中很快就会腐烂。扎尔夫会将信使指引给十字路口的飞行管理员迪弗拉克，这样就能通过双足飞龙在肉类变质前将其送达奥格瑞玛。",al={"为什么要飞着送肉","迪弗拉克 双足飞龙 肉"}},{q="为什么只有特定种族才能运送这个包裹？",a="兽人和巨魔旅者会被托付扎尔夫前往奥格瑞玛的差事，而牛头人冒险者则会被指引前往雷霆崖运送兽皮，被遗忘者的信使则负责将补给送回瑟伯切尔。",al={"为什么牛头人接不到这个任务","亡灵 扎尔夫的肉品","谁能运送扎尔夫的肉品"}}},fp="13,149,17.408.0,18.387.0,27.95.0,34.76.0,41.188.0,48.175.0"}
P.entries["item:zhevra-hooves"] = {n="斑马蹄",s="斑马蹄是从漫步在贫瘠之地干旱平原上的野生马科动物身上采集到的坚实动物肢体部位。它们被当作猎物战利品带到十字路口，以证明旅行者有能力对抗那些外表看起来比实际更凶猛的野兽。",h="斑马蹄是从漫步在贫瘠之地干旱平原上的野生马科动物身上采集到的坚实动物肢体部位。它们被当作猎物战利品带到十字路口，以证明旅行者有能力对抗那些外表看起来比实际更凶猛的野兽。",kw={"贫瘠之地","十字路口","暗棘","蹄子","狩猎","奔跑者","塞尔格拉","斑马"},ang={["class:Hunter"]="在稀树草原上追踪斑马可以教会神射手和捕猎者如何处理迅捷、敏捷的群居动物，它们能迅速转身并用毁灭性的踢击发动攻击。",["faction:Horde"]="对于刚到达贫瘠之地的新兵来说，为塞尔格拉·暗棘采集蹄子是一项早期的试炼仪式，展示了他们保卫十字路口的能力。"},sec={{t="狩猎的战利品",b="斑马看起来可能只是普通的条纹食草动物，但它们结实且肌肉发达的腿部却极具杀伤力。十字路口的负责人，兽人萨满祭司塞尔格拉·暗棘，通过派部落新兵去采集斑马奔跑者蹄子的任务来考验他们。这项练习旨在磨练初出茅庐的猎人的直觉和韧性，因为众所周知，受惊的奔跑者猛踢的一脚，甚至能将强壮的牛头人踢得人仰马翻。提交完整的蹄子可以证明猎人有能力应付迅速且会踢人的猎物，从而为挑战卡利姆多更致命的掠食者做好准备。"}},faq={{q="谁需要斑马蹄？",a="位于贫瘠之地十字路口的兽人萨满祭司塞尔格拉·暗棘会要求猎人带给她四只斑马蹄，以证明他们已经准备好面对更艰巨的挑战。",al={"谁需要蹄子","谁收购斑马蹄","塞尔格拉的蹄子"}},{q="斑马蹄来自哪里？",a="它们是从斑马奔跑者身上采集的，这些动物在十字路口南北两侧广阔的稀树草原上随处可见。",al={"在哪里获得蹄子","斑马奔跑者位置","寻找斑马"}},{q="为什么狩猎斑马很危险？",a="虽然斑马不像迅猛龙或潜行者那样具有攻击性，但它们的后腿拥有巨大的踢力。来自奔跑中斑马的直接踢击足以将一名成年牛头人踢倒在地。",al={"斑马强壮吗","斑马踢击力度","斑马危险性"}},{q="为什么塞尔格拉让猎人追踪斑马而不是更凶猛的野兽？",a="塞尔格拉认为斑马比平原陆行鸟高出一个难度等级，为新手提供了一个既安全又稳妥的试炼场，让他们在面对真正致命的生物之前磨练自己的技巧。",al={"为什么要猎杀斑马","塞尔格拉的训练目的"}}},fp="13,114,20.440.0,24.152.0,33.106.0,33.179.0,69.136.0"}
P.entries["npc:abercrombie"] = {n="亚伯克隆比",s="亚伯克隆比看起来是一个虚弱而古怪的隐士，住在暮色森林西部乌鸦岭墓地附近的一间破旧棚屋里。他声称自己是一个饱受森林恐怖事物困扰、人畜无害的隐居者，并乐于招募富有同情心的旅行者，为他收集奇特的试剂和补给品。",h="亚伯克隆比看起来是一个虚弱而古怪的隐士，住在暮色森林西部乌鸦岭墓地附近的一间破旧棚屋里。他声称自己是一个饱受森林恐怖事物困扰、人畜无害的隐居者，并乐于招募富有同情心的旅行者，为他收集奇特的试剂和补给品。",kw={"亚伯克隆比","憎恶","夜色镇","暮色森林","伊莱扎","食尸鬼雕像","乌鸦岭","隐士"},ang={["class:Paladin"]="亚伯克隆比代表了亡灵巫术的邪恶腐化，这种腐化伪装成一个需要救济的普通、无害的城镇居民而不断滋生。",["class:Warlock"]="亚伯克隆比牺牲自己的心脏来复活尸体的行为，展示了凡人为了掌握黑暗魔法可以做出何种极端的自毁行为。",["faction:Alliance"]="天真地向这位可怜的隐士伸出援手的联盟英雄们，在不知不觉中提供了策划袭击夜色镇所需的材料。"},sec={{t="乌鸦岭的隐士",b="亚伯克隆比躲藏在乌鸦岭墓地附近的腐朽阴影中，显得十分可怜。他把自己伪装成一个只想在暮色森林的恐怖中生存下去的老人，请求旅行者前往夜色镇跑跑腿，帮他带回一些补给品、草药和丝线。对于那些不了解该地区历史的人来说，他看起来只是在这个省份衰落后被遗弃的又一个不幸的灵魂。"},{t="缚尸者的疯狂",b="在悲伤吞噬他的理智之前，亚伯克隆比曾是一位受人尊敬、和蔼可亲的炼金术士，居住在乌鸦岭。当他深爱的妻子伊莱扎去世后，悲痛击碎了他的理智。他转向禁忌的亡灵魔法，挖出了自己的心脏，放入伊莱扎死去的胸膛中试图让她复活。这个仪式唯一的结果就是创造了一个怪物：伊莱扎复活了，但被诅咒着对活人的血肉有着无法满足的饥渴，这迫使这位疯狂的炼金术士不得不将她埋葬在墓地里。"},{t="巨大的欺骗",b="亚伯克隆比在黑暗的民间传说中被称为“缚尸者”，他对夜色镇及其领导人怀有深刻且病态的怨恨。他指派给乐于助人的冒险者那些看似无害的任务——去取食尸鬼的肋骨、特种丝线和腐蚀性药剂——实际上是组装缝合怪所需的最后组件，这是一种巨大的、由血肉缝合而成的憎恶，旨在屠杀守夜人并蹂躏这座城镇。"}},faq={{q="亚伯克隆比是谁？",a="亚伯克隆比是一位住在暮色森林乌鸦岭墓地附近的隐士。他曾是一位技艺精湛的炼金术士，在妻子去世后失去了理智，私下里，他就是被称为“缚尸者”的亡灵法术使用者。",al={"谁是那个隐士","亚伯克隆比背景故事","亚伯克隆比是谁"}},{q="为什么亚伯克隆比需要从夜色镇获取补给？",a="虽然亚伯克隆比声称他需要日常用品和丝线来在荒野中生存，但实际上他是在欺骗冒险者，让他们收集组装巨大憎恶缝合怪所需的必要部件。",al={"亚伯克隆比为什么需要丝线","亚伯克隆比的补给","亚伯克隆比在建造什么"}},{q="伊莱扎是谁？",a="伊莱扎是亚伯克隆比的妻子。在她去世后，亚伯克隆比试图用黑暗魔法复活她，并将自己的心脏移植到她的尸体中。她复活成了一个贪婪的亡灵怪物，迫使他不得不将她继续埋葬在乌鸦岭墓地中。",al={"伊莱扎·亚伯克隆比","亚伯克隆比的妻子","缚尸者的新娘"}},{q="把那封信交给市长会发生什么？",a="埃洛领主无法阅读它，因为它是用一种古老的语言写成的，所以他让希拉·沃宁迪翻译了它。翻译内容揭示了亚伯克隆比做了一些不可言说的事情，一旦埃洛读了它，巨大的缝合怪就会开始从乌鸦岭顺着大路向夜色镇蹒跚走去。",al={"给市长的信","信上写了什么","亚伯克隆比的信件"}},{q="为什么亚伯克隆比痛恨夜色镇？",a="亚伯克隆比从不解释自己的行为。在妻子去世后，被悲痛和黑暗魔法逼疯的他，一边嘲讽地称市长埃洛·埃博洛克为老朋友，一边派出了他那巨大的造物顺着大路去摧毁夜色镇。",al={"亚伯克隆比为什么袭击夜色镇","缚尸者的动机","亚伯克隆比的复仇"}},{q="亚伯克隆比是天灾军团的盟友吗？",a="不。亚伯克隆比是一位独来独往的隐士，与巫妖王的军队没有任何联系。",al={"亚伯克隆比属于天灾军团吗","亚伯克隆比为谁效力"}}},fx={["5abf44f4"]={q="亚伯克隆比为什么住在乌鸦岭墓地附近？",a="亚伯克隆比住在暮色森林西部、乌鸦岭墓地东北方一间孤零零的小屋里，远离夜色镇。他自称是个无害而古怪的隐士，还会请路过的旅人从镇上替他带些补给。",al={"亚伯克隆比为什么在这里","乌鸦岭的亚伯克隆比","亚伯克隆比所在位置的原因"}},a3c5130f={q="亚伯克隆比为什么令整个暮色森林的人都害怕？",a="亚伯克隆比表面上是个无害的隐士，实际上却是那个令人胆寒的“防腐师”。当地传说和孩子们的故事讲述了他如何堕入疯狂的通灵术，为了让死去的妻子复生为嗜肉的食尸鬼，竟亲手剖出自己的心脏。光是他的名字，就足以让人想起那些被禁忌之术缝合而成、并被释放到生者之间的恐怖怪物。",al={"亚伯克隆比为什么令人畏惧","防腐师亚伯克隆比的名声","暮色森林的防腐师"}}},fp="11,251,25.395.0,22.379.2,21.366.1,19.181.2,50.193.1,14.225.1,52.291.2,36.238.1,39.72.0"}
P.entries["npc:aelthalyste"] = {n="艾萨莱斯特",s="艾萨莱斯特是一位女妖牧师训练师，也是被遗忘者教派中的杰出人物，驻扎在幽暗城的War Quarter。她负责监督被遗忘者侍僧的精神修行，教导他们掌握暗影的黑暗能量。她还与其他部落信仰领袖进行协调，指引巨魔侍僧前往奥格瑞玛寻找他们自己的长者。",h="艾萨莱斯特是一位女妖牧师训练师，也是被遗忘者教派中的杰出人物，驻扎在幽暗城的War...",kw={"艾萨莱斯特","女妖","噬灵瘟疫","牧师","暗影","幽暗城","乌尔库","war quarter"},ang={["class:Priest"]="对于被遗忘者牧师来说，艾萨莱斯特代表了他们教义的核心，传授专门的暗影法术并提供暗影修行之路上的指导。",["faction:Horde"]="她与乌尔库等卡利姆多训练师的合作证明了宗教上的尊重如何有助于弥合年轻部落联盟之间的文化鸿沟。",["race:Troll"]="艾萨莱斯特没有强迫巨魔新兵接受被遗忘者的仪式，而是出于相互尊重，将暗矛牧师引导回奥格瑞玛的乌尔库那里。",["race:Undead"]="艾萨莱斯特反映了被遗忘者从生前所信仰的圣光，向着更务实的暗影之力转化的过程。"},sec={{t="被遗忘的暗影之声",b="与艾泽拉斯各地崇敬圣光的牧师不同，艾萨莱斯特引导那些背弃了圣光的被遗忘者牧师转向暗影之力。作为一名无形的死者，她体现了Sylvanas Windrunner追随者那幽灵般的痛苦与坚韧不拔的决心。从她位于幽暗城War Quarter的房间里，她召回渴望修行的牧师从偏远的前哨站归来，以掌握其修习法门中更黑暗的部分，教导他们利用苦难作为一种致命的武器。"},{t="与部落的纽带",b="虽然她的重心始终坚定地放在她的被遗忘者同胞身上，但艾萨莱斯特与其他部落精神修行者保持着相互尊重。意识到暗矛部族精神主义的独特性质，她将巨魔新兵引导离开她自己的暗影教义，并将他们送到海对岸奥格瑞玛的乌尔库那里。这种尊重的姿态确保了部落施法者能够在他们自己的文化传统中成长，同时也巩固了卡利姆多和洛丹伦之间的联盟。"}},faq={{q="谁是艾萨莱斯特？",a="艾萨莱斯特是一位居住在幽暗城War Quarter的女妖牧师训练师。她是该被遗忘者教派的主要导师之一，负责指导被遗忘者修行者学习暗影魔法。",al={"艾萨莱斯特背景故事","谁是女妖牧师","艾萨莱斯特npc"}},{q="我在哪里可以找到艾萨莱斯特？",a="她位于幽暗城洛丹伦王都遗迹下方的War Quarter，周围环绕着其他被遗忘者导师。",al={"艾萨莱斯特位置","艾萨莱斯特在哪里","寻找艾萨莱斯特"}},{q="被遗忘者牧师信仰什么？",a="许多被遗忘者牧师认为圣光在他们死后抛弃了他们。他们不再像生前那样崇敬圣光，而是转向了暗影，拥抱黑暗、意志力和个人修行。",al={"被遗忘的暗影","被遗忘者牧师宗教","被遗忘的暗影教派"}},{q="为什么艾萨莱斯特要把巨魔牧师送到奥格瑞玛？",a="艾萨莱斯特认识到巨魔与灵魂和暗影的关系与被遗忘者的教义大相径庭。出于尊重，她将巨魔侍僧送到位于Valley of Spirits的暗矛牧师训练师乌尔库那里接受训练。",al={"乌尔库 艾萨莱斯特","为什么要送走巨魔","艾萨莱斯特巨魔任务"}},{q="艾萨莱斯特传授什么？",a="她为被遗忘者玩家提供核心的牧师教学，并将进阶侍僧引导至标志性的亡灵仪式，包括像虚弱之触和黑暗牺牲这样的法术。",al={"牧师训练艾萨莱斯特","艾萨莱斯特教授的法术","艾萨莱斯特能力"}},{q="艾萨莱斯特效忠于Sylvanas吗？",a="是的。作为幽暗城内的一名女妖，她效忠于Sylvanas Windrunner，并积极致力于通过掌握暗影魔法来壮大被遗忘者。",al={"艾萨莱斯特阵营","她是否效忠幽暗城","女妖忠诚度"}}},fp="11,188,29.452.0,19.359.0,19.162.0,29.136.0,33.195.0,53.247.0,28.182.0,33.146.0"}
P.entries["npc:agathelos-the-raging"] = {n="暴怒的阿迦赛罗斯",s="暴怒的阿迦赛罗斯是一头巨大的装甲野猪，被关押在剃刀沼泽的多刺隧道之中。对于视伟大的野猪阿迦玛甘为神灵与始祖的野猪人来说，这样体型的野兽具有极其重大的精神意义，而且它在愤怒时会变得更加可怕。它庞大的身躯和惊人的力量使它成为了潜伏在南贫瘠之地地底最危险的野兽之一。",h="暴怒的阿迦赛罗斯是一头巨大的装甲野猪，被关押在剃刀沼泽的多刺隧道之中。对于视伟大的野猪阿迦玛甘为神灵与始祖的野猪人来说，这样体型的野兽具有极其重大的精神意义，而且它在愤怒时会变得更加可怕。它庞大的身躯和惊人的力量使它成为...",kw={"阿迦玛甘","阿迦赛罗斯","野猪","死亡之颅","野猪人","暴怒","剃刀沼泽"},ang={["class:Druid"]="德鲁伊们非常敬重阿迦玛甘，视其为在上古之战中陨落的伟大半神之一；看到它的一位巨大同族被关在剃刀沼泽中愤怒咆哮，令人感到一丝凄凉。",["class:Hunter"]="猎人或许会欣赏阿迦赛罗斯那纯粹的掠食者体魄，但它那无尽的愤怒注定了它是一头只能被杀死的野兽，而不是被驯服的宠物。",["race:Tauren"]="深谙大地之道的牛头人非常了解阿迦玛甘的传说，他们意识到野猪人对其同类野兽的腐化，是贫瘠之地遭受侵蚀的又一个迹象。"},sec={{t="伟大野猪的化身",b="野猪人的神灵与始祖是阿迦玛甘，一头泰坦般的野猪。因此，像阿迦赛罗斯这样体型的野兽——足足有两头贫瘠之地雷蜥那么大——在剃刀沼泽的各个部落中具有相当重要的精神意义。"},{t="身陷囹圄",b="野猪人并没有让阿迦赛罗斯在剃刀沼泽中自由走动。它被关在由几名野猪人守卫看守的一片场地后方的一条死胡同隧道里。如果有闯入者突破了这道防线，他们就会面对一头在愤怒时体型会变得更大、更加恐怖的狂暴野兽。"}},faq={{q="阿迦赛罗斯为什么这么巨大？",a="阿迦赛罗斯是一头天生体型巨大的装甲野猪，大约有普通雷蜥的两倍大，而且它在愤怒时体型还会进一步增大。对于视阿迦玛甘（一头泰坦野猪）为神灵与始祖的野猪人来说，这种体型的野兽具有相当重要的精神意义。",al={"阿迦赛罗斯为什么巨大","阿迦赛罗斯体型","贫瘠之地巨型野猪"}},{q="为什么野猪人要把它锁在屏障后面？",a="野猪人将阿迦赛罗斯关在由几名守卫维护的场地后方的一条短隧道里，这样这头凶猛狂暴的野猪就无法在剃刀沼泽中自由游荡了。",al={"阿迦赛罗斯屏障","阿迦赛罗斯为什么被关押","阿迦赛罗斯力场"}},{q="它与阿迦玛甘有什么联系？",a="阿迦玛甘是伟大的野猪半神，也是野猪人种族的始祖。由于这种血缘关系，像阿迦赛罗斯这样巨大的野猪对野猪人来说具有相当重要的精神意义。",al={"阿迦赛罗斯阿迦玛甘","阿迦赛罗斯是神吗","阿迦玛甘之子"}},{q="是哪个部落创造了阿迦赛罗斯？",a="阿迦赛罗斯是一头野兽，并非由谁创造。它是由剃刀沼泽的死亡之颅野猪人所饲养的，他们将它关在荆棘深处的一条受守卫看守的隧道中。",al={"谁制造了阿迦赛罗斯","谁喂养阿迦赛罗斯","阿迦赛罗斯部落"}},{q="猎人可以驯服阿迦赛罗斯吗？",a="不能。阿迦赛罗斯是一头精英级、全身披甲的怪物，太危险了，无法被猎人驯服。",al={"驯服阿迦赛罗斯","我可以驯服阿迦赛罗斯吗","猎人阿迦赛罗斯"}}},fx={a8df9e57={q="暴怒的阿迦赛罗斯是谁？",a="暴怒的阿迦赛罗斯是一头被关在剃刀沼泽深处的巨型披甲野猪。对于野猪人而言，他们的神祇和始祖阿迦玛甘是一头泰坦巨兽般的野猪，因此阿迦赛罗斯具有相当重要的灵性意义；它的体型约有普通雷霆蜥蜴的两倍，战斗时还会变得更加骇人。",al={"阿迦赛罗斯是谁","阿迦赛罗斯的身份","什么是暴怒的阿迦赛罗斯"}},["28c36899"]={q="暴怒的阿迦赛罗斯站在哪一边？",a="阿迦赛罗斯只是一头野兽，并非阴谋家。它被剃刀沼泽的野猪人看守着，关在一条设有守卫的隧道里，任何闯入它领地的人都会遭到攻击。",al={"阿迦赛罗斯的阵营","阿迦赛罗斯侍奉谁","阿迦赛罗斯站在哪一边"}},["38ca6f4f"]={q="暴怒的阿迦赛罗斯想要什么？",a="阿迦赛罗斯没有什么远大抱负，也没有自己的狡诈阴谋。它被纯粹的野性怒火吞噬，只想粉碎、顶撞并践踏任何闯入它领地的东西。",al={"阿迦赛罗斯想要什么","阿迦赛罗斯的动机","阿迦赛罗斯的目标"}},be737a36={q="暴怒的阿迦赛罗斯为什么令人畏惧？",a="阿迦赛罗斯因其骇人的庞大身躯和无法遏制的狂怒而令人畏惧。它身披甲胄，天生体型就极为庞大；发怒时，体型和凶性还会进一步暴涨，足以用蹄子踏碎整支突袭队伍。",al={"阿迦赛罗斯为什么令人畏惧","阿迦赛罗斯有多危险","阿迦赛罗斯的名声"}}},fp="20,322,25.219.0,14.268.0,25.267.0,53.165.0,36.158.0,29.134.0,27.102.0"}
P.entries["npc:aggem-thorncurse"] = {n="阿格姆",s="阿格姆是一位居住在剃刀沼泽的野猪人萨满，拥有“死亡之首预言者”的头衔。当受到威胁时，他会召唤一个野猪之魂来协助作战。",h="阿格姆是一位居住在剃刀沼泽的野猪人萨满，拥有“死亡之首预言者”的头衔。当受到威胁时，他会召唤一个野猪之魂来协助作战。",kw={"阿格姆","剃刀沼泽","野猪人","thorncurse"},ang={["class:Priest"]="他作为预言者的头衔反映了野猪人的精神传统。",["class:Shaman"]="阿格姆召唤野猪之魂协助他，这是野猪人萨满教的一种独特表现。",["faction:Horde"]="由于野猪人不断威胁着贫瘠之地，消灭像阿格姆这样顽固的防守者有助于保障杜隆塔尔和莫高雷的安全。"},sec={{t="死亡之首预言者",b="阿格姆守卫着剃刀沼泽中被死亡之首部族占据的一片区域。他的萨满力量包括召唤野猪之魂，这反映了野猪人对阿迦玛甘的崇敬。"}},faq={{q="阿格姆是谁？",a="阿格姆是一位野猪人萨满，也是剃刀沼泽中的死亡之首预言者。",al={"阿格姆","阿格姆是谁","阿格姆 剃刀沼泽"}},{q="在哪里可以找到阿格姆？",a="他在南贫瘠之地的剃刀沼泽内。",al={"阿格姆位置","阿格姆在哪里","哪里可以找到阿格姆"}},{q="阿格姆召唤的是什么灵魂？",a="阿格姆会召唤一个野猪之魂与他并肩作战。",al={"阿格姆 灵魂","阿格姆 野猪之魂"}},{q="阿格姆如何进行战斗？",a="阿格姆使用萨满魔法，并召唤一个野猪之魂与他并肩作战。",al={"阿格姆 技能","阿格姆如何战斗"}},{q="阿格姆隶属于特定的野猪人部族吗？",a="他属于死亡之首部族。",al={"阿格姆 部族","阿格姆属于什么部族","剃刀沼泽 野猪人"}}},fx={["0a149290"]={q="阿格姆为什么在这里？",a="阿格姆身处剃刀沼泽的亡首野猪人之中，守卫着部族的领地。",al={"阿格姆·荆棘诅咒为什么在剃刀沼泽","阿格姆·荆棘诅咒所在位置的原因"}},["32004356"]={q="阿格姆与谁有关联？",a="他属于亡首部族，修习野猪人的萨满传统。",al={"阿格姆·荆棘诅咒的人脉","阿格姆·荆棘诅咒与谁结盟"}}},fp="16,124,24.174.0,24.70.0,36.61.0,33.48.0,31.70.0,62.40.0"}
P.entries["npc:ahanu"] = {n="安哈努",s="安哈努是雷霆崖下层高地赫瓦军械库里的一名牛头人商人。他为前往莫高雷及更广阔平原的旅行者和年轻勇士制作并交易皮甲。他也会协助刚抵达的信使，引导他们在从附近定居点送信时在峭壁间穿行。",h="安哈努是雷霆崖下层高地赫瓦军械库里的一名牛头人商人。他为前往莫高雷及更广阔平原的旅行者和年轻勇士制作并交易皮甲。他也会协助刚抵达的信使，引导他们在从附近定居点送信时在峭壁间穿行。",kw={"安哈努","赫瓦军械库","加翰·鹰翼","皮甲","莫高雷","雷霆崖"},ang={["race:Tauren"]="对于刚从十字路口乘坐第一次双足飞龙航班抵达的年轻牛头人勇士来说，安哈努既能提供熟悉的招待，也能提供路途必备的皮料。"},sec={{t="赫瓦军械库商人",b="安哈努位于雷霆崖下层高地的制皮摊位和军械库之中，为那些在卡利姆多大草原上谋生的人们提供必需的装备。他利用他的朋友加翰·鹰翼从十字路口送来的兽皮进行加工，代表了那些确保牛头人主城物资供应充足，提供耐用熟皮和鞣革装备的普通工匠。对于刚从十字路口乘坐双足飞龙抵达的旅行者来说，安哈努通常是他们在这座大城市里的第一个接触点，负责接收货物并指引信使前往当地的飞行点。"}},faq={{q="安哈努是谁？",a="安哈努是一位居住在雷霆崖下层高地赫瓦军械库里的牛头人商人。他出售皮甲并协助从十字路口抵达主城的信使。",al={"安哈努 npc","安哈努 剧情","安哈努是谁"}},{q="安哈努卖什么？",a="他出售各种基础的熟皮和鞣革皮甲，包括为猎人、潜行者和年轻冒险者设计的皮上衣、腰带、靴子和护腕。",al={"安哈努商品","安哈努货物","安哈努 供应商"}},{q="我在雷霆崖哪里能找到他？",a="安哈努位于雷霆崖下层高地的赫瓦军械库内，靠近其他的护甲商、制皮师和武器商。",al={"安哈努 位置","安哈努在哪里","安哈努 地图"}},{q="有哪些任务与安哈努有关？",a="年轻的牛头人冒险者在任务“前往雷霆崖”中会被指派乘坐双足飞龙为他送货，之后他会指引他们去找城市的双足飞龙管理员塔尔。",al={"安哈努 任务","前往雷霆崖 安哈努"}}},fp="5,239,25.376.0,13.146.0,21.139.0,38.119.0,26.155.0"}
P.entries["npc:aku-mai"] = {n="阿库麦尔",s="阿库麦尔是一头巨大的三头九头蛇，栖息在佐拉姆海岸的黑暗深渊沉没的废墟之中。它是上古之神的一名仆从，当上古之神的腐化污染了神庙神圣的月亮井时，它便从水中升起。暮光之锤邪教聚集在黑暗深渊中，向它献祭无辜者以获取力量。",h="阿库麦尔是一头巨大的三头九头蛇，栖息在佐拉姆海岸的黑暗深渊沉没的废墟之中。它是上古之神的一名仆从，当上古之神的腐化污染了神庙神圣的月亮井时，它便从水中升起。暮光之锤邪教聚集在黑暗深渊中，向它献祭无辜者以获取力量。",kw={"阿库麦尔","黑暗深渊","深渊","九头蛇","克尔里斯","上古之神","佐拉姆"},ang={["class:Druid"]="阿库麦尔非自然的腐化扭曲了灰谷的沿海水域，需要净化以恢复自然平衡。",["class:Priest"]="阿库麦尔和暮光之锤卑劣的存在，代表了上古之神对圣光和艾露恩教义的腐蚀。",["race:NightElf"]="阿库麦尔玷污了一座曾经供奉月亮女神艾露恩的神庙中最深处的圣所，将一处圣地变成了一个腐化的巢穴。"},sec={{t="佐拉姆海岸的灾祸",b="黑暗深渊曾是艾露恩的一座伟大神庙，直到上古之神的腐化从大地深处渗出并污染了其神圣的月亮井。阿库麦尔，一头巨大的九头蛇兼上古之神的仆从，从水中升起。阿库麦尔并非普通的潮汐生物，它是佐拉姆海岸的一场活体瘟疫，占据了暗夜精灵陷落神庙的沉没废墟，用它的恶意毒害着水域。"},{t="原始黑暗的仆从",b="阿库麦尔邪恶的存在最终将暮光之锤吸引到了地下的洞穴深处。在梦游者克尔里斯的带领下，并与娜迦结盟，邪教徒们占据了这座被淹没的神庙，并向阿库麦尔献祭无辜者以获取力量。"}},faq={{q="阿库麦尔是什么？",a="阿库麦尔是一头沉浸在黑暗力量中的古老三头九头蛇。作为上古之神的仆从，它从黑暗深渊受污染的水中升起，现在潜伏在神庙被淹没的大厅中。",al={"谁是阿库麦尔","阿库麦尔背景故事","阿库麦尔是什么怪物"}},{q="阿库麦尔住在哪里？",a="阿库麦尔栖息在黑暗深渊最深处的淹没洞穴中，黑暗深渊是一座供奉艾露恩的废弃神庙建筑群，位于灰谷西北部的佐拉姆海岸沿岸。",al={"阿库麦尔位置","阿库麦尔在哪里","我在哪里可以找到阿库麦尔"}},{q="为什么暮光之锤要供养阿库麦尔？",a="暮光之锤崇拜阿库麦尔，视其为他们所信仰的上古之神的仆从。在梦游者克尔里斯的带领下，邪教徒们向这头野兽献祭无辜者，以换取黑暗力量。",al={"为什么邪教徒要供养阿库麦尔","克尔里斯 阿库麦尔","暮光之锤 阿库麦尔"}},{q="阿库麦尔拥有什么力量？",a="除了巨大的体型和多张足以撕咬的头颅外，阿库麦尔还带有上古之神的黑暗恩赐。在战斗中，它会陷入狂暴，并将靠近的敌人吞没在毒雾中。",al={"阿库麦尔的力量","阿库麦尔有魔法吗","虚空九头蛇"}},{q="阿库麦尔是上古之神吗？",a="不。阿库麦尔不是上古之神，而是一头侍奉上古之神的原始九头蛇。它邪恶的存在足以吸引暮光之锤在其周围崇拜。",al={"阿库麦尔是上古之神吗","阿库麦尔是神吗"}},{q="为什么冒险者要冒险进入深渊去击杀它？",a="如果放任不管，阿库麦尔的野蛮行径和邪教徒的虔诚将威胁要在整个灰谷和卡利姆多引发灾难性的邪恶。联盟和部落的当局都寻求终结暮光之锤，并铲除潜伏在神庙深处的恐怖怪物。",al={"为什么要击杀阿库麦尔","黑暗深渊的邪恶阿库麦尔","阿库麦尔的威胁"}}},fx={["055a774d"]={q="阿库麦尔站在哪一边？",a="阿库麦尔侍奉一位上古之神，不效忠于任何凡人种族。暮光之锤教派崇拜这头野兽，并以无辜者为祭品，换取黑暗力量。",al={"阿库麦尔的阵营","阿库麦尔侍奉谁","阿库麦尔的忠诚对象"}},["7b9e18bb"]={q="阿库麦尔想要什么？",a="阿库麦尔是一头凶残的野兽，并非阴谋家。它是上古之神的仆从，潜伏在黑暗深渊受污染的水域中；暮光之锤教徒以无辜者为祭品，希望恢复上古之神统治世界的时代。",al={"阿库麦尔的目标","阿库麦尔渴望什么","阿库麦尔的目的"}},["6cae52d5"]={q="阿库麦尔为什么在黑暗深渊？",a="当上古之神的腐化从地底渗出，污染了沉没神庙的月亮井时，阿库麦尔便从神庙水中崛起。如今，黑暗深渊的沉没大厅为暮光之锤教派提供了一处阴暗的水下藏身之所，让他们能在此庇护并秘密崇拜这头野兽。",al={"阿库麦尔为什么在黑暗深渊","阿库麦尔是如何来到这里的","阿库麦尔藏身处"}},ba41fb22={q="阿库麦尔与谁有关？",a="阿库麦尔是上古之神的仆从。在黑暗深渊，梦游者克尔里斯率领暮光之锤崇拜这头野兽，并向它献祭无辜者以换取力量。",al={"阿库麦尔相关人物","谁控制阿库麦尔","阿库麦尔与克尔里斯"}},["989c4b42"]={q="阿库麦尔为何如此令人畏惧？",a="阿库麦尔是一头体型庞大的三头九头蛇，也是上古之神的仆从，从佐拉姆海岸受污染的水域中崛起。关于它残暴行径的传说，以及暮光之锤对它的黑暗崇拜，使它成为灰谷海岸最令人胆寒的邪恶存在之一。",al={"阿库麦尔为何令人畏惧","阿库麦尔的名声","阿库麦尔危险吗"}}},fp="7,276,27.329.0,34.215.1,16.160.0,24.136.0,45.156.0,33.164.0,22.124.0,53.241.0"}
P.entries["npc:alamar-grimm"] = {n="阿拉玛尔·格里姆",s="阿拉玛尔·格里姆是一位驻扎在寒脊山谷安威玛尔的侏儒术士训练师。因为诺莫瑞根的悲剧性沦陷而怀恨在心，他对外来者抱有不信任感，并将精力集中在教导年轻的术士如何驾驭黑暗技艺以及召唤他们的第一个恶魔爪牙上。",h="阿拉玛尔·格里姆是一位驻扎在寒脊山谷安威玛尔的侏儒术士训练师。因为诺莫瑞根的悲剧性沦陷而怀恨在心，他对外来者抱有不信任感，并将精力集中在教导年轻的术士如何驾驭黑暗技艺以及召唤他们的第一个恶魔爪牙上。",kw={"阿拉玛尔","安威玛尔","寒脊","诺莫瑞根","格里姆","小鬼","训练师","术士"},ang={["class:Warlock"]="对于在寒脊山谷开始冒险的侏儒术士来说，格里姆会提供你最早的法术，并让你证明自己的价值，以获得你的第一个小鬼爪牙。",["race:Gnome"]="格里姆体现了流亡者那种沉默的苦涩——当诺莫瑞根依然处于穴居人手中时，他们觉得自己被盟友抛弃了。"},sec={{t="苦涩的流亡者",b="当寒脊山谷的大多数侏儒将精力投入到恢复和修补工作时，阿拉玛尔·格里姆却对诺莫瑞根的陷落怀有深深的怨恨。他对普通的冒险者甚至铁炉堡的东道主矮人都持冷嘲热讽的态度，抱怨他们的盟友比起收复这座陷落的科技之城，更关心与人类的外交关系。他在安威玛尔开展工作，寻找那些明白“冷酷的力量也许才是他的人民真正所需”的志同道合者。"},{t="黑暗技艺大师",b="对于走上邪能魔法之路的年轻侏儒来说，格里姆是他们最初的引导者。当收到一份被污染的备忘录时，他会罕见地表现出热情的态度，并开始指导新兵学习基础法术。然而，在向新手传授奴役恶魔小鬼所需的危险知识之前，他会要求他们证明自己的魔法和体能耐力，派遣他们去取回当地霜鬃巨魔新手所携带的奇异羽毛护身符。"}},faq={{q="阿拉玛尔·格里姆是谁？",a="阿拉玛尔·格里姆是一位位于寒脊山谷安威玛尔内的侏儒术士训练师。他负责训练侏儒术士新手学习基础的邪能技能，并教导他们如何召唤第一只小鬼。",al={"阿拉玛尔·格里姆","阿拉玛尔是谁","安威玛尔侏儒术士训练师"}},{q="为什么阿拉玛尔·格里姆对矮人感到愤怒？",a="阿拉玛尔认为，尽管矮人为流离失所的侏儒提供了庇护，但铁炉堡的矮人们并没有真正把收复诺莫瑞根放在首位。他怨恨矮人的利益似乎更倾向于与人类的联盟，而不是解放他的人民的家园。",al={"为什么阿拉玛尔讨厌矮人","阿拉玛尔对矮人的看法","为何愤怒"}},{q="阿拉玛尔·格里姆让新晋术士去做什么？",a="为了证明他们拥有控制恶魔的耐力和魔法能力，格里姆指示术士新手去猎杀当地的霜鬃巨魔新手，并收集他们的羽毛护身符。收集完成后，他会用这些护身符测试新兵，然后再教导他们召唤小鬼的仪式。",al={"阿拉玛尔·格里姆小鬼任务","羽毛护身符任务","霜鬃护身符术士"}}},fp="12,196,14.402.0,23.366.0,20.142.0,41.228.0,46.194.0"}
P.entries["npc:alanndarian-nightsong"] = {n="奥兰达利亚·夜歌",s="奥兰达利亚·夜歌是一位居住在黑海岸奥伯丁的暗夜精灵，致力于照料该地区饱受困扰的动物。她与旅行者们共同努力，试图治愈折磨着当地野生动物的瘟疫，尤其是那些因为黑海岸水源受到污染而生病的鹿。",h="奥兰达利亚·夜歌是一位居住在黑海岸奥伯丁的暗夜精灵，致力于照料该地区饱受困扰的动物。她与旅行者们共同努力，试图治愈折磨着当地野生动物的瘟疫，尤其是那些因为黑海岸水源受到污染而生病的鹿。",kw={"奥兰达利亚","奥伯丁","治疗","黑海岸","卡多雷","夜歌","陆行鸟","野生动物"},ang={["class:Druid"]="德鲁伊会在奥兰达利亚的事业中找到知音，她致力于识别水体污染并从生理上治愈黑海岸各地中毒的生物。",["class:Hunter"]="熟悉野兽行为的猎人会与奥兰达利亚密切合作，利用他们的追踪技能定位野生陆行鸟和受困的猎物。",["faction:Alliance"]="奥兰达利亚是抵达奥伯丁的联盟旅行者的重要联络人，帮助新来者了解卡利姆多北部荒野脆弱的现状。",["race:NightElf"]="她对森林的敬畏以及致力于净化被腐蚀的野生动物的奉献精神，体现了卡多雷保护自然的核心理念。"},sec={{t="奥伯丁的照料者",b="奥兰达利亚·夜歌身处奥伯丁的海滨定居点，守护着黑海岸脆弱的生态平衡。随着神秘的污染渗入土地和水域，古老森林中的生物开始遭受疾病和反常攻击性的折磨。奥兰达利亚作为一名守护者和自然学家，寻找着实用的治疗方法来减轻它们的痛苦，并恢复它们的自然活力。"},{t="治愈受难与患病的生灵",b="奥兰达利亚的大部分精力都集中在查明在当地动物群中蔓延的病痛的根本原因。通过仔细收集植物试剂并研究该地区的主要水源，她制作出了药膏和治疗药剂。她招募流浪的冒险者将这些药物直接用于患病的森林生物，试图在这些腐蚀永久吞噬黑海岸的野生动物之前将其遏制住。"}},faq={{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位位于黑海岸港口城镇奥伯丁的暗夜精灵自然学家。她专注于照料受感染的当地野生动物，并寻找草药疗法来治疗困扰这片海岸的反常疾病。",al={"奥兰达利亚","奥兰达利亚·夜歌是谁","奥兰达利亚·夜歌背景故事"}},{q="在哪里可以找到奥兰达利亚·夜歌？",a="她以奥伯丁为家，这是黑海岸雾气缭绕的海岸线上主要的暗夜精灵据点。",al={"奥兰达利亚位置","奥兰达利亚在哪里","寻找奥兰达利亚·夜歌"}},{q="她请求冒险者执行什么任务？",a="奥兰达利亚请求冒险者追踪污染黑海岸生物的病源，从荒野中收集关键的治疗成分，并将药剂直接用于生病的动物，例如那些患病的鹿。",al={"奥兰达利亚任务","奥伯丁生病动物任务","奥兰达利亚想要什么"}},{q="她和其他夜歌族人有亲属关系吗？",a="其他暗夜精灵也拥有夜歌这个姓氏，但没有任何证据表明她与他们有任何亲属关系。她的日常重心依然是照管黑海岸的荒野。",al={"夜歌家族","与夜歌大师的关系","法拉拉·夜歌"}},{q="为什么黑海岸的生物会生病？",a="某种东西污染了峭壁之泉，这是黑海岸主要的饮用水源，被污染的水导致整个地区的鹿都生了病。奥兰达利亚怀疑背后还有更严重的污染在作祟。",al={"黑海岸动物为什么生病","黑海岸受腐蚀的陆行鸟","黑海岸瘟疫"}},{q="她能训练陆行鸟宠物吗？",a="尽管有传言称她对陆行鸟了如指掌，但她并不会为在野外冒险的猎人训练宠物，而是将重心保持在野生种群上。",al={"陆行鸟训练师","奥伯丁陆行鸟训练","训练我的陆行鸟"}}},fp="21,181,24.265.0,29.290.0,29.155.0,41.99.0,47.144.0,35.149.0,40.172.0,31.149.0"}
P.entries["npc:althea-ebonlocke"] = {n="Althea Ebonlocke",s="指挥官阿尔泰娅·埃伯洛克领导着夜色镇警卫队，这支身陷困境的城镇卫队在暮色森林中保卫着夜色镇，抵御着各种恐怖威胁。作为艾尔罗·埃伯洛克镇长的亲戚，她肩负着保护这个被暴风城正规军遗弃的孤立地区的重任。她组织巡逻，指派冒险者清除当地的恐怖生物，并协调城镇在持续不断的怪物威胁下生存下去。",h="指挥官阿尔泰娅·埃伯洛克领导着夜色镇警卫队，这支身陷困境的城镇卫队在暮色森林中保卫着夜色镇，抵御着各种恐怖威胁。作为艾尔罗·埃伯洛克镇长的亲戚，她肩负着保护这个被暴风城正规军遗弃的孤立地区的重任。她组织巡逻，指派冒险者清...",kw={"阿尔泰娅","指挥官","夜色镇","暮色森林","埃伯洛克","民兵","摩拉迪姆","夜色镇警卫队","缝合怪"},ang={["class:Paladin"]="行走在暮色森林阴暗道路上的圣骑士们可以协助阿尔泰娅安抚那些躁动的灵魂，减轻压在她民兵身上的精神重担。",["class:Warrior"]="战士们在阿尔泰娅身上找到了一位严厉、务实的指挥官，她尊重军事纪律，并重视那些愿意在压倒性劣势下坚守阵地的先锋战士。",["faction:Alliance"]="阿尔泰娅代表了联盟被遗忘的边境地区那冷酷的决心，在王国军队撤离的地方维系着这一地区。"},sec={{t="警卫队指挥官",b="当她的亲戚艾尔罗·埃伯洛克镇长在镇政厅负责民政管理时，指挥官阿尔泰娅负责指挥夜色镇薄弱的防御防线。当暴风城未能部署皇家军队来保护暮色森林免受潜伏的恐怖威胁时，市民们组建了夜色镇警卫队。在阿尔泰娅坚定而不可动摇的指挥下，这些志愿者在被迷雾笼罩的道路上巡逻，阻止骷髅亡灵、凶猛的狼群和蜘蛛越过城镇边界。"},{t="濒临危机的城镇",b="阿尔泰娅为人务实，了解她所率领的民兵的局限性。由于兵力不足且招募的新兵不断减员，她不遗余力地招募过往的雇佣兵和旅行者，以减少夜色镇门口的威胁。她指挥针对森林中宁静而悲伤的墓地里的食尸鬼和骷髅的战斗，同时对森林深处涌动的黑暗传闻保持警惕。"},{t="森林的悲剧",b="除了常见的森林害虫，阿尔泰娅还协调调查并摧毁暮色森林中最大的祸害。她协助揭开斯塔文·密斯特曼托的黑暗命运，并寻求解决“摩拉迪姆”——即堕落的骑士摩根·拉迪莫尔——不安游荡的方法。当亚伯克隆比释放出可怕的缝合怪在主路上游荡时，正是阿尔泰娅的夜色镇警卫队沿路集结，奋起抵抗。"}},faq={{q="阿尔泰娅·埃伯洛克是谁？",a="指挥官阿尔泰娅·埃伯洛克是夜色镇警卫队的领导者，这是暮色森林夜色镇的城镇民兵组织。她负责组织该地区的防御，抵御潜伏在阴影中的亡灵和野兽。",al={"阿尔泰娅是谁","指挥官埃伯洛克","谁是夜色镇警卫队指挥官"}},{q="什么是夜色镇警卫队？",a="夜色镇警卫队是由夜色镇市民组建的志愿者民兵组织。由于暴风城几乎没有为暮色森林提供任何军事支持，当地镇民在阿尔泰娅的领导下团结起来，巡逻道路并击退森林中的恐怖威胁。",al={"什么是夜色镇警卫队","谁是夜色镇警卫队","夜色镇民兵"}},{q="阿尔泰娅和艾尔罗·埃伯洛克镇长是什么关系？",a="阿尔泰娅是夜色镇镇长艾尔罗·埃伯洛克公爵的亲戚。当镇长在镇政厅管理城镇事务时，阿尔泰娅在战场上指挥民兵。",al={"埃伯洛克镇长的亲戚","阿尔泰娅是埃伯洛克的女儿吗","阿尔泰娅的家人"}},{q="为什么暴风城不帮助阿尔泰娅保卫夜色镇？",a="随着瓦里安·乌瑞恩国王的失踪以及暴风城资源的紧张，贵族议会很大程度上忽略了王国的外部领土。夜色镇几乎没有得到任何士兵或救援，迫使阿尔泰娅不得不依靠当地志愿者和自由冒险者。",al={"为什么没有暴风城的卫兵","暴风城对暮色森林的支持","士兵在哪里"}},{q="指挥官阿尔泰娅提供什么任务？",a="阿尔泰娅提供核心的夜色镇警卫队任务线，派遣冒险者在暮色森林中猎杀狼群、骷髅恶魔和食尸鬼。她还协助调查斯塔文的传说，并处理游荡的恐怖生物摩拉迪姆。",al={"阿尔泰娅的任务","夜色镇警卫队任务线"}},{q="当缝合怪袭击夜色镇时，阿尔泰娅会做什么？",a="当亚伯克隆比制造的缝合怪蹒跚着沿路走向夜色镇时，她的夜色镇警卫队小队会沿路集结起来进行抵抗，尽管如果没有冒险者的帮助，怪物可以直接冲破他们的防线。",al={"阿尔泰娅与缝合怪","谁在对抗缝合怪","夜色镇遭到袭击"}}},fx={["4a666294"]={q="指挥官阿尔泰娅·埃伯洛克站在哪一方？",a="指挥官阿尔泰娅坚定地支持夜色镇的居民和联盟。暴风城基本上已将暮色森林留给阴影摆布，但阿尔泰娅拒绝抛弃自己的家园。她领导着夜行者——一支走投无路的地方民兵，立誓抵挡那些威胁要将镇子从地图上抹去的野兽、躁动的亡灵与步步逼近的恐怖。",al={"阿尔泰娅·埃伯洛克的阵营","阿尔泰娅为谁而战","阿尔泰娅属于联盟吗"}},["37e849b9"]={q="指挥官阿尔泰娅·埃伯洛克想要什么？",a="她最重要的目标是让夜色镇存续下去。由于常规军队迟迟没有增援，阿尔泰娅不懈努力，阻止荒野不断逼近。她指挥夜行者对抗来袭的骷髅魔物、狂暴的狼和蜘蛛，并积极招募勇敢的冒险者，铲除潜伏在林中阴影里的致命威胁，以免它们屠戮饱受困扰的镇民。",al={"阿尔泰娅想要什么","阿尔泰娅·埃伯洛克的目标","阿尔泰娅在暮色森林的任务"}},["288c0322"]={q="指挥官阿尔泰娅·埃伯洛克为何在夜色镇？",a="暮色森林是她的家园，也是她的职责所在。她与镇长艾尔罗·埃伯洛克公爵有亲缘关系，驻守在镇中心广场，从聚落核心指挥夜行者。阿尔泰娅没有逃往安全的暴风城，而是留在前线协调巡逻，并召集任何有能力的旅人共同守卫边境。",al={"阿尔泰娅为何在夜色镇","指挥官阿尔泰娅为何在此","阿尔泰娅·埃伯洛克的位置"}}},fp="16,220,22.387.0,19.341.0,21.380.1,24.168.0,24.214.0,46.126.0,53.263.0,40.179.0,52.215.1"}
P.entries["npc:altsoba-ragetotem"] = {n="奥索巴·狂怒图腾",s="奥索巴·狂怒图腾是一位驻扎在费伍德森林血毒岗哨的牛头人武器商。在这座偏远的部落前哨站，他为过往的勇士提供可靠的钉锤、法杖和斧头，助他们对抗森林中被腐蚀的恐怖生物。",h="奥索巴·狂怒图腾是一位驻扎在费伍德森林血毒岗哨的牛头人武器商。在这座偏远的部落前哨站，他为过往的勇士提供可靠的钉锤、法杖和斧头，助他们对抗森林中被腐蚀的恐怖生物。",kw={"奥索巴","血毒岗哨","费伍德森林","狂怒图腾","牛头人","商人","武器商"},ang={["faction:Horde"]="奥索巴为在卡利姆多最受腐蚀地区之一坚守阵地的部落特工提供必要的武备物资。",["race:Tauren"]="作为狂怒图腾部族的一员，奥索巴为这片饱受恶魔腐化之苦的土地带来了牛头人传统的坚定信念。"},sec={{t="血毒岗哨的护甲商",b="血毒岗哨是一个位于费伍德森林中心地带的危险前哨站，周围充斥着恶魔的腐化和受污染的野生动物。在这里维持补给线是一项艰巨而必要的任务，奥索巴·狂怒图腾通过为部落侦察兵和旅行者装备物资来尽自己的一份力量。无论谁需要一把结实的新月斧还是一把沉重的战锤，奥索巴都能确保前往受腐蚀林地的勇士们不会赤手空拳地投入战斗。"}},faq={{q="奥索巴·狂怒图腾是谁？",a="奥索巴·狂怒图腾是一位驻扎在费伍德森林的部落营地——血毒岗哨的牛头人商人。他为勇敢面对这片荒芜山谷的旅行者和守卫提供基础的重型武器。",al={"奥索巴是谁","奥索巴·狂怒图腾","血毒岗哨的牛头人"}},{q="奥索巴出售什么？",a="他出售各种标准的近战武器，包括战斗法杖、晨星锤、战锤和斧头，为深入费伍德森林的冒险者提供可靠的钢制装备。",al={"奥索巴的商品","奥索巴出售的物品","奥索巴卖什么武器"}},{q="我在哪里可以找到奥索巴·狂怒图腾？",a="他可以在血毒岗哨内找到，该岗哨坐落在悬崖边，俯瞰着费伍德森林中污浊的水域和受腐蚀的林地。",al={"奥索巴的位置","奥索巴在哪里","血毒岗哨商人位置"}}},fp="17,229,26.419.0,25.188.0,23.177.0,35.131.0"}
P.entries["npc:alyissia"] = {n="奥莉希亚",s="奥莉希亚是一位卡多雷战士训练师，驻守在幽影谷奥达希尔的中空树枝内。她指导刚刚苏醒的暗夜精灵战士掌握武技的基础，帮助他们利用原始的力量和纪律来保卫他们新生的世界之树。",h="奥莉希亚是一位卡多雷战士训练师，驻守在幽影谷奥达希尔的中空树枝内。她指导刚刚苏醒的暗夜精灵战士掌握武技的基础，帮助他们利用原始的力量和纪律来保卫他们新生的世界之树。",kw={"奥达希尔","奥莉希亚","暗夜精灵","幽影谷","泰达希尔","战士训练师"},ang={["class:Warrior"]="对于年轻的暗夜精灵战士来说，奥莉希亚是最初的导师，在他们深入泰达希尔荒野之前，为他们提供早期的姿态训练和武技纪律。",["race:NightElf"]="奥莉希亚代表了卡多雷的前线武技纪律，时刻准备着训练保卫者，以守护奥达希尔的根系免受腐蚀。"},sec={{t="幽影谷的武技导师",b="奥莉希亚站在奥达希尔受庇护的圣所内，指导那些比起自然魔法或神职，更向往钢铁与盾牌之道的年轻暗夜精灵。虽然卡多雷军队传统上以哨兵和潜行弓箭手而闻名，但当今卡利姆多的危险局势需要坚定的前线战士。奥莉希亚教授基础技巧，确保新兵能够掌控战斗怒火、掌握战斗姿态，并抵御侵蚀幽影谷的凶猛野生动物和堕落格雷尔。"}},faq={{q="奥莉希亚是谁？",a="奥莉希亚是一位暗夜精灵战士训练师，位于幽影谷的核心圣所奥达希尔。她为刚在泰达希尔开启旅程的初出茅庐的战士提供初步指导、训练和简单的武技练习。",al={"奥莉希亚是谁","奥莉希亚npc","奥莉希亚有什么作用"}},{q="我在哪里可以找到奥莉希亚？",a="她驻守在奥达希尔巨大的中空树干内的底层，位于泰达希尔的幽影谷中心地带。",al={"奥莉希亚位置","奥莉希亚在哪里","寻找奥莉希亚"}},{q="奥莉希亚提供什么任务？",a="奥莉希亚会接收新晋暗夜精灵战士携带的简易符记。这会将他们引荐给她，作为他们在奥达希尔的战士训练师。",al={"奥莉希亚的任务","奥莉希亚提供的任务"}}},fp="8,143,28.455.0,16.179.0,26.112.0,32.127.0"}
P.entries["npc:amber-kearnen"] = {n="Amber Kearnen",s="Amber Kearnen 是驻扎在西部荒野深处的一名目光敏锐的军情七处特工。她从俯瞰平原的隐蔽监视点出发，代表马迪亚斯·肖尔大师监控迪菲亚潜行者的非法活动。",h="Amber Kearnen 是驻扎在西部荒野深处的一名目光敏锐的军情七处特工。她从俯瞰平原的隐蔽监视点出发，代表马迪亚斯·肖尔大师监控迪菲亚潜行者的非法活动。",kw={"amber","迪菲亚","吉尔妮","klaven mortwake","klaven's tower","mathias shaw","潜行者","军情七处","西部荒野"},ang={["class:Rogue"]="对于证明自己职业技能的联盟潜行者来说，密探吉尔妮是你在现场的主要联络人，协助协调针对 Klaven's Tower 的潜入行动。",["faction:Alliance"]="Kearnen 代表了暴风城积极主动的隐蔽侧翼，在西部荒野敌后开展工作，在不惊动民众的情况下瓦解迪菲亚潜行者。"},sec={{t="紧盯高塔",b="作为军情七处的一名特工，Amber Kearnen 是暴风城的现场侦察员之一。她没有在 Stormwind Keep 的大厅里行走，而是在西部荒野广阔的天空下开展行动，监视着一座被迪菲亚潜行者征用的废弃岗哨。在马迪亚斯·肖尔大师的直接领导下，Kearnen 为被派去消除迪菲亚威胁并搜集这片充满纷争的乡村地区情报的潜入特工们提供关键的监督和简报。"},{t="致命的任务",b="她的警惕重心集中在 Klaven Mortwake 身上，这名迪菲亚成员躲藏在哨兵岭东南方的岗哨中。在对该塔进行了数周的监视后，Kearnen 向潜入的潜行者通报了那些随暮色森林货船一同抵达的诡异非人守卫的情况，并派遣他们去窃取塔楼钥匙，潜入塔内，查明暮色森林宝箱中的内容，包括 Klaven 的日记。她的耐心和仔细的记录使她成为王室对抗迪菲亚的暗影行动中不可或缺的一员。"}},faq={{q="Amber Kearnen 是谁？",a="Amber Kearnen 是暴风城精英情报部门军情七处的一名特工。她担任现场特工和侦察员，目前负责追踪西部荒野的迪菲亚行动。",al={"amber kearnen","吉尔妮是谁","密探吉尔妮"}},{q="Amber Kearnen 在哪里？",a="她驻扎在西部荒野的荒野中，在被迪菲亚潜行者占据的废弃联盟岗哨附近进行监视。",al={"amber kearnen 位置","吉尔妮在哪里","amber kearnen 在哪里"}},{q="她与 Mathias Shaw 有什么联系？",a="她直接向军情七处首领马迪亚斯·肖尔大师汇报。肖尔会派遣其他特工到西部荒野找她，听取关于当地迪菲亚活动的简报。",al={"吉尔妮 mathias shaw","吉尔妮为谁工作"}},{q="她在 Klaven's Tower 中扮演什么角色？",a="Kearnen 监视着由 Klaven Mortwake 占据的岗哨。她负责指导由军情七处派遣的联盟潜行者，提供潜入塔内、绕过迪菲亚守卫并取回 Klaven 日记所需的战术监督。",al={"klaven's tower","amber kearnen klaven's tower","她在塔楼做什么"}}},fp="13,139,17.291.0,19.446.1,21.138.0,33.126.0,39.171.0,42.170.0"}
P.entries["npc:anastasia-hartwell"] = {n="安娜斯塔西娅·哈特威尔",s="安娜斯塔西娅·哈特威尔是一位著名的被遗忘者法师训练师，居住在幽暗城的Magic Quarter。她指导初学者和进阶施法者掌握奥术，并负责监督洛丹伦及其他地区的重要魔法研究和实地任务。",h="安娜斯塔西娅·哈特威尔是一位著名的被遗忘者法师训练师，居住在幽暗城的Magic Quarter。她指导初学者和进阶施法者掌握奥术，并负责监督洛丹伦及其他地区的重要魔法研究和实地任务。",kw={"安娜斯塔西娅","巴尼尔","迪诺","被遗忘者","哈特威尔","洛丹伦","法师","magic quarter","塔贝萨","训练师","幽暗城"},ang={["class:Mage"]="安娜斯塔西娅·哈特威尔是部落法师路过幽暗城时的重要导师，她负责训练更高等级的法术并委派重要的职业任务。",["faction:Horde"]="通过与奥格瑞玛的迪诺等训练师的合作，安娜斯塔西娅将洛丹伦的奥术传承与部落更广泛的魔法事业连接了起来。",["race:Undead"]="她代表了达拉然和洛丹伦尊贵的奥术传统在被遗忘者中的延续，即使经历了亡灵化的悲剧，这些传统依然被保存了下来。"},sec={{t="废墟中的奥术造诣",b="安娜斯塔西娅·哈特威尔站在幽暗城Magic Quarter阴暗而空旷的大厅里，指导着被遗忘者和部落法师如何引导奥术能量。虽然洛丹伦王国已沦为废墟，但像安娜斯塔西娅这样的前人类从业者在亡灵状态下仍保留了他们的学术传统。她坚持认为魔法需要严格的纪律，并告诫她遇到的每一位旅人：粗心的咒语会迅速吞噬未经训练的人。"},{t="实地研究与遗物",b="除了基础的法术指导，安娜斯塔西娅还引导有前途的学生进行重要的实地调查。她派遣法师前往提瑞斯法林地的巴尼尔农场采集金鱼草，以显示瘟疫蔓延的程度；并前往Apothecarium阿尔格农的炼金商店，捕捉一场奇怪骚动背后的纯粹魔法生物。通过她的任务，从业者们了解到掌握魔法意味着直面其危险，即使是在他们自己的城市内也是如此。"},{t="技艺的盟友",b="安娜斯塔西娅的人脉远不止提瑞斯法边界。随着部落施法者精通程度的提高，她与远方的训练师（如奥格瑞玛的迪诺）协调，并引导高级学生前往尘泥沼泽等地的隐居大师（如塔贝萨）处学习。她的指导确保了被遗忘者法师始终融入部落宏大的魔法追求之中。"}},faq={{q="谁是安娜斯塔西娅·哈特威尔？",a="安娜斯塔西娅·哈特威尔是一位位于幽暗城Magic Quarter的被遗忘者法师训练师。她教授进阶法师法术，并提供专门的任务来寻回洛丹伦各地的奥术神器和试剂。",al={"安娜斯塔西娅·哈特威尔","谁是安娜斯塔西娅","哈特威尔 幽暗城"}},{q="我在哪里可以找到安娜斯塔西娅·哈特威尔？",a="她位于幽暗城的Magic Quarter，在城市拱形的地下天花板下，与其他奥术从业者和训练师聚集在一起。",al={"安娜斯塔西娅·哈特威尔位置","安娜斯塔西娅·哈特威尔在哪里","幽暗城法师训练师位置"}},{q="安娜斯塔西娅对非施法者说什么？",a="她为非施法者的访客提供谨慎的建议，提醒他们在世界各地旅行时要警惕魔法，并指出未经训练的人很容易被魔法灼伤。",al={"安娜斯塔西娅闲谈","安娜斯塔西娅对话","哈特威尔建议"}},{q="安娜斯塔西娅·哈特威尔提供什么任务？",a="安娜斯塔西娅为法师提供各种训练任务，包括在巴尼尔农场收集金鱼草，调查Apothecarium一家炼金商店中的魔法骚动，以及联络远方的导师，如奥格瑞玛的迪诺和尘泥沼泽的塔贝萨。",al={"安娜斯塔西娅任务","哈特威尔任务","幽暗城法师任务"}},{q="安娜斯塔西娅·哈特威尔和提瑞斯法的其他哈特威尔家族成员有关系吗？",a="她与安德鲁·哈特威尔和杰弗里·哈特威尔拥有相同的姓氏，但他们的家庭关系尚未得到证实。",al={"哈特威尔家族","安德鲁·哈特威尔","杰弗里·哈特威尔"}},{q="为什么安娜斯塔西娅派遣法师前往巴尼尔农场？",a="她要求法师收集巴尼尔金鱼草，以便她可以测量提瑞斯法林地瘟疫的蔓延程度，并将这些花朵送往药剂师手中。",al={"巴尼尔农场任务","为什么要去巴尼尔农场","哈特威尔 巴尼尔"}}},fx={["686de903"]={q="安娜斯塔西娅·哈特威尔站在哪一方？",a="安娜斯塔西娅·哈特威尔坚定地支持被遗忘者和部落。她驻扎在幽暗城深处的Magic Quarter，为希尔瓦娜斯·风行者女士培养新崛起的法师，让他们掌握奥术之力，守卫这个新生的王国。",al={"安娜斯塔西娅·哈特威尔的阵营","安娜斯塔西娅·哈特威尔效忠于谁","安娜斯塔西娅·哈特威尔的忠诚对象"}},bc0bb7e5={q="安娜斯塔西娅·哈特威尔为何在这里？",a="她住在幽暗城的Magic Quarter，训练有志成为施法者的被遗忘者和部落成员研习奥术。她指导初出茅庐的施法者，警告新手魔法的危险，同时派遣有能力的法师执行洛丹伦及更远地区的重要任务。",al={"安娜斯塔西娅·哈特威尔为何在幽暗城","安娜斯塔西娅·哈特威尔在这里做什么","安娜斯塔西娅·哈特威尔的职责"}},["18e123e6"]={q="安娜斯塔西娅·哈特威尔想要什么？",a="她致力于确保奥术施法者纪律严明、能力出众且行事谨慎，并经常提醒外来者，未经训练便驾驭狂暴的力量只会引火烧身。她通过严苛的任务和魔法调查，努力增强被遗忘者的奥术力量。",al={"安娜斯塔西娅·哈特威尔的目标","安娜斯塔西娅·哈特威尔的动机是什么"}}},fp="18,218,27.341.0,25.418.0,19.358.0,26.169.0,36.155.0,37.102.0,42.291.0,61.116.0,54.141.0"}
P.entries["npc:andron-gant"] = {n="安德隆·甘特",s="安德隆·甘特是一位深居简出、常常醉酒的被遗忘者，居住在幽暗城Apothecarium阴暗的深处，偶尔会为当地学者处理一些研究委托和遗物回收工作。",h="安德隆·甘特是一位深居简出、常常醉酒的被遗忘者，居住在幽暗城Apothecarium阴暗的深处，偶尔会为当地学者处理一些研究委托和遗物回收工作。",kw={"安德隆·甘特","apothecarium","astor hadren","死亡猎手","jediga","玛科里石板","瓦里玛萨斯"},ang={["class:Rogue"]="在死亡猎手中晋升的被遗忘者潜行者们终会明白，幽暗城内部的大厅需要和其边境一样保持警惕。",["race:Undead"]="甘特是Apothecarium里常见的身影，一个很少离开城市的醉酒被遗忘者，为城里的法师充当杂务掮客。"},sec={{t="醉醺醺的隐士",b="安德隆·甘特蜷缩在Apothecarium有害的烟雾中，很少离开幽暗城那坚固的石墙之外。在旁观者看来，他不过是个醉酒的学者，偶尔会雇佣冒险者信使，为当地法师从遥远的海岸取回玛科里石板之类的晦涩遗物。"},{t="被死亡猎手揭穿",b="甘特的背叛行径没能逃过幽暗城情报网的注意。当辛迪加派遣一名名为Astor Hadren的信使来收集一本包含泄密数据的账本时，死亡猎手中的有志之士拦截了这名信使。一名特工伪装成Hadren，成功骗过了烂醉如泥的甘特，在不引起怀疑的情况下拿走了那本罪证账本，并将其交给了瓦里玛萨斯，作为甘特背叛被遗忘者的确凿证据。"}},faq={{q="我在哪里可以找到安德隆·甘特？",a="安德隆·甘特位于幽暗城内，在Apothecarium区域的下层徘徊。",al={"安德隆·甘特位置","安德隆·甘特在哪里","甘特幽暗城位置"}},{q="为什么安德隆·甘特对艾萨拉的石板感兴趣？",a="甘特充当幽暗城某些法师的中间人，负责向拾荒者和Jediga这样的联系人支付报酬，以从艾萨拉的废墟中找回古代遗物。",al={"安德隆·甘特艾萨拉","玛科里石板安德隆·甘特","为什么甘特想要石板"}},{q="为什么死亡猎手要调查安德隆·甘特？",a="死亡猎手正在调查他与外部联系人的交易，并试图搜集有关他研究委托的情报。",al={"甘特调查","安德隆·甘特联系人","安德隆·甘特为谁工作"}},{q="谁负责指导对安德隆·甘特的调查？",a="死亡猎手代表瓦里玛萨斯调查甘特，旨在搜集有关他联系人和研究的情报。",al={"谁在调查安德隆·甘特","死亡猎手安德隆·甘特","瓦里玛萨斯安德隆·甘特"}}},fp="11,185,18.293.0,29.427.1,29.96.0,49.151.0,49.121.1,47.119.1"}
P.entries["npc:anduin-wrynn"] = {n="安度因·乌瑞恩国王",s="安度因·乌瑞恩国王年仅十岁，在父亲瓦里安·乌瑞恩国王失踪期间继位统治暴风城。由于他年纪尚幼，王国的实际管理权掌握在伯瓦尔·弗塔根公爵和皇家法院手中。",h="安度因·乌瑞恩国王年仅十岁，在父亲瓦里安·乌瑞恩国王失踪期间继位统治暴风城。由于他年纪尚幼，王国的实际管理权掌握在伯瓦尔·弗塔根公爵和皇家法院手中。",kw={"安度因","伯瓦尔","少年国王","普瑞斯托","王子","暴风城","王座大厅","乌瑞恩"},ang={["faction:Alliance"]="对于联盟的公民和士兵来说，安度因国王是王国坚韧不屈的纯洁象征，尽管许多人担心他的年幼会让王座面临宫廷暗流涌动的威胁。",["race:Human"]="对于暴风城的人民来说，这位少年国王代表了乌瑞恩王朝的延续，并代替他失踪的父亲瓦里安行使职责。"},sec={{t="王座上的男孩",b="安度因王子出生于第二次战争后的和平时期，他的名字是为了纪念他的祖父莱恩国王以及传奇骑士安度因·洛萨爵士。在前往塞拉摩参加外交峰会的途中，他的父亲神秘失踪，为了维持王国的稳定，这个孩子被仓促加冕。尽管这位十岁的君主有着超越年龄的智慧与同情心，但他对国家事务几乎没有实际的决定权，王国的统治权被分摊在伯瓦尔·弗塔根公爵和皇家议员女伯爵卡特拉娜·普瑞斯托的手中。"},{t="宫廷里的棋子",b="在Stormwind Keep那镀金的城墙内，年幼的安度因被日益紧张的政治局势所包围。虽然伯瓦尔公爵管理着军事防御并努力维护王国的完整，但女贵族卡特拉娜·普瑞斯托却不断在宫廷里散布流言，并暗中阻挠对人类外围定居点的兵力部署。安度因感受到了宫廷内不稳定的气氛，并深切地思念着他的父亲，但目前他仍只是一个被阴谋家和警惕的守护者所包围的傀儡君主。"}},faq={{q="为什么一个孩子在统治暴风城？",a="瓦里安·乌瑞恩国王在乘船前往塞拉摩参加外交峰会的途中神秘失踪。为了避免继承危机并维持整个王国的秩序，十岁的安度因王子被正式加冕为国王，而伯瓦尔·弗塔根公爵被任命为摄政王，代行统治之责。",al={"为什么安度因是国王","瓦里安在哪里","谁是小孩国王"}},{q="现在究竟是谁在管理王国？",a="伯瓦尔·弗塔根公爵担任暴风城的摄政王，指挥着王国的军队，并在安度因成年之前掌握着最终的行政权力。然而，女贵族卡特拉娜·普瑞斯托作为高级顾问，对皇家法院和贵族议会施加了重大的影响。",al={"谁统治暴风城","谁在负责","暴风城摄政王"}},{q="安度因的名字是为了纪念谁？",a="他的名字是为了纪念暴风城历史上的两位英雄：他的祖父，已故的莱恩·乌瑞恩国王，以及艾泽拉斯之狮安度因·洛萨爵士，他曾率领联盟度过了第一次和第二次战争。",al={"安度因名字由来","安度因纪念对象","为什么叫安度因"}},{q="安度因在城里的什么位置？",a="安度因国王就在Stormwind Keep的王座大厅里，坐在皇家宝座上，伯瓦尔·弗塔根公爵和卡特拉娜·普瑞斯托女伯爵紧随其后。",al={"安度因在哪里","安度因位置","安度因·乌瑞恩位置"}}},fp="12,261,19.571.0,19.525.0,32.303.1,40.300.0,26.196.0,36.160.0"}
P.entries["npc:apothecary-helbrim"] = {n="药剂师赫布瑞姆",s="药剂师赫布瑞姆是皇家药剂师协会派驻在尘土飞扬的十字路口中心地带的一名特使。他被派遣到遥远的卡利姆多搜集不常见的试剂，并代表被遗忘者研究贫瘠之地的本土植物群和奇特的生态系统。",h="药剂师赫布瑞姆是皇家药剂师协会派驻在尘土飞扬的十字路口中心地带的一名特使。他被派遣到遥远的卡利姆多搜集不常见的试剂，并代表被遗忘者研究贫瘠之地的本土植物群和奇特的生态系统。",kw={"药剂师","贫瘠之地","十字路口","菌类孢子","赫布瑞姆","皇家药剂师协会","扎玛"},ang={["faction:Horde"]="尽管与兽人卫兵和牛头人旅行者驻扎在一起，但赫布瑞姆对收集孢子和毒素的执着使他的盟友们也感到有些不安。",["race:Undead"]="赫布瑞姆代表了你们的族人在西部对部落所做的实际贡献，将卡利姆多崎岖的荒野变成了协会持续研究的原材料。"},sec={{t="尘土中的药剂师",b="虽然皇家药剂师协会的大部分成员都留在幽暗城潮湿的地底深处，但赫布瑞姆却在十字路口那烈日灼人和赤土干燥的环境中工作。他跨越了无尽之海来到卡利姆多，任务简单却至关重要：识别并从贫瘠之地提取有用的植物、真菌和自然样本。为此，他依靠过往的冒险者来收集样本（例如当地的菌类孢子），并与他在雷霆崖的同事扎玛药剂师直接对接。他的存在提醒着旅客，希尔瓦娜斯的炼金术士的影响力早已延伸到了洛丹伦那片满目疮痍的土地之外。"}},faq={{q="药剂师赫布瑞姆是谁？",a="赫布瑞姆是一名被遗忘者炼金术士，也是皇家药剂师协会的特工。他驻扎在十字路口，负责收集和分析在贫瘠之地发现的独特自然试剂。",al={"赫布瑞姆是谁","赫布瑞姆背景故事","十字路口药剂师"}},{q="为什么被遗忘者的药剂师会驻扎在贫瘠之地？",a="皇家药剂师协会一直在寻求新的化合物、毒素和试剂来支持他们的炼金研究。赫布瑞姆被派往卡利姆多中部研究当地的样本，例如在稀树草原上萌发的那些奇特菌类孢子，这些东西在饱受瘟疫蹂躏的洛丹伦土地上是没有对应物的。",al={"为什么他在十字路口","赫布瑞姆在这里做什么","为什么被遗忘者在贫瘠之地"}},{q="他用玩家带给他的菌类孢子做什么？",a="赫布瑞姆会对这些孢子进行分析，以确定其毒性、药用价值和生化特性。他经常会将这些样本打包，并指派信使将其送到雷霆崖的扎玛药剂师那里进行进一步的炼金实验。",al={"赫布瑞姆的菌类孢子","孢子有什么用","菌类孢子任务"}},{q="赫布瑞姆与谁共事？",a="赫布瑞姆听命于驻扎在幽暗城的皇家药剂师协会。在卡利姆多，他直接与雷霆崖预见之池的扎玛药剂师合作，偶尔也会通过棘齿城的码头管理员迪兹威格这样的地精中间人处理事务。",al={"赫布瑞姆的盟友","赫布瑞姆听命于谁"}}},fp="18,158,22.484.0,26.170.0,54.236.0,57.196.0,27.248.0"}
P.entries["npc:apothecary-johaan"] = {n="药剂师乔汉",s="药剂师乔汉是一位驻扎在布瑞尔的皇家药剂师学会的炼金术师兼研究员。受其组织和Sylvanas Windrunner女士的委托，他正在对当地的动植物进行致命实验，以研制被遗忘者的The New Plague。",h="药剂师乔汉是一位驻扎在布瑞尔的皇家药剂师学会的炼金术师兼研究员。受其组织和Sylvanas Windrunner女士的委托，他正在对当地的动植物进行致命实验，以研制被遗忘者的The New Plague。",kw={"药剂师","布瑞尔","乔汉","瘟疫","皇家药剂师学会","银松森林","提瑞斯法"},ang={["faction:Horde"]="虽然兽人和牛头人可能会对炼金枯萎病感到排斥，但乔汉制造的致命混合物服务于部落在东部王国的据点的战略安全。",["race:Undead"]="乔汉的研究是被遗忘者事业的核心，旨在开发铲除天灾军团和生者威胁，开辟永久家园所需的武器。"},sec={{t="学会的仆从",b="药剂师乔汉在提瑞斯法林地的被遗忘者定居点布瑞尔公开工作，代表了新成立的皇家药剂师学会的科学抱负。像洛丹伦各地的同事一样，乔汉在直接命令下开展工作，制造能够确保被遗忘者在面对生者和天灾军团时拥有脆弱未来的生物和炼金武器。"},{t="酿造The New Plague",b="乔汉负责协调学会所称的“The New Plague”的早期实地试验。他利用从提瑞斯法受腐蚀的野生动物和农业枯萎病中采集的原材料——例如黑暗犬的血液、鱼人鳞片、蜘蛛毒液和偷来的农场南瓜——测试毒素混合物，并在将结果发送到南方的银松森林之前，对活体目标进行药效评估。"}},faq={{q="药剂师乔汉是谁？",a="药剂师乔汉是一位驻扎在布瑞尔的炼金研究员。他隶属于皇家药剂师学会，并指挥年轻的被遗忘者勇士们在提瑞斯法林地各地收集邪恶的试剂。",al={"药剂师乔汉","药剂师乔汉是谁","乔汉 布瑞尔"}},{q="我在哪里可以找到药剂师乔汉？",a="他就站在提瑞斯法林地幽暗城北部的布瑞尔镇外，靠近绞刑架和炼金设备的地方。",al={"乔汉位置","乔汉在哪里","寻找乔汉"}},{q="乔汉在研究什么？",a="乔汉正在配制和提炼The New Plague的早期菌株，测试来自提瑞斯法受枯萎病影响的田野和野兽的生物制剂及毒液提取物。",al={"乔汉的实验","乔汉做什么","乔汉 瘟疫"}},{q="他如何处理瘟疫样本？",a="一旦试剂混合完成并评估了其致命性，乔汉就会将样本打包，并派遣信使将其送到驻扎在银松森林的盟军药剂师手中。",al={"运往银松森林","瘟疫样本去哪儿了"}},{q="乔汉属于哪个组织？",a="他是皇家药剂师学会的活跃成员，该炼金公会服务于幽暗城的Sylvanas Windrunner女士和被遗忘者。",al={"乔汉所属阵营","乔汉为谁工作"}},{q="他为什么对当地的农场感兴趣？",a="像索利丹农场和附近的南瓜田这类人类农场种植的南瓜，为他的实验性毒素提供了原始试剂。",al={"苦难之地的乔汉","为什么让我去农场"}}},fp="17,188,24.322.0,22.341.1,25.163.0,35.153.0,26.146.0,40.134.0,40.140.0,40.141.0"}
P.entries["npc:apothecary-renferrel"] = {n="药剂师伦弗利尔",s="药剂师伦弗利尔是皇家药剂师学会的一位杰出成员，驻扎在银松森林的瑟伯切尔。他负责推进被遗忘者的炼金术研究，并协调对该地区受腐蚀的野生生物和天灾军团威胁的广泛实地调查。穿行于银松森林的旅者经常协助他收集不稳定的试剂，并调查危险的天灾军团残党。",h="药剂师伦弗利尔是皇家药剂师学会的一位杰出成员，驻扎在银松森林的瑟伯切尔。他负责推进被遗忘者的炼金术研究，并协调对该地区受腐蚀的野生生物和天灾军团威胁的广泛实地调查。穿行于银松森林的旅者经常协助他收集不稳定的试剂，并调查危...",kw={"药剂师","死亡配方","伦弗利尔","腐皮","皇家药剂师学会","瑟伯切尔","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="虽然兽人和牛头人可能会对他的生物实验的残酷本质感到退缩，但伦弗利尔针对天灾军团的情报收集有助于保护部落领土免受北方的入侵。",["race:Undead"]="伦弗利尔代表了被遗忘者务实且冷酷的生存心态，他将洛丹伦的本土动植物武器化，为获得自由的亡灵建立一个安全的未来。"},sec={{t="瑟伯切尔的炼金术师",b="伦弗利尔以瑟伯切尔为基地开展工作，是皇家药剂师学会在银松森林的主要实地研究员之一。虽然幽暗城拥有该学会宏伟的实验室和高层领导，但伦弗利尔处理的是获取当地生物样本、提炼强效药剂以及分析洛丹伦西部边境严峻生态环境等实际的泥泞工作。"},{t="调查腐皮豺狼人与天灾军团",b="伦弗利尔将大部分精力投入到盘踞在这一地区的腐皮豺狼人和游荡的亡灵身上。通过血液和组织样本，他试图了解瘟疫挥之不去的影响，以及束缚当地怪物的通灵力量。他的调查使他与图勒·鸦爪——一位在芬里斯岛遗迹附近活动的强大的天灾军团死灵法师——直接对立。"}},faq={{q="药剂师伦弗利尔是谁？",a="药剂师伦弗利尔是皇家药剂师学会的一名炼金术师，驻扎在被遗忘者位于银松森林的主要据点瑟伯切尔。他研究当地的野兽、瘟疫变种以及敌对势力，以调制药剂并为女王Sylvanas Windrunner巩固该地区的局势。",al={"伦弗利尔","伦弗利尔是谁","药剂师伦弗利尔背景故事"}},{q="伦弗利尔在银松森林研究什么？",a="他专注于开发新型瘟疫和毒药混合物，统称为“死亡配方”。他委托冒险者收集灰熊心脏、腐皮豺狼人脓液以及其他生物成分，以测试和提炼致命的药剂。",al={"伦弗利尔的研究","伦弗利尔的实验","死亡配方"}},{q="他与腐皮豺狼人有什么关联？",a="伦弗利尔研究腐皮豺狼人受腐蚀的脓液。他的初步测试检测到了术士和通灵魔法，因此他将样本送往幽暗城的比索·埃斯沙德处进行进一步研究。",al={"腐皮豺狼人的脓液","腐皮豺狼人的起源","银松森林的豺狼人"}},{q="为什么伦弗利尔要针对图勒·鸦爪？",a="伦弗利尔调查了腐皮豺狼人背后的魔法，并寻求比索·埃斯沙德的帮助以查明其来源。调查将目标指向了芬里斯岛上的威胁。",al={"图勒·鸦爪任务","图勒·鸦爪是谁","芬里斯城堡的死灵法师"}},{q="在银松森林之后，伦弗利尔会把冒险者派往何处？",a="一旦他的初步研究和当地的威胁得到解决，伦弗利尔会将经验丰富的旅行者派往东南方的希尔斯布莱德丘陵，将瑟伯切尔的前线工作与被遗忘者在洛丹伦更广泛的行动联系起来。",al={"瑟伯切尔之后","希尔斯布莱德运送","前往希尔斯布莱德"}},{q="什么是皇家药剂师学会？",a="皇家药剂师学会是被遗忘者的科学与炼金分支，由Sylvanas Windrunner女士创立。其总部位于幽暗城，研究人员不知疲倦地致力于开发新型毒药、抵抗自然腐朽，并制造出能够根除天灾军团的瘟疫。",al={"皇家药剂师学会","被遗忘者药剂师"}}},fp="20,229,25.349.0,34.323.1,28.250.0,43.241.0,46.189.0,42.177.1,55.228.0,37.264.0"}
P.entries["npc:apothecary-zinge"] = {n="药剂师金格",s="药剂师金格是皇家药剂师学会的一名炼金术士和研究员，驻扎在洛丹伦废墟下方的Apothecarium中。她效忠于被遗忘者，负责调查生物样本并协调整个部落领地的研究物资运输。",h="药剂师金格是皇家药剂师学会的一名炼金术士和研究员，驻扎在洛丹伦废墟下方的Apothecarium中。她效忠于被遗忘者，负责调查生物样本并协调整个部落领地的研究物资运输。",kw={"apothecarium","药剂师金格","十字路口","赫布瑞姆","皇家药剂师学会","样本","幽暗城","金格"},ang={["faction:Horde"]="她的研究依赖于畅通的补给线和值得信赖的信使穿梭于卡利姆多与东部王国之间的海洋，以维持部落前线的物资供应。",["race:Undead"]="对于被遗忘者来说，像金格这样的研究人员代表了科学自主的先锋，他们不懈地研制解决方案，以确保他们种族的生存与霸权。"},sec={{t="效忠学会",b="药剂师金格在幽暗城Apothecarium阴暗的区域深处进行实验。和大药剂师法拉尼尔麾下的其他同僚一样，她致力于寻找能够推进被遗忘者目标的化学和生物化合物。她的研究常常需要与远在提瑞斯法林地边界之外的实地研究员和侦察兵取得联系，甚至包括与卡利姆多的偏远前哨站进行交流。"},{t="跨大陆实验",b="为了提炼她的配方并发现新的试剂，金格依赖信使和冒险者将测试材料跨海运送。她与驻扎在贫瘠之地十字路口的药剂师赫布瑞姆等同僚保持定期联络，将银松森林的狼心样本寄送给他，以便他研究洛丹伦毒素对卡利姆多野兽的影响。"}},faq={{q="在哪里可以找到药剂师金格？",a="药剂师金格位于Apothecarium内，这是位于幽暗城东南层的炼金区域。",al={"金格位置","药剂师金格在哪里","药剂师金格地点"}},{q="她属于哪个组织？",a="她是皇家药剂师学会的一员，该组织是被遗忘者炼金术士的团体，致力于为希尔瓦娜斯·风行者效力，研制新的药剂、瘟疫和解毒剂。",al={"金格阵营","金格为谁工作"}},{q="她为什么需要来自贫瘠之地的样本？",a="样本是反向运输的。金格派遣冒险者将最初在银松森林采集的狼心样本带给她在十字路口的同事药剂师赫布瑞姆，他正在研究洛丹伦的毒素如何影响卡利姆多的野兽。",al={"为什么需要贫瘠之地样本","赫布瑞姆样本","金格贫瘠之地运送"}}},fp="16,157,25.315.0,29.296.0,36.109.0,37.177.0,43.203.0"}
P.entries["npc:aramis-hammerhand"] = {n="Aramis Hammerhand",s="Aramis Hammerhand是一位亡灵圣战战士，驻扎在丧钟镇那座饱受亵渎的教堂里。作为一名被遗忘者圣骑士训练师，他指导那些试图重拾与圣光纽带的复生亡灵。在亡灵状态下走上这条道路需要极大的纪律，因为引导这种光辉能量会给他们腐朽的躯体带来剧痛。",h="Aramis...",kw={"aramis","教堂","丧钟镇","被遗忘者","hammerhand","圣光","圣骑士","提瑞斯法","训练师"},ang={["class:Paladin"]="对于被遗忘者圣骑士来说，Aramis是他们遇到的第一位导师，指导他们度过在亡灵躯壳中驾驭圣光所需的痛苦和精神纪律。",["race:Undead"]="Aramis证明了复活成为亡灵并不意味着要放弃洛丹伦引以为傲的圣战传统，即使这伴随着巨大的个人痛苦。"},sec={{t="丧钟镇的明灯",b="站在丧钟镇教堂阴沉的墙壁内，Aramis Hammerhand代表了最近苏醒的被遗忘者中的一个异数。在生前，许多洛丹伦的公民响应了白银之手的召唤，却在天灾军团横扫北方时丧生。Aramis在陷落中幸存下来，却被复活成了亡灵，但他选择不放弃前世的武艺和精神教义。现在，他为其他拒绝放弃信仰的人提供指导。"},{t="圣光的苦痛",b="对于亡灵生物来说，引导圣光是对意志力的终极考验。这种力量会灼烧坏死的血肉，并唤醒早已死亡的神经，带来极度的痛苦。Aramis教导他的学员，坚守这种信仰需要忍受不断的折磨。通过像“艰难的道路”和“重拾圣光”这样的任务，他要求年轻的圣骑士去面对驾驭一种本质上与他们现有本性相抵触的力量所带来的肉体和精神代价。"}},faq={{q="Aramis Hammerhand是谁？",a="Aramis Hammerhand是一位位于提瑞斯法林地丧钟镇教堂内的被遗忘者圣骑士训练师。他协助那些希望追求圣战之路的复生亡灵。",al={"aramis背景故事","hammerhand是谁","丧钟镇圣骑士训练师"}},{q="被遗忘者真的可以使用圣光吗？",a="是的，通过纯粹的意志力和信念，被遗忘者可以呼唤圣光。然而，这样做会引起巨大的肉体痛苦，因为这种光辉能量在治愈或增强他们的同时，也会灼烧和侵蚀他们腐烂的血肉。",al={"亡灵可以是圣骑士吗","亡灵如何使用圣光","被遗忘者圣光"}},{q="我在哪里可以找到Aramis Hammerhand？",a="他就站在丧钟镇的教堂里，那是被遗忘者在提瑞斯法林地的初始定居点。",al={"aramis在哪里","hammerhand位置","丧钟镇圣骑士训练师"}},{q="Aramis Hammerhand提供什么任务？",a="Aramis为新复生的圣骑士提供几个职业任务，包括“艰难的道路”、“重拾圣光”、“黑暗中的微光”、“达成共识”和“继续你的训练”。",al={"aramis任务","丧钟镇圣骑士任务"}},{q="为什么会有圣骑士训练师为被遗忘者工作？",a="在瘟疫发生之前，洛丹伦是白银之手骑士团的摇篮。许多新解放的被遗忘者铭记着他们的誓言，拒绝放弃他们神圣的使命，无论他们现在处于什么样的亡灵状态。",al={"为什么会有被遗忘者圣骑士","被遗忘者白银之手"}},{q="使用圣光能像往常一样治疗亡灵吗？",a="虽然圣光可以修复他们的身体并赋予他们战斗力量，但这个过程极为痛苦。它重新点燃了他们的感觉神经系统，强迫他们感受到自己身体的腐烂。",al={"圣光会伤害亡灵吗","圣光治疗亡灵背景"}}},fp="17,200,22.384.0,27.320.0,25.133.0,47.173.0,35.112.0,41.185.0,50.190.0,55.165.0"}
P.entries["npc:arcanist-doan"] = {n="奥法师杜安",s="奥法师杜安是一位人类法师大师，居住在血色修道院的图书馆区域。他效力于血色十字军，是其最致命的奥术专家之一，也是十字军关键档案的守护者。",h="奥法师杜安是一位人类法师大师，居住在血色修道院的图书馆区域。他效力于血色十字军，是其最致命的奥术专家之一，也是十字军关键档案的守护者。",kw={"奥法师","知识殿堂","引爆","杜安","图书馆","血色十字军钥匙","血色修道院"},ang={["class:Mage"]="杜安对奥术防御的精通，使其防护气泡成为了魔法结界的生动典范。",["class:Paladin"]="对于圣骑士来说，杜安是一位罕见的、受到血色十字军信任的奥法师，而这个组织通常将圣光置于所有其他力量之上。",["faction:Alliance"]="对于联盟军队来说，杜安展现了血色十字军的狂热达到了何种地步，即便是奥术大师也受制于其暴力的偏执。",["faction:Horde"]="被遗忘者及其部落盟友视杜安为一名危险的血色指挥官，他的图书馆里藏着突破十字军内部圣所所需的关键情报和钥匙。"},sec={{t="图书馆看守者",b="尽管血色十字军的狂热成员们主要依赖武力和圣光的狂热，但杜安始终确信，纯粹的奥术力量对于从洛丹伦肃清天灾军团至关重要。他驻守在修道院图书馆深处的知识殿堂，被委以重任，既是学识的守护者，也是行动的把关人，保护着开启北部王国各地十字军圣地的血色十字军钥匙。"}},faq={{q="为什么血色十字军里会有法师？",a="虽然十字军中充斥着狂热的圣骑士和牧师，但杜安坚信，精湛的奥术魔法是肃清洛丹伦天灾军团不可或缺的武器。",al={"为什么杜安是法师","十字军法师","杜安魔法"}},{q="奥法师杜安与灰烬使者有什么联系吗？",a="目前没有已知的联系。杜安的身份是血色修道院图书馆的看守者和血色十字军钥匙的守护者，并非灰烬使者故事的一部分。",al={"杜安与灰烬使者","杜安制造了灰烬使者吗","灰烬使者水晶"}},{q="杜安在图书馆里守护着什么？",a="杜安负责看守修道院在知识殿堂内的书籍和历史记录。在他身后放着一个锁箱，里面装着血色十字军钥匙，这把钥匙至关重要，可以打开通往修道院军械库和大教堂区域的锁闭大门。",al={"杜安掉落什么","血色十字军钥匙","为什么要杀杜安"}},{q="杜安在战斗中使用什么魔法？",a="杜安以施放奥术气泡而闻名，这能让他不仅在引导大规模、席卷整个房间的引爆法术时处于无敌状态，还能通过区域沉默来干扰施法者，并将威胁变羊。",al={"杜安法术","杜安技能","奥法师杜安气泡"}},{q="杜安在第三次战争期间在哪里战斗过？",a="他在第三次战争中的事迹并无记载。如今，人们只知道他是血色修道院图书馆的看守者，守护着知识殿堂和血色十字军钥匙。",al={"杜安战争历史","杜安在哪里"}},{q="杜安有什么个人秘密吗？",a="杜安担任血色十字军的奥法师。他在经典旧世版本中没有关于其个人情感关系的记载。",al={"杜安背景故事"}}},fx={["979d2c44"]={q="奥法师杜安是谁？",a="奥法师杜安是一名人类法师，也是效力于血色十字军的最强大奥术施法者之一。他住在血色修道院图书馆深处的雅典娜神殿，负责保管组织的档案和血色十字军钥匙，并以毁灭性的奥术魔法守卫组织的圣所。",al={"杜安是谁","奥法师杜安背景","杜安与血色修道院"}},["46f867c9"]={q="奥法师杜安想要什么？",a="杜安坚信，奥术魔法是彻底净化洛丹伦、驱逐天灾军团的唯一办法。血色十字军的同袍几乎完全依靠圣光的狂热信仰，而杜安认为，只有原始的奥术力量和深入研究，才能彻底遏制并根除亡灵瘟疫。",al={"杜安的目标","杜安想要什么","奥法师杜安的动机"}},["88b26aa6"]={q="奥法师杜安为何令人畏惧？",a="杜安是洛丹伦最令人畏惧的强大法师之一。战斗中，他会用几乎坚不可摧的奥术屏障护住自己，同时施放毁灭性的爆炸法术，瞬间将大群闯入者烧成灰烬。",al={"杜安为何令人畏惧","杜安有多强","杜安的名声"}}},fp="13,220,23.418.0,37.188.0,53.153.0,36.244.0,35.219.0,42.163.0,38.122.0"}
P.entries["npc:archaeologist-flagongut"] = {n="考古学家弗拉冈特",s="考古学家弗拉冈特是一位代表探险者协会的矮人学者，驻扎在米奈希尔港的深水旅店中。尽管他最初是在前往当地的威尔加挖掘场途中，但他成为了接收来自黑海岸跨海而来的实地报告的重要联络人。",h="考古学家弗拉冈特是一位代表探险者协会的矮人学者，驻扎在米奈希尔港的深水旅店中。尽管他最初是在前往当地的威尔加挖掘场途中，但他成为了接收来自黑海岸跨海而来的实地报告的重要联络人。",kw={"考古学家","深水旅店","探险者协会","弗拉冈特","米奈希尔港","雷姆塔维尔","威尔加"},ang={["faction:Alliance"]="弗拉冈特充当了暗夜精灵的黑海岸领地与卡兹莫丹东部联盟据点之间的后勤桥梁。",["race:Dwarf"]="弗拉冈特代表了探险者协会深远的抱负，证明了即使是海边的一家小酒馆，也可以作为拼凑泰坦秘密的前哨站。"},sec={{t="港口的学者",b="考古学家弗拉冈特常常手持麦芽酒杯，在米奈希尔港的深水旅店中休息。像铁炉堡探险者协会的许多成员一样，他向西穿过卡兹莫丹，旨在协助湿地威尔加挖掘场附近的考古发现。尽管远离图书馆的高大殿堂，他仍与实地研究人员保持着密切联系，帮助处理通过无尽之海从遥远考察队运来的遗失文物和报告。"},{t="与实地的联系",b="矮人的好奇心很少局限于一片大陆。当心不在焉的勘察员雷姆塔维尔在黑海岸出土的神秘的化石被达纳苏斯的首席考古学家杜瑟·灰须转交给他时，弗拉冈特感到十分惊讶：他曾将一块类似的化石带到铁炉堡的探险者协会年度会议上，确信它蕴含着某种可以解开的力量。"}},faq={{q="考古学家弗拉冈特是谁？",a="弗拉冈特是来自探险者协会的矮人研究员。他驻扎在米奈希尔港的深水旅店，在那里审查挖掘现场的工作并与挖掘点进行联络。",al={"弗拉冈特是谁","弗拉冈特npc","考古学家弗拉冈特背景故事"}},{q="为什么弗拉冈特在深水旅店？",a="他最初到达米奈希尔港是为了前往湿地的威尔加挖掘场。在停靠期间，他以这家旅店为基地，处理邮件、入境文物以及来自海外的通信。",al={"为什么弗拉冈特在米奈希尔","弗拉冈特位置","弗拉冈特在这里做什么"}},{q="弗拉冈特与黑海岸有什么联系？",a="勘察员雷姆塔维尔在黑海岸发现的神秘的化石被达纳苏斯的首席考古学家杜瑟·灰须转交给了弗拉冈特，因为这块化石与弗拉冈特曾经带到探险者协会会议上的一块非常相似。弗拉冈特相信这类化石蕴含着可以被解开的力量。",al={"弗拉冈特与黑海岸的联系","为什么在湿地有黑海岸任务"}},{q="他属于什么组织？",a="他属于探险者协会，这是国王麦格尼·铜须建立的皇家协会，致力于揭示艾泽拉斯矮人种族的古代起源、文物和历史。",al={"弗拉冈特所属阵营","弗拉冈特探险者协会"}}},fp="23,228,17.421.0,17.367.0,31.184.0,41.198.0,40.252.0,36.169.0"}
P.entries["npc:archaeologist-hollee"] = {n="考古学家霍莉",s="考古学家霍莉是一位驻扎在奥伯丁沿海定居点的矮人研究员。她代表矮人的挖掘利益，负责记录并考察整个黑暗海岸这片古老而雾气笼罩的荒野上的考古发现。她经常与在这一地区搜寻遗物和地质异常的勘察员协调工作。",h="考古学家霍莉是一位驻扎在奥伯丁沿海定居点的矮人研究员。她代表矮人的挖掘利益，负责记录并考察整个黑暗海岸这片古老而雾气笼罩的荒野上的考古发现。她经常与在这一地区搜寻遗物和地质异常的勘察员协调工作。",kw={"考古学家霍莉","奥伯丁","黑暗海岸","探险者协会","铁炉堡","勘察员雷姆塔维尔","心不在焉的勘察员","黑暗海岸的麻烦"},ang={["faction:Alliance"]="霍莉代表了东部王国与暗夜精灵之间的合作，利用奥伯丁作为基地来研究卡利姆多久远的过去。",["race:Dwarf"]="在黑暗海岸多雾的森林中看到一位远渡重洋的同胞，这时刻提醒着人们铁炉堡对于发掘古代历史有着无限的渴求。"},sec={{t="卡多雷土地上的矮人学者",b="虽然黑暗海岸主要由暗夜精灵守卫和定居，但像考古学家霍莉这样的矮人学者的出现，反映了铁炉堡对卡利姆多的日益关注。探险者协会派遣代表远渡重洋去发掘古代历史的痕迹，而黑暗海岸的废墟为研究提供了诱人的土壤。霍莉以奥伯丁为临时基地，担任游荡的勘察员和探险队的区域联络人。"},{t="关注雷姆塔维尔",b="霍莉日常工作的一大部分涉及追踪她的实地研究同事，特别是心不在焉的勘察员雷姆塔维尔。雷姆塔维尔被委以在狂野海岸进行重要勘测任务的重任，却经常在没有按时汇报的情况下走得很远。霍莉经常征募路过奥伯丁的旅行者去追踪他，寻回丢失的勘测数据，并确保实地研究工作不会成为当地野生生物或逼近的威胁的牺牲品。"}},faq={{q="考古学家霍莉是谁？",a="考古学家霍莉是一位驻扎在黑暗海岸奥伯丁的矮人。她代表矮人在西大陆的考古事业，负责开展和监督区域性的实地研究。",al={"霍莉是谁","黑暗海岸的霍莉","奥伯丁的矮人"}},{q="在哪里可以找到霍莉？",a="她位于黑暗海岸西海岸的奥伯丁沿海港口城镇。",al={"霍莉的位置","考古学家霍莉在哪里"}},{q="为什么矮人在黑暗海岸进行研究？",a="在第三次战争之后，随着铁炉堡与暗夜精灵之间联盟关系的加深，矮人研究员们来到卡利姆多，研究古老的遗物、地质结构以及可能揭示他们自身起源的久远历史。",al={"为什么矮人在黑暗海岸","卡利姆多的铁炉堡"}},{q="她需要什么方面的帮助？",a="霍莉主要关心的是勘察员雷姆塔维尔，这是一位心不在焉的勘测员，他独自游荡到了黑暗海岸的南部地区，并且未能带着他的发现回来汇报。",al={"霍莉的任务","心不在焉的勘察员任务"}},{q="霍莉和勘察员雷姆塔维尔是什么关系？",a="他们是在黑暗海岸共同进行挖掘和勘测工作的同事。虽然雷姆塔维尔在废墟中进行实际的野外考察，但霍莉负责协调报告并与来自奥伯丁的旅行者进行联络。",al={"雷姆塔维尔是谁","雷姆塔维尔和霍莉"}},{q="霍莉属于探险者协会吗？",a="她代表与铁炉堡结盟的矮人考古和勘探远征队，这些远征队通常在以东部王国为基地的探险者协会的庇护下组织。",al={"探险者协会的霍莉","霍莉的阵营"}}},fp="20,230,35.339.0,25.347.1,28.149.0,26.85.0,49.221.0,37.145.0,65.200.0,44.203.0"}
P.entries["npc:archbishop-benedictus"] = {n="大主教本尼迪塔斯",s="大主教本尼迪塔斯是圣光教会的最高精神领袖，在暴风城的Cathedral of Light领导着信徒们。作为阿隆苏斯·法奥大主教曾经虔诚的学生，如今在局势极其动荡的时期，他指引着联盟的道德与宗教核心。",h="大主教本尼迪塔斯是圣光教会的最高精神领袖，在暴风城的Cathedral of Light领导着信徒们。作为阿隆苏斯·法奥大主教曾经虔诚的学生，如今在局势极其动荡的时期，他指引着联盟的道德与宗教核心。",kw={"阿隆苏斯·法奥","大主教","本尼迪塔斯","cathedral of light","圣光教会","帕雷斯之眼","牧师","暴风城"},ang={["class:Priest"]="作为圣光教会的最高牧者，本尼迪塔斯是监督所有联盟牧师的训练、教义和誓言的核心人物。",["faction:Alliance"]="本尼迪塔斯担任着暴风城乃至整个联盟的道德指南针，为难民提供精神慰藉，并指导高级圣骑士和指挥官。"},sec={{t="圣光牧者",b="本尼迪塔斯在他受人敬仰的导师阿隆苏斯·法奥大主教去世后崛起并成为了领袖。在目睹了第一次和第二次战争带来的破坏后，本尼迪塔斯监督了暴风城壮丽的Cathedral of Light的建设，并发誓要守护信仰的美德。随着第三次战争中洛丹伦的陷落和天灾军团的崛起，人类王国的精神指引重担便落在了他的肩上。他在祭坛前为皇室提供建议，训练新入会的牧师，并指挥针对威胁艾泽拉斯的亡灵和恶魔势力的神圣远征。"},{t="希望的灯塔",b="本尼迪塔斯在联盟中被视为一位温和、睿智且慈悲的族长，他为公众展现了一座坚不可摧的希望灯塔，号召英雄们消灭像卡利姆多的寒冰之王阿门纳尔这样的黑暗威胁，并协助净化由虔诚的冒险者带来的被诅咒的圣物。"}},faq={{q="大主教本尼迪塔斯是谁？",a="他是圣光教会的现任领袖，也是大联盟中最高的宗教权威。他驻守在暴风城的Cathedral of Light，负责引导信徒并为王国领袖提供建议。",al={"本尼迪塔斯","大主教暴风城","圣光教会领袖"}},{q="他与阿隆苏斯·法奥是什么关系？",a="本尼迪塔斯是传奇大主教阿隆苏斯·法奥最得意的学生，而法奥正是白银之手骑士团的创始人。在法奥去世后，本尼迪塔斯继承了教会的领导权，以继续完成他导师的事业。",al={"法奥的学生","阿隆苏斯·法奥本尼迪塔斯"}},{q="本尼迪塔斯为冒险者监督哪些任务？",a="本尼迪塔斯指导联盟英雄进行对抗天灾军团的任务，包括批准前往剃刀高地的远征，以击杀巫妖寒冰之王阿门纳尔。他还利用自己的神圣力量净化强大的被腐蚀的神器，例如被诅咒的帕雷斯之眼。",al={"本尼迪塔斯任务","大主教本尼迪塔斯做什么"}},{q="他对亡灵持什么态度？",a="本尼迪塔斯对亡灵展现了一种冷酷的怜悯。据他的追随者卡尔·菲利普斯指挥官所言，大主教希望给予被遗忘者以迅速而彻底的死亡，并要求将他们的心脏带回，以便在Cathedral of Light中将其焚毁。",al={"本尼迪塔斯与被遗忘者","本尼迪塔斯对天灾军团的看法"}}},fp="21,169,26.598.0,16.287.0,29.226.0,41.211.0,51.240.0,33.221.0"}
P.entries["npc:archmage-ansirem-runeweaver"] = {n="大法师安斯雷姆·鲁因维沃尔",s="大法师安斯雷姆·鲁因维沃尔是一位资深的人类法师，也是达拉然六人议会的成员之一。在第三次战争中，他幸存于天灾军团对达拉然的毁灭性打击，并在达拉然重建期间，于紫罗兰城堡统筹肯瑞托的各项行动。尽管他致力于城市的重建工作，但也始终关注着外界的事务——包括他那个任性的女儿，她跑去藏宝海湾当了一名海盗。",h="大法师安斯雷姆·鲁因维沃尔是一位资深的人类法师，也是达拉然六人议会的成员之一。在第三次战争中，他幸存于天灾军团对达拉然的毁灭性打击，并在达拉然重建期间，于紫罗兰城堡统筹肯瑞托的各项行动。尽管他致力于城市的重建工作，但也始...",kw={"安斯雷姆","藏宝海湾","凯特琳","六人议会","达拉然","紫罗兰城堡","肯瑞托","里维加兹","鲁因维沃尔"},ang={["class:Mage"]="安斯雷姆是六人议会中受人尊敬的一员，这使他成为了严谨奥术研究领域中持久的权威。",["faction:Alliance"]="作为一名常驻洛丹伦的肯瑞托领导人，随着人类施法者努力从天灾余孽手中夺回自己的土地，安斯雷姆始终与联盟的利益保持一致。"},sec={{t="肯瑞托的支柱",b="安斯雷姆·鲁因维沃尔是一位资深法师，几十年来一直致力于保卫达拉然。他身居肯瑞托的统治机构——六人议会。当阿尔萨斯·米奈希尔率领天灾军团攻打这座城市并召唤阿克蒙德时，他幸免于难。在达拉然陷落之后，安斯雷姆协助重建了这座奥术之城，并在防护结界提前恢复后，继续在紫罗兰城堡中开展工作。"},{t="遥远的羁绊",b="尽管身负学术重任且法师作风严谨，安斯雷姆在奥特兰克山脉之外也有个人牵挂。他任性的女儿凯特琳跑去藏宝海湾当了一名海盗，还带走了一把他在荆棘谷研究时发现的古老巨魔匕首。他也在那里与大财主里维加兹打过交道。此外，他还参与过涉及巨魔文物的奥术研究，并与遥远的国度保持着外交往来。"}},faq={{q="大法师安斯雷姆·鲁因维沃尔是谁？",a="他是一位卓有成就的人类法师，也是肯瑞托六人议会中的六位统治大法师之一。几十年来，他一直致力于保卫达拉然，目前负责监管重建后的城市及其奥术外围区域的运作。",al={"安斯雷姆是谁","安斯雷姆·鲁因维沃尔背景故事","大法师是谁"}},{q="他的女儿怎么了？",a="他任性的女儿凯特琳跑去藏宝海湾当了一名海盗，在那里她被称为利刃凯特琳。安斯雷姆曾把一把他在荆棘谷研究时发现的古老巨魔匕首送给她，她便带着那把匕首离开了。",al={"安斯雷姆的女儿","利刃凯特琳","凯特琳·鲁因维沃尔"}},{q="他在达拉然担任什么职务？",a="在达拉然于第三次战争被毁后的重建期间，安斯雷姆是紫罗兰城堡中的核心肯瑞托成员，负责协调研究、魔法防御以及与盟友之间的沟通工作。",al={"安斯雷姆为何在奥特兰克","安斯雷姆 达拉然","他在这里做什么"}},{q="安斯雷姆参加过第三次战争吗？",a="是的。安斯雷姆几十年来一直协助保卫达拉然，并亲身经历了天灾军团对城市的围攻，当时阿尔萨斯在守护着克尔苏加德召唤阿克蒙德的过程。他在城市毁灭中幸存下来，如今正协助重建达拉然。",al={"安斯雷姆 天灾军团","安斯雷姆是否与阿尔萨斯战斗过"}}},fp="27,420,25.428.0,19.452.0,35.233.0,30.233.0,28.213.0,35.217.0"}
P.entries["npc:archmage-malin"] = {n="大法师马林",s="大法师马林是一位资深人类法师，驻守在暴风城Mage Quarter的法师密室外。作为大法师特里兰的昔日学生，马林负责协调奥术事务，并派遣外勤人员前往东部王国各地回收魔法神器和稀有试剂。",h="大法师马林是一位资深人类法师，驻守在暴风城Mage Quarter的法师密室外。作为大法师特里兰的昔日学生，马林负责协调奥术事务，并派遣外勤人员前往东部王国各地回收魔法神器和稀有试剂。",kw={"阿拉希高地","大法师马林","克里汀","mage quarter","马林","斯奎尔图","暴风城","特里兰","法师密室"},ang={["class:Mage"]="对于造访法师密室的联盟法师而言，马林是在暴风城的正统学院学习与在野外回收遗物的危险现实之间架起的一座桥梁。",["faction:Alliance"]="马林在阿拉希的特工们正努力在辛迪加、巨石拳食人魔或部落抢先夺取之前，保护好那些强大的神器。"},sec={{t="法师密室的守望者",b="大法师马林伫立在法师密室高耸的螺旋塔下，是暴风城奥术修行者们的主要联络点。他师从大法师特里兰，这是一位富有传奇色彩的法师，而马林现在正致力于守护特里兰留下的遗产。当年轻的学徒们在塔内那旋转的蓝色传送门中研习理论时，马林则将注意力集中在王国之外，关注着那些需要魔法监管的事务。"},{t="高地之眼",b="马林的大部分精力都投向了北方危机四伏的阿拉希高地废墟。为了寻回大法师特里兰遗失的财物并确保稀有法术组件的安全，马林派遣了他信任的同伴——斯奎尔图和学徒克里汀前往现场。马林在首都协调着这些远方的行动，并依靠能干的联盟旅行者将指令、补给和情报传达给他身处敌对领地的特工们。"}},faq={{q="大法师马林是谁？",a="大法师马林是暴风城的一位高级人类法师。他驻守在Mage Quarter法师密室的入口外，负责监督研究计划，派遣外勤学徒，并帮助维护首都魔法修行者之间的秩序。",al={"大法师马林背景故事","马林是谁","马林 暴风城"}},{q="马林与大法师特里兰有什么关系？",a="大法师特里兰是马林最初的导师。马林对特里兰始终保持着深厚的忠诚，积极协调各方努力，寻找并收回他昔日导师散落在阿拉希高地各处的个人物品和魔法遗物。",al={"马林 特里兰","马林的导师是谁","大法师特里兰的关系"}},{q="马林为什么要派冒险者去阿拉希高地？",a="马林有两名特工驻扎在阿拉希高地：斯奎尔图和学徒克里汀。由于路途艰险且通讯困难，马林雇佣往来的冒险者将重要的请求、魔法补给以及关于回收特里兰遗物的指令传达给他的外勤人员。",al={"马林的请求任务","为什么是阿拉希","斯奎尔图任务"}},{q="大法师马林在哪里？",a="他站在暴风城Mage Quarter中心法师密室塔楼的基座外，俯瞰着通往密室传送门大厅的斜坡。",al={"马林在哪里","大法师马林位置","马林 地图"}}},fp="14,230,31.318.0,21.374.0,22.228.0,47.193.0,56.265.0,34.198.0"}
P.entries["npc:archmage-xylem"] = {n="大法师克希雷姆",s="大法师克希雷姆是一位古怪而深居简出的人类法师，居住在艾萨拉北部悬崖顶端的一座与世隔绝的塔楼中。他以性格反复无常和进行危险的实验而闻名，为了追求深奥的奥术研究，他早已远离世俗。前往那里需要使用魔法传送，而且他只接待那些能协助他进行独特研究或帮助他处理个人恩怨的冒险者。",h="大法师克希雷姆是一位古怪而深居简出的人类法师，居住在艾萨拉北部悬崖顶端的一座与世隔绝的塔楼中。他以性格反复无常和进行危险的实验而闻名，为了追求深奥的奥术研究，他早已远离世俗。前往那里需要使用魔法传送，而且他只接待那些能协...",kw={"奥术","大法师","艾萨拉","莫法兹","萨纳斯·林尤","塔楼","克希雷姆"},ang={["class:Mage"]="对于奥术修行者而言，克希雷姆既代表了至高的造诣，也代表了在追求魔法力量的过程中彻底与世隔绝所带来的令人不安的后果。",["faction:Horde"]="尽管是人类，这位深居简出的法师却出人意料地愿意与那些能协助他研究的部落勇士进行交涉。",["race:Human"]="与达拉然或暴风城的正统法师不同，克希雷姆完全抛弃了人类社会，在艾萨拉的荒野之上过着不受打扰的生活。"},sec={{t="海岸之上的隐士",b="大法师克希雷姆居住在艾萨拉北部崎岖悬崖高处的一座隐蔽尖塔中，俯瞰着破碎的精灵海岸。这位法师并没有修筑道路或小径，而是将他的避难所完全与世隔绝，依靠他的仆从萨纳斯·林尤将获准的访客通过魔法传送到悬崖之上。整个卡利姆多的观察者都认为他极其古怪，与之打交道十分危险；甚至连其他的学者在对待他时都保持着深深的警惕，因为他的行为举止几乎与任何其他人族法师都迥然不同。"},{t="对莫法兹的宿怨",b="克希雷姆的隐居生活并非完全平静；他怀着对绿龙军团的强烈怨恨，特别是针对一只名叫莫法兹的幼龙。过去，这头野兽一口吞掉了克希雷姆的一名不幸学徒——连同学生一起吞下的还有一枚拥有巨大能量的奥术碎片。这位复仇心切的大法师并没有哀悼学徒，而是执着于猎杀莫法兹，以便从那头龙的肚子里取回这件珍贵的宝物。"}},faq={{q="如何前往大法师克希雷姆的塔楼？",a="大法师克希雷姆的塔楼坐落在艾萨拉北部一座无法攀登的悬崖顶端，没有步行道路可以上去。要找到他，你必须找到他的仆从萨纳斯·林尤，他就站在悬崖底部附近，可以将旅行者通过魔法传送到塔楼区域。",al={"前往克希雷姆处","前往克希雷姆塔楼","传送至克希雷姆处","克希雷姆位置"}},{q="大法师克希雷姆是谁？",a="他是一位古怪的人类大法师，居住在艾萨拉北部一座孤立的悬崖塔楼中，远离文明世界，进行着危险的奥术实验。",al={"克希雷姆是谁","大法师克希雷姆背景","克希雷姆背景"}},{q="克希雷姆为什么要杀掉巨龙莫法兹？",a="绿龙莫法兹袭击了克希雷姆的追随者，并一口吞掉了一名学徒。那名学徒当时随身携带了一枚拥有强大奥术能量的碎片，克希雷姆寻求消灭这头幼龙，以便从它的胃里取回那件遗物。",al={"克希雷姆与莫法兹","为什么要杀莫法兹","莫法兹与碎片"}},{q="为什么人们说克希雷姆很危险？",a="像耶迪加这样的当地联络人警告旅行者，与其他人族相比，克希雷姆难以捉摸、冷漠疏离且非常怪异。",al={"克希雷姆危险吗","克希雷姆疯了吗","克希雷姆性格"}},{q="克希雷姆属于联盟还是肯瑞托？",a="克希雷姆是一个彻底独立的隐士。他不为联盟军队效力，并且愿意与任何愿意听命于他的冒险者进行交易，无论其阵营如何。",al={"克希雷姆阵营","克希雷姆是联盟吗","克希雷姆与肯瑞托"}}},fp="14,410,25.521.0,24.442.1,40.269.0,22.158.0,44.235.0,37.125.0,51.191.0"}
P.entries["npc:argent-guard-manados"] = {n="银月守卫玛纳杜斯",s="银月守卫玛纳杜斯是一名代表银色黎明驻扎在达纳苏斯的暗夜精灵哨兵。他驻守在工匠区，监视着卡利姆多日益增长的腐化，并将冒险者引向潜伏在黑暗深渊中的邪恶势力。",h="银月守卫玛纳杜斯是一名代表银色黎明驻扎在达纳苏斯的暗夜精灵哨兵。他驻守在工匠区，监视着卡利姆多日益增长的腐化，并将冒险者引向潜伏在黑暗深渊中的邪恶势力。",kw={"银色黎明","银月守卫玛纳杜斯","黑暗深渊","工匠区","达纳苏斯","玛纳杜斯","暮光之坠"},ang={["faction:Alliance"]="对于造访达纳苏斯的联盟勇士来说，玛纳杜斯在洛丹伦遥远的圣战与卡利姆多北部日益逼近的邪教威胁之间建立了一个关键的联系。",["race:NightElf"]="玛纳杜斯表明，并非所有的暗夜精灵都将自己的职责局限于塞纳里奥议会或哨兵部队；有些人为了守护艾泽拉斯，将一生奉献给了像银色黎明这样的中立跨阵营组织。"},sec={{t="黎明的哨兵",b="虽然银色黎明的大部分精力都集中在洛丹伦的被瘟疫侵蚀的土地和天灾军团上，但银月守卫玛纳杜斯代表他们，在暗夜精灵主城达纳苏斯充当警惕的双眼。玛纳杜斯站在工匠区的工匠和商贩之中，监视着威胁卡利姆多北部平衡的新兴威胁。当他收到暮光之锤教派在灰谷水下建立邪恶据点的传言时，玛纳杜斯便招募有能力的英雄去进攻黑暗深渊，并找回他们黑暗信仰的圣物。"}},faq={{q="谁是银月守卫玛纳杜斯？",a="玛纳杜斯是一名驻扎在达纳苏斯的银色黎明暗夜精灵特工。他没有在东部王国对抗天灾军团，而是留在卡利姆多，监视黑暗教派和来自异界的腐化。",al={"玛纳杜斯是谁","银月守卫玛纳杜斯的职责","达纳苏斯的玛纳杜斯"}},{q="在哪里可以找到银月守卫玛纳杜斯？",a="他位于达纳苏斯的工匠区，在那里守护着城市并与当地的冒险者协调行动。",al={"玛纳杜斯的位置","银月守卫玛纳杜斯在哪里","玛纳杜斯 工匠区"}},{q="银月守卫玛纳杜斯会提供什么任务？",a="他提供任务“暮光之坠”，要求冒险者进入灰谷的黑暗深渊，从潜伏在其中的邪教徒身上找回暮光吊坠。",al={"玛纳杜斯的任务","暮光之坠任务发布者","黑暗深渊银色黎明任务"}},{q="为什么银色黎明会对黑暗深渊感兴趣？",a="银色黎明致力于对抗威胁艾泽拉斯的邪恶势力。暮光之锤教派突然出现，在灰谷的沉没废墟中崇拜古老且腐化的存在，这构成了他们无法忽视的威胁。",al={"为什么银色黎明关注黑暗深渊","银色黎明 暮光教派"}}},fx={df5dd966={q="银月守卫玛纳杜斯属于哪一方？",a="银月守卫玛纳杜斯效力于银色黎明，这是一个致力于铲除邪恶、保护艾泽拉斯免受黑暗腐化侵害的独立组织。虽然他是一名驻扎在达纳苏斯的暗夜精灵，但他主要效忠于银色黎明在世界各地开展的圣战，而非联盟的常规指挥体系。",al={"玛纳杜斯的阵营","玛纳杜斯效忠谁","玛纳杜斯是否属于联盟"}},f4cc0234={q="银月守卫玛纳杜斯想做什么？",a="玛纳杜斯想要阻止在灰谷海岸滋生的黑暗仪式。他召集能干的冒险者深入黑暗深渊，打击亵渎暗夜精灵古老圣所的暮光之锤教徒。",al={"玛纳杜斯在寻找什么","玛纳杜斯的目标","为何派人前往黑暗深渊"}}},fp="20,175,22.472.0,28.193.0,38.136.0,43.143.0,55.215.0"}
P.entries["npc:argos-nightwhisper"] = {n="阿古斯·夜语",s="阿古斯·夜语是一位出现在暴风城公园区的暗夜精灵特使。他担任联盟联络人，引导冒险者前往黑海岸，他的兄弟戈沙拉正在那里研究不断蔓延的腐蚀。",h="阿古斯·夜语是一位出现在暴风城公园区的暗夜精灵特使。他担任联盟联络人，引导冒险者前往黑海岸，他的兄弟戈沙拉正在那里研究不断蔓延的腐蚀。",kw={"阿古斯","奥伯丁","腐蚀蔓延","达纳苏斯","卡多雷","夜语","公园区","暴风城"},ang={["faction:Alliance"]="阿古斯是东部王国和卡利姆多之间早期的联络纽带，鼓励年轻的联盟英雄跨越大海去援助暗夜精灵。",["race:NightElf"]="对于远离卡利姆多的卡多雷旅行者来说，阿古斯是一个熟悉的面孔，他指引旅行者前往他在黑海岸的兄弟处，去面对威胁他们家园的危机。"},sec={{t="人类首都的卡多雷",b="阿古斯·夜语居住在暴风城中日益壮大的暗夜精灵群体中，常常流连于那片葱郁而僻静的公园区，那里旨在让卡多雷想起他们祖先的林地。像许多驻扎在人类王国的族人一样，阿古斯在跨越无尽之海的新盟友之间架起了一座桥梁。由于深感对跨洋传来的消息的担忧，他敦促有能力的联盟勇士踏上前往黑海岸奥伯丁的长途旅程，他的兄弟戈沙拉正需要在那里对抗蔓延的腐蚀。"}},faq={{q="阿古斯·夜语是谁？",a="阿古斯·夜语是一位居住在暴风城的暗夜精灵。他在联盟东部首都代表达纳苏斯的利益，帮助组织旅行者并指引冒险者乘船前往卡利姆多。",al={"阿古斯·夜语","阿古斯是谁","阿古斯 暴风城"}},{q="在哪里可以找到阿古斯·夜语？",a="阿古斯位于公园区，那是暴风城中造访的暗夜精灵们聚集的绿色区域。",al={"阿古斯位置","阿古斯在哪里","寻找阿古斯·夜语"}},{q="阿古斯要求冒险者做什么？",a="阿古斯请求经验丰富的冒险者前往黑海岸的奥伯丁，他的兄弟戈沙拉正需要在那里寻求帮助，以研究这片土地上蔓延的腐蚀。",al={"腐蚀蔓延任务","阿古斯任务","为什么要前往达纳苏斯"}},{q="阿古斯和其他夜语家族成员有关系吗？",a="是的。阿古斯是戈沙拉·夜语的兄弟，后者是黑海岸奥伯丁的一位暗夜精灵学者，这也是他将冒险者派往那里的原因。",al={"夜语家族","阿古斯的亲属"}}},fp="18,144,31.434.0,26.165.0,38.98.0,38.152.0,40.139.0"}
P.entries["npc:arugal"] = {n="阿鲁高",s="大法师阿鲁高是达拉然的一名前巫师，他将狂暴的狼人释放到了洛丹伦。在疯狂与悲痛的驱使下，他如今统治着高耸的影牙城堡，将这些野兽视如己出，并威胁着整个银松森林。",h="大法师阿鲁高是达拉然的一名前巫师，他将狂暴的狼人释放到了洛丹伦。在疯狂与悲痛的驱使下，他如今统治着高耸的影牙城堡，将这些野兽视如己出，并威胁着整个银松森林。",kw={"阿鲁高","肯瑞托","焚木村","影牙城堡","席瓦莱恩","银松森林","乌尔","狼人"},ang={["class:Mage"]="阿鲁高代表了鲁莽召唤所带来的灾难性危险，将肯瑞托深奥的研究变成了一场无法控制的噩梦。",["faction:Horde"]="阿鲁高的狼人出没在瑟伯切尔以南的道路上，希尔瓦娜斯女士下令处决他，以确保被遗忘者能稳固银松森林。",["race:Undead"]="阿鲁高的野兽杀死了几名死亡猎手和药剂师；终结他的疯狂对于皇家药剂师协会来说是一项至关重要的任务。"},sec={{t="绝望的召唤",b="在洛丹伦陷落之前，阿鲁高曾是肯瑞托的一员，尽管像达拉尔·道恩维沃尔这样的一些同僚认为他只是个靠附魔饰品施展软弱法术的江湖骗子。当第三次战争中天灾军团席卷北方时，阿鲁高寻求一种足以阻挡这股浪潮的强力武器。他利用已故达拉然法师乌尔的秘术研究，刺穿了领域之间的面纱，将狼人召唤到了凡人的世界。这些贪婪的野兽正如预想的那样撕碎了亡灵军团，但它们狂野的凶性无法被遏制，它们野蛮的饥饿迅速转向了无辜的凡人。"},{t="陷入疯狂",b="召唤出来的恐怖生物不仅屠杀了天灾军团，很快也将矛头对准了巫师们自己。随后，这些野兽围攻了席瓦莱恩男爵的祖宅，城堡在利爪和尖牙下迅速陷落，男爵和他的仆从在屠杀中丧生。阿鲁高没有逃离他创造的怪物，而是因为负罪感而精神崩溃，他收养了这些野兽作为自己的后代。他将这座堡垒更名为影牙城堡，并固守在城墙之内，周围环绕着幽灵般的受害者和忠诚的猎犬群。"},{t="银松森林的祸害",b="从影牙城堡的高处，阿鲁高将其扭曲的统治延伸到周围的乡村。他的黑暗魔法笼罩了焚木村，使得村民们生活在夜晚的诅咒之中，并让饥饿的月怒野兽侵扰着埃利姆矿洞。被遗忘者如今视他为无法容忍的威胁；Sylvanas Windrunner麾下的死亡猎手和药剂师正积极谋划处决这位疯狂的大法师，以确保他们新兴王国的边境安全。"}},faq={{q="阿鲁高是谁？",a="阿鲁高是一位曾属于肯瑞托的人类大法师。在第三次战争期间，他召唤了可怕的狼人来对抗天灾军团。由于不堪自己的所作所为，他退居影牙城堡，如今他率领着一群狼人，并自称为它们的父亲。",al={"阿鲁高是谁","阿鲁高的背景故事","影牙城堡首领剧情"}},{q="阿鲁高为什么要召唤狼人？",a="在第三次战争期间，天灾军团威胁要淹没洛丹伦北部。为了寻找一种能阻止亡灵的武器，阿鲁高急中生智，利用了达拉然法师乌尔关于异界的研究。他相信这些野蛮的野兽能够消灭天灾军团，但他在召唤出这些生物后却失去了控制。",al={"为什么是狼人","为什么要召唤野兽","阿鲁高召唤狼人的动机"}},{q="阿鲁高现在住在哪里？",a="阿鲁高将巢穴设在影牙城堡的顶端，这是一座俯瞰银松森林南部焚木村的古老堡垒。他由自己的怪兽狼宠物芬鲁斯，以及成群忠诚的狼人和不安的灵魂所守护。",al={"阿鲁高在哪里","阿鲁高的位置","寻找阿鲁高"}},{q="席瓦莱恩男爵发生了什么事？",a="席瓦莱恩男爵曾是最初统治这座城堡和焚木村的贵族领主。当阿鲁高的狼人围攻城堡时，席瓦莱恩和他的随从被残忍地屠杀。他们复仇心切、饱受折磨的鬼魂如今徘徊在城堡那沾满鲜血的大厅里。",al={"席瓦莱恩男爵的命运","谁拥有影牙城堡","城堡历史"}},{q="为什么被遗忘者想要除掉阿鲁高？",a="阿鲁高的狼群恐吓着银松森林，攻击被遗忘者的侦察兵，伏击巡逻队，甚至感染了皇家药剂师协会的忠诚仆从。Sylvanas Windrunner认为这位疯狂的大法师是对幽暗城边境安全和扩张的直接威胁。",al={"被遗忘者对抗阿鲁高","必须处死阿鲁高任务","为什么要除掉阿鲁高"}},{q="焚木村的诅咒是什么？",a="阿鲁高在该地区施加了邪恶的附魔，使焚木村的人类居民遭受了狼人诅咒。白天，村民们表现得像正常的人类臣民，但到了夜晚，他们就会变成必须保卫阿鲁高领地的凶猛野兽。",al={"焚木村的诅咒","为什么焚木村村民会变成狼","焚木村与阿鲁高"}}},fx={c709d248={q="大法师阿鲁高属于哪一方？",a="阿鲁高既不效力于联盟，也不效力于部落。他曾是达拉然肯瑞托的一员，但陷入疯狂后断绝了所有旧日关系。如今，他在影牙城堡中率领自己的野蛮狼群，将狼人视为真正的子嗣，并强烈排斥肯瑞托使者和被遗忘者。",al={"阿鲁高的阵营","阿鲁高效忠谁","阿鲁高属于部落还是联盟"}},["5a0ecd53"]={q="大法师阿鲁高想做什么？",a="阿鲁高释放狼人给世间带来灾祸后，深陷罪疚与疯狂，如今一心想庇护、统领并壮大自己的族群。他用附魔魔法将野兽束缚于自己的意志之下，在银松森林传播狼人诅咒，以建立他黑暗的家族，并屠杀任何胆敢侵入其领地的人。",al={"阿鲁高的目标","阿鲁高想做什么","阿鲁高的动机"}},["127eccbf"]={q="大法师阿鲁高为何在影牙城堡？",a="被召唤出的狼人挣脱控制后，袭击了焚木村上方席瓦莱恩男爵的堡垒。阿鲁高因自己一手酿成的灾祸而发疯，将凶暴的野兽收为子嗣，占据了化为废墟的城堡，并将其更名为影牙城堡，以隐居之姿统治自己的族群。",al={"阿鲁高为何在这里","阿鲁高为何前往影牙城堡","阿鲁高如何占据影牙城堡"}},["760497b6"]={q="大法师阿鲁高为何令人畏惧？",a="阿鲁高因借助乌尔的禁忌研究、将野蛮的狼人释放到世间而在洛丹伦臭名昭著。他带来的诅咒不只杀死了天灾军团，还感染附近的土地，将和平的村民变成嗜血野兽，并在他反复无常的魔法操控下，把整个地区变成了噩梦。",al={"阿鲁高为何出名","阿鲁高的声望","阿鲁高为何危险"}}},fp="6,208,19.543.0,17.462.0,25.422.1,14.242.0,33.282.0,35.225.0,35.220.0,37.264.0,38.218.0"}
P.entries["npc:ashlan-stonesmirk"] = {n="阿什兰·暗石",s="阿什兰·暗石是一位矮人爆破专家，被指派到驻守丹莫德和萨多尔大桥的军团，位于湿地北部。从那里，他时刻警惕着威胁铁炉堡王国的区域危险。",h="阿什兰·暗石是一位矮人爆破专家，被指派到驻守丹莫德和萨多尔大桥的军团，位于湿地北部。从那里，他时刻警惕着威胁铁炉堡王国的区域危险。",kw={"迫近的黑暗威胁","阿什兰","丹莫德","铁炉堡","洛克莫丹","暗石"},ang={["faction:Alliance"]="协助阿什兰有助于稳固连接洛克莫丹与湿地及北部联盟领土的战略通道。",["race:Dwarf"]="暗石代表了在卡兹莫丹边境支持铁炉堡士兵的熟练专家。"},sec={{t="边境专家",b="阿什兰·暗石驻扎在湿地北部的丹莫德，效力于驻守萨多尔大桥的军团。他在爆破方面的专业知识使他成为应对威胁矮人防御的可疑材料时的重要联系人。"},{t="迫近的黑暗威胁",b="当首席工程师欣德维尔在巨石水坝附近发现可疑火药时，他将其送交给阿什兰进行检查。阿什兰鉴定该粉末为瑟银炸药，并提供了中和它的建议。"}},faq={{q="我能在哪里找到阿什兰·暗石？",a="在这个时代，阿什兰·暗石驻扎在湿地北部的丹莫德，靠近萨多尔大桥。",al={"阿什兰位置","阿什兰·暗石在哪里","阿什兰·暗石坐标"}},{q="阿什兰·暗石的角色是什么？",a="他是一位驻扎在丹莫德和萨多尔大桥守卫军团的矮人爆破专家。欣德维尔向他求助，以鉴定在巨石水坝附近发现的可疑火药。",al={"阿什兰·暗石是谁","阿什兰目的","阿什兰做什么"}},{q="阿什兰提供什么任务？",a="他在“迫近的黑暗威胁”任务中协助冒险者，检查由首席工程师欣德维尔送来的可疑火药。",al={"阿什兰任务","阿什兰·暗石提供的任务"}}},fx={["0cdc60de"]={q="阿什兰·暗石是谁？",a="阿什兰·暗石是一名矮人爆炸物专家，驻扎在湿地北部丹莫德的军团中。",al={"阿什兰是谁","阿什兰·暗石的背景","阿什兰·暗石是谁"}},c5f8e74c={q="阿什兰·暗石属于哪一方？",a="他效力于铁炉堡和联盟，协助守卫湿地北部，并查明对矮人工程构成威胁的事物。",al={"阿什兰·暗石的阵营","阿什兰是否属于联盟","阿什兰·暗石效忠谁"}},["82d01692"]={q="阿什兰·暗石为何在这里？",a="阿什兰驻扎在丹莫德，他的爆炸物知识能帮助矮人军团和调查巨石水坝险情的旅者。",al={"阿什兰为何在洛克莫丹","阿什兰·暗石营地的用途","阿什兰为何在莫格罗什附近"}}},fp="17,171,23.210.0,19.192.1,35.91.0,33.193.0,30.114.0"}
P.entries["npc:asterion"] = {n="阿斯特利安",s="阿斯特利安是一位被束缚在黑海岸巴莎兰遗迹中的古代上层精灵之魂。在一万年前，他曾是总督阿斯瑞克斯·纳拉辛最为信任的副手，但后来他神秘地被囚禁在了一枚魔法月亮石印记之中，这一禁锢贯穿了他的凡世一生，直至死后依然未曾消散。如今，他的幽灵依然被锁在这座破败的神龛里，周围环绕着恶魔野兽，在梦中渴望着重获自由。",h="阿斯特利安是一位被束缚在黑海岸巴莎兰遗迹中的古代上层精灵之魂。在一万年前，他曾是总督阿斯瑞克斯·纳拉辛最为信任的副手，但后来他神秘地被囚禁在了一枚魔法月亮石印记之中，这一禁锢贯穿了他的凡世一生，直至死后依然未曾消散。如今...",kw={"亚米萨兰","阿斯特利安","阿斯瑞克斯","巴莎兰","黑海岸","上层精灵","月亮石","纳拉辛","萨特"},ang={["class:Mage"]="在生前，阿斯特利安不仅因精通奥术而闻名，还具备卓越的近战能力，这使他成为了研究早期卡多雷法术的绝佳案例。",["faction:Alliance"]="阿斯特利安是少数愿意信任并协助联盟冒险者的上层精灵之魂，他寻求他们的帮助来打破自己长达万年的囚牢。",["race:NightElf"]="阿斯特利安是大分裂前的一件悲剧遗物，展现了上层精灵内部残酷的政治斗争，而这种斗争甚至在艾萨拉引燃燃烧军团入侵之前就已经存在了。"},sec={{t="古代辉煌的仆从",b="在大分裂摧毁古老的卡利姆多之前，巴莎兰和亚米萨兰是艾萨拉女王亲自赐福的姐妹城市。艾萨拉任命阿斯瑞克斯·纳拉辛治理这两座定居点，而阿斯特利安则是他的得力助手。阿斯特利安不仅因精通奥术魔法而备受尊敬，其卓越的格斗技巧也让他声名远扬。他在巴莎兰的居民中生活，并经常往返于两座姐妹城市之间，处理当地民众的事务。"},{t="月亮石监狱",b="出于某种早已被遗忘的原因，阿斯特利安失宠于他的主人。阿斯瑞克斯制作了一枚强大的月亮石印记，以此构筑了一个无法逃脱的魔法牢笼，将阿斯特利安囚禁在巴莎兰之中。这场囚禁持续了数个世纪的痛苦折磨；更糟糕的是，当阿斯特利安最终死亡时，他发现死亡并没有带来解脱。他的灵魂依然被束缚在破败的神龛中，当世界崩裂、恶魔淹没这座古老的定居点时，他却被遗弃在了这里。"},{t="来自坟墓的复仇",b="尽管邪恶的萨特和格瑞尔在巴莎兰的废墟中游荡，以残余的奥术能量为食，但它们却避开了阿斯特利安的幽灵所停留的神龛。如果联盟的冒险者能从萨特手中取回月亮石印记并在亚米萨兰将其摧毁，阿斯特利安的幽灵枷锁终将破裂。然而，自由并没能带给他安宁；感觉到阿斯瑞克斯·纳拉辛依然存活于世，这位古老的法师将他心中积累了万年的绝望转为了复仇的怒火。"}},faq={{q="阿斯特利安是谁？",a="阿斯特利安是一位古代上层精灵的幽灵，出现在黑海岸的巴莎兰遗迹中。在大分裂之前，他是一位造诣深厚的法师，也是总督阿斯瑞克斯·纳拉辛的副官。",al={"阿斯特利安传说","巴莎兰的幽灵是谁","黑海岸精灵幽灵"}},{q="为什么阿斯特利安被囚禁？",a="阿斯瑞克斯·纳拉辛利用一枚魔法月亮石印记束缚了阿斯特利安。他们决裂的具体原因尚不得而知，但那种魔法异常强大，以至于即使在阿斯特利安死后，咒语也未曾消散，将其灵魂困住了数千年。",al={"阿斯特利安为什么被困","阿斯特利安监狱","为什么阿斯瑞克斯要囚禁阿斯特利安"}},{q="为什么巴莎兰的萨特不攻击他？",a="虽然遗迹中的萨特和格瑞尔以巴莎兰残存的奥术能量为食，但它们却与阿斯特利安被束缚的神龛保持着距离。它们只是持有那枚作为其囚禁根源的月亮石印记，并未直接干扰他的灵魂。",al={"萨特会攻击阿斯特利安吗","为什么恶魔不理会阿斯特利安"}},{q="阿斯特利安生前居住在哪里？",a="阿斯特利安居住在巴莎兰的居民中，并经常南下前往姐妹城市亚米萨兰，在艾萨拉女王任命的总督管辖下处理市政事务。",al={"阿斯特利安的住所","阿斯特利安来自哪里"}},{q="在你释放他之后会发生什么？",a="阿斯特利安希望摧毁月亮石印记能结束他死后仍未停止的囚禁。该尝试的结果在剧透部分中有详细说明。",al={"阿斯特利安发生了什么","阿斯特利安会安息吗","阿斯特利安的复仇"}},{q="阿斯特利安对现代暗夜精灵持有敌意吗？",a="不。尽管他是来自艾萨拉女王宫廷的古代上层精灵，但阿斯特利安对联盟的旅行者非常友善，并寻求他们的帮助来打破他古老的魔法枷锁。",al={"阿斯特利安友好吗","阿斯特利安联盟"}}},fx={["0f52734c"]={q="阿斯特利安想做什么？",a="阿斯特利安想要摆脱困住自己灵魂长达一万年的古老魔法囚牢。阿斯瑞库斯·纳拉辛用月石封印将他束缚在巴莎兰，即使肉身消亡，阿斯特利安仍饱受折磨。他迫切需要你从萨特手中夺回封印，并在亚米萨兰将其击碎，以结束漫长的苦难，让他得以将心思转向报复昔日的主人。",al={"阿斯特利安的目标","阿斯特利安需要什么","阿斯特利安的动机"}},["98a0ebe3"]={q="阿斯特利安与谁有关联？",a="远古时期，阿斯特利安直接效力于阿斯瑞库斯·纳拉辛。阿斯瑞库斯是艾萨拉女王任命的上层精灵领主，负责统治亚米萨兰和巴莎兰。作为副手，阿斯特利安照料着两处聚居地的事务。尽管阿斯特利安忠心耿耿，阿斯瑞库斯还是用黑暗法术将他囚禁在奥术月石牢笼中，缘由早已湮没于历史，昔日的主从情谊也就此沦为背叛的遗产。",al={"阿斯特利安的主人","是谁囚禁了阿斯特利安","阿斯瑞库斯·纳拉辛与阿斯特利安"}}},fp="8,175,29.355.0,20.384.0,24.410.1,16.187.0,27.195.0,47.230.0,32.158.0,32.150.1,42.171.0"}
P.entries["npc:athridas-bearmantle"] = {n="阿斯瑞达斯·熊皮",s="阿斯瑞达斯·熊皮是一位居住在泰达希尔枝干上多兰纳尔的暗夜精灵德鲁伊。他肩负着保卫当地定居点的重任，指引年轻的冒险者去调查那些正在侵蚀当地野生动物和附近刺鬃熊怪的腐蚀力量。",h="阿斯瑞达斯·熊皮是一位居住在泰达希尔枝干上多兰纳尔的暗夜精灵德鲁伊。他肩负着保卫当地定居点的重任，指引年轻的冒险者去调查那些正在侵蚀当地野生动物和附近刺鬃熊怪的腐蚀力量。",kw={"阿斯瑞达斯","熊皮","多兰纳尔","熊怪","刺鬃","卡多雷","暗夜精灵","泰达希尔"},ang={["class:Druid"]="阿斯瑞达斯针对受腐蚀的刺鬃熊怪所发布的任务，以及他对远古遗物的关心，直接关系到德鲁伊誓言要恢复的自然平衡。",["race:NightElf"]="对于离开幽影谷的年轻卡多雷来说，阿斯瑞达斯代表了泰达希尔挣扎求生的现实，他指出了他们的新家园已经从内部受到了威胁。"},sec={{t="多兰纳尔的守卫",b="阿斯瑞达斯·熊皮驻扎在多兰纳尔，是暗夜精灵离开幽影谷后的第一道防线。随着新生的世界之树泰达希尔的枝干出现反常的腐朽和动荡迹象，阿斯瑞达斯不懈地协调当地的侦察工作，保护这个宁静的城镇免受周边威胁。"},{t="熊怪之灾",b="阿斯瑞达斯非常担心邻近的刺鬃熊怪部族。刺鬃熊怪曾经是和平的邻居，如今却陷入了蔓延的疯狂与腐蚀之中，这股力量毒害了他们的萨满和酋长，使他们陷入疯狂，对卡多雷发动猛烈的攻击。阿斯瑞达斯动员有志之士去遏制这种威胁，并挖掘出在荒野中扎根的深层污秽。"}},faq={{q="阿斯瑞达斯·熊皮是谁？",a="阿斯瑞达斯·熊皮是一位驻扎在泰达希尔岛上多兰纳尔的暗夜精灵。他负责组织当地防御，招募冒险者对抗正在世界之树枝干间蔓延的黑暗力量。",al={"阿斯瑞达斯是谁","阿斯瑞达斯·熊皮背景故事","阿斯瑞达斯 多兰纳尔"}},{q="我在哪里可以找到阿斯瑞达斯·熊皮？",a="阿斯瑞达斯位于多兰纳尔，这是暗夜精灵冒险者离开泰达希尔的幽影谷后到达的第一个主要城镇。",al={"阿斯瑞达斯位置","阿斯瑞达斯在哪里","寻找阿斯瑞达斯·熊皮"}},{q="阿斯瑞达斯关注哪些威胁？",a="阿斯瑞达斯主要关注那些受到腐蚀影响而变得富有攻击性的刺鬃熊怪，他指引旅行者平息他们的攻击，调查他们疯狂的原因，并找回重要的遗物。",al={"阿斯瑞达斯任务","阿斯瑞达斯的要求","阿斯瑞达斯·熊皮的工作"}},{q="为什么刺鬃熊怪要攻击多兰纳尔？",a="刺鬃部族沦为了渗透在泰达希尔中那股黑暗且反常的腐蚀的受害者，这使他们的萨满和战士陷入疯狂，并对暗夜精灵充满了敌意。",al={"为什么刺鬃熊怪会疯狂","刺鬃熊怪腐蚀","泰达希尔熊怪敌意"}},{q="阿斯瑞达斯在保卫泰达希尔中扮演什么角色？",a="阿斯瑞达斯担任初期守卫和组织者，确保泰达希尔的野兽和熊怪中蔓延的腐蚀能够在波及多兰纳尔定居点之前得到遏制。",al={"阿斯瑞达斯的作用","阿斯瑞达斯的重要性"}}},fp="19,205,20.268.0,22.344.0,27.184.0,37.115.0,36.197.0,50.171.0,52.148.0"}
P.entries["npc:auntie-bernice-stonefield"] = {n="波尼斯·斯通菲尔德姑妈",s="“阿姨”伯妮斯·斯通菲尔德是斯通菲尔德家族的长辈，住在艾尔文森林中南部他们的家园里。她的丈夫在王国的军事行动中阵亡，守寡后的她以其著名的猪肉馅饼闻名整个山谷。她常和斯通菲尔德妈妈一起待在农舍外，时刻警惕着周围的邻居，并对敌对的马科伦家族怀有极深的怀疑。",h="“阿姨”伯妮斯·斯通菲尔德是斯通菲尔德家族的长辈，住在艾尔文森林中南部他们的家园里。她的丈夫在王国的军事行动中阵亡，守寡后的她以其著名的猪肉馅饼闻名整个山谷。她常和斯通菲尔德妈妈一起待在农舍外，时刻警惕着周围的邻居，并对...",kw={"阿姨","伯妮斯","艾尔文","金牙","马科伦","项链","猪肉馅饼","斯通菲尔德"},ang={["profession:Cooking"]="伯妮斯的猪肉馅饼在艾尔文森林享有盛名，是人类边境地区热气腾腾的家常主食。",["race:Human"]="伯妮斯体现了暴风城乡村居民坚韧不拔的精神，在丈夫于王国的战争中牺牲后，依然坚持着日常生活，守护着家族的骄傲。"},sec={{t="艰辛的一生",b="和暴风城王国的许多平民一样，伯妮斯承担了持续不断的战争所带来的沉重代价。在失去丈夫后，她现在和亲人一起住在家族的家园里，协助族长斯通菲尔德妈妈打理日常农务。尽管遭受了个人损失，她依然操持着家务，维持家人的温饱，并凭借其招牌猪肉馅饼赢得了当地的名声。"},{t="积怨与丢失的项链",b="斯通菲尔德家族和马科伦家族之间长期的积怨是伯妮斯世界观中非常重要的一部分。当她珍贵的家传项链丢失时，她立刻怀疑是年轻的比利·马科伦偷走了它。然而，找回她的纪念品比处理邻居的小恶作剧要复杂得多：比利发誓不是他干的，但他差点说漏嘴，提到他曾在法戈第矿洞附近弄丢了东西，在那里他看到金牙狗头人抢走了它并带回了自己的洞穴。"}},faq={{q="“阿姨”伯妮斯·斯通菲尔德是谁？",a="她是居住在艾尔文森林南部斯通菲尔德农场的一位斯通菲尔德家族长辈。她是一位战争寡妇，每天和斯通菲尔德妈妈一起在农场劳作，并烘焙她著名的猪肉馅饼。",al={"阿姨伯妮斯是谁","伯妮斯·斯通菲尔德背景故事","斯通菲尔德阿姨"}},{q="“阿姨”伯妮斯的丈夫发生了什么事？",a="伯妮斯的丈夫在为暴风城王国作战的军事行动中阵亡，她因此守了寡。",al={"阿姨伯妮斯的丈夫","伯妮斯的丈夫是谁","斯通菲尔德寡妇"}},{q="“阿姨”伯妮斯因什么而出名？",a="她因美味的猪肉馅饼而在当地乡村广为人知，这道点心非常诱人，连那些顽皮的邻居都忍不住想讨要一片尝尝。",al={"伯妮斯·斯通菲尔德馅饼","艾尔文森林猪肉馅饼"}},{q="为什么“阿姨”伯妮斯对比利·马科伦感到愤怒？",a="伯妮斯怀疑比利·马科伦偷了她珍视的家传项链，这激化了斯通菲尔德家族和马科伦家族之间长期的家族积怨。",al={"比利·马科伦积怨","伯妮斯项链窃贼","为什么伯妮斯讨厌比利"}},{q="比利·马科伦真的偷了项链吗？",a="比利发誓他不是小偷，但他差点承认自己在法戈第矿洞附近玩耍时弄丢了项链。他说是一个长着金牙的大狗头人，也就是金牙，捡走了项链并带回了他的洞穴。",al={"比利偷了项链吗","谁拿走了斯通菲尔德项链","金牙项链"}},{q="“阿姨”伯妮斯在哪里？",a="她就站在斯通菲尔德农场的主农舍外，该农场位于闪金镇和西部荒野之间道路的南侧，她常和斯通菲尔德妈妈站在一起。",al={"阿姨伯妮斯位置","伯妮斯·斯通菲尔德在哪里"}}},fp="27,319,18.302.0,33.438.1,33.237.0,42.109.0,34.129.0,47.141.0,46.196.1,32.139.0"}
P.entries["npc:austil-de-mon"] = {n="奥斯蒂尔·德·蒙",s="奥斯蒂尔·德·蒙是一位被遗忘者战士训练师，驻扎在提瑞斯法林地的布瑞尔。他以恐惧之末旅店为基地，指导那些新复活的战士，帮助他们磨练武艺，为黑暗女王效力。",h="奥斯蒂尔·德·蒙是一位被遗忘者战士训练师，驻扎在提瑞斯法林地的布瑞尔。他以恐惧之末旅店为基地，指导那些新复活的战士，帮助他们磨练武艺，为黑暗女王效力。",kw={"奥斯蒂尔·德·蒙","布瑞尔","被遗忘者战士","恐惧之末旅店","提瑞斯法林地","战士训练师"},ang={["class:Warrior"]="对于离开丧钟镇的被遗忘者战士来说，奥斯蒂尔·德·蒙是在提瑞斯法林地提供指导和正式技能训练的主要导师之一。",["race:Undead"]="奥斯蒂尔帮助将新复活的亡灵磨练成强大的前线战士，让他们做好准备，保卫洛丹伦免受天灾军团和血色十字军的威胁。"},sec={{t="恐惧之末的老兵",b="奥斯蒂尔·德·蒙位于布瑞尔的恐惧之末旅店，他是被遗忘者战士从丧钟镇出发后的首批导师之一。虽然旅店曾经是生者饮酒休憩的地方，但现在奥斯蒂尔利用这处阴沉的避难所，教导刚获得自由的亡灵如何运用纯粹的武力纪律和冷酷的战斗技巧，去对抗王国周边的敌人。"}},faq={{q="奥斯蒂尔·德·蒙是谁？",a="奥斯蒂尔·德·蒙是一位驻扎在提瑞斯法林地布瑞尔的亡灵战士训练师，为被遗忘者战士提供训练。",al={"奥斯蒂尔·德·蒙","奥斯蒂尔","奥斯蒂尔是谁"}},{q="在哪里可以找到奥斯蒂尔·德·蒙？",a="你可以在提瑞斯法林地布瑞尔的恐惧之末旅店找到他，那里就在幽暗城的正北方。",al={"奥斯蒂尔·德·蒙位置","奥斯蒂尔在哪里","奥斯蒂尔·德·蒙地图"}},{q="他在布瑞尔扮演什么角色？",a="他指导新手战士学习战斗技巧、姿态和武力技能，以帮助加强被遗忘者的军事力量，对抗当地威胁。",al={"奥斯蒂尔做什么","奥斯蒂尔训练师","奥斯蒂尔职责"}}},fp="13,137,25.315.0,21.91.0,31.105.0,32.142.0"}
P.entries["npc:ayanna-everstride"] = {n="阿亚娜·远途",s="阿亚娜·远途是一位卡多雷猎人训练师，驻扎在泰达希尔幽影谷内的奥达希尔。她指导初出茅庐的暗夜精灵游侠学习箭术、追踪和荒野求生的基础技艺。年轻的猎人们在世界之树的枝叶下迈出第一步时，都会寻求她的指引，以磨练自己的林地修行。",h="阿亚娜·远途是一位卡多雷猎人训练师，驻扎在泰达希尔幽影谷内的奥达希尔。她指导初出茅庐的暗夜精灵游侠学习箭术、追踪和荒野求生的基础技艺。年轻的猎人们在世界之树的枝叶下迈出第一步时，都会寻求她的指引，以磨练自己的林地修行。",kw={"奥达希尔","阿亚娜","远途","猎人训练师","暗夜精灵","幽影谷","泰达希尔"},ang={["class:Hunter"]="对于在幽影谷开始旅程的暗夜精灵猎人新兵来说，阿亚娜·远途是他们在武器使用、追踪和在未开化的荒野中生存方面的第一位导师。",["race:NightElf"]="阿亚娜驻扎在奥达希尔的神圣树洞中，通过训练新兵抵御周围森林中不断侵蚀的腐化，从而协助守护这棵年轻的世界之树。"},sec={{t="幽影谷的导师",b="阿亚娜·远途盘踞在幽影谷中心的奥达希尔内，时刻准备着指导刚刚觉醒的卡多雷掌握荒野之道。对暗夜精灵来说，猎人不仅仅是陷阱捕手或神射手，更是神圣森林不可或缺的守护者。阿亚娜提供早期战斗技巧的指导，帮助新手掌握远程战斗，并在泰达希尔危险的树林中生存下来。"}},faq={{q="阿亚娜·远途是谁？",a="阿亚娜·远途是一位暗夜精灵猎人训练师，位于泰达希尔幽影谷新手区内的奥达希尔。她教授新手猎人基础的战斗技能和户外生存技巧。",al={"阿亚娜·远途","阿亚娜是谁","奥达希尔猎人训练师"}},{q="我在哪里可以找到阿亚娜·远途？",a="她位于奥达希尔的内部，那是座落在泰达希尔中心地带幽影谷中的巨大空心树定居点。",al={"阿亚娜位置","阿亚娜在哪里","找到阿亚娜·远途"}},{q="哪些任务与阿亚娜·远途有关？",a="新的暗夜精灵猎人会通过早期的训练任务被指引去找阿亚娜，比如从早期导师那里获得风化符记，之后她会为有志成为林地游侠的新人提供入门训练。",al={"阿亚娜任务","风化符记任务","阿亚娜任务发布者"}}},fp="17,174,22.329.0,25.150.0,35.128.0,38.186.0"}
P.entries["npc:ayessa-dawnsinger"] = {n="Ayessa Dawnsinger",s="Ayessa Dawnsinger 是位于泽风岛瓦拉纳尔的一位天空之子领袖。她领导着塑风者，指引效忠部落的天空之子们通过试炼并处理政治事务。",h="Ayessa Dawnsinger 是位于泽风岛瓦拉纳尔的一位天空之子领袖。她领导着塑风者，指引效忠部落的天空之子们通过试炼并处理政治事务。",kw={"ayessa","dawnsinger","部落","天空之子","瓦拉纳尔","塑风者","泽风"},ang={["faction:Horde"]="对于部落而言，Ayessa Dawnsinger 代表了他们与天空之子的主要伙伴关系，稳固了部落在泽风岛的影响力和外交关系。",["race:Skyborne"]="作为塑风者的领袖，Ayessa 体现了那些选择与部落团结一致以保障自身未来的天空之子的愿景。"},sec={{t="塑风者领袖",b="Ayessa Dawnsinger 驻扎在泽风岛的瓦拉纳尔定居点，作为塑风者——即效忠部落的天空之子派系——的最高向导。她在此统筹全岛的关键事务，应对外部威胁、解决内部纷争，并在天空之子于卡利姆多及其他地区寻求结盟的过程中，确保族人的生存。"},{t="泽风岛的纷争",b="Ayessa 在解决岛上的冲突中发挥了关键作用，她会派遣值得信赖的勇士去处理失控的构装体、像 Lorthuna 这样的敌对势力，以及天空之子面临的重大命运抉择。她的权威指引着塑风者度过紧张的政治与军事对抗，确保他们在部落中拥有话语权并保持其实力。"}},faq={{q="Ayessa Dawnsinger 是谁？",a="Ayessa Dawnsinger 是一位杰出的天空之子领袖，领导着在泽风岛效忠部落的天空之子派系：塑风者。",al={"ayessa 背景故事","ayessa 是谁","ayessa dawnsinger 背景"}},{q="Ayessa Dawnsinger 在哪里？",a="她位于泽风岛的瓦拉纳尔定居点。",al={"ayessa 在哪里","ayessa 位置","ayessa dawnsinger 地图"}},{q="什么是塑风者？",a="塑风者是效忠部落的天空之子派系，由 Ayessa Dawnsinger 在瓦拉纳尔基地领导。",al={"塑风者派系","什么是塑风者"}},{q="Ayessa 在当地任务中扮演什么角色？",a="Ayessa 发布了多项与岛屿防御相关的关键任务，包括调查失控的构装体、对抗 Lorthuna 以及塑造泽风岛未来的命运。",al={"ayessa 任务","ayessa 任务线"}}},fx={["53a49c44"]={q="Ayessa Dawnsinger支持哪一方？",a="Ayessa Dawnsinger坚定地支持部落。作为塑风者的领袖，她统率这支与部落结盟的天裔势力。塑风者以泽风岛上的瓦拉纳尔为据点，由她指挥行动并召集部落勇士追随她。",al={"ayessa dawnsinger所属阵营","ayessa是部落还是联盟","ayessa效忠于谁"}},e31c8ea2={q="Ayessa Dawnsinger与谁有关联？",a="Ayessa Dawnsinger与塑风者关系密切，她领导着这支由部落天裔组成的阵营。她以瓦拉纳尔为据点，协调他们的行动，并在泽风岛各地组织抵抗当地的敌人。",al={"ayessa dawnsinger的阵营关系","ayessa的关系网","ayessa与谁共事"}}},fp="17,179,25.385.0,24.356.1,25.138.0,37.61.0,25.121.0,38.174.0"}
P.entries["npc:azar-stronghammer"] = {n="阿扎尔·战锤",s="阿扎尔·战锤是一位驻扎在卡拉诺斯雷酒酿制厂的矮人圣骑士。在完成了自己的圣光之道训练后，他指导新觉醒的矮人圣光勇士，并将有前途的新兵引荐至铁炉堡接受更高级的指导。",h="阿扎尔·战锤是一位驻扎在卡拉诺斯雷酒酿制厂的矮人圣骑士。在完成了自己的圣光之道训练后，他指导新觉醒的矮人圣光勇士，并将有前途的新兵引荐至铁炉堡接受更高级的指导。",kw={"阿扎尔","酿制厂","丹莫罗","卡拉诺斯","圣骑士","战锤","雷酒","神圣之书","训练师"},ang={["class:Paladin"]="对于在丹莫罗开启旅程的矮人圣骑士来说，阿扎尔是一位至关重要的早期导师，他最终会将你引向铁炉堡，去获取神圣的《神圣之书》。",["race:Dwarf"]="阿扎尔体现了矮人对圣光的拥抱，表明了对神圣正义的奉献可以与温暖的壁炉和一杯雷酒完美融合。"},sec={{t="寒冬中的向导",b="虽然人们通常将圣骑士与人类的大教堂联系在一起，但卡兹莫丹的矮人也完全信奉圣光的美德。阿扎尔·战锤驻扎在卡拉诺斯的雷酒酿制厂，看护着那些在丹莫罗冰冷山坡上寻找立足点的新入伍矮人圣骑士。在掌握了自己的武技与灵性誓言后，他成为了一位平易近人的导师。当一名新手表现出足够的奉献精神和灵性成熟度时，阿扎尔会指引他们踏上山路，前往铁炉堡，跟随蒂萨·热炉等资深勇士学习。"}},faq={{q="阿扎尔·战锤是谁？",a="阿扎尔·战锤是一位驻扎在卡拉诺斯雷酒酿制厂的矮人圣骑士训练师。他在年轻的矮人圣光战士前往首都之前，负责监督他们的初期训练。",al={"阿扎尔是谁","阿扎尔·战锤的角色","卡拉诺斯圣骑士训练师"}},{q="在哪里可以找到阿扎尔·战锤？",a="他位于卡拉诺斯村的雷酒酿制厂内，该村坐落在丹莫罗中部雪山之中。",al={"阿扎尔·战锤的位置","阿扎尔在哪里","寻找阿扎尔·战锤"}},{q="他为年轻的圣骑士提供什么训练？",a="阿扎尔向新手教授基础的圣骑士武技与法术。一旦学徒准备好接受《神圣之书》的试炼以学习神圣的复活仪式，他就会将其指引至铁炉堡的蒂萨·热炉处。",al={"阿扎尔做什么","阿扎尔任务","圣骑士任务阿扎尔"}},{q="为什么一位圣骑士训练师会驻扎在酿制厂？",a="矮人文化将市民生活、友谊和烈酒交织在一起。雷酒酿制厂是卡拉诺斯的社交和防御中心，这使它自然而然地成为了当地保卫者和导师的聚集地。",al={"为什么圣骑士在酿制厂","酒吧里的圣骑士","酿制厂训练师"}}},fp="17,194,19.463.0,25.197.0,37.114.0,48.214.0,51.220.0"}
P.entries["npc:azuregos"] = {n="艾索雷葛斯",s="艾索雷葛斯是一条古怪的蓝龙，驻扎在艾萨拉的海岸边，保护着古代上层精灵的遗物。他受织法者玛里苟斯的重托，负责看守强大的魔法力量。他更喜欢安静的研究而非暴力，但对于任何愚蠢到打扰他守护的冒险者，他会毫不留情地将其扫除。",h="艾索雷葛斯是一条古怪的蓝龙，驻扎在艾萨拉的海岸边，保护着古代上层精灵的遗物。他受织法者玛里苟斯的重托，负责看守强大的魔法力量。他更喜欢安静的研究而非暴力，但对于任何愚蠢到打扰他守护的冒险者，他会毫不留情地将其扫除。",kw={"艾萨拉","艾索雷葛斯","风暴海湾","蓝龙","埃达拉斯","玛里苟斯","节杖碎片","流沙之战"},ang={["class:Mage"]="作为蓝龙军团的一员，艾索雷葛斯体现了对奥术的掌握与管理，他将凡人施法者视为鲁莽的孩童，正在摆弄着他们无法理解的力量。",["race:NightElf"]="艾索雷葛斯在埃达拉斯的残垣断壁间徘徊，警惕地守护着那些在大分裂时期几乎将卡利姆多撕裂的上层精灵魔法。"},sec={{t="埃达拉斯的守护者",b="由于被艾萨拉那浸透魔法的海岸所吸引，艾索雷葛斯选择了埃达拉斯的古代废墟作为他的避难所。无数遗物在大分裂中幸存下来，散落在这些破碎的海岸上。艾索雷葛斯认为，作为玛里苟斯的仆从，他有神圣的职责防止这些强大的神器落入粗心大意凡人之手。他并没有躲在阴暗的洞穴里，而是在峭壁和海滩上自由漫步，并自豪地称自己为该地区所有魔法的领主。虽然他拥有一种讽刺的幽默感，但他会为了保护艾萨拉的宝藏，猛烈反击那些为了名利而蜂拥而至的冒险者们。"},{t="不情愿的监护人",b="流沙之战后，艾索雷葛斯被指派守护蓝色节杖碎片——这是打开甲虫之墙屏障所需的一把碎片化钥匙。这条聪明的巨龙厌恶那些不断涌现、为了神器而来的冒险者和所谓的英雄，最终以一种难以想象且极其草率的方式处理了这件圣物：他把它喂给了一条名为“大嘴”的强化小鱼，确保任何想要得到这枚碎片的人都必须去深海里搜寻，而不是来骚扰他。"}},faq={{q="谁是艾索雷葛斯？",a="艾索雷葛斯是一条强大的蓝龙，受龙王玛里苟斯派遣巡视艾萨拉的废墟。虽然许多巨龙都显得严厉或愤怒，但艾索雷葛斯却显得格外古怪和机智，不过，如果凡人打扰了他的魔法研究或是觊觎埃达拉斯的宝藏，他会毫不留情地将其碾碎。",al={"艾索雷葛斯背景故事","艾萨拉的蓝龙是谁","艾索雷葛斯背景"}},{q="为什么艾索雷葛斯会在艾萨拉？",a="他来到这里是为了研究并确保大分裂后古代上层精灵文明留下的强大奥术神器安全。他守护着埃达拉斯的废墟，以防那些为了危险魔法而来的鲁莽掠夺者。",al={"为什么艾索雷葛斯在这里","艾索雷葛斯在艾萨拉做什么","艾索雷葛斯的目的"}},{q="他与甲虫之墙有什么联系？",a="艾索雷葛斯受托保管蓝色节杖碎片，这是可以重新开启甲虫之墙的钥匙的一部分。想要了解它的去向，就需要与这条巨龙谈谈。",al={"艾索雷葛斯的节杖碎片","艾索雷葛斯与流沙之战","流沙之战碎片"}},{q="为什么他的灵魂会出现在艾萨拉？",a="艾索雷葛斯之魂出现在艾萨拉那条活着的巨龙附近，并与旅行者交谈。灵魂和活着的巨龙如何同时存在，从未得到过解释。",al={"艾索雷葛斯之魂","幽灵艾索雷葛斯","为什么艾索雷葛斯是幽灵"}}},fp="8,310,24.599.0,21.501.1,16.296.0,27.217.0,42.165.1,38.160.0"}
P.entries["npc:bailiff-conacher"] = {n="拜里弗·科纳彻尔",s="拜里弗·科纳彻尔在Lakeshire Town Hall担任首席执法官，辅佐所罗门镇长。他的职责是维护民事秩序并执行当地法令，为了在饱受战火的赤脊山执行暴风城的法律，他不得不求助于那些独立的勇士。",h="拜里弗·科纳彻尔在Lakeshire Town Hall担任首席执法官，辅佐所罗门镇长。他的职责是维护民事秩序并执行当地法令，为了在饱受战火的赤脊山执行暴风城的法律，他不得不求助于那些独立的勇士。",kw={"拜里弗","科纳彻尔","湖畔镇","morganth","赤脊山","影皮豺狼人","所罗门镇长","镇政厅"},ang={["faction:Alliance"]="拜里弗·科纳彻尔代表了暴风城法律体系在这一边境小镇上脆弱的延伸，而这座小镇在很大程度上已被遗弃，只能自生自灭。"},sec={{t="湖畔镇的正义",b="在Lakeshire Town Hall内，拜里弗·科纳彻尔与所罗门镇长紧密合作，维护赤脊山的合法权威。由于小镇四面受敌，不仅有黑石兽人，还有当地的豺狼人，科纳彻尔无法依靠常规的民事程序或皇家卫队。因此，他发布法律法令，授予过往的旅人代表王国执行死刑的权力。"},{t="实施所罗门律法",b="当黑暗法师Morganth占领了伊尔加拉之塔并奴役了当地的影皮豺狼人时，湖畔镇法庭判定这些野兽犯有叛国罪。由于协助暴风王国的逃犯和罪犯会被判处死刑，科纳彻尔援引了所罗门律法。他指引冒险者们在山脊中搜寻影皮豺狼人，并要求他们上交吊坠，作为王国法律已得到执行的法律证明。"}},faq={{q="谁是拜里弗·科纳彻尔？",a="拜里弗·科纳彻尔是湖畔镇法庭的一名官员，他协助所罗门镇长在赤脊山维护民事权威和暴风城法律。",al={"拜里弗·科纳彻尔的职责","谁是科纳彻尔","科纳彻尔背景故事"}},{q="在哪里可以找到拜里弗·科纳彻尔？",a="他位于赤脊山大桥北侧的Lakeshire Town Hall内。",al={"拜里弗·科纳彻尔位置","科纳彻尔在哪里","科纳彻尔赤脊山"}},{q="什么是所罗门律法？",a="这是由所罗门镇长颁布的暴风城法律的司法应用。根据该法令，协助诸如流亡巫师Morganth等已知罪犯的行为将被判处死刑，这意味着与他结盟的影皮豺狼人被合法列为处决目标。",al={"什么是所罗门律法","所罗门律法豺狼人","影皮豺狼人法律"}},{q="为什么科纳彻尔要求收集影皮吊坠？",a="吊坠作为可核实的证据，证明了影皮豺狼人因协助Morganth而受到湖畔镇法律制裁并已被击杀。",al={"为什么要收集吊坠","影皮吊坠用途"}}},fx={["6ce891cc"]={q="拜里弗·科纳彻尔支持哪一方？",a="拜里弗·科纳彻尔为联盟效力，直接听命于湖畔镇的所罗门镇长。作为赤脊山法庭的官员，他的职责是维护暴风城的法律，并保护当地居民免受日益逼近的威胁。",al={"科纳彻尔效忠于谁","科纳彻尔为谁效力","科纳彻尔是否属于联盟"}},["5d999432"]={q="拜里弗·科纳彻尔想要什么？",a="科纳彻尔致力于维护湖畔镇的法律并保护赤脊山。叛逃法师摩根特招募了当地的暗皮豺狼人，治安官于是招募有本领的冒险者惩治这些豺狼人，并遏制黑暗法师的势力。",al={"科纳彻尔的目标","拜里弗·科纳彻尔需要什么"}},["8124ae86"]={q="拜里弗·科纳彻尔为什么在湖畔镇？",a="科纳彻尔驻扎在湖畔镇市政厅，担任镇上的治安官。他与所罗门镇长并肩工作，协助处理地方事务、维护公正，并在暴风城无力派遣援军支援此地时管理城镇防务。",al={"科纳彻尔为什么在赤脊山","科纳彻尔与湖畔镇市政厅"}},df8ac9aa={q="拜里弗·科纳彻尔与谁有关联？",a="科纳彻尔是湖畔镇法庭的一员，直接听命于所罗门镇长。他与镇上的官员和当地卫兵密切合作，抵御外来侵略者，维护聚居地的秩序。",al={"科纳彻尔的盟友","科纳彻尔与谁共事"}}},fp="16,183,20.353.0,22.417.0,24.143.0,36.116.0,22.210.0,46.121.0"}
P.entries["npc:bailor-stonehand"] = {n="白洛尔·石手",s="白洛尔·石手是一位居住在洛克莫丹塞尔萨玛的矮人铁匠。他以冶金技艺精湛而闻名，曾指导过人类武器匠乔丹·斯迪威尔，并能提炼出制造杰出武器所需的特殊合金。目前，由于当地的莫格罗什食人魔伏击并抢走了他的矿石补给，他的锻造工作陷入了困境。",h="白洛尔·石手是一位居住在洛克莫丹塞尔萨玛的矮人铁匠。他以冶金技艺精湛而闻名，曾指导过人类武器匠乔丹·斯迪威尔，并能提炼出制造杰出武器所需的特殊合金。目前，由于当地的莫格罗什食人魔伏击并抢走了他的矿石补给，他的锻造工作陷入...",kw={"白洛尔·石手","乔丹·斯迪威尔","洛克莫丹","莫格罗什","铁匠","塞尔萨玛","维里甘之拳"},ang={["class:Paladin"]="寻求锻造传奇武器维里甘之拳的圣骑士们会追随白洛尔的足迹，因为正是他将特殊合金的配方直接传授给了乔丹·斯迪威尔，以供制作这把神圣的战锤。",["profession:Blacksmithing"]="作为一位冶金大师，他的特殊合金在卡兹莫丹享有盛誉，白洛尔体现了矮人对追求完美、稀有且坚韧金属的传统精神。"},sec={{t="锻造大师",b="白洛尔·石手在矮人定居点塞尔萨玛工作，代表了洛克莫丹铁匠们经久不衰的技艺。他以对原始矿石的敏锐眼光和提炼特殊合金的能力而闻名，他的知识领域甚至超出了卡兹莫丹。他曾担任著名人类铁匠乔丹·斯迪威尔的导师，传授给他冶金的基础艺术，并分享了后来在锻造维里甘之拳等圣洁圣骑士武器时不可或缺的配方。"},{t="食人魔伏击",b="尽管白洛尔拥有炉火纯青的技艺，但他的贸易也无法免受洛克莫丹日益严重的威胁。原本运往他锻造铺的高等级矿石在东北部山丘被盘踞在那里的莫格罗什食人魔劫掠一空。由于缺乏原材料，白洛尔无法制作他那些稀有的合金，只能寄希望于路过的旅行者和盟友从粗暴的营地中找回被偷走的Stolen Supplies。"}},faq={{q="谁是白洛尔·石手？",a="白洛尔·石手是一位位于洛克莫丹塞尔萨玛的矮人铁匠老兵。他以提炼稀有金属合金，以及过去曾教导乔丹·斯迪威尔武器锻造工艺而闻名。",al={"白洛尔·石手","谁是白洛尔","塞尔萨玛铁匠"}},{q="白洛尔和乔丹·斯迪威尔有什么关系？",a="白洛尔曾是乔丹·斯迪威尔的老师，乔丹是一位在铁炉堡附近工作的人类铁匠。斯迪威尔将传授他精炼矿石的秘诀归功于白洛尔，特别是用于制造神圣战锤维里甘之拳的那种特殊合金。",al={"白洛尔与乔丹","乔丹·斯迪威尔的老师","维里甘之拳铁匠"}},{q="白洛尔的矿石发生了什么事？",a="白洛尔的一批原始矿石在洛克莫丹东北部山区被居住在那里的莫格罗什食人魔拦截并抢走，导致他无法获得进行特殊冶金所需的材料。",al={"白洛尔的矿石补给","谁偷了白洛尔的矿石","食人魔补给"}},{q="在哪里可以找到白洛尔·石手？",a="白洛尔可以在塞尔萨玛的中心地带找到，这是洛克莫丹主干道上主要的矮人城镇。",al={"白洛尔位置","白洛尔·石手在哪里","白洛尔塞尔萨玛"}}},fp="16,212,19.252.0,11.237.0,24.153.0,47.164.0,30.150.0,36.101.0"}
P.entries["npc:baine-bloodhoof"] = {n="贝恩·血蹄",s="贝恩·血蹄是大酋长凯恩·血蹄之子，也是莫高雷血蹄村的代理守护者。当他的父亲在雷霆崖高耸的巅峰之上统领各部族时，贝恩直接负责当地的防御工作，调查日益严重的工业开采，并抵御凶猛掠食者的侵扰。他不仅是牛头人年轻勇士与部落先祖智慧之间不可或缺的桥梁，更承担着守护族人的重任。",h="贝恩·血蹄是大酋长凯恩·血蹄之子，也是莫高雷血蹄村的代理守护者。当他的父亲在雷霆崖高耸的巅峰之上统领各部族时，贝恩直接负责当地的防御工作，调查日益严重的工业开采，并抵御凶猛掠食者的侵扰。他不仅是牛头人年轻勇士与部落先祖智...",kw={"贝恩","血蹄","血蹄村","凯恩","半人马","克里格","莫高雷","苍鬃豺狼人","雷克萨","雷霆崖"},ang={["class:Shaman"]="贝恩将精神看得高于一切，他派遣旅者去让矮人的机器和鲁莽的矿工停下来，以免他们的挖掘进一步伤害大地的灵魂。",["faction:Horde"]="贝恩体现了沉稳的智慧和安静的武力，这让牛头人在萨尔的部落中得以扎根，并为路过莫高雷中部的旅者提供指引。",["race:Tauren"]="贝恩既代表了大酋长凯恩尊贵的血统，也代表了在莫高雷平原上汇聚的年轻部族的勃勃生机。"},sec={{t="大酋长之子",b="贝恩出生于凯恩麾下，在牛头人定居莫高雷肥沃的草原之前，他一直跟随游牧的族人四处奔波。他早年的生活时刻笼罩在半人马部族的威胁之下。第三次战争结束后不久，半人马战团首领克里格俘虏了年幼的贝恩，这让凯恩陷入了极度悲痛之中，甚至险些让刚刚建立的定居点分崩离析。多亏了勇士雷克萨的英勇，贝恩才得以从囚禁中获救。这次营救重燃了凯恩的斗志，使牛头人得以与萨尔的部落并肩作战，抵御库尔提拉斯人的入侵，并在大陆上稳固了自己的立足之地。"},{t="血蹄村守护者",b="贝恩没有选择留在舒适的首都台地上，而是选择与族人一同住在血蹄村。随着凯恩年事渐高，贝恩承担起了愈发繁重的管理职责，代表着牛头人领导层的下一代。他指挥勇士和来访的盟友对抗骚扰边境的苍鬃豺狼人，并密切关注着威胁莫高雷自然平衡的可疑外部势力。"},{t="保卫大地母亲",b="除了边境的领土冲突外，贝恩还面临着不顾精神平衡、只知掠夺的现代入侵者。在东部，荆棘谷地精正在深挖圣地，而来自巴尔莫丹的矮人勘探员则在巴尔丹挖掘场开凿先祖的土地。贝恩主张采取坚定而适度的回应：试图警告矿工并摧毁他们破坏性的设备，而不是贸然陷入无谓的流血冲突。他警告说，矮人的暴力挖掘正在伤害大地的灵魂，但矿工们拒绝听从。"}},faq={{q="贝恩·血蹄是谁？",a="贝恩是牛头人部族大酋长凯恩·血蹄的独子。他负责管理血蹄村的防御和部族事务，在父亲于雷霆崖进行统治的同时，他挺身而出，指挥当地勇士并保护莫高雷。",al={"贝恩背景故事","贝恩是谁","凯恩之子"}},{q="贝恩现在在哪里？",a="贝恩位于莫高雷中部的血蹄村，雷霆崖正南。他通常在镇中心附近为刚抵达的冒险者安排任务。",al={"贝恩位置","贝恩在哪里","贝恩·血蹄地点"}},{q="贝恩是如何从半人马手中获救的？",a="第三次战争后，半人马领袖克里格俘虏了贝恩，使凯恩陷入了极度的绝望。兽王雷克萨找到了波凡·风图腾的流亡者，追踪半人马至其营地，击杀了俘虏者，并将贝恩安全地带回他父亲身边。",al={"贝恩被绑架","雷克萨拯救贝恩","贝恩被俘"}},{q="贝恩在血蹄村处理什么问题？",a="贝恩统筹应对骚扰当地畜群的侵略性苍鬃豺狼人，并密切关注外国入侵者，例如荆棘谷地精和破坏大地的联盟矮人挖掘者。",al={"贝恩任务","贝恩做什么","血蹄村危机"}},{q="贝恩对巴尔丹矮人挖掘场持什么立场？",a="贝恩认为巴尔丹矿工的暴力挖掘伤害了大地的灵魂，玷污了土地。他派遣旅者去夺取并砸毁他们的工具，希望以此吓退他们，并让他们明白挖空大地并非寻求知识的正途。",al={"贝恩矮人","巴尔丹采矿","莫高雷矮人挖掘场"}},{q="贝恩会继任凯恩成为大酋长吗？",a="作为凯恩之子，随着父亲年岁增长，贝恩在领导牛头人方面发挥的作用逐年增加，人们普遍视他为统一部族名正言顺的继承人。",al={"贝恩会成为领袖吗","未来大酋长","凯恩继承人"}}},fp="15,171,25.470.0,29.373.0,26.453.0,23.199.0,35.150.0,39.242.0,53.198.0,55.252.0,44.149.0"}
P.entries["npc:balir-frosthammer"] = {n="巴尔林·霜锤",s="巴尔林·霜锤是一位驻守在丹莫罗寒脊山谷的矮人守卫。由于岩颚穴居人突然对矮人领地发起了激进的入侵，他感到十分警惕，并招募初出茅庐的冒险者在山谷被攻陷前阻止这场浪潮。",h="巴尔林·霜锤是一位驻守在丹莫罗寒脊山谷的矮人守卫。由于岩颚穴居人突然对矮人领地发起了激进的入侵，他感到十分警惕，并招募初出茅庐的冒险者在山谷被攻陷前阻止这场浪潮。",kw={"新的威胁","巴尔林·霜锤","寒脊山谷","丹莫罗","岩颚穴居人","塔诺克·霜锤"},ang={["faction:Alliance"]="巴尔林的努力确保了寒脊山谷作为联盟新兵在卡兹莫丹开始训练的重要集结地时的安全。",["race:Dwarf"]="对于年轻的矮人来说，巴尔林·霜锤代表着保卫家园的第一道防线，为他们提供了守护丹莫罗免受地下威胁的最初机会。"},sec={{t="守卫寒脊山谷",b="巴尔林·霜锤栖身于寒脊山谷的雪地营地中，时刻警惕着外围不断逼近的危险。长期以来，这座山谷一直是矮人和侏儒新兵的安全避风港与训练场，但近期地下的动荡将狂暴的岩颚穴居人推向了地表。巴尔林是第一批发出警报的人之一，他号召新到的招募者去消灭穴居人，防止他们进一步深入丹莫罗。"},{t="霜锤氏族的族人",b="身为自豪的霜锤族人，巴尔林可能与卡拉诺斯的塔诺克·霜锤有着血缘关系。他们的家族坚定地履行着对铁炉堡的职责，确保寒冷的山口能让旅行者、矿工和登山者安全通行，尽管区域性的威胁正在不断增加。"}},faq={{q="巴尔林·霜锤是谁？",a="巴尔林·霜锤是一名驻守在丹莫罗寒脊山谷的矮人。他委派初来乍到的冒险者去清理威胁山谷防御的敌对岩颚穴居人。",al={"巴尔林·霜锤是谁","巴尔林是谁"}},{q="为什么巴尔林会对穴居人感到担忧？",a="岩颚穴居人最近大举出现在地表，扰乱了寒脊山谷的安宁，并袭击了矮人定居点。巴尔林意识到这是一个必须尽早遏制的升级威胁。",al={"为什么会有穴居人","寒脊山谷的穴居人问题"}},{q="巴尔林与塔诺克·霜锤有亲戚关系吗？",a="有可能。巴尔林与卡拉诺斯的塔诺克·霜锤拥有同样的霜锤姓氏，暗示他们之间可能存在亲缘关系，尽管尚未得到证实。",al={"塔诺克是亲戚吗","霜锤家族"}}},fp="17,99,24.334.0,23.263.0,25.156.0,40.168.0,39.142.0"}
P.entries["npc:balthule-shadowstrike"] = {n="巴苏尔·影击",s="巴苏尔·影击是一位驻扎在黑海岸北部，奥萨拉克斯之塔附近的暗夜精灵斥候。作为净化者德尔格伦的前线代理人，他时刻监视着占据这些古老精灵废墟的邪恶教徒和黑暗施法者。沿着北海岸旅行的冒险者经常被指引去寻找他，以协助揭露并破坏在塔内进行的黑暗仪式。",h="巴苏尔·影击是一位驻扎在黑海岸北部，奥萨拉克斯之塔附近的暗夜精灵斥候。作为净化者德尔格伦的前线代理人，他时刻监视着占据这些古老精灵废墟的邪恶教徒和黑暗施法者。沿着北海岸旅行的冒险者经常被指引去寻找他，以协助揭露并破坏在塔...",kw={"奥萨拉克斯之塔","巴苏尔","教徒","黑海岸","德尔格伦","迈斯特拉","净化者","斥候","影击"},ang={["class:Rogue"]="巴苏尔在危险的施法者眼皮底下深入敌后作战，展现了一名真正精灵斥候的耐心与警觉。",["faction:Alliance"]="巴苏尔是联盟成员的重要前线联络人，从奥伯丁被派往北方的成员都会找他，以铲除在奥萨拉克斯之塔周围活动的黑暗教徒。",["race:NightElf"]="对于暗夜精灵来说，古老的卡利姆多废墟被邪恶教徒亵渎是一种暴行，巴苏尔试图在腐化进一步蔓延到他们的领土之前实施报复。"},sec={{t="阴影中的斥候",b="巴苏尔·影击在奥萨拉克斯之塔以西的荒野中坚守着一个孤独而危险的哨位。黑海岸的北部地区到处都是不安的灵魂和阴暗的废墟，但塔周边的活动构成了尤为严峻的威胁。巴苏尔在净化者德尔格伦的指挥下行动，观察着那些潜入古老上层精灵遗迹的黑暗施法者的动向。"},{t="揭露邪教",b="占据奥萨拉克斯之塔的术士和教徒们正在进行黑暗且禁忌的魔法实验，从周边的废墟中搜刮文物与灵魂。巴苏尔依靠路过的联盟勇士深入塔区，击溃邪教徒的首领，并找回那些揭示其召唤阴谋真正规模的羊皮纸与护身符。"}},faq={{q="巴苏尔·影击是谁？",a="巴苏尔·影击是一位驻扎在黑海岸北部的暗夜精灵斥候。他作为一名先遣斥候和代理人，与净化者德尔格伦协同工作，监视该地区的邪恶教徒活动。",al={"巴苏尔是谁","巴苏尔的职责","巴苏尔·影击 npc"}},{q="巴苏尔·影击在哪里？",a="他驻扎在黑海岸北部，位置就在阴森的奥萨拉克斯之塔以西，靠近海岸线的地方。",al={"巴苏尔在哪里","巴苏尔位置","寻找巴苏尔·影击"}},{q="他在奥萨拉克斯之塔的任务是什么？",a="他被派去监视那些在奥萨拉克斯之塔安营扎寨的黑暗施法者和教徒，帮助收集情报并协调突袭，以破坏他们腐化的仪式。",al={"巴苏尔为什么在这里","巴苏尔想要什么","奥萨拉克斯之塔任务发布者"}},{q="谁是净化者德尔格伦？",a="净化者德尔格伦是一位驻扎在灰谷迈斯特拉岗哨的人类圣骑士，他负责协调针对肆虐黑海岸北部的黑暗势力的行动。巴苏尔正是他的前线耳目。",al={"谁是德尔格伦","巴苏尔的上级","德尔格伦的联系"}},{q="奥萨拉克斯之塔里有哪些敌人？",a="这座塔及其周边区域遍布黑暗教徒、术士以及被召唤出来的恶魔或阴影爪牙，他们一心想要利用古老的上层精灵力量来达成邪恶的目的。",al={"塔里有什么人","奥萨拉克斯之塔的敌人","奥萨拉克斯之塔的教徒"}},{q="联盟为什么要关注这些废墟？",a="奥萨拉克斯之塔是一座古老的精灵建筑。在靠近精灵领土的地方出现邪恶巫术和恶魔活动，直接威胁到了黑海岸和达纳苏斯暗夜精灵的安全。",al={"为什么要关注这座塔","联盟在黑海岸的驻军"}}},fp="21,207,22.310.0,19.294.1,29.113.0,39.103.0,46.160.0,28.190.0,51.182.0,46.160.0"}
P.entries["npc:barithras-moonshade"] = {n="巴瑞萨斯·月影",s="巴瑞萨斯·月影是一位居住在黑海岸奥伯丁的暗夜精灵。他身处这座沿海定居点内，正寻求冒险者的帮助，探索阴影笼罩的荒野并采集稀有的地下植物。",h="巴瑞萨斯·月影是一位居住在黑海岸奥伯丁的暗夜精灵。他身处这座沿海定居点内，正寻求冒险者的帮助，探索阴影笼罩的荒野并采集稀有的地下植物。",kw={"奥伯丁","巴瑞萨斯","洞穴蘑菇","黑海岸","毒帽蘑菇","月影","奥努"},ang={["profession:Herbalism"]="那些对植物生命有感知的人会赞赏巴瑞萨斯对黑海岸奇特洞穴真菌的兴趣。",["race:NightElf"]="巴瑞萨斯通过监测植物并与像奥努这样的森林古树守护者保持联系，帮助他在奥伯丁的族人守护黑海岸。"},sec={{t="奥伯丁的居民",b="巴瑞萨斯·月影在奥伯丁村中守望，协助暗夜精灵研究和管理黑海岸动荡的土地。他指引旅行者前往附近的地下洞穴采集特定的真菌，例如毒帽蘑菇，以供研究和使用。"},{t="与古树的联系",b="除了当地的植物，巴瑞萨斯还负责引导有能力的冒险者向南进发，与奥努取得联系。奥努是一位受人尊敬的古树，致力于治愈黑海岸被腐蚀的土壤，并安抚那里焦躁不安的自然之灵。"}},faq={{q="巴瑞萨斯·月影是谁？",a="巴瑞萨斯·月影是一位居住在黑海岸多雾海岸奥伯丁的暗夜精灵。他会委托冒险者调查当地植物并与该地区的守护者进行接触。",al={"巴瑞萨斯是谁","巴瑞萨斯·月影","这个暗夜精灵是谁"}},{q="我在哪里可以找到巴瑞萨斯·月影？",a="他位于黑海岸海岸线上的奥伯丁港口定居点。",al={"巴瑞萨斯位置","巴瑞萨斯在哪里","巴瑞萨斯·月影位置"}},{q="巴瑞萨斯会提供什么任务？",a="巴瑞萨斯会委托旅行者进入附近的洞穴采集蘑菇，例如危险的毒帽蘑菇，随后会指引冒险者前往南方与古树奥努会面。",al={"巴瑞萨斯的任务","巴瑞萨斯提供什么任务","洞穴蘑菇任务"}},{q="巴瑞萨斯和其他月影家族成员有关联吗？",a="没有关于巴瑞萨斯亲属的记录，因此他与其他拥有月影姓氏的暗夜精灵之间的联系尚不明确。",al={"月影家族","其他月影","巴瑞萨斯和哨兵月影有关联吗"}}},fp="19,178,21.202.0,20.150.0,27.131.0,37.88.0,31.126.0,45.99.0"}
P.entries["npc:barkeep-daniels"] = {n="酒吧老板丹尼尔",s="酒吧老板丹尼尔守在Lakeshire Inn的柜台后，招待着疲惫的城镇守卫、当地渔民和来访的旅客。由于黑石氏族在赤脊山各处进行劫掠并切断了补给路线，让酒馆库存充足已经成为了一场艰苦的战斗。",h="酒吧老板丹尼尔守在Lakeshire Inn的柜台后，招待着疲惫的城镇守卫、当地渔民和来访的旅客。由于黑石氏族在赤脊山各处进行劫掠并切断了补给路线，让酒馆库存充足已经成为了一场艰苦的战斗。",kw={"酒吧老板丹尼尔","调酒师","丹尼尔","干旱时刻","lakeshire inn","赤脊山旅店老板"},ang={["faction:Alliance"]="在湖畔镇维持士气对联盟至关重要，因为该定居点是王国对抗北部黑石要塞受损严重的缓冲地带。"},sec={{t="保持湖畔镇的高昂士气",b="Lakeshire Inn的柜台后站着酒吧老板丹尼尔，他忙着斟酒，招呼着从桥那边走进来的每一个人。湖畔镇已经在豺狼人和黑石兽人的持续压力下度过了数月，镇上的守卫们依靠酒馆在残酷的巡逻后放松身心。对丹尼尔来说，不幸的是，被切断的道路和不断的袭击扰乱了整个地区的贸易。在镇上最需要欢乐的时候，他却发现酒水库存告急，因此他急切地希望有路过的冒险者愿意从更安全的定居点取回货物。"}},faq={{q="谁是酒吧老板丹尼尔？",a="酒吧老板丹尼尔是一位在Lakeshire Inn柜台工作的人类酒馆老板。他负责处理当地镇民、旅行冒险者和饱受困扰的城镇守卫的酒水订单。",al={"丹尼尔 赤脊山","湖畔镇 酒吧老板","谁是丹尼尔"}},{q="为什么他的酒水短缺？",a="黑石兽人和邻近豺狼人部落持续不断的突袭，切断了进入赤脊山的补给商队和贸易路线。由于补给中断，而压力巨大的守卫们又消耗了现有的库存，丹尼尔正努力维持酒馆的供应。",al={"为什么没酒了","干旱时刻 任务背景","为什么没有酒精饮料"}},{q="他需要什么帮助？",a="通过任务“干旱时刻”，丹尼尔寻求愿意冒险的旅行者前往赤脊山外带回新鲜的酒水补给，以让酒馆的顾客满意。",al={"酒吧老板丹尼尔 任务","他想要什么","丹尼尔的差事"}}},fx={["2f43c9bf"]={q="酒吧老板丹尼尔站在哪一方？",a="酒吧老板丹尼尔是忠诚的联盟公民，也是湖畔镇的一员。他在湖畔镇旅店柜台后为当地居民、访客和驻防守军服务；面对日益严重的黑石威胁，他坚定地支持暴风王国。",al={"酒吧老板丹尼尔的阵营","酒吧老板丹尼尔是联盟成员吗","丹尼尔在赤脊山效忠于谁"}}},fp="15,216,33.415.0,23.115.0,32.218.0,28.108.0"}
P.entries["npc:baron-aquanis"] = {n="阿奎尼斯男爵",s="阿奎尼斯男爵是盘踞在黑暗深渊中被淹没的Moonshrine Ruins里的一位强大的水元素，暮光之锤已在那里筑起了巢穴。当有人触动了遗迹中的深渊之石时，他就会从深水中升起。大地之环的萨满祭司长期以来一直认为他是一种受到腐蚀的元素力量，并怀疑是该教派在幕后操纵。",h="阿奎尼斯男爵是盘踞在黑暗深渊中被淹没的Moonshrine...",kw={"阿奎尼斯男爵","黑暗深渊","大地之环","深渊之核","深渊之石","耶努萨克雷","moonshrine ruins","暮光之锤","水元素"},ang={["class:Shaman"]="对于大地之环的萨满祭司来说，阿奎尼斯男爵是一个元素被扭曲的悲剧例子，他那受到污染的遗骸为净化扭曲的灵魂提供了关键的见解。",["faction:Horde"]="耶努萨克雷在灰谷海岸与部落合作，而他的部落帮手取回的深渊之核旨在揭示暮光之锤在那里对元素做了什么。"},sec={{t="深渊之石的守护者",b="深渊之石沉没在Moonshrine Ruins被淹没的大厅之下，就位于现在占据该遗迹的暮光之锤教徒的眼皮底下。其中包含了一个深渊之核，这是一种设备，如果读取得当，可以揭示其周围所有元素活动的过往。大地之环的耶努萨克雷派遣部落冒险者去取回这个核心，而触动深渊之石会将阿奎尼斯男爵从深渊中引出。"},{t="深渊的腐蚀",b="大地之环长期以来一直认为阿奎尼斯男爵是一种受到腐蚀的元素力量。当他被消灭时，他会留下一个奇怪的水球：一个无法穿透的球体，里面装着腐臭、晃动的水，似乎这些水为他提供了能量。耶努萨克雷相信这个水球能证明究竟是什么腐蚀了男爵，以及腐蚀是如何发生的。如果结果证明是暮光之锤所为，他一点也不会感到惊讶。"}},faq={{q="我在哪里可以找到阿奎尼斯男爵？",a="阿奎尼斯男爵居住在黑暗深渊深处被淹没的Moonshrine Ruins中。他不会在大厅里游荡：当遗迹水下的深渊之石被触动时，他就会从水中升起，而部落冒险者在为耶努萨克雷取回深渊之核时就会触发这一点。",al={"阿奎尼斯男爵位置","阿奎尼斯男爵在哪里","如何召唤阿奎尼斯男爵"}},{q="奇怪的水球是什么？",a="奇怪的水球是阿奎尼斯男爵被消灭后留下的东西：一个没有任何物理力量可以打破的球体，里面装着腐臭晃动的水。它似乎为该元素提供了能量。大地之环的耶努萨克雷想要研究它，相信它能证明究竟是什么腐蚀了男爵，以及它是如何做到的。",al={"奇怪的水球","阿奎尼斯男爵水球","奇怪的水球有什么用"}},{q="为什么大地之环对阿奎尼斯男爵感兴趣？",a="大地之环守护着元素的平衡。耶努萨克雷和他的同志们长期以来一直认为阿奎尼斯男爵是一种受到腐蚀的元素力量，现在暮光之锤占据了Moonshrine Ruins，他们担心该教派正在胁迫这些元素去对抗部落。男爵的遗骸和遗迹中的深渊之核可能会向他们揭示该教派的阴谋。",al={"为什么大地之环关注此事","耶努萨克雷 阿奎尼斯男爵"}},{q="深渊之核是什么？",a="深渊之核是一件存放于沉没的深渊之石内的元素神器。如果由受过训练的萨满祭司正确读取，它能揭示该地区元素活动的完整历史，从而揭露暮光之锤在遗迹中进行的任何黑暗仪式。",al={"深渊之核背景故事","深渊之核有什么作用"}},{q="阿奎尼斯男爵是暮光之锤的盟友吗？",a="就目前所知，并非出于他自己的意愿。大地之环认为他是一个受到腐蚀的元素，而不是一个心甘情愿的仆从，而占据Moonshrine Ruins的暮光之锤教徒是显而易见的嫌疑人。耶努萨克雷表示，如果真的是他们所为，他一点也不会感到惊讶，但他想在下定论之前找到证据。",al={"阿奎尼斯男爵是暮光之锤的吗","阿奎尼斯男爵 教派"}},{q="联盟与阿奎尼斯男爵有关联吗？",a="没有直接关联。深渊之石，以及随之而来的阿奎尼斯男爵，都是耶努萨克雷关心的问题：他是一位在大地之环效力并与灰谷海岸的部落合作的萨满祭司，而他派遣去取回深渊之核的是部落冒险者。在黑暗深渊中的联盟探险者在那里有其他任务。",al={"联盟可以挑战阿奎尼斯男爵吗","联盟阿奎尼斯男爵任务"}}},fp="13,237,28.401.0,24.376.1,31.235.0,32.274.0,52.356.0,24.267.0,51.289.0,51.277.0"}
P.entries["npc:baron-revilgaz"] = {n="大财主里维加兹",s="大财主里维加兹是藏宝海湾和黑水掠夺者的狡猾地精领袖，他代表热砂港统治着这个海盗避风港。他盘踞在Salty Sailor Tavern高处的阳台上，在脆弱的贸易中立与冷酷务实的机会主义之间寻找平衡。他雇佣过往的雇佣兵来保障他的投资安全，削弱像血帆海盗这样的竞争对手，并寻回古老的丛林遗物。",h="大财主里维加兹是藏宝海湾和黑水掠夺者的狡猾地精领袖，他代表热砂港统治着这个海盗避风港。他盘踞在Salty Sailor...",kw={"黑水掠夺者","血帆海盗","藏宝海湾","纳菲瑞提湖","里维加兹","salty sailor tavern","卡拉·海角","热砂港","海潮之石"},ang={["class:Rogue"]="里维加兹尊重小偷、间谍和机会主义者。他经常雇佣潜行者进行高风险的盗窃、对竞争财团的破坏活动，以及秘密找回稀有的丛林人工制品。",["faction:Alliance"]="藏宝海湾坐落在第一次战争前暴风城黑水湾飞地的废墟之上，当古代传说能转化为利润时，里维加兹会定期与暴风城的人类学者和图书馆员进行协调。",["profession:Engineering"]="里维加兹参与了地精工程学的竞争，利用卑劣的手段从荆棘谷地精那里获取先进的蓝图和燃料调节器。"},sec={{t="藏宝海湾的主宰",b="从Salty Sailor Tavern顶端的有利位置，大财主里维加兹透过一个定制的附魔望远镜注视着黑水湾繁忙的码头。在他的信任顾问、舰队指挥官卡拉·海角的协助下，里维加兹牢牢控制着城里的扒手、商人和私掠者。这里最初是一个在第一次战争前被巨魔占领的人类定居点，后来被地精夺取并加固，最终演变成了黑水掠夺者倾向海盗的商业枢纽。里维加兹确保港口对联盟和部落的旅行者正式开放，并在港口范围内严格执行中立政策，从而使贸易得以不间断地进行。"},{t="野心的网络",b="里维加兹的影响力早已超出了港口码头的范围。当艾泽拉斯其他地区经历近期的战争导致贸易停滞时，他敏锐地发现了美味风蛇的商业价值，从而创办了荆棘谷钓鱼大赛，将人群重新吸引到他的海岸。在整个荆棘谷，他密切注视着竞争对手和潜在威胁：他策划对纳菲瑞提湖的荆棘谷地精进行破坏活动，密切监视奈辛瓦里狩猎探险队以及北部的流氓人类军营，并与沙漠赛道的Monte Gazlowe和普兹克保持着赛车贸易往来。"},{t="海潮之石",b="在里维加兹的商人外表之下，隐藏着他对古代力量和财富的执着。在调查海岸附近一个闹鬼岛屿的传言后，里维加兹派遣冒险者去发掘传说中的海潮之石。这次搜寻需要查阅暴风城图书馆的古籍，与大法师安斯雷姆·鲁因维沃尔一起研究元素残留，并从血帆海盗手中夺回一把古代巨魔匕首，以击碎守护海潮之石的沿海祭坛。通过这样做，里维加兹打破了一个致命的元素诅咒，将这件无价的遗物收入囊中。"}},faq={{q="大财主里维加兹是谁？",a="大财主里维加兹是藏宝海湾的统治者和黑水掠夺者的领袖。他代表中立的热砂港行事，以一种冷酷的贪婪和外交实用主义相结合的方式管理着这个海盗避风港。",al={"谁是里维加兹","里维加兹背景故事","藏宝海湾首领","藏宝海湾领袖"}},{q="在哪里可以找到大财主里维加兹？",a="他站在藏宝海湾Salty Sailor Tavern的顶部阳台上，与他信任的顾问舰队指挥官卡拉·海角一起俯瞰海湾。",al={"里维加兹在哪里","里维加兹位置","如何找到里维加兹"}},{q="里维加兹与血帆海盗的关系如何？",a="他们是死敌。血帆海盗在热砂港的规则之外行事，并积极劫掠藏宝海湾的航运。事实上，血帆海盗的领导层经常策划针对里维加兹和舰队指挥官卡拉·海角的暗杀行动。",al={"里维加兹血帆海盗","血帆海盗与里维加兹","为何憎恨血帆海盗"}},{q="里维加兹在沙漠赛道中有什么利益？",a="里维加兹赞助了由普兹克领导的地精赛车队，以对抗闪光平原的侏儒。他利用冒险者从纳菲瑞提湖的荆棘谷地精那里窃取专有的燃料调节器的蓝图，并将它们送到赛道。",al={"里维加兹赛车","里维加兹闪光平原","里维加兹普兹克"}},{q="什么是荆棘谷钓鱼大赛？",a="当由于艾泽拉斯其他地区的区域性战争导致贸易下滑时，里维加兹在品尝了当地的“美味风蛇”后，支持了一位名叫Riggle Bassbait的钓鱼爱好者。里维加兹将捕鱼活动变成了一场沿着荆棘谷海岸进行的每周一次的竞技比赛，以振兴藏宝海湾的经济。",al={"钓鱼大赛背景","谁发起了钓鱼比赛","美味风蛇里维加兹"}},{q="什么是海潮之石？",a="它是一块隐藏在暗礁海的古代受诅咒的魔法石。里维加兹通过暴风城的记录发掘了它的传说，并雇用达拉然学者大法师安斯雷姆·鲁因维沃尔来帮助冒险者拆除其元素结界并夺取该遗物。",al={"海潮之石任务","暗礁海之石","海潮祭坛"}}},fp="14,425,19.682.0,17.589.0,22.572.1,22.222.0,34.143.0,62.231.0,47.242.0,47.274.0,31.245.1"}
P.entries["npc:baron-silverlaine"] = {n="席瓦莱恩男爵",s="席瓦莱恩男爵曾是这座堡垒名正言顺的人类领主，它过去被称为席瓦莱恩城堡，高踞于焚木村之上。当大法师阿鲁高将野蛮的狼人释放到该地区时，男爵被无情地屠杀了。现在，他那饱受折磨的灵魂徘徊在破败的宴会大厅中，被困在亡灵状态下，守护着这处成为了他坟墓的巢穴。",h="席瓦莱恩男爵曾是这座堡垒名正言顺的人类领主，它过去被称为席瓦莱恩城堡，高踞于焚木村之上。当大法师阿鲁高将野蛮的狼人释放到该地区时，男爵被无情地屠杀了。现在，他那饱受折磨的灵魂徘徊在破败的宴会大厅中，被困在亡灵状态下，守护...",kw={"阿鲁高","男爵","幽灵","大厅","城堡","焚木村","影牙","席瓦莱恩","狼人"},ang={["class:Mage"]="席瓦莱恩的命运为魔法的鲁莽行径敲响了警钟；召唤术如果像大法师阿鲁高那样被滥用，将会摧毁无辜的生命并留下不可磨灭的伤痕。",["race:Human"]="席瓦莱恩是一个痛苦的见证，象征着吉尔尼斯边境人类贵族统治的衰落，他的城堡被一位受过达拉然训练的法师的魔法傲慢所践踏。",["race:Undead"]="对于在银松森林推进的被遗忘者来说，席瓦莱恩的幽灵不过是旧贵族阶级的残余，必须将其清除，以打破阿鲁高对这座城堡的控制。"},sec={{t="席瓦莱恩城堡的陷落",b="在狼群怪兽的阴影笼罩银松森林南部山丘之前，席瓦莱恩男爵统治着一片令人自豪的贵族领地。他的堡垒为周边地区提供了安全保障和监管。当大法师阿鲁高为了寻找对抗肆虐的天灾军团的武器，将召唤出的狼人释放到该地区时，这份平静便破碎了。这些野性的怪物无法被控制；它们冲入要塞，击溃了守卫，并屠杀了男爵。"},{t="饱受折磨的幽灵",b="死亡并没有给席瓦莱恩男爵带来解脱。他的灵魂被禁锢在城堡古老的大厅中，四处游荡，徘徊在他曾经宴饮过的破烂餐桌旁。这位受诅咒的领主攻击着任何进入他废墟家园的入侵者。"}},faq={{q="席瓦莱恩男爵是谁？",a="他是最初被称为席瓦莱恩城堡的堡垒的贵族人类主人，位于焚木村上方。当狼人占领这座堡垒时，他被杀害了。",al={"席瓦莱恩男爵背景故事","谁是席瓦莱恩","谁统治影牙城堡"}},{q="为什么他在影牙城堡徘徊？",a="席瓦莱恩在一次大法师阿鲁高引发的狼人袭击中，于自己的家中被杀。他在死后受到诅咒，灵魂被束缚在废弃城堡的宴会厅中，无法超度。",al={"为什么席瓦莱恩是幽灵","席瓦莱恩死了吗","席瓦莱恩之灵"}},{q="为什么席瓦莱恩会攻击入侵者？",a="他那受诅咒的灵魂仍留在昔日的家中，在大厅内攻击入侵者。",al={"为什么席瓦莱恩会攻击","席瓦莱恩幽灵","席瓦莱恩入侵者"}},{q="在城堡的什么地方能找到他？",a="席瓦莱恩男爵徘徊在大厅，在领地陷落并遭到破坏之前，这里曾是城堡奢华的餐厅。",al={"席瓦莱恩在哪里","席瓦莱恩男爵位置","席瓦莱恩宴会厅"}},{q="在狼人袭击之前，影牙城堡叫什么名字？",a="它最初被称为席瓦莱恩城堡，以在阿鲁高夺取控制权之前统治此地的男爵贵族家族命名。",al={"影牙城堡原名","席瓦莱恩城堡背景","影牙城堡的旧称"}},{q="席瓦莱恩的家族有人幸存吗？",a="没有记录说明。旧时的报告只提到狼人围攻了男爵的城堡，而他充满怨恨的幽灵至今仍徘徊于此；关于他家人的其他情况则没有任何记载。",al={"席瓦莱恩家族","席瓦莱恩的家人是否幸存","席瓦莱恩继承人"}}},fx={["1b1b3783"]={q="席瓦莱恩男爵站在哪一方？",a="席瓦莱恩男爵只为自己和对毁灭领地的悲惨回忆而战。阿鲁高大法师将凶暴的狼人放入城堡时，席瓦莱恩惨遭杀害；死亡扭曲了他的幽灵心智。在痛苦的诅咒束缚下，他会不分青红皂白地袭击任何闯入他宴会厅的活人。",al={"席瓦莱恩男爵的阵营","席瓦莱恩为谁而战","席瓦莱恩男爵和阿鲁高站在一边吗"}},["5d3ddd3d"]={q="席瓦莱恩男爵想要什么？",a="席瓦莱恩男爵化作复仇幽魂，困于世间，只想赶走或杀死任何胆敢侵入家园的人。他饱受惨烈死亡的折磨，灵魂因任何扰乱城堡古老大厅的人而持续暴怒，猛烈反击。",al={"席瓦莱恩想要什么","席瓦莱恩男爵的目标","席瓦莱恩为什么发动攻击"}},["02c6a3ca"]={q="席瓦莱恩男爵与谁有关？",a="席瓦莱恩男爵的悲惨命运与阿鲁高大法师紧密相连。阿鲁高召唤异次元的狼人对抗天灾军团时，这些野兽变得嗜血成性，围攻了席瓦莱恩的城堡。阿鲁高将这座堡垒据为己有，命名为影牙城堡，而男爵复仇的幽灵至今仍在其中徘徊。",al={"席瓦莱恩的关系","席瓦莱恩与谁有关","席瓦莱恩男爵与阿鲁高"}}},fp="17,189,28.379.0,19.208.0,26.120.0,35.168.0,40.103.0,34.116.0,57.140.0,43.176.0"}
P.entries["npc:baros-alexston"] = {n="巴隆斯·阿历克斯顿",s="巴隆斯·阿历克斯顿是暴风城的首席建筑师，驻扎在俯瞰Cathedral Square的市政厅内。作为石匠工会的前成员，他曾协助在第一次战争后重建首都。当激烈的争端导致工会分裂时，他选择接受官方任命并效忠于王室，而不是加入他的老友艾德温·范克里夫。",h="巴隆斯·阿历克斯顿是暴风城的首席建筑师，驻扎在俯瞰Cathedral...",kw={"阿历克斯顿","建筑师","巴隆斯","cathedral square","市政厅","迪菲亚","农场","石匠工会","未寄出的信","范克里夫"},ang={["class:Rogue"]="对于在首都阴影中穿梭的潜行者来说，巴隆斯是通往马迪亚斯·肖尔和军情七处的联系人，尽管他与范克里夫过去有过联系，但他们仍欠这位建筑师一些人情。",["faction:Alliance"]="巴隆斯·阿历克斯顿代表了联盟内部痛苦的妥协，展示了石匠工会的背叛是如何撕裂了那些倾注毕生心血重建首都的工匠们。",["race:Human"]="来自西部荒野的人类冒险者会从那个现在被强盗和豺狼人占领的、杂草丛生且破败不堪的农场中认出巴隆斯的姓氏。"},sec={{t="从农场到绞刑架",b="巴隆斯在西部荒野起伏的草原上的阿历克斯顿农场长大。年轻时，强盗占领并烧毁了他家的宅院，迫使他父亲在逃离前匆忙将家里最珍贵的传家宝藏在各处。巴隆斯最终前往首都并加入了石匠工会，与工会长艾德温·范克里夫一起进行了多年的艰苦劳动，在第一次战争的灰烬中重建了暴风城。"},{t="分道扬镳",b="当重建工作接近尾声时，贵族议会拒绝支付约定的报酬，导致了激烈的抗议、石匠工会的解散以及致命的街头暴乱。当范克里夫带领被剥夺权利的工匠流亡并组建迪菲亚潜行者时，贵族们向巴隆斯提供了尊贵的城市建筑师职位，前提是他必须否认这场起义。由于在工会走向暴力强盗行为的道路上存在意识形态上的分歧，巴隆斯接受了这个提议，这也加深了他与昔日同伴之间悲剧性的裂痕。"},{t="死亡矿井中的幽灵",b="在市政厅的办公桌后，巴隆斯继续监督着首都的维护工作，并保持着政治联系，其中包括军情七处的Mathias Shaw欠他一个人情。然而，他的过去不愿就此埋葬。随着范克里夫在死亡矿井深处的倒下，一封写给巴隆斯的未寄出的信躺在迪菲亚首领的尸体上——这见证了一段因政治、背叛以及在暴风城基石上流下的鲜血而断裂的羁绊。"}},faq={{q="我在哪里可以找到巴隆斯·阿历克斯顿？",a="巴隆斯·阿历克斯顿驻扎在暴风城市政厅内，位于暴风城Cathedral Square的北侧。",al={"巴隆斯·阿历克斯顿位置","巴隆斯·阿历克斯顿在哪里","巴隆斯暴风城"}},{q="巴隆斯·阿历克斯顿在暴风城担任什么职务？",a="他担任暴风城的首席建筑师。他负责管理首都的持续建设、市政维护和建筑规划。",al={"巴隆斯的工作","巴隆斯的头衔","巴隆斯负责什么"}},{q="巴隆斯是怎么认识艾德温·范克里夫的？",a="他们曾是石匠工会的亲密同事，在第一次战争后并肩努力重建暴风城。当贵族议会拒绝向工人支付报酬时，范克里夫领导了反抗，而巴隆斯则留下来接受了城市建筑师的职位。",al={"巴隆斯和范克里夫","巴隆斯认识艾德温吗","巴隆斯石匠工会"}},{q="为什么巴隆斯没有加入迪菲亚潜行者？",a="巴隆斯对于工会堕落为暴力反抗在意识形态上持有不同意见。当贵族议会提出，如果他拒绝跟随范克里夫，就给他城市建筑师的职位时，巴隆斯选择了城市秩序而非亡命生涯。",al={"为什么巴隆斯留下来","巴隆斯迪菲亚分裂","为什么巴隆斯背叛石匠工会"}},{q="在艾德温·范克里夫身上发现的未寄出的信是什么？",a="在艾德温·范克里夫于死亡矿井死亡后，冒险者发现了一封直接写给巴隆斯·阿历克斯顿的未寄出的信，揭示了这两位前工匠之间挥之不去的个人怨恨和未解决的历史。",al={"未寄出的信任务","范克里夫未寄出的信","给巴隆斯的信"}},{q="巴隆斯·阿历克斯顿与西部荒野有什么联系？",a="巴隆斯在西部荒野的阿历克斯顿农场长大。他的家人在强盗烧毁农场后逃离了那里，后来巴隆斯招募冒险者去取回他的童年遗物，包括他的第一个指南针。",al={"阿历克斯顿农场","巴隆斯西部荒野","巴隆斯的童年"}}},fp="14,189,34.402.0,24.486.1,27.341.1,32.112.0,43.104.0,35.263.1,45.150.1,50.198.1,48.185.0"}
P.entries["npc:bartleby"] = {n="巴特莱比",s="巴特莱比是一个好斗的酒鬼，在暴风城Old Town的Pig and Whistle Tavern里游荡。他以对自己的麦芽酒有着顽固的执念而闻名，对于那些想要在传统的酒馆斗殴中证明自己勇气的年轻战士来说，他是早期的一项武力考验。",h="巴特莱比是一个好斗的酒鬼，在暴风城Old Town的Pig and Whistle...",kw={"巴特莱比","斗殴","伯加德","酒鬼","酒杯","old town","pig and whistle tavern","酒馆","战士"},ang={["class:Warrior"]="每个在暴风城受训的年轻战士都记得他们与巴特莱比的那场决斗。从一个顽固酒鬼手中夺下酒杯，是格斗训练中令人难忘的成人礼。",["race:Human"]="巴特莱比代表了暴风城Old Town中粗犷的工人阶级一面，在这里，当地的争端是靠打翻的酒吧凳子解决的，而不是靠国王的法令。"},sec={{t="Pig and Whistle Tavern的常客",b="Pig and Whistle Tavern坐落在Old Town狭窄的鹅卵石巷弄中，比起Cathedral Square那些整洁的酒吧，这里吸引着一群更粗犷、更饱经风霜的顾客。巴特莱比是这里最长久的常客之一。他紧紧攥着自己最爱的酒杯，靠廉价的麦芽酒维持着那份醉意，终日在那儿发泄不满，并找任何打扰他喝酒的倒霉鬼寻衅滋事。"},{t="战士的成人礼",b="虽然巴特莱比看起来和其他社区里的酒鬼没什么两样，但暴风城的战士训练师却发现了他身上的实用价值。哈里·伯加德经常指引初出茅庐的战士去找到巴特莱比，并从他手里夺走那个酒杯。要拿到酒杯，就必须与这个醉醺醺的格斗者进行肉搏，这能证明一位新手战士是否具备近距离应对不守规矩对手的胆魄。"}},faq={{q="谁是巴特莱比？",a="巴特莱比是暴风城Old Town的Pig and Whistle Tavern里的一名不守规矩的酒馆常客。他以烂醉如泥且不打一架就不肯交出酒杯而闻名。",al={"巴特莱比背景故事","谁是巴特莱比","巴特莱比 暴风城"}},{q="我在哪里可以找到巴特莱比？",a="你可以在位于暴风城Old Town区的Pig and Whistle Tavern的一楼找到正在喝酒的巴特莱比。",al={"巴特莱比位置","巴特莱比在哪里","巴特莱比 pig and whistle tavern"}},{q="为什么战士需要和他战斗？",a="Old Town的战士训练师哈里·伯加德会将年轻的新兵派往巴特莱比那里，作为一项原始战斗能力的测试。强行夺走巴特莱比的酒杯证明了一名新兵能够应对突发的肢体冲突，并克服顽固且强硬的对手。",al={"为什么要打败巴特莱比","战士任务 巴特莱比","巴特莱比的作用"}},{q="当你面对他时会发生什么？",a="当有人为了他珍视的酒杯向他发起挑战时，巴特莱比会喝下一瓶药水来增强自己的毅力并变得敌对，然后在酒馆中央展开一场赤手空拳的斗殴，直到他被打倒屈服为止。",al={"与巴特莱比战斗","打败巴特莱比任务","巴特莱比斗殴"}},{q="巴特莱比属于任何派系或组织吗？",a="巴特莱比只是暴风城的一名平民，也是个习惯性酗酒的酒鬼。他与迪菲亚潜行者这样的犯罪集团或城市卫兵没有任何已知的联系。",al={"巴特莱比是迪菲亚潜行者吗","巴特莱比阵营","巴特莱比 联盟"}},{q="他为什么不直接把酒杯交出来？",a="巴特莱比好斗、烂醉如泥且顽固不化。他将任何索要他酒水或酒杯的人视为一种侮辱，比起交出他的酒，他更愿意用拳头来解决问题。",al={"巴特莱比的酒杯","巴特莱比的麦芽酒杯","为什么要争夺酒杯"}}},fp="8,194,32.256.0,27.267.0,16.166.0,26.105.0,34.193.0,35.159.0,52.126.0,36.184.0"}
P.entries["npc:bashana-runetotem"] = {n="巴珊娜·符文图腾",s="巴珊娜·符文图腾是一位居住在雷霆崖长者高地的草药师和德鲁伊研究员。作为大德鲁伊哈缪尔·符文图腾的女儿，她通过监督农业调查并引导部落冒险者对抗腐化力量，从而协助塞纳里奥议会。",h="巴珊娜·符文图腾是一位居住在雷霆崖长者高地的草药师和德鲁伊研究员。作为大德鲁伊哈缪尔·符文图腾的女儿，她通过监督农业调查并引导部落冒险者对抗腐化力量，从而协助塞纳里奥议会。",kw={"巴珊娜","黑暗深渊","塞纳里奥议会","长者高地","哈缪尔","晨光麦","符文图腾","雷霆崖"},ang={["class:Druid"]="对于在她的父亲哈缪尔门下学习技艺的牛头人德鲁伊来说，巴珊娜代表了理解卡利姆多不断变化的生态环境所必需的实际野外工作。",["faction:Horde"]="巴珊娜是雷霆崖的塞纳里奥议会代表与寻求打击邪教威胁的部落勇士之间的关键桥梁。"},sec={{t="议会之女",b="巴珊娜·符文图腾站在长者高地微风习习的高处，传承着她父亲——大德鲁伊哈缪尔·符文图腾的德鲁伊遗产。当她的父亲指导新兴的牛头人德鲁伊并为凯恩·血蹄提供建议时，巴珊娜则专注于对植物异常现象和地区性威胁的实际研究。她为旅行者配备诸如常青袋之类的工具来培育神秘的植物，尤其是谜一般的晨光麦，同时还协调部落的努力，以净化从黑暗深渊等地方蔓延出来的邪恶腐化。"}},faq={{q="巴珊娜·符文图腾是谁？",a="巴珊娜是一位住在雷霆崖长者高地的牛头人德鲁伊兼研究员。她是大德鲁伊哈缪尔·符文图腾的女儿，并代表塞纳里奥议会研究奇特的植物，组织对卡利姆多各地自然威胁的应对措施。",al={"巴珊娜是谁","巴珊娜背景故事","巴珊娜·符文图腾是谁"}},{q="她对晨光麦进行了哪些研究？",a="巴珊娜招募部落冒险者使用种子袋和土壤来培育和收集晨光麦。塞纳里奥议会研究这种强力而神秘的草药，以了解其不同寻常的特性，以及它与卡利姆多各地正在展开的更宏大的植物学谜团之间的联系。",al={"晨光麦研究","巴珊娜如何处理晨光麦","为什么要研究晨光麦"}},{q="她与黑暗深渊有什么联系？",a="巴珊娜会接收由银月守卫塞尔瑞德派遣、前往对抗黑暗深渊邪教徒的冒险者所带回的报告和证据。她会奖励他们为对抗威胁灰谷的腐化所做出的贡献。",al={"巴珊娜与黑暗深渊","黑暗深渊的邪恶任务","为什么要前往黑暗深渊"}},{q="在哪里可以找到她？",a="她位于雷霆崖的长者高地，这座平顶山是城市中萨满祭司、德鲁伊和精神长者们的聚集地，她就站在德鲁伊亭台附近。",al={"巴珊娜·符文图腾在哪里","巴珊娜位置","如何找到巴珊娜"}}},fp="17,164,24.437.0,25.238.0,48.219.0,44.194.0,23.151.0"}
P.entries["npc:bath-rah-the-windwatcher"] = {n="捕风者巴斯拉",s="捕风者巴斯拉是一位隐居的丛林巨魔萨满祭司兼武器匠，居住在冰风岗附近的废墟之中。他远离故乡的热带家园，在北方群山中研究狂暴的元素之力，并寻找强大的勇士来协助他打造威力强大的风之武器。",h="捕风者巴斯拉是一位隐居的丛林巨魔萨满祭司兼武器匠，居住在冰风岗附近的废墟之中。他远离故乡的热带家园，在北方群山中研究狂暴的元素之力，并寻找强大的勇士来协助他打造威力强大的风之武器。",kw={"奥特兰克","巴斯拉","冰风岗","塞克隆尼亚","元素生物","萨满祭司","旋风","捕风者"},ang={["class:Shaman"]="作为一名同道元素大师，巴斯拉与那些追求与大地、水和空气之灵进行更深层次交流的萨满祭司们有着深厚的精神共鸣。",["class:Warrior"]="巴斯拉在老练的战士中颇有名气，因为他会引导他们完成锻造标志性旋风武器所需的试炼，并使用元素生物塞克隆尼亚的精华来完成锻造。"},sec={{t="山巅隐士",b="虽然大多数丛林巨魔都待在南方温暖的森林和海岸，但巴斯拉却在寒冷的奥特兰克山脉废墟中，过着山中隐士的孤独生活。作为一名经验丰富的萨满祭司和工匠，他将自己的日子投入到倾听呼啸的风声和与自然之灵交流中。他的执念不仅仅止于哲学层面；他试图将狂暴的元素风暴之力束缚在有形的武器之中，赠予那些拥有足够力量驾驭它们的人。"},{t="塞克隆尼亚的主人",b="巴斯拉最大的雄心壮志与塞克隆尼亚有关，那是一个盘踞在周边山峰中的巨大风元素生物。由于无法独自击败这样的存在，这位捕风者便招募经验丰富的战士和萨满祭司去收集奇异的元素精华，并召唤出这头野兽。通过击杀塞克隆尼亚并夺取其元素之心，巴斯拉将原始的风暴之力驯服，制成在艾泽拉斯享有盛誉的传奇武器。"}},faq={{q="捕风者巴斯拉是谁？",a="巴斯拉是一位古怪的丛林巨魔萨满祭司兼武器匠，隐居在冰风岗附近的奥特兰克山脉废墟中。他帮助经验丰富的冒险者驾驭元素之力，打造强大的武器。",al={"捕风者巴斯拉身份","捕风者巴斯拉是谁","捕风者背景故事"}},{q="为什么丛林巨魔会住在奥特兰克？",a="巴斯拉作为隐士居住在冰风岗附近，研究元素力量并帮助有能力的冒险者锻造武器。他离开故乡的原因尚不为人知。",al={"为什么巴斯拉在奥特兰克","奥特兰克山脉的巨魔"}},{q="塞克隆尼亚是什么？",a="塞克隆尼亚是一个巨大的狂暴风元素生物，出没在巴斯拉的栖身地附近的废墟中。巴斯拉需要这种生物的核心来锻造注入了元素之风的武器。",al={"塞克隆尼亚是谁","巴斯拉召唤什么"}},{q="战士们为什么要寻找他？",a="战士们从世界各地赶来寻找巴斯拉，因为他知道如何锻造标志性的旋风系列武器。在他的指引下击败塞克隆尼亚，就能获得注入了狂风之力的武器。",al={"捕风者战士任务","旋风斧制作者"}},{q="巴斯拉只帮助部落成员吗？",a="巴斯拉作为一名孤独的隐士，远离各大阵营的政治纠纷。他主要专注于元素锻造工艺，并愿意协助那些尊重灵魂、能为他的元素研究提供帮助的有能力的战士和萨满祭司。",al={"巴斯拉是敌对的吗","捕风者阵营"}}},fx={["4f68ea16"]={q="捕风者巴斯拉想要什么？",a="巴斯拉正在寻找一位有资格挑战并击败塞克隆尼亚的勇士。这个狂暴的元素生物居住在他的营地附近。他渴望得到它的心脏，希望借助其中原始而狂野的能量，铸造一件威力惊人的非凡武器。",al={"捕风者巴斯拉想要什么","捕风者巴斯拉的目标"}}},fp="24,300,19.475.0,19.409.1,32.221.0,40.185.0,18.178.0,29.192.0,45.218.0"}
P.entries["npc:bazil-thredd"] = {n="巴基尔·斯瑞德",s="巴基尔·斯瑞德是艾德温·范克里夫的副手和最信任的助手，自从石匠工会暴乱以来一直被关押在暴风城监狱中。现在监狱爆发了叛乱，斯瑞德率领着监狱东区牢房的迪菲亚囚犯们发动了暴动。",h="巴基尔·斯瑞德是艾德温·范克里夫的副手和最信任的助手，自从石匠工会暴乱以来一直被关押在暴风城监狱中。现在监狱爆发了叛乱，斯瑞德率领着监狱东区牢房的迪菲亚囚犯们发动了暴动。",kw={"巴基尔·斯瑞德","迪菲亚","迪菲亚潜行者","艾德温·范克里夫","哈姆霍克","马利克","监狱","石匠工会","暴风城监狱","斯瑞德","典狱官塞尔沃特"},ang={["faction:Alliance"]="一场发生在暴风城街道下方的迪菲亚叛乱对首都构成了直接威胁，典狱官塞尔沃特希望在它蔓延之前除掉其首领。",["race:Human"]="斯瑞德是那场让迪菲亚潜行者与王国为敌的石匠工会暴乱的活证人。"},sec={{t="范克里夫的副手",b="当石匠工会因为重建暴风城的工程被贵族拒绝支付报酬时，艾德温·范克里夫拒绝了政府的安抚，并引发了公开的暴乱。巴基尔·斯瑞德作为首席副手和最信任的助手站在范克里夫的一边。在随后发生的暴力冲突中，斯瑞德被城卫军俘虏。当范克里夫和幸存的石匠逃往西部荒野建立迪菲亚潜行者组织时，斯瑞德被投入了暴风城监狱的深处。"},{t="监狱暴乱",b="多年来，斯瑞德在铁栏后保持沉默，似乎已被遗忘。但随着一场大规模的监狱暴动，这种与世隔绝的状态被打破了，囚犯们制服了守卫，打开了牢门，使监狱变成了Mage Quarter下方的一座武装堡垒。斯瑞德夺取了囚禁的迪菲亚强盗、叛乱分子和同伙匪徒的领导权，并在食人魔哈姆霍克的看守下，在东侧牢区建立了指挥所。典狱官塞尔沃特急于在混乱蔓延到城市街道之前恢复秩序，他要求取下斯瑞德的头颅，以瓦解叛乱的领导核心。"},{t="神秘的访客",b="典狱官塞尔沃特一直认为迪菲亚潜行者已经抛弃了斯瑞德，任由他在狱中腐烂。然而，在暴乱发生前的几个月里，一名自称马利克（Maelik）的神秘男子开始每周一到两次探望斯瑞德。尽管塞尔沃特心存疑虑，但该访客的证件完全合法。随着斯瑞德的死亡，塞尔沃特怀疑那人不会再来了，但他的描述值得传阅：任何拥有如此完备证件的人都一定有着广泛的门路，而这些探视暗示着城内有外部势力曾接触过这位迪菲亚副手。"}},faq={{q="巴基尔·斯瑞德是谁？",a="巴基尔·斯瑞德是艾德温·范克里夫在暴风城石匠工会暴乱期间的得力助手。在暴乱中被捕后，他被关进监狱，现在他在那里领导着叛乱的囚犯。",al={"巴基尔·斯瑞德背景故事","斯瑞德是谁","监狱首领斯瑞德"}},{q="在哪里可以找到巴基尔·斯瑞德？",a="他位于暴风城监狱深处，那是Mage Quarter附近运河区下方的一个监狱综合体。在主走廊的交叉口，往东侧牢区走，经过食人魔蛮兵哈姆霍克；斯瑞德在最深处房间的中央牢房指挥。",al={"巴基尔·斯瑞德在哪里","斯瑞德位置","找到巴基尔·斯瑞德"}},{q="监狱为什么会发生暴乱？",a="囚犯们制服了守卫，打开了牢门，并占领了监狱大厅。巴基尔·斯瑞德是监狱中最重要的迪菲亚囚犯，他夺取了暴动强盗和罪犯的领导权，典狱官塞尔沃特正努力阻止这场暴乱蔓延到暴风城的街道上。",al={"为什么发生暴乱","监狱暴乱起因","囚犯为何暴动"}},{q="为什么典狱官塞尔沃特想要斯瑞德死？",a="典狱官塞尔沃特认为，只要斯瑞德还活着指挥叛乱，起义就无法平息。由于监狱守卫已被压制，囚犯们控制了整个区域，典狱官下令处决斯瑞德以摧毁叛乱的指挥结构。",al={"为什么要杀斯瑞德","塞尔沃特悬赏斯瑞德","巴基尔·斯瑞德的头颅原因"}},{q="暴乱前是谁在探望斯瑞德？",a="在暴乱发生前的几个月里，一名自称马利克的沉默男子每周都会探望斯瑞德。尽管塞尔沃特对此感到怀疑，但访客持有合法的文书，这强烈暗示着暴风城内的迪菲亚同情者或腐败官员为这种接触提供了便利。",al={"斯瑞德的访客","马利克是谁","神秘访客身份"}},{q="斯瑞德在石匠工会中扮演什么角色？",a="在暴风城重建和随后的劳资纠纷中，斯瑞德担任艾德温·范克里夫的首席副手，当贵族议会拒绝支付他们的劳动报酬时，他协助组织了工会的抵抗活动。",al={"斯瑞德是石匠吗","石匠斯瑞德","石匠工会斯瑞德"}}},fp="12,187,21.517.0,21.469.0,19.473.1,20.181.0,32.249.0,28.274.0,43.202.0,40.241.1,48.211.0"}
P.entries["npc:bazzalan"] = {n="巴扎兰",s="巴扎兰是一位邪恶的萨特潜行者，潜伏在怒焰裂谷的火山深处。他与祈求者耶戈什并肩作战，在奥格瑞玛这座部落主城正下方的暗处，指挥着灼热利刃邪教的阴暗勾当。",h="巴扎兰是一位邪恶的萨特潜行者，潜伏在怒焰裂谷的火山深处。他与祈求者耶戈什并肩作战，在奥格瑞玛这座部落主城正下方的暗处，指挥着灼热利刃邪教的阴暗勾当。",kw={"巴扎兰","邪教徒","祈求者耶戈什","奥格瑞玛","怒焰裂谷","萨特","灼热利刃"},ang={["class:Rogue"]="巴扎兰展示了经典的潜行技巧、凶狠的打击和涂毒的刀刃，使他成为了一个具有独特职业关注价值的对手。",["faction:Horde"]="巴扎兰和他的邪教就在萨尔的据点下方构成了不可容忍的威胁，必须立即清除。",["race:Orc"]="兽人们历尽艰辛才摆脱了恶魔的操纵，因此看到一个萨特在他们的根基处指挥邪教徒，被视为一种暴行。"},sec={{t="城下的毒蛇",b="当萨尔在杜隆塔尔努力建立兽人新家园时，古老的邪恶已经在他的脚下找到了栖身之所。巴扎兰，一位狡诈的萨特潜行者，与盘踞在怒焰裂谷蜿蜒熔岩洞穴中的灼热利刃邪教结成了同盟。他手持双刃，身手敏捷且致命，是该邪教的主要战地指挥官之一。"},{t="邪教领导与欺诈",b="巴扎兰栖息在俯瞰中央大厅的黑色火山岩架上，祈求者耶戈什正在那里进行恶魔仪式，而巴扎兰则负责监督他的邪教徒卫兵。像所有萨特一样，他的终极忠诚属于恶魔主人，他利用毒药、快速打击和阴暗的潜行技术，清除任何过于接近邪教据点的部落斥候。"}},faq={{q="巴扎兰是谁？",a="巴扎兰是一位萨特潜行者，也是在奥格瑞玛地下的怒焰裂谷中活动的灼热利刃邪教的共同领导者。",al={"巴扎兰背景故事","巴扎兰是谁","怒焰裂谷萨特首领"}},{q="在怒焰裂谷哪里可以找到巴扎兰？",a="他潜伏在怒焰裂谷的上层岩架，位于祈求者耶戈什的上方。可以通过攀爬凿在洞穴墙壁上的黑暗坡道找到他。",al={"巴扎兰位置","巴扎兰在哪里","寻找巴扎兰"}},{q="萨特为什么会在奥格瑞玛下方？",a="巴扎兰与灼热利刃邪教协同行动，这是一个试图从内部破坏部落的恶魔邪教。萨特受缚于恶魔力量，经常担任暗影议会的煽动者和刺客。",al={"为什么奥格瑞玛有萨特","为什么巴扎兰在怒焰裂谷"}},{q="巴扎兰在战斗中使用什么技能？",a="巴扎兰的战斗方式是经典的潜行者，使用近战武器进行快速打击，使用邪恶攻击，并偶尔使对手感染一种轻微的致残毒药。",al={"巴扎兰技能","巴扎兰攻击方式","巴扎兰怎么战斗"}},{q="他与祈求者耶戈什是什么关系？",a="巴扎兰和耶戈什共同领导着怒焰裂谷内的灼热利刃。耶戈什专注于祈求和召唤黑暗力量，而巴扎兰则充当军事和潜行方面的权威。",al={"耶戈什和巴扎兰","巴扎兰和耶戈什有关吗"}},{q="为什么部落想要除掉巴扎兰？",a="他出现在主城地下的深处，直接构成了恶魔威胁。部落首领委托冒险者潜入怒焰裂谷，在他将灼热利刃的阴谋危及城市之前将其消灭。",al={"巴扎兰赏金","击退入侵巴扎兰"}}},fp="8,151,26.264.0,26.319.0,16.114.0,46.133.0,40.198.0,43.134.0,48.197.0,38.192.0"}
P.entries["npc:beldin-steelgrill"] = {n="贝尔丁·钢架",s="贝尔丁·钢架是一位著名的矮人工程师，也是丹莫罗钢架补给站的首席技术员。他被公认为是卡兹莫丹最顶尖的攻城机械技师之一，负责维护铁炉堡军队的重甲和履带式战争机器。要让那些庞大的装置保持运转，需要源源不断地供应高等级的专用工具。",h="贝尔丁·钢架是一位著名的矮人工程师，也是丹莫罗钢架补给站的首席技术员。他被公认为是卡兹莫丹最顶尖的攻城机械技师之一，负责维护铁炉堡军队的重甲和履带式战争机器。要让那些庞大的装置保持运转，需要源源不断地供应高等级的专用工具...",kw={"贝尔丁·钢架","丹莫罗","铁炉堡","卡拉诺斯","技师","攻城机械","蒸汽坦克","钢架"},ang={["profession:Engineering"]="对于工程师来说，贝尔丁代表了矮人载具技术的巅峰，让他人能够近距离观察联盟最强大的机械化战争资产。",["race:Dwarf"]="贝尔丁的场地展示了铁炉堡的工业实力，证明了矮人的工艺不仅限于手持的锤子和斧头，更延伸到了毁灭性的攻城火炮。"},sec={{t="履带猛兽的主人",b="钢架补给站位于卡拉诺斯下方的道路旁，是矮人蒸汽坦克和攻城机械的主要测试场和服务站。贝尔丁·钢架担任首席技术员，他以修理和调试装甲战车的卓越技术而闻名遐迩。驾驭重金属和轰鸣的锅炉是一项极其艰苦的工作，贝尔丁消耗工具的速度极快。为了保持工作台的供应，他对重型扳手、切割机和精密仪器的持续需求常常让当地的铁匠们疲于奔命。"}},faq={{q="贝尔丁·钢架是谁？",a="贝尔丁·钢架是一位矮人机械大师，也是丹莫罗钢架补给站的经营者。他在整个卡兹莫丹都以矮人攻城机械和战车的杰出技术员而闻名。",al={"贝尔丁·钢架","贝尔丁是谁","丹莫罗坦克技师"}},{q="钢架补给站里有什么？",a="该补给站位于卡拉诺斯东北方，是联盟蒸汽坦克和重型机械装备繁忙的维护和测试场地。",al={"钢架补给站","什么是钢架补给站","补给站用途"}},{q="为什么贝尔丁会消耗这么多工具？",a="维修重型装甲板、复杂的齿轮和高压蒸汽锅炉需要高强度的劳动和专业设备。贝尔丁的重型工作使工具的磨损速度惊人，迫使他不得不向附近的铁匠们下达高要求的订单。",al={"为什么他需要工具","钢架工具","给钢架的工具"}}},fp="17,234,27.289.0,25.181.0,35.138.0,41.172.0"}
P.entries["npc:bethor-iceshard"] = {n="比索·埃斯沙德",s="比索·埃斯沙德是一位强大的被遗忘者法师，驻扎在幽暗城的魔法区。他主管受难者神殿内的奥术和暗影施法者，在希尔瓦娜斯的领域中拥有相当大的权威。在他冰冷的外表下，隐藏着一段往事，那是他与昔日好友因天灾军团而分崩离析的痛苦记忆。",h="比索·埃斯沙德是一位强大的被遗忘者法师，驻扎在幽暗城的魔法区。他主管受难者神殿内的奥术和暗影施法者，在希尔瓦娜斯的领域中拥有相当大的权威。在他冰冷的外表下，隐藏着一段往事，那是他与昔日好友因天灾军团而分崩离析的痛苦记忆。",kw={"比索·埃斯沙德","被遗忘者","冈瑟尔·阿坎努斯","magic quarter","浪子巫妖","受难者神殿","图勒·鸦爪","幽暗城"},ang={["class:Mage"]="对于被遗忘者法师来说，比索代表了坚韧的巅峰，证明了即使在亡灵的冰冷掌控之下，奥术艺术依然可以蓬勃发展。",["faction:Horde"]="比索负责协调关键的进攻性魔法行动和反死灵法术作战，以保护部落在洛丹伦各地的立足点。",["race:Undead"]="比索个人的悲剧是许多被遗忘者的缩影：被天灾军团切断了珍贵的友谊与家园，最终却只能面对曾经的盟友，将其视为苦涩的敌人。"},sec={{t="魔法区大师",b="比索·埃斯沙德伫立在受难者神殿中，监管着幽暗城内的奥术和暗影魔法修行者。他以智慧和冰冷的意志著称，既受人敬重又令人畏惧，比索拥有足够的政治和魔法影响力，可以直接向洛丹伦各地的地区治安官下达指令。他指挥着被遗忘者的特工去获取珍贵的魔法书，调查奥术异常现象，并铲除那些威胁幽暗城统治的敌对势力。"},{t="故友重逢与苦涩回忆",b="比索没有忘记他曾经的同伴。他追踪着提瑞斯法林地和银松森林各处强大的亡灵施法者，派遣特工去辨别这些游荡的施法者究竟是效忠于巫妖王，还是可以被争取到被遗忘者的阵营中来。当比索发现冈瑟尔·阿坎努斯正在澈水湖上复活死者时，他耐心地将其老友引向希尔瓦娜斯女王的麾下，而对图勒·鸦爪则毫不留情，因为正是图勒的背叛摧毁了他们往日的兄弟情谊。"},{t="学徒羁绊",b="在第三次战争摧毁洛丹伦之前，比索曾是一名凡人学徒，与两位挚友一同钻研魔法：冈瑟尔·阿坎努斯和图勒·鸦爪。为了见证他们的友谊，这三名学生将各自的练习法杖编织在了一起。天灾军团彻底粉碎了这份羁绊。当死亡和黑暗魔法席卷整个王国时，图勒·鸦爪自愿向巫妖王献出了灵魂，冈瑟尔在澈水湖的一座孤岛上死去并复生，而比索则在死后才得以挣脱束缚，成为了一名被遗忘者。"}},faq={{q="比索·埃斯沙德是谁？",a="比索·埃斯沙德是一位地位崇高的被遗忘者法师，主管幽暗城魔法区的受难者神殿。他代表黑暗女王协调魔法研究、游荡者情报收集以及秘密奥术行动。",al={"比索·埃斯沙德","比索是谁","比索背景故事"}},{q="在哪里可以找到比索·埃斯沙德？",a="比索居住在受难者神殿内，那是位于幽暗城魔法区的核心建筑。",al={"比索在哪里","比索位置","找到比索·埃斯沙德"}},{q="比索与冈瑟尔·阿坎努斯有什么过往？",a="比索和冈瑟尔在洛丹伦担任魔法学徒期间是亲密的好友。在天灾军团入侵期间死亡后，两人最终都摆脱了巫妖王的控制，随后比索一手策划了冈瑟尔加入被遗忘者的过程。",al={"冈瑟尔与比索","冈瑟尔·阿坎努斯的友谊","比索如何认识冈瑟尔"}},{q="图勒·鸦爪对比索来说是什么人？",a="图勒·鸦爪是比索和冈瑟尔学徒圈子里的第三名成员。与其他两人不同，图勒在天灾军团入侵期间自愿向巫妖王献出了灵魂，成为了一个盘踞在芬里斯岛上的可憎的死灵法师。",al={"图勒·鸦爪的联系","图勒与比索","比索与鸦爪"}},{q="比索法杖背后的故事是什么？",a="年轻时，比索、冈瑟尔和图勒将他们的练习法杖编织在一起，作为他们永恒友谊的象征。那根编织而成的纪念物，至今仍是一件令人感伤的文物，将这三位破碎的施法者与他们的凡人过去紧紧相连。",al={"狼人魔杖","比索的法杖","比索学徒法杖"}},{q="比索在被遗忘者社会中扮演什么角色？",a="比索是幽暗城主要的奥术权威之一。他指导新复活的法师和术士，指挥有关游荡死灵法师的军事情报，并对像执政官塞弗伦这样的地方被遗忘者官员拥有管辖权。",al={"比索的角色","比索做什么","比索的权威"}}},fp="15,179,27.409.0,36.460.1,23.486.1,23.232.0,35.90.0,46.235.1,34.226.1,39.228.0,47.240.0"}
P.entries["npc:billy-maclure"] = {n="比利·马科伦",s="比利·马科伦是一个调皮的人类小男孩，住在艾尔文森林的马科伦农场。由于他的家庭与邻近的斯通菲尔德农场之间存在着激烈的世仇，比利那幼稚的恶作剧常常给两家农场带来麻烦。他抵挡不住新鲜糕点的诱惑，每当他的胡闹过了头，这便成了贿赂他最好的手段。",h="比利·马科伦是一个调皮的人类小男孩，住在艾尔文森林的马科伦农场。由于他的家庭与邻近的斯通菲尔德农场之间存在着激烈的世仇，比利那幼稚的恶作剧常常给两家农场带来麻烦。他抵挡不住新鲜糕点的诱惑，每当他的胡闹过了头，这便成了贿赂...",kw={"伯尼斯·斯通菲尔德","比利·马科伦","法戈第矿洞","金牙","丢失的项链","马科伦农场","猪肉馅饼","斯通菲尔德"},ang={["faction:Alliance"]="对于刚从北郡山谷抵达的联盟冒险者来说，协助处理比利的愚蠢恶作剧，可以作为了解潜伏在法戈第矿洞中危险的入门课。",["profession:Cooking"]="伯尼斯大婶闻名遐迩的猪肉馅饼证明了简单的边境烹饪如何能解决紧张的当地纠纷，并从守口如瓶的农场男孩口中套出真相。",["race:Human"]="比利代表了艾尔文乡村根深蒂固的日常争吵，这表明即使在暴风城的政治动荡之中，当地的农场世仇和童年的顽皮行为依然照常进行。"},sec={{t="农场的男孩",b="比利·马科伦通常会在马科伦农场的谷仓外闲逛，离农夫葛拉德·提勒不远。在连绵不断的葡萄藤间长大，比利大部分时间都在逃避干活，在艾尔文森林南部的乡村草地上四处乱跑。和他的族人一样，他敏锐地察觉到马科伦家族和斯通菲尔德家族之间由来已久的敌意，尽管比利更多地把这种世仇当成一场恶作剧和小偷小摸的游戏，而不是严重的冲突。"},{t="被偷走的项链",b="比利的恶作剧变本加厉，他偷走了伯尼斯·斯通菲尔德大婶珍藏的一条传家宝项链。当他在危险的法戈第矿洞附近狂奔时，这个受惊的孩子没拿稳饰品。在他找回它之前，项链被一只特别巨大而凶残的狗头人金牙抢走了，那家伙消失在深邃的地下矿道中。比利既害怕地下的害虫，又畏惧邻居长辈的怒火，直到用美味的诱饵——特别是伯尼斯大婶亲手烘焙的热腾腾的猪肉馅饼——哄骗他，否则他不愿吐露实情。"}},faq={{q="比利·马科伦是谁？",a="比利·马科伦是一个住在艾尔文森林马科伦农场的人类小男孩。他每天都在逃避农场里的活计，搞恶作剧，并激怒邻居斯通菲尔德一家。",al={"比利是谁","比利·马科伦背景故事","马科伦家的孩子"}},{q="在哪里可以找到比利·马科伦？",a="比利驻扎在马科伦农场主谷仓外，位于艾尔文森林南部，斯通菲尔德农场以东。",al={"比利·马科伦位置","比利在哪里","找到比利·马科伦"}},{q="比利对伯尼斯大婶做了什么？",a="作为他们两家之间持续世仇的一部分，比利溜到斯通菲尔德农场偷走了伯尼斯·斯通菲尔德大婶的传家宝项链。",al={"伯尼斯的项链","比利偷了什么","艾尔文森林被偷的项链"}},{q="比利偷走的项链发生了什么事？",a="当在法戈第矿洞入口附近粗心玩耍时，比利弄丢了项链。它很快被金牙捡走了，那是一个臭名昭著且强大的狗头人，它把项链带进了矿洞深处。",al={"项链在哪里","艾尔文丢失的项链","谁拿了伯尼斯的项链"}},{q="怎么让比利坦白项链的下落？",a="出于固执和对惩罚的恐惧，比利拒绝说出真相，但他无法抗拒自己的食欲。给他一个伯尼斯大婶刚烤好的猪肉馅饼就足以让他开口了。",al={"给比利的馅饼","如何贿赂比利","贿赂比利·马科伦"}},{q="金牙是谁？",a="金牙是一只体型巨大且凶残的狗头人首领，盘踞在法戈第矿洞里。它从矿洞入口附近抢走了伯尼斯大婶掉落的项链，并将它藏在黑暗的矿道中。",al={"金牙是谁","金牙背景故事","法戈第矿洞狗头人"}}},fp="13,221,22.344.0,19.383.1,21.152.0,33.106.0,36.97.0,42.97.1,62.101.1,17.166.1"}
P.entries["npc:bingles-blastenheimer"] = {n="宾格斯·雷管",s="宾格斯·雷管是一位古怪的侏儒飞行员，被困在洛克莫丹洛克湖的东南岸。在驾驶他的实验性飞行器坠毁后，他发现自己被困在当地的穴居人和野兽中间，急于回收他珍贵的工具和部件。",h="宾格斯·雷管是一位古怪的侏儒飞行员，被困在洛克莫丹洛克湖的东南岸。在驾驶他的实验性飞行器坠毁后，他发现自己被困在当地的穴居人和野兽中间，急于回收他珍贵的工具和部件。",kw={"宾格斯","雷管","侏儒","直升机","洛克莫丹","飞行员"},ang={["profession:Engineering"]="任何修补匠都能理解这种窘境：在一次雄心勃勃的飞行出错后，还要面对那些偷走不可替代的定制扳手和装置的穴居小偷。",["race:Gnome"]="宾格斯代表了侏儒对空中创新的典型追求，在他们看来，机械故障和爆炸只不过是通往进步道路上的小挫折而已。"},sec={{t="迫降",b="像许多雄心勃勃的侏儒工程师一样，宾格斯·雷管驾驶着一架改装的飞行器冲上蓝天，却发现安全着陆远比起飞要困难得多。在直升机发生故障并坠毁在洛克湖东南岸后，宾格斯幸免于难，但这架机器却摔得粉碎，零件散落一地。他远离铁炉堡，被困在残骸附近，不得不防备饥饿的鳄鱼和充满敌意的穴居人，并恳求路过的旅行者帮他收回被附近岛上的穴居人偷走的工具和爆破帽炸药。"}},faq={{q="谁是宾格斯·雷管？",a="宾格斯·雷管是一位侏儒飞行员兼修补匠，他的飞行器在洛克莫丹洛克湖的东南岸发生了灾难性的坠毁。",al={"谁是宾格斯","宾格斯·雷管背景故事","湖边的侏儒是谁"}},{q="他的飞行器发生了什么事？",a="宾格斯驾驶的直升机坠入了洛克湖。附近岛上的穴居人随后袭击了他，偷走了他的工具和特制的爆破帽炸药。",al={"宾格斯为什么坠机","宾格斯的直升机","宾格斯的飞机怎么了"}},{q="为什么宾格斯没有回城？",a="宾格斯的直升机毁了，被困在了原地，而且附近岛上的穴居人偷走了他的工具和爆破帽炸药。为了收复诺莫瑞根的大业，他必须拿回这些东西，所以他守在残骸旁等待有人能帮他找回它们。",al={"宾格斯为什么被困","为什么待在湖边"}},{q="宾格斯的飞行器修好后他去了哪里？",a="在这个时期，宾格斯一直待在洛克湖东南岸的坠机现场，等待冒险者帮他回收丢失的补给。",al={"宾格斯去哪了","宾格斯小屋"}}},fp="21,191,15.438.0,29.134.0,36.136.0,36.233.0,51.124.1"}
P.entries["npc:bink"] = {n="彬克",s="彬克是一位侏儒法师训练师，常驻于铁炉堡神秘区（Mystic Ward）的奥术大厅（Hall of Mysteries）。她思维敏捷、热情洋溢，引领着有抱负的施法者们参透奥术技艺的奥秘，并将他们与联盟各地的杰出法师联系起来。",h="彬克是一位侏儒法师训练师，常驻于铁炉堡神秘区（Mystic Ward）的奥术大厅（Hall of...",kw={"安多玛斯","彬克","侏儒","hall of mysteries","铁炉堡","法师训练师","mystic ward","塔贝萨"},ang={["class:Mage"]="对于来访或常驻铁炉堡的联盟法师而言，彬克是一位至关重要的训练师和任务联络人，负责派遣学生去艾泽拉斯各地的强大导师门下学习。",["race:Gnome"]="彬克代表了流亡在矮人盟友大厅中的侏儒们对奥术掌握的不懈追求。"},sec={{t="奥术大厅的指路明灯",b="彬克位于铁炉堡的神秘区，站在奥术大厅中聚集的学者、牧师和奥术师之中。和其他许多被迫逃离诺莫瑞根的侏儒一样，她已经适应了在这座矮人山中堡垒里的生活，并向那些学习法师之道的人提供她敏锐的才智和奥术工艺知识。她与东部王国和卡利姆多的法师们联系紧密，经常将有潜力的学徒引荐给更伟大的导师，例如暴风城的大法师安多玛斯或尘泥沼泽的塔贝萨。"}},faq={{q="彬克是谁？",a="彬克是一位联盟侏儒法师训练师，驻扎在铁炉堡神秘区的奥术大厅内。她教授奥术施法技巧，并担任成长中法师的导师和联络人。",al={"彬克背景故事","彬克是谁","铁炉堡彬克"}},{q="在哪里可以找到彬克？",a="你可以在铁炉堡神秘区西翼的奥术大厅内找到她。",al={"彬克位置","彬克在哪里","寻找彬克"}},{q="哪些任务与彬克有关？",a="成长中的法师会通过“与彬克交谈”等任务被指引去找她。反过来，她也会引导法师们进行深造，将他们派往诸如暴风城法师塔的大法师安多玛斯或尘泥沼泽的隐居法师塔贝萨等权威人士处。",al={"彬克任务","与彬克交谈任务"}},{q="彬克会对非非职业玩家说什么？",a="如果不是法师职业的玩家靠近她，她会愉快地提供一些实用建议：“去和法师交个朋友吧！我们确实有那么一两手绝活……”",al={"彬克闲聊","彬克对话"}}},fx={cf09b30e={q="彬克效忠哪一方？",a="彬克坚定地支持联盟和避居铁炉堡的诺莫瑞根流亡者。她与其他学者和法师一起在神秘大厅活动，运用自己的魔法才能帮助盟友，并指导在联盟旗帜下作战、有潜力的新法师。",al={"彬克的阵营","彬克为谁效力","彬克属于联盟还是部落"}},d0de8b26={q="彬克为什么在神秘大厅？",a="彬克住在铁炉堡的神秘大厅，担任侏儒法师训练师。诺莫瑞根陷落后，流离失所的侏儒在铜须矮人中找到了庇护；彬克运用自己的奥术专长训练有志成为法师的人，并派学生执行对奥术界至关重要的任务。",al={"彬克为什么在这里","彬克在铁炉堡做什么","彬克为什么在铁炉堡"}}},fp="4,152,33.505.0,12.130.0,22.91.0,25.210.0,32.126.0"}
P.entries["npc:bishop-delavey"] = {n="德拉维主教",s="德拉维主教是圣光教会的高级代表，驻扎在Stormwind Keep的Petitioner's Chamber内。他处理国家与信仰相关事务，并暗中负责监管王室无法公开处理的敏感宫廷事务。",h="德拉维主教是圣光教会的高级代表，驻扎在Stormwind Keep的Petitioner's Chamber内。他处理国家与信仰相关事务，并暗中负责监管王室无法公开处理的敏感宫廷事务。",kw={"德拉维主教","埃林·提亚斯","圣光","乔贞","失踪的外交官","petitioner's chamber","stormwind keep"},ang={["class:Priest"]="德拉维主教是教会深度参与暴风城政治的典型代表，这表明对圣光的信仰往往与国家治理和秘密事务交织在一起。",["faction:Alliance"]="他开展的秘密调查旨在保护暴风城与吉安娜·普罗德摩尔的塞拉摩前哨站之间脆弱的和平。"},sec={{t="宫廷中的主教",b="当大主教本尼迪塔斯在Cathedral of Light主持工作时，德拉维主教则居住在Stormwind Keep的贵族和请愿者之中。他担任教会与宫廷之间的联络人，在精神指引与王国的政治现实之间寻求平衡。他的职位使他能够在流言蜚语和敏感的宫廷积怨传到伯瓦尔·弗塔根公爵或年轻的安度因国王耳中之前，就先行察觉。"},{t="一次微妙的调查",b="当一名被派往塞拉摩会见吉安娜·普罗德摩尔的重要外交官失踪后，王室为了避免引起广泛恐慌，对这起失踪事件严格保密。怀疑是迪菲亚潜行者的阴险势力所为，德拉维主教绕过了常规的警卫程序。相反，他动用了私人渠道和谨慎的冒险者，利用像渔夫乔贞这样的联系人，与埃林·提亚斯等秘密线人建立了联系。"}},faq={{q="哪里可以找到德拉维主教？",a="德拉维主教位于Stormwind Keep内的Petitioner's Chamber里，就在民众聚集向王室请愿的主入口旁边。",al={"德拉维主教位置","德拉维主教在哪里","德拉维主教 stormwind keep"}},{q="他在Stormwind Keep中担任什么角色？",a="他在王室宫廷中代表圣光教会，管理教会事务，为贵族提供建议，并为王国谨慎地处理敏感问题。",al={"德拉维主教职责","德拉维主教是谁","德拉维主教做什么"}},{q="他为什么要调查失踪的外交官？",a="这名外交官在前往塞拉摩会见吉安娜·普罗德摩尔的途中失踪了。德拉维主教怀疑有迪菲亚潜行者的干预，并利用安静且值得信赖的渠道进行调查，以免危机消息引起公众恐慌。",al={"德拉维主教失踪外交官","德拉维主教为什么关心外交官失踪"}},{q="德拉维主教与埃林·提亚斯有什么联系？",a="德拉维主教利用一个中间人网络（包括渔夫乔贞）向埃林·提亚斯传递信息，后者是一位奶酪大师，同时也是秘密为军情七处收集情报的特工。",al={"德拉维主教与提亚斯","德拉维主教军情七处联系人"}}},fp="14,183,17.380.0,18.424.1,34.156.0,35.187.0,45.212.0,41.174.1"}
P.entries["npc:blanchy"] = {n="Blanchy",s="老布兰奇是西奥多·法布隆和弗娜·法布隆夫妇所拥有的忠诚且勤劳的母马。她目前在西部荒野贾森农场附近的马车旁休息。她以温顺的性情和惊人的食量而闻名，在动荡不安的乡村生活中，她始终是主人身边可靠的伙伴。",h="老布兰奇是西奥多·法布隆和弗娜·法布隆夫妇所拥有的忠诚且勤劳的母马。她目前在西部荒野贾森农场附近的马车旁休息。她以温顺的性情和惊人的食量而闻名，在动荡不安的乡村生活中，她始终是主人身边可靠的伙伴。",kw={"blanchy","法布隆","贾森农场","燕麦","老布兰奇","弗娜·法布隆","西部荒野"},ang={["faction:Alliance"]="对于从艾尔文森林南下进入西部荒野的联盟旅人来说，帮助喂养老布兰奇通常是他们为当地流离失所的难民所做的第一件善举。"},sec={{t="忠实的农场帮手",b="在拉着法布隆一家的马车穿过西部荒野的尘土之前，布兰奇曾在暴风城的粮仓地带为法布隆夫妇的农场工作，在那里她以性格格外温顺、听话而闻名。多年的沉重劳作让她成了“老布兰奇”，而背井离乡的艰苦旅程也让她筋疲力尽。尽管看起来十分疲惫，她的胃口依然很好。如果旅人们能从周围的田野里收集一些燕麦带来喂她，弗娜便会用老布兰奇珍视的毛毯和饲料袋作为回报。"}},faq={{q="布兰奇的主人是谁？",a="布兰奇属于流浪在西部荒野的农户西奥多·法布隆和弗娜·法布隆。她是他们坚实的挽马，也是深爱的家庭伴侣。",al={"布兰奇的主人","布兰奇属于谁","法布隆的马"}},{q="布兰奇最初来自哪里？",a="没有记录显示布兰奇出生于何处。西部荒野的人们只知道她一直都是法布隆一家的马，在他们被迫踏上流亡之路前，她一直在他们的农场工作。",al={"布兰奇的起源","布兰奇来自哪里","年轻时的布兰奇"}},{q="为什么弗娜·法布隆需要燕麦来喂布兰奇？",a="多年的劳作加上在西部荒野危险的道路上长途跋涉，让老布兰奇精疲力尽。弗娜请求路过的冒险者从附近的农田里搜寻残留的燕麦袋，以帮助这匹忠实的马恢复体力。",al={"布兰奇的燕麦","为什么要喂布兰奇","法布隆的马累了"}},{q="在哪里可以找到布兰奇？",a="老布兰奇被拴在西部荒野北部贾森农场附近大道旁的法布隆马车边上。",al={"布兰奇的位置","老布兰奇在哪里","布兰奇地图"}}},fp="7,303,19.579.0,17.160.0,39.178.0,46.237.0,27.116.0"}
P.entries["npc:blind-hunter"] = {n="盲眼猎手",s="盲眼猎手是一只行踪诡秘的白化蝙蝠，栖息在剃刀沼泽的深处。与巢居在洞穴入口附近的普通蝙蝠不同，这种稀有生物徘徊在野猪人堡垒深处那永不见天日的黑暗之中。",h="盲眼猎手是一只行踪诡秘的白化蝙蝠，栖息在剃刀沼泽的深处。与巢居在洞穴入口附近的普通蝙蝠不同，这种稀有生物徘徊在野猪人堡垒深处那永不见天日的黑暗之中。",kw={"白化蝙蝠","盲眼猎手","沼泽蝙蝠","沼泽野兽","稀有蝙蝠","剃刀沼泽"},ang={["class:Hunter"]="对于在贫瘠之地穿行的兽王猎人来说，盲眼猎手是一种珍贵的猎物——既可以作为一种稀有的白化野兽来驯服，也可以作为制作优质地下弓箭的材料来源。"},sec={{t="沼泽深处",b="剃刀沼泽中布满了蜿蜒的荆棘和阴暗的地下洞穴。虽然普通的沼泽蝙蝠栖息在靠近地表、有微弱光线从外界射入的地方，但盲眼猎手已经完全适应了这片棘刺最深、最黑暗的角落。它苍白的白化外皮和乳白色的双眼，很可能是长期与自然光完全隔绝、世代繁衍的结果。"},{t="稀有的猎物",b="正如其名，学者和斥候们认为这种生物已经失去了大部分甚至全部的视力，转而依靠敏锐的听觉和回声定位能力在黑暗中追踪猎物。它极少露面，只偶尔在茂密的灌木丛中捕猎，对于洞穴探险者来说，能遇到这只幽灵般的野兽是一件值得称道的事。"}},faq={{q="盲眼猎手是什么？",a="盲眼猎手是一只罕见的白化蝙蝠，居住在剃刀沼泽最深处漆黑一片的隧道中。与入口附近常见的洞穴蝙蝠相比，它显得格外苍白且行踪难觅。",al={"谁是盲眼猎手","盲眼猎手是什么","盲眼猎手蝙蝠"}},{q="盲眼猎手出现在哪里？",a="它栖息在剃刀沼泽阴影笼罩的内部通道中，巢穴位于外界日光完全消失的阈值之后。",al={"盲眼猎手位置","在哪里可以找到盲眼猎手","盲眼猎手刷新"}},{q="盲眼猎手真的失明了吗？",a="虽然博物学家和探险家因其乳白色的双眼和深穴栖息地而怀疑它确实已经失明，但它的捕猎能力依然极其敏锐，在黑暗中依靠着灵敏的听觉和回声定位。",al={"它失明吗","盲眼猎手能看见吗"}},{q="猎人可以驯服盲眼猎手吗？",a="可以。有能力驾驭带翼掠食者的兽王猎人可以驯服盲眼猎手，对于那些有耐心追踪它的猎人来说，它是一个独特的苍白伙伴。",al={"我能驯服盲眼猎手吗","盲眼猎手可驯服吗","盲眼猎手宠物"}},{q="为什么盲眼猎手是白色的？",a="它是一个白化个体，其体色很可能是因为长期生活在远离阳光照射的永恒黑暗中而形成的，这与那些在洞口附近活动的蝙蝠不同。",al={"为什么它是白化病","为什么盲眼猎手是白色的","白化蝙蝠"}},{q="它与普通的沼泽蝙蝠有什么区别？",a="普通的沼泽蝙蝠有着典型的深色体色，生活在光线仍能射入的入口附近；而盲眼猎手体色苍白，生性孤僻，完全适应了深层的地下隧道。",al={"沼泽蝙蝠区别","沼泽蝙蝠与盲眼猎手对比"}}},fx={["7be10a10"]={q="盲眼猎手属于哪一方？",a="盲眼猎手是一头野兽，既不隶属于剃刀沼泽的野猪人，也不听命于任何外部势力。它是剃刀沼泽漆黑洞穴中的顶级捕食者，完全凭借动物本能生存，将任何闯入者都视为潜在猎物。",al={"盲眼猎手阵营","盲眼猎手是否与野猪人一伙","盲眼猎手属于哪一方"}},["5a3f492c"]={q="盲眼猎手想要什么？",a="作为一头未受驯服的地下生物，盲眼猎手没有政治野心，也没有恶意。它只是为了觅食而狩猎，并在剃刀沼泽最深处不见天日的洞穴中守卫自己与世隔绝的猎场，不让任何不幸闯入巢穴的人靠近。",al={"盲眼猎手的动机","盲眼猎手的目标","盲眼猎手想要什么"}},["66c6306f"]={q="盲眼猎手为什么在这里？",a="与在入口附近、阳光还能照进来的地方飞舞的普通沼泽蝙蝠不同，盲眼猎手栖息在剃刀沼泽最深处的漆黑地带。它早已习惯了永恒的黑暗，在远离地表的幽深洞穴中繁衍生息，从未见过光明。",al={"盲眼猎手为何在剃刀沼泽","盲眼猎手的位置缘由","盲眼猎手为何在这里"}}},fp="12,175,19.308.0,13.312.0,25.180.0,35.123.0,35.171.0,34.142.0,30.153.0,43.171.0"}
P.entries["npc:blind-mary"] = {n="盲眼玛丽",s="盲眼玛丽是一个受尽折磨的女妖，游荡在夜色镇东南方暮色森林里一处废弃的破败农舍中。她曾是一位虚荣而美丽的凡人女性，死后的暴力遭遇和转变令她悲痛欲绝，最终导致她为了逃避自己的新形态而自残。",h="盲眼玛丽是一个受尽折磨的女妖，游荡在夜色镇东南方暮色森林里一处废弃的破败农舍中。她曾是一位虚荣而美丽的凡人女性，死后的暴力遭遇和转变令她悲痛欲绝，最终导致她为了逃避自己的新形态而自残。",kw={"女妖","盲眼玛丽","夜色镇","暮色森林","幽灵的发丝","栖息地","眼镜","幽灵"},ang={["class:Priest"]="玛丽代表了一个因可怕创伤而灵魂受困的悲剧，她因悲伤和虚荣被困在生死之间。",["faction:Alliance"]="盲眼玛丽的悲剧命运对于夜色镇的保卫者来说，是一个深刻的提醒，警示着暮色森林的诅咒对普通镇民造成了多么深重的破坏。",["profession:Tailoring"]="织工们偶尔会寻找像玛丽这样的幽灵实体来获取幽灵的发丝，这是一种从空灵残骸中编织出来的精致超自然材料。"},sec={{t="悲剧的虚荣",b="在阴影笼罩暮色森林之前，玛丽是一位引人注目的凡人女性，她以自己的美貌为傲，从不离身心爱的眼镜。当亡灵席卷该地区时，玛丽和她的许多邻居一起遇害了。与那些在地下获得安息的灵魂不同，她的精神以一种空灵的女妖形态徘徊不去，注定要以这种可怕的半透明形态在凡人世界中游荡。"},{t="绝望致盲",b="在成为亡灵苏醒后，玛丽对自己的怪物镜像感到无比的悲伤、恐惧和愤怒。她无法忍受看到自己鬼魂般的面容，于是用双手挖出了自己的双眼，这样她就永远不必再审视自己。在极度痛苦中，她丢弃了心爱的眼镜，变成了一个盲眼、哀泣的幽灵，在废弃的家中游荡，苦苦抓着她失去的凡人生活的模糊记忆。"}},faq={{q="盲眼玛丽是谁？",a="盲眼玛丽是一个游荡在夜色镇东南郊外一处破败农舍里的女妖。在生前，她是一位美丽的当地女性，但在暮色森林陷入黑暗的过程中被杀害，并以亡灵的形态苏醒。",al={"盲眼玛丽是谁","盲眼玛丽背景故事","盲眼玛丽背景设定","暮色森林的盲眼玛丽"}},{q="为什么她被称为盲眼玛丽？",a="玛丽对她可怕的女妖形态感到无比的悲伤和绝望，于是用双手挖出了自己的双眼，这样她就永远不必再看到自己的镜像了。",al={"她为什么瞎了","盲眼玛丽怎么挖掉双眼的","盲眼玛丽的眼睛"}},{q="盲眼玛丽住在哪里？",a="她徘徊在被称为“盲眼玛丽的栖息地”的一座破败农舍里，该处位于暮色森林东部夜色镇的东南方。",al={"盲眼玛丽位置","盲眼玛丽在哪","盲眼玛丽的栖息地"}},{q="盲眼玛丽对活着的旅行者怀有敌意吗？",a="与周围森林中游荡的具有攻击性的食尸鬼和骷髅不同，盲眼玛丽并不会立即攻击旅行者。她仍然沉浸在悲伤之中，接近她那处废墟的人可以与她交谈。",al={"盲眼玛丽有敌意吗","盲眼玛丽会攻击吗","可以和盲眼玛丽交谈吗"}},{q="玛丽的眼镜发生了什么事？",a="在惊恐地撕掉双眼以逃避自己鬼魂状态后，玛丽丢弃了她珍视的眼镜，让它遗失在暮色森林闹鬼的区域某处。",al={"玛丽的镜子","盲眼玛丽的眼镜","她的镜子怎么了"}},{q="为什么冒险者要寻找盲眼玛丽？",a="旅行者和当地的工匠会在夜色镇执行任务时拜访玛丽，有时是为了给维克托·安特拉斯的观星装置寻找她旧日的眼镜，有时则是带着伊瓦夫人的鬼梳去收集用于制作特殊丝线的幽灵发丝。",al={"盲眼玛丽任务","为什么要拜访盲眼玛丽","盲眼玛丽任务线"}}},fx={d3776a58={q="盲眼玛丽属于哪一方？",a="盲眼玛丽不属于任何军队或阵营。尽管她是暮色森林悲剧中诞生的女妖，却没有加入天灾军团，也没有向生者开战。她被困在孤独的苦痛之中，对四处游荡的冒险者保持中立；只要有人愿意聆听她的悲伤，或归还她前世的遗物，她便会与之交谈。",al={"盲眼玛丽属于联盟还是部落","盲眼玛丽的阵营","玛丽属于哪一方"}},["45d21972"]={q="盲眼玛丽想要什么？",a="玛丽渴望找回失去的美貌，无法忍受别人看见自己。她曾随身携带一面镜子，如今仍会向询问的人提起它。但有人给她带来一把梳子时，那只会让她想起自己如今的模样，于是她便将梳子送走。",al={"玛丽想要什么","盲眼玛丽追求什么","盲眼玛丽的愿望"}},["5b1d02ea"]={q="盲眼玛丽为什么在这里？",a="盲眼玛丽徘徊在夜色镇东南方的一座废弃农舍中，因为她正是在那里悲惨地死去的。她被肆虐暮色森林的游荡亡灵杀死，随后化作哭泣的女妖，因悲伤与疯狂而被束缚在昔日家园的废墟之中。",al={"盲眼玛丽为何在暮色森林","盲眼玛丽为何徘徊在农舍","盲眼玛丽的位置与故事"}}},fp="10,242,15.388.0,18.344.0,18.181.0,29.116.0,28.120.0,42.207.0,38.155.0,39.241.0"}
P.entries["npc:bloodmage-drazial"] = {n="血法师德拉吉亚",s="血法师德拉吉亚是一名居住在诅咒之地北部的血精灵，修行奥术与血魔法。他和他的同伴血法师莱诺雷一起，研究这片红色荒原上的原生野兽，为往来的冒险者配制强力的炼金药剂。",h="血法师德拉吉亚是一名居住在诅咒之地北部的血精灵，修行奥术与血魔法。他和他的同伴血法师莱诺雷一起，研究这片红色荒原上的原生野兽，为往来的冒险者配制强力的炼金药剂。",kw={"诅咒野猪","诅咒之地","血法师","药剂","德拉吉亚","莱诺雷","scorpok","snickerfang"},ang={["class:Mage"]="德拉吉亚代表了血精灵中有争议的分歧，他公开利用血魔法和生物试剂来合成奥术增强效果，而不是完全依赖传统的肯瑞托法术。"},sec={{t="红色荒原上的炼金研究",b="血法师德拉吉亚在悲伤沼泽通往诅咒之地的北部隘口附近安营扎寨，钻研着一种独特的魔法。当许多高等精灵对禁忌之术避之唯恐不及，或对奎尔萨拉斯的命运感到绝望时，德拉吉亚和他的同伴莱诺雷却利用血魔法从这片恶劣的环境中汲取力量。荒原上那些受腐蚀的动物——Scorpok、Snickerfang和诅咒野猪——表现出奇怪且不自然的活力，德拉吉亚和莱诺雷认为这源于黑暗之门开启时释放的能量。通过从这些生物身上采集特定的器官和组织，德拉吉亚酿造出了极其不稳定的药剂，能赋予使用者巨大的物理力量、敏捷度和耐力。"},{t="一名独立的供应商",b="与驻扎在诅咒之地的许多阵营代理人不同，德拉吉亚行事超然。他对联盟和部落均无正式效忠，而是选择将自己的炼金技术交易给任何有胆量勇闯荒原并收集他所需原材料的冒险者。只要旅行者能带回当地掠食者的器官，德拉吉亚就很乐意让他的坩埚保持沸腾。"}},faq={{q="血法师德拉吉亚是谁？",a="血法师德拉吉亚是驻扎在诅咒之地北入口附近的一名血精灵法师。他和他的同伴莱诺雷一起研究当地的野生动物，并利用从该地区受腐蚀的野兽身上收集到的部位酿造强力的炼金试剂。",al={"谁是德拉吉亚","德拉吉亚背景故事","血法师德拉吉亚npc"}},{q="德拉吉亚为什么要收集动物部位？",a="诅咒之地的生物已经适应了在受腐蚀且充满魔法能量的土地上生存。德拉吉亚利用野猪、鬣狗、蝎子和蛇怪强有力的内脏来配制专门的药剂，以增强战士的体能。",al={"德拉吉亚为什么需要野猪肺","德拉吉亚的任务物品","德拉吉亚的动物器官"}},{q="德拉吉亚为联盟还是部落工作？",a="德拉吉亚对两大阵营均保持中立。他和莱诺雷并不关心暴风城与部落之间的战争，乐于与任何愿意为他们的魔法和炼金研究提供补给的冒险者进行交易。",al={"德拉吉亚阵营","德拉吉亚是部落还是联盟","联盟可以与德拉吉亚对话吗"}},{q="和他在营地里的另一个血精灵是谁？",a="他身边的精灵是他的同伴，血法师莱诺雷。这对同伴一起练习血魔法，并利用徘徊在诅咒之地各处的野兽酿造独特的药剂。",al={"德拉吉亚的同伴","谁和德拉吉亚在一起","莱诺雷"}}},fp="17,267,36.687.0,23.431.0,25.255.0,39.255.0,48.220.0,43.177.0"}
P.entries["npc:bloodmage-lynnore"] = {n="血法师莱诺雷",s="血法师莱诺雷是一位血精灵，她正在诅咒之地的北入口附近与她的兄弟血法师德拉吉亚一起扎营，钻研禁忌的血魔法。她通过从当地野兽的器官中调制强效炼金药剂来协助冒险者。",h="血法师莱诺雷是一位血精灵，她正在诅咒之地的北入口附近与她的兄弟血法师德拉吉亚一起扎营，钻研禁忌的血魔法。她通过从当地野兽的器官中调制强效炼金药剂来协助冒险者。",kw={"诅咒之地","血魔法","血法师莱诺雷","脑皮层混合饮料","砂囊口香糖","莱诺雷"},ang={["class:Mage"]="对于那些痴迷于非常规法术的法师来说，莱诺雷代表了一种难以捉摸且充满争议的奥术哲学分支，即操纵生命本质而非传统的地脉能量。",["faction:Horde"]="对于部落旅行者来说，莱诺雷是诅咒之地中一位有价值的联络人，她会与任何带来原材料的阵营成员交易独特的炼金药剂。"},sec={{t="血魔法大师",b="血法师莱诺雷与她的兄弟血法师德拉吉亚一起在诅咒之地的北入口附近扎营，她是东部王国中极其罕见的血魔法精灵修行者。她对诅咒之地严酷且腐化的环境丝毫不以为意，专注于研究当地野兽体内流动的潜在奥术和生命能量。若旅行者能为她带来当地动物的大脑和砂囊，她便能将这些恐怖的试剂蒸馏成特殊的药剂，从而极大提升智力和精神。"}},faq={{q="血法师莱诺雷是谁？",a="血法师莱诺雷是一位血精灵血法师，在诅咒之地的北入口附近扎营。她担任任务发布者和炼金专家，用强大的属性增强药剂来交换野兽部件。",al={"莱诺雷是谁","血法师莱诺雷背景故事","莱诺雷 诅咒之地"}},{q="在哪里可以找到血法师莱诺雷？",a="她与她的兄弟血法师德拉吉亚一起在诅咒之地的北入口附近扎营，即悲伤沼泽通往荒地的隘口处。",al={"莱诺雷位置","莱诺雷在哪里","如何找到血法师莱诺雷"}},{q="她酿造什么药剂？",a="莱诺雷利用从当地野生动物身上搜集到的部件——例如蛇颈龙大脑、秃鹫砂囊和笑面獠牙兽的下颚——来酿造稀有的补药，比如脑皮层混合饮料和砂囊口香糖，这些药剂能提供持久的智力和精神加成。",al={"莱诺雷增益效果","诅咒之地消耗品","脑皮层混合饮料"}}},fp="17,249,21.549.0,25.228.0,37.168.0,31.252.0"}
P.entries["npc:bloodmage-thalnos"] = {n="血法师萨尔诺斯",s="血法师萨尔诺斯是一位徘徊在血色修道院墓地区域的骷髅施法者。没人知道他生前是谁，但他最终被亡灵瘟疫所吞噬，如今他潜伏在血色十字军圣地的深处，渴望着复仇。",h="血法师萨尔诺斯是一位徘徊在血色修道院墓地区域的骷髅施法者。没人知道他生前是谁，但他最终被亡灵瘟疫所吞噬，如今他潜伏在血色十字军圣地的深处，渴望着复仇。",kw={"血法师","墓地","血色修道院","骷髅","萨尔诺斯"},ang={["class:Mage"]="萨尔诺斯展示了亡灵瘟疫是如何将一位天赋异禀的施法者扭曲成一个依然能操纵火焰和暗影的复仇之物。",["class:Priest"]="萨尔诺斯伫立在墓群之中，这是一个令人不安的迹象，表明血色十字军所有的狂热都没能阻止黑暗侵蚀他们自己的圣地。",["faction:Horde"]="被遗忘者在萨尔诺斯身上看到了他们曾经逃脱的命运：一个除了复仇已别无意志的亡灵法师，潜伏在血色十字军修道院的心脏地带。"},sec={{t="死后复生的法师",b="没有任何记录表明萨尔诺斯生前是谁。无论他的过去如何，他最终还是被亡灵瘟疫所吞噬。他并没有被净化或彻底消灭，而是作为一具枯萎的骷髅复生了，依然紧握着他的烈焰魔法和奥术造诣，渴望着复仇和更多的灵魂。"},{t="墓地之主",b="萨尔诺斯被困在修道院庭院墓穴的最深处，他指挥着幽灵和蹒跚的亡灵爪牙，攻击任何打扰他领地的人。他的存在对血色十字军来说是一个极其讽刺的矛盾：一个亡灵怪物就潜伏在他们神圣的大厅之下，这正是他们发誓要永远根除的恐怖。"}},faq={{q="血法师萨尔诺斯是谁？",a="萨尔诺斯是一位徘徊在血色修道院墓地的骷髅施法者。没人知道他生前是谁；他被亡灵瘟疫所吞噬，复生为一名依然渴望复仇的亡灵法师。",al={"萨尔诺斯是谁","萨尔诺斯背景故事","血法师萨尔诺斯信息"}},{q="为什么血色修道院里会允许一个亡灵骷髅存在？",a="血色十字军狂热地执行见亡灵就杀的政策，这使得萨尔诺斯的存活显得十分反常。他藏身于墓地尽头，置身于复活的墓穴和幽灵之间，徘徊在自己受诅咒的领地里，而不是在活着的十字军中自由行走。",al={"萨尔诺斯为什么在修道院","为什么血色十字军留着萨尔诺斯","血色十字军亡灵法师"}},{q="萨尔诺斯拥有什么力量？",a="尽管保留着血法师的头衔并以骷髅之躯复生，萨尔诺斯仍能操控烈焰法术和暗影魔法，并召唤复仇之灵和行尸来淹没墓地的入侵者。",al={"萨尔诺斯的法术","血法师萨尔诺斯的魔法","萨尔诺斯做什么"}},{q="萨尔诺斯是血精灵吗？",a="他最初的凡人血统尚不确定。仅凭“血法师”这个头衔并不能证明他就是血精灵。",al={"萨尔诺斯是高等精灵吗","萨尔诺斯的种族","萨尔诺斯是什么种族"}},{q="谁想要萨尔诺斯死？",a="萨尔诺斯对修道院墓地的入侵者怀有敌意。在这个时代，并没有针对击杀他的特定委托。",al={"萨尔诺斯任务","谁想要萨尔诺斯被杀","光明中的黑暗面萨尔诺斯"}}},fx={ee50c387={q="血法师萨尔诺斯属于哪一方？",a="萨尔诺斯不为任何人效力。在屈服于亡灵瘟疫后，他变成了一个完全受复仇欲望与邪恶力量驱使的生物。如今，这具亡灵骷髅在修道院的墓地中牢牢守卫着自己的领地，驱使幽灵和僵尸般的生物，屠杀所有挡路的生者。",al={"萨尔诺斯的阵营","萨尔诺斯为谁效力","萨尔诺斯是否属于血色十字军"}},fb23ba27={q="血法师萨尔诺斯想要什么？",a="萨尔诺斯因亡灵之躯而发疯，除了邪恶的复仇，几乎别无所求。这位被束缚在修道院墓地中的复仇法师操纵着不安的幽灵和复活的尸体，想要消灭所有胆敢踏入他诅咒领地的人。",al={"萨尔诺斯想要什么","萨尔诺斯的目标","萨尔诺斯的动机"}},["39b55bcf"]={q="为什么人们惧怕血法师萨尔诺斯？",a="萨尔诺斯是一名强大的亡灵施法者，统治着修道院的墓地。他向入侵者投掷火焰与暗影，高喊着复仇与更多灵魂。这样一个生物潜伏在血色十字军自己的亡者之中，更让人不寒而栗。",al={"萨尔诺斯为何令人畏惧","萨尔诺斯因何闻名","血法师萨尔诺斯的名声"}}},fp="17,258,21.282.0,23.362.0,25.203.0,59.256.0,31.200.0,24.111.0,23.130.0"}
P.entries["npc:bluff-runner-windstrider"] = {n="雷霆崖信使斯塔德尔",s="雷霆崖信使斯塔德尔是一位游荡的牛头人信使，常年在雷霆崖的台地上奔波。他在城内传递紧急公文，引导部落的冒险者前往诸如灰谷、菲拉斯和瘟疫之地等遥远的边疆。",h="雷霆崖信使斯塔德尔是一位游荡的牛头人信使，常年在雷霆崖的台地上奔波。他在城内传递紧急公文，引导部落的冒险者前往诸如灰谷、菲拉斯和瘟疫之地等遥远的边疆。",kw={"灰谷","雷霆崖信使","莫沙彻营地","信使","莫高雷","雷霆崖","斯塔德尔"},ang={["faction:Horde"]="斯塔德尔在莫高雷宁静的平原与部落为资源和生存而战的血腥前线之间，起到了一座至关重要的桥梁作用。",["race:Tauren"]="像斯塔德尔这样的传统奔跑者，在不依赖现代机械或外来邮政网络的情况下，保持了分散的部落与中央长者之间的联系。"},sec={{t="台地上的信使",b="雷霆崖高耸的台地需要快捷的脚步来确保其领袖和来访者能及时获取讯息，而雷霆崖信使斯塔德尔承担了这一重要职责。他不断地在牛头人主城的吊桥和道路上奔跑，担任着城镇传令官和信使的角色。当卡利姆多或东部王国的关键哨所需要增援时，斯塔德尔会拦下过往的勇士，将消息传达给他们并召集他们响应战斗的号召。"},{t="边疆的呼唤",b="斯塔德尔的公文传达范围远远超出了莫高雷宁静的边界。他指引冒险者向北前往灰谷，加入碎木岗哨塞娜尼·雷心的伟大狩猎；引导经验丰富的斥候向南前往菲拉斯深处的莫沙彻营地；并传达有关西瘟疫之地持续不断的亡灵威胁的严峻警告。通过他，莫高雷的部落核心始终与部落更广阔的冲突紧密相连。"}},faq={{q="雷霆崖信使斯塔德尔是谁？",a="雷霆崖信使斯塔德尔是一位在雷霆崖徘徊的牛头人信使。他负责分享新闻并召集有能力的部落旅行者，以协助艾泽拉斯各地的紧急战役。",al={"斯塔德尔npc","雷霆崖信使","斯塔德尔是谁"}},{q="我在哪里可以找到雷霆崖信使斯塔德尔？",a="斯塔德尔并不固定待在一个地方。他不断地在雷霆崖的桥梁和露台上慢跑，通常在中央台地和邻近的高地之间来回穿梭。",al={"斯塔德尔位置","雷霆崖信使在哪里","找到斯塔德尔"}},{q="斯塔德尔提供什么任务？",a="他提供引导任务，将成长中的冒险者指引向遥远的争议地区，包括灰谷的狩猎活动、在菲拉斯建立莫沙彻营地，以及对瘟疫之地的战斗号召。",al={"斯塔德尔任务","他给什么任务","雷霆崖信使职责"}},{q="他为什么被称为“雷霆崖信使”？",a="牛头人依靠敏捷、耐力极强的奔跑者在雷霆崖崎岖的台地、悬崖和悬索桥上穿梭传递信息，因为在这些地方骑乘坐骑往往笨重而缓慢。",al={"什么是雷霆崖信使","雷霆崖信使头衔"}}},fp="24,195,24.385.0,21.397.0,32.161.0,42.138.0,35.188.0,34.168.0"}
P.entries["npc:bolvar-fordragon"] = {n="Bolvar Fordragon",s="伯瓦尔·弗塔根公爵在瓦里安·乌瑞恩国王神秘失踪后，担任暴风城的摄政王以及军队的总指挥官。他站在Stormwind Keep中那位年幼的君长安度因·乌瑞恩国王身边，努力在日益加剧的国内动荡中维持王国的稳定。尽管为人刚正不阿，但伯瓦尔在军事决策上往往会受到皇家顾问女伯爵卡特拉娜·普瑞斯托的影响和阻挠。",h="伯瓦尔·弗塔根公爵在瓦里安·乌瑞恩国王神秘失踪后，担任暴风城的摄政王以及军队的总指挥官。他站在Stormwind...",kw={"安度因·乌瑞恩国王","伯瓦尔","弗塔根","大领主","卡特拉娜·普瑞斯托","摄政王","stormwind keep"},ang={["class:Paladin"]="伯瓦尔代表了联盟武力圣骑士的巅峰，尽管政治阴谋不断加剧，他依然体现了对圣光的坚定奉献和对人民的不懈责任。",["faction:Alliance"]="作为暴风城的总指挥官，伯瓦尔是人类军队的行政首脑，在处理局部叛乱与履行更广泛的联盟义务之间保持平衡。"},sec={{t="王国摄政",b="当瓦里安国王在前往塞拉摩岛参加和平峰会的途中失踪后，暴风城陷入了政治混乱。十岁的安度因王子加冕继位以保持王权的延续，但实际的统治权交由摄政王伯瓦尔·弗塔根公爵掌握。伯瓦尔是一位受人尊敬、忠于王室的圣骑士，但他正面临巨大的压力。暴风城的军队在西部荒野、Redridge和暮色森林等地兵力薄弱，捉襟见肘。更糟糕的是，伯瓦尔频繁听从女伯爵卡特拉娜·普瑞斯托的建议，而她那轻描淡写的劝诫一再阻碍伯瓦尔向边缘城镇派遣皇家部队。"},{t="谎言之网",b="在王室法庭的幕后，伯瓦尔受到的束缚比他意识到的还要严重。尽管城镇长官和边境警官请求增援以对抗迪菲亚潜行者和黑石兽人，女伯爵普瑞斯托却巧妙地操纵皇家法令，并贬低所有关于危险的报告。伯瓦尔尊重贵族的建议，在没有确凿证据的情况下犹豫不决，无意中让王权陷入了瘫痪。只有当令人信服的证据出现时——例如来自塞拉摩的调查警告或失踪的实地军官——摄政王才会绕过常规的宫廷礼仪，去招募独立的冒险者。"}},faq={{q="为什么是伯瓦尔在执政，而不是瓦里安国王？",a="瓦里安·乌瑞恩国王在乘船前往塞拉摩岛参加外交峰会的途中，在可疑的情况下失踪了。在他缺席期间，瓦里安十岁的儿子安度因加冕为王以维持政治秩序，而伯瓦尔·弗塔根公爵则被任命为摄政王，在国王被寻回之前代为管理王国并指挥军队。",al={"国王在哪里","为什么是伯瓦尔负责","谁是摄政王"}},{q="为什么伯瓦尔不派遣士兵去支援Redridge或西部荒野？",a="暴风城的常备军在守卫核心领土和边境时已是兵力薄弱。此外，伯瓦尔的首席顾问女伯爵卡特拉娜·普瑞斯托一再质疑来自湖畔镇等地报告的紧急性，称其为夸大其词，并建议不要调动皇家部队。由于缺乏军事证据，伯瓦尔转而授权独立的冒险者进行干预。",al={"为什么没有暴风城军队","为什么伯瓦尔不派援军","湖畔镇的军队"}},{q="伯瓦尔与女伯爵卡特拉娜·普瑞斯托的关系如何？",a="女伯爵卡特拉娜·普瑞斯托是暴风城王座的首要皇家顾问。伯瓦尔尊重她的政治敏锐度和对贵族事务的深厚了解。然而，她不断利用自己的影响力劝导伯瓦尔保持克制，敦促他驳回关于巨龙、兽人和迪菲亚阴谋的传言。",al={"伯瓦尔与普瑞斯托","女伯爵普瑞斯托对伯瓦尔的身份"}},{q="伯瓦尔与年幼的安度因王子有什么联系？",a="伯瓦尔与安度因没有血缘关系，但他担任着这位年轻国王的坚定保护者、监护人和导师。伯瓦尔站在Stormwind Keep中安度因的王座旁，保护这个孩子免受宫廷阴谋的侵害，并确保乌瑞恩王朝在瓦里安回归前保持稳固。",al={"安度因与伯瓦尔","伯瓦尔是安度因的父亲吗"}}},fp="16,333,19.514.0,15.531.1,44.297.0,60.355.0,56.256.0,51.248.0"}
P.entries["npc:braelyn-firehand"] = {n="布莱林·火拳",s="布莱林·火拳是一位居住在石爪山脉烈日石居、低调生活在部落之中的精灵奥术修行者。她声称自己有兴趣清除高地上的神秘阻碍，并雇佣旅行者去打击石爪峰的暗夜精灵守卫。",h="布莱林·火拳是一位居住在石爪山脉烈日石居、低调生活在部落之中的精灵奥术修行者。她声称自己有兴趣清除高地上的神秘阻碍，并雇佣旅行者去打击石爪峰的暗夜精灵守卫。",kw={"布莱林","塞纳留斯","火拳","上层精灵","欧尔达努斯","石爪","烈日石居"},ang={["class:Druid"]="她蓄意屠杀塞纳留之子并洗劫猛禽洞穴，这是对自然平衡的可恶罪行。",["class:Mage"]="布莱林乐于谈论能量线和神秘阻碍，以此吸引那些了解大地上奥术魔法流动的同行。",["faction:Horde"]="布莱林乐意雇佣部落游荡者去打击暗夜精灵，将卡利姆多正在进行的领土冲突作为掩护，来推行更深层、更黑暗的计划。"},sec={{t="不速之客",b="在烈日石居的牛头人小屋和简朴的兽人帐篷中，布莱林·火拳显得格外显眼：一个公开居住在偏远部落定居点里的血精灵，这实属罕见。营地的萨满祭司和首领们容忍了她的存在，似乎并没有察觉到她真正的忠诚对象。布莱林将自己包装成一名醉心于当地魔法流动的观察者，热衷于雇佣路过的部落雇佣兵来处理遍布山岩的危险实地任务。"},{t="对林地的积怨",b="布莱林指使她的盟友去攻击驻扎在石爪峰高处的暗夜精灵德鲁伊和塞纳留斯的神圣后代。她声称这些德鲁伊阻碍了周围的能量线，抑制了整个山峰的奥术能量流动。然而，她真正的目的极其个人化：她对守护者欧尔达努斯怀有深仇大恨，回忆起很久以前，他竟自以为比上层精灵还要高贵。她心甘情愿地花钱雇佣部落旅行者去追杀欧尔达努斯，并带回他的头颅。"},{t="与加德纳尔的联系",b="布莱林的怨恨并非仅仅是闲散的积怨；她的目标与在费伍德森林的加德纳尔活动的暗影议会分支完全一致。通过鼓励部落勇士系统性地屠杀暗夜精灵和守卫圣峰的守护者，她在普通边境冲突的掩护下，为更黑暗的力量清除了障碍，同时也掩盖了她邪恶的从属关系。"}},faq={{q="谁是布莱林·火拳？",a="布莱林·火拳是一位住在石爪山脉烈日石居的精灵法师。尽管身处部落之中，她仍在推行自己针对石爪峰暗夜精灵守卫的奥术计划。",al={"布莱林是谁","布莱林·火拳背景故事","烈日石居里的精灵"}},{q="为什么一个精灵会待在烈日石居？",a="烈日石居是一个繁忙而与世隔绝的边境避难所。布莱林利用营地的包容性以及源源不断的部落战士，将她针对暗夜精灵的个人打击行动外包出去，而不会引起定居点领导层的直接怀疑。",al={"她为何待在部落","布莱林为何在烈日石居","石爪山脉的血精灵"}},{q="她想在石爪峰达成什么目的？",a="她要求冒险者去攻击石爪峰的德鲁伊和塞纳留斯的后代，声称他们抑制了魔法的流动。她随后对守护者欧尔达努斯的追杀最终引向了灰谷的林中树居。",al={"布莱林的任务目标","为什么要杀欧尔达努斯","布莱林·火拳的任务"}},{q="她和守护者欧尔达努斯有什么过往？",a="布莱林声称在遥远的过去就认识守护者欧尔达努斯。她对他怀有强烈的怨恨，声称他极其傲慢，甚至自认为比古老的上层精灵还要高贵。",al={"布莱林与欧尔达努斯","她如何认识欧尔达努斯","欧尔达努斯背景故事"}},{q="布莱林·火拳声称在研究什么？",a="布莱林声称石爪峰的德鲁伊和塞纳留斯的后代正在限制魔法的流动。她希望除掉他们，以便自己能够汲取那股力量。",al={"布莱林真实的阵营","布莱林与暗影议会","她为谁效力"}},{q="布莱林是法师还是术士？",a="她修行奥术魔法，并用火球术进行战斗。",al={"布莱林的职业","布莱林是术士吗","布莱林·火拳的法术"}}},fx={deec6fbf={q="布莱林·火拳与谁有关联？",a="布莱林为加德纳尔的一位主子效力，并与暗影议会有所牵连。她招募部落旅人，派他们袭击暗夜精灵和塞纳留斯的子嗣。",al={"布莱林·火拳的关系","布莱林与谁有联系","布莱林·火拳的盟友"}}},fp="16,139,17.325.0,26.380.1,16.270.1,24.202.0,42.208.0,43.203.0,40.184.0,51.148.2,31.57.2"}
P.entries["npc:braenna-flintcrag"] = {n="布莱纳·火崖",s="布莱纳·火崖是一位驻扎在铁炉堡Mystic Ward的Hall of Mysteries里的矮人牧师训练师。她教导圣光的虔诚追随者，指引矮人侍僧发展他们的精神修行和治疗艺术。当暗夜精灵牧师被传唤回达纳苏斯的Temple of the Moon时，她也会负责传达消息。",h="布莱纳·火崖是一位驻扎在铁炉堡Mystic Ward的Hall of Mysteries里的矮人牧师训练师。她教导圣光的虔诚追随者，指引矮人侍僧发展他们的精神修行和治疗艺术。当暗夜精灵牧师被传唤回达纳苏斯的Temple...",kw={"布莱纳·火崖","hall of mysteries","圣光","铁炉堡","mystic ward","牧师训练师","回归家园"},ang={["class:Priest"]="对于矮人和联盟牧师来说，布莱纳是铁炉堡中一位值得信赖的导师，可以学习基本的法术并掌握圣光之道。",["race:Dwarf"]="布莱纳代表了铁炉堡矮人中根深蒂固的精神信仰，将尚武的坚韧与对圣光的虔诚服务结合在了一起。"},sec={{t="Hall of Mysteries的向导",b="布莱纳·火崖居住在铁炉堡Mystic Ward的Hall of Mysteries那宁静的壁龛中，作为一名尽职的牧师训练师为联盟服务。虽然铁炉堡以其轰鸣的熔炉和尚武的战士而闻名，但像布莱纳这样虔诚的矮人致力于照料卡兹莫丹的精神福祉。她指导响应圣光召唤的新手，传授在日益危险的世界中生存所需的恢复性治疗和防御性结界的双重修行。"}},faq={{q="布莱纳·火崖是谁？",a="布莱纳·火崖是一位矮人牧师训练师，位于铁炉堡Mystic Ward的Hall of Mysteries内。她教育牧师学习新的圣光祷言、法术和精神修行。",al={"布莱纳·火崖","布莱纳是谁","牧师训练师布莱纳"}},{q="在哪里可以找到布莱纳·火崖？",a="你可以在Hall of Mysteries内找到她，这是一个致力于奥术和神圣艺术的大型圣所，位于铁炉堡的Mystic Ward。",al={"布莱纳在哪里","布莱纳·火崖位置","寻找布莱纳·火崖"}},{q="她为旅行者提供什么服务？",a="她为联盟的牧师提供训练和等级提升。她还会告知来访的暗夜精灵牧师他们何时被传唤回达纳苏斯的Temple of the Moon，就像任务“回归家园”中那样。",al={"布莱纳的服务","布莱纳做什么","布莱纳能训练我吗"}},{q="她和卡兹莫丹的其他任何人有关系吗？",a="她与瑟尔曼·火崖共有火崖这个姓氏，这表明她属于卡兹莫丹内一个显赫的矮人家族。",al={"火崖家族","瑟尔曼·火崖亲属","布莱纳·火崖亲属"}}},fp="17,240,32.337.0,25.126.0,35.78.0,44.175.0,44.135.0"}
P.entries["npc:brainwashed-noble"] = {n="被洗脑的贵族",s="被洗脑的贵族是一位难以捉摸的被俘贵族，他位于西部荒野死亡矿井外的地下洞穴深处。他失去了自主权，在魔法的操纵下，他并没有行走在暴风城宏伟的大厅中，而是与亡灵爪牙一起为迪菲亚潜行者效力。",h="被洗脑的贵族是一位难以捉摸的被俘贵族，他位于西部荒野死亡矿井外的地下洞穴深处。他失去了自主权，在魔法的操纵下，他并没有行走在暴风城宏伟的大厅中，而是与亡灵爪牙一起为迪菲亚潜行者效力。",kw={"被洗脑的贵族","死亡矿井","迪菲亚潜行者","贵族议会","月溪镇","暴风城","西部荒野"},ang={["class:Mage"]="这位贵族依赖魔法法杖和变形术之类的奥术诡计，这表明在心智破碎之前，他在首都接受过正规的魔法教育。",["race:Human"]="看到一位王国同僚沦为西部荒野深处毫无心智的哨兵，这令人毛骨悚然，也提醒着人们迪菲亚潜行者对暴风城统治精英阶层怀有怎样深刻的怨恨。"},sec={{t="潜行者的棋子",b="被洗脑的贵族在通往死亡矿井的阴暗且遍布白骨的通道中徘徊，与周围绝望的强盗和腐烂的尸体形成了鲜明的对比。他身穿残破的高贵服饰，几乎可以肯定在落入艾德温·范克里夫手中之前，他曾是暴风城贵族议会的一员或后裔。迪菲亚潜行者并没有为了黄金而勒索他，而是用附魔扭曲了他的心智，将这位统治阶级的成员变成了一个守护他们秘密避难所的施法守卫。他悲惨的存在充分说明了为了向那些拒绝支付工钱的同僚复仇，潜行者可以不择手段。"}},faq={{q="被洗脑的贵族是谁？",a="他是一位人类贵族，推测来自暴风城的贵族议会，被迪菲亚潜行者俘虏并用魔法奴役在死亡矿井的洞穴深处。",al={"被洗脑的贵族是谁","被洗脑的贵族是什么","死亡矿井里的贵族"}},{q="为什么暴风城的贵族会在死亡矿井的洞穴里？",a="迪菲亚潜行者对暴风城的贵族阶层怀有极深的仇恨，起因是在重建城市后未支付的债务。俘虏、奴役并扭曲一位贵族的心智，既能获得有用的魔法劳动力，也是一种个人报复。",al={"他为什么在死亡矿井","为什么贵族在洞穴里"}},{q="被洗脑的贵族在哪里可以找到？",a="在月溪镇通往死亡矿井入口的巨大洞穴隧道中，他并不常见，他专门徘徊在有骷髅亡灵出没的通道里。",al={"被洗脑的贵族位置","他在哪里刷新"}},{q="他是如何被洗脑的？",a="虽然确切的施法者尚不得而知，但迪菲亚潜行者在整个西部荒野雇佣了数名叛变的施法者和附魔师，他们完全有能力通过强制性的法术来扭曲俘虏的心智。",al={"谁洗脑了他","他如何被控制"}}},fp="17,224,25.460.1,29.181.0,52.204.1,41.143.1,23.151.0"}
P.entries["npc:brandur-ironhammer"] = {n="布兰度尔·铁锤",s="布兰度尔·铁锤是一位矮人圣骑士训练师，居住在铁炉堡的Hall of Mysteries内。他引导圣光的有志拥护者完成早期的仪式，考验他们的虔诚，并将他们派遣到联盟各处。",h="布兰度尔·铁锤是一位矮人圣骑士训练师，居住在铁炉堡的Hall of Mysteries内。他引导圣光的有志拥护者完成早期的仪式，考验他们的虔诚，并将他们派遣到联盟各处。",kw={"布兰度尔","hall of mysteries","铁炉堡","铁锤","mystic ward","圣骑士","蒂萨·热炉","神圣之书","训练师"},ang={["class:Paladin"]="对于矮人和联盟圣骑士来说，布兰度尔是铁炉堡的一位重要导师，提供必要的武艺训练、神圣印记以及通往进阶神圣试炼的指引。",["race:Dwarf"]="布兰度尔是卡兹莫丹矮人圣骑士传统的典范，他们在铁炉堡的心脏地带将钢铁武艺与对圣光的崇敬结合在了一起。"},sec={{t="Mystic Ward的向导",b="布兰度尔·铁锤驻扎在宁静的Hall of Mysteries壁龛中，通过教授新手圣骑士圣光之道来服务联盟。与他的同僚蒂萨·热炉一道，布兰度尔密切关注着年轻的矮人拥护者，指导他们完成“神圣之书”的试炼。虽然他深信自己的神圣职责，但也承认在蒂萨的直言劝诫下，他有着个人的缺点，并正努力克服自己的嫉妒心，以保持圣光战士所要求的内在纯洁。"},{t="联系白银之手",b="布兰度尔是铁炉堡与更广泛的联盟兄弟会之间的重要联络人。当人类新兵来到这座矮人山城时，他会将他们引向南方的暴风城Cathedral of Light，去寻找达索瑞恩·拉尔。随着圣骑士在野外变得更加成熟，布兰度尔会协调他们前往西瘟疫之地的寒风营地等战场，最终将资深的十字军战士送往格雷森·沙东布瑞克公爵处，以承担战争坐骑的艰巨试炼。"}},faq={{q="布兰度尔·铁锤在哪里？",a="布兰度尔位于铁炉堡北侧Mystic Ward里的Hall of Mysteries内。",al={"布兰度尔·铁锤位置","寻找布兰度尔·铁锤","布兰度尔在哪里"}},{q="布兰度尔·铁锤在圣骑士扮演什么角色？",a="他是一位圣骑士职业训练师，教授新的法术和技能，指导新兵完成诸如“神圣之书”之类的职业任务，并引导资深圣骑士前往联盟各处进行进阶试炼。",al={"布兰度尔圣骑士训练师","布兰度尔的作用","布兰度尔的职责"}},{q="谁是布兰度尔在Hall of Mysteries里的同僚？",a="布兰度尔与蒂萨·热炉一起工作，她是Hall of Mysteries里的另一位矮人圣骑士训练师。蒂萨是他坦诚的导师，她指出嫉妒是他的弱点——这也是布兰度尔发誓要克服的一个缺点。",al={"布兰度尔的伙伴","谁与布兰度尔共事","与蒂萨·热炉的关系"}},{q="为什么布兰度尔要把圣骑士送到暴风城？",a="在铁炉堡训练的人类圣骑士通常会被布兰度尔引向暴风城Cathedral of Light的达索瑞恩·拉尔或格雷森·沙东布瑞克公爵，以确保他们进行各自王国所规定的正式仪式。",al={"布兰度尔暴风城任务","为什么去见达索瑞恩·拉尔","布兰度尔人类圣骑士"}},{q="布兰度尔与对抗天灾军团的战斗有联系吗？",a="是的。布兰度尔会传达阿什拉姆·瓦洛菲斯特指挥官的紧急呼吁，派遣纯洁而英勇的资深圣骑士前往西瘟疫之地边缘的寒风营地协助联盟远征军。",al={"布兰度尔瘟疫之地","寒风营地布兰度尔","阿什拉姆·瓦洛菲斯特布兰度尔"}}},fp="18,108,26.330.0,26.354.0,36.98.0,52.156.0,47.168.0,49.177.0,63.204.0"}
P.entries["npc:brann-bronzebeard"] = {n="Brann Bronzebeard",s="Brann Bronzebeard是国王麦格尼·铜须和被认为已经阵亡的穆拉丁最小的弟弟。他作为一名无与伦比的探险家、考古学家以及探险者协会的创始领导人，在整个艾泽拉斯享有盛誉。出于对泰坦遗迹和古代历史无法满足的好奇心，他的探险热情将他带到了希利苏斯致命的荒原深处。他在希利苏斯南部的探险队同伴们正等待着他最新探险的消息。",h="Brann...",kw={"安其拉","brann","铜须","探险者协会","frankal","glibb","natalia mar'alith","rutgar","甲虫之墙","希利苏斯"},ang={["faction:Alliance"]="Brann的探险工作直接为联盟的知识积累和档案建设提供了素材，不过他经常毫无踪迹地消失的习惯常常让铁炉堡的领导层感到头疼。",["race:Dwarf"]="作为国王麦格尼最小的弟弟，Brann体现了矮人对于挖掘泰坦遗产根源的热情。"},sec={{t="皇室流浪者",b="当他的大哥麦格尼在铁炉堡的王座上发号施令，穆拉丁在前线战场服役时，Brann却选择了广阔的荒野。他是第二次战争中的一名老兵。然而，和平时期将他坚韧的体魄引向了发掘被遗忘的过去。作为探险者协会的领导人，Brann绘制了东部王国大片地区的地图——从艾尔文森林到野性难驯的祖尔格拉布丛林——随后他又将目光投向了无尽之海彼岸，去探寻古代卡利姆多的奥秘。"},{t="希利苏斯的麻烦",b="受塞纳里奥议会关于上古之神克苏恩和沉睡的其拉虫群的报告吸引，Brann前往南方，与探险家同伴鲁特加尔·雕石和Frankal Stonebridge一起在希利苏斯南部建立了铜须营地。悲剧发生时，牧师Natalia Mar'alith因流沙之鳞中低语的恐怖而疯狂，袭击了他们的营地。当Brann拒绝了她要求带他们回到雷戈虫巢的命令时，她发狂并进行了攻击，Brann、他的队员以及他的宠物猿猴Glibb费了很大劲才击退了她。"},{t="甲虫之墙之外",b="在遭遇了这次可怕的袭击后，这位勇敢的考古学家非但没有撤退，反而对进入甲虫之墙后被封印的王国产生了执念。Brann发现了一条隐藏的地下隧道，可以完全绕过那道古老的屏障，于是他独自冒险进入，将Glibb留给他的探险队照顾，并写下了严厉的命令，要求队员们给这只猿猴提供充足的食物、水和充满爱心的拥抱。他的同伴们仍滞留在希利苏斯南部，绝望地等待着来自其拉虫巢内部的消息。"}},faq={{q="Brann Bronzebeard是谁？",a="他是铁炉堡国王麦格尼·铜须最小的弟弟，也是矮人探险者协会的共同创始人和推动者。Brann不是那种坐在议事厅里的人，他是一位传奇的考古学家和制图师，足迹遍布艾泽拉斯最危险的边境，只为发掘泰坦神器和失落的文明。",al={"brann是谁","brann背景故事","brann bronzebeard背景"}},{q="Brann Bronzebeard现在在哪里？",a="他的踪迹指向希利苏斯，鲁特加尔·雕石和Frankal Stonebridge在那里留守着铜须营地。他们可能有关于他最新探险的情报。",al={"brann位置","在哪里可以找到brann","brann在希利苏斯的哪里"}},{q="他的希利苏斯营地发生了什么？",a="鲁特加尔·雕石和Frankal Stonebridge有一些关于这次探险的令人不安的消息。与他们交谈就能了解营地里发生了什么。",al={"铜须营地发生了什么","谁袭击了brann的营地","natalia袭击brann"}},{q="Glibb是谁？",a="Glibb是Brann Bronzebeard的猿猴伙伴，现在正和希利苏斯的铜须营地的探险家们待在一起。",al={"glibb猿猴","brann的猴子","brann宠物"}},{q="Brann参加过第二次战争吗？",a="是的。Brann是第二次战争的老兵，尽管在和平时期他将自己的力量转向了发掘被遗忘的过去。",al={"brann第二次战争","brann在联盟军队吗","brann和穆拉丁战争"}},{q="为什么Brann对希利苏斯感兴趣？",a="Brann被塞纳里奥议会关于上古之神克苏恩、泰坦历史以及被困的其拉帝国的低语吸引到了沙漠，这促使他寻找一条越过甲虫之墙封印的道路，以便亲自考察遗迹。",al={"为什么brann去希利苏斯","brann在希利苏斯的目的","brann克苏恩"}}},fp="17,421,16.500.0,19.540.1,22.520.1,25.329.0,37.169.0,38.138.0,13.109.0,34.123.0,36.225.0"}
P.entries["npc:branstock-khalder"] = {n="布兰斯托克·卡德尔",s="布兰斯托克·卡德尔是驻扎在寒脊山谷安威玛尔的牧师训练师。他性格友善且脚踏实地，在引领新手矮人牧师接触圣光的同时，也时刻警惕着外围日益严重的穴居人威胁。",h="布兰斯托克·卡德尔是驻扎在寒脊山谷安威玛尔的牧师训练师。他性格友善且脚踏实地，在引领新手矮人牧师接触圣光的同时，也时刻警惕着外围日益严重的穴居人威胁。",kw={"安威玛尔","布兰斯托克","寒脊山谷","丹莫罗","卡德尔","圣光","牧师","训练师"},ang={["class:Priest"]="对于矮人牧师来说，布兰斯托克·卡德尔是你遇到的第一位精神向导，他会为你解读最初的神圣符文，并向你介绍圣光的防御和治疗法术。",["race:Dwarf"]="布兰斯托克体现了铁炉堡矮人务实、脚踏实地的虔诚品质，他将对圣光的崇敬信仰与对抗严寒和当地穴居人入侵的坚韧精神完美地融合在了一起。"},sec={{t="寒脊山的引路人",b="在喧闹的安威玛尔大厅内，布兰斯托克·卡德尔耐心地指导着那些踏上精神修行之路的准牧师们。作为一名对圣光有着虔诚信仰的随和矮人，他帮助新晋的侍僧掌握最初的祷言和神圣符文。尽管他的主要职责是提供精神指导，但布兰斯托克也敏锐地察觉到了山谷中不断增加的危险——最显著的便是威胁着当地登山者的穴居人入侵。一旦新手展现出对圣光足够的掌控力，他便会指引他们穿过寒脊山小径，前往卡拉诺斯，从他的上级马克萨恩·安沃尔那里寻求进一步的指导。"}},faq={{q="布兰斯托克·卡德尔是谁？",a="布兰斯托克·卡德尔是一位矮人牧师训练师，位于寒脊山谷的起始哨站安威玛尔。他教导初出茅庐的牧师圣光之道，并为面对山谷艰苦环境的保卫者们提供精神上的建议。",al={"布兰斯托克背景故事","布兰斯托克是谁","安威玛尔牧师训练师"}},{q="布兰斯托克接下来会把学生送到哪里？",a="当年轻的牧师磨练好了他们早期的能力并协助解决了寒脊山谷的麻烦后，布兰斯托克会让他们穿过寒脊山小径前往卡拉诺斯，指引他们去找他的上级马克萨恩·安沃尔神父。",al={"离开布兰斯托克后去哪里","布兰斯托克后续任务","安威玛尔牧师之路"}},{q="布兰斯托克在寒脊山谷担心什么？",a="除了精神指导的职责外，布兰斯托克对最近蔓延至寒脊山谷的穴居人入侵深感忧虑，他认识到圣光的力量对于治愈伤痛和加强山谷防御刻不容缓。",al={"安威玛尔的麻烦","布兰斯托克的担忧","寒脊山谷穴居人威胁"}},{q="他对非牧师职业的人说什么？",a="即使你选择了其他的道路，布兰斯托克也会给你一个谦逊的建议：永远不要背弃圣光，并提醒路人，信仰或许正是未来某天拯救他们性命的关键。",al={"布兰斯托克语录","布兰斯托克闲谈文本"}}},fp="17,140,27.331.0,25.149.0,44.124.0,54.120.0,32.93.0"}
P.entries["npc:brave-moonhorn"] = {n="卫兵穆赫·月角",s="卫兵穆赫·月角是一位牛头人斥候，驻守在贫瘠之地南端边界的升降梯顶端。从这处峭壁之上，他密切注视着通往千针石林的入口，并提醒过往的旅人前方存在的危险。",h="卫兵穆赫·月角是一位牛头人斥候，驻守在贫瘠之地南端边界的升降梯顶端。从这处峭壁之上，他密切注视着通往千针石林的入口，并提醒过往的旅人前方存在的危险。",kw={"卫兵穆赫·月角","半人马","峭壁卫兵图林·长角","乱风岗","升降梯","恐怖图腾","千针石林"},ang={["faction:Horde"]="穆赫·月角担任着部落的一名前哨，指引刚抵达峡谷的人们前往安全地带和防御森严的乱风岗高地。",["race:Tauren"]="穆赫·月角对恐怖图腾的深深戒备，反映了效忠于凯恩·血蹄的传统部族与行事隐秘的恐怖图腾氏族之间日益激化的矛盾与不信任。"},sec={{t="升降梯哨兵",b="卫兵穆赫·月角栖身在千针石林的陡峭断崖之上，驻守着这片北部平原与峡谷地带的交汇处。他的主要职责是监视峡谷下方移动的区域威胁，特别是敌对的半人马氏族。任何想要下降进入千针石林的人通常都会先遇到他，并在踏上升降梯那巨大的平台前收到至关重要的警告。"},{t="不安的阴影",b="除了半人马不断威胁之外，穆赫·月角对来自恐怖图腾部族的牛头人同胞也深感忧虑。他告诫过往的部落盟友要与他们保持距离，并指出他们在千针石林附近的行径日益古怪且可疑。为了确保该地区的防御，他会派遣信使前往乱风岗，将警告传达给峭壁卫兵图林·长角。"}},faq={{q="卫兵穆赫·月角是谁？",a="卫兵穆赫·月角是一位牛头人战士兼斥候，负责监视连接贫瘠之地和千针石林的升降梯入口。他监控敌人的动向，并向过往的旅客预警附近的危险。",al={"卫兵穆赫·月角职责","穆赫·月角是谁","升降梯牛头人卫兵"}},{q="为什么穆赫·月角警告要提防恐怖图腾？",a="穆赫·月角注意到恐怖图腾氏族在周边的峡谷中行事诡异且难以预测。虽然他们名义上是牛头人社会的一部分，但他们咄咄逼人的孤立主义使得沿路维持秩序的卫兵无法信任他们。",al={"恐怖图腾警告","为什么要避开恐怖图腾","穆赫·月角与恐怖图腾"}},{q="他希望将什么口信传达给乱风岗？",a="他携带了关于千针石林内半人马活动升级的紧急警告，并请求可靠的部落信使将此情报传达给乱风岗的峭壁卫兵图林·长角。",al={"乱风岗口信","穆赫·月角的口信内容","传信乱风岗背景"}},{q="卫兵穆赫·月角在哪里？",a="他站在升降梯顶端的悬崖边缘，就在贫瘠之地与千针石林的分界线上。",al={"穆赫·月角在哪里","卫兵穆赫·月角位置","升降梯守卫"}}},fx={["9347caaf"]={q="卫兵穆赫·月角支持哪一方？",a="卫兵穆赫·月角效力于雷霆崖和部落。他驻守在贫瘠之地与千针石林之间的升降梯顶端，监视边境，并指引途经的部落冒险者安全进入下方峡谷。",al={"卫兵穆赫·月角是部落成员吗","卫兵穆赫·月角的阵营","月角为谁效力"}},ff589928={q="卫兵穆赫·月角为什么驻守在升降梯？",a="月角驻守在千针石林的悬崖边，守卫下行通道并监视附近的危险。从这个制高点，他留意半人马的侵袭和蛮锤氏族不安分的动向，确保下到峡谷的旅人得到适当警告。",al={"月角为什么在这里","月角在升降梯做什么","卫兵穆赫·月角为什么在升降梯"}},["4ac94a87"]={q="卫兵穆赫·月角与谁有关？",a="月角听命于雷霆崖的牛头人领袖，并与乱风岗的峭壁卫兵图林·长角密切合作。峡谷道路附近出现危险时，长角是他依靠的指挥官，负责接收他的侦察报告。",al={"月角的盟友","月角向谁汇报","卫兵穆赫·月角的关系"}}},fp="14,230,20.436.0,14.403.0,22.214.0,45.239.0,53.188.0,32.139.0"}
P.entries["npc:brewmaster-drohn"] = {n="酿酒师德罗恩",s="酿酒师德罗恩是一位居住在繁华的棘齿城港口上方山坡上的兽人酿酒师。通过与传说中的游学者熊猫人陈·风暴烈酒之间的联系，他学会了异域的发酵艺术，并在贫瘠之地的荒凉边境酿造出强劲的佳酿。在卡利姆多各地发现废弃酒桶的冒险者，往往会直接被指引到他的门口。",h="酿酒师德罗恩是一位居住在繁华的棘齿城港口上方山坡上的兽人酿酒师。通过与传说中的游学者熊猫人陈·风暴烈酒之间的联系，他学会了异域的发酵艺术，并在贫瘠之地的荒凉边境酿造出强劲的佳酿。在卡利姆多各地发现废弃酒桶的冒险者，往往会...",kw={"贫瘠之地","酿酒师","陈·风暴烈酒","德罗恩","棘齿城","穴居人麦酒"},ang={["faction:Alliance"]="尽管是兽人，德罗恩仍受棘齿城热砂港的保护；攻击他会迅速招致当地地精当局的愤怒。",["profession:Cooking"]="美食冒险家们会欣赏德罗恩对稀有动植物的精准调配，能在沙漠中央酿造出世界级的饮品。",["race:Orc"]="与大多数追随萨尔来到卡利姆多建造堡垒的战士不同，德罗恩将杜隆塔尔和贫瘠之地新获得的和平转化为精湛的酿造艺术。"},sec={{t="棘齿城的酿造大师",b="酿酒师德罗恩俯瞰着棘齿城的地精码头，他是一位将自己的技艺奉献给酿造科学而非单纯战斗的兽人。他在山坡上的家中酿酒，在加兹鲁维的热砂港建立的中立避难所中平静地经营着。虽然大多数兽人满足于粗糙的麦酒或简单的烈酒，但德罗恩的作品涉及稀有原料、精致的口味平衡，以及在他族人中很少使用的技术。"},{t="熊猫人的联系",b="德罗恩的技艺深受陈·风暴烈酒的影响，这位著名的熊猫人游学者曾在杜隆塔尔建国期间与雷克萨和部落并肩作战。德罗恩的导师曾直接师从陈，学习了风暴烈酒酿造术的保密配方，后来陈本人还指导了德罗恩制作穴居人麦酒。当旅行者在野外偶然发现陈那独特的废弃酒桶时，德罗恩是当地唯一有能力辨别成分并重现这位游学者强劲佳酿的权威。"}},faq={{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩是一位住在贫瘠之地棘齿城的兽人酿酒师。他以精通各种异域麦酒，以及与游学者熊猫人陈·风暴烈酒的酿酒传统有直接联系而闻名。",al={"德罗恩背景故事","德罗恩是谁","棘齿城酿酒师"}},{q="德罗恩是怎么认识陈·风暴烈酒的？",a="德罗恩的导师从陈·风暴烈酒本人那里学会了如何酿造风暴烈酒，并将知识传授给了德罗恩。后来，陈还亲自向德罗恩传授了酿造穴居人麦酒的配方和方法。",al={"与陈的联系","他是如何认识陈的","德罗恩与陈"}},{q="如果我找到了陈的空酒桶，我该怎么办？",a="把酒桶带给棘齿城的酿酒师德罗恩。他一眼就能认出这是陈的亲手之作，并会让你去寻找重现这种佳酿所需的稀有本地原料。",al={"陈的空酒桶","找到空酒桶","酒桶任务"}},{q="酿酒师德罗恩是部落阵营的吗？",a="是的。德罗恩是部落的一名兽人，但他居住在中立的地精港口棘齿城并在此经商。攻击他会损害联盟冒险者在棘齿城和热砂港的声望。",al={"德罗恩是部落吗","德罗恩是中立的吗","德罗恩所属阵营"}},{q="德罗恩酿造什么样的饮品？",a="他酿造烈性混合酒，包括穴居人麦酒和以陈·风暴烈酒命名的风暴烈酒，这些都需要用到在贫瘠之地各处发现的野兽的獠牙、腺体和其他部位。",al={"德罗恩的配方","德罗恩的酒厂佳酿"}},{q="德罗恩具体在哪里？",a="你可以在俯瞰棘齿城港口的山坡上他的房子外面找到他，就在贫瘠之地主码头的西北方。",al={"德罗恩位置","德罗恩在哪里","寻找酿酒师德罗恩"}}},fp="16,264,32.403.0,23.386.0,24.161.0,36.128.0,44.162.0,43.191.0,36.171.0,31.110.0"}
P.entries["npc:brewmeister-bilger"] = {n="布鲁米·比格尔",s="布鲁米·比格尔是一位嗜酒的矮人酿酒师，居住在希尔斯布莱德丘陵的南海镇旅店地下室里。他整日沉迷于品尝各种烈酒，并等待着来自遥远之地的货物。",h="布鲁米·比格尔是一位嗜酒的矮人酿酒师，居住在希尔斯布莱德丘陵的南海镇旅店地下室里。他整日沉迷于品尝各种烈酒，并等待着来自遥远之地的货物。",kw={"比格尔","布鲁米·比格尔","希尔斯布莱德丘陵","旅店地下室","马克里尔","南海镇"},ang={["faction:Alliance"]="作为南海镇旅店地下室的常客，比格尔是那些在这个饱受战火蹂躏的联盟城镇中与人类为邻的矮人之一。",["race:Dwarf"]="比格尔证明了即使远离铁炉堡，身处人类港口城镇，矮人对烈酒的热爱依然如故。"},sec={{t="地下室的生活",b="比格尔终日在他南海镇旅店下方的凉爽地下室里踱步，不仅被呃逆所困，还在苦苦寻找艾泽拉斯所能提供的最烈的美酒。"},{t="对烈性进口酒的偏好",b="尽管他长期处于醉酒状态，比格尔依然是一位眼光独到的品酒师。他偏爱浓烈的矮人月光酒和南方酿造的烈酒，总是热切地接收一些特殊的批次，比如醉鬼马克里尔从萨多尔大桥寄来的月光酒。"}},faq={{q="我在哪里可以找到布鲁米·比格尔？",a="布鲁米·比格尔位于希尔斯布莱德丘陵的联盟港口城镇——南海镇旅店楼下的地下室里。",al={"比格尔位置","比格尔在哪里","南海镇地下室矮人"}},{q="有哪些任务与布鲁米·比格尔有关？",a="比格尔是来自湿地的稀有酒类的收件人，其中包括像马克里尔的月光酒这样运往北方的南海镇的烈酒。",al={"比格尔任务","马克里尔的月光酒任务"}}},fx={["0436bf77"]={q="布鲁米·比格尔是谁？",a="布鲁米·比格尔是一名矮人酿酒师，整天待在南海镇旅店的地窖里喝酒，醉醺醺地打着嗝，等着朋友醉鬼马克里尔还他欠下的私酿酒。",al={"比格尔是谁","布鲁米·比格尔的身份","布鲁米·比格尔是谁"}},["29798063"]={q="布鲁米·比格尔支持哪一方？",a="比格尔站在联盟和南海镇一边。他是铁炉堡的矮人，在当地居民中安稳度日，尽管比起履行城镇事务，他更喜欢在地窖里安静地陪伴酒桶。",al={"比格尔的阵营","比格尔是联盟成员吗","比格尔支持哪一方"}},["5541902b"]={q="布鲁米·比格尔为什么在这里？",a="比格尔把南海镇旅店的地窖当成了自己的家，整天待在酒桶间，喝着烈酒，等着朋友醉鬼马克里尔还他欠下的私酿酒。",al={"比格尔为什么在南海镇","比格尔在这里做什么","布鲁米·比格尔为什么在这里"}}},fp="18,149,18.128.0,26.232.0,36.115.0,39.142.0"}
P.entries["npc:brine"] = {n="布瑞恩",s="布莱恩是一位兽人萨满，居住在南贫瘠之地的黑棘山干旱丘陵中。作为水之灵魂的专家，她指引萨满学徒踏上灵魂之路，与潮汐沟通并获得他们的水之图腾。",h="布莱恩是一位兽人萨满，居住在南贫瘠之地的黑棘山干旱丘陵中。作为水之灵魂的专家，她指引萨满学徒踏上灵魂之路，与潮汐沟通并获得他们的水之图腾。",kw={"贫瘠之地","黑棘山","布莱恩","call of water","萨满","塔伦米尔","水之图腾"},ang={["class:Shaman"]="布莱恩是你旅途中的重要向导，在你能够与水沟通并获得你的水之图腾之前，她会考验你的耐力和精神。",["faction:Horde"]="作为希尔斯布莱德战争的老兵，布莱恩并非在最前线为部落服务，而是通过将元素的精神传承传授给新一代来贡献力量。"},sec={{t="山脊隐士",b="布莱恩居住在黑棘山北部的风蚀山丘上，远离贫瘠之地繁忙的贸易站。尽管周围环绕着干旱的稀树草原，但她一生致力于理解水这种流动且多变的元素。部落各地的萨满在掌握了大地与火焰的力量后，都会被指引去寻求她的智慧，因为水需要一种耐心与视角，而这是极少有人能像她那样深刻理解的。"},{t="东部王国的记忆",b="年轻时，布莱恩曾随兽人同伴行军穿过希尔斯布莱德丘陵，参与了针对人类定居点的战斗。在艰苦的战役中，她曾来到塔伦米尔，在那里，她发现了一口由纯净、清冽的泉水供养的简陋水井。那口水井作为在毁灭中依然存在的生命象征，留在了她的记忆中，并加深了她孩提时学到的道理：即使在最黑暗、最悲伤的时刻，仍然能找到一丝希望的寄托。"},{t="水之图腾",b="布莱恩通过派遣渴望成为萨满的人去进行朝圣之旅，收集来自不同源头的纯净水滴来考验他们，以此教导他们水既可以温柔，也可以坚韧。她的仪式最终将引导萨满与元素之灵沟通，从而使萨满能够将水的治愈本质与他们的图腾焦点绑定在一起。"}},faq={{q="布莱恩是谁？",a="布莱恩是一位经验丰富的兽人萨满，隐居在南贫瘠之地黑棘山北部的一座山丘上。她是寻求与水之灵沟通的灵魂学徒的导师。",al={"布莱恩背景故事","布莱恩是谁","黑棘山的兽人"}},{q="为什么一位水之萨满会住在沙漠里？",a="尽管贫瘠之地十分干旱，但水的真正价值和精神纯净往往在生命最匮乏的地方才最为清晰。她的隐居生活使她能够远离定居点的喧嚣，与元素进行深入的沟通。",al={"为什么在贫瘠之地","为什么布莱恩住在沙漠"}},{q="布莱恩与塔伦米尔有什么联系？",a="多年前，布莱恩曾与部落战士并肩作战，穿过希尔斯布莱德丘陵并进入了塔伦米尔。在那里，她发现了一口清澈的泉水井，这成为了她在战争废墟中铭记生命与希望的象征。",al={"塔伦米尔水井","布莱恩希尔斯布莱德","布莱恩过往"}},{q="布莱恩在萨满训练中扮演什么角色？",a="布莱恩负责监督“水之图腾”试炼的几个阶段。她指引学徒去世界各地收集原始水样，在赋予他们获得水之图腾所需的洞察力之前，教导他们保持谦逊与坚韧。",al={"布莱恩萨满任务","如何获得水之图腾","水之图腾布莱恩"}},{q="布莱恩具体在哪里？",a="她坐在南贫瘠之地北部黑棘山的一处高耸悬崖上，位置就在剃刀沼泽的北面。",al={"布莱恩位置","布莱恩在哪","寻找贫瘠之地的布莱恩"}},{q="什么哲学指引着她的教导？",a="布莱恩相信，即使在极度的痛苦和悲伤中，也能找到一丝希望和纯净的复苏。她教导人们水代表着生命，以及在严酷考验面前的坚韧不拔。",al={"布莱恩哲学","水的教诲"}}},fp="5,162,19.350.0,32.405.0,17.266.1,13.174.0,41.120.0,42.205.0,45.222.0,31.114.0,37.135.0"}
P.entries["npc:brock-stoneseeker"] = {n="布洛克·寻石者",s="布洛克·寻石者是一位居住在洛克莫丹塞尔萨玛定居点的矮人采矿训练师。作为布洛克采矿与勘测学校的经营者，他指导新手勘探者如何从大地中提取珍贵的矿石和矿物。",h="布洛克·寻石者是一位居住在洛克莫丹塞尔萨玛定居点的矮人采矿训练师。作为布洛克采矿与勘测学校的经营者，他指导新手勘探者如何从大地中提取珍贵的矿石和矿物。",kw={"布洛克·寻石者","洛克莫丹","采矿训练师","采矿学校","塞尔萨玛"},ang={["profession:Mining"]="途径洛克莫丹的矿工们会在塞尔萨玛寻找布洛克·寻石者，以开始或进修他们挖掘和熔炼地区矿石的培训。",["race:Dwarf"]="对于卡兹莫丹的矮人来说，石头和金属是立足之本，这使得像布洛克这样的导师成为维持铁炉堡深厚工艺传统的关键环节。"},sec={{t="采矿与勘测大师",b="布洛克·寻石者在塞尔萨玛开展工作，并负责管理布洛克采矿与勘测学校。在矿产丰富的洛克莫丹山丘中，熟练掌握十字镐的使用技巧以及对地质矿脉的敏锐观察力是不可或缺的。布洛克指导有志成为矿工的人学习识别矿点、提取粗金属以及正确勘测地下矿藏的基础技术，确保联盟的工匠们能够为铁炉堡传奇的铁匠铺提供燃料。"}},faq={{q="布洛克·寻石者是谁？",a="布洛克·寻石者是一位位于洛克莫丹塞尔萨玛的矮人采矿训练师。他经营着布洛克采矿与勘测学校，教导工匠们如何提取矿石并勘测原生矿藏。",al={"布洛克·寻石者","布洛克是谁","布洛克 塞尔萨玛"}},{q="布洛克·寻石者在哪里？",a="布洛克居住在洛克莫丹主要的矮人城镇塞尔萨玛，并在当地商人附近经营他的采矿机构。",al={"布洛克在哪里","布洛克·寻石者位置","布洛克地图"}},{q="布洛克教授什么专业？",a="他是一位采矿训练师，教导旅行者采集粗石、铜矿以及散布在卡兹莫丹乡村各处的其他早期矿石的基础知识。",al={"布洛克教授什么","布洛克训练师类型","塞尔萨玛采矿训练师"}},{q="什么是布洛克采矿与勘测学校？",a="这是布洛克在塞尔萨玛设立的培训机构，致力于教导未来的勘探者如何安全地提取矿物并解读山脉中的地下矿脉。",al={"布洛克学校","塞尔萨玛采矿学校"}}},fp="17,162,30.348.0,25.165.0,37.133.0,33.149.0,47.179.0"}
P.entries["npc:bromos-grummner"] = {n="布罗莫斯·格鲁诺尔",s="布罗莫斯·格鲁诺尔是一位驻扎在寒脊山谷安威玛尔的矮人圣骑士训练师。他指导初出茅庐的矮人圣战者，传授对圣光的坚定信仰，以及白银之手骑士团中矮人与人类之间至关重要的纽带。",h="布罗莫斯·格鲁诺尔是一位驻扎在寒脊山谷安威玛尔的矮人圣骑士训练师。他指导初出茅庐的矮人圣战者，传授对圣光的坚定信仰，以及白银之手骑士团中矮人与人类之间至关重要的纽带。",kw={"安威玛尔","布罗莫斯","寒脊山谷","丹莫罗","格鲁诺尔","圣骑士","白银之手","训练师"},ang={["class:Paladin"]="对于矮人圣骑士来说，布罗莫斯是他们最初的精神导师，将他们引入白银之手的神圣职责之中。",["race:Dwarf"]="布罗莫斯体现了矮人圣光信徒与人类盟友并肩作战的悠久传统。"},sec={{t="寒脊山谷的明灯",b="布罗莫斯·格鲁诺尔站在安威玛尔坚固的石厅内，欢迎那些被圣光之道所吸引的矮人新手。他自信而坚定，教导年轻的圣骑士战斗礼仪和神圣祷言。除了基本的战斗准则外，布罗莫斯还强调团结，提醒他的学生们，白银之手骑士团将铁炉堡与联盟的人类王国以正义的目标紧密联系在了一起。"}},faq={{q="布罗莫斯·格鲁诺尔是谁？",a="布罗莫斯·格鲁诺尔是位于丹莫罗寒脊山谷安威玛尔的常驻圣骑士训练师。他为新晋的矮人圣骑士提供基础训练、法术以及精神指引。",al={"布罗莫斯是谁","布罗莫斯·格鲁诺尔背景故事","安威玛尔圣骑士训练师"}},{q="布罗莫斯代表哪个组织？",a="布罗莫斯代表白银之手骑士团。他积极强调人类与矮人在该神圣组织旗帜下所建立的纽带的重要性。",al={"布罗莫斯 白银之手","布罗莫斯是白银之手成员吗"}},{q="他教导新兵什么？",a="他指导新兵圣骑士职业的基本战斗技巧和神圣法术，并指派他们进行初期的试炼，以证明他们对圣光的奉献以及保卫丹莫罗的决心。",al={"布罗莫斯任务","布罗莫斯·格鲁诺尔做什么"}}},fp="15,215,21.238.0,23.157.0,33.137.0,32.179.0"}
P.entries["npc:brother-joshua"] = {n="乔舒修士",s="乔舒修士是一位人类牧师，隶属于圣光教会，驻扎在暴风城宏伟的Cathedral of Light内。他致力于指引信徒，训练新手牧师引导圣光来治愈伤口并支持盟友。他默默的服务支撑着王国中心地带的日常属灵教育。",h="乔舒修士是一位人类牧师，隶属于圣光教会，驻扎在暴风城宏伟的Cathedral of Light内。他致力于指引信徒，训练新手牧师引导圣光来治愈伤口并支持盟友。他默默的服务支撑着王国中心地带的日常属灵教育。",kw={"乔舒修士","cathedral of light","圣光","人类牧师","牧师训练师","暴风城"},ang={["class:Priest"]="乔舒修士是暴风城的一位主要导师，指导你对圣光的研究，并在你提升等级时帮助你解锁新的祈祷和法术。",["faction:Alliance"]="乔舒以Cathedral of Light为基地，代表了圣光教会在联盟心脏地带持久的精神韧性。"},sec={{t="大教堂中的导师",b="在宁静的Cathedral of Light大厅内，乔舒修士站在主祭坛旁，随时准备指导新入教的信仰仆人。作为圣光教会的牧师训练师，乔舒提供有关治疗、防护结界以及与圣光沟通所需的精神专注等基础学科的指导。对于开始为联盟效力的人类年轻牧师来说，他是他们深入了解神圣力量的第一位导师之一。"}},faq={{q="谁是乔舒修士？",a="乔舒修士是圣光教会的一位人类牧师兼训练师。他驻扎在暴风城的Cathedral of Light内，指导有抱负的牧师学习法术、仪式和神圣职责。",al={"谁是乔舒修士","乔舒修士的角色","牧师乔舒"}},{q="我在哪里可以找到乔舒修士？",a="他位于暴风城Cathedral Square的Cathedral of Light后方，靠近高祭坛。",al={"乔舒修士的位置","乔舒修士在哪里","乔舒在哪里"}},{q="他提供什么服务？",a="乔舒修士提供牧师指导，帮助牧师学习新等级的神圣和恢复法术，并允许他们重置天赋。",al={"乔舒的工作","乔舒修士的训练","乔舒能训练我吗"}}},fp="14,177,25.338.0,22.182.0,32.122.0,28.117.0"}
P.entries["npc:brother-kristoff"] = {n="克里斯托弗修士",s="克里斯托弗修士是一位人类，也是圣光教会的成员，驻扎在暴风城的Cathedral Square。他经常站在Uther the Lightbringer的巨大雕像附近。他专注于神学研究，经常寻找实用的文献，将其融入关于精神力量的布道之中。",h="克里斯托弗修士是一位人类，也是圣光教会的成员，驻扎在暴风城的Cathedral Square。他经常站在Uther the...",kw={"克里斯托弗修士","cathedral of light","cathedral square","坚韧","克里斯托弗","钢铁应力","乌瑟尔雕像"},ang={["class:Priest"]="在Cathedral Square学习的牧师们会欣赏克里斯托弗脚踏实地的礼拜方式，因为他借鉴了具体的、世俗的技艺来教授内在坚韧更深层的奥秘。",["profession:Blacksmithing"]="铁匠们可能会觉得很有趣，一位圣光牧师竟然会翻阅关于钢铁应力和冶金学的书籍，以此来教导神职人员关于韧性的知识。"},sec={{t="雕像旁的传道者",b="克里斯托弗修士在Cathedral Square的露天庭院中为圣光教会服务，徘徊在Uther the Lightbringer宏伟纪念碑的阴影下。与一些深居在Cathedral of Light大理石回廊中的牧师不同，克里斯托弗在广场上来往的市民和朝圣者之间工作。在准备他的讲道时——例如关于“精神坚韧”的布道——他会借鉴务实且世俗的类比。他最出名的一点是查阅《钢铁的应力》这类技术论文，用以解释凡人的灵魂如何承受压力，将圣光赋予的内在决心比作经过锻造的金属所具备的坚韧强度。"}},faq={{q="克里斯托弗修士是谁？",a="克里斯托弗修士是一位人类牧师，也是圣光教会的学者。他驻扎在暴风城Cathedral Square的Cathedral of Light外，就在Uther the Lightbringer的巨大雕像旁边。",al={"克里斯托弗修士背景","克里斯托弗是谁","暴风城克里斯托弗"}},{q="克里斯托弗修士在Cathedral Square做什么？",a="克里斯托弗准备关于圣光与信仰问题的布道和演讲。值得注意的是，他正在准备一场关于“精神坚韧”的讲座，并寻求从冶金文献中寻找素材，以阐释精神的韧性。",al={"克里斯托弗的目标","克里斯托弗的角色","为什么克里斯托弗修士站在外面"}},{q="克里斯托弗修士为什么需要一本关于铁的书？",a="克里斯托弗寻找《钢铁的应力》一书是为了丰富他关于坚韧的布道。他利用钢铁在压力下的物理特性作为世俗的隐喻，来解释对圣光的虔诚是如何加固凡人的精神以抵御逆境的。",al={"钢铁的应力","关于坚韧的书","克里斯托弗为什么需要冶金学"}}},fp="16,144,24.495.0,24.179.0,50.180.0,49.186.0"}
P.entries["npc:brother-neals"] = {n="尼尔斯修士",s="尼尔斯修士是一位居住在艾尔文森林北郡修道院的僧侣。他负责管理修道院的食物和饮品储备，并将大量时间花在监督货物运输和品尝当地农场酿造的葡萄酒上。",h="尼尔斯修士是一位居住在艾尔文森林北郡修道院的僧侣。他负责管理修道院的食物和饮品储备，并将大量时间花在监督货物运输和品尝当地农场酿造的葡萄酒上。",kw={"尼尔斯修士","艾尔文森林","葡萄出货单","北郡修道院","北郡山谷","农场","葡萄酒"},ang={["profession:Cooking"]="尼尔斯修士管理着修道院的物资和烈酒，对于任何对王国的烹饪艺术和酿造传统感兴趣的人来说，他都是一位志同道合的伙伴。"},sec={{t="酒窖管理员",b="尼尔斯修士藏身于北郡修道院上层的钟楼房间里，负责照看修道院的膳食供应和酒水储备。他对北郡农场有着特别而热切的关注，仔细追踪每一份葡萄出货单，并以极其专注的频率品尝修道院著名的葡萄酒，以确保其品质。尽管他的工作是和平的库存盘点和酒窖管理，但他依然密切留意着从山谷周围田野运送来的货物。"}},faq={{q="尼尔斯修士是谁？",a="尼尔斯修士是北郡修道院修士会的一员，负责为驻扎在山谷中的教士和新兵管理食物、饮品和葡萄酒库存。",al={"尼尔斯修士","尼尔斯","谁是尼尔斯"}},{q="在哪里可以找到尼尔斯修士？",a="他待在北郡修道院最顶层的房间里。想要找到他，请沿着主大厅内的石阶向上走，直到你到达塔楼顶部附近那个安静的房间。",al={"尼尔斯修士在哪里","尼尔斯修士位置","寻找尼尔斯"}},{q="他在葡萄园方面担任什么职责？",a="他负责追踪从附近的北郡农场运来的葡萄收成和葡萄酒运输，不过众所周知，他在平衡账目上花的时间和品尝葡萄酒的时间一样多。",al={"葡萄出货单任务","尼尔斯的酒","尼尔斯做什么的"}}},fp="13,140,20.243.0,21.117.0,33.161.0,40.137.0"}
P.entries["npc:brother-sarno"] = {n="萨尔努修士",s="萨尔努修士是一位和蔼的人类牧师，驻守在暴风城的Cathedral of Light入口处。作为信徒和游客的主要接待员，他还会指引勇敢的联盟旅行者前往铁炉堡，寻找那些需要帮助以收复诺莫瑞根的工程师。",h="萨尔努修士是一位和蔼的人类牧师，驻守在暴风城的Cathedral of Light入口处。作为信徒和游客的主要接待员，他还会指引勇敢的联盟旅行者前往铁炉堡，寻找那些需要帮助以收复诺莫瑞根的工程师。",kw={"萨尔努修士","cathedral of light","圣光教会","暴风城","techbot","大工匠欧沃斯巴克"},ang={["class:Priest"]="萨尔努修士是你们教派在暴风城的接待使者，他以身作则，体现了圣光美德所核心倡导的热情好客与温柔优雅。",["race:Gnome"]="尽管在人类的礼拜场所服务，萨尔努修士还是乐于指引有志之士前往铁炉堡，以支持诺莫瑞根的恢复工作。"},sec={{t="教堂中友善的声音",b="萨尔努修士站在暴风城宏伟的Cathedral of Light拱门内，常常是朝圣者和旅行者见到的第一张面孔。作为圣光教会的一名虔诚修士，他的职责简单却至关重要：为任何前来这座圣殿寻求慰藉、祈祷或指引的人提供亲切的问候。他的热情甚至延伸到了最出人意料的访客身上，使他成为这座城市忙碌教务生活中一个令人安心的存在。"},{t="与铁炉堡的联系",b="除了牧师的日常问候外，萨尔努修士还与联盟各地的盟友保持联系。当铁炉堡的大工匠欧沃斯巴克急需帮助来处理他那深陷诺莫瑞根受辐射大厅中的失控发明“Techbot”时，萨尔努主动承担起指引有能力的冒险者前往丹莫罗的重任。尽管他只是一名谦卑的修道者，但他明白，支持流离失所的侏儒是一种真诚的兄弟情谊。"}},faq={{q="我在哪里可以找到萨尔努修士？",a="萨尔努修士位于暴风城Cathedral Square的Cathedral of Light内。他站在正门左侧，随时准备迎接每一位进门的访客。",al={"萨尔努位置","萨尔努修士在哪里","教堂接待员"}},{q="萨尔努修士是做什么的？",a="萨尔努担任圣光教会的接待人员，负责问候游客和信徒。他还将冒险者引荐给铁炉堡的大工匠欧沃斯巴克，以协助解决诺莫瑞根的麻烦。",al={"萨尔努修士的职责","萨尔努做什么"}},{q="为什么一位暴风城的牧师会把人派往诺莫瑞根？",a="圣光教会致力于促进整个大联盟之间的合作与援助。当教会得知大工匠欧沃斯巴克需要帮助来回收像Techbot这样的失控科技时，萨尔努修士便协助指引有能力的勇士前往铁炉堡提供帮助。",al={"萨尔努诺莫瑞根任务","萨尔努为什么关心侏儒"}},{q="他属于什么特定的教派吗？",a="他是圣光教会的一名受戒成员，在暴风城大教堂主教和大主教本尼迪塔斯的领导下服务。",al={"萨尔努阵营","萨尔努修士所属教派"}}},fp="13,200,34.272.0,17.285.0,31.139.0,27.173.0,54.175.0,37.153.0"}
P.entries["npc:brother-wilhelm"] = {n="威尔海姆修士",s="威尔海姆修士是一位人类圣骑士训练师，驻扎在艾尔文森林的闪金镇。他隐身于村里的铁匠铺后，负责教导那些刚刚走出北郡修道院，踏上圣光之路的年轻保卫者。",h="威尔海姆修士是一位人类圣骑士训练师，驻扎在艾尔文森林的闪金镇。他隐身于村里的铁匠铺后，负责教导那些刚刚走出北郡修道院，踏上圣光之路的年轻保卫者。",kw={"威尔海姆修士","北郡兄弟会","艾尔文森林","闪金镇","圣光","圣骑士训练师","神圣法典"},ang={["class:Paladin"]="威尔海姆修士是你离开北郡山谷后的第一位导师，他指引你的成长，并为你开启掌握神圣法典的神圣之路。",["race:Human"]="作为王国神圣传统的熟悉面孔，威尔海姆修士体现了圣光教会捍卫艾尔文腹地的坚定信仰。"},sec={{t="闪金镇的向导",b="虽然北郡山谷为圣光的初学者提供了最初的庇护所，但那些踏入广阔的艾尔文森林世界的人们往往会寻找威尔海姆修士。他驻扎在闪金镇繁忙的铁匠铺后面，训练新晋的圣骑士履行他们神圣的职责，在他们从修道院的新手成长为王国宣誓守护者的过程中，提供指导和课程。"},{t="圣典之路",b="威尔海姆在引导有抱负的圣骑士踏上他们的神圣旅程，协助他们寻找神圣法典方面扮演着至关重要的角色。通过这一重要的仪式，入门者将学会牺牲的份量和神圣救赎的力量，并考验他们的虔诚，以便他们能够运用圣光复活倒下的战友，并在暴风王国维护正义。"}},faq={{q="我在哪里可以找到威尔海姆修士？",a="威尔海姆修士位于艾尔文森林的闪金镇。他站在村庄铁匠铺的后面，随时准备训练和引导有志成为圣骑士的冒险者。",al={"威尔海姆位置","威尔海姆修士在哪里","寻找威尔海姆修士"}},{q="威尔海姆修士提供什么服务？",a="他担任圣骑士职业训练师，为在艾尔文森林冒险的年轻圣骑士传授新的法术、战斗祝福和神圣技能。",al={"威尔海姆的作用","闪金镇圣骑士训练师","威尔海姆修士训练师"}},{q="威尔海姆修士是北郡兄弟会的一员吗？",a="他的头衔以及与北郡修道院的距离表明他与北郡兄弟会的神圣教团有着密切的联系，尽管他主要是在为圣光教会和暴风王国服务。",al={"威尔海姆是北郡兄弟会的吗","威尔海姆阵营","威尔海姆修士为谁服务"}},{q="他在神圣法典任务中扮演什么角色？",a="威尔海姆引导那些实力有所提升的人类圣骑士去完成他们的神圣任务——寻找神圣法典，指引他们通过获得神圣复活祝福所必须的试炼。",al={"神圣法典威尔海姆","复活任务威尔海姆","闪金镇圣骑士任务"}}},fp="15,156,20.304.0,20.318.0,33.134.0,43.127.0,57.189.0,47.163.0"}
P.entries["npc:bruegal-ironknuckle"] = {n="布鲁高·铁拳",s="布鲁高·铁拳是关押在暴风城监狱中一位臭名昭著的矮人囚犯。与那些充斥在牢房里的轻罪犯和暴乱匪徒不同，他是一名可怕的格斗家，他出现在监狱走廊深处，对任何试图恢复秩序的人来说都意味着即刻的危险。",h="布鲁高·铁拳是关押在暴风城监狱中一位臭名昭著的矮人囚犯。与那些充斥在牢房里的轻罪犯和暴乱匪徒不同，他是一名可怕的格斗家，他出现在监狱走廊深处，对任何试图恢复秩序的人来说都意味着即刻的危险。",kw={"格斗家","布鲁高·铁拳","矮人","囚犯","铁拳","稀有","监狱","暴风城"},ang={["class:Warrior"]="铁拳以原始的毅力和沉重的铁拳战斗，让尚武的战士们一窥在失去了纪律和荣誉的情况下，那种肆无忌惮的蛮力是什么样子。",["faction:Alliance"]="暴风城的城市卫队依赖勇敢的联盟勇士来镇压像铁拳这样的暴徒，因为他们威胁要将首都的中心变成一座永恒的无政府要塞。",["race:Dwarf"]="矮人游客看到一位结实的同胞被抛在暴风城的扒手和流氓之中可能会感到清醒，这表明流放和法外生活甚至波及到了铁炉堡的子民。"},sec={{t="危险的罪犯",b="当暴风城监狱爆发公开骚乱时，城里许多最危险的恶棍控制了地下牢房。其中就包括布鲁高·铁拳，这是一名以残暴的格斗力量而闻名的极其危险的矮人囚犯。他并没有被禁锢在单一的牢房里，而是在被暴乱蹂躏的走廊中游荡，随时准备痛击任何试图平息骚乱的人。"},{t="桀骜不驯的法外之徒",b="虽然监狱内部的大部分暴乱是由迪菲亚潜行者及其头目策划的，但像布鲁高这样的囚犯表明，这座监狱关押着来自东部王国的各种流氓和亡命徒。无论是什么罪行让他被判处在暴风城地底深处服刑，他那凶猛的韧性都让他成为了一个难以捉摸的目标，也是游荡在监狱走廊中最致命的独行囚犯之一。"}},faq={{q="布鲁高·铁拳是谁？",a="布鲁高·铁拳是被关押在暴风城监狱中的一名精英矮人罪犯。他以一名难以捉摸、强硬的囚犯而闻名，在持续的暴乱期间会游荡在监狱大厅中。",al={"布鲁高是谁","铁拳背景","监狱矮人囚犯"}},{q="布鲁高·铁拳是迪菲亚潜行者的一员吗？",a="布鲁高是监狱里的一名矮人囚犯。现有资料中并未记载他的确切从属关系。",al={"布鲁高是迪菲亚吗","迪菲亚矮人监狱"}},{q="他为什么被关押在监狱里？",a="导致他被关进监狱的确切罪名并未记录在官方公开的通缉令中，但他暴躁的脾气和好勇斗狠的名声表明他触犯了暴风城的律法，犯下了严重的罪行。",al={"为什么布鲁高被关押","布鲁高罪行"}},{q="在监狱里哪里可以找到他？",a="布鲁高不会呆在指定的牢房里。他是一名难以捉摸的囚犯，偶尔会在监狱的内部通道和交叉路口游荡，让那些清理暴徒的人感到措手不及。",al={"布鲁高刷新","布鲁高在哪里","监狱稀有刷新"}},{q="他一直都在监狱里吗？",a="不。布鲁高在暴乱的人群中很少见。他通常被关禁闭或躲藏起来，在持续的骚乱期间只是偶尔出现。",al={"布鲁高为什么不刷新","为什么找不到布鲁高"}},{q="是什么让他能在囚犯中脱颖而出？",a="除了他可怕的战斗能力之外，据传布鲁高身上携带着躲避监狱守卫藏起来的贵重违禁品和装备，这使他成为了勇于面对他的冒险者们眼中梦寐以求的战利品。",al={"为什么人们要找布鲁高","布鲁高重要性"}}},fp="19,171,19.359.0,13.379.0,27.153.0,54.87.0,37.179.0,42.133.0,35.102.0,43.190.0"}
P.entries["npc:cain-firesong"] = {n="凯恩·火歌",s="凯恩·火歌是一位被遗忘者法师训练师，位于提瑞斯法林地的布瑞尔定居点。他协助奥术新手提升力量，在引导他们前往幽暗城进行更深造之前给予指导。你可以在恐惧之末旅店的楼上平台上找到他。",h="凯恩·火歌是一位被遗忘者法师训练师，位于提瑞斯法林地的布瑞尔定居点。他协助奥术新手提升力量，在引导他们前往幽暗城进行更深造之前给予指导。你可以在恐惧之末旅店的楼上平台上找到他。",kw={"安娜斯塔西娅·哈特威尔","奥术","布瑞尔","凯恩·火歌","恐惧之末旅店","法师训练师","提瑞斯法林地"},ang={["class:Mage"]="对于刚走出丧钟镇的年轻被遗忘者法师来说，凯恩·火歌是你被召唤到幽暗城之前在提瑞斯法林地的主要导师。",["race:Undead"]="凯恩证明了即使在死亡之后，前人类法师的奥术传统对于被遗忘者来说依然是一种强大的武器。"},sec={{t="布瑞尔的修行者",b="尽管许多被遗忘者施法者钻研暗影或死灵法术，但凯恩·火歌依然保持着对传统奥术学科的精通。他驻扎在布瑞尔，是刚从丧钟镇出发的被遗忘者法师的启蒙导师。当地的死亡卫士会指引访客前往恐惧之末旅店的楼上平台，并开玩笑说他来得太晚，没订到房间。"},{t="指引新秀",b="当他门下的新手法师在提瑞斯法林地完成了初步学习后，凯恩会确保他们不会停滞不前。他会指引自己最有能力的学员去寻找安娜斯塔西娅·哈特威尔，这是一位居住在幽暗城Magic Quarter的大法师。"}},faq={{q="凯恩·火歌是谁？",a="凯恩·火歌是一位驻扎在提瑞斯法林地布瑞尔的被遗忘者法师训练师。他向部落的施法新手传授奥术法术，并将进阶学员指引向幽暗城。",al={"凯恩·火歌是谁","凯恩·火歌背景故事","凯恩·火歌布瑞尔"}},{q="凯恩·火歌在布瑞尔待在哪里？",a="凯恩站在布瑞尔的恐惧之末旅店的楼上平台上。当地的死亡卫士开玩笑说他办理入住太晚，没能订到房间。",al={"凯恩·火歌在哪里","凯恩·火歌位置","凯恩旅店房间"}},{q="凯恩在初级训练后将法师派往何处？",a="一旦法师在他的指导下达到足够水平，凯恩就会指引他们前往幽暗城的Magic Quarter，继续在安娜斯塔西娅·哈特威尔的门下学习。",al={"凯恩·火歌任务","凯恩指引法师去找谁","与安娜斯塔西娅交谈"}}},fp="13,189,23.388.0,18.199.0,21.169.0,39.154.0,56.135.0"}
P.entries["npc:cairne-bloodhoof"] = {n="凯恩·血蹄",s="凯恩·血蹄是牛头人各部族尊敬的大酋长，也是雷霆崖的统治者。作为一名拥有非凡智慧的高大勇士，在兽人帮助他的族人从半人马手中逃脱灭绝的命运后，他将牛头人的命运与Thrall的部落联系在了一起。",h="凯恩·血蹄是牛头人各部族尊敬的大酋长，也是雷霆崖的统治者。作为一名拥有非凡智慧的高大勇士，在兽人帮助他的族人从半人马手中逃脱灭绝的命运后，他将牛头人的命运与Thrall的部落联系在了一起。",kw={"贝恩","血蹄","凯恩","半人马","大酋长","莫高雷","thrall","雷霆崖"},ang={["faction:Horde"]="与Thrall一道，凯恩·血蹄是卡利姆多现代部落的奠基人，是荣誉、智慧和军事力量的支柱。",["race:Tauren"]="凯恩·血蹄是你族人的救世主，他统一了分散的部族，击退了半人马，并领导了雷霆崖的建设。"},sec={{t="莫高雷的国家",b="世世代代，牛头人一直作为游牧民族生活在贫瘠之地，不断遭到野蛮的半人马掠夺者的猎杀，濒临灭绝。当Thrall和他的兽人来到卡利姆多海岸时，凯恩·血蹄在他们身上发现了一种难得的高贵品质。Thrall提供了军事保护，护送凯恩·血蹄那绝望的商队穿过平原前往莫高雷的安全地带，作为交换，凯恩·血蹄指引他们前往石爪峰的先知之处。在雷霆崖高耸的台地上定居下来后，凯恩·血蹄终于为所有牛头人部族建立了一个永久的统一家园。"},{t="对部落的誓言",b="出于对Thrall的感激，凯恩·血蹄跟随兽人前往石爪峰，并在第三次战争期间与部落和Jaina Proudmoore的人类并肩作战，共同对抗燃烧军团。后来，当戴林·普罗德摩尔海军上将入侵杜隆塔尔时，在被俘的儿子贝恩·血蹄获救后，凯恩·血蹄再次亲自拿起武器，与雷克萨并肩作战。如今，凯恩·血蹄作为部落最受尊敬的长者之一和Thrall最亲密的知己，为应对鲁莽的战争行为提供冷静的建议。"}},faq={{q="谁是凯恩·血蹄？",a="凯恩·血蹄是统一的牛头人各部族的大酋长，血蹄氏族的酋长，也是雷霆崖的领袖。他是一位古老的勇士，他的领导力和力量带领牛头人走出了游牧流亡的生活，进入了一个安全的家园。",al={"谁是凯恩","牛头人领袖","大酋长"}},{q="为什么牛头人与兽人结盟？",a="在第三次战争期间，掠夺成性的半人马部族将牛头人猎杀至濒临灭绝。Thrall和刚抵达的兽人击退了掠夺者，并将凯恩·血蹄的大商队护送至莫高雷。出于感激，凯恩·血蹄承诺他的族人将效忠于Thrall的部落，并贡献他们的力量。",al={"为何牛头人加入部落","凯恩与thrall的友谊","牛头人与兽人盟友"}},{q="凯恩·血蹄住在哪里？",a="他坐镇于建立在莫高雷高耸台地上的首都雷霆崖，与各统一的牛头人部族首领共同统治。",al={"凯恩在哪里","凯恩位置","寻找凯恩·血蹄"}},{q="贝恩·血蹄对于凯恩·血蹄来说是谁？",a="贝恩·血蹄是凯恩·血蹄深爱的儿子和继承人。当贝恩·血蹄被半人马掠夺者绑架时，凯恩·血蹄陷入了深深的悲痛，拒绝战斗，直到雷克萨和他的同伴追踪到贝恩·血蹄并将他安全送回家中。",al={"凯恩之子","贝恩是凯恩的儿子吗","贝恩·血蹄关系"}}},fp="16,227,19.547.0,19.495.0,24.217.0,40.278.0,25.136.0,33.200.0"}
P.entries["npc:calor"] = {n="卡洛尔",s="卡洛尔是夜色镇的一名忠诚居民，他协助卡尔文家族守卫暮色森林。他在乔纳森·卡尔文的指挥下行事，积极协调并搜寻潜伏在阴暗森林中的凶残狼人。那些想要击退在森林中出没的贪婪野兽的冒险者，往往会从他那里接到任务。",h="卡洛尔是夜色镇的一名忠诚居民，他协助卡尔文家族守卫暮色森林。他在乔纳森·卡尔文的指挥下行事，积极协调并搜寻潜伏在阴暗森林中的凶残狼人。那些想要击退在森林中出没的贪婪野兽的冒险者，往往会从他那里接到任务。",kw={"卡洛尔","卡尔文","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","烂果园","狼人"},ang={["class:Hunter"]="猎人们可以在卡洛尔这里找到稳定的工作，追踪并清理那些违背森林自然秩序的野蛮异界野兽。",["faction:Alliance"]="对于那些愿意勇敢进入阴暗森林以保卫夜色镇孤立镇民的联盟勇士来说，卡洛尔是一位至关重要的联络人。"},sec={{t="阴影中的效忠者",b="卡洛尔驻扎在饱受困扰的夜色镇，与镇上杰出的守卫者之一乔纳森·卡尔文密切合作。在暮色森林无尽的阴霾和蔓延的恐惧中，卡洛尔致力于支持卡尔文家族的使命：在剩下的镇民惨遭屠戮之前，铲除那些侵蚀镇子周边的超自然恐怖。"},{t="狼人威胁",b="卡洛尔的主要职责是应对潜伏在林中的野性狼人，尤其是在像烂果园这样的腐坏区域附近。这些凶猛的狼人远比普通的野兽更具侵略性和危险性，它们会屠杀路人和巡逻队。卡洛尔招募有能力的战士来削减狼人的数量并调查它们的起源，试图绝望地遏制这股嗜血的浪潮。"}},faq={{q="卡洛尔是谁？",a="卡洛尔是居住在夜色镇并与卡尔文家族结盟的人类。他通过派遣冒险者去猎杀暮色森林中的危险威胁，从而协助小镇的防卫。",al={"卡洛尔 夜色镇","卡洛尔是谁","卡洛尔 暮色森林"}},{q="在哪里可以找到卡洛尔？",a="卡洛尔驻扎在夜色镇，这是坐落在暮色森林阴影之中的主要联盟城镇。",al={"卡洛尔在哪里","卡洛尔位置","卡洛尔坐标"}},{q="卡洛尔和乔纳森·卡尔文是什么关系？",a="卡洛尔是卡尔文家族的坚定支持者。他遵循乔纳森·卡尔文的指示，协助他与肆虐森林的致命怪物开战。",al={"卡洛尔与卡尔文","卡洛尔为谁效力","卡尔文家族 卡洛尔"}},{q="卡洛尔让你去对付什么敌人？",a="卡洛尔委派冒险者去猎杀那些遍布森林的嗜血狼人族群，并特别指挥针对烂果园等地附近的狼人进行打击。",al={"卡洛尔任务","卡洛尔想要什么","狼人任务 卡洛尔"}},{q="为什么暮色森林的狼人威胁如此紧迫？",a="狼人是凶残且贪婪的掠食者，它们见到任何东西都会发动攻击。如果没有像卡洛尔和守夜人这样的人来协调定期的清理行动，这些野兽很快就会冲垮夜色镇薄弱的防线。",al={"为什么要杀暮色森林的狼人","暮色森林狼人威胁"}},{q="卡洛尔是守夜人的成员吗？",a="不是。因为对守夜人表现出的自满感到失望，卡洛尔转而加入了乔纳森·卡尔文的阵营。如今，他作为卡尔文家族反狼人行动的直接代理人和支持者而活动。",al={"卡洛尔 守夜人","卡洛尔是守夜人吗"}}},fx={e997a1f9={q="卡洛尔想要什么？",a="卡洛尔决心铲除盘踞在暮色森林的狼人。他直接奉乔纳森·卡尔文之命，召集有能力的冒险者，追猎潜伏在烂果园等地的野兽，并阻止它们阴暗的腐化蔓延，以免夜色镇遭其吞噬。",al={"卡洛尔的目标","卡洛尔在做什么","卡洛尔想要什么"}},f0ff266f={q="卡洛尔为什么在夜色镇？",a="卡洛尔留驻夜色镇，协助卡尔文家族讨伐林地中的野兽。他在这座饱受困扰的城镇里，协调侦察和狩猎行动，对付徘徊于周围树林和废弃果园中的凶残狼人群。",al={"卡洛尔为什么在这里","卡洛尔为何在夜色镇","卡洛尔为什么在暮色森林"}}},fp="5,157,25.243.0,17.318.0,13.139.0,25.68.0,51.119.0,39.86.0,47.193.0,37.161.0"}
P.entries["npc:calvin-montague"] = {n="卡尔文·蒙泰古",s="卡尔文·蒙泰古是一个投机的被遗忘者潜行者，在提瑞斯法林地的丧钟镇出口大门附近徘徊。他以那些刚离开墓地苏醒的不死族为目标，试图欺骗路人替他跑腿。",h="卡尔文·蒙泰古是一个投机的被遗忘者潜行者，在提瑞斯法林地的丧钟镇出口大门附近徘徊。他以那些刚离开墓地苏醒的不死族为目标，试图欺骗路人替他跑腿。",kw={"潜行者的交易","卡尔文·蒙泰古","骗子","丧钟镇","被遗忘者潜行者","蒙泰古","提瑞斯法林地"},ang={["class:Rogue"]="被遗忘者潜行者会很快识破卡尔文·蒙泰古拙劣的操纵企图，认出这是个试图对新手进行廉价诈骗的同道窃贼。",["race:Undead"]="对于离开丧钟镇的新生者来说，卡尔文算是一个早期的教训，让他们知道并非所有希尔瓦娜斯的臣民都愿意团结互助。"},sec={{t="门边的骗子",b="卡尔文·蒙泰古守在通往丧钟镇外的大门旁，体现了洛丹伦那些不安宁的亡者所共有的冷酷实用主义。他没有亲自处理信件，也没有支付合理的邮费，而是试图通过花言巧语诱骗漫游的冒险者在虚假的借口下帮他送信。虽然其他几位背负蒙泰古家族姓氏的显赫亡者在幽暗城管理着银行业务，但卡尔文从事的行当却远没有那么光彩，他更偏好小打小闹的阴谋和欺诈。"},{t="潜行者的诡计",b="卡尔文的提议是让他人代他送信，但那些头脑敏锐或受过地下世界训练的人很快就能识破他言语背后的骗局。即使是在提瑞斯法荒凉废墟中努力寻找生存意义的新生者中，卡尔文也提醒着新来者：在为黑暗女王效力时，信任是极其稀缺的商品。"}},faq={{q="卡尔文·蒙泰古是谁？",a="卡尔文·蒙泰古是一名被遗忘者潜行者，位于提瑞斯法林地的丧钟镇出口大门附近。他试图利用刚复活的不死族，欺骗他们免费为自己跑腿。",al={"卡尔文·蒙泰古","卡尔文·蒙泰古是谁","卡尔文 丧钟镇"}},{q="卡尔文想让冒险者做什么？",a="卡尔文试图用欺骗的手段劝说路过的旅行者为他送信，希望通过花言巧语获得免费的快递服务。",al={"卡尔文·蒙泰古任务","卡尔文的信","卡尔文想要什么"}},{q="卡尔文·蒙泰古与幽暗城的银行家们有关系吗？",a="他与幽暗城的几位显赫银行家同姓，例如奥菲莉亚、莫蒂默、威廉和伦道夫·蒙泰古。家族关系尚未得到证实。",al={"蒙泰古家族","幽暗城银行家蒙泰古","卡尔文与银行家的关系"}},{q="在哪里可以找到卡尔文·蒙泰古？",a="他潜伏在丧钟镇北部出口木门外侧的路上，拦截那些前往广阔的提瑞斯法林地的冒险者。",al={"卡尔文位置","卡尔文·蒙泰古在哪里","寻找卡尔文·蒙泰古"}}},fp="15,134,21.422.0,16.310.1,23.167.0,40.157.0,52.152.0,35.149.0"}
P.entries["npc:canaga-earthcaller"] = {n="坎纳甘·地鸣",s="坎纳甘·地鸣是一位暗矛巨魔萨满祭司，驻扎在烈日当空的试炼谷。他指导部落的新手萨满祭司与大地的灵魂沟通，并帮助他们获得第一件元素图腾。",h="坎纳甘·地鸣是一位暗矛巨魔萨满祭司，驻扎在烈日当空的试炼谷。他指导部落的新手萨满祭司与大地的灵魂沟通，并帮助他们获得第一件元素图腾。",kw={"call of earth","坎纳甘","暗矛","杜隆塔尔","大地之灵药","地鸣","萨满","试炼谷"},ang={["class:Shaman"]="坎纳甘是你在杜隆塔尔的第一位精神导师，他准备了大地之灵药，让你能够与元素沟通并领取你的大地图腾。",["race:Orc"]="坎纳甘与谷中的兽人教官并肩工作，帮助年轻的兽人们将他们的灵魂与这片新家园贫瘠的土地紧密相连。",["race:Troll"]="作为试炼谷中著名的暗矛巨魔人物之一，坎纳甘确保年轻的巨魔萨满祭司们能在灵魂的正确指引下开始他们的旅程。"},sec={{t="大地之声",b="坎纳甘·地鸣栖身于试炼谷的红色峭壁之上，是暗矛巨魔和兽人萨满学徒最初的精神导师之一。虽然许多训练师只专注于战备训练，但坎纳甘会教导新手如何静下心来，聆听卡利姆多本身的隆隆回响，并准备好与灵魂沟通所需的大地之灵药。"},{t="第一件图腾",b="在任何萨满学徒真正能够驾驭大地元素之怒前，他们必须向灵魂证明自己的尊重和决心。坎纳甘会指引初学者收集神圣的试剂，并前往杜隆塔尔当地的灵魂石地。在他的指引下，新手们喝下大地之灵药，亲眼目睹元素之灵，并获得他们的大地图腾。"}},faq={{q="坎纳甘·地鸣是谁？",a="坎纳甘·地鸣是一位居住在试炼谷的暗矛巨魔萨满祭司。他负责指导部落中迈出第一步的年轻萨满祭司。",al={"坎纳甘背景故事","坎纳甘是谁","坎纳甘·地鸣npc"}},{q="坎纳甘教导年轻萨满祭司什么？",a="坎纳甘负责监督杜隆塔尔部落萨满祭司的“大地之召”系列任务。他会调制大地之灵药，这是一种神秘的药剂，能让初学者感知并与当地的大地元素之灵交谈，从而获得他们的第一件图腾。",al={"杜隆塔尔萨满任务","杜隆塔尔大地之召","坎纳甘任务"}},{q="坎纳甘准备的大地之灵药是什么？",a="大地之灵药是用当地试剂特别调制的一种精神药剂。萨满祭司喝下它后能开启感官，感知大地上隐藏的灵魂，从而直接与元素实体交流。",al={"什么是大地之灵药","灵药背景"}},{q="为什么会有巨魔在兽人的试炼场训练萨满祭司？",a="第三次战争后，暗矛巨魔部族与萨尔的部落紧密融合，并与兽人们一同在杜隆塔尔定居。现在，巨魔萨满祭司和战士正与年轻的兽人一起在试炼谷并肩训练。",al={"为什么巨魔在试炼谷","试炼谷的暗矛巨魔"}},{q="在哪里可以找到坎纳甘·地鸣？",a="坎纳甘坐在俯瞰试炼谷东侧小径的岩石平台上，就在主要训练中心南边。",al={"坎纳甘位置","坎纳甘在哪里"}}},fp="18,123,17.269.0,15.219.0,26.135.0,37.210.0,40.181.0,60.200.0,38.116.0"}
P.entries["npc:captain-danuvin"] = {n="丹努文队长",s="丹努文队长是一名驻扎在西部荒野哨兵岭的军官，他是负责守卫边境的领导者之一。他与人民民兵团并肩作战，指挥志愿者和新兵巡逻道路，并击退入侵的豺狼人和歹徒。他的命令对于防止补给线和农田完全落入敌手至关重要。",h="丹努文队长是一名驻扎在西部荒野哨兵岭的军官，他是负责守卫边境的领导者之一。他与人民民兵团并肩作战，指挥志愿者和新兵巡逻道路，并击退入侵的豺狼人和歹徒。他的命令对于防止补给线和农田完全落入敌手至关重要。",kw={"丹努文队长","丹努文","格里安·斯托曼","巡逻西部荒野","人民民兵团","河爪","哨兵岭","西部荒野"},ang={["class:Warrior"]="丹努文尊重军事纪律和直接的前线行动，他赏识那些愿意冲入豺狼人群中并以蛮力清除公路威胁的战士。",["faction:Alliance"]="丹努文队长是少数几位在王室忽视的情况下，仍努力维护西部荒野秩序的现役军人之一，他为联盟的新兵提供保卫王国的稳定工作。",["race:Human"]="对于王国的人类来说，协助丹努文是关乎家园存亡的大事，以确保暴风城的粮仓不会永远落入掠夺者和野兽手中。"},sec={{t="守卫哨兵岭",b="丹努文队长驻守在哨兵岭的防御塔上，负责协调西部荒野各地的地面巡逻。随着暴风城正规驻军的撤离，该地区陷入了混乱，当地的防御力量严重不足。丹努文非常依赖流浪的冒险者、当地的农夫和志愿战士，以在这些草原上维持哪怕一丝秩序。"},{t="边境巡逻",b="丹努文当前最关心的战略问题是哨兵岭周边的道路和开阔地的安全。随着河爪豺狼人日益猖獗，并在中心哨所附近进行劫掠，他组织了积极的巡逻队来消灭这些兽群并确保周边安全。他的命令有助于防止营地被西部荒野的投机分子和掠夺者完全包围。"}},faq={{q="我可以在哪里找到丹努文队长？",a="丹努文队长驻扎在哨兵岭，这是位于西部荒野中心地带的主要联盟哨所。他通常站在俯瞰道路的防御塔附近。",al={"丹努文位置","丹努文队长在哪里","丹努文西部荒野"}},{q="丹努文队长代表哪个阵营？",a="丹努文效忠于联盟，直接支持西部荒野的当地防御力量，与格里安·斯托曼和人民民兵团密切合作。",al={"丹努文阵营","丹努文效忠谁"}},{q="他会分配给冒险者什么任务？",a="丹努文指派新兵保卫乡村，主要是通过巡逻平原和击退逼近哨兵岭的凶猛的河爪豺狼人等命令。",al={"丹努文任务","丹努文队长想要什么","巡逻西部荒野任务"}},{q="为什么丹努文要依靠志愿者而不是暴风城军队？",a="暴风城已经放弃了西部荒野，没有派遣任何驻军进行防御。丹努文和哨兵岭的其他领导者别无选择，只能依靠雇佣兵和民兵新兵。",al={"为什么没有暴风城军队","为什么是民兵","暴风城西部荒野驻军"}},{q="丹努文在西部荒野之外有关系网吗？",a="丹努文与西部荒野有着紧密的联系。这里是他的家园，他发誓不会抛弃那些选择留下的公民，因此他的职责使他专注于哨兵岭周围的平原和道路。",al={"丹努文赤脊山","丹努文人脉"}},{q="与格里安·斯托曼相比，他的职责是什么？",a="虽然格里安·斯托曼负责全面的防御战略和人民民兵团的领导工作，但丹努文队长则作为一名野战军官，负责管理战术问题、道路巡逻以及基地周围紧迫的豺狼人威胁。",al={"斯托曼与丹努文","丹努文是负责人吗"}}},fp="15,238,16.246.0,23.254.0,33.149.0,44.142.0,42.112.0,67.143.0,50.163.0,47.171.0"}
P.entries["npc:captain-grayson"] = {n="葛瑞森船长",s="葛瑞森船长是驻守在西部荒野灯塔的一名海盗船长的游荡灵魂。他的船在黑暗的海岸线上撞毁，失去了自己的生命，现在他看守着灯塔，以防其他水手遭受同样的命运。",h="葛瑞森船长是驻守在西部荒野灯塔的一名海盗船长的游荡灵魂。他的船在黑暗的海岸线上撞毁，失去了自己的生命，现在他看守着灯塔，以防其他水手遭受同样的命运。",kw={"葛瑞森船长","幽灵海盗","葛瑞森","灯塔","老瞎眼","西部荒野","西部荒野灯塔"},ang={["class:Paladin"]="尽管葛瑞森是一个亡灵，但他的目的是无私且具有保护性的。协助他就是对捍卫无助者和清除致命鱼人潮这一神圣职责的尊重。",["class:Priest"]="葛瑞森的灵魂被目睹无辜家庭死亡所带来的内疚和悲痛所束缚。提供援助能给这颗不安的灵魂带来一丝慰藉。",["faction:Alliance"]="随着迪菲亚潜行者对西部荒野的封锁以及暴风城对边境的疏于管理，前来西部荒野的联盟旅行者有责任响应葛瑞森的请求，保住灯塔的火焰。"},sec={{t="被岩石断送的一生",b="生前，葛瑞森曾在东部王国险恶的南部海域指挥一艘船只。在一个灯塔之火熄灭的夜晚，他的航程在西部荒野崎岖的浅滩处迎来了一个暴力的终局。葛瑞森的船撞上了岩石，他和船只一起覆灭，最后变成了一个被困在海岸上的尘世幽灵。"},{t="灯塔的悲剧",b="死后被吸引到西部荒野灯塔的葛瑞森，本希望找到关于来世的答案。但他目睹的却是一场惨剧。一个被称为老瞎眼的臭名昭著的鱼人驱逐了灯塔管理员及其家人。尽管管理员们勇敢地回来重新点燃了火焰，老瞎眼却召集了周围的鱼人进行了第二次残酷的屠杀。葛瑞森只能无助地看着那家人被屠戮殆尽。"},{t="幽灵的守望",b="随着管理员的死亡和西部荒野在疏于管理下的衰败，葛瑞森船长在自己虚幻的肩膀上承担起了看守灯塔的重任。他向路过的冒险者寻求援助，收集燃油以维持伟大的火焰，并试图通过猎杀老瞎眼和击退沿海的鱼人潮来为惨死的家庭复仇。"}},faq={{q="葛瑞森船长是谁？",a="葛瑞森船长是一个居住在西部荒野灯塔的人类幽灵海盗。在他因灯塔熄灭而在海岸遇难后，他的灵魂开始自行承担起维护灯塔和保护路过水手的职责。",al={"葛瑞森身份","谁是那个幽灵海盗","灯塔幽灵"}},{q="葛瑞森船长是怎么死的？",a="他在驾驶海盗船驶向西部荒野沿岸的危险岩石时遇难。那天晚上灯塔是黑的，他和他的船员在船身破碎前没有得到任何警告。",al={"葛瑞森之死","葛瑞森如何成为幽灵","是什么杀死了葛瑞森船长"}},{q="真正的灯塔管理员发生了什么事？",a="管理员和他的家人遭到了沿海鱼人的袭击。虽然他们从最初的袭击中逃脱并返回重新点燃了灯塔，但老瞎眼组织了第二次突袭，并在葛瑞森眼前屠杀了他们所有人。",al={"灯塔管理员在哪里","管理员发生了什么","灯塔一家"}},{q="老瞎眼是谁？",a="老瞎眼是一个狡猾而残暴的鱼人首领，潜伏在西部荒野的海岸线上。是他领导了杀害灯塔管理员一家的袭击，并对任何试图保持灯塔点亮的人构成持续的威胁。",al={"老瞎眼背景故事","老瞎眼","西部荒野鱼人首领"}},{q="为什么葛瑞森想要保持灯塔点亮？",a="因为海岸线漆黑一片而溺亡，葛瑞森将确保没有其他水手在浅滩遭遇同样的命运视为他在来世的神圣职责。",al={"葛瑞森动机","为什么要点亮灯塔"}},{q="葛瑞森船长对冒险者有敌意吗？",a="没有。尽管生前有着海盗背景，葛瑞森对生者并无恶意。他目睹了太多的屠杀，只寻求平静以及在维护火焰方面的协助。",al={"葛瑞森是否友好","葛瑞森敌意"}}},fp="15,183,29.290.0,21.372.0,15.310.0,23.171.0,28.203.0,44.217.0,20.193.0,46.176.0,42.160.0"}
P.entries["npc:captain-greenskin"] = {n="绿皮队长",s="绿皮队长是一名精英地精海盗，负责监督艾德温·范克里夫那艘巨型铁甲战舰的建造和船员管理。他潜藏在死亡矿井深处的地下海湾中，指挥着由迪菲亚潜行者雇佣的海盗部队。他的目标是将这艘战舰准备就绪，驶向暴风城。",h="绿皮队长是一名精英地精海盗，负责监督艾德温·范克里夫那艘巨型铁甲战舰的建造和船员管理。他潜藏在死亡矿井深处的地下海湾中，指挥着由迪菲亚潜行者雇佣的海盗部队。他的目标是将这艘战舰准备就绪，驶向暴风城。",kw={"绿皮队长","死亡矿井","地精海盗","绿皮","战舰","重拳","范克里夫"},ang={["class:Rogue"]="绿皮处于迪菲亚海盗势力的顶峰，就在战舰甲板上，由海盗和暴徒重兵把守。",["faction:Alliance"]="对于联盟军队来说，绿皮队长代表着迪菲亚叛乱的海上威胁；如果他的战舰突破海岸，西部荒野和暴风城毫无防备的海岸线将直接面临危险。"},sec={{t="战舰之主",b="绿皮队长在死亡矿井海湾中那艘正在建造的巨型战舰的主甲板上踱步，他代表了迪菲亚阴谋的海军中坚力量。作为一名经验丰富的地精海员，绿皮被带入了艾德温·范克里夫的核心圈子，将一座地下洞穴改造成了制造战争机器的干船坞。"},{t="海盗船员",b="绿皮指挥的并非普通的石匠或强盗船员。在他的直接监视下，服役着一群经验丰富的切喉手，其中包括他那令人生畏的牛头人大副重拳先生和鱼人船厨曲奇。他们共同把守着船只的跳板和上层甲板，挡在入侵者与范克里夫位于舰桥顶部的私人船舱之间。"}},faq={{q="绿皮队长是谁？",a="绿皮队长是一名地精海盗船长，受艾德温·范克里夫雇佣，负责监督迪菲亚潜行者在死亡矿井中秘密战争巨舰的完工和运作。",al={"绿皮背景故事","绿皮是谁","绿皮队长"}},{q="绿皮在加入迪菲亚之前从何而来？",a="没有记录显示绿皮在受雇于范克里夫之前航行于何处。人们只知道他是指挥死亡矿井中迪菲亚战舰及其船员的地精海盗船长。",al={"绿皮的起源","绿皮来自哪里","绿皮藏宝海湾"}},{q="谁在绿皮队长的麾下服役？",a="他的指挥部下包括他的大副——牛头人重拳先生，以及鱼人厨师曲奇，还有一队在铁甲舰甲板上巡逻的迪菲亚海盗。",al={"绿皮的船员","大副","绿皮的手下"}},{q="绿皮在死亡矿井的目的是什么？",a="他的任务是使这艘巨大的铁甲战舰具备适航能力，并准备驶出地下洞窟，进入无尽之海，对暴风城王国发起打击。",al={"绿皮做什么","绿皮为什么在这里"}},{q="在哪里可以找到绿皮队长？",a="他在死亡矿井最后一间洞穴中停泊的大型战舰的主甲板上踱步，守卫着通往艾德温·范克里夫的通道。",al={"绿皮位置","绿皮队长在哪里"}},{q="绿皮队长是迪菲亚潜行者的一员还是雇佣兵？",a="他是一名直接受雇于艾德温·范克里夫的雇佣海盗船长，指挥着与迪菲亚潜行者的阴谋相一致的海军部队。",al={"绿皮是迪菲亚吗","绿皮阵营"}}},fx={["9c1c4117"]={q="绿皮队长为什么在这里？",a="绿皮队长受艾德温·范克里夫雇用，负责监督迪菲亚潜行者巨型主宰战舰的建造并指挥战舰。他留在死亡矿井深处的海湾中，指挥自己的海盗船员，确保战舰完工并装备齐全。",al={"绿皮为什么在死亡矿井","绿皮队长为什么在这里","绿皮在死亡矿井的目的"}},["6bcae29e"]={q="绿皮队长想要什么？",a="作为受雇的地精船长，绿皮追求财富和统率舰队的刺激。他打算在死亡矿井的海湾中建造完这艘庞大的铁甲战舰，然后驾船驶入无尽之海，为艾德温·范克里夫对付暴风城的阴谋效力。",al={"绿皮的目标","绿皮队长想要什么","绿皮的动机"}},["433e5911"]={q="绿皮队长为何令人畏惧？",a="绿皮队长统率着艾德温·范克里夫主宰战舰上的海盗船员，手下还有他的牛头人副手重拳先生这样的凶残掠夺者。他手持砍刀和涂毒鱼叉，在甲板上巡行，挡在入侵者和范克里夫之间。",al={"绿皮为何令人畏惧","绿皮队长的名声","绿皮有名吗"}}},fp="17,220,24.234.0,15.276.0,25.169.0,56.135.0,35.128.0,45.153.0,37.149.0,67.154.0"}
P.entries["npc:captain-rugelfuss"] = {n="拉格弗斯上尉",s="拉格弗斯上尉是一位驻守在国王谷南大门的严厉的矮人军官。他肩负着保卫洛克莫丹边境的重任，负责组织防御，抵御突如其来的穴居人暴乱。",h="拉格弗斯上尉是一位驻守在国王谷南大门的严厉的矮人军官。他肩负着保卫洛克莫丹边境的重任，负责组织防御，抵御突如其来的穴居人暴乱。",kw={"拉格弗斯上尉","铁炉堡卫兵","洛克莫丹","山地巡逻队员","拉格弗斯","穴居人威胁","国王谷"},ang={["class:Warrior"]="战士们会发现拉格弗斯那种雷厉风行的战术作风，以及用刀盾清理前线的直接指令，与他们的意气相投。",["faction:Alliance"]="拉格弗斯提醒联盟的旅行者，当主力军队在别处作战时，保卫家园免受野蛮入侵对联盟的生存至关重要。",["race:Dwarf"]="对矮人而言，拉格弗斯上尉代表了铁炉堡军队坚定不移的决心，守护着祖先的山口，抵御着地底深处的宿敌。"},sec={{t="坚守南大门",b="拉格弗斯上尉驻扎在国王谷那座宏伟的雕刻拱门旁，负责看守通往洛克莫丹的南部大门。由于联盟的军队分散在世界各地，铁炉堡需要像他这样的老练军官来确保领土安全。拉格弗斯不屑于那些军事排场和繁文缛节，他更倾向于将全部精力集中在边境面临的严峻现实上。"},{t="穴居人入侵",b="拉格弗斯当前首要应对的危机是日益严重的穴居人威胁。这些野蛮的生物从古老的洞穴中涌出，冲入高地，击溃了边远的矮人巡逻队，并在附近建立了坚固的据点。为了捍卫国王的土地，这位上尉招募有能力的旅行者去削减它们的数量，将这些生物驱逐出大路。"},{t="前线侦察",b="拉格弗斯的职责不仅仅是动用武力。他的山地巡逻队员一直在不断侦察穴居人的营地。"}},faq={{q="谁是拉格弗斯上尉？",a="拉格弗斯上尉是一位驻扎在洛克莫丹境内国王谷南大门的铁炉堡矮人军事指挥官。他负责区域防御和边境安全。",al={"拉格弗斯上尉背景故事","谁是拉格弗斯","拉格弗斯 洛克莫丹"}},{q="在哪里可以找到拉格弗斯上尉？",a="他驻扎在国王谷的南大门附近，守卫着从洛克莫丹通往丹莫罗的南部隘口。",al={"拉格弗斯在哪里","拉格弗斯上尉位置"}},{q="为什么拉格弗斯上尉会担心穴居人？",a="近期发生的穴居人暴乱对矮人的定居点和补给线构成了严重威胁。穴居人已经直接侵犯了南大门，并袭击了铁炉堡的巡逻队，如果置之不理，它们可能会占领国王的领土。",al={"为什么要对抗穴居人","洛克莫丹的穴居人威胁"}},{q="为什么拉格弗斯不讲究军事礼节？",a="在国王的土地正遭受围攻时，拉格弗斯认为不必要的敬礼和仪式会造成危险的分心。他要求采取直接、实际的行动，而不是拘泥于礼节。",al={"拉格弗斯的性格","矮人军人作风"}}},fp="17,134,25.270.0,19.263.0,24.96.1,25.159.0,37.137.0,48.184.0,50.144.0"}
P.entries["npc:captain-shatterskull"] = {n="沙塔尔·碎颅",s="沙塔尔·碎颅是一位经验丰富的兽人指挥官，驻扎在贫瘠之地北疆的莫尔杉营地。作为部落的关键堡垒，他负责协调力量，击退在战歌峡谷附近边境挑衅的暗夜精灵部队。",h="沙塔尔·碎颅是一位经验丰富的兽人指挥官，驻扎在贫瘠之地北疆的莫尔杉营地。作为部落的关键堡垒，他负责协调力量，击退在战歌峡谷附近边境挑衅的暗夜精灵部队。",kw={"贫瘠之地","沙塔尔·碎颅","卡德拉克","莫尔杉营地","兽人队长","碎颅","银翼","战歌"},ang={["faction:Horde"]="对于从南贫瘠之地赶来的部落战士来说，沙塔尔·碎颅代表了抵御来自灰谷的暗夜精灵入侵的坚强前卫。",["race:Orc"]="碎颅体现了新部落坚韧不拔的尚武精神，守护着他们来之不易的土地，对抗那些将他们的存在视为入侵者的人。"},sec={{t="北境守卫者",b="沙塔尔·碎颅驻扎在灰谷边缘的莫尔杉营地，奋战在部落领土冲突的最前线。在卡德拉克等军官的协助下，碎颅努力维持部落在这一地区的立足点，对抗试图夺回边境之地的暗夜精灵哨兵和银翼要塞部队。他的哨位需要时刻保持警惕，因为围绕灰谷木材和古老土地的冲突随时可能蔓延到贫瘠之地。"}},faq={{q="谁是沙塔尔·碎颅？",a="沙塔尔·碎颅是一位驻扎在贫瘠之地北缘莫尔杉营地的兽人军官，负责监督防御工作以抵御暗夜精灵。",al={"碎颅身份","谁是沙塔尔·碎颅","碎颅npc"}},{q="在哪里可以找到沙塔尔·碎颅？",a="他位于莫尔杉营地，坐落在贫瘠之地的最北端边界，进入灰谷之前的位置。",al={"碎颅位置","沙塔尔·碎颅在哪里","莫尔杉营地碎颅"}},{q="他在莫尔杉营地的职责是什么？",a="碎颅担任前线指挥官，协助防御部落的北疆，集结战士以抵御联盟的银翼哨兵。",al={"碎颅做什么","碎颅目标","莫尔杉指挥官"}},{q="沙塔尔·碎颅与谁共事？",a="他与卡德拉克等其他营地内杰出的前线军官并肩作战，协调边境冲突的防御和征兵工作。",al={"碎颅盟友","卡德拉克与碎颅"}}},fp="20,206,31.335.0,28.128.0,40.110.0,39.163.0,40.131.0"}
P.entries["npc:captain-stoutfist"] = {n="斯托菲队长",s="斯托菲队长是负责湿地米奈希尔港军事防御的矮人军官。随着龙喉氏族大举进攻，企图从他们的沼泽据点向外扩张，斯托菲队长正指挥着防御和反击行动，以确保这座至关重要的联盟港口不会陷落。",h="斯托菲队长是负责湿地米奈希尔港军事防御的矮人军官。随着龙喉氏族大举进攻，企图从他们的沼泽据点向外扩张，斯托菲队长正指挥着防御和反击行动，以确保这座至关重要的联盟港口不会陷落。",kw={"斯托菲队长","龙喉氏族","丹奥加兹","矮人","铁炉堡","米奈希尔港","尼克罗什","湿地"},ang={["class:Warrior"]="作为一名务实的矮人战术家，斯托菲重视大胆的军事打击胜过谨慎的防御工事，他让战士们冲在第一线，拆除敌人的火炮并消灭其首领。",["faction:Alliance"]="斯托菲队长在联盟最重要的海上枢纽之一坚守防线，保持着卡兹莫丹、暴风城与远方哨所之间的航线畅通。",["race:Dwarf"]="斯托菲代表了铁炉堡军队坚韧不拔的意志，受命保卫着深埋在山峰庇护之下的重要低地基础设施。"},sec={{t="米奈希尔的捍卫者",b="米奈希尔港是连接铁炉堡、暴风城与湿地沼泽低地及外海的主要深水港口。作为该城镇的指挥官，斯托菲队长肩负着沉重的重担，要保护其码头、平民和驻军免受周围威胁。沼泽地环境恶劣，举世皆知，但该定居点面临的最大危险是来自反叛兽人的有组织突袭。"},{t="龙喉氏族的威胁",b="自第二次战争以来一直盘踞在湿地的龙喉氏族，已开始将其行动直接推向公路和隘口。他们潜入丹奥加兹，威胁要切断连接洛克莫丹、铁炉堡与米奈希尔港的陆路生命线。面对兵力严重短缺的局面，斯托菲队长只能依靠登山家瓦斯塔格·铁腭推荐的前来帮忙的联盟志愿者来抵御攻势。"},{t="打击尼克罗什",b="斯托菲队长并未坐等围攻，而是对兽人营地发动了积极的攻势。他指挥盟军夺取维尔加挖掘场附近的战旗，破坏龙喉氏族准备用来发动突袭的投石车，并铲除该氏族在当地残暴的首领——尼克罗什·碎颅者。通过除掉尼克罗什，斯托菲旨在米奈希尔港被压垮之前，彻底摧毁兽人的攻势。"}},faq={{q="斯托菲队长是谁？",a="斯托菲队长是负责保卫米奈希尔港的矮人军事指挥官。他负责协调驻军防御、评估地区威胁，并招募志愿者来击退针对该港口的敌人。",al={"斯托菲队长","斯托菲 米奈希尔","米奈希尔队长"}},{q="斯托菲队长在哪里？",a="他驻扎在湿地西海岸的主要联盟枢纽——米奈希尔港内。",al={"斯托菲位置","斯托菲队长在哪里","寻找斯托菲"}},{q="为什么斯托菲队长需要外界帮助？",a="当地驻军在湿地的兵力捉襟见肘。随着龙喉兽人占领了丹奥加兹的山口并不断向城镇推进，斯托菲缺乏足够的常备兵力来同时发动攻势和维持港口安全。",al={"为什么斯托菲需要帮助","米奈希尔防御问题"}},{q="尼克罗什·碎颅者是谁？",a="尼克罗什·碎颅者是盘踞在湿地的龙喉兽人的残暴领袖。斯托菲队长下令将其处决，旨在粉碎兽人的组织能力，保护米奈希尔港免受全面突袭。",al={"尼克罗什是谁","尼克罗什·碎颅者","龙喉首领 湿地"}},{q="丹奥加兹与斯托菲队长的任务有何关联？",a="丹奥加兹是连接洛克莫丹、铁炉堡与湿地的重要山口。当龙喉兽人推进到山口时，登山家瓦斯塔格·铁腭发出警告称米奈希尔已陷入危局，并将冒险者引荐给斯托菲，以帮助加固港口防线。",al={"丹奥加兹 斯托菲","阿尔加兹关口连接"}},{q="龙喉投石车构成了什么威胁？",a="龙喉氏族组装了攻城武器，旨在摧毁防御工事并直接围攻米奈希尔港。斯托菲指挥勇士们在这些投石车进入射程之前就将其破坏。",al={"尼克罗什的计谋 投石车","龙喉投石车"}}},fx={["40162abd"]={q="斯托菲队长效忠哪一方？",a="斯托菲队长效忠联盟和矮人王国铁炉堡。他驻扎在米奈希尔港，指挥镇上的驻军，守护这座至关重要的港口城镇，并保护往来于湿地与卡兹莫丹群山之间的旅人。",al={"斯托菲队长所属阵营","斯托菲是联盟的吗","斯托菲为谁效力"}},["31290b24"]={q="斯托菲队长想要什么？",a="斯托菲队长想彻底铲除步步逼近的龙喉兽人威胁。他要从龙喉兽人的营地夺取战旗，烧毁奈克罗什为围攻米奈希尔港而建造的投石车，并杀死他们的酋长奈克罗什·碎骨者，以确保米奈希尔港的安全。",al={"斯托菲队长的目标","斯托菲需要什么","斯托菲的目标"}},["6891235c"]={q="斯托菲队长为何在米奈希尔港？",a="斯托菲队长驻扎在米奈希尔港，负责指挥港口防务。丹奥加兹的战略山道已被敌对的龙喉兽人封锁，他留在这里召集士兵和佣兵，保护港口免遭摧毁。",al={"斯托菲为何在湿地","斯托菲队长在米奈希尔的职责","斯托菲为何在这里"}},["2b51270f"]={q="斯托菲队长与谁有联系？",a="斯托菲队长与卡兹莫丹各地的联盟守军协调行动，并接收瓦斯塔格·铁腭调派的援军。他指挥米奈希尔城堡的驻军，依靠途经此地的联盟勇士直接向龙喉氏族发起进攻。",al={"斯托菲队长的盟友","斯托菲队长与谁共事","斯托菲队长的关系"}}},fp="17,199,20.331.0,20.371.0,20.372.1,25.212.0,35.110.0,45.226.0,29.193.0,58.260.0,44.163.0"}
P.entries["npc:captain-thalo-thas-brightsun"] = {n="沙罗萨斯船长",s="沙罗萨斯船长是一名隶属于热砂港的私掠者，驻扎在棘齿城的码头。尽管他对前往那里的联盟成员保持着客气的态度，但他对北方城堡里那些胆敢炮击他船只的塞拉摩军队怀有强烈的怨恨。",h="沙罗萨斯船长是一名隶属于热砂港的私掠者，驻扎在棘齿城的码头。尽管他对前往那里的联盟成员保持着客气的态度，但他对北方城堡里那些胆敢炮击他船只的塞拉摩军队怀有强烈的怨恨。",kw={"贫瘠之地","沙罗萨斯","北方城堡","棘齿城","热砂港","塔洛丹私掠者","沙罗萨斯船长"},ang={["faction:Alliance"]="沙罗萨斯船长在港口会与你客气交谈，但北方城堡的塞拉摩军队不断施加的侵略行为，已迫使他暗中与你们的敌人勾结。",["faction:Horde"]="沙罗萨斯船长为部落提供了打击北方城堡的宝贵借口，以此瘫痪了卡利姆多中部沿海的联盟海军火炮。"},sec={{t="棘齿城私掠者",b="沙罗萨斯船长以繁忙的中立港口棘齿城为基地，在热砂港的大旗下统领着塔洛丹私掠者。理论上，只要钱给够，棘齿城的商人们欢迎任何旗帜的船只，但贫瘠之地沿海的海上贸易充满了危险。在港口以南，坐落着北方城堡，这是一座具有侵略性的联盟要塞，其重型火炮威胁着中立航道。沙罗萨斯船长对来访的旅客保持着表面上的中立，但他对这支不断炮击他船队的交战驻军已经忍无可忍。"},{t="与北方城堡的私下战争",b="由于全面冲突会危及棘齿城的中立地位，沙罗萨斯船长不能派遣一支公开的武装舰队去对抗要塞。相反，他寄希望于有能力的部落雇佣兵来解决这笔账。他秘密安排了针对北方城堡的袭击，以摧毁要塞的大炮并确保他被俘船员的安全。通过雇佣部落人员而非直接挑起联盟对卡特尔的报复，沙罗萨斯船长既保护了自己的航运利益，又保持了棘齿城官方账目的清白。"}},faq={{q="沙罗萨斯船长是谁？",a="沙罗萨斯船长是一位船长，也是塔洛丹私掠者的首领，在棘齿城为热砂港效力。",al={"沙罗萨斯船长","谁是沙罗萨斯船长","棘齿城船长"}},{q="他为什么对北方城堡感到愤怒？",a="驻扎在北方城堡的联盟军队一再用重炮轰击他的商船，并监禁了他的水手，破坏了沿海的贸易活动。",al={"为什么要攻击北方城堡","沙罗萨斯与北方城堡的问题","为什么憎恨联盟"}},{q="他为什么只雇佣部落去攻击北方城堡？",a="虽然他对造访棘齿城的联盟旅客保持外交上的中立，但他无法合理地要求联盟的拥护者去轰炸像北方城堡这样的联盟据点。然而，部落有充分的战略理由削弱塞拉摩的军事前哨。",al={"联盟可以做他的任务吗","为什么只找部落","沙罗萨斯的联盟任务"}},{q="他属于联盟还是部落？",a="他两者都不属于；他主要效忠于热砂港和他自己的私掠者，尽管他的不满使得他目前的利益与部落一致。",al={"沙罗萨斯的阵营","沙罗萨斯是部落吗","沙罗萨斯是中立的吗"}}},fp="28,220,20.444.0,29.428.0,36.114.0,35.163.0,53.193.0,44.180.0"}
P.entries["npc:captured-mountaineer"] = {n="被俘虏的巡山人",s="“被俘虏的巡山人”是一名被关在布瑞尔“恐惧之末旅店”地下室里的铁炉堡矮人。他被遗忘者捆绑并严加看管，成为了皇家药剂师协会残酷实验中不情愿的实验品。",h="“被俘虏的巡山人”是一名被关在布瑞尔“恐惧之末旅店”地下室里的铁炉堡矮人。他被遗忘者捆绑并严加看管，成为了皇家药剂师协会残酷实验中不情愿的实验品。",kw={"新型瘟疫","药剂师乔汉","布瑞尔地下室","被俘虏的巡山人","矮人囚犯","恐惧之末旅店","铁炉堡侦察兵"},ang={["race:Dwarf"]="看见一位骄傲的铁炉堡同胞被囚禁在遗忘者的旅店之下，并遭受可怕的炼金术折磨，这让人苦涩地意识到遗忘者对活物那冷酷无情的敌意。",["race:Undead"]="对遗忘者而言，活着的联盟俘虏是皇家药剂师协会的重要资源，他们的目标是完善一种能够同时消灭天灾军团和活体敌人的瘟疫。"},sec={{t="地下室里的囚犯",b="这名铁炉堡巡山人被关在布瑞尔“恐惧之末旅店”的地板下，远离卡兹莫丹的安全庇护。当上面的客人在饮酒作乐时，皇家药剂师协会却将他当作药剂的试验品。药剂师乔汉和他的同僚们正在测试他们开发的瘟疫对联盟活体生理的致命效力，利用这名囚犯来衡量他们的毒素能在多快的时间内让活物经历痛苦而迅速的死亡。"}},faq={{q="谁是“被俘虏的巡山人”？",a="他是一名来自铁炉堡的联盟侦察兵，不幸落入了遗忘者手中。他目前被关在布瑞尔“恐惧之末旅店”的地下室里。",al={"这个矮人是谁","布瑞尔旅店里的矮人","被俘的矮人"}},{q="为什么遗忘者要把他活着关在地下室里？",a="皇家药剂师协会将他作为活体实验对象。药剂师乔汉等人并没有直接处决他，而是给他注射各种实验性的混合药剂，以研究它们对活体矮人生理机能的效果。",al={"为什么要留活口","他为什么在旅店里","他们对这个矮人做了什么"}},{q="在实验过程中他会怎样？",a="作为研发新型瘟疫研究的一部分，他被迫服用药剂师酿制的混合药剂。这些致命的混合物很快便显现出效果，通过终结这名囚犯的生命来证明毒素的进展。",al={"矮人会死吗","新型瘟疫发生了什么"}},{q="还有谁会在这里与他接触？",a="除了进行实验的药剂师外，死亡卫士也会利用旅店地下室作为临时牢房，将抓获的巡山人关押在此，直到他们被“妥善”处理。",al={"谁会和这个矮人交谈","renee lauer"}}},fp="20,159,24.334.0,32.110.0,55.164.0,37.139.1,38.149.0"}
P.entries["npc:captured-scarlet-zealot"] = {n="血色十字军俘虏",s="血色十字军俘虏是关押在布瑞尔恐惧之末旅店地下室中的一名十字军囚犯。他由被遗忘者药剂师和城镇居民严密看管，是皇家药剂师学会正在研发的药剂的活体测试对象。",h="血色十字军俘虏是关押在布瑞尔恐惧之末旅店地下室中的一名十字军囚犯。他由被遗忘者药剂师和城镇居民严密看管，是皇家药剂师学会正在研发的药剂的活体测试对象。",kw={"药剂师乔汉","布瑞尔","血色十字军俘虏","恐惧之末旅店","囚犯","血色十字军","提瑞斯法林地"},ang={["class:Priest"]="血色十字军狂热者声称对圣光拥有独占权，但这名囚犯坚定不移的狂热在被遗忘者残酷囚禁的现实面前毫无防御力。",["race:Undead"]="对于布瑞尔的被遗忘者来说，这个锁链加身的狂热者代表了那些寻求消灭他们的无情十字军，将其作为药剂师的实验品显然更有价值。"},sec={{t="布瑞尔的苦涩俘虏",b="这名被关押在恐惧之末旅店下方的血色十字军成员体现了他们组织坚不可摧的狂热。即使身陷囹圄，被他视为污秽之物的亡灵所包围，他也毫不悔改，呼唤圣光保护他免受周围这些邪恶且亵渎的生物的伤害。对于被遗忘者来说，俘获这名狂热者并非仁慈之举，而是为药剂师乔汉正在开发的实验性瘟疫和毒素提供了宝贵的活体测试材料。"}},faq={{q="为什么血色十字军俘虏会被关在布瑞尔？",a="被遗忘者将他关在旅店地下室作为活体，用于测试皇家药剂师学会研发的新型毒药和化学药剂。",al={"为什么血色十字军俘虏会被抓住","为什么让狂热者活着","布瑞尔地窖里的狂热者是谁"}},{q="我在哪里可以找到这个俘虏？",a="他被囚禁在位于提瑞斯法林地布瑞尔中心地带的恐惧之末旅店潮湿的地窖中。",al={"血色十字军俘虏在哪里","血色十字军俘虏位置","布瑞尔的狂热者"}},{q="他对周围的被遗忘者有何反应？",a="尽管身陷囹圄，他依然狂热且桀骜不驯，大声呼唤圣光保护他免受亡灵囚禁者的伤害，并誓言血色十字军将把艾泽拉斯从他们手中清除。",al={"狂热者说了什么","狂热者对话","蕾妮·劳尔与狂热者"}}},fp="23,155,25.457.0,44.164.0,30.96.0,45.163.0"}
P.entries["npc:carendin-halgar"] = {n="凯伦丁·哈加尔",s="凯伦丁·哈加尔是一位知名的被遗忘者术士训练师，居住在幽暗城的魔法区。他言辞犀利，并且出了名的缺乏耐心，负责监督那些初涉暗影技艺者的训练。他指导有志于成为术士的人如何从扭曲虚空征服强大的恶魔实体，尤其是传授绑定虚空行者和魅魔的仪式。",h="凯伦丁·哈加尔是一位知名的被遗忘者术士训练师，居住在幽暗城的魔法区。他言辞犀利，并且出了名的缺乏耐心，负责监督那些初涉暗影技艺者的训练。他指导有志于成为术士的人如何从扭曲虚空征服强大的恶魔实体，尤其是传授绑定虚空行者和魅...",kw={"凯伦丁·哈加尔","虚空生物","被遗忘者","哈加尔","magic quarter","魅魔","束缚","训练师","幽暗城","虚空行者","术士"},ang={["class:Warlock"]="凯伦丁·哈加尔是洛丹伦的一位关键导师，指导术士们通过严酷的考验，以征服并绑定虚空行者和魅魔。",["faction:Horde"]="凯伦丁是部落术士在东部王国的主要引导者，负责协调跨越海洋在卡利姆多开展训练的黑暗修行者。",["race:Undead"]="凯伦丁反映了被遗忘者那毫不妥协的精神，他不表现出任何怜悯或犹豫，将恶魔实体视为纯粹的、应当被击碎和利用的工具。"},sec={{t="暗影技艺大师",b="在幽暗城魔法区那有害的阴暗环境中，凯伦丁·哈加尔指导着那些深入探索扭曲虚空的人。他要求专注和服从，对失败、犹豫或软弱几乎毫无容忍。在他的严密注视下，术士们超越了基础咒语，进入了召唤和灵魂操纵的危险领域，这巩固了被遗忘者对待恶魔奴役那残酷无情的方式。"},{t="征服虚空",b="凯伦丁的核心教学围绕着将愈发危险的恶魔束缚于召唤者的意志之下。他派遣学生前往洛丹伦及更远的地方取回古老的符文、符文石以及凡人的纯净精华，以完成危险的召唤仪式。无论是指挥一只来自虚空的阴影生物，还是诱惑魅魔进入束缚，凯伦丁都确保术士在恶魔吞噬主人之前将其彻底征服。"}},faq={{q="在哪里可以找到凯伦丁·哈加尔？",a="凯伦丁·哈加尔位于幽暗城的魔法区，与其他邪能和暗影魔法的从业者聚集在一起。",al={"凯伦丁·哈加尔位置","幽暗城术士训练师位置","哈加尔在哪里"}},{q="凯伦丁·哈加尔对术士来说扮演什么角色？",a="他担任部落术士的导师和任务发布者，指导他们完成召唤并永久绑定主要恶魔（如虚空行者和魅魔）所需的仪式。",al={"凯伦丁做什么","哈加尔的目标","凯伦丁任务"}},{q="凯伦丁·哈加尔的性格如何？",a="他出了名的直言不讳、严苛，而且完全没有耐心。他期待学生能迅速拿出成果，并且鄙视浪费时间或寻找借口。",al={"哈加尔脾气","凯伦丁和善吗","凯伦丁·哈加尔背景故事"}},{q="为什么凯伦丁需要纯洁的心来进行召唤仪式？",a="在关于召唤魅魔的课程中，哈加尔的助手高德瑞克·法杉指派侍僧去获取纯洁之人的无瑕之心，利用他们的天真和精华作为诱饵，以引诱并捕捉邪恶的恶魔进入束缚法阵。",al={"纯洁之心的用途","凯伦丁魅魔召唤","为什么需要纯洁的心"}},{q="凯伦丁·哈加尔会与幽暗城以外的术士互动吗？",a="是的。他会派遣有前途的学生前往贫瘠之地寻找斯坦哈德·法尔杉，以继续他们的学业。",al={"凯伦丁人脉","哈加尔奥格瑞玛","甘鲁尔·血眼凯伦丁"}},{q="凯伦丁会派遣高阶术士去见谁？",a="一旦侍僧展现出对基础恶魔足够的掌控力，凯伦丁就会指引他们向外寻求更深奥的指导，例如派遣他们前往贫瘠之地寻找古怪的召唤师斯坦哈德·法尔杉。",al={"寻找斯坦哈德","凯伦丁派遣你去见谁","哈加尔下一位导师"}}},fp="15,213,23.313.0,22.349.1,35.112.0,49.122.0,43.124.0,60.203.0,66.105.0,48.159.0"}
P.entries["npc:caretaker-folsom"] = {n="管理员弗索姆",s="管理员弗索姆是一位神情忧郁的人类仆役，出现在暴风城运河边，靠近公园区。他曾是弗林特里奇贵族庄园深受信赖的管家，如今却只能处理他们悲惨覆灭后留下的苦涩残局。",h="管理员弗索姆是一位神情忧郁的人类仆役，出现在暴风城运河边，靠近公园区。他曾是弗林特里奇贵族庄园深受信赖的管家，如今却只能处理他们悲惨覆灭后留下的苦涩残局。",kw={"运河","管理员弗索姆","弗林特里奇","弗索姆","密斯莱托","公园","斯塔文","暴风城"},ang={["faction:Alliance"]="对于追踪暮色森林最臭名昭著的杀手那残酷命运的联盟调查员来说，弗索姆提供了关于弗林特里奇家族最后日子的不可或缺的活线索。"},sec={{t="毁于一旦的家园",b="和他的父亲一样，弗索姆一生都在侍奉弗林特里奇家族，担任他们的庄园管理员。那平静的服务生涯随着弗林特里奇一家的惨遭屠戮而血腥告终。随着血脉断绝，庄园从此荒废，直到其剩余的资金彻底枯竭。弗索姆孑然一身，留守看顾这个家族的残骸，肩负着变卖家族幸存传家宝和财产的悲伤职责。"},{t="一段黑暗往事的牵连",b="追踪斯塔文·密斯莱托血腥历史的调查员，经常被指引去暴风城运河步道寻找弗索姆。尽管饱受悲痛与不情愿的折磨，但这位管理员掌握着这场悲剧的关键线索，包括来自弗林特里奇庄园的幸存财物和文件，揭示了斯塔文令人不安的堕落历程，以及他最终消失在暮色森林阴影中的经过。"}},faq={{q="管理员弗索姆是谁？",a="他是暴风城的一位人类仆役，曾照料弗林特里奇贵族庄园。在弗林特里奇一家惨遭谋杀后，他留下来负责处理他们剩余的财产。",al={"弗索姆","弗索姆是谁","管理员弗索姆背景故事"}},{q="我在哪里可以找到管理员弗索姆？",a="他站在暴风城运河的石砌步道旁，靠近公园区的入口处。",al={"管理员弗索姆在哪里","弗索姆位置","管理员弗索姆暴风城"}},{q="弗林特里奇一家发生了什么事？",a="该家族多年前在庄园中惨遭屠杀。由于没有继承人来认领庄园，房产被查封并陷入荒废，直至资金耗尽。",al={"弗林特里奇谋杀案","弗林特里奇发生了什么","谁杀了弗林特里奇一家"}},{q="为什么弗索姆要变卖家族传家宝？",a="在家族覆灭后，他们剩余的资金最终彻底枯竭。弗索姆被委以严酷的重任，将庄园中仅存的财物送去拍卖。",al={"为什么拍卖","弗林特里奇拍卖","弗索姆拍卖"}},{q="他在“斯塔文的传说”中扮演什么角色？",a="弗索姆通过提供弗林特里奇庄园遗留下的剩余个人物品和线索，协助冒险者拼凑出斯塔文·密斯莱托那场悲剧的真相。",al={"斯塔文任务弗索姆","斯塔文的传说弗索姆"}}},fp="16,184,16.277.0,19.321.1,24.182.0,34.112.0,39.152.1,43.129.0,42.139.0"}
P.entries["npc:carolai-anise"] = {n="卡罗莱·安尼斯",s="卡罗莱·安尼斯是一名古怪的被遗忘者炼金术士，居住在提瑞斯法林地的布瑞尔村。她负责训练炼金术新手，不过她那危险的药剂已经引起了当地卫兵不安的低语。",h="卡罗莱·安尼斯是一名古怪的被遗忘者炼金术士，居住在提瑞斯法林地的布瑞尔村。她负责训练炼金术新手，不过她那危险的药剂已经引起了当地卫兵不安的低语。",kw={"炼金术","药剂师","布瑞尔","卡罗莱·安尼斯","被遗忘者训练师","提瑞斯法林地"},ang={["profession:Herbalism"]="在提瑞斯法各地采集野生植物的采集者经常把宁神花、银叶草和地根草带给卡罗莱，以便提炼成强效的混合药剂。",["race:Undead"]="对于那些刚刚获得自由、正在学习操控试剂的被遗忘者来说，卡罗莱在提瑞斯法林地提供了炼金术的基础知识。"},sec={{t="危险的技艺",b="卡罗莱·安尼斯在布瑞尔开展工作，将她余下的不死生命奉献给了危险的炼金术。虽然许多被遗忘者研究员都在皇家药剂师学会的严苛指令下工作，但卡罗莱却在定居点内研究她自己那些奇怪的药水。她那不可预测的实验和冒烟的蒸馏器已经声名狼藉，以至于负责守卫布瑞尔的死亡卫兵们公开抱怨说，她似乎铁了心要炸掉自己的房子。"}},faq={{q="卡罗莱·安尼斯是谁？",a="卡罗莱·安尼斯是一位亡灵炼金术训练师，居住在提瑞斯法林地的布瑞尔定居点。她教授那些有抱负的被遗忘者如何酿制药水、药剂和油膏。",al={"卡罗莱·安尼斯","布瑞尔炼金术士","卡罗莱是谁"}},{q="我在哪里能找到她？",a="她就在提瑞斯法林地中部主要的被遗忘者城镇布瑞尔，在镇上的一栋建筑内处理她的炼金用品。",al={"卡罗莱·安尼斯在哪里","卡罗莱·安尼斯位置","布瑞尔炼金训练师在哪里"}},{q="为什么死亡卫兵会抱怨她？",a="当地的死亡卫兵警告说，卡罗莱那不稳定的炼金实验随时可能引发事故，他们常开玩笑说或担忧地表示，她最终会把整栋房子炸飞。",al={"死亡卫兵对卡罗莱的评价","炸掉房子","卡罗莱·安尼斯的危险性"}}},fp="13,85,16.382.0,21.138.0,21.121.0,42.153.0"}
P.entries["npc:cazul"] = {n="卡祖尔",s="卡祖尔是一位古老的盲眼兽人术士，居住在奥格瑞玛下方阴影裂口幽暗的洞穴中。尽管失去了肉眼的视觉，但他拥有深刻的神秘洞察力，并指引那些寻求增强恶魔统御能力的暗影技艺初学者。",h="卡祖尔是一位古老的盲眼兽人术士，居住在奥格瑞玛下方阴影裂口幽暗的洞穴中。尽管失去了肉眼的视觉，但他拥有深刻的神秘洞察力，并指引那些寻求增强恶魔统御能力的暗影技艺初学者。",kw={"盲眼卡祖尔","卡祖尔","cleft of shadow","恶魔学","奥格瑞玛","虚空行者","术士"},ang={["class:Warlock"]="部落的术士在寻求如何从虚空中束缚更强大的力量时，会被指引前往阴影裂口寻找卡祖尔。",["race:Orc"]="卡祖尔代表了暗影魔法在兽人中经久不衰的存在，他在远离萨尔荣誉卫队监视目光的地方研习着他的技艺。"},sec={{t="黑暗之眼",b="卡祖尔隐居在阴影裂口幽深的洞穴中，是古老术士传统的遗存。虽然他双目失明，但他的感官却与扭曲虚空的涌动电流以及恶魔实体的低语产生了共鸣。当术士们试图增强自己的造诣并束缚更危险的仆从时，通常会被指引来寻找他。他敏锐的感知和深奥的智慧证明，失去双眼并未让他失去任何奥术力量。"}},faq={{q="卡祖尔是谁？",a="卡祖尔是一位年迈的盲眼兽人术士，居住在奥格瑞玛下方的阴影裂口中。他以精通暗影法术和恶魔学而闻名，担任着有抱负的术士们的导师。",al={"卡祖尔是谁","卡祖尔背景故事","盲眼npc卡祖尔"}},{q="为什么卡祖尔是盲的？",a="关于卡祖尔失明的确切原因并无记载。",al={"卡祖尔为什么失明","卡祖尔如何失去视力"}},{q="卡祖尔对术士扮演什么角色？",a="卡祖尔在指导术士提升技艺方面发挥着至关重要的作用，特别是那些正在学习召唤和束缚魅魔的术士。",al={"卡祖尔任务","卡祖尔传授什么","术士任务卡祖尔"}}},fp="5,155,16.336.0,13.151.0,19.35.0,39.110.0"}
P.entries["npc:cerellean-whiteclaw"] = {n="塞瑞利恩·白爪",s="塞瑞利恩·白爪是一位在黑海岸奥伯丁的码头和旅店附近休憩的暗夜精灵。他被远古大分裂时期失去挚爱的记忆所困扰，正挣扎着试图让那不安的灵魂得到安息。",h="塞瑞利恩·白爪是一位在黑海岸奥伯丁的码头和旅店附近休憩的暗夜精灵。他被远古大分裂时期失去挚爱的记忆所困扰，正挣扎着试图让那不安的灵魂得到安息。",kw={"亚米萨兰","阿纳亚·晨行者","奥伯丁","塞瑞利恩·白爪","黑海岸","永恒之爱","鬼魂","大分裂"},ang={["class:Druid"]="像许多德鲁伊一样，塞瑞利恩曾与玛法里奥·怒风一同进入漫长的沉睡，尽管翡翠梦境无法洗去他尘世间破碎的心。",["race:NightElf"]="塞瑞利恩的悲剧故事反映了上古之战和大分裂给卡多雷留下的深重而持久的伤痕。"},sec={{t="破碎的爱",b="一万年前，在上古之战前夕，塞瑞利恩·白爪与阿纳亚·晨行者生活在一起。当恶魔入侵撕裂了古老的卡利姆多时，阿纳亚在亚米萨兰城的毁灭中丧生。悲痛欲绝的塞瑞利恩跟随玛法里奥·怒风进入了漫长的德鲁伊沉睡，然而翡翠梦境却无法让他摆脱对她的记忆。千年之后苏醒时，他在悲痛的迷雾中徘徊于黑海岸，却发现阿纳亚的鬼魂依然被束缚在她倒下的地方。"},{t="解脱的恳求",b="尽管他渴望让阿纳亚获得安宁，但塞瑞利恩无法忍受亲手击碎她那备受折磨的阴影所带来的悲痛。他恳求过往的旅行者冒险前往南方的亚米萨兰废墟，让她的灵魂安息，并找回她的坠饰。在获得解脱后，阿纳亚的阴影会短暂地出现在奥伯丁的码头上，安慰塞瑞利恩并让他确信她那永恒的爱，同时承诺他们终有一天会在来世团聚。"}},faq={{q="塞瑞利恩·白爪是谁？",a="塞瑞利恩·白爪是一位居住在黑海岸奥伯丁码头附近的古代暗夜精灵。他哀悼着在一万年前的上古之战中丧生的挚爱阿纳亚·晨行者。",al={"塞瑞利恩是谁","塞瑞利恩·白爪","奥伯丁码头的精灵"}},{q="阿纳亚·晨行者是谁？",a="阿纳亚·晨行者是塞瑞利恩的爱人，她曾生活在古老的亚米萨兰城。她在上古之战城市沦陷时被杀，其受尽折磨的灵魂在废墟中徘徊了数千年。",al={"阿纳亚·晨行者","塞瑞利恩的爱人","塞瑞利恩的恋人"}},{q="为什么塞瑞利恩不亲自让阿纳亚的灵魂安息？",a="塞瑞利恩对此深感不舍且心碎不已，他没有情感力量去面对并亲手摧毁她的鬼魂形态。他只能依赖富有同情心的旅行者来给予她最后的解脱。",al={"为什么塞瑞利恩不与阿纳亚战斗","为什么需要冒险者"}},{q="亚米萨兰的废墟在哪里？",a="亚米萨兰的废墟位于黑海岸南部，大路以东。该地区充斥着在大分裂期间丧生的古代卡多雷的鬼魂。",al={"亚米萨兰在哪里","阿纳亚的位置","阿纳亚在哪里"}}},fp="19,191,19.500.0,18.388.1,27.187.0,25.235.0,57.143.0,34.152.0"}
P.entries["npc:charlga-razorflank"] = {n="卡尔加·刺肋",s="卡尔加·刺肋（Charlga Razorflank），通常被称为“沼泽老妪”，是统治剃刀沼泽的凶猛且狡诈的土灵法师酋长。在她的领导下，剃刀沼泽的野猪人通过无情的扩张，将牛头人赶出了南贫瘠之地，并声称是在以他们倒下的半神阿迦玛甘（Agamaggan）的名义进行战斗。",h="卡尔加·刺肋（Charlga...",kw={"阿迦玛甘","贫瘠之地","卡尔加","老妪","土灵法师","剃刀沼泽","野猪人","刺肋"},ang={["class:Shaman"]="虽然卡尔加掌握着强大的土灵法术，但她对元素的扭曲代表了对神圣原始传统的黑暗腐化。",["faction:Horde"]="除掉卡尔加对于保护南贫瘠之地的商队路线和营地免受野猪人武装部队的无情袭击至关重要。",["race:Tauren"]="卡尔加的侵略性扩张将你们的人民驱逐出了他们在南贫瘠之地的祖居地，因此击败她关乎部落的生存与收复失地。"},sec={{t="沼泽老妪",b="在剃刀沼泽错综复杂、巨大的荆棘丛中，统治者便是卡尔加·刺肋。她被族人奉为大师级土灵法师，其试验性的魔法在野猪人中无人能及，卡尔加将她那分裂的族人组织成了一个统一且致命的威胁。她驾驭着原始大地和从半神阿迦玛甘遗骸中萌发出的巨型荆棘，将迷宫般的剃刀沼泽改造成了一座坚不可摧的堡垒。"},{t="扩张与背叛",b="卡尔加指挥着野猪人不断对南贫瘠之地的敌对部落和部落营地进行暴力入侵，最终将牛头人驱逐出了他们传统的家园。但她真正的野心更为深远：卡尔加秘密与亡灵天灾的使者进行了谈判，以她族人对亡灵的盲目崇拜为筹码，换取了非自然的力量和阴险的联盟。"}},faq={{q="卡尔加·刺肋是谁？",a="卡尔加·刺肋是剃刀沼泽野猪人部落的酋长兼最高土灵法师，她在南贫瘠之地的剃刀沼泽深处建立了巢穴。",al={"卡尔加背景故事","谁是沼泽老妪","剃刀沼泽首领"}},{q="卡尔加使用什么魔法？",a="她是一位天赋异禀的土灵法师，能够操纵元素土系力量以及从半神阿迦玛甘身上诞生的巨大血棘。",al={"卡尔加技能","土灵法师能力"}},{q="为什么野猪人在贫瘠之地攻击牛头人？",a="在卡尔加的领导下，剃刀沼泽的野猪人攻击了敌对部落和部落村庄，并将牛头人赶出了南贫瘠之地。",al={"为什么野猪人仇恨牛头人","贫瘠之地野猪人战争"}},{q="卡尔加与剃刀高地有什么联系？",a="剃刀高地与她的剃刀沼泽生长于同一片强大的藤蔓之上，是野猪人的传统都城，也是死亡之头部落及其大祭司的所在地。卡尔加统治的是剃刀沼泽，而非剃刀高地。",al={"卡尔加与剃刀高地","卡尔加剃刀高地"}},{q="为什么部落想要除掉她？",a="牛头人和他们的部落盟友视她为直接的生存威胁，因为她发动了无休止的突袭，窃取了他们的土地，并与黑暗势力进行了危险的交易。",al={"沼泽老妪任务","为什么要杀卡尔加"}}},fx={["29fd1a6b"]={q="卡尔加·刺肋效忠于哪一方？",a="卡尔加领导着剃刀沼泽的野猪人，但她与天灾军团交易，出卖了自己的族人。她声称要拥护野猪人，并让他们的野猪之神阿迦玛甘复生，却暗中与寒冰使者阿门纳尔派来的亡灵使节结盟，为其追随者所不知的险恶势力效力。",al={"卡尔加·刺肋的阵营","卡尔加效忠于谁","卡尔加·刺肋的立场"}},["98b63c0f"]={q="卡尔加·刺肋想要什么？",a="卡尔加企图绝对统治南贫瘠之地，并为自己的部族夺取至高权力。她驱使族人血洗敌对部族、部落村庄和牛头人；她还一直暗中与天灾军团的代理人谈判，在族人毫不知情的情况下让他们与亡灵结盟，意图不明。",al={"卡尔加的目标","卡尔加想要什么","卡尔加·刺肋的动机"}},["581cf8d6"]={q="卡尔加·刺肋为何在此？",a="剃刀沼泽是剃刀野猪人的祖地核心，那里由远古之战中阿迦玛甘陨落之处生长出的巨大荆棘构成。身为部族中至高无上的老巫婆和酋长，卡尔加在沼泽最深处筑巢，在那里调度她的战队并研究地脉水晶。",al={"卡尔加为何在剃刀沼泽","卡尔加·刺肋所在此处的原因","卡尔加在哪里"}},["98250d5e"]={q="卡尔加·刺肋与谁有关联？",a="卡尔加与盘踞在剃刀高地的天灾军团势力直接勾结。她与寒冰使者阿门纳尔的使者谈判；这位巫妖暗中控制着亡首野猪人。卡尔加让自己的部族在不知情的情况下加入了亡灵的阵营。",al={"卡尔加的盟友","卡尔加的关系","卡尔加与谁共事"}},f526ba0c={q="卡尔加·刺肋为何声名狼藉或令人畏惧？",a="卡尔加被称为沼泽老巫婆，拥有同族无人能及的地脉秘术，令人闻风丧胆。在她铁腕领导下，剃刀野猪人发动了残酷的征战，将游牧的牛头人彻底赶出了南贫瘠之地，使她在整个卡利姆多凶名远扬。",al={"卡尔加为何令人畏惧","卡尔加有多强","卡尔加·刺肋的力量"}}},fp="18,177,22.366.0,22.325.1,26.122.0,28.131.0,54.131.0,47.209.0,33.174.0"}
P.entries["npc:chef-breanna"] = {n="厨师布雷纳",s="厨师布雷纳是赤脊山湖畔镇当地餐馆的主厨。她肩负着为驻扎在这个饱受战火蹂躏的湖畔小镇、保护这里的暴风城士兵提供食物的重任，她依赖丰盛的当地食材让守军们保持战斗力。",h="厨师布雷纳是赤脊山湖畔镇当地餐馆的主厨。她肩负着为驻扎在这个饱受战火蹂躏的湖畔小镇、保护这里的暴风城士兵提供食物的重任，她依赖丰盛的当地食材让守军们保持战斗力。",kw={"布雷纳","厨师布雷纳","厨师","驻军","炖肉","湖畔镇","赤脊山炖肉"},ang={["faction:Alliance"]="如果没有厨师布雷纳为坚守桥梁和城镇外围的士兵提供补给，湖畔镇紧张的驻军很快就会在无休止的兽人和豺狼人入侵中精疲力竭。",["profession:Cooking"]="布雷纳为赤脊山炖肉所准备的足智多谋的食谱展示了一位边境厨师如何将危险的当地掠食者——蜘蛛、秃鹫和野猪——变成维持军事前哨的丰盛餐点。"},sec={{t="喂饱湖畔镇的守军",b="厨师布雷纳在湖畔镇西北部的一间餐馆工作，与她的助手克里斯塔尔·鲍曼（Crystal Boughman）和格雷琴·沃格尔（Gretchen Vogel）一起，承担着为整个当地营提供补给的重任。由于湖畔镇正受到黑石兽人、豺狼人和鱼人的围困，维持暴风城人手不足的驻军的体力和士气至关重要。她的招牌菜“赤脊山炖肉”以徘徊在周边山脊的野生猎物和野兽为原料，将危险的荒野掠食者变成了镇上疲惫守卫的补给。"}},faq={{q="厨师布雷纳是谁？",a="厨师布雷纳是湖畔镇的厨师，在定居点西北角经营着当地的厨房。她的任务是喂饱保卫赤脊山的暴风城士兵。",al={"厨师布雷纳","布雷纳 湖畔镇","布雷纳是谁"}},{q="厨师布雷纳需要什么帮助？",a="她需要当地的野味来为驻军烹制赤脊山炖肉。冒险者通过从湖畔镇周边的荒野中收集硬秃鹫肉、野猪獠牙和香脆蜘蛛肉来帮助她。",al={"布雷纳任务","赤脊山炖肉配料","她想要什么"}},{q="谁与厨师布雷纳一起工作？",a="她繁忙的餐馆雇用了克里斯塔尔·鲍曼和格雷琴·沃格尔，她们协助她管理餐馆并招待饥肠辘辘的镇民和士兵。",al={"布雷纳的帮手","克里斯塔尔·鲍曼","格雷琴·沃格尔"}}},fx={["33f751f4"]={q="厨师布雷纳效忠于哪一方？",a="厨师布雷纳效忠于联盟和暴风城王国。她在湖畔镇经营厨房，负责为驻扎在当地、守卫城镇及周边边境的暴风城军团提供补给。",al={"厨师布雷纳的阵营","布雷纳效忠于谁","厨师布雷纳属于联盟吗"}},f2dfd1fc={q="厨师布雷纳为什么在湖畔镇？",a="布雷纳在湖畔镇西北部经营镇上的餐馆。她的主要职责是在威胁不断逼近赤脊山之际，为当地的暴风城士兵提供食物，确保他们随时能够投入战斗；她依靠新鲜的本地食材，为驻军补充给养。",al={"布雷纳为什么在赤脊山","厨师布雷纳为什么在湖畔镇","布雷纳在湖畔镇的职责"}}},fp="12,188,29.406.0,20.143.0,38.186.0,28.161.0"}
P.entries["npc:chef-grual"] = {n="厨师格鲁奥",s="厨师格鲁奥是夜色镇Scarlet Raven Tavern的常驻厨师。在这个被迷雾和怪物笼罩的偏僻小镇里，格鲁奥尽他所能为守夜人和疲惫的旅人提供食物，尽管他选择的食材总是令人侧目。",h="厨师格鲁奥是夜色镇Scarlet Raven Tavern的常驻厨师。在这个被迷雾和怪物笼罩的偏僻小镇里，格鲁奥尽他所能为守夜人和疲惫的旅人提供食物，尽管他选择的食材总是令人侧目。",kw={"厨师格鲁奥","蟹肉蛋糕","夜色镇","暮色森林","格鲁奥","基特斯","scarlet raven tavern","狼肉烤串"},ang={["faction:Alliance"]="格鲁奥驻扎在夜色镇的Scarlet Raven Tavern，尽管缺乏来自暴风城的定期补给车队，但他依然让联盟疲惫的守卫们吃饱穿暖。",["profession:Cooking"]="格鲁奥是一个关于烹饪即兴发挥的残酷教训，证明了在偏远地区，厨师只能使用任何在树林间行走或爬行的当地野生动物作为食材。",["race:Human"]="就像夜色镇许多留守的居民一样，格鲁奥展现出了一种严酷而顽强的韧性，用他自己务实的方式适应着这片阴影森林的恐怖。"},sec={{t="围城之下的烹饪",b="在夜色镇经营一家餐馆是一项艰巨的任务。由于来自西部荒野和暴风城的补给线不断受到强盗、狼群和亡灵的骚扰，新鲜物资几乎不存在。格鲁奥只能凑合着用荒野里能找到的任何东西。从狼肉到当地冒险者带进门来的任何拾荒肉类，格鲁奥的烹饪充满了因必要而生的实用主义。"},{t="秘密食材",b="格鲁奥以其特色菜肴而闻名，其中最著名的就是他的“黑蟹蛋糕”和调味狼肉烤串。考虑到暮色森林阴暗的内陆树林附近根本没有海岸螃蟹，他的黑蟹蛋糕依赖于一种相当令人作呕的替代品：当地Venom Web Spiders黏糊糊的腿。无论客人们是意识到自己在吃蜘蛛肉，还是仅仅选择不去过问，格鲁奥都毫无歉意地维持着厨房的运转。"}},faq={{q="厨师格鲁奥是谁？",a="厨师格鲁奥是驻扎在夜色镇Scarlet Raven Tavern的人类厨师。他为小镇的守卫、旅人以及躲避暮色森林危险的难民准备餐食。",al={"厨师格鲁奥","格鲁奥 夜色镇","夜色镇厨师"}},{q="我可以在哪里找到厨师格鲁奥？",a="他站在夜色镇中心Scarlet Raven Tavern的后室和厨房区域，位于主干道的南侧。",al={"格鲁奥位置","厨师格鲁奥在哪里","寻找厨师格鲁奥"}},{q="黑蟹蛋糕实际上是用什么做的？",a="尽管名字叫黑蟹蛋糕，但暮色森林里并没有螃蟹。厨师格鲁奥用从周围森林中泛滥的巨型蜘蛛身上采集到的黏糊糊的腿来代替，将它们绞碎成模仿海鲜口感的肉饼。",al={"蟹肉蛋糕食材","蜘蛛蟹肉蛋糕","黑蟹蛋糕里有什么"}},{q="厨师格鲁奥提供什么任务？",a="格鲁奥会委托旅人从野外收集新鲜食材，包括用来制作调味狼肉烤串的狼肋排，以及用来制作黑蟹蛋糕的蜘蛛腿。他还为躲在暮色森林里的饥饿难民基特斯烹制黑蟹蛋糕。",al={"格鲁奥任务","厨师格鲁奥食谱"}},{q="他为什么要喂基特斯？",a="基特斯已经在暮色森林的一个鬼镇里躲了好几个星期，只靠吃幼虫和杂草度日。因为极度渴望正常的食物，他会派旅人去找格鲁奥，带回一些黑蟹蛋糕。",al={"基特斯的食物","基特斯 饥肠辘辘 格鲁奥"}},{q="格鲁奥隶属于守夜人吗？",a="格鲁奥是一位平民厨师，而非武装警卫，但他的厨房直接支持着守夜人和当地民兵，让夜色镇在持续的围困中保持温饱。",al={"格鲁奥 守夜人","格鲁奥会战斗吗"}}},fx={ccc14f35={q="厨师格鲁奥属于哪一方？",a="厨师格鲁奥坚定地站在夜色镇居民和联盟一边。尽管小镇依然与外界隔绝，饱受阴影侵袭，格鲁奥仍在 Scarlet Raven Tavern 守着炉火，为当地居民、疲惫的旅人和小镇守卫准备饭菜。",al={"厨师格鲁奥的阵营","厨师格鲁奥为谁效力","厨师格鲁奥属于联盟吗"}},["3ac222da"]={q="厨师格鲁奥想要什么？",a="格鲁奥想在暮色森林危机四伏的局势下，确保 Scarlet Raven Tavern 的物资充足。贸易路线已被切断，新鲜牲畜也十分稀缺，他只能依靠勇于冒险的旅人收集不寻常的本地食材——比如狼肉和黏糊糊的蜘蛛腿——来供给饥肠辘辘的顾客。",al={"厨师格鲁奥需要什么","厨师格鲁奥的食材","厨师格鲁奥的目标"}},["91c4d31a"]={q="厨师格鲁奥为什么在这里？",a="格鲁奥是夜色镇的常驻厨师，在 Scarlet Raven Tavern 工作。暮色森林中许多人都已逃离逐渐逼近的黑暗，格鲁奥却留下来经营厨房，尽自己的一份力，帮助这座与世隔绝的聚居地生存下去。",al={"厨师格鲁奥为什么在暮色森林","格鲁奥为什么留在夜色镇","厨师格鲁奥的职责"}}},fp="10,160,19.305.0,18.284.1,18.158.0,28.137.0,43.148.1,34.197.1,25.157.0,41.128.0"}
P.entries["npc:chef-jessen"] = {n="厨师杰森",s="厨师杰森是南海镇的驻地肉类商人和烹饪师，在持续不断的边界紧张局势中，他致力于为这座沿海城镇提供补给。他最令人难忘的是他那著名的海龟浓汤。",h="厨师杰森是南海镇的驻地肉类商人和烹饪师，在持续不断的边界紧张局势中，他致力于为这座沿海城镇提供补给。他最令人难忘的是他那著名的海龟浓汤。",kw={"厨师杰森","烹饪","希尔斯布莱德丘陵","杰森","洛丹米尔湖","鳄鱼龟","南海镇","海龟浓汤"},ang={["faction:Alliance"]="杰森在南海镇工作，帮助维持着联盟士兵和冒险者们防线的补给，抵御北方的威胁。",["profession:Cooking"]="对于路过希尔斯布莱德的厨师来说，杰森是一个很有价值的联络人，因为他的海龟浓汤食谱能为坚韧的旅行者提供一顿丰盛的大餐。"},sec={{t="南海镇的厨师",b="厨师杰森在希尔斯布莱德丘陵南部的南海镇开展业务，为当地居民和来访的联盟士兵提供肉类和补给。他拥有卓越的烹饪专长。多年前，在瘟疫和战争破坏洛丹伦北部之前，他经常向北越过达拉然，前往洛丹米尔湖岸边。在那里，他会采集当地鳄鱼龟的肉来调制他珍贵的舒心海龟浓汤，这是一种丰盛的食谱，他愿意与那些协助他收集食材的怀揣抱负的旅行者分享。"}},faq={{q="厨师杰森是谁？",a="厨师杰森是一位位于希尔斯布莱德丘陵南海镇的人类屠夫和厨师。他向支持联盟的旅行者出售肉类并分享当地的烹饪食谱。",al={"杰森","南海镇厨师杰森","杰森是谁"}},{q="厨师杰森的拿手菜是什么？",a="他的招牌食谱是舒心海龟浓汤。过去，他会从达拉然以北洛丹米尔湖周围栖息的鳄鱼龟身上采集新鲜龟肉，来制作这种丰盛的汤品。",al={"海龟浓汤食谱","杰森的特长","舒心海龟浓汤"}},{q="为什么厨师杰森会请求旅行者帮助？",a="由于地区动荡和附近被遗忘者的存在，在洛丹米尔湖周围采集鳄鱼龟肉变得越来越危险。杰森依靠有能力的冒险者来收集龟肉，以便他能够准备浓汤。",al={"杰森的任务","龟肉任务"}},{q="厨师杰森是否出售任何不同寻常的东西？",a="除了卖给南海镇居民的肉类之外，杰森的真正特长是他的舒心海龟浓汤，他会将这个食谱传授给那些帮助他收集鳄鱼龟肉的厨师。",al={"杰森的特产","杰森食品商"}}},fx={["4b3f98b6"]={q="厨师杰森属于哪一方？",a="厨师杰森效忠于联盟。他在南海镇生活和工作。南海镇是希尔斯布莱德丘陵南岸主要的人类避难所和联盟据点，为当地居民以及奋力守住洛丹伦防线的旅人提供膳食。",al={"厨师杰森属于联盟还是部落","厨师杰森属于联盟吗","厨师杰森的阵营"}},["73d1d0ab"]={q="厨师杰森为什么在南海镇？",a="厨师杰森在南海镇经营肉类摊位，也担任厨师。他以前会一路北上，经过达拉然前往洛丹米尔湖，亲自猎捕钳嘴龟；如今他待在镇上，依靠路过的冒险者带来新鲜食材。",al={"厨师杰森为什么在南海镇","厨师杰森为什么在这里","是什么让厨师杰森来到希尔斯布莱德"}}},fp="11,127,20.458.0,19.162.0,34.182.0,44.213.0,39.148.0"}
P.entries["npc:chief-archaeologist-greywhisker"] = {n="首席考古学家杜瑟·灰须",s="首席考古学家杜瑟·灰须是铁炉堡探险者协会派驻在达纳苏斯Temple of the Moon外的使者。他从铁炉堡远渡重洋来到北卡利姆多，旨在发掘古代历史，并统筹该地区矮人的实地考察工作。目前，他正忙于收集实地报告，并追踪在黑海岸活动的失踪同事。",h="首席考古学家杜瑟·灰须是铁炉堡探险者协会派驻在达纳苏斯Temple of the...",kw={"阿迦玛甘","首席考古学家","黑海岸","达纳苏斯","探险者协会","灰须","铁炉堡","塔瑞尔维尔","temple of the moon"},ang={["faction:Alliance"]="他是连接铁炉堡探险者协会与驻扎在北卡利姆多各地的考察队之间至关重要的学术和后勤桥梁。",["race:Dwarf"]="在Temple of the Moon外发现铁炉堡的一位顶尖学者，这是一种令人欣慰的提醒，表明你们的人民对揭开古代历史有着无限的渴望，即使是在卡利姆多的遥远角落。",["race:NightElf"]="灰须代表了你们的人民与东部王国之间新建立的联盟，他在艾露恩神殿外恭敬地与学者们讨论这片大陆的过去。"},sec={{t="一位在达纳苏斯的矮人学者",b="虽然在泰达希尔的高枝上看到一位铁炉堡的矮人很不寻常，但首席考古学家杜瑟·灰须代表了探险者协会那远大的志向。他放弃了铁炉堡的演讲厅和博物馆库房，转而投身于卡利姆多的实地考察，现在你可以在达纳苏斯的Temple of the Moon外找到他，他正在与当地的暗夜精灵学者（例如塔瑞尔维尔）进行交流。灰须在东部王国时的学术讲座曾以探讨古代传说和诸如荒野之神阿迦玛甘这样的原始实体而闻名，他非常渴望看看暗夜精灵的祖居之地隐藏着什么样的古老秘密。"},{t="关注黑海岸",b="灰须在卡利姆多的主要职责是监督矮人的挖掘工作，并留意沿海地区搜索古老遗迹的考察队。然而对这位首席考古学家来说，在未开发的土地上进行实地考察伴随着独特的危险。他依赖过往的旅行者来与远在黑海岸的勘探者建立联系，焦急地等待着来自挖掘现场的消息，并希望他的同事们没有屈服于潜伏在古老遗迹中的危险。"}},faq={{q="谁是首席考古学家杜瑟·灰须？",a="他是一位来自铁炉堡的著名矮人学者，也是探险者协会的代表。他驻扎在达纳苏斯的Temple of the Moon外，统筹协会在北卡利姆多的研究工作，并与暗夜精灵学者保持联络。",al={"谁是灰须","灰须背景故事","首席考古学家"}},{q="一个铁炉堡的矮人在达纳苏斯做什么？",a="探险者协会已经在艾泽拉斯各地派遣了研究人员，以发掘被遗忘的历史和古代文物。灰须被派往海外，旨在暗夜精灵的首都会建立学术联系，并监督探索卡利姆多古老海岸线的矮人考察队。",al={"为什么会有矮人在达纳苏斯","矮人 temple of the moon"}},{q="他与阿迦玛甘有什么联系？",a="在铁炉堡时，灰须以其关于古代历史的学术讲座而闻名。他讨论的主题包括巨型野猪荒野之神阿迦玛甘，其传说激励了像朗布罗这样年轻的矮人勘探者去研究古老的野兽传说。",al={"灰须 阿迦玛甘","阿迦玛甘讲座"}},{q="灰须在神殿外和谁交谈？",a="灰须站在达纳苏斯，正与Temple of the Moon外的暗夜精灵学者塔瑞尔维尔交谈，交流思想并协调双方人民之间的历史研究。",al={"灰须 塔瑞尔维尔","谁和灰须在一起"}},{q="他在黑海岸遇到了什么麻烦？",a="灰须已经派遣了矮人实地研究员前往黑海岸挖掘古老遗迹，但与孤立的考察队保持联系已被证明十分困难。他经常寻找信使去查看那些心不在焉的勘探者，并找回他们的研究日志。",al={"灰须 黑海岸","黑海岸勘探者"}},{q="灰须属于哪个阵营？",a="灰须隶属于探险者协会，这是一个致力于发掘矮人起源和古代历史的铁炉堡考古组织，完全效忠于联盟。",al={"灰须所属阵营","探险者协会 达纳苏斯"}}},fp="31,225,30.479.0,17.347.0,39.253.0,46.224.0,36.195.0,49.177.0,45.220.0,41.187.0"}
P.entries["npc:chief-engineer-hinderweir-vii"] = {n="主工程师辛德维尔七世",s="主工程师辛德维尔七世是一位驻守在洛克莫丹巨石水坝上的资深矮人工程师。他负责维护和防御这项伟大的工程杰作，在监管其精密机械装置的同时，时刻警惕着任何破坏活动。与之交谈的人很快就会发现，巨大的危险正威胁着这座宏伟水坝的安全。",h="主工程师辛德维尔七世是一位驻守在洛克莫丹巨石水坝上的资深矮人工程师。他负责维护和防御这项伟大的工程杰作，在监管其精密机械装置的同时，时刻警惕着任何破坏活动。与之交谈的人很快就会发现，巨大的危险正威胁着这座宏伟水坝的安全。",kw={"黑暗的威胁","矮人","工程师","辛德维尔","洛克莫丹","破坏","巨石水坝"},ang={["faction:Alliance"]="联盟无法承受水坝失守的后果；灾难性的溃坝将中断补给线，并摧毁洛克莫丹北部的盟军领地。",["profession:Engineering"]="工程师们一定能体会到辛德维尔所负责工程的庞大机械规模，因为巨石水坝代表了土木建筑与机械控制的无与伦比的结合。",["race:Dwarf"]="对矮人来说，辛德维尔代表着保护卡兹莫丹最伟大的石匠成就免受外敌恶意破坏的神圣职责。"},sec={{t="水坝掌控者",b="巨石水坝是矮人石匠工艺和工程学的巅峰成就之一，它阻挡着洛克湖浩瀚的湖水。主工程师辛德维尔七世承担着维护其结构和运行机械的重任。他伫立在坝顶，监测着水道、水闸和结构应力点，以应对自然环境和当地威胁。"},{t="破坏与颠覆",b="管理水坝不仅仅是日常维护；黑暗势力一直在不断试探它的防御。辛德维尔发现了该地区敌对势力精心策划的破坏活动的迹象。这位主工程师意识到，灾难性的决堤将淹没低地，摧毁卡兹莫丹脆弱的基础设施，因此他招募可靠的联盟冒险者来追查阴谋，拆除隐藏的炸药，并在堤坝崩塌前化解威胁。"}},faq={{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世是负责维护和防御洛克莫丹北部巨石水坝的矮人主管。",al={"辛德维尔","主工程师","水坝工程师"}},{q="在哪里可以找到主工程师辛德维尔七世？",a="他就站在巨石水坝的顶部通道上，这座水坝横跨洛克莫丹的北缘，靠近湿地边境。",al={"辛德维尔的位置","辛德维尔在哪里","寻找辛德维尔"}},{q="什么是巨石水坝？",a="巨石水坝是一项巨大的矮人建筑奇迹，它阻挡着洛克湖的水流，防止湖水猛烈地倾泻到北部的低洼湿地中。",al={"什么是水坝","巨石水坝的用途","为什么水坝很重要"}},{q="辛德维尔担心哪些威胁？",a="辛德维尔正在调查针对水坝的蓄意破坏行为，并发现了企图炸毁水坝地基的黑暗阴谋和爆炸装置的证据。",al={"水坝威胁","黑暗的威胁","谁想摧毁水坝"}},{q="为什么他的名字里有“七世”？",a="“七世”是罗马数字七。辛德维尔的名字中为何包含此后缀目前并无记录。",al={"辛德维尔的名字","为什么是七世","辛德维尔七世的含义"}},{q="主工程师辛德维尔提供什么任务？",a="他提供任务线“黑暗的威胁”，引导冒险者去调查篡改行为并保护巨石水坝免遭破坏。",al={"辛德维尔的任务","水坝处的任务","黑暗的威胁任务"}}},fp="29,194,17.267.0,23.292.1,37.92.0,47.150.0,29.162.0,41.152.0,32.91.0,49.173.0"}
P.entries["npc:chief-hawkwind"] = {n="鹰风酋长",s="鹰风酋长是纳拉其营地的部落首领，这座试炼场坐落在莫高雷的红云台地。他负责引导舒哈鲁的年轻一代，为踏上传统成人礼的冒险者们提供指引。在他的注视下，年轻的勇士们学会了谦逊、对土地的尊重，以及保护族人所需的力量。",h="鹰风酋长是纳拉其营地的部落首领，这座试炼场坐落在莫高雷的红云台地。他负责引导舒哈鲁的年轻一代，为踏上传统成人礼的冒险者们提供指引。在他的注视下，年轻的勇士们学会了谦逊、对土地的尊重，以及保护族人所需的力量。",kw={"卑微的任务","刺背","纳拉其营地","鹰风酋长","莫高雷","红云台地","力量仪式","大地之母的仪式","牛头人酋长"},ang={["faction:Horde"]="鹰风的教导确保了新晋的牛头人勇士不仅能成为出色的战士和施法者，还能成为年轻部落坚定且光荣的盟友。",["race:Tauren"]="作为引导你踏上旅程的第一位酋长，鹰风酋长为你灌输了舒哈鲁的基本价值观：对大地之母的敬畏、对部落的忠诚，以及在力量面前保持谦逊。"},sec={{t="台地酋长",b="鹰风酋长驻守在纳拉其营地的核心地带，肩负着将下一代牛头人引向更广阔世界的重任。红云台地作为一处避风港，让年轻的猎人、萨满、德鲁伊和战士们在此完成古老的大地之母的仪式。鹰风监督着这些习俗，确保每位年轻人在踏出台地的安全范围之前，都能领悟到责任与坚韧。"},{t="仪式指引",b="鹰风的教导始于谦逊，而非武力上的荣耀。他会派遣初学者去完成琐碎的杂务，比如取回洁净的泉水，以培养他们对自然界和长者的敬畏之心。只有在展现出谦卑的心态后，勇士们才会被引导去接受武技考验，最终面对那些侵犯祖地平原、充满敌意的刺背野猪人。"},{t="保卫纳拉其营地",b="作为导师，鹰风酋长还必须应对营地门口日益严重的威胁。刺背部落变得越来越猖狂，不断向红云台地的边缘施压。鹰风负责协调营地的防御，指派那些刚刚证明了自己的勇士去挫败野猪人的袭击，以确保这片神圣的训练场安然无恙。"}},faq={{q="鹰风酋长是谁？",a="鹰风酋长是红云台地纳拉其营地的酋长。他监管着该地区的部落事务，并指导年轻的牛头人准备踏出前往莫高雷和卡利姆多更广阔世界的第一步。",al={"鹰风","鹰风酋长背景故事","纳拉其营地的酋长是谁"}},{q="什么是大地之母的仪式？",a="大地之母的仪式是年轻牛头人在成年时必须完成的一系列传统神圣试炼。在像鹰风酋长这样的长者引导下，这些仪式考验着勇士们的谦逊、力量、勇气，以及与土地和祖先之间的精神纽带。",al={"牛头人仪式","大地之母的仪式","什么是仪式"}},{q="为什么鹰风酋长让你先去取水？",a="鹰风分配“卑微的任务”是为了提醒年轻的勇士，服务和尊重群体与武力同样重要。在开始战斗之前，为部落长者收集淡水可以教会他们耐心与谦逊。",al={"卑微的任务","为什么取水","鹰风取水任务"}},{q="纳拉其营地面临什么威胁？",a="纳拉其营地正承受着来自红云台地周边山丘中敌对的刺背野猪人的持续压力。鹰风酋长必须组织台地的防御，并派遣初学者去削减野猪人的兵力。",al={"纳拉其的威胁","谁在攻击纳拉其营地","纳拉其营地的野猪人"}},{q="鹰风酋长接下来会指引冒险者去哪里？",a="当年轻的勇士在台地上完成了初步仪式后，鹰风酋长会指引他们前往莫高雷广阔的谷地，前往血蹄村寻找贝恩·血蹄酋长（凯恩之子），继续完成大地之母的仪式。",al={"完成鹰风的任务后去哪","纳拉其营地之后","离开红云台地"}},{q="鹰风酋长和鹰风酋长的母亲有亲戚关系吗？",a="是的，鹰风酋长的母亲就是他的母亲。鹰风家族在红云台地居住的牛头人中长期扎根，并担任着领导角色。",al={"鹰风酋长的母亲的亲属关系","鹰风家族","谁是鹰风酋长的母亲"}}},fp="14,234,21.301.0,17.362.0,22.300.0,22.170.0,38.228.0,51.239.0,35.181.0,48.237.0,50.150.0"}
P.entries["npc:christoph-jeffcoat"] = {n="克里斯托弗·杰弗寇特",s="克里斯托弗·杰弗寇特是驻扎在希尔斯布莱德丘陵的塔伦米尔定居点的一名被遗忘者商人。他为当地的工匠和旅行者提供必要的贸易商品、烹饪调料和特殊配方。在这个由联盟和辛迪加争夺的活跃战区中，他贩售的平凡商品支撑着部落在北方的战争行动。",h="克里斯托弗·杰弗寇特是驻扎在希尔斯布莱德丘陵的塔伦米尔定居点的一名被遗忘者商人。他为当地的工匠和旅行者提供必要的贸易商品、烹饪调料和特殊配方。在这个由联盟和辛迪加争夺的活跃战区中，他贩售的平凡商品支撑着部落在北方的战争行...",kw={"克里斯托弗·杰弗寇特","被遗忘者商人","希尔斯布莱德","舒缓香料","塔伦米尔","贸易补给品","贸易商人"},ang={["faction:Horde"]="对于在希尔斯布莱德丘陵作战的部落勇士来说，杰弗寇特在塔伦米尔的心脏地带提供了不可或缺的制作材料和常用工具。",["profession:Cooking"]="克里斯托弗·杰弗寇特是希尔斯布莱德有抱负的厨师们的必经之地，因为他出售舒缓香料，并会向带来颚骨龟肉的厨师教授他独门的舒缓龟肉浓汤配方。"},sec={{t="前线商人",b="虽然塔伦米尔是希尔斯布莱德丘陵中被遗忘者的军事堡垒，但驻军不能仅靠怨恨进行战斗。克里斯托弗·杰弗寇特负责处理占领期间那些安静而实际的事务，向士兵和过往的工匠出售试剂、工具、丝线和香料。从当地烹饪食谱（如龟肉浓汤）所需的舒缓香料，到稀有的图纸和炼金药瓶，杰弗寇特确保途径洛丹伦南部的部落部队能够为对抗南海镇和应对地区危险做好充分的补给。"}},faq={{q="我可以在哪里找到克里斯托弗·杰弗寇特？",a="克里斯托弗·杰弗寇特居住在塔伦米尔，这是位于希尔斯布莱德丘陵北部主要的被遗忘者和部落据点。",al={"克里斯托弗·杰弗寇特位置","杰弗寇特在哪里","塔伦米尔贸易商"}},{q="他出售什么样的商品？",a="他是一名贸易补给品商人，库存包括裁缝丝线、锻造锤、助熔剂、炼金药瓶以及舒缓香料和热香料等烹饪调料，此外还有一些精选的特殊配方。",al={"杰弗寇特卖什么","克里斯托弗·杰弗寇特商品","杰弗寇特出售物品"}},{q="为什么他对当地厨师很重要？",a="杰弗寇特出售舒缓香料，这是舒缓龟肉浓汤的一种配料，并且当部落厨师带给他颚骨龟肉时，他会亲自教给他们制作浓汤的方法。",al={"希尔斯布莱德舒缓香料商","舒缓龟肉浓汤配料","杰弗寇特烹饪"}}},fx={["36cd3db3"]={q="克里斯托弗·杰弗寇特是谁？",a="克里斯托弗·杰弗寇特是一名亡灵商人，驻扎在希尔布莱德丘陵的塔伦米尔。他为被遗忘者效力，为旅人、工匠以及坚守部落前线的守卫提供贸易物资、原材料和制造用品。",al={"克里斯托弗·杰弗寇特是谁","克里斯托弗·杰弗寇特的身份","杰弗寇特是谁"}},["1470d19f"]={q="克里斯托弗·杰弗寇特属于哪一方？",a="克里斯托弗·杰弗寇特坚定地效忠于被遗忘者和部落。他驻扎在争夺激烈的前哨塔伦米尔，为部落冒险者和勇士提供服务；他们正与来自南海镇的联盟势力交战。",al={"克里斯托弗·杰弗寇特的阵营","克里斯托弗·杰弗寇特属于部落吗","克里斯托弗·杰弗寇特为谁效力"}},["7ff6f152"]={q="克里斯托弗·杰弗寇特为什么在塔伦米尔？",a="塔伦米尔是部落在希尔斯布莱德丘陵北部行动的支点，工匠和战士经常缺少日常物资。克里斯托弗·杰弗寇特驻扎在此，确保贸易货物、药瓶、线和香料能随时供给守卫据点的人。",al={"克里斯托弗为什么在塔伦米尔","克里斯托弗·杰弗寇特为什么在这里","杰弗寇特为什么在希尔斯布莱德"}}},fp="18,206,29.409.0,36.113.0,33.167.0,36.140.0"}
P.entries["npc:chronormu"] = {n="Chronormu",s="克罗诺姆，也就是以凡人名字“克罗米”行事的青铜龙，伪装成一位活力十足的侏儒女性。她肩负着守护艾泽拉斯时间流动的重任，比起在远方旁观，她更常与凡人直接合作。在西瘟疫之地，她悄然介入了第三次战争后的惨剧，以修正被打乱的时间线。",h="克罗诺姆，也就是以凡人名字“克罗米”行事的青铜龙，伪装成一位活力十足的侏儒女性。她肩负着守护艾泽拉斯时间流动的重任，比起在远方旁观，她更常与凡人直接合作。在西瘟疫之地，她悄然介入了第三次战争后的惨剧，以修正被打乱的时间线...",kw={"andorhal","青铜龙","克罗米","chronormu","诺兹多姆","伪装形态"},ang={["class:Mage"]="研究奥术中时间法术的法师们会发现，克罗诺姆对时间的随意操纵和局部时间空洞的掌控，其规模既令人着迷，又让人感到震撼。",["race:Gnome"]="克罗诺姆以克罗米的身份行走在凡人中间，这是一位开朗的侏儒，她那小巧且不起眼的外表下隐藏着一条青铜龙。"},sec={{t="小巧身姿的巨龙",b="虽然在凡人眼中，她是一位名叫克罗米的古怪而开朗的侏儒，但克罗诺姆实际上是青铜龙军团的一员，效忠于永恒者诺兹多姆。青铜龙被泰坦委以守护历史、修正时间线扰动的重任。她以女性侏儒的形态行走在凡人中间，作为一名平易近人、乐观向上的同伴与他们并肩作战。"},{t="瘟疫之地的守望者",b="克罗诺姆已在洛丹伦的废墟中安顿下来，主要关注满目疮痍的西瘟疫之地。王国的灾难性覆灭和天灾军团的蔓延严重破坏了该地区的历史，留下了许多时间异常和被困的残影。她从安多哈尔废墟等地隐秘地开展工作，招募凡人冒险者来修补错综复杂的时间线，并在必要时才显露巨龙军团那令人畏惧的威严，以此调查各种异动。"}},faq={{q="克罗米真的是侏儒吗？",a="不。克罗米只是克罗诺姆——一条青铜龙——所使用的凡人形态。青铜龙会采取凡人的伪装，以便在年轻种族中行走而不引起过度的恐惧或怀疑。",al={"克罗米是侏儒吗","克罗米的真身","克罗米是谁"}},{q="为什么克罗米有两个名字？",a="克罗诺姆是她身为青铜龙的真名，而克罗米则是她以侏儒形态在凡人中行走时所使用的简称。",al={"克罗诺姆的名字和性别","为什么克罗米被称为克罗诺姆","克罗诺姆的性别"}},{q="克罗米在西瘟疫之地做什么？",a="天灾军团在洛丹伦造成的浩劫引发了严重的各种历史和时间线扰动。克罗米驻扎在废墟中，负责调查时间异常，消除历史扰动，并招募值得信赖的冒险者来修复受损的时间线。",al={"克罗米在这里做什么","为什么克罗米在安多哈尔","克罗米西瘟疫之地"}},{q="什么是青铜龙军团？",a="青铜龙军团由巨龙军团统领诺兹多姆领导，他们受到了泰坦的祝福，拥有穿越和守护时间路径的力量。他们确保历史按照预定的方向发展，并在时间被篡改或腐化时进行干预。",al={"青铜龙","什么是青铜军团","诺兹多姆军团"}}},fp="9,360,23.370.0,26.516.0,26.180.0,32.124.0,49.274.0,32.245.0"}
P.entries["npc:clarice-foster"] = {n="克拉莉斯·弗斯特",s="克拉莉斯·弗斯特是一位居住在莫高雷预见之池地底深处的被遗忘者女性。她远离洛丹伦受瘟疫侵袭的林地，终日与牛头人先知和神秘主义者一同沉思。",h="克拉莉斯·弗斯特是一位居住在莫高雷预见之池地底深处的被遗忘者女性。她远离洛丹伦受瘟疫侵袭的林地，终日与牛头人先知和神秘主义者一同沉思。",kw={"克拉莉斯·弗斯特","被遗忘者","预见之池","灵魂高地","雷霆崖","直到死亡将我们分离"},ang={["race:Tauren"]="克拉莉斯·弗斯特受到了灵魂高地下神圣的预见之池的欢迎，这展示了牛头人愿意接纳部落中这些不同寻常的新来者。",["race:Undead"]="克拉莉斯·弗斯特代表了被遗忘者与他们在卡利姆多的牛头人盟友之间的联系，使她远离了提瑞斯法和银松森林那片被枯萎病沾染的土地。"},sec={{t="预见之池中的被遗忘者",b="虽然大多数被遗忘者都留在洛丹伦北部的土地上，在幽暗城之下重建他们的王国，但克拉莉斯·弗斯特却远赴卡利姆多，来到了牛头人领地的中心。她栖身于雷霆崖台地之下那洞穴般的预见之池中，与研究大地精神与元素奥秘的被遗忘者药剂师和牛头人萨满们居住在一起。"}},faq={{q="克拉莉斯·弗斯特是谁？",a="克拉莉斯·弗斯特是一位位于雷霆崖下方地下预见之池的被遗忘者女性。她是居住在莫高雷牛头人社会中为数不多的亡灵使者和访客之一。",al={"克拉莉斯是谁","克拉莉斯·弗斯特npc","克拉莉斯·弗斯特背景故事"}},{q="我在哪里可以找到克拉莉斯·弗斯特？",a="她位于预见之池，那是一个位于雷霆崖灵魂高地下方的洞穴群。",al={"克拉莉斯·弗斯特位置","克拉莉斯·弗斯特在哪里","寻找克拉莉斯·弗斯特"}},{q="她提供什么任务？",a="她提供任务“直到死亡将我们分离”。由于她已故的丈夫为了参加对抗亡灵的远征而抛弃了她并最终战死，她对此耿耿于怀，于是派遣旅者前往银松森林的瑟伯切尔，将他的坠饰安放在他的墓碑上。",al={"克拉莉斯·弗斯特任务","直到死亡将我们分离任务"}}},fp="14,179,33.339.0,22.180.0,32.104.0,27.203.0"}
P.entries["npc:clerk-daltry"] = {n="书记员达尔塔",s="书记员达尔塔是驻扎在暮色森林Darkshire Town Hall的市政记录员。他周围堆满了分类账和登记簿，帮助调查这个村庄的过去并追踪历史记录，尽管他的档案有些疏于打理且已过时。",h="书记员达尔塔是驻扎在暮色森林Darkshire Town Hall的市政记录员。他周围堆满了分类账和登记簿，帮助调查这个村庄的过去并追踪历史记录，尽管他的档案有些疏于打理且已过时。",kw={"卡雷文","书记员达尔塔","夜色镇","暮色森林","分类账","密斯特曼托","记录","斯塔文","市政厅"},ang={["faction:Alliance"]="对于那些揭开暮色森林邪恶谜团的联盟调查者来说，书记员达尔塔是获取遗失已久的记录和悬案档案不可或缺的官僚联系人。",["race:Human"]="达尔塔保留着Grand Hamlet在黑暗降临这片林地王国之前所留下的历史遗产。"},sec={{t="城镇记录员",b="当夜色镇竭力对抗入侵的野兽、亡灵恐怖和超自然阴影时，日常的市政职责就落在了书记员达尔塔身上。达尔塔在Darkshire Town Hall与艾尔罗·埃伯洛克公爵及地方议会一起工作，维护着城镇的历史分类账、财产名册和人口普查数据。在这个饱受灾难蹂躏的地区，他的记录是连接Grand Hamlet陷入阴影之前的岁月为数不多的幸存纽带之一。"},{t="纸上踪迹",b="由于夜色镇与暴风城的日常行政联系中断，达尔塔的记录工作出了名的不完善。旧文件丢失、分类账滞后，重要的城镇档案也经常被放错位置或损坏。调查当地悬案或早已失踪的居民的冒险者经常向他咨询，却发现要揭开真相，需要翻阅被忽视的笔记，或者冒险进入危险的森林去寻回丢失的文件。"},{t="斯塔文的传说",b="达尔塔在解开斯塔文·密斯特曼托黑暗谜团的过程中扮演着核心角色。当一个不祥的家族传说将调查者引回夜色镇时，达尔塔会在他的档案中搜索这位前任教师的记录。由于他关于斯塔文的城镇登记条目支离破碎，达尔塔必须派遣寻求者穿过城镇并前往王国各处被遗忘的家园，以拼凑出那段悲惨而血腥的真相。"}},faq={{q="书记员达尔塔在哪里？",a="书记员达尔塔位于暮色森林夜色镇中心村落的Darkshire Town Hall内。他站在城镇官员和议会议员中间，管理着市政记录。",al={"书记员达尔塔位置","达尔塔在哪里","夜色镇书记员位置"}},{q="书记员达尔塔在夜色镇的工作是什么？",a="他担任夜色镇的市政书记员，负责保存文件、城镇名册和法律登记簿。他会协助那些需要有关前居民、土地所有权或历史查询等档案信息的冒险者。",al={"达尔塔的工作","达尔塔的角色","书记员达尔塔是谁"}},{q="为什么他的记录不完整？",a="暮色森林经历了多年的孤立、魔法腐蚀和暴力动荡。由于城镇的注意力都消耗在对抗守夜人的敌人以求生存上，维护最新的分类账往往被搁置，导致他的档案支离破碎。",al={"为什么达尔塔的记录很差","暮色森林过时的记录","达尔塔丢失的分类账"}},{q="书记员达尔塔开启或参与了哪些任务线？",a="达尔塔是“斯塔文的传说”任务线中的关键人物，帮助玩家追踪斯塔文·密斯特曼托那难以捉摸的过去。他还协助进行诸如“卡雷文家族”和“影踪搜寻继续”之类的调查。",al={"达尔塔的任务","达尔塔给的任务","书记员达尔塔任务链"}},{q="谁会派遣调查者去找书记员达尔塔？",a="伊瓦夫人会将那些追查斯塔文谜团的人送到Darkshire Town Hall的书记员那里，而那些追寻其他线索（例如寻找维琳德·星歌）的旅行者也会被指引到他那里。当他自己的记录用完时，达尔塔会把他们打发走，例如去旅店询问一个陌生人的情况。",al={"谁派人去找达尔塔","达尔塔联系人"}},{q="部落玩家能与书记员达尔塔交谈吗？",a="不能。书记员达尔塔是隶属于联盟的市政职员。夜色镇及其市政厅由守夜人守卫，对所有部落冒险者怀有敌意。",al={"达尔塔对部落友好吗","部落可以和达尔塔交谈吗"}}},fx={["063859f4"]={q="书记员达尔塔是谁？",a="书记员达尔塔是一名人类文书官，驻守在暮色森林的 Darkshire Town Hall。他负责保存小镇居民的市政记录、人口普查资料和家族史，是这座饱受阴影与尘封往事困扰的孤立聚居地的常驻档案管理员。",al={"达尔塔是谁","书记员达尔塔是谁","夜色镇的书记员达尔塔"}},["7e4b683b"]={q="书记员达尔塔属于哪一方？",a="达尔塔坚定地站在联盟和夜色镇一边。作为镇政厅的官员，他为当地民政机构效力，并协助那些帮助查明小镇祸患或寻找失踪者的旅人和调查者。",al={"达尔塔属于联盟吗","达尔塔的阵营","书记员达尔塔效忠于谁"}},["3b37b748"]={q="书记员达尔塔想要什么？",a="书记员达尔塔希望维护井然有序的档案，并协助调查暮色森林周围的黑暗谜团。他经常帮助旅人查阅镇上的日志、家族名册和旧文件，追查斯塔文·密斯特曼托等失踪居民，不过他的档案并不完整。",al={"达尔塔想要什么","书记员达尔塔的目标","达尔塔的动机"}},["7e737b61"]={q="书记员达尔塔为什么在这里？",a="达尔塔留在夜色镇，在镇政厅履行自己的市政职责。尽管森林日渐阴森，聚居地也不断遭遇危险，小镇仍需要一名文书官保存契约、信件以及本地区居民的身份记录。",al={"达尔塔为什么在夜色镇","书记员达尔塔为什么在这里","达尔塔在镇政厅的职责"}}},fp="12,203,18.395.0,15.375.0,21.308.1,30.168.0,40.166.0,31.233.0,58.197.0,40.255.0,42.119.0"}
P.entries["npc:cliffwatcher-longhorn"] = {n="峭壁卫兵图林·长角",s="峭壁卫兵图林·长角是驻守在千针石林乱风岗高处的一位坚毅的牛头人领袖。他肩负着保卫这座与世隔绝的部落哨所的重任，负责协调针对不断逼近的加拉克半人马的防御，并监视恐怖图腾部族可疑的阴谋。",h="峭壁卫兵图林·长角是驻守在千针石林乱风岗高处的一位坚毅的牛头人领袖。他肩负着保卫这座与世隔绝的部落哨所的重任，负责协调针对不断逼近的加拉克半人马的防御，并监视恐怖图腾部族可疑的阴谋。",kw={"阿纳克·恐怖图腾","卫兵穆赫·月角","峭壁卫兵图林·长角","乱风岗","加拉克","恐怖图腾","纳塔卡·长角","千针石林"},ang={["faction:Horde"]="乱风岗是保障卡利姆多南部补给线的关键环节，而长角确保了部落能够在充满敌意的半人马领地中守住这处险要的立足点。",["race:Tauren"]="对于牛头人旅行者来说，长角代表了舒哈鲁的前哨精神，他守护着饱受争议的神圣台地，同时还要应对与恐怖图腾部族之间苦涩而未解的摩擦。"},sec={{t="台地守护者",b="乱风岗矗立在千针石林高耸的石柱之上，其生存仰赖于敏锐的眼光和稳健的领导。峭壁卫兵图林·长角负责监督这处险境定居点的日常安全。随着敌对势力在下方的峡谷底部和周边的山脊上集结，长角成为了该定居点侦察报告和军事防御工作的核心协调人。"},{t="半人马的敌意与恐怖图腾的阴谋",b="长角需要在多条战线上应对威胁。在下方的峡谷中，侵略成性的加拉克半人马不断试探哨所的防线，迫使他派遣冒险者去击退它们并削减其数量。然而，更令他感到困扰的是恐怖图腾牛头人。长角对他们在哨所附近建立的秘密营地深感不信任，于是安排侦察以夺取他们隐藏的笔记，从而揭露了内部背叛的令人不安的证据，其中包括阿纳克·恐怖图腾所犯下的暴行。"}},faq={{q="峭壁卫兵图林·长角是谁？",a="峭壁卫兵图林·长角是乱风岗的指挥官，乱风岗是部落在千针石林的一座高耸哨所。他负责组织侦察、防御巡逻，并应对当地的威胁。",al={"峭壁卫兵图林·长角信息","长角是谁","乱风岗领袖"}},{q="我在哪里可以找到峭壁卫兵图林·长角？",a="他位于千针石林乱风岗的主台地上，你可以从峡谷底部乘坐升降梯上去，然后穿过木桥即可到达。",al={"峭壁卫兵图林·长角位置","长角在哪里"}},{q="长角为什么担心半人马？",a="诸如卫兵穆赫·月角之类的侦察兵带回的报告显示，加拉克半人马的敌意正在惊人地膨胀。长角下令主动出击以平息该部族，并防止他们攻占哨所的通道。",al={"为什么要杀半人马","平息半人马背景","千针石林半人马威胁"}},{q="他为什么关注恐怖图腾部族？",a="虽然从名义上来说恐怖图腾氏族是部落的一员，但他们的行径却充满了公开的秘密和恶意。长角怀疑其中有诈，因此委托冒险者窃取他们隐藏的笔记，以查明他们在策划什么阴谋。",al={"长角与恐怖图腾","侦察恐怖图腾的原因"}},{q="阿纳克·恐怖图腾是谁，长角为什么要通缉他？",a="阿纳克·恐怖图腾曾对哨所的居民发动过暴力袭击。长角对他发出了悬赏令，以确保阿纳克能为自己的背叛行为接受正义的制裁。",al={"通缉阿纳克·恐怖图腾","阿纳克悬赏背景"}},{q="峭壁卫兵图林·长角有家人吗？",a="有，他的兄弟纳塔卡·长角驻守在遥远西方的凄凉之地，在幽灵岗哨。由于公务繁忙，峭壁卫兵很少有机会给他写信。",al={"长角的兄弟","兄弟纳塔卡·长角"}}},fx={["8c33620b"]={q="峭壁卫兵图林·长角效忠于哪一方？",a="峭壁卫兵图林·长角坚定地支持部落，以及听命于雷霆崖的牛头人部族。他驻守在乱风岗顶端，负责协调定居点的防御，依靠部落勇士守卫下方的峡谷道路，抵御来犯的半人马氏族和暗中作乱的邪枝部族。",al={"峭壁卫兵图林·长角阵营","长角效忠部落还是联盟","长角效忠于谁"}},d26a5d43={q="峭壁卫兵图林·长角想要什么？",a="长角希望维护千针石林各处的安全与秩序。他想要报复骚扰旅人的敌对加拉克半人马，揭穿当地邪枝部族正在策划的秘密阴谋，并让阿纳克·邪枝这类叛乱分子迅速受到制裁。",al={"长角想要什么","长角的目标","峭壁卫兵图林·长角的动机"}},e12f4ee3={q="峭壁卫兵图林·长角为什么在这里？",a="长角驻守在乱风岗，是这里的主要监管者和守卫之一。他从这座高耸的台地上监视峡谷地面的情况，指挥部落斥候，并组织应对包围前哨站的危险半人马部族和狡诈的邪枝部族。",al={"长角为什么在乱风岗","峭壁卫兵图林·长角为什么在千针石林","长角在乱风岗的职责"}}},fp="21,279,21.405.0,40.498.1,29.201.0,39.158.0,44.213.0,44.218.0,54.162.0,43.174.0"}
P.entries["npc:coleman-farthing"] = {n="库勒曼·法席恩",s="库勒曼·法席恩是一位痛苦的被遗忘者幸存者，住在布瑞尔的恐惧之末旅店。生前，他曾为富有的阿加曼德家族效力，在提瑞斯法北部的庞大面粉磨坊工作。他被说服留下来保卫庄园抵御天灾军团，最终与同事们一同战死，现在他将自己的不死生涯献给了向昔日的主人复仇。",h="库勒曼·法席恩是一位痛苦的被遗忘者幸存者，住在布瑞尔的恐惧之末旅店。生前，他曾为富有的阿加曼德家族效力，在提瑞斯法北部的庞大面粉磨坊工作。他被说服留下来保卫庄园抵御天灾军团，最终与同事们一同战死，现在他将自己的不死生涯献...",kw={"阿加曼德传家宝","阿加曼德磨坊","布瑞尔","库勒曼·法席恩","家族死亡事件","恐惧之末旅店","洛丹伦","提瑞斯法林地"},ang={["class:Warrior"]="库勒曼直接将有志向的战士引向阿加曼德家族墓穴，敦促他们洗劫这个没落贵族家庭的军事传家宝，为即将到来的战争武装自己。",["race:Undead"]="对于被遗忘者来说，库勒曼代表了许多平民对洛丹伦旧贵族的共同怨恨，这些贵族的傲慢和虚荣往往在瘟疫期间加速了臣民的灭亡。"},sec={{t="痛苦的仆人",b="在第三次战争之前，库勒曼·法席恩在阿加曼德磨坊做苦工，过着踏实的生活，那是提瑞斯法林地最大的磨坊和农业基地。当亡灵天灾席卷洛丹伦时，傲慢的阿加曼德家族拒绝放弃他们宝贵的土地。相反，他们敦促家仆和劳工与他们并肩作战，承诺他们能守住农场，抵御亡灵大军。库勒曼和他的工友们相信了他们的主人，并留了下来——这个决定让每一个留下的人都付出了生命的代价。"},{t="来自坟墓的复仇",b="在被唤醒成为亡灵，随后在被遗忘者的旗帜下获得自由后，库勒曼对阿加曼德家族怀有刻骨铭心的仇恨。他不仅责怪天灾军团，更将罪责归咎于雇主那种彻头彻尾的狂妄和贪婪，是他们欺骗了员工，导致他们陷入了一场必死无疑的最后抵抗。现在，库勒曼在布瑞尔的旅店里徘徊，他招募部落的勇士潜入饱受瘟疫蹂躏的磨坊，砍杀那些复活的阿加曼德族人，并洗劫他们家族墓穴中珍藏的传家宝武器，以此剥夺他们最后的尊严。"}},faq={{q="库勒曼·法席恩在哪里？",a="库勒曼·法席恩整天待在布瑞尔的恐惧之末旅店里，该旅店位于提瑞斯法林地的中部。",al={"库勒曼·法席恩位置","库勒曼·法席恩在哪里","库勒曼·法席恩布瑞尔"}},{q="为什么库勒曼如此痛恨阿加曼德家族？",a="当天灾军团入侵洛丹伦时，阿加曼德家族的族长说服了他们的工人——包括库勒曼——留下抵抗以保护磨坊，而不是逃往安全地带。结果，所有的劳工都被屠杀殆尽。库勒曼认为他们的号召不过是一种傲慢的操纵，直接导致了自己的死亡。",al={"为什么库勒曼痛恨阿加曼德","库勒曼·法席恩动机","阿加曼德磨坊仇恨"}},{q="阿加曼德磨坊发生了什么事？",a="这片广阔的庄园完全被天灾军团占领了。它的风力磨坊已成废墟，鬼影憧憧，而阿加曼德家族的成员和他们被屠杀的工人们则在饱受枯萎病侵蚀的田野上徘徊，成了巫妖王麾下毫无思想的亡灵傀儡。",al={"阿加曼德磨坊发生了什么","阿加曼德磨坊背景故事","谁拥有阿加曼德磨坊"}},{q="库勒曼给冒险者指派了什么任务？",a="库勒曼指引冒险者前往北部的阿加曼德磨坊，清理那里游荡的亡灵，杀掉复活的阿加曼德家族成员以亵渎他们的遗骸，并洗劫阿加曼德家族墓穴中的祖传武器。",al={"库勒曼·法席恩任务","布瑞尔阿加曼德任务"}},{q="为什么库勒曼想要阿加曼德家族的传家宝武器？",a="库勒曼将阿加曼德家族的祖传武器视为导致他工友们丧命的虚伪骄傲的象征。他派遣技艺精湛的战士从家族墓穴中掠夺这些遗物，既是为了剥夺这个家族的荣誉，也是为了将这些武器投入对抗他们敌人的实际用途中。",al={"阿加曼德传家宝任务背景","为什么要偷阿加曼德武器"}},{q="库勒曼·法席恩和主教法席恩有亲戚关系吗？",a="他们有相同的姓氏，也都来自覆灭的洛丹伦王国，但没有任何记录证实他们之间存在具体的血缘关系。",al={"主教法席恩关系","库勒曼·法席恩家庭"}}},fp="16,296,16.456.0,24.432.0,36.97.0,49.279.0,35.224.0,44.227.0,51.265.0,47.153.0"}
P.entries["npc:collin-mauren"] = {n="科林·马伦",s="科林·马伦是一名居住在暴风城法师区的人类法师。他是一位学术研究者和咒语制造者，擅长利用奇异的天然试剂来开发独特的实用法术。他的研究方向之一是协助他的熟人，侏儒工程师兼探险家加克希姆·尘链制作特殊的奥术卷轴。",h="科林·马伦是一名居住在暴风城法师区的人类法师。他是一位学术研究者和咒语制造者，擅长利用奇异的天然试剂来开发独特的实用法术。他的研究方向之一是协助他的熟人，侏儒工程师兼探险家加克希姆·尘链制作特殊的奥术卷轴。",kw={"石化蜥蜴","科林·马伦","尘卷风","加克希姆·尘链","mage quarter","石爪山脉","暴风城","西部荒野"},ang={["class:Mage"]="科林是实验性法术创造的典范，他展示了如何利用元素残骸和石化蜥蜴鳞片等尘世试剂来编织实用魔法。",["faction:Alliance"]="科林通过为冒险者提供从西部荒野到卡利姆多各地的实用魔法，促进了联盟内部的交流与贸易。",["race:Human"]="科林在暴风城的法师区安静地生活着，代表了那些从首都中心研究广阔世界的学者型人类法师。"},sec={{t="奥术学者",b="科林·马伦身处暴风城繁华的法师区，整日潜心钻研那些更安静、更实用的魔法应用。他并不追求原始的元素力量，而是专注于制作能够解决特定后勤问题的奥术公式。科林经常从艾泽拉斯各地搜集自然异常现象和原始材料，将它们内在的属性编织进功能性的魔法卷轴和试剂中，供朋友和旅人们使用。"},{t="协助加克希姆·尘链",b="科林与侏儒工匠加克希姆·尘链保持着亲密的友谊。当加克希姆需要一种远程引爆NG-5炸药的方法时，科林想出了一道传讯法术来完成这项工作。为了将咒语刻印在卷轴上，他使用了西部荒野的尘卷风留下的残骸，他很期待听到这位发明家朋友的计划进展如何。"},{t="石爪山脉的异域研究",b="除了与当地元素生物有关的研究外，科林的触角还延伸到了横跨无尽之海的卡利姆多山岩之中。科林对石爪山脉当地石化蜥蜴那坚韧的皮充满了好奇，他一直在搜寻它们的鳞片来合成新的法术。前往卡利姆多的旅人们经常会接到他寻找这些稀有皮革的请求，这进一步加深了科林对原始生物解剖结构如何稳定复杂附魔的痴迷。"}},faq={{q="科林·马伦在哪里？",a="科林·马伦位于暴风城的法师区，隐藏在首都奥术学者们经常出没的塔楼和商店之间。",al={"科林·马伦位置","科林·马伦在哪里","科林·马伦暴风城"}},{q="科林擅长哪种魔法？",a="科林擅长应用附魔和实用法术。他并不钻研战斗唤醒，而是通过实验原始的自然成分（如元素残骸和野兽鳞片）来设计卷轴，例如他为加克希姆的远程爆炸物所适配的传讯法术，以及其他独特的咒语。",al={"科林·马伦研究","科林·马伦做什么","科林·马伦魔法"}},{q="谁是加克希姆·尘链，他和科林是什么关系？",a="加克希姆·尘链是一位热衷冒险的侏儒工匠，也是科林的朋友。当加克希姆需要一种远程引爆炸药的方法时，科林为他制作了一张带有传讯法术的卷轴。",al={"加克希姆·尘链朋友","科林和加克希姆","谁是加克希姆·尘链"}},{q="为什么科林需要西部荒野的元素残骸？",a="科林需要西部荒野尘卷风的残骸，以便将传讯法术刻印在卷轴上。加克希姆·尘链需要这道法术，这样他就能从远处引爆他的NG-5炸药。",al={"西部荒野尘卷风任务","为什么要尘卷风残骸"}},{q="为什么科林对石爪山脉感兴趣？",a="科林研究卡利姆多石爪山脉当地石化蜥蜴鳞片的魔法属性。他将它们那坚固且具有天然抗性的皮作为试剂基础，以合成新的咒语。",al={"石爪山脉石化蜥蜴","马伦的搜集品","石爪山脉鳞片科林"}},{q="科林是肯瑞托的成员吗？",a="虽然科林居住在法师区，并且习练着联盟法师中常见的传统，但他主要是一名独立研究员和试剂制作者，而非达拉然的现任代表。",al={"科林是肯瑞托吗","科林·马伦达拉然","法师区科林"}}},fp="13,203,21.269.0,23.321.0,28.375.0,33.126.0,45.257.0,59.178.0,52.180.0,53.181.0,37.204.0"}
P.entries["npc:colonel-kurzen"] = {n="库尔森上校",s="康拉德·库尔森上校曾是一位受人尊敬且高贵的暴风城军官，被派往荆棘谷北部领导一支探险队。在陷入突然的疯狂与暴政后，他将自己的部队变成了一支在武装营地中活动的流氓丛林民兵。如今，他以前在附近反抗军营地的部下正积极寻求将他处死，以终结他的恐怖统治。",h="康拉德·库尔森上校曾是一位受人尊敬且高贵的暴风城军官，被派往荆棘谷北部领导一支探险队。在陷入突然的疯狂与暴政后，他将自己的部队变成了一支在武装营地中活动的流氓丛林民兵。如今，他以前在附近反抗军营地的部下正积极寻求将他处死...",kw={"库尔森上校","康拉德·库尔森","doren","库尔森","库尔森的营地","反抗军营地","仓库","荆棘谷"},ang={["class:Warrior"]="库尔森作为一个警示性的例子，展示了纪律严明的军事力量在失去意志和荣誉后，是如何被完全颠覆和扭曲的。",["faction:Alliance"]="库尔森代表了一起严重的军事丑闻和暴风城军队的惨痛损失，促使联盟指挥部和当地忠诚派授权将他铲除。",["race:Human"]="对于暴风城的人类来说，库尔森曾是一位同僚和受人尊敬的领袖，这使得他沦为暴君的残酷过程成了丛林危险的严峻提醒。"},sec={{t="坠落",b="在堕落之前，康拉德·库尔森上校在暴风城被视为一位能力出众且高贵的军官。他深受王国领导层的信任，被授予了指挥权，率领一支探险队被派往南方的荆棘谷茂密丛林。然而，在潮湿的荒野深处，库尔森开始表现出反复无常的行为和极端的自大狂，宣布对周围的荒野拥有绝对主权，并抛弃了对暴风城的效忠。"},{t="叛乱",b="库尔森的突然转变导致他的队伍分崩离析。虽然许多士兵屈服于盲目的忠诚或扭曲的狂热，但其他人却对他疯狂和残暴的行为感到震惊——包括他仅仅因为埃梅里·朱尼斯拒绝了他的追求，就将她扔进营地监狱的行为。在多伦上尉的带领下，一群良心未泯的士兵脱离出来，沿着北部道路建立了反抗军营地。这些忠诚的叛逃者现在正对库尔森发动绝望的战争，以阻止他那横行霸道的部队。"},{t="幕后的食人魔",b="库尔森的疯狂并非源于丛林热或自然的精疲力竭。这位上校成为了莫什奥格氏族狡猾的食人魔术士迈佐斯所施展的黑暗魔法的受害者。通过控制库尔森的意志，迈佐斯将一支训练有素的暴风城士兵分遣队变成了暴力的棋子，操纵库尔森在无需食人魔亲自发动公开战争的情况下，实现了对该地区的控制。"}},faq={{q="库尔森上校为何背叛了暴风城？",a="在前往荆棘谷探险期间的某个时候，库尔森开始表现出反复无常的行为和自大狂，抛弃了对暴风城的效忠。是什么让这位曾经高贵的上校陷入疯狂，至今仍是一个他的反抗军营地前部下们试图解开的谜团。",al={"库尔森为什么变坏了","库尔森发生了什么","库尔森背景故事"}},{q="库尔森上校在哪里？",a="他在荆棘谷北部山区的库尔森的营地深处指挥着他的民兵。他居住在营地后方的加固仓库建筑内。",al={"在哪里找到库尔森","库尔森位置","库尔森的营地"}},{q="反抗军营地的反抗军是谁？",a="这些反抗军是库尔森麾下拒绝跟随他陷入疯狂的前士兵。在多伦上尉的带领下，他们保持着对暴风城的忠诚，并在北部边界附近的反抗军营地开展活动，寻求终结库尔森的流氓军队。",al={"反抗军营地背景","多伦上尉是谁","为什么要建立反抗军营地"}},{q="埃梅里·朱尼斯是谁？",a="埃梅里·朱尼斯是随探险队同行的一名女性，她拒绝了库尔森不受欢迎的追求。随着残酷和妄想的加深，上校将她关进了营地的囚笼中。",al={"埃梅里·朱尼斯","库尔森的囚犯"}},{q="库尔森在丛林里是孤军奋战吗？",a="不是。他指挥着那些在反抗军撤往反抗军营地后仍对他保持忠诚的人类雇佣兵、士兵和丛林战士。",al={"库尔森为谁工作","库尔森的盟友"}},{q="如果库尔森上校被杀会怎样？",a="多伦上尉请求联盟冒险者割下库尔森的头颅，以确凿地证明这位上校的死亡，摧毁他民兵的指挥链，并挽回暴风城军队的荣誉。",al={"库尔森任务结局","多伦库尔森的头颅"}}},fp="14,386,17.474.0,13.497.0,27.387.2,46.275.2,32.195.0,37.261.0,21.190.0,37.141.2,40.194.1"}
P.entries["npc:commander-mar-alith"] = {n="指挥官玛尔利斯",s="指挥官玛尔利斯是一位坚毅的暗夜精灵军事指挥官，在希利苏斯的塞纳里奥要塞统领着塞纳里奥议会的先锋部队。他身披重甲，手持一柄巨大的战刃，负责指挥抵抗其拉虫人和暮光之锤邪教徒的军事行动。在他那果决的领导能力之下，深藏着对爱妻娜塔莉亚（Natalia）神秘命运的沉重悲伤。",h="指挥官玛尔利斯是一位坚毅的暗夜精灵军事指挥官，在希利苏斯的塞纳里奥要塞统领着塞纳里奥议会的先锋部队。他身披重甲，手持一柄巨大的战刃，负责指挥抵抗其拉虫人和暮光之锤邪教徒的军事行动。在他那果决的领导能力之下，深藏着对爱妻娜...",kw={"塞纳里奥议会","塞纳里奥要塞","指挥官玛尔利斯","亚什虫巢","雷戈虫巢","佐拉虫巢","玛尔利斯","natalia mar'alith","希利苏斯"},ang={["class:Warrior"]="玛尔利斯身披重甲，挥舞着巨大的战刃，在这个主要由神秘主义者和自然守护者组成的定居点中，指挥着最前线的战斗。",["race:NightElf"]="玛尔利斯是卡多雷哨兵与战士的典范，他们与德鲁伊教团并肩作战，为了保卫卡利姆多抵御古老的威胁，不惜做出沉重的个人牺牲。"},sec={{t="要塞指挥官",b="指挥官玛尔利斯驻守在塞纳里奥要塞的核心地带，肩负着保卫塞纳里奥议会沙漠堡垒的重任。在德鲁伊们揭开希利苏斯古老的生态与宇宙异常现象的同时，玛尔利斯处理着残酷且必要的战争事务。他监督着对亚什虫巢、佐拉虫巢和雷戈虫巢中那些蠢蠢欲动的虫群进行的战术打击，确保这些不间断的虫族入侵不会压垮探险队的中心据点。"},{t="沙漠中的哀伤",b="尽管展现出严谨的军人风度，但玛尔利斯显然正备受一场悲惨的个人遭遇的折磨。他深爱的妻子，Natalia Mar'alith，在执行塞纳里奥议会的任务时深入流沙地带，却再也没有回来。在对塞纳里奥探险队的职责与心如刀绞的悲伤之间，这位指挥官显得越来越心不在焉，他固守着最后的一丝希望，迫切想要知道她在荒漠中究竟遭遇了什么。"},{t="悲剧的命运",b="关于Natalia失踪的残酷真相始终沉重地压在指挥官心头。那些循着她足迹的人最终发现，她在沙漠的低语中陷入疯狂，并被一颗其拉水晶洗脑，成为了克苏恩的奴仆。得知她那悲惨的结局让玛尔利斯受到了沉重的打击，这位指挥官必须在承受心碎之痛的同时，继续领导希利苏斯的防御作战，抵御地下涌动的恐怖威胁。"}},faq={{q="指挥官玛尔利斯是谁？",a="指挥官玛尔利斯是一位暗夜精灵军官，担任塞纳里奥议会在塞纳里奥要塞部队的最高军事指挥官。他负责组织侦察兵、防御部队，并指挥对希利苏斯各处虫巢的战术打击。",al={"玛尔利斯","指挥官玛尔利斯是谁","希利苏斯 暗夜精灵 指挥官"}},{q="在哪里可以找到指挥官玛尔利斯？",a="他位于塞纳里奥要塞内，这是塞纳里奥议会在希利苏斯狂风肆虐的沙地中建立的主要中立定居点。",al={"玛尔利斯位置","玛尔利斯在哪里"}},{q="他的妻子娜塔莉亚怎么了？",a="Natalia Mar'alith在一次探险中消失在沙漠里，从此一去不返。沿着她在希利苏斯留下的踪迹进行探索的冒险者可以了解到她的遭遇。",al={"娜塔莉亚在哪里","亲爱的娜塔莉亚","natalia mar'alith 命运"}},{q="为什么玛尔利斯看起来心不在焉？",a="这位指挥官因其失踪妻子的下落和命运而深陷悲伤与焦虑，这使得他在努力指挥堡垒防御作战时，经常会分心。",al={"为什么玛尔利斯分心","玛尔利斯状态异常"}},{q="指挥官玛尔利斯会指派给冒险者什么任务？",a="玛尔利斯发布战斗指令，引导勇士们剿灭亚什虫巢、佐拉虫巢和雷戈虫巢的虫族势力，对抗暮光之锤，并调查他失踪妻子的下落。",al={"玛尔利斯任务","玛尔利斯给什么任务"}},{q="指挥官玛尔利斯是德鲁伊吗？",a="不。尽管他服务于塞纳里奥议会，但玛尔利斯是一位身披重甲的哨兵和战士指挥官，他负责探险队的军事防御和战术行动，而不是施展德鲁伊魔法。",al={"玛尔利斯是德鲁伊吗","玛尔利斯职业"}}},fp="19,402,21.489.0,19.443.0,13.455.1,27.236.0,39.137.0,35.163.1,38.186.0,58.197.0,31.204.0"}
P.entries["npc:commander-springvale"] = {n="指挥官斯普林瓦尔",s="指挥官斯普林瓦尔曾是一位虔诚的圣骑士，也是影牙城堡的一名指挥官。在大法师阿鲁高策划的野性狼人屠杀中，他与部下们一同丧生，他那复仇的灵魂至今仍徘徊在城堡大厅之中。即使在死后，他的鬼魂依然在守护着这座城堡，抵御着所有入侵者。",h="指挥官斯普林瓦尔曾是一位虔诚的圣骑士，也是影牙城堡的一名指挥官。在大法师阿鲁高策划的野性狼人屠杀中，他与部下们一同丧生，他那复仇的灵魂至今仍徘徊在城堡大厅之中。即使在死后，他的鬼魂依然在守护着这座城堡，抵御着所有入侵者。",kw={"阿鲁高","指挥官","鬼魂","圣骑士","影牙","席瓦莱恩","银松","斯普林瓦尔","狼人"},ang={["class:Paladin"]="斯普林瓦尔是一个清醒的警示：当一位荣誉骑士被禁锢在腐化的坟墓中时，职责和神圣的誓言会变成永恒的折磨。",["faction:Alliance"]="斯普林瓦尔代表了洛丹伦和吉尔尼斯那些失落的士兵，他们不是直接死于天灾军团，而是死于本应阻止天灾的鲁莽召唤。",["faction:Horde"]="对于正在收复银松森林的被遗忘者来说，让这位指挥官的阴魂安息是清除阿鲁高那场悲剧性失败残留物的又一步。"},sec={{t="陨落的指挥官",b="在影牙城堡陷落之前，指挥官斯普林瓦尔是一位忠于圣光的荣誉圣骑士。他统领着银松森林的守军，在洛丹伦沦陷于天灾军团后的动荡时期，负责城堡的安全保卫工作。"},{t="Arugal's Folly",b="当大法师阿鲁高召唤异位面的狼人来增强达拉然对抗亡灵天灾的颓势时，这些野兽很快就脱离了法师的控制。贪婪的狼群袭击了这座要塞，屠杀了席瓦莱恩男爵和他所有的卫兵。斯普林瓦尔死在了他誓言保护的大厅里，他的职责被暴力终结了。"},{t="无尽的守望",b="死亡并没有让斯普林瓦尔得到解脱。他的鬼魂和那些幽灵士兵一起盘踞在城堡的议会厅中。他仍然能运用圣骑士的力量，包括圣光和公正之锤，来对抗入侵者。"}},faq={{q="指挥官斯普林瓦尔生前是什么人？",a="指挥官斯普林瓦尔是一位圣光圣骑士，也是影牙城堡的指挥官。当阿鲁高的狼人攻陷城堡时，他死在了那里。",al={"斯普林瓦尔背景故事","谁是指挥官斯普林瓦尔","斯普林瓦尔是圣骑士吗"}},{q="指挥官斯普林瓦尔是如何死的？",a="他死于大法师阿鲁高为对抗天灾军团而召唤出的野性狼人之手。这些未驯服的野兽转而攻击影牙城堡的居民，屠杀了席瓦莱恩男爵、斯普林瓦尔和守军。",al={"斯普林瓦尔是怎么死的","谁杀死了斯普林瓦尔","斯普林瓦尔之死"}},{q="为什么指挥官斯普林瓦尔的灵魂会盘踞在影牙城堡？",a="死后的扭曲让他仍受限于最后的誓言。斯普林瓦尔的鬼魂徘徊在大厅中，保卫着遗迹，抵御所有来犯者。",al={"为什么斯普林瓦尔是鬼魂","斯普林瓦尔的动机","为什么斯普林瓦尔要战斗"}},{q="斯普林瓦尔使用什么力量？",a="斯普林瓦尔在死后仍保留着圣骑士的能力，用圣光治疗，并用公正之锤击晕敌人。",al={"为什么使用邪恶魔法","斯普林瓦尔的邪恶能力","腐化的圣骑士"}},{q="谁是他的主人？",a="没有记录说明他曾效忠于哪位领主。人们只知道他是一位指挥官，在阿鲁高的狼人攻陷席瓦莱恩男爵的驻地——影牙城堡时牺牲了。",al={"斯普林瓦尔的主人","斯普林瓦尔效忠于谁","斯普林瓦尔与席瓦莱恩"}},{q="在城堡的什么地方可以找到他？",a="指挥官斯普林瓦尔的鬼魂出现在城堡深处，盘踞在靠近城堡教堂和议会厅的防御工事中。",al={"斯普林瓦尔的位置","斯普林瓦尔在哪里","影牙城堡斯普林瓦尔房间"}}},fx={ccdbb916={q="指挥官斯普林瓦尔效忠于哪一方？",a="指挥官斯普林瓦尔不再效忠任何活人，也没有与大法师阿鲁高或占据影牙城堡的狼人结盟。他死后化作幽灵，与自己的幽灵士兵一同徘徊在影牙城堡的议事厅，击倒闯入城堡大厅的任何活人。",al={"斯普林瓦尔的阵营","斯普林瓦尔效忠于谁","斯普林瓦尔的效忠对象"}},["5e96515a"]={q="指挥官斯普林瓦尔想要什么？",a="即使死后，指挥官斯普林瓦尔仍被束缚在自己陨落的影牙城堡。遭到腐化并转化为亡灵后，他将怒火倾泻在任何胆敢踏入城堡大厅的入侵者身上。",al={"斯普林瓦尔的目标","斯普林瓦尔想做什么","斯普林瓦尔的动机"}}},fp="20,197,20.258.0,14.318.0,16.197.0,37.153.0,33.176.0,53.124.0,32.115.0,19.156.0,34.122.0"}
P.entries["npc:cookie"] = {n="曲奇",s="曲奇是一个精英鱼人，在隐藏于死亡矿井深处的巨舰上担任厨师。作为迪菲亚潜行者中一个不同寻常的成员，他在绿皮队长和艾德温·范克里夫的严密监视下照料着船员的汤锅。他是潜入地下干船坞时唯一完全可选的BOSS。",h="曲奇是一个精英鱼人，在隐藏于死亡矿井深处的巨舰上担任厨师。作为迪菲亚潜行者中一个不同寻常的成员，他在绿皮队长和艾德温·范克里夫的严密监视下照料着船员的汤锅。他是潜入地下干船坞时唯一完全可选的BOSS。",kw={"绿皮队长","厨师","曲奇","死亡矿井","迪菲亚","艾德温·范克里夫","铁甲湾","巨舰","鱼人"},ang={["class:Rogue"]="范克里夫的潜行者网络依赖于各种奇怪的非传统资产，而曲奇证明了即便是兄弟会的补给线也有意想不到的惊喜。",["faction:Alliance"]="暴风城的侦察兵常常惊讶地发现，鱼人竟然活跃在迪菲亚的领导层中，而不仅仅是滋扰西部荒野的外围海岸。",["profession:Cooking"]="发现一个鱼人被任命为武装海盗巨舰的首席厨师，这证明了海盗饮食那绝望且粗糙的标准。"},sec={{t="兄弟会的厨师",b="在铁甲湾高耸的巨舰甲板下，掌勺的任务既不是由人类强盗，也不是由地精工程师承担，而是由一个简单的鱼人负责，他被称为曲奇。没人知道他是如何得到这个职位的。无论船员们对于一个鱼人负责他们的口粮有什么怀疑，海盗们很少能挑肥拣瘦，而在月溪镇的地下世界，有吃的就已经不错了。"},{t="苦味佳肴",b="曲奇在海盗旗舰周围的水道和岸边巡逻，挥舞着他的烹饪用具，并使用酸性的药水。尽管他与典型的鱼人部落隔绝，但他仍以野蛮的凶猛捍卫着自己的大锅，向任何闯入码头的入侵者投掷腐蚀性的混合物。因为他的位置远离主要舷梯，许多强攻海湾的人会完全绕过他的厨房，这使得他成为了迪菲亚巨舰上唯一可选的监督者。"}},faq={{q="为什么会有鱼人为迪菲亚当厨师？",a="没有任何记录解释曲奇是如何来到巨舰上服役的。迪菲亚暴徒和地精造船师只是接受了这个安排，因为海盗船员无论厨师是什么种族，只要有食物吃就行。",al={"为什么有鱼人厨师","为什么曲奇在船上","曲奇迪菲亚背景"}},{q="在死亡矿井里哪里可以找到曲奇？",a="曲奇位于死亡矿井最尽头的铁甲湾。他在巨型木质巨舰船尾附近的浅水区和码头上巡逻，就在重拳先生站岗的坡道后面。",al={"曲奇在哪里","死亡矿井曲奇位置","找到曲奇"}},{q="完成死亡矿井必须击杀曲奇吗？",a="不需要，曲奇是副本中唯一的可选BOSS。潜入者可以直接登上船只去对抗绿皮队长和艾德温·范克里夫，而无需打扰在岸边巡逻的厨师。",al={"曲奇是可选的吗","必须杀死曲奇吗","跳过曲奇"}},{q="曲奇属于某个特定的鱼人部落吗？",a="曲奇与当地已知的任何鱼人部落（例如西部荒野沿海的那些）都没有关联。他完全生活并工作在迪菲亚潜行者的暴徒和恶棍之中。",al={"曲奇是什么部落","曲奇鱼人部落"}},{q="曲奇使用什么武器或攻击方式？",a="曲奇在近战中使用烹饪用具，并能向攻击者投掷腐蚀性的酸液，用危险的烹饪混合物灼伤敌人。",al={"曲奇技能","曲奇怎么战斗","曲奇攻击"}},{q="曲奇在巨舰上听命于谁？",a="曲奇直接为迪菲亚潜行者的海军部门服务，在绿皮队长的指挥下工作，最终听命于艾德温·范克里夫本人。",al={"曲奇boss","谁领导曲奇","曲奇绿皮范克里夫"}}},fx={f44f954f={q="曲奇是谁？",a="曲奇是一名精英鱼人，在死亡矿井深处艾德温·范克里夫的铁甲战舰上担任船厨。与大多数在西部荒野海岸四处游荡的野性鱼人不同，曲奇在一群人类暴徒中找到了一个不同寻常的归宿：他在锅里烹煮着令人难以放心的食物，供迪菲亚潜行者的海盗船员享用。",al={"曲奇是谁","曲奇的身份","鱼人厨师是谁"}},c6e0c482={q="曲奇效忠于哪一方？",a="曲奇坚定地效忠于迪菲亚潜行者。他与绿皮队长和艾德温·范克里夫一同驻守在战舰上，直接为海盗暴徒效力；他会竭力保卫船只，抵御任何试图破坏范克里夫叛乱的联盟入侵者。",al={"曲奇效忠于谁","曲奇是迪菲亚潜行者成员吗","曲奇属于什么阵营"}}},fp="6,253,22.348.0,13.437.0,49.210.0,43.188.0,43.192.0,46.180.0,40.148.0,44.130.0"}
P.entries["npc:corithras-moonrage"] = {n="科瑞萨斯·月怒",s="科瑞萨斯·月怒是一位暗夜精灵学者，也是驻扎在泰达希尔多兰纳尔村的任务发布者。他指引刚到达的冒险者了解伟大的世界之树的本质，并委托他们维护神圣的月亮井。通过他的教导，他揭示了泰达希尔的精神重要性以及卡多雷所肩负的日益沉重的负担。",h="科瑞萨斯·月怒是一位暗夜精灵学者，也是驻扎在泰达希尔多兰纳尔村的任务发布者。他指引刚到达的冒险者了解伟大的世界之树的本质，并委托他们维护神圣的月亮井。通过他的教导，他揭示了泰达希尔的精神重要性以及卡多雷所肩负的日益沉重的...",kw={"科瑞萨斯·月怒","crown of the earth","多兰纳尔","范达尔·鹿盔","卡多雷","月亮井","暗夜精灵","泰达希尔"},ang={["class:Druid"]="德鲁伊会发现科瑞萨斯的任务与他们的使命息息相关，因为他的月亮井仪式直接追踪着世界之树的健康状况和蔓延的疾病。",["class:Priest"]="艾露恩的牧师协助科瑞萨斯运送月亮井的圣水，维持多兰纳尔周边荒野的精神与物质和谐。",["race:NightElf"]="对于暗夜精灵来说，与科瑞萨斯交谈是了解第三次战争后现实的基础课程，直面古老永生能力的丧失以及泰达希尔充满争议的创造过程。"},sec={{t="多兰纳尔学者",b="科瑞萨斯·月怒居住在多兰纳尔这个林荫聚落，担任离开幽影谷庇护所的旅行者的导师。当年轻的卡多雷冒险进入泰达希尔更广阔的枝叶间时，科瑞萨斯确保他们了解自己新家园的历史。他教导说，在这个不断变化的时代，生存需要警惕并敬畏自然法则。"},{t="Crown of the Earth",b="科瑞萨斯的大部分职责围绕着为达纳苏斯的德鲁伊收集月亮井水。他指导冒险者从泰达希尔各处的月亮井中收集纯净的水，装入特制的瓶中，送交给范达尔·鹿盔。通过这些考验，他监测着世界之树的健康状况，并试图维持荒野中脆弱的平衡，以抵御不断蔓延的腐蚀。"},{t="卡多雷的负担",b="在科瑞萨斯的指引之下隐藏着关于泰达希尔起源的令人不安的事实。与古老的诺达希尔不同，这棵新的世界之树是在没有巨龙军团祝福的情况下培育出来的，因为他们拒绝了范达尔·鹿盔那充满野心的创造。科瑞萨斯反思着暗夜精灵永生能力的丧失，以及卡多雷如今在这一棵未受祝福的枝干下所面临的脆弱而又不确定的未来。"}},faq={{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是一位位于多兰纳尔的暗夜精灵学者。他向冒险者介绍泰达希尔的历史，并委托他们照料神圣的月亮井，以及测试世界之树的泉水。",al={"科瑞萨斯·月怒角色","科瑞萨斯是谁","多兰纳尔任务发布者"}},{q="在哪里可以找到科瑞萨斯·月怒？",a="他站在多兰纳尔，也就是位于泰达希尔南部的中心十字路口村庄的户外。",al={"科瑞萨斯位置","科瑞萨斯在哪里","寻找科瑞萨斯"}},{q="Crown of the Earth任务线是关于什么的？",a="Crown of the Earth任务包括从泰达希尔各处的月亮井中取水。科瑞萨斯将收集到的水汇总，送往达纳苏斯交给范达尔·鹿盔，那里的德鲁伊需要补充他们的月亮井。",al={"crown of the earth含义","科瑞萨斯任务","月亮井任务"}},{q="为什么科瑞萨斯担心泰达希尔的起源？",a="科瑞萨斯分享了泰达希尔如何在第三次战争后被种植以恢复暗夜精灵永生能力的历史。由于巨龙军团拒绝祝福这棵树，科瑞萨斯敏锐地意识到这棵树缺乏神圣的保护，而他的人民仍然是凡人。",al={"为什么是卡多雷的负担","龙族拒绝祝福","为什么没有永生"}},{q="科瑞萨斯教导新冒险者什么？",a="他传授关于第三次战争中近期牺牲的教训、泰达希尔的建立，以及每个卡多雷为保卫他们新的林地家园所肩负的责任。",al={"科瑞萨斯背景故事","多兰纳尔历史","科瑞萨斯告诉你什么"}},{q="科瑞萨斯是属于塞纳里奥议会还是达纳苏斯？",a="他是达纳苏斯的一名忠诚公民和学者，驻扎在多兰纳尔，与德鲁伊和牧师们密切合作，监测森林及其水域的福祉。",al={"科瑞萨斯阵营","科瑞萨斯是德鲁伊吗"}}},fx={a5e544f2={q="科瑞萨斯·月怒想要什么？",a="科瑞萨斯想要照料并了解这棵年轻世界之树的状况。通过名为“Crown of the Earth”的仪式，他让旅人从泰达希尔各处神圣的月亮井收集重要的泉水，为参天的枝干赐福。他努力滋养这片土地，并探寻困扰卡多雷的重重负担。",al={"科瑞萨斯想要什么","科瑞萨斯·月怒的目标","科瑞萨斯的目的"}},["35aa58f2"]={q="科瑞萨斯·月怒为什么在多兰纳尔？",a="科瑞萨斯驻扎在繁忙的多兰纳尔，担任向幽影谷之外探险的新晋暗夜精灵冒险者的向导。他位于泰达希尔的中心，招募能干的人手执行重要仪式，并调查围绕世界之树日益加剧的生态与灵性问题。",al={"科瑞萨斯为什么在这里","科瑞萨斯为什么在多兰纳尔","科瑞萨斯·月怒在多兰纳尔的目的"}}},fp="18,173,19.310.0,18.301.0,26.324.1,26.159.0,38.100.0,47.209.0,54.216.0,42.146.0,59.139.0"}
P.entries["npc:councilman-millstipe"] = {n="议员米尔斯迪普",s="议员米尔斯迪普是夜色镇管理委员会的成员，居住在暮色森林的市政厅内。他对王室的忽视和来自首都的司法干预深感不满，积极寻求对威胁这片黑暗之地的罪犯进行惩罚。",h="议员米尔斯迪普是夜色镇管理委员会的成员，居住在暮色森林的市政厅内。他对王室的忽视和来自首都的司法干预深感不满，积极寻求对威胁这片黑暗之地的罪犯进行惩罚。",kw={"议员米尔斯迪普","夜色镇","迪克斯特·瓦德","暮色森林","house of nobles","米尔斯迪普","morbent fel","监狱"},ang={["class:Rogue"]="对于愿意潜入戒备森严的监狱并执行未经授权的政治处决的行动者，米尔斯迪普提供的任务直接挑战了House of Nobles。",["faction:Alliance"]="米尔斯迪普体现了暴风城养尊处优的贵族与绝望的暮色森林边境定居点之间深刻的政治裂痕，这些定居点几乎得不到援助，却面临着来自首都的强硬干预。"},sec={{t="被暴风城拒绝的正义",b="当夜色镇在亡灵和凶猛野兽的阴影下苦苦挣扎时，当地议会正在与暴风城的官僚机构进行着一场艰难的斗争。议员米尔斯迪普代表了小镇对王室日益增长的怨恨。当臭名昭著的掘墓人迪克斯特·瓦德被抓获，因其向死灵法师Morbent Fel出售新鲜挖掘的尸体时，夜色镇的领导人判处了他死刑。然而，暴风城的House of Nobles介入了，将迪克斯特·瓦德的死刑改判，并将他安全地关押在暴风城监狱中。"},{t="给贵族的信息",b="米尔斯迪普拒绝让首都腐败的政客凌驾于暮色森林的安全与正义之上，他秘密委托冒险者去完成这项工作。通过下令在监狱牢房内对迪克斯特·瓦德进行即决处决，米尔斯迪普旨在向House of Nobles传递一个明确的信息：如果暴风城拒绝保护暮色森林的人民，人民就会亲手伸张正义。"}},faq={{q="在哪里可以找到议员米尔斯迪普？",a="议员米尔斯迪普位于夜色镇的市政厅内，坐落在暮色森林的东部。",al={"米尔斯迪普位置","米尔斯迪普在哪里","寻找议员米尔斯迪普"}},{q="为什么米尔斯迪普想要迪克斯特·瓦德死？",a="迪克斯特·瓦德是一名掘墓人，他挖掘了暮色森林的死者并将其卖给死灵法师Morbent Fel。Lord Ebonlocke判处他斩首，但暴风城的House of Nobles赦免了他的死刑，并将他关进了监狱。",al={"为什么要杀死迪克斯特·瓦德","米尔斯迪普 迪克斯特·瓦德","瓦德的罪行"}},{q="米尔斯迪普对暴风城有什么不满？",a="米尔斯迪普认为暴风城在干预当地司法的同时却抛弃了暮色森林。House of Nobles推翻了夜色镇对迪克斯特·瓦德的正当死刑判决，使这个饱受创伤的定居点感到被王座忽视和缺乏保护。",al={"为什么对暴风城不满","house of nobles 夜色镇","米尔斯迪普的政治立场"}},{q="米尔斯迪普有已知的家人吗？",a="议员米尔斯迪普没有已知的家人。",al={"米尔斯迪普的亲属","dorothea millstipe","米尔斯迪普的家庭"}}},fx={["2e4c6610"]={q="议员米尔斯迪普是谁？",a="议员米尔斯迪普是暮色森林夜色镇议会的重要成员。他对暴风城的忽视和官僚干预感到不满，于是留在镇政厅保护饱受困扰的居民，并坚决反抗那些破坏暮色森林边境正义的远方贵族。",al={"米尔斯迪普是谁","议员米尔斯迪普","议员米尔斯迪普是谁"}},["926d4bb5"]={q="议员米尔斯迪普效忠于哪一方？",a="米尔斯迪普效忠于夜色镇居民和暮色森林议会。尽管他在名义上属于大联盟的一员，但他对暴风城腐败的贵族议会怀有强烈怨恨，坚定地维护自己的地方城镇，反对那些拒绝派遣援助的远方官僚。",al={"米尔斯迪普的阵营","米尔斯迪普属于联盟吗","米尔斯迪普效忠于谁"}},["78c3778b"]={q="议员米尔斯迪普想要什么？",a="米尔斯迪普想为暮色森林伸张边境正义，并向贵族议会发出明确警告。他对贵族赦免盗墓贼迪克斯特·瓦德、免其死刑一事深感厌恶，因此要求在监狱处死瓦德，以证明暮色森林不会容忍暴风城的腐败干预。",al={"米尔斯迪普的目标","米尔斯迪普想要什么","议员米尔斯迪普的目标"}},["7f6b4a90"]={q="议员米尔斯迪普为什么在这里？",a="米尔斯迪普留在夜色镇的镇政厅履行议员的公职。他在那里应对暮色森林日益严峻的危机，协调地方事务，并招募独立的勇士执行暴风城治安官拒绝执行的判决。",al={"米尔斯迪普为什么在暮色森林","米尔斯迪普为什么在这里","米尔斯迪普在夜色镇做什么"}}},fp="20,154,27.459.0,23.323.1,40.84.0,42.222.0,45.239.0,37.43.0"}
P.entries["npc:count-remington-ridgewell"] = {n="雷明顿·瑞治维尔伯爵",s="雷明顿·瑞治维尔伯爵是一位富有的、出现在Stormwind Keep内Petitioner's Chamber的人类贵族。作为House of Nobles的一员，他以能策划王国中最顶级的私人稀有历史文物、传家宝和艺术品收藏而自豪。",h="雷明顿·瑞治维尔伯爵是一位富有的、出现在Stormwind Keep内Petitioner's Chamber的人类贵族。作为House of...",kw={"house of nobles","mayara brightwing","博物馆","匹瑞诺德王冠","petitioner's chamber","雷明顿·瑞治维尔","瑞治维尔","stormwind keep"},ang={["faction:Alliance"]="对于联盟的雇佣兵来说，瑞治维尔伯爵是一位有利可图的赞助人，他愿意为找回北方覆灭王国和失落矮人城市的遗物而支付高额报酬。",["race:Human"]="作为暴风城House of Nobles的一员，瑞治维尔体现了富有的贵族阶层，尽管王国政治动荡，他们仍将文化声望和艺术收藏置于首位。"},sec={{t="古董鉴赏家",b="雷明顿·瑞治维尔代表了House of Nobles的精英品味，他为家族收藏珠宝和文物的私人博物馆感到无比自豪。这位伯爵并不关心军事行动或当地的起义，而是将他可观的财富花在收购艾泽拉斯各地已覆灭的文明和家族的遗物上。为了扩充他那名声显赫的画廊，他资助大胆的冒险者并雇佣像Mayara Brightwing这样的外勤探员，派遣他们从危险的废墟中找回无价的奇珍异宝，从奥特兰克的高山堡垒到燃烧平原的火山荒地。"}},faq={{q="谁是雷明顿·瑞治维尔伯爵？",a="雷明顿·瑞治维尔伯爵是一位人类贵族和古董收藏家，驻扎在Stormwind Keep的Petitioner's Chamber中。他利用家族财富从世界各地收购有价值的遗物、珠宝和艺术品。",al={"雷明顿·瑞治维尔是谁","雷明顿·瑞治维尔","瑞治维尔伯爵"}},{q="瑞治维尔伯爵寻找什么文物？",a="瑞治维尔雇佣冒险者为他的博物馆找回遗失的传家宝。值得注意的藏品包括从奥特兰克废墟中获得的匹瑞诺德王冠，以及从索瑞森废墟中找回的历史悠久的黑铁矮人宝藏。",al={"瑞治维尔任务","匹瑞诺德王冠任务","他想要什么"}},{q="谁是Mayara Brightwing？",a="Mayara Brightwing是瑞治维尔伯爵雇佣的一名探员。他派遣她前往燃烧平原，在古老的索瑞森废墟中搜寻古董。",al={"mayara brightwing关联","mayara是谁"}},{q="在哪里可以找到雷明顿·瑞治维尔伯爵？",a="他居住在Stormwind Keep内的Petitioner's Chamber中，与其他寻求谒见王室的贵族和显贵们在一起。",al={"瑞治维尔伯爵在哪里","瑞治维尔位置","petitioner's chamber的贵族"}}},fp="25,174,28.437.0,33.194.0,41.170.0,25.155.0,45.167.0"}
P.entries["npc:crane-operator-bigglefuzz"] = {n="起重机操作员比戈弗兹",s="起重机操作员比戈弗兹是一名在地精港口棘齿城操作重型机械的码头工人。在一次因起重机超载导致的货物洒落事故后，他急于在主管发现之前找回一瓶被盗的贵重葡萄酒。",h="起重机操作员比戈弗兹是一名在地精港口棘齿城操作重型机械的码头工人。在一次因起重机超载导致的货物洒落事故后，他急于在主管发现之前找回一瓶被盗的贵重葡萄酒。",kw={"比戈弗兹","货物","起重机操作员","码头","疯子麦格利什","波特酒","棘齿城","热砂港"},ang={["class:Rogue"]="潜行者们应该能体会，像“疯子”麦格利什这样投机取巧的小偷是多么迅速地利用码头的混乱，从地精的眼皮底下偷走价值连城的违禁品。",["profession:Engineering"]="工程师们也许会明白，热砂港的索具和起重机过载依然是卡利姆多海岸线上工业事故的主要原因。"},sec={{t="码头事故",b="和许多地精码头工人一样，起重机操作员比戈弗兹更看重效率和速度，而忽略了基本的安全准则。在试图从一艘商船上吊起过重的货物时，他的起重机发生了故障，导致板条箱在棘齿城的码头上四处散落。在随后的混乱中，趁火打劫的无赖们蜂拥而至，只留下比戈弗兹在现场清理烂摊子，并试图在加兹鲁维或当地港口主管扣除他的薪水之前，抢救出最珍贵的货物。"},{t="被盗的波特酒",b="这场事故最大的损失并非破损的木板，而是一箱装有极其罕见的九十九年陈酿波特酒。在比戈弗兹还没来得及清理洒落物之前，一个行踪诡秘的流浪汉“疯子”麦格利什抢走了一瓶酒并藏了起来，这让比戈弗兹面临着无法弥补的损失，不知该如何交代。"}},faq={{q="起重机操作员比戈弗兹是谁？",a="他是一名部署在棘齿城码头的地精起重机操作员，负责为热砂港装卸海运货物。",al={"比戈弗兹是谁","起重机操作员","棘齿城的比戈弗兹"}},{q="是什么导致了码头的事故？",a="比戈弗兹试图用他的起重机一次吊起过重的货物，导致机械故障，货物散落满地。",al={"起重机为什么掉落货物","棘齿城码头事故","起重机事故"}},{q="是谁偷了比戈弗兹的东西？",a="一个叫“疯子”麦格利什的狡猾捣蛋鬼趁着货物洒落的混乱，顺走了一瓶名贵的九十九年陈酿波特酒，然后溜之大吉。",al={"谁拿走了波特酒","麦格利什的货物","谁抢劫了比戈弗兹"}},{q="为什么比戈弗兹对被偷的那瓶酒如此担忧？",a="那瓶九十九年陈酿的波特酒极其稀有且昂贵。因为疏忽导致丢失，意味着他将面临热砂港老板们的严厉经济处罚，甚至更糟。",al={"比戈弗兹为什么在意那瓶酒","码头麻烦的原因"}}},fx={acbd2274={q="起重机操作员比戈弗兹效忠于哪一方？",a="比戈弗兹受雇于热砂港，驻扎在中立港口棘齿城。和镇上的大多数地精一样，他主要效忠于自己的生意和雇主，而非部落或联盟；只要愿意做生意，或帮他弥补代价高昂的过失，他都会欢迎。",al={"比戈弗兹所属阵营","比戈弗兹为谁工作","起重机操作员比戈弗兹的效忠对象"}},e72c0e10={q="起重机操作员比戈弗兹想要什么？",a="比戈弗兹想找人取回那瓶在货物洒满码头时遗失的99年波尔多陈酿。一个名叫Mad Magglish的地精偷走了这瓶珍稀佳酿。比戈弗兹急着把它找回来，以免上司发现这场意外。",al={"比戈弗兹需要什么","比戈弗兹的目标","比戈弗兹要你做什么"}},d46df1e8={q="起重机操作员比戈弗兹为何在这里？",a="比戈弗兹驻守在棘齿城码头，负责操作大型装货起重机，在商船和岸边之间搬运货物。不幸的是，他试图一次吊起远超负荷的货物，结果起重机严重损坏，港口的货物也散落在整个码头上。",al={"比戈弗兹为何在棘齿城","比戈弗兹在棘齿城的职责","比戈弗兹为何在码头"}},eaf0ddf2={q="起重机操作员比戈弗兹与谁有关联？",a="比戈弗兹隶属于热砂港，是棘齿城码头工人的一员。他眼下的烦恼与窃贼Mad Magglish直接相关，对方从他洒落的货物中偷走了贵重酒品。",al={"比戈弗兹的人际关系","比戈弗兹隶属于谁","比戈弗兹与热砂港"}}},fp="25,257,19.467.0,15.303.0,33.144.0,38.138.0,26.150.0,53.175.0"}
P.entries["npc:craven-drok"] = {n="克拉文·德洛克",s="克拉文·德洛克是一位流浪的兽人，常被发现躲藏在奥格瑞玛下方阴暗的Cleft of Shadow隧道中。正如他的绰号所暗示的那样，他总是待在城市黑暗的角落里，偶尔会向愿意帮忙的旅人寻求协助，处理一件棘手的事情：联盟如何看待部落。",h="克拉文·德洛克是一位流浪的兽人，常被发现躲藏在奥格瑞玛下方阴暗的Cleft of...",kw={"联盟关系","cleft of shadow","克拉文·德洛克","奥格瑞玛"},ang={["class:Rogue"]="Cleft of Shadow是那些在聚光灯之外行事的人们聚集的天然场所，像德洛克这样的联络人正是这座首都地下世界的典型代表。",["race:Orc"]="大多数兽人都对克拉文·德洛克嗤之以鼻，因为他喜欢潜伏在阴暗的Cleft of Shadow，这与兽人传统中对荣誉和勇气的认知形成了鲜明的对比。"},sec={{t="阴影中的潜行者",b="当奥格瑞玛的大多数兽人自豪地走在Valley of Honor或Valley of Strength阳光明媚的大道上时，克拉文·德洛克却完全避开了阳光。他出没于Cleft of Shadow蜿蜒的地底路径，这是一个通常留给术士、潜行者和从事不那么光彩行当的人的隐秘之地。德洛克名副其实，行为怯懦，更喜欢躲在暗处，雇佣路人去执行他那些不可告人的差事，其中就包括一件关于部落与联盟关系的任务。"}},faq={{q="我在哪里可以找到克拉文·德洛克？",a="克拉文·德洛克在Cleft of Shadow宽阔的地下通道中游荡，那里位于奥格瑞玛主干道的深处。",al={"克拉文·德洛克位置","克拉文·德洛克在哪里","德洛克奥格瑞玛位置"}},{q="他为什么被称为“克拉文（怯懦者）”？",a="兽人文化最推崇公开的勇敢和武勇。德洛克因为躲藏在阴暗的洞穴里、总是低着头行事，并雇佣他人去处理他自己不愿亲自过问的任务，从而赢得了这个绰号。",al={"为什么他是怯懦者","克拉文·德洛克名字","克拉文·德洛克是个懦夫吗"}},{q="他与联盟有什么关联？",a="德洛克会发布名为“联盟关系”的差事。他称萨尔是一位明智的外交官，学习了许多人类的处事方式，随后他会派遣旅人去找科尔丹，后者致力于防止联盟错误地断定部落已经与燃烧军团达成了协议。",al={"克拉文·德洛克联盟","联盟关系德洛克"}},{q="克拉文·德洛克会把旅人派给谁？",a="他把他们派给科尔丹，这是一位魔法学徒，他的小屋位于奥格瑞玛西出口附近。在大酋长的授意下，科尔丹致力于确保部落不会被误认为是燃烧军团的盟友。",al={"科尔丹是谁","德洛克联络人"}}},fp="11,156,24.313.0,29.105.0,26.188.0,42.229.0,39.223.0"}
P.entries["npc:cyrus-therepentous"] = {n="塞勒斯·萨雷芬图斯",s="塞勒斯·萨雷芬图斯是一只强大的黑龙人，栖息在燃烧平原滑石的洞穴深处。与其立刻击杀闯入者，他更倾向于考验那些大胆的凡人，看看他们是否拥有为黑龙军团效力的实力。",h="塞勒斯·萨雷芬图斯是一只强大的黑龙人，栖息在燃烧平原滑石的洞穴深处。与其立刻击杀闯入者，他更倾向于考验那些大胆的凡人，看看他们是否拥有为黑龙军团效力的实力。",kw={"黑龙军团","燃烧平原","塞勒斯·萨雷芬图斯","龙人","滑石","烈焰的滋味"},sec={{t="滑石的主宰",b="塞勒斯·萨雷芬图斯隐居在滑石的一处洞穴中，监视着燃烧平原的火山峭壁。像他的许多同类一样，他以极度轻蔑的态度看待凡人旅行者，声称只有蠢货才会打扰他的巢穴。然而，在他凶猛的外表下隐藏着冷酷的算计：与其一见到闯入者就将其吞噬，他宁愿让他们去面对他手下致命的挑战，并利用那些能在烈焰试炼中幸存下来的强者。"}},faq={{q="塞勒斯·萨雷芬图斯是谁？",a="塞勒斯·萨雷芬图斯是一只足智多谋的黑龙人，驻扎在燃烧平原滑石的一个洞穴中。他效忠于黑龙军团，并会考验那些胆敢进入他巢穴的凡人冒险者。",al={"塞勒斯·萨雷芬图斯","塞勒斯是谁","滑石龙人"}},{q="在哪里可以找到塞勒斯·萨雷芬图斯？",a="他居住在燃烧平原东北部滑石内的一处洞穴深处。",al={"塞勒斯位置","塞勒斯·萨雷芬图斯在哪里","塞勒斯的洞穴"}},{q="为什么塞勒斯不会一见到冒险者就发起攻击？",a="尽管他公开表示考虑吃掉闯入者，但塞勒斯更倾向于观察凡人是否对他有用。他会让那些证明自己有利用价值的人去面对致命的试炼和爪牙，以此作为交换。",al={"为什么塞勒斯没有敌意","为什么塞勒斯不杀我","塞勒斯对话"}}},fp="18,283,26.477.0,26.201.0,38.105.0,46.191.0"}
P.entries["npc:dalar-dawnweaver"] = {n="达拉尔·道恩维沃尔",s="达拉尔·道恩维沃尔曾是达拉然的一位大法师，现在银松森林的瑟伯切尔为被遗忘者效力。他在天灾军团摧毁法师之城的战役中丧生，后来摆脱了巫妖王的控制，将他那睿智的魔法头脑转向了剖析区域威胁。在墓地的阴影中，他指挥着各方势力去了解达拉然的残留影响，并试图扭转大法师阿鲁高的疯狂。",h="达拉尔·道恩维沃尔曾是达拉然的一位大法师，现在银松森林的瑟伯切尔为被遗忘者效力。他在天灾军团摧毁法师之城的战役中丧生，后来摆脱了巫妖王的控制，将他那睿智的魔法头脑转向了剖析区域威胁。在墓地的阴影中，他指挥着各方势力去了解...",kw={"大法师","阿鲁高","达拉尔","达拉然","道恩维沃尔","被遗忘者","肯瑞托","瑟伯切尔","银松森林"},ang={["class:Mage"]="对于被遗忘者法师来说，达拉尔是达拉然往昔辉煌的一面黑暗镜子，他展示了肯瑞托的训练可以如何被武器化，用来为黑暗女王效力。",["faction:Horde"]="达拉尔驻扎在瑟伯切尔，通过协调对影牙城堡的狼人和敌对的肯瑞托据点的打击，确保了部落西线的安全。",["race:Undead"]="达拉尔是被遗忘者重获自主权的典范，他将自己生前掌握的知识反过来用于对付达拉然的残党和威胁他们主权的流氓法师。"},sec={{t="一位陨落的大法师",b="生前，达拉尔·道恩维沃尔曾在肯瑞托身居高位，当达拉然还是奥术造诣的巅峰之时，他曾漫步于紫罗兰城堡的大厅中。他的凡人之躯终结于天灾军团攻陷这座城市，为阿克蒙德的召唤铺平道路之时。他被复活成为巫妖王毫无思想的奴仆，当巫妖王对天灾军团的控制减弱时，达拉尔随希尔瓦娜斯·风行者一同挣脱了枷锁。现在驻扎在瑟伯切尔的他，依然保留着大法师敏锐的智识，并将全部心力转向了守护被遗忘者的疆域。"},{t="聚焦安伯米尔与影牙城堡",b="银松森林正处于多重危险之中，而达拉尔担任着瑟伯切尔的奥术战略家。在南方，达拉然的法师们占据了安伯米尔，干涉着达拉尔试图揭露和破坏的事务。更近处则是影牙城堡以及被释放到森林中的野性狼人。达拉尔对他曾经的同事大法师阿鲁高有着深入的了解，他精心策划了一系列行动，旨在摧毁阿鲁高制造的野兽，防止它们横扫整个区域。"}},faq={{q="谁是达拉尔·道恩维沃尔？",a="达拉尔·道恩维沃尔是一位身处银松森林瑟伯切尔的被遗忘者法师。生前，他是达拉然肯瑞托的一位大法师。在第三次战争中死亡并被天灾军团复活后，他摆脱了巫妖王的控制，转而效忠黑暗女王。",al={"达拉尔是谁","达拉尔·道恩维沃尔背景故事","达拉尔背景"}},{q="他在第三次战争中遭遇了什么？",a="阿尔萨斯·米奈希尔率领天灾军团入侵达拉然以夺取麦迪文之书时，达拉尔就在城中。当克尔苏加德在艾泽拉斯召唤阿克蒙德时，达拉尔在袭击中阵亡，并作为天灾军团的仆从被复活，直到希尔瓦娜斯解放了他。",al={"达拉尔如何死亡","达拉尔死亡","达拉尔与第三次战争"}},{q="为什么达拉尔驻扎在瑟伯切尔？",a="他是银松森林被遗忘者当地的奥术权威。他不仅熟知占领安伯米尔的肯瑞托部队，还曾是大法师阿鲁高的同僚，这使他成为对抗这些威胁的最佳人选。",al={"达拉尔为何在瑟伯切尔","达拉尔在银松森林的角色"}},{q="达拉尔与大法师阿鲁高有什么联系？",a="在达拉然陷落之前，他们都是肯瑞托的法师。达拉尔意识到阿鲁高在影牙城堡进行的召唤实验所导致的堕落及其致命危险，因此他委派冒险者去收集那些由阿鲁高之愚行导致的遗物，并最终要求终结这位疯狂法师的性命。",al={"达拉尔与阿鲁高","达拉尔是否认识阿鲁高"}},{q="达拉尔对达拉然的残余势力有何企图？",a="达拉尔密切关注着他曾经的家园以及驻扎在安伯米尔的幸存肯瑞托部队。他指挥特工拦截他们的通讯并分析其意图，以确保他们无法威胁到银松森林的被遗忘者。",al={"达拉尔与达拉然","达拉尔与安伯米尔"}},{q="达拉尔是肯瑞托的一员吗？",a="不。尽管他曾是其中的大法师，但他现在的忠诚属于被遗忘者和部落。他积极反对在银松森林活动的幸存肯瑞托部队。",al={"达拉尔是否属于肯瑞托","达拉尔是否忠于达拉然"}}},fp="16,312,17.487.0,32.417.0,24.262.0,42.239.0,40.206.0,46.294.0,45.208.0,36.183.0"}
P.entries["npc:daphne-stilwell"] = {n="达芙妮·斯迪威尔",s="达芙妮·斯迪威尔在西部荒野沿海悬崖顶上的一处偏僻果园里耕种，那里可以俯瞰长滩。她和丈夫乔丹一起逃离了北方的动乱，南下迁居至此。她在默默援助圣光教会的同时，还保护着自己的家园，抵御附近歹徒的侵扰。",h="达芙妮·斯迪威尔在西部荒野沿海悬崖顶上的一处偏僻果园里耕种，那里可以俯瞰长滩。她和丈夫乔丹一起逃离了北方的动乱，南下迁居至此。她在默默援助圣光教会的同时，还保护着自己的家园，抵御附近歹徒的侵扰。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","乔丹·斯迪威尔","长滩","果园","焚木村","影牙城堡","勇气之书","西部荒野"},ang={["class:Paladin"]="达芙妮·斯迪威尔是勇气之书试炼中的关键人物；保护她免受残酷的迪菲亚掠夺者的侵害，可以证明圣骑士保护无辜者的决心。",["faction:Alliance"]="斯迪威尔夫妇体现了流离失所的北方难民的困境，尽管西部荒野边境充满危险，他们依然继续为联盟和圣光教会服务。"},sec={{t="悬崖上的生活",b="达芙妮·斯迪威尔居住在月溪镇西侧及死亡矿井出口上方的峭壁之上，经营着一处与世隔绝的家园和苹果园。无论是在下方的长滩，还是在前往荆棘谷的狮鹫航线上，这座小农场看起来都宁静而不起眼。然而在如今的西部荒野，经营这样一处家园却绝非易事。尽管强盗和流浪的拾荒者不断逼近，达芙妮依然勤恳地照料着果树，守护着这一片属于她的孤立土地。"},{t="北方的难民",b="在定居西部荒野的丘陵之前，达芙妮和她的丈夫乔丹曾住在洛丹伦焚木村附近，在如今被称为影牙城堡的地方工作。当黑暗和灾难席卷该地区时，他们与其他成千上万的人类难民一起被驱赶向南。在暴风城的庇护下，乔丹精湛的锻造工艺和达芙妮坚定的支持使他们与圣光教会建立了紧密的联系，为白银之手骑士团的圣骑士们提供支援和圣洁的武器。"},{t="保卫农场",b="居住在离死亡矿井如此之近的地方，使达芙妮直接处于迪菲亚潜行者的威胁之下。当乔丹外出旅行或在首都外锻造圣器时，达芙妮常常独自守卫他们的沿海家园。每当强盗袭击农场寻求报复或掠夺时，达芙妮都会拿起武器，与大教堂派来的圣骑士们并肩作战，并在激战中展现出令人惊叹的勇猛和能力。"}},faq={{q="达芙妮·斯迪威尔是谁？",a="达芙妮·斯迪威尔是一位人类农场主，住在西部荒野长滩上方的一处偏僻农舍中。她是著名铁匠乔丹·斯迪威尔的妻子，两人曾一同逃离了遭受重创的北方王国。",al={"达芙妮是谁","达芙妮·斯迪威尔信息","斯迪威尔的妻子"}},{q="达芙妮来自哪里？",a="达芙妮先前住在北方的焚木村附近，并在如今被称为影牙城堡的地方工作，直到灾难迫使她和乔丹南下前往暴风城的领土。",al={"达芙妮的出身","达芙妮来自哪里","达芙妮是吉尔尼斯人吗"}},{q="为什么她的农场会遭到迪菲亚潜行者的袭击？",a="她的农场位于悬崖之上，直接俯瞰着西部荒野的南部水域，就在死亡矿井出口隧道的正上方。由于紧邻迪菲亚潜行者的据点，对于那些想要掠夺物资或清除碍事者的歹徒来说，这里是一个容易下手的目标。",al={"为什么迪菲亚攻击达芙妮","农场遭受迪菲亚袭击","斯迪威尔农场的强盗"}},{q="达芙妮与圣骑士有什么联系？",a="她的丈夫乔丹通过锻造圣洁的武器来援助圣光教会。作为勇气之书试炼的一部分，白银之手骑士团的圣骑士会被派往西部荒野，保护达芙妮免受强盗袭击。",al={"达芙妮的圣骑士任务","勇气之书达芙妮","为什么圣骑士要拜访达芙妮"}},{q="达芙妮能保护自己吗？",a="是的。当迪菲亚潜行者袭击她的果园时，她不会畏缩；她会拔出武器，与前来保卫家园的圣骑士们并肩作战。",al={"达芙妮会战斗吗","达芙妮是战士吗"}},{q="如何到达她的农舍？",a="她的农场位于西部荒野西南部，坐落在月溪镇西南方，靠近死亡矿井秘密港口的出口，俯瞰着长滩。",al={"达芙妮的农场在哪里","如何前往斯迪威尔农场","达芙妮·斯迪威尔的位置"}}},fp="15,208,20.344.0,21.442.0,18.356.1,23.186.0,27.166.0,51.220.1,40.185.0,26.121.0,31.150.0"}
P.entries["npc:darcy-parker"] = {n="达希",s="达希是Lakeshire Inn的一名服务员，负责为客人们提供酒水和热食。在赤脊山时刻笼罩的威胁阴影下，她始终保持乐观，尽心照顾着当地的保卫者——尤其是卫兵帕克。",h="达希是Lakeshire Inn的一名服务员，负责为客人们提供酒水和热食。在赤脊山时刻笼罩的威胁阴影下，她始终保持乐观，尽心照顾着当地的保卫者——尤其是卫兵帕克。",kw={"达希","卫兵帕克","湖畔镇","lakeshire inn","玛蒂·詹罗斯","赤脊山","服务员"},ang={["faction:Alliance"]="达希代表了湖畔镇坚韧的普通民众，在小镇等待暴风城援助的同时，她尽力鼓舞士气并让大家吃饱肚子。"},sec={{t="旅店里一张友好的面孔",b="在Lakeshire Inn忙碌的柜台后，达希日夜操劳，为镇上疲惫的民兵提供饮食。湖畔镇时刻面临着豺狼人和黑石兽人的威胁，使得这家旅店成为镇上仅存的几处温暖之地之一。达希非常关心驻扎在镇子周围的卫兵，经常招募路过的冒险者为驻守在边界的卫兵送去热食，或是帮忙跑腿。"},{t="哨所里的罗曼史",b="达希对卫兵帕克尤为关照，他经常在三角路口附近的道路上巡逻。达希深信他总是饿着肚子过度工作，因此经常让旅客带上午餐，好让他保持体力。她的爱慕并非无人察觉——达希对玛蒂·詹罗斯保持着警惕，她将此人视为争夺帕克青睐的嫉妒竞争者，让湖畔镇的防务成了这段朴实小镇恋情的背景。"}},faq={{q="达希是谁？",a="达希是赤脊山Lakeshire Inn内的一名人类服务员。她为镇上的保卫者准备食物，并经常请求路过的旅客帮忙将饭菜送到正在执勤的卫兵手中。",al={"达希是谁","达希 帕克 npc","湖畔镇服务员"}},{q="达希和卫兵帕克是什么关系？",a="达希对卫兵帕克怀有深切的爱慕。她特意为他准备新鲜午餐，并委托路过的旅客送去，以确保他在三角路口附近巡逻时不会挨饿。",al={"达希和卫兵帕克","卫兵帕克 达希","达希喜欢谁"}},{q="为什么达希会怀疑玛蒂·詹罗斯？",a="达希认为玛蒂·詹罗斯是个爱嫉妒的人，并将其视为争夺卫兵帕克注意力的恋爱竞争对手，这为镇上的日常生活增添了几分私人恩怨。",al={"达希和玛蒂","玛蒂·詹罗斯","达希的对手"}},{q="在哪里可以找到达希？",a="你可以在赤脊山止水湖北岸，位于湖畔镇中心的Lakeshire Inn里找到她，她正在那里为顾客服务。",al={"达希位置","达希在哪里","寻找达希"}}},fp="5,146,26.342.0,25.341.0,13.185.0,47.142.0,43.102.0,25.122.0"}
P.entries["npc:dark-cleric-beryl"] = {n="黑暗牧师贝里尔",s="黑暗牧师贝里尔是一位被遗忘者牧师训练师，驻扎在布瑞尔的恐惧之末旅店。他指引那些刚刚觉醒的亡灵牧师学习如何运用暗影魔法，并适应他们在黑暗女王统治下那全新的、邪恶的生存状态。",h="黑暗牧师贝里尔是一位被遗忘者牧师训练师，驻扎在布瑞尔的恐惧之末旅店。他指引那些刚刚觉醒的亡灵牧师学习如何运用暗影魔法，并适应他们在黑暗女王统治下那全新的、邪恶的生存状态。",kw={"贝里尔","布瑞尔","黑暗牧师贝里尔","被遗忘者牧师","恐惧之末旅店","牧师训练师","提瑞斯法林地"},ang={["class:Priest"]="对于冒险进入提瑞斯法林地的被遗忘者牧师来说，贝里尔是布瑞尔的一位重要导师，他提供关于如何操纵暗影魔法以及如何在向邪恶力量转化的艰难过程中生存下去的指导。",["race:Undead"]="贝里尔代表了被遗忘者对他们被诅咒的状态的适应，他们用实用的暗影韧性取代了洛丹伦过去信仰中盲目的虔诚。"},sec={{t="暗影中的指引",b="黑暗牧师贝里尔居住在布瑞尔的恐惧之末旅店楼上，通过指导新晋牧师为被遗忘者服务。贝里尔教导说，被遗忘者牧师的力量源于黑暗与阴影，但一个人在掌握黑暗之前，也必须了解圣光。他协助新生的修行者将注意力转向暗影和黑暗艺术，引导他们完成早期的试炼，例如制作他们的暗影法衣，并证明他们对这条新道路的忠诚。"}},faq={{q="黑暗牧师贝里尔是谁？",a="黑暗牧师贝里尔是一位被遗忘者牧师训练师，位于布瑞尔的恐惧之末旅店楼上。他指导新生的亡灵牧师扩展他们的法术，并拥抱暗影。",al={"贝里尔的角色","贝里尔是谁","黑暗牧师贝里尔背景故事"}},{q="我在哪里可以找到黑暗牧师贝里尔？",a="他位于提瑞斯法林地的布瑞尔镇内。你可以在恐惧之末旅店的楼上找到他。",al={"贝里尔的位置","贝里尔在哪里","寻找黑暗牧师贝里尔"}},{q="为什么被遗忘者牧师使用黑暗牧师这个头衔？",a="那些放弃了传统圣光教条或用更黑暗的学科来平衡圣光的被遗忘者牧师，会采用黑暗牧师的头衔。他们的教派教导说，被遗忘者是在腐化中锻造出来的，黑暗就是他们的家园，尽管牧师必须学会审慎地运用光与暗。",al={"什么是黑暗牧师","被遗忘者黑暗牧师","为什么叫黑暗牧师"}},{q="贝里尔提供什么任务？",a="贝里尔参与早期的被遗忘者牧师训练任务，包括“向黑暗致敬”和“暗影法衣”，这些任务教导年轻的侍僧如何帮助他们的盟友，并穿上适合暗影的法衣。",al={"贝里尔的任务","黑暗牧师贝里尔的任务"}}},fp="17,215,22.403.0,25.167.0,35.90.0,50.305.0,29.189.0"}
P.entries["npc:dark-iron-ambassador"] = {n="黑铁大师",s="黑铁大师是黑铁部族的一位使者，盘踞在诺莫瑞根深处。他的出现引发了人们对于该部族为何会对这座废弃的侏儒主城产生兴趣的质疑。",h="黑铁大师是黑铁部族的一位使者，盘踞在诺莫瑞根深处。他的出现引发了人们对于该部族为何会对这座废弃的侏儒主城产生兴趣的质疑。",kw={"阴谋","黑铁大师","黑铁部族","诺莫瑞根","超级钻机","索瑞森","麦克尼尔·瑟玛普拉格"},ang={["faction:Alliance"]="联盟调查员有理由彻查黑铁部族在诺莫瑞根的动向。",["race:Dwarf"]="一名黑铁矮人出现在这座废弃的侏儒城市，引起了铁炉堡盟友的关注。",["race:Gnome"]="一名出现在诺莫瑞根的黑铁使者为侏儒调查员们敲响了警钟。"},sec={{t="暗影特使",b="黑铁大师现身于受到辐射的诺莫瑞根的危险之中。他代表了黑铁部族，但其任务的具体目的尚不明确。"},{t="深渊中的阴谋",b="调查员和地精对黑铁部族在诺莫瑞根的动荡及其神秘超级钻机中的介入产生了怀疑。这些仍仅限于理论猜测；大师的出现并不能确证到底是谁导致了这座城市的陷落，也没有证据表明存在任何协议。"}},faq={{q="黑铁大师是谁？",a="他是潜伏在诺莫瑞根内部的一名黑铁部族使者。他具体的外交使命尚不为人所知。",al={"这个矮人是谁","黑铁大师身份","黑铁大师是什么"}},{q="为什么会有黑铁矮人出现在诺莫瑞根？",a="他的目的尚无定论。他的存在表明黑铁部族对诺莫瑞根怀有企图。",al={"为什么黑铁矮人在诺莫瑞根","他在这里做什么","黑铁矮人的目的"}},{q="黑铁部族是否导致了诺莫瑞根的陷落？",a="这一点尚无定论。调查员们提出过怀疑，但他们的理论并不能证明到底是谁引发了这场灾难。",al={"黑铁矮人是否导致了石腭怪入侵","黑铁阴谋","索瑞森是否帮助了瑟玛普拉格"}},{q="这位大师来自何处？",a="他隶属于黑铁部族，其统治者是达格兰·索瑞森大帝。",al={"大师来自哪里","谁派他来的","他为谁效力"}},{q="他是否与麦克尼尔·瑟玛普拉格结盟了？",a="人们怀疑双方存在结盟，但仅凭他的出现并不能确证任何协议。",al={"瑟玛普拉格的黑铁盟友","他是否与瑟玛普拉格是一伙的","与瑟玛普拉格共事"}},{q="可以在哪里找到黑铁大师？",a="他是一个难以捉摸的稀有遭遇，在诺莫瑞根地下城的受污染工程区和车间走廊中徘徊。",al={"大师刷新位置","他在哪里刷新","大师在诺莫瑞根的位置"}}},fp="20,165,15.120.0,24.273.1,32.113.0,43.92.0,53.108.0,36.69.0,40.71.0,44.129.0"}
P.entries["npc:darkmaster-gandling"] = {n="黑暗院长加丁",s="黑暗院长加丁是通灵学院凡人形态的院长，负责监管通灵教派招募的通灵师的教学与训练。他在凯尔达隆废墟要塞的深处运作，通过对生者与死者进行令人毛骨悚然的魔法实验来效忠于天灾军团。",h="黑暗院长加丁是通灵学院凡人形态的院长，负责监管通灵教派招募的通灵师的教学与训练。他在凯尔达隆废墟要塞的深处运作，通过对生者与死者进行令人毛骨悚然的魔法实验来效忠于天灾军团。",kw={"凯尔达隆","通灵教派","黑暗院长加丁","加丁","院长","通灵师","通灵学院"},ang={["class:Mage"]="加丁代表了达拉然学术传统的最终腐化，将学术严谨性扭曲成了一座令人恐惧的亡灵工厂。",["race:Undead"]="对于被遗忘者来说，加丁是一位可恨的天灾军团洗脑监督者，他将自由的灵魂束缚在凯尔达隆地下，使其永世为奴。"},sec={{t="院长的领地",b="在凯尔达隆地下的黑暗大厅中，黑暗院长加丁统治着通灵学院，这是天灾军团培养通灵师的首要学院。作为一名效力于通灵教派的人类，加丁曾与巫妖拉斯·霜语并肩工作，对从周边地区俘获的无数无辜受害者实施暴行。进入他课堂的学生会被教授如何酿造瘟疫、重新动画尸体以及血肉塑形。"},{t="圣物之主",b="加丁居住在院长书房的深处，掌管着被困在这座古老学校里的黑暗圣物与灵魂。他不仅施展毁灭性的奥术与暗影魔法，还结合禁忌的通灵术，诅咒入侵者并将他们通过暗影传送门抛入他书房周围的密室中，让他们在独自面对死而复生的亡灵时，加丁则保护自己免受伤害。"}},faq={{q="黑暗院长加丁是谁？",a="黑暗院长加丁是一位隶属于通灵教派的人类通灵师。他担任通灵学院的院长，管理这所黑暗学校并训练新的通灵师为巫妖王效力。",al={"加丁是谁","黑暗院长加丁背景故事","通灵学院首领"}},{q="加丁是亡灵还是活人？",a="尽管他精通死亡魔法并效忠于天灾军团，但加丁仍然是一个凡人。他领导着通灵学院内的凡人侍僧与教徒，甘愿为天灾军团效劳。",al={"加丁是亡灵吗","加丁还活着吗","加丁种族"}},{q="他与拉斯·霜语有什么关系？",a="拉斯·霜语曾是加丁的导师。这位人类院长与强大的巫妖共同主持了通灵学院的黑暗教学，并监督了在凯尔达隆发生的针对萨科夫一家等无辜灵魂的恐怖罪行。",al={"霜语与加丁","拉斯·霜语导师"}},{q="在哪里可以找到黑暗院长加丁？",a="加丁居住在通灵学院最底层的院长书房，可以通过达隆米尔湖下方的凯尔达隆地下墓穴进入。",al={"加丁位置","加丁在哪里","如何找到加丁"}}},fp="19,305,23.441.0,23.418.0,27.199.0,40.194.0,43.240.0,35.150.0"}
P.entries["npc:darn-talongrip"] = {n="达恩·鹰爪",s="达恩·鹰爪是一名驻扎在石爪山脉玛拉卡金附近的边境兽人侦察兵。他监视着崎岖山路中的当地威胁，并协助协调部落前哨基地与区域指挥官之间的联络。",h="达恩·鹰爪是一名驻扎在石爪山脉玛拉卡金附近的边境兽人侦察兵。他监视着崎岖山路中的当地威胁，并协助协调部落前哨基地与区域指挥官之间的联络。",kw={"达恩·鹰爪","卡德拉克","玛拉卡金","兽人侦察兵","石爪山脉"},ang={["faction:Horde"]="达恩·鹰爪在进入石爪山脉的上坡路沿途进行早期警戒，是刚从贫瘠之地前来的部落冒险者们的重要联络人。",["race:Orc"]="像许多兽人侦察兵一样，达恩欣然接受了边境的艰苦条件，在嶙峋的岩石和充满敌意的野生生物中站岗放哨。"},sec={{t="石爪山脉前线侦察兵",b="达恩·鹰爪监视着从南贫瘠之地进入石爪山脉的崎岖上坡路。他驻扎在玛拉卡金定居点，指挥新兵前往部落在灰谷的新前线。他的哨位是旅行者向上攀登进入争夺激烈的山峰时的第一道联络线。"},{t="指挥部的耳目",b="从他在玛拉卡金的岗位出发，达恩确保情报和前线报告能够送达关键的指挥官手中，例如北贫瘠之地瞭望塔的卡德拉克。这些山脉中的偏远营地一直处于高压之下，这使得达恩作为哨兵和信使的角色对于让部落先锋队保持信息通畅至关重要。"}},faq={{q="达恩·鹰爪是谁？",a="达恩·鹰爪是一名驻扎在石爪山脉南部玛拉卡金的兽人侦察兵。",al={"达恩·鹰爪是谁","达恩·鹰爪的身份","这名兽人是谁"}},{q="在哪里可以找到达恩·鹰爪？",a="他位于石爪山脉的巨魔定居点玛拉卡金。",al={"达恩·鹰爪的位置","达恩·鹰爪在哪里","达恩·鹰爪的坐标"}},{q="他在石爪山脉的角色是什么？",a="达恩指挥新兵前往北贫瘠之地的卡德拉克处，以帮助保卫部落在灰谷的前哨基地。",al={"达恩·鹰爪的作用","达恩·鹰爪的目的"}},{q="卡德拉克是谁，为什么达恩要把旅行者派往那里？",a="卡德拉克是驻扎在北贫瘠之地瞭望塔的部落指挥官，负责领导部落在灰谷的战役。达恩指挥新兵前往他那里，以帮助保卫部落在灰谷的新前线。",al={"卡德拉克是谁","向卡德拉克汇报"}}},fp="14,170,28.244.0,20.273.0,22.89.0,34.95.0,31.105.0,55.183.0"}
P.entries["npc:darsok-swiftdagger"] = {n="达索克·快刀",s="达索克·快刀是一名兽人战士和侦察兵，驻扎在贫瘠之地的中心地带十字路口。他以对鹰身人的刻骨仇恨而闻名，他指引部落的冒险者前往北部的无水岭，去铲除那些骚扰旅行者和定居点的鹰身人母系社会。他同时也是玛拉卡金的巫医金吉尔的老朋友。",h="达索克·快刀是一名兽人战士和侦察兵，驻扎在贫瘠之地的中心地带十字路口。他以对鹰身人的刻骨仇恨而闻名，他指引部落的冒险者前往北部的无水岭，去铲除那些骚扰旅行者和定居点的鹰身人母系社会。他同时也是玛拉卡金的巫医金吉尔的老朋友...",kw={"贫瘠之地","血羽","十字路口","达索克","鹰身人","金吉尔","塞瑞娜","快刀","索克","巫翼"},ang={["class:Rogue"]="正如“快刀”这个名字一样，达索克偏好对敌方首领进行精确的致命斩首打击，而不是消磨式的消耗战。",["faction:Horde"]="对于部落旅行者来说，达索克提供了关键的早期战术任务，以确保十字路口的贸易路线免受空中伏击。",["race:Orc"]="达索克体现了负责驯服并保卫卡利姆多危险边境的兽人那种专注的武者心态。"},sec={{t="十字路口的守望者",b="在十字路口这个繁忙的枢纽中，达索克·快刀时刻警惕着从北部灌木丛中蔓延出的威胁。连接杜隆塔尔、莫高雷和北部地区的贸易动脉正受到不断的围攻，不仅来自强盗和半人马，还来自有组织的空中猎手。达索克将他的怒火集中在巫翼鹰身人身上，这些盘踞在遗忘之池西北方无水岭的鹰身人直接威胁着北部的商队。"},{t="对抗巫翼的战争",b="达索克不仅仅是在保卫道路；他还会协调针对鹰身人领地的精确打击。他的行动始于削弱极具侵略性的鹰身人突袭者，随后派遣身经百战的战士去处决她们的副官，并最终取下她们的女族长——塞瑞娜·血羽的首级。通过系统地瓦解她们的领导层，快刀的目标是让这些掠夺成性的群体分崩离析，溃散在山脊之间。"},{t="灌木丛中的羁绊",b="虽然他当下的职责主要集中在消灭鹰身人上，但达索克·快刀在西北方远处的石爪山脉还有一位老朋友：住在玛拉卡金的巨魔巫医金吉尔，那里正是鹰身人的发源地。达索克给金吉尔寄去了一封信，通报了关于鹰身人作战的消息，尽管他们二人已经多年没有联系了。"}},faq={{q="达索克·快刀在哪里？",a="达索克·快刀驻扎在贫瘠之地中部的部落据点十字路口。他随时准备指引过往的旅客去面对北方的威胁。",al={"达索克位置","达索克·快刀在哪里","找到达索克","达索克·快刀地点"}},{q="达索克为什么要猎杀鹰身人？",a="巫翼鹰身人在遗忘之池西北方的峡谷中筑巢，对在贫瘠之地北部小径上行进的部落商队、旅行者和侦察兵构成了持续的掠夺威胁。",al={"为什么要杀鹰身人","达索克与鹰身人的仇恨","贫瘠之地的巫翼鹰身人"}},{q="塞瑞娜·血羽是谁？",a="塞瑞娜·血羽是统治无水岭巫翼鹰身人的残忍女族长。达索克委托冒险者去击杀她，以粉碎鹰身人群体的凝聚力和指挥体系。",al={"塞瑞娜·血羽","贫瘠之地的鹰身人首领","巫翼领袖"}},{q="达索克与巫医金吉尔有什么联系？",a="居住在石爪山脉玛拉卡金的巨魔巫医金吉尔是达索克的老友。达索克派一名旅人给他送信，这是他多年来第一次与金吉尔联系。",al={"金吉尔的信","达索克和金吉尔","巫医金吉尔的关系"}},{q="达索克是向塞格拉·黑刺还是索克汇报工作？",a="达索克在十字路口组织他的鹰身人作战行动。没有任何经典旧世的资料说明塞格拉·黑刺或索克是他的直接上级。",al={"达索克 索克","达索克听命于谁","十字路口领导层"}},{q="巫翼鹰身人在哪里筑巢？",a="巫翼鹰身人在无水岭筑巢，那是一系列位于贫瘠之地北部边缘、遗忘之池西北方的崎岖峡谷和悬崖。",al={"巫翼位置","无水岭的鹰身人","去哪里找贫瘠之地的鹰身人"}}},fp="18,271,27.375.0,24.292.1,24.287.0,36.145.0,30.153.0,27.132.0,52.215.0,48.135.0,36.129.0"}
P.entries["npc:daryl-the-youngling"] = {n="年轻的达瑞尔",s="年轻的达瑞尔是一位居住在洛克莫丹东南部山丘旅行者营地的人类猎人。他渴望在资深的矮人追踪者面前证明自己的射术，于是向过往的冒险者发起挑战，以磨练他们的野外生存技巧并测试他们对抗当地野兽的勇气。",h="年轻的达瑞尔是一位居住在洛克莫丹东南部山丘旅行者营地的人类猎人。他渴望在资深的矮人追踪者面前证明自己的射术，于是向过往的冒险者发起挑战，以磨练他们的野外生存技巧并测试他们对抗当地野兽的勇气。",kw={"野猪狩猎","达瑞尔","旅行者营地","猎人","猎人的吹嘘","洛克莫丹","年轻的"},ang={["class:Hunter"]="达瑞尔精通追踪、野兽习性和狩猎的门道，这使得他的竞赛成为造访旅行者营地的游历猎人们绝佳的试炼场。",["race:Human"]="在矮人领地的深处发现一个学习野外技艺的年轻人类，这凸显了铁炉堡与人类王国之间建立的务实情谊。"},sec={{t="登山者中的人类",b="旅行者营地主要是矮人登山者、追踪者和经验丰富的户外生存专家的避风港，他们负责守卫洛克莫丹的荒野。年轻的达瑞尔作为一名人类，努力想要在这些资深猎人中争得一席之地，显得尤为引人注目。他并不依靠虚张声势，而是主动寻求与其他的旅行者切磋狩猎本能，向他们发起挑战，去猎杀漫游在岩壁和湖岸边那些强壮的野猪与野兽。"}},faq={{q="年轻的达瑞尔是谁？",a="达瑞尔是一位驻扎在洛克莫丹旅行者营地的年轻人类猎人。他被那些饱经风霜的矮人射手所环绕，通过狩猎比赛来测试新人的能力，以证明他们对付野兽和追踪目标的技巧。",al={"达瑞尔是谁","达瑞尔背景故事","年轻的达瑞尔是谁"}},{q="在哪里可以找到达瑞尔？",a="达瑞尔待在旅行者营地，该营地位于俯瞰洛克莫丹湖东南部湖岸的森林悬崖上。",al={"达瑞尔位置","年轻的达瑞尔在哪里","哪里可以找到达瑞尔"}},{q="为什么他被称为“年轻的”？",a="与那些已经在卡兹莫丹崎岖荒野中巡逻了数十年的矮人射手和营地常客相比，达瑞尔相对年轻且缺乏历练，他仍在努力建立自己作为一名真正猎人的长久声望。",al={"为什么叫年轻的","达瑞尔绰号"}}},fp="19,178,26.266.0,27.176.0,25.91.0,33.193.0"}
P.entries["npc:dashel-stonefist"] = {n="达舍尔·石拳",s="达舍尔·石拳是一位臭名昭著的矮人斗殴者，经常在暴风城的Old Town阴暗小巷里游荡。他因为脾气火爆、拳头沉重而被称为“铁拳”，是城里混乱地下世界的老熟人。在他那流氓般的外表下，隐藏着危险的勾当，引起了秘密调查员的注意。",h="达舍尔·石拳是一位臭名昭著的矮人斗殴者，经常在暴风城的Old Town阴暗小巷里游荡。他因为脾气火爆、拳头沉重而被称为“铁拳”，是城里混乱地下世界的老熟人。在他那流氓般的外表下，隐藏着危险的勾当，引起了秘密调查员的注意。",kw={"斗殴者","达舍尔","迪菲亚","铁拳","失踪的外交官","old town","石拳","暴风城"},ang={["class:Rogue"]="对于在Old Town犯罪网络中穿梭的盗贼来说，达舍尔是一个当被敲碎下巴后就会说漏嘴的行动者的典型案例——这是一个关于不要信任只会用蛮力的粗人来处理敏感秘密的警示。",["faction:Alliance"]="达舍尔代表了暴风城首都内部的静悄悄的腐烂，证明了迪菲亚潜行者的触角已经延伸到了西部荒野的农场之外，直抵这座君主制城市。",["race:Dwarf"]="虽然暴风城的许多铁炉堡矮人担任着受人尊敬的铁匠、山地探险者或使节，但石拳表明，矮人同样容易堕落为街头流氓和叛徒。"},sec={{t="Old Town的一名斗殴者",b="达舍尔·石拳躲在Old Town狭窄的鹅卵石后巷里，看起来就像任何其他喝醉了酒、喜欢找茬打架的矮人。当地人和城市守卫只知道他叫“铁拳”，这个绰号是他通过无数次酒馆门外的街头斗殴得来的。然而，达舍尔远不止是个简单的酒馆打手；他在Old Town的存在使他处于暴风城地下世界的枢纽位置，走私者、扒手和政治煽动者在这里交易钱财和流言，避开Cathedral Square探听的目光。"},{t="外交官失踪事件",b="当一名高级外交官在一次秘密出国航行中失踪时，秘密皇家调查员追踪到了直指达舍尔的背叛传言。石拳是迪菲亚潜行者在暴风城围墙内的街头联络人，掌握着关于绑架案的关键情报。达舍尔并非乐于合作的线人，他拒绝开口，直到被打得屈服，才透露出这起阴谋涉及王国政治的程度远比单纯的绑架要深得多。"}},faq={{q="达舍尔·石拳是谁？",a="达舍尔·石拳是一名居住在暴风城Old Town的矮人。他因暴力的名声和斗殴的习惯而被称为“铁拳”，是潜伏在首都阴影区域的一名底层恶棍和线人。",al={"达舍尔是谁","铁拳是谁","达舍尔·石拳背景故事"}},{q="我可以在哪里找到达舍尔·石拳？",a="他可以在暴风城的Old Town户外找到，躲在靠近城里盗贼和战士出没地的后巷中。",al={"达舍尔位置","达舍尔·石拳在哪里","寻找达舍尔"}},{q="为什么调查员需要与他战斗？",a="在对失踪皇家外交官的调查中，线索直接指向达舍尔是同谋。因为他对他的阴暗雇主极其忠诚，且只屈服于武力，调查员必须在赤手空拳的决斗中击败他，他才会吐露实情。",al={"为什么攻击达舍尔","制服达舍尔·石拳","与达舍尔战斗"}},{q="他与迪菲亚潜行者有什么联系？",a="达舍尔作为迪菲亚潜行者在暴风城内的内部行动人员和信使进行活动。他帮助协调当地联络人和街头打手，以使迪菲亚潜行者的计划不被城市守卫发现。",al={"达舍尔是迪菲亚吗","达舍尔·石拳迪菲亚","暴风城的迪菲亚"}},{q="与达舍尔有关的那位失踪外交官是谁？",a="皇家特工所追查的官方故事涉及一名在前往塞拉摩途中失踪的匿名外交官。",al={"失踪的外交官是谁","失踪的外交官任务线","瓦里安国王失踪"}},{q="达舍尔与其他已知的矮人有亲属关系吗？",a="没有关于达舍尔亲属的记录。他在暴风城的犯罪勾当使他与声誉良好的矮人社会分道扬镳。",al={"泰尔达·石拳亲属","达舍尔·石拳家人","石拳家族"}}},fp="16,209,21.350.0,28.373.1,24.188.0,34.114.0,39.225.1,49.201.1,48.88.2,45.123.0"}
P.entries["npc:david-trias"] = {n="大卫·提亚斯",s="大卫·提亚斯是驻扎在丧钟镇的被遗忘者潜行者训练师。他教导刚刚苏醒的亡灵学习潜行、诡计和刀锋的艺术，以辅佐希尔瓦娜斯女王和被遗忘者。",h="大卫·提亚斯是驻扎在丧钟镇的被遗忘者潜行者训练师。他教导刚刚苏醒的亡灵学习潜行、诡计和刀锋的艺术，以辅佐希尔瓦娜斯女王和被遗忘者。",kw={"大卫·提亚斯","丧钟镇","埃林·提亚斯","密文卷轴","被遗忘者","潜行者训练师","提瑞斯法林地"},ang={["class:Rogue"]="对于被遗忘者潜行者来说，大卫·提亚斯是你的第一位导师，他会帮你破译秘密卷轴，并教你如何将亡灵冰冷的精确感转化为致命的刀锋技巧。",["race:Undead"]="大卫·提亚斯代表了被遗忘者严酷的现实：洛丹伦曾经的人类，其过去的生活和血统已被瘟疫切断，如今被重塑为服务于希尔瓦娜斯女王。"},sec={{t="影中指引",b="大卫·提亚斯位于丧钟镇的墓碑与废墟之间，他的任务是甄别并训练那些具有暗杀天赋的新生亡灵。对于羽翼未丰的被遗忘者来说，生存不仅需要强大的武力，更需要来自暗影的精确打击。提亚斯负责破译密令，并教导新手如何使用匕首、隐藏行踪，以及将他们复生后的本能转化为对活人和天灾军团的致命精确打击。"},{t="一个熟悉的名字",b="“提亚斯”这个姓氏在大陆各地有着奇特的共鸣。在遥远南方的暴风城里，有一位名为埃林·提亚斯的知名奶酪商人，他私下里与潜行者大师和间谍头目有着深厚的联系。大卫和埃林虽然同姓，但尚未证实他们之间有任何血缘关系。"}},faq={{q="大卫·提亚斯是谁？",a="大卫·提亚斯是一位被遗忘者潜行者训练师，可以在提瑞斯法林地的丧钟镇找到他。他负责向新苏醒的被遗忘者潜行者传授基础战斗技巧，并发布他们的第一个秘密任务。",al={"大卫·提亚斯","大卫·提亚斯是谁","丧钟镇潜行者训练师"}},{q="我可以在哪里找到大卫·提亚斯？",a="他位于提瑞斯法林地的丧钟镇，那是被遗忘者的出生地。他站在定居点的建筑附近，协助新苏醒的亡灵。",al={"大卫·提亚斯位置","大卫·提亚斯在哪里","丧钟镇潜行者训练师"}},{q="大卫·提亚斯和暴风城的埃林·提亚斯有亲戚关系吗？",a="他和暴风城的埃林·提亚斯同姓，但尚未证实有任何家庭联系。",al={"埃林·提亚斯关系","提亚斯家族","他和埃林·提亚斯有亲戚关系吗"}},{q="他在被遗忘者的训练中扮演什么角色？",a="从丧钟镇墓穴中走出的潜行者新手会被指引去寻找大卫·提亚斯，并带去一份密文卷轴。他负责解读指示、指导基础训练，并引导他们走上成为被遗忘者潜行特工的道路。",al={"大卫·提亚斯任务","密文卷轴","他传授什么"}}},fp="11,147,24.425.0,15.220.1,19.172.0,29.155.0,52.101.0,44.197.0"}
P.entries["npc:dawnwatcher-selgorm"] = {n="哨兵塞尔高姆",s="哨兵塞尔高姆是银色黎明的一名人类代表，驻扎在达纳苏斯的工匠区。作为暗夜精灵主城的一名观察员和联络人，他负责监测有关邪教活动和在卡利姆多北部涌动的黑暗威胁的报告。",h="哨兵塞尔高姆是银色黎明的一名人类代表，驻扎在达纳苏斯的工匠区。作为暗夜精灵主城的一名观察员和联络人，他负责监测有关邪教活动和在卡利姆多北部涌动的黑暗威胁的报告。",kw={"银色黎明","黑暗深渊","黑暗深渊的邪恶","工匠区","达纳苏斯","哨兵塞尔高姆","暮光之锤"},ang={["faction:Alliance"]="对于探索卡利姆多北部的联盟冒险者来说，塞尔高姆是连接达纳苏斯与对抗海岸沿线潜藏邪教远征之间的重要桥梁。",["race:Human"]="前往泰达希尔偏远枝干旅行的人类游客，在遇到一位服务于高尚的银色黎明的同胞时，或许会感到一丝慰藉。"},sec={{t="世界之树的注视",b="尽管银色黎明主要致力于消除东瘟疫之地肆虐的亡灵天灾，但他们的警惕性延伸到了任何古老邪恶扎根的地方。哨兵塞尔高姆在达纳苏斯守望，架起了封闭的暗夜精灵与更广泛的对抗邪恶的远征之间的桥梁。他从工匠区收集有关卡利姆多荒野中新出现的威胁的情报，并招募有能力的联盟旅者，以便在邪教徒和黑暗力量的影响腐蚀整个世界之前给予他们打击。"},{t="对抗黑暗的打击",b="塞尔高姆首要关注的是位于灰谷佐拉姆海岸的黑暗深渊。他洞察到了暮光之锤教派与波涛之下的蛇形纳迦之间那邪恶的勾结，并以此奖励那些冒险进入淹没废墟的资深勇士。通过打击该教派邪恶的首领并回收被污染的圣物，他希望能平息那些威胁着卡利姆多神圣海岸的日益增长的阴影。"}},faq={{q="谁是哨兵塞尔高姆？",a="哨兵塞尔高姆是银色黎明的一名人类特工。他驻扎在暗夜精灵主城达纳苏斯，以防范卡利姆多各地不断逼近的邪恶。",al={"塞尔高姆","谁是塞尔高姆","哨兵塞尔高姆背景故事"}},{q="哨兵塞尔高姆在哪里？",a="他就站在达纳苏斯工匠区的户外，俯瞰着这座暗夜精灵主城熙熙攘攘的工坊。",al={"塞尔高姆位置","塞尔高姆在哪里","塞尔高姆 达纳苏斯"}},{q="为什么银色黎明的成员会驻扎在达纳苏斯？",a="虽然银色黎明因在洛丹伦对抗天灾军团而闻名，但该组织致力于铲除各地的邪恶。塞尔高姆负责监测卡利姆多北部日益增长的邪教活动，例如暮光之锤。",al={"达纳苏斯的银色黎明","为什么银色黎明在这里"}},{q="塞尔高姆要求冒险者做什么？",a="塞尔高姆等待着从灰谷黑暗深渊归来的联盟英雄，他们需要带回梦游者克尔里斯（当地暮光之锤的首领）的头颅。受伤的银月守卫塞尔瑞德敦促他们杀死这个首领，以阻止该教派的腐化蔓延。",al={"塞尔高姆的任务","黑暗深渊的邪恶任务发布者"}}},fp="19,269,22.445.0,25.351.1,27.126.0,39.131.0,52.203.0,40.258.0"}
P.entries["npc:dawnwatcher-shaedlass"] = {n="哨兵山德拉斯",s="哨兵山德拉斯是一位效力于银色黎明的暗夜精灵，驻扎在达纳苏斯的工匠区。作为银色黎明在卡利姆多的情报人员，他时刻关注着那些被派往危险地区执行侦察任务的同僚们的消息。",h="哨兵山德拉斯是一位效力于银色黎明的暗夜精灵，驻扎在达纳苏斯的工匠区。作为银色黎明在卡利姆多的情报人员，他时刻关注着那些被派往危险地区执行侦察任务的同僚们的消息。",kw={"银色黎明","黑暗深渊","工匠区","达纳苏斯","哨兵","山德拉斯","塞尔瑞德"},ang={["faction:Alliance"]="山德拉斯为身处达纳苏斯的联盟英雄们提供了一条通往黑暗深渊谜团的直接线索，并派出侦察兵去营救敌后深处的盟友。",["race:NightElf"]="作为少数公开在银色黎明旗帜下效力的暗夜精灵之一，山德拉斯架起了泰达希尔封闭的政治环境与全球反抗黑暗监视之间的桥梁。"},sec={{t="银色黎明之眼",b="尽管银色黎明最出名的事迹是在东瘟疫之地对天灾军团发起的艰苦远征，但他们的警惕范围远不止洛丹伦。哨兵山德拉斯驻守在暗夜精灵主城达纳苏斯，负责守护该组织在卡利姆多的利益。他在工匠区的安静岗位上，密切监视着针对那些威胁整个世界的黑暗邪教和腐化势力的秘密行动。"},{t="失踪的兄弟",b="山德拉斯目前最担心的是银月守卫塞尔瑞德的下落。作为他的同志，塞尔瑞德此前被派往南方，调查有关灰谷海岸黑暗深渊中潜藏邪教活动的报告。山德拉斯担心塞尔瑞德可能遭遇了暮光之锤教徒和那座古老精灵神庙中水底恐怖生物的毒手，因此他积极招募勇敢的联盟冒险者潜入遗迹，查明这位侦察兵的命运。"}},faq={{q="谁是哨兵山德拉斯？",a="哨兵山德拉斯是银色黎明的一位暗夜精灵特工。他驻扎在达纳苏斯的工匠区，担任该组织在卡利姆多北部行动的联络人和接头人。",al={"谁是山德拉斯","哨兵山德拉斯背景故事","银色黎明达纳苏斯npc"}},{q="为什么会有银色黎明的成员出现在达纳苏斯？",a="尽管银色黎明的战场主要在洛丹伦对抗天灾军团，但他们也在艾泽拉斯各地保留了警惕的特工，以追踪腐化邪恶。山德拉斯负责协调情报，并监控在卡利姆多各地滋生的威胁，包括那些隐秘的邪教。",al={"为什么银色黎明在达纳苏斯","银色黎明暗夜精灵"}},{q="山德拉斯要求冒险者做什么？",a="山德拉斯会派遣联盟冒险者进入黑暗深渊的沉没神庙，执行“寻找塞尔瑞德”的任务。他要求冒险者找到银月守卫塞尔瑞德，这位潜入遗迹调查暮光之锤的侦察兵至今音讯全无。",al={"山德拉斯任务","寻找塞尔瑞德任务"}},{q="我在哪里可以找到哨兵山德拉斯？",a="他在达纳苏斯的工匠区，就在主城的贸易商和工匠附近。",al={"山德拉斯位置","哨兵山德拉斯在哪里"}}},fp="21,185,23.347.0,17.341.1,29.171.0,42.162.0,42.200.0,39.113.0"}
P.entries["npc:dazalar"] = {n="达扎拉",s="达扎拉是一名暗夜精灵猎人训练师，驻扎在泰达希尔的多兰纳尔。他引导初出茅庐的哨兵和斥候，帮助他们磨练箭术，并学习与这片巨木之地的野兽建立羁绊的神圣艺术。",h="达扎拉是一名暗夜精灵猎人训练师，驻扎在泰达希尔的多兰纳尔。他引导初出茅庐的哨兵和斥候，帮助他们磨练箭术，并学习与这片巨木之地的野兽建立羁绊的神圣艺术。",kw={"达扎拉","多兰纳尔","猎人","暗夜精灵","taming the beast","泰达希尔","猎人之道","训练师"},ang={["class:Hunter"]="达扎拉是暗夜精灵猎人最早接触的导师之一，他引导他们完成野兽控制和宠物训练的基础试炼。",["race:NightElf"]="他坚守着卡多雷哨兵和斥候的传统，教导年轻的暗夜精灵如何与大自然中凶猛的掠食者保持平衡相处。"},sec={{t="多兰纳尔营地",b="达扎拉身处多兰纳尔定居点，是年轻猎人们在离开幽影谷的庇护之后，所接触到的主要导师。暗夜精灵社会非常依赖游侠和哨兵来巡逻荒野，达扎拉致力于确保新人们具备保护泰达希尔脆弱生态系统所需的纪律与耐心。"},{t="与野性建立羁绊",b="在达扎拉的指导下，一个至关重要的成人仪式就是学习驯服并照料野兽。卡多雷的方式并非通过蛮力迫使生物屈服于猎人的意志，而是强调与夜刃豹、猫头鹰和鸮兽等森林掠食者建立互信契约，训练它们学会尊重并与主人并肩作战。"}},faq={{q="谁是达扎拉？",a="达扎拉是一名暗夜精灵猎人训练师，位于泰达希尔的多兰纳尔村。他教授新手猎人新的战斗技能，并指导他们驯服野兽的方法。",al={"谁是达扎拉","达扎拉背景故事","达扎拉身份"}},{q="我在哪里可以找到达扎拉？",a="他驻扎在多兰纳尔的户外，这是泰达希尔的中心枢纽，冒险者在离开幽影谷的新手区后不久便会抵达此处。",al={"达扎拉位置","达扎拉在哪里","多兰纳尔猎人训练师"}},{q="达扎拉提供什么样的训练？",a="达扎拉教授适合进阶猎人的各种远程攻击、陷阱和生存技巧，并派遣新手通过试炼来掌握驯服荒野动物的本领。",al={"达扎拉教授什么","达扎拉技能","达扎拉猎人训练"}},{q="达扎拉提供特殊任务吗？",a="是的，达扎拉提供关键的猎人训练任务，包括“猎人之道”、多阶段试炼“Taming the Beast”以及“Training the Beast”，这些任务教会年轻猎人如何与动物伙伴建立联系并进行照料。",al={"达扎拉任务","多兰纳尔猎人任务","taming the beast任务"}},{q="为什么暗夜精灵如此依赖猎人？",a="几千年来，卡多雷一直与卡利姆多古老的森林和谐共处。弓箭手和斥候构成了哨兵部队的中坚力量，他们利用潜行、箭术和动物盟友的力量来保卫家园，同时不破坏自然环境。",al={"暗夜精灵猎人背景","为什么哨兵使用猎人","卡多雷猎人"}},{q="达扎拉会派遣猎人去驯服什么样的野兽？",a="他指引猎人追踪泰达希尔本土的动物，包括当地的蜘蛛、夜刃豹和猛禽，以此考验猎人接近并安抚野生掠食者的能力。",al={"驯服什么野兽","多兰纳尔驯服试炼","在泰达希尔驯服野兽"}}},fp="7,160,23.227.0,21.226.0,15.102.0,25.102.0,35.141.0,38.202.0,46.236.0,54.181.0"}
P.entries["npc:deathguard-bartholomew"] = {n="亡灵卫兵巴塞洛缪",s="亡灵卫兵巴塞洛缪是一名驻扎在布瑞尔的警惕的被遗忘者士兵。他的任务是维护提瑞斯法林地的治安，他帮助旅行者在这一荒废的定居点中穿行，并协助在当地守卫中执行纪律。",h="亡灵卫兵巴塞洛缪是一名驻扎在布瑞尔的警惕的被遗忘者士兵。他的任务是维护提瑞斯法林地的治安，他帮助旅行者在这一荒废的定居点中穿行，并协助在当地守卫中执行纪律。",kw={"巴塞洛缪","布瑞尔","亡灵卫兵","被遗忘者","卫兵","提瑞斯法"},ang={["faction:Horde"]="从卡利姆多远道而来的盟友可以依靠巴塞洛缪，在布瑞尔雾气缭绕的街道上找到方向。",["race:Undead"]="对于从丧钟镇走出的新解放的被遗忘者来说，像布瑞尔的巴塞洛缪这样的卫兵是他们见到的希尔瓦娜斯女王常备军的第一张有组织的脸孔。"},sec={{t="布瑞尔哨兵",b="亡灵卫兵巴塞洛缪在布瑞尔定居点站岗，代表了被遗忘者坚定的军事中坚力量。正如他遍布提瑞斯法林地的亡灵卫兵同僚一样，他保卫着这片收复的领土，抵御残留的天灾军团、狂热的血色十字军以及任何对希尔瓦娜斯女王领地的其他威胁。除了站岗，他还为试图在镇内设施间穿行的旅行者提供指引，并参与维护新生者之间的秩序。"}},faq={{q="亡灵卫兵巴塞洛缪是谁？",a="亡灵卫兵巴塞洛缪是一名驻扎在提瑞斯法林地布瑞尔的被遗忘者卫兵。他作为守卫守护着这座城镇，并为过路人指引兴趣点。",al={"巴塞洛缪","巴塞洛缪是谁","亡灵卫兵巴塞洛缪背景故事"}},{q="亡灵卫兵的角色是什么？",a="亡灵卫兵是被遗忘者的主要步兵和防御力量。他们巡逻洛丹伦的领土，保卫像布瑞尔这样的定居点免受天灾军团和血色十字军的侵扰，并代表黑暗女王维护秩序。",al={"什么是亡灵卫兵","亡灵卫兵阵营","被遗忘者卫兵"}},{q="亡灵卫兵巴塞洛缪可以指路吗？",a="可以。正如艾泽拉斯各地的许多城镇哨兵一样，巴塞洛缪可以指引旅行者前往布瑞尔各处的必要设施，包括训练师、旅店和专业技能商人。",al={"旅店在哪里","布瑞尔路线指引","卫兵布瑞尔指引"}}},fp="22,163,17.336.0,30.130.0,35.190.0,43.125.0"}
P.entries["npc:deathguard-burgess"] = {n="亡灵卫兵伯吉斯",s="亡灵卫兵伯吉斯是驻扎在提瑞斯法林地布瑞尔镇的一名被遗忘者哨兵。他守护着这座定居点，维持秩序并为旅客指引前往村庄各处重要设施的方向。",h="亡灵卫兵伯吉斯是驻扎在提瑞斯法林地布瑞尔镇的一名被遗忘者哨兵。他守护着这座定居点，维持秩序并为旅客指引前往村庄各处重要设施的方向。",kw={"布瑞尔","伯吉斯","亡灵卫兵伯吉斯","被遗忘者","卫兵","提瑞斯法林地"},ang={["faction:Horde"]="来自卡利姆多的盟友在寻找补给商或在旅店休息时，可以与伯吉斯交谈，以便在布瑞尔这种陌生且枯萎的环境中导航。",["race:Undead"]="对于刚从丧钟镇离开的觉醒被遗忘者来说，布瑞尔的伯吉斯这类卫兵将为你提供关于洛丹伦更广阔的基础设施的初步指引。"},sec={{t="布瑞尔的守卫",b="亡灵卫兵伯吉斯位于幽暗城以北的布瑞尔定居点，担任城镇卫兵，负责维护治安以抵御天灾军团和血色十字军。像提瑞斯法林地各处的其他亡灵卫兵一样，伯吉斯会为新来的被遗忘者指引方向，帮助他们找到当地的商人、职业训练师和公共服务设施，确保这个脆弱的前哨站能够正常运作。"}},faq={{q="亡灵卫兵伯吉斯是谁？",a="亡灵卫兵伯吉斯是效忠于被遗忘者、驻守在布瑞尔镇的一名亡灵哨兵。他帮助维持村庄的秩序，并为访客指引当地训练师和地标的位置。",al={"伯吉斯 布瑞尔","伯吉斯是谁","亡灵卫兵伯吉斯背景故事"}},{q="亡灵卫兵在布瑞尔担任什么职责？",a="亡灵卫兵是被遗忘者的标准军队和治安力量。在布瑞尔这样的地方，他们保护当地居民免受天灾军团和血色十字军等外部威胁的侵害，同时维护社会秩序。",al={"什么是亡灵卫兵","亡灵卫兵的职责"}},{q="亡灵卫兵伯吉斯能提供指引吗？",a="是的。和艾泽拉斯各地的许多城镇卫兵一样，与伯吉斯交谈可以让旅客询问职业训练师、旅店、专业训练师以及布瑞尔其他重要设施的位置。",al={"伯吉斯指引","布瑞尔去哪"}}},fp="18,149,19.269.0,26.132.0,44.106.0,42.122.0"}
P.entries["npc:deathguard-dillinger"] = {n="亡灵卫兵迪林格尔",s="亡灵卫兵迪林格尔是驻扎在提瑞斯法林地布瑞尔的一名被遗忘者哨兵。他守卫着城镇的边界，引导新到达的亡灵前往必要的设施，并指派新兵阻击当地残余的天灾军团。",h="亡灵卫兵迪林格尔是驻扎在提瑞斯法林地布瑞尔的一名被遗忘者哨兵。他守卫着城镇的边界，引导新到达的亡灵前往必要的设施，并指派新兵阻击当地残余的天灾军团。",kw={"腐烂的任务","布瑞尔","死亡卫士","亡灵卫兵迪林格尔","迪林格尔","磨坊沦陷","提瑞斯法林地","切肉者乌拉格"},ang={["class:Warrior"]="渴望成为被遗忘者战士的人经常直接与迪林格尔共事，在布瑞尔郊外游荡的凶猛食尸鬼和骷髅怪身上磨练他们的战斗技巧。",["faction:Horde"]="迪林格尔代表了被遗忘者在洛丹伦北部开辟稳固立足点的艰苦奋斗，向部落盟友展示了家门口的无脑天灾所带来的持续威胁。",["race:Undead"]="对于刚从丧钟镇抵达的新生被遗忘者来说，迪林格尔往往是他们见到的第一位军事权威，他会引导他们前往接受训练，并开始履行侍奉希尔瓦娜斯的首批职责。"},sec={{t="布瑞尔的哨兵",b="作为被遗忘者死亡卫士的一员，迪林格尔站在布瑞尔的入口处，既是前线守卫，也是为从丧钟镇走出来的旅行者提供指引的向导。他为旅店、市政厅和当地训练师等城镇设施指明方向，帮助新觉醒的亡灵适应在黑暗女王统治下的新现实。"},{t="保卫边境",b="迪林格尔积极招募有能力的冒险者，去清理附近农场和磨坊中游荡的无脑天灾。通过剔除腐烂的食尸鬼和收复被占领的设施等任务，他试图在布瑞尔周围建立一道安全缓冲区，确保新生的被遗忘者定居点能够抵御无休止的亡灵侵袭。"},{t="遏制无脑的恐怖",b="除了常规巡逻外，迪林格尔还守卫着死亡卫士最阴暗的秘密之一。当年的天灾军团席卷提瑞斯法时，被遗忘者俘虏了“切肉者”乌拉格，一个仍受巫妖王奴役但却拥有自由意识的天灾特工，并将他封印在布瑞尔北侧的一座陵墓中。在所有打破巫妖王控制的尝试都失败后，迪林格尔会派遣久经考验的战士去解除封印并消灭乌拉格。"}},faq={{q="我可以在哪里找到亡灵卫兵迪林格尔？",a="亡灵卫兵迪林格尔驻守在提瑞斯法林地中部的布瑞尔郊外，注视着通往城镇的小路。",al={"迪林格尔位置","迪林格尔在哪里","亡灵卫兵迪林格尔坐标"}},{q="死亡卫士的职责是什么？",a="死亡卫士是被遗忘者的正规军和治安部队，保卫着布瑞尔和幽暗城等定居点，抵御天灾军团、血色十字军以及其他区域性的威胁。",al={"什么是死亡卫士","谁是死亡卫士","死亡卫士目的"}},{q="亡灵卫兵迪林格尔提供哪些任务？",a="迪林格尔会指派冒险者去屠杀在周边田野和磨坊中徘徊的无脑天灾，收复关键的当地基础设施，并处理像“切肉者”乌拉格这样危险的个体。",al={"迪林格尔任务","迪林格尔有什么任务"}},{q="亡灵卫兵迪林格尔能指路吗？",a="是的，与迪林格尔交谈，玩家可以请求指引前往布瑞尔各处的重要设施、专业训练师和职业导师。",al={"迪林格尔指引","向迪林格尔寻求帮助"}},{q="为什么被遗忘者要在布瑞尔附近攻击其他亡灵？",a="游荡在提瑞斯法境内的无脑亡灵依然受到天灾军团和巫妖王的奴役。在挣脱了精神控制后，被遗忘者必须消灭这些野性的残党以保卫自己的领土。",al={"为什么要对抗天灾","亡灵对抗亡灵","布瑞尔食尸鬼"}},{q="“切肉者”乌拉格是谁？",a="“切肉者”乌拉格是一个与布瑞尔郊外附近陵墓有关的危险天灾怪物。迪林格尔会与被遗忘者新兵协同召唤并消灭乌拉格，以确保周边地区的安全。",al={"乌拉格任务","乌拉格是谁","切肉者乌拉格"}}},fp="20,181,17.254.0,24.261.0,27.318.1,38.106.0,35.185.0,43.169.0,44.109.0,54.191.0,24.169.0"}
P.entries["npc:deathguard-humbert"] = {n="亡灵卫兵亨伯特",s="亡灵卫兵亨伯特是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者哨兵。他被指派监视日益逼近的联盟势力，却因将自己的军用装备弄丢给了丹加洛克的矮人而陷入了尴尬的困境。",h="亡灵卫兵亨伯特是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者哨兵。他被指派监视日益逼近的联盟势力，却因将自己的军用装备弄丢给了丹加洛克的矮人而陷入了尴尬的困境。",kw={"亡灵卫兵亨伯特","丹加洛克","希尔斯布莱德丘陵","亨伯特","亨伯特的长剑","雷矛","塔伦米尔"},ang={["faction:Horde"]="找回亨伯特丢失的长剑不仅是对希尔斯布莱德境内猖狂矮人势力的一次反击，也能维护塔伦米尔守军的尊严。",["race:Undead"]="被遗忘者的士兵被要求以不屈的警惕侍奉黑暗女王，因此亨伯特因疏忽大意被生者夺走装备，这对亡灵卫兵来说是一个令人尴尬的污点。"},sec={{t="一名失去武装的卫兵",b="在执行维持塔伦米尔周边区域安全以应对当地威胁的任务时，亡灵卫兵亨伯特遭受了一次羞辱性的挫折。他受高级执行官达萨利亚派遣，前往一个隐蔽的营地监视丹加洛克。一天清晨，当他离开去收集柴火时，来自丹加洛克的矮人斥候顺手牵羊偷走了他珍贵的长剑和各种装备，这让这位亡灵士兵在指挥部发现之前，迫切地想要挽回自己的尊严和武器。"}},faq={{q="亡灵卫兵亨伯特是谁？",a="亡灵卫兵亨伯特是一名驻扎在塔伦米尔担任斥候和守卫的被遗忘者战士。他的职责包括密切监视希尔斯布莱德丘陵各地敌对的联盟行动。",al={"亨伯特背景故事","谁是亨伯特","亨伯特塔伦米尔"}},{q="亨伯特的长剑和护甲发生了什么事？",a="高级执行官达萨利亚派遣亨伯特在远处监视丹加洛克。一天清晨，他离开隐蔽的营地去收集柴火。等他回来时，来自丹加洛克的矮人斥候路过此处，顺手偷走了他的装备，包括他那柄珍贵的长剑。",al={"亨伯特的长剑被盗","谁拿走了亨伯特的装备","为什么亨伯特需要帮助"}},{q="为什么亨伯特不自己去拿回装备？",a="丹加洛克有着训练有素的矮人火枪手和山地之王，防御极为严密。一名站在战壕外的孤身斥候几乎没有胜算，而且亨伯特如果擅离职守，就无法解释他当初是如何丢失装备的。",al={"为什么亨伯特不能战斗","亨伯特丹加洛克"}}},fp="18,152,29.306.0,26.117.0,43.212.0,50.220.0"}
P.entries["npc:deathguard-linnea"] = {n="亡灵卫兵林奈",s="亡灵卫兵林奈是一名驻扎在提瑞斯法林地东南部的亡灵卫兵补给站的被遗忘者士兵。她协助确保布瑞尔与东部边界之间的道路安全，防范来自血色十字军和游荡的天灾军团的威胁。沿主干道经过的冒险者经常协助她的部队执行巡逻任务。",h="亡灵卫兵林奈是一名驻扎在提瑞斯法林地东南部的亡灵卫兵补给站的被遗忘者士兵。她协助确保布瑞尔与东部边界之间的道路安全，防范来自血色十字军和游荡的天灾军团的威胁。沿主干道经过的冒险者经常协助她的部队执行巡逻任务。",kw={"布瑞尔","亡灵卫兵林奈","被遗忘者","执政官塞弗伦","rear guard patrol","提瑞斯法林地"},ang={["faction:Horde"]="在提瑞斯法林地穿行的被遗忘者盟友可以通过协助林奈稳定偏远道路、抵御敌对势力来赢得好感。",["race:Undead"]="对于从丧钟镇刚刚复生的被遗忘者来说，协助亡灵卫兵林奈所在的补给站，是为保卫他们新王国的边界而最早承担的职责之一。"},sec={{t="路边的警戒",b="亡灵卫兵林奈守卫着布瑞尔东南方的一处小型防御哨站。在提瑞斯法林地执行巡逻任务的生活——或者说“死后生活”——危机四伏，因为被遗忘者必须时刻警惕，保卫他们初生的领地，抵御血色十字军的渗透者和在荒野中游荡的无脑天灾军团。林奈与她的守卫同伴一起驻扎在此，监督道路沿线的巡逻工作，并与布瑞尔的执政官塞弗伦等当地官员协调情报，以确保通往亡灵壁垒的东部道路安全。"}},faq={{q="谁是亡灵卫兵林奈？",a="林奈是一名服役于亡灵卫兵的亡灵士兵，这支军事力量负责保卫被遗忘者的领土。她驻扎在提瑞斯法林地布瑞尔东南方道路沿线的一个亡灵卫兵补给站中。",al={"林奈","亡灵卫兵林奈背景故事","林奈是谁"}},{q="她为什么需要巡逻援助？",a="被遗忘者的军事资源在整个提瑞斯法林地都捉襟见肘。林奈依靠过往的旅人和初露锋芒的勇士来协助清理周围的威胁，以确保信使和补给员能够安全地往返于布瑞尔。",al={"rear guard patrol背景故事","为什么要帮助林奈"}}},fp="17,242,23.342.0,25.156.0,34.199.0"}
P.entries["npc:deathguard-samsa"] = {n="亡灵卫兵沙穆萨",s="亡灵卫兵沙穆萨是驻扎在希尔斯布莱德丘陵塔伦米尔的一名被遗忘者哨兵。他的职责是在紧张的前线维持部落的警戒，并指引来往的勇士打击侵扰定居点的当地威胁。",h="亡灵卫兵沙穆萨是驻扎在希尔斯布莱德丘陵塔伦米尔的一名被遗忘者哨兵。他的职责是在紧张的前线维持部落的警戒，并指引来往的勇士打击侵扰定居点的当地威胁。",kw={"亡灵卫兵沙穆萨","被遗忘者","希尔斯布莱德","沙穆萨","死亡的纪念品","塔伦米尔"},ang={["faction:Horde"]="穿越希尔斯布莱德丘陵的部落旅人依靠像沙穆萨这样的哨兵来协调防御，抵御来自南海镇的附近联盟势力的侵犯。",["race:Undead"]="对于被遗忘者而言，亡灵卫兵沙穆萨代表了守护洛丹伦南部边界抵御敌对邻居所必需的务实而冷酷的防御。"},sec={{t="塔伦米尔的前线哨兵",b="亡灵卫兵沙穆萨在塔伦米尔守卫，代表了被遗忘者在纷争不断的希尔斯布莱德丘陵中的防御中坚力量。塔伦米尔是部落在该地区的主要前哨站，直接面临着来自南海镇等联盟据点以及凶猛的当地野生生物的压力。沙穆萨的职责包括保卫外围区域，并指引有能力的冒险者在威胁危及营地之前将其铲除。"}},faq={{q="亡灵卫兵沙穆萨是谁？",a="亡灵卫兵沙穆萨是一名在塔伦米尔服役于被遗忘者军队的亡灵士兵。他守卫着城镇，并向来访的冒险者下达指令，协助保障该地区的安全，抵御邻近的危险。",al={"沙穆萨","沙穆萨是谁","亡灵卫兵沙穆萨的角色"}},{q="我在哪里可以找到亡灵卫兵沙穆萨？",a="他位于希尔斯布莱德丘陵北部的主要部落定居点——塔伦米尔。",al={"沙穆萨的位置","亡灵卫兵沙穆萨在哪里","塔伦米尔卫兵位置"}},{q="亡灵卫兵沙穆萨会提供什么任务？",a="沙穆萨委托冒险者深入希尔斯布莱德荒野，任务包括收集部落在对希尔斯布莱德人类的战役中击杀的人类头颅。",al={"沙穆萨的任务","死亡的纪念品任务发布者"}}},fp="16,116,30.334.0,24.160.0,34.101.0,42.154.0"}
P.entries["npc:deathguard-simmer"] = {n="亡灵卫兵希米尔",s="亡灵卫兵希米尔是一名驻扎在提瑞斯法林地丧钟镇外的被遗忘者士兵。他会评估新复活的被遗忘者，并派他们去突袭西边由血色十字军巡逻的人类南瓜农场，为布瑞尔的药剂师们获取试剂。",h="亡灵卫兵希米尔是一名驻扎在提瑞斯法林地丧钟镇外的被遗忘者士兵。他会评估新复活的被遗忘者，并派他们去突袭西边由血色十字军巡逻的人类南瓜农场，为布瑞尔的药剂师们获取试剂。",kw={"亡灵卫兵","亡灵卫兵希米尔","丧钟镇","提瑞斯法林地"},ang={["race:Undead"]="希米尔提供了一些首批直接针对血色十字军的任务，标志着亡灵冒险者从丧钟镇的墓穴中毕业，开始参与保卫洛丹伦的更广阔战事。"},sec={{t="丧钟镇外的守卫",b="亡灵卫兵希米尔驻扎在丧钟镇外，他代表了被遗忘者的军事防线，守卫着丧钟镇这片安全港湾与提瑞斯法林地更广阔险境之间的边界。该地区到处都是活人——其中最著名的是狂热的血色十字军——他们将所有亡灵视为必须用烈火和利刃清除的憎恶。希米尔通过派遣新生的被遗忘者前往西边的索利丹农场（血色十字军从附近的塔楼派遣巡逻队守卫那里）来考验他们，让他们偷走十个南瓜并送到布瑞尔的药剂师乔汉手中。"}},faq={{q="亡灵卫兵希米尔是谁？",a="亡灵卫兵希米尔是一名驻扎在提瑞斯法林地丧钟镇外的被遗忘者哨兵。他通过派遣新生的被遗忘者去偷取血色十字军巡逻的人类农场里的南瓜来考验他们。",al={"亡灵卫兵希米尔","希米尔是谁","希米尔npc"}},{q="亡灵卫兵希米尔在哪里？",a="他站在提瑞斯法林地西南部丧钟镇外，位于新复活的被遗忘者离开墓穴的路上。",al={"亡灵卫兵希米尔位置","希米尔在哪里","寻找亡灵卫兵希米尔"}},{q="亡灵卫兵希米尔对抗哪些威胁？",a="希米尔蔑视那些仍然在提瑞斯法务农的活人，以及在他们附近巡逻的血色十字军。他派遣新生的被遗忘者突袭索利丹农场夺取南瓜，以此给那些人类一点教训，同时为布瑞尔的药剂师提供补给。",al={"希米尔的敌人","希米尔对抗什么","血色十字军任务"}}},fp="17,202,27.485.0,25.198.0,35.140.0,42.256.0"}
P.entries["npc:deathstalker-faerleia"] = {n="亡灵哨兵费雷亚",s="亡灵哨兵费雷亚是驻扎在敌后腹地、焚木村内的一名被遗忘者情报特工。她以镇上的市政厅为据点，指挥着针对焚木议会的秘密袭击。焚木议会是阿鲁高用来操纵村庄领导层的傀儡。",h="亡灵哨兵费雷亚是驻扎在敌后腹地、焚木村内的一名被遗忘者情报特工。她以镇上的市政厅为据点，指挥着针对焚木议会的秘密袭击。焚木议会是阿鲁高用来操纵村庄领导层的傀儡。",kw={"伏击","议会","亡灵哨兵","费雷亚","被遗忘者","焚木村","银松森林"},ang={["class:Rogue"]="对于效力于被遗忘者的潜行者来说，费雷亚代表了亡灵哨兵外勤技术的巅峰：神不知鬼不觉地直接潜入敌人的权力核心进行伏击部署。",["race:Undead"]="费雷亚是亡灵哨兵依靠渗透和冷酷计算来瓦解黑暗女王敌人的典范，无需动用整支军队即可完成目标。"},sec={{t="深入敌后",b="作为幽暗城秘密情报与暗杀分支——亡灵哨兵的一名特工，费雷亚的任务是渗透进位于银松森林南部的焚木村。这个与世隔绝的人类飞地隐藏着黑暗的秘密，包括一种会在夜幕降临时诅咒其居民并使其发生变异的诅咒。费雷亚驻扎在市政厅的上层，从内部协调行动以瓦解该定居点，并召唤部落特工消灭焚木议会中具有影响力的成员。"}},faq={{q="亡灵哨兵费雷亚是谁？",a="她是亡灵哨兵的一名特工，隶属于Sylvanas Windrunner女王麾下被遗忘者的潜行与情报部门。她潜入焚木村，旨在对其领导层发动秘密战争。",al={"费雷亚","费雷亚是谁","亡灵哨兵费雷亚"}},{q="在哪里可以找到亡灵哨兵费雷亚？",a="费雷亚藏身于位于银松森林南部，格雷迈恩之墙以北的焚木村市政厅内。",al={"费雷亚在哪里","费雷亚位置","寻找费雷亚"}},{q="她发布什么任务？",a="她指引冒险者执行“焚木村的伏击”任务，这是一项暗杀治理焚木村的议会议员的行动，旨在削弱该飞地对被遗忘者的抵抗力。",al={"费雷亚任务","焚木村的伏击任务"}},{q="为什么亡灵哨兵要针对焚木村？",a="阿鲁高利用焚木议会作为傀儡，以此控制那些受诅咒的村民。费雷亚相信，只要议会成员身死，阿鲁高之子就会反戈对抗他们的主人，从而帮助被遗忘者夺取该镇，并将阿鲁高赶出影牙城堡。",al={"为什么要攻击焚木村","焚木村的亡灵哨兵"}}},fp="21,200,18.513.1,29.183.0,41.121.0,27.176.0,53.260.0"}
P.entries["npc:deathstalker-lesh"] = {n="亡灵哨兵莱什",s="亡灵哨兵莱什是一名被遗忘者潜行者，在希尔斯布莱德丘陵的南点哨塔担任前哨侦察兵。她直接受命于高级执行官达萨利亚，负责监视希尔斯布莱德农场的人类农场，以判断被遗忘者何时该发起进攻。",h="亡灵哨兵莱什是一名被遗忘者潜行者，在希尔斯布莱德丘陵的南点哨塔担任前哨侦察兵。她直接受命于高级执行官达萨利亚，负责监视希尔斯布莱德农场的人类农场，以判断被遗忘者何时该发起进攻。",kw={"亡灵哨兵莱什","高级执行官达萨利亚","希尔斯布莱德农场","希尔斯布莱德丘陵","南点哨塔","塔伦米尔","进攻时机"},ang={["class:Rogue"]="亡灵哨兵莱什展示了部落战争中秘密行动人员至关重要的军事职能。",["race:Undead"]="对于被遗忘者而言，像莱什这样的侦察兵代表了从联盟复苏势力手中夺回洛丹伦的关键边境工作。"},sec={{t="关注农场",b="亡灵哨兵莱什驻守在贯穿希尔斯布莱德丘陵的南路上的南点哨塔，监视着在附近的希尔斯布莱德农场工作的人类农夫和城镇民兵。作为亡灵哨兵——被遗忘者秘密情报与暗杀网络——的一名特工，莱什负责为塔伦米尔的高级执行官达萨利亚追踪敌人的动向和兵力。时机成熟时，莱什会向达萨利亚发送一条暗号：“西方的乌鸦啼叫在召唤”，暗示希尔斯布莱德已被被遗忘者视为进攻的成熟目标。"}},faq={{q="亡灵哨兵莱什是谁？",a="莱什是一名驻扎在南点哨塔的被遗忘者侦察兵。她听命于塔伦米尔的高级执行官达萨利亚，并负责监视希尔斯布莱德农场的人类活动。",al={"亡灵哨兵莱什","莱什是谁","莱什 希尔斯布莱德"}},{q="什么是亡灵哨兵？",a="亡灵哨兵作为侦察兵、间谍和刺客效忠于希尔瓦娜斯·风行者女王。他们是被遗忘者军队的秘密力量，负责在洛丹伦各地收集情报并清除高价值目标。",al={"什么是亡灵哨兵","亡灵哨兵组织","被遗忘者潜行者"}},{q="莱什在南点哨塔的角色是什么？",a="她担任前哨观察员。她在南点哨塔监视希尔斯布莱德镇，当时机成熟时，她会派遣一名旅行者向塔伦米尔的高级执行官达萨利亚传递暗号，示意希尔斯布莱德已可进行攻击。",al={"南点哨塔侦察兵","莱什任务","莱什为什么在这里"}},{q="莱什向谁报告？",a="她向驻扎在塔伦米尔的被遗忘者指挥官高级执行官达萨利亚报告，后者负责监管针对希尔斯布莱德人类势力的攻势。",al={"莱什首领","谁指挥莱什","高级执行官达萨利亚"}}},fp="17,169,18.547.0,25.155.0,27.184.0,40.257.0,24.144.0"}
P.entries["npc:deathstalker-rane-yorick"] = {n="兰妮·尤瑞克",s="死亡猎手兰妮·尤瑞克是一名被派驻在银松森林深处的被遗忘者情报组织特工。她和她的兄弟奎恩·尤瑞克一同被派往侦察银松森林北部的农场，并向高级执行官哈德瑞克汇报情况。",h="死亡猎手兰妮·尤瑞克是一名被派驻在银松森林深处的被遗忘者情报组织特工。她和她的兄弟奎恩·尤瑞克一同被派往侦察银松森林北部的农场，并向高级执行官哈德瑞克汇报情况。",kw={"死亡猎手","埃兰","被遗忘者","伊瓦农场","兰妮","潜行者","侦察兵","银松森林","尤瑞克"},ang={["class:Rogue"]="对于被遗忘者的潜行者来说，兰妮·尤瑞克体现了死亡猎手所必需的危险外勤工作，即在持续的敌对压力下保持潜行并收集情报。",["faction:Horde"]="她的情报工作有助于确保途经银松森林的部落补给路线免受狼人和当地伏击的威胁。",["race:Undead"]="被遗忘者的勇士们作为前线侦察兵遇到了兰妮，她正在防止银松森林那未被驯服的边境落入敌手。"},sec={{t="林中之眼",b="死亡猎手是希尔瓦娜斯·风行者女王在洛丹伦的耳目和利刃。像兰妮·尤瑞克这样的特工常在阴影和隐秘哨所中活动，监视着荒野，排除可能扰乱被遗忘者统治的威胁。当兰妮和她的兄弟奎恩被派去侦察银松森林北部时，他们发现自己被周围野性的危险团团围住，原本秘密的侦察任务演变成了一场生存之战。"},{t="困在伊瓦农场",b="兰妮·尤瑞克躲在伊瓦农场的一间废弃农舍里，任务陷入了僵局。食尸鬼伊瓦尔把她的兄弟奎恩打成了重伤，而她与瑟伯切尔的安全区之间徘徊着许多狼人。为了不放弃任务，她只能依靠路过的部落旅人去收集狼人心脏以制作治疗药水，击杀伊瓦尔，并将她的报告送回指挥部。"}},faq={{q="死亡猎手兰妮·尤瑞克是谁？",a="她是死亡猎手的一名特工，这是被遗忘者旗下的刺客与情报收集潜行者组织。她目前驻扎在银松森林伊瓦农场的一间破旧农舍里。",al={"兰妮·尤瑞克是谁","兰妮·尤瑞克背景故事","死亡猎手尤瑞克是谁"}},{q="什么是死亡猎手？",a="死亡猎手是被遗忘者的秘密潜行者组织，直接听命于希尔瓦娜斯·风行者女王。他们在洛丹伦全境执行秘密侦察、间谍活动和定点清除任务。",al={"什么是死亡猎手","死亡猎手阵营","死亡猎手是什么组织"}},{q="为什么她被困在农舍里？",a="兰妮和她的兄弟奎恩被派去侦察银松森林北部的农场，但在伊瓦农场遭到了食尸鬼伊瓦尔的袭击，奎恩被打成重伤，迫使他们在奎恩疗伤期间躲进了农舍。",al={"为什么兰妮被困住了","伊瓦农场农舍","为什么她在躲藏"}},{q="她的兄弟是谁？",a="她的兄弟是奎恩·尤瑞克，也是一名执行相同侦察任务的死亡猎手。他在伊瓦农场被食尸鬼伊瓦尔打成了重伤。",al={"兰妮·尤瑞克的兄弟","埃兰是谁","亡灵哨兵埃兰德"}},{q="他们在银松森林追踪什么威胁？",a="他们的任务是侦察银松森林北部的农场，以应对被遗忘者占领区面临的威胁。他们发现天灾军团的势力比预想的要大得多，此外还有游荡的狼人和食尸鬼伊瓦尔。",al={"他们在侦察什么","兰妮在调查什么"}},{q="她向哪里汇报调查结果？",a="她向瑟伯切尔的高级执行官哈德瑞克汇报，此人负责监管被遗忘者对银松森林的占领。",al={"报告提交到哪里","兰妮的上级是谁"}}},fp="11,186,17.337.0,21.336.1,32.194.0,27.162.0,34.219.0,19.136.0,45.185.0,35.129.0"}
P.entries["npc:deathstalker-vincent"] = {n="亡灵哨兵文森特",s="亡灵哨兵文森特是遗忘者的一名侦察兵，他与亡灵哨兵亚当特一起被派往影牙城堡执行渗透任务。由于被疯狂的法师阿鲁高杀害，他的尸体至今仍留在堡垒内部，作为对任何胆敢挑战内部野性狼人的入侵者的一种残酷警告。",h="亡灵哨兵文森特是遗忘者的一名侦察兵，他与亡灵哨兵亚当特一起被派往影牙城堡执行渗透任务。由于被疯狂的法师阿鲁高杀害，他的尸体至今仍留在堡垒内部，作为对任何胆敢挑战内部野性狼人的入侵者的一种残酷警告。",kw={"阿鲁高","亡灵哨兵亚当特","亡灵哨兵文森特","影牙城堡","银松森林","文森特","狼人"},ang={["class:Rogue"]="文森特的处决是一个严酷的提醒，警示着潜行特工单独渗透敌方据点时所面临的风险。",["faction:Horde"]="发现文森特的尸体证实了银松森林遗忘者指挥官们最担心的事：侦察小组失败了，现在必须通过武力来肃清这座城堡。"},sec={{t="侦察兵的悲惨结局",b="在遗忘者能够对占领影牙城堡的野兽发动全面突袭之前，他们急需关于堡垒内部的情报。两名来自亡灵哨兵（遗忘者的情报部门）的特工溜过了路障：文森特和亚当特。他们的任务以灾难告终。亚当特被俘并关进了地牢，而文森特则被直接拖到了影牙城堡的主人面前。文森特拒绝屈服，也不愿效忠于阿鲁高的邪恶计划，当场被处决，尸体被丢弃在石地板上任其腐烂，以此彰显这位法师的愤怒。"},{t="阿鲁高的藐视",b="阿鲁高利用文森特的死亡向闯入他城堡的入侵者发表了一通尖刻的声明。这位疯狂的法师与被俘的特工对峙，嘲弄了遗忘者，并将他们的入侵与他前肯瑞托同僚的失败尝试相提并论。阿鲁高要求文森特交出他的武器和秘密，在遭到拒绝后，法师杀死了这名侦察兵，并宣称文森特腐烂的遗骸将是对任何愚蠢到闯入他领地之人的警告。"}},faq={{q="亡灵哨兵文森特是谁？",a="文森特是隶属于亡灵哨兵的一名遗忘者侦察兵。他与亡灵哨兵亚当特一同被派往影牙城堡，在幽暗城计划发动的突袭之前收集关键的侦察信息。",al={"谁是文森特","影牙城堡文森特","影牙城堡死去的潜行者"}},{q="文森特在影牙城堡遭遇了什么？",a="文森特在侦察任务中被俘，并因拒绝投降或提供不利于遗忘者的情报，被大法师阿鲁高处决。阿鲁高将他的尸体弃置在当场，以展示自己的力量。",al={"文森特是怎么死的","为什么文森特死了","谁杀了文森特"}},{q="他的搭档亡灵哨兵亚当特在哪里？",a="虽然文森特被公开处决了，但亡灵哨兵亚当特被活捉，并关在附近一间由狼人守卫严密看守的地牢牢房里。",al={"亚当特在哪里","另一名亡灵哨兵","亚当特的位置"}},{q="为什么亡灵哨兵会被派往影牙城堡？",a="银松森林对于希尔瓦娜斯和遗忘者来说是至关重要的领土，但阿鲁高的狼人占据了该地区的要塞——影牙城堡。文森特和亚当特被派去侦察其布局和防御，以便遗忘者能够组织有效的进攻。",al={"为什么亡灵哨兵在影牙城堡","遗忘者的影牙任务"}}},fp="20,213,19.401.0,17.396.1,29.188.0,44.153.0,43.103.0,51.238.0"}
P.entries["npc:deathwing"] = {n="Deathwing",s="毁灭者Deathwing，曾经被称为大地守卫Neltharion，是黑龙军团堕落的龙王。在古神黑暗低语的折磨下，他陷入了疯狂，背叛了其他龙王，让整个世界陷入了战火与混乱。尽管在第二次战争后于格瑞姆巴托附近被击败，并被认为已被消灭或隐藏起来，但他留下的恐怖阴影依然笼罩着艾泽拉斯深处的角落。",h="毁灭者Deathwing，曾经被称为大地守卫Neltharion，是黑龙军团堕落的龙王。在古神黑暗低语的折磨下，他陷入了疯狂，背叛了其他龙王，让整个世界陷入了战火与混乱。尽管在第二次战争后于格瑞姆巴托附近被击败，并被认为...",kw={"龙王","黑龙军团","deathwing","恶魔之魂","毁灭者","巨龙之魂","大地守卫","格瑞姆巴托","neltharion","prestor"},ang={["faction:Alliance"]="联盟的贵族们至今仍在战栗，回想起Daval Prestor领主曾是多么接近夺取奥特兰克王冠，并操纵七国议会从内部摧毁联盟。",["faction:Horde"]="旧部落在第二次战争期间曾与Deathwing达成邪恶交易，通过龙喉氏族控制红龙，这是新部落试图抹去的过去污点。",["race:NightElf"]="暗夜精灵长者们依然记得一万年前上古之战期间，Neltharion那突如其来的毁灭性背叛，那场暴行摧毁了龙族，并注定了他们古老帝国的灭亡。"},sec={{t="Neltharion的堕落",b="在被称为毁灭者之前，Neltharion曾被泰坦万神殿授予统御艾泽拉斯大地与地底深处的权力。然而，长久居住在世界最深处的密室中，使他暴露在被囚禁的古神那邪恶的低语之下。在上古之战期间，疯狂彻底占据了他的心灵。他欺骗其他龙王，谎称为了抵御燃烧军团，让他们将各自的部分精髓注入一张金色的圆盘——巨龙之魂，随后便将这件恐怖的武器对准了自己的盟友，并引发了灾难性的毁灭。"},{t="人类领主的阴谋",b="第二次战争后，Deathwing试图从内部瓦解人类王国。他伪装成一位极具魅力的贵族——Daval Prestor领主，迷惑了Terenas Menethil二世国王和洛丹伦联盟的高层议会，密谋夺取奥特兰克的空缺王位。与此同时，他协助格瑞姆巴托的龙喉氏族囚禁了红龙女王Alexstrasza，并利用她产下的龙蛋。当Rhonin摧毁了恶魔之魂，恢复了其他龙王被窃取的力量，并合力将Deathwing击退后，他的阴谋才彻底破产。"},{t="留下的后裔",b="在当今时代，人类王国大多认为Deathwing已经被消灭或彻底驱逐出了这个世界。然而，黑龙军团依然是整个艾泽拉斯的一大祸患。在他的狡诈后裔——包括女儿奥妮克希亚和儿子奈法利安——的带领下，黑龙不断操纵着人类的政治，并从山脉巢穴中威胁着这片土地。这位黑龙王的古老背叛留下的伤疤至今未愈，行经崎岖荒野与深邃地底隧道的旅人，依然畏惧着这位巨龙的苏醒。"}},faq={{q="Deathwing最初是谁？",a="Deathwing最初是大地守卫Neltharion，他是黑龙军团的领袖，受泰坦赋予神力，负责守护艾泽拉斯的大地与群山。数千年前，由于长期处于地底深处，他极易受到古神阴险低语的侵蚀，导致精神崩溃。",al={"neltharion历史","谁是neltharion","大地守卫起源"}},{q="什么是巨龙之魂？",a="巨龙之魂，后来被称为恶魔之魂，是Neltharion在上古之战期间锻造的一件金色神器。他诱骗其他四位龙王将自己的力量注入其中，随后便将这件武器那末日般的威力对准了同族的巨龙以及凡人守卫者。",al={"恶魔之魂","什么是巨龙之魂","neltharion的神器"}},{q="Daval Prestor领主是谁？",a="Daval Prestor领主是Deathwing在第二次战争后所采取的人类伪装。通过强大的魅惑魔法和宫廷诡计，他试图夺取奥特兰克的王位，并从内部操纵洛丹伦联盟，直到他的背叛行径暴露。",al={"prestor领主","daval prestor身份","prestor背景故事"}},{q="Deathwing与格瑞姆巴托有什么关联？",a="Deathwing曾在格瑞姆巴托暗中将恶魔之魂交给龙喉兽人，确保红龙女王Alexstrasza始终被囚禁并被迫为战争繁育后代。后来，Rhonin利用一片Deathwing的鳞片摧毁了这件神器。力量恢复后，其他龙王与Deathwing交战并将他击退。",al={"deathwing格瑞姆巴托","格瑞姆巴托发生了什么"}},{q="如今是谁在领导黑龙军团？",a="由于Deathwing失踪且被推定死亡，他的主要后裔各自为政。他的女儿奥妮克希亚在尘泥沼泽的巢穴中潜伏，而他的儿子奈法利安则统领着黑龙，并在黑石山顶端进行着龙血实验。",al={"现任黑龙领袖","谁在领导黑龙","奈法利安和奥妮克希亚"}}},fp="9,406,22.588.0,24.571.1,21.547.0,29.287.0,25.292.0,27.265.1,45.305.0,39.252.2"}
P.entries["npc:deino"] = {n="迪诺",s="迪诺是一名暗矛巨魔训练师，居住在奥格瑞玛的Valley of Spirits。她与其他导师一起，教导初出茅庐的奥术师如何掌握奥术以及驾驭动荡的元素力量。她还会指引卡利姆多各地的资深施法者，让他们去解开古老的魔法异常现象，并寻找隐居的导师。",h="迪诺是一名暗矛巨魔训练师，居住在奥格瑞玛的Valley of...",kw={"迪诺","笑面姐妹","法师训练师","奥格瑞玛","塔贝萨","巨魔法师","valley of spirits","萨维亚之水","萨维亚"},ang={["class:Mage"]="迪诺是奥格瑞玛的一名重要职业训练师，提供关键的天赋指导、传送门法术，以及通往灰谷和尘泥沼泽的专门任务。",["faction:Horde"]="她驻扎在奥格瑞玛的灵性区域，确保部落的施法者能与萨满和术士一样维持强大的奥术力量。",["race:Troll"]="迪诺体现了暗矛巨魔对奥术魔法的适应，将传统的学术法术与Valley of Spirits的文化环境相结合。"},sec={{t="谷地的奥术师",b="迪诺站在Valley of Spirits的图腾、小屋和宁静水域之中，为来到兽人主城的部落法师提供教导。巨魔施法者在传统上行走在灵性崇敬和纯粹奥术掌握之间，迪诺在暗矛部族中代表了这一独特的道路，她与同事埃尼奥和佩弗雷多并肩作战。"},{t="解开奥术之谜",b="除了基础的法术技艺外，迪诺还会指派有前途的施法者前往杜隆塔尔红尘之外进行实地研究。她派遣施法者向北进入被腐蚀的灰谷荒野，收集萨维亚的污染之水，并从笑面姐妹那里取回附魔毛发。当学生的法力超出了奥格瑞玛所能提供的范畴时，迪诺会指引他们前往偏远的导师处，例如尘泥沼泽中隐居的女巫塔贝萨。"}},faq={{q="在哪里可以找到迪诺？",a="迪诺站在奥格瑞玛西南部Valley of Spirits的高台上，与巨魔法师训练师同事埃尼奥和佩弗雷多在一起。",al={"迪诺位置","迪诺在哪里","迪诺 奥格瑞玛"}},{q="迪诺教授什么？",a="她训练法师学习奥术、火焰和冰霜法术、传送门制造，以及随着施法者经验增长而获得的基本法术等级。",al={"迪诺 训练师","迪诺教授什么法术"}},{q="为什么迪诺会派法师去萨维亚？",a="萨维亚是灰谷东部的一座古城，现在被萨特占据，据说那里的水蕴含着巨大的魔法力量。迪诺需要一份从其最高瀑布底部提取的样本，以便进行研究。",al={"萨维亚之水任务","为什么要去萨维亚"}},{q="和迪诺在一起的训练师是谁？",a="她与埃尼奥和佩弗雷多在一起。这三人的名字取自古老神话中的格赖埃三姐妹，她们共同组成了奥格瑞玛巨魔法师指导的核心圈子。",al={"谁是埃尼奥","佩弗雷多","valley of spirits的巨魔法师"}},{q="为什么迪诺派法师去尘泥沼泽？",a="当法师达到更高的熟练度时，迪诺会把他们派往塔贝萨。塔贝萨是一位强大而隐居的人类女巫，住在尘泥沼泽深处，掌握着专门的奥术秘密。",al={"迪诺 塔贝萨","前往沼泽的旅程"}},{q="非巨魔玩家可以找迪诺训练吗？",a="可以。任何部落法师——无论是巨魔、兽人还是被遗忘者——都可以在Valley of Spirits找迪诺学习职业法术并获得指导。",al={"兽人可以找迪诺训练吗","部落法师训练"}}},fp="5,230,21.269.0,27.345.0,23.146.0,22.114.0,36.193.0,41.158.0,46.163.0,32.148.0"}
P.entries["npc:delgren-the-purifier"] = {n="净化者德尔格伦",s="净化者德尔格伦是一位驻扎在灰谷北缘迈斯特拉岗哨的人类圣骑士。他与同伴巴苏尔·影击和费罗·艾隆汉并肩作战，协助暗夜精灵清除威胁边境的恶魔与暗影魔法，并将重心特别放在邪恶的暗滩教派上。",h="净化者德尔格伦是一位驻扎在灰谷北缘迈斯特拉岗哨的人类圣骑士。他与同伴巴苏尔·影击和费罗·艾隆汉并肩作战，协助暗夜精灵清除威胁边境的恶魔与暗影魔法，并将重心特别放在邪恶的暗滩教派上。",kw={"奥萨拉克斯","银色黎明","灰谷","巴苏尔·影击","暗滩教派","德尔格伦","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨","奥萨拉克斯之塔"},ang={["class:Paladin"]="德尔格伦代表了圣光在卡利姆多遥远的触角，展现了圣骑士如何在东部王国之外，将他们针对恶魔与黑暗魔法的十字军行动延展下去。",["faction:Alliance"]="对于从黑海岸南下的联盟旅者来说，德尔格伦和他的同伴们在危险的灰谷公路上提供了一个令人安心的军事据点。",["race:NightElf"]="虽然传统的卡多雷通常对外部信仰持怀疑态度，但德尔格伦的队伍通过他们对抗困扰古老遗迹的恶魔邪教的实际行动，赢得了信任。"},sec={{t="卡多雷边境的十字军",b="在卡利姆多古老的森林深处，人类圣骑士是罕见的身影，但净化者德尔格伦带着使命而来。德尔格伦隶属于银色黎明，他率领着一队圣光战士西行，决心协助联盟的新盟友暗夜精灵，对抗第三次战争遗留的恶魔与亡灵残党。他驻扎在黑海岸与灰谷的交界处附近，时刻警惕着从奥伯丁南下的旅者。"},{t="清洗暗滩",b="德尔格伦眼下的十字军行动主要是直接对抗暗滩教派，这是一个在黑海岸北部的奥萨拉克斯之塔周边活动的邪恶组织。德尔格伦与斥候巴苏尔·影击组队，精心策划对教派领地的突袭，调查他们的黑暗仪式，并派遣冒险者去击杀邪教徒、摧毁他们的召唤法阵，铲除那些胆敢与恶魔暗影交易的腐化术士。"},{t="非传统的思想",b="尽管他对圣光有着强烈的虔诚，且称号极其狂热，但德尔格伦对卡利姆多错综复杂的政治局势有着不寻常的见解。令他那些保守的上级感到恼火和不屑的是，他花时间学习了兽人语。这种罕见的语言技能暗示了他有着非传统的思维——他不愿仅仅依赖盲目的教条，而是寻求了解在这片蛮荒大陆上共同生存的敌人与邻居。"}},faq={{q="净化者德尔格伦是谁？",a="德尔格伦是一位人类圣骑士，驻扎在灰谷北部公路旁的迈斯特拉岗哨。作为银色黎明的一名特工，他协助暗夜精灵保卫他们的领土，抵御恶魔腐化、邪教徒以及燃烧军团入侵后留下的阴影。",al={"德尔格伦是谁","德尔格伦背景故事","迈斯特拉岗哨的圣骑士是谁"}},{q="我在哪里可以找到德尔格伦？",a="德尔格伦站在灰谷西北部的迈斯特拉岗哨，这是一个位于通往黑海岸的边境小径以南的暗夜精灵哨所。",al={"德尔格伦在哪里","德尔格伦位置","德尔格伦坐标"}},{q="为什么会有人类圣骑士远在灰谷？",a="德尔格伦率领一队银色黎明圣骑士西行，为联盟的暗夜精灵盟友提供援助。他们的目标是协助清除威胁卡利姆多北部的恶魔入侵、亡灵残党和黑暗邪教。",al={"为什么德尔格伦在灰谷","为什么灰谷会有凡人","德尔格伦使命"}},{q="德尔格伦与奥萨拉克斯之塔有什么联系？",a="德尔格伦和他的同伴负责监视从黑海岸北部奥萨拉克斯之塔散播出的腐化活动。他指挥冒险者调查那座废墟，狩猎暗滩教派，并瓦解他们黑暗的召唤仪式。",al={"德尔格伦 奥萨拉克斯","奥萨拉克斯之塔任务","暗滩教派"}},{q="德尔格伦为什么要学习兽人语？",a="德尔格伦学习兽人语是为了更好地理解卡利姆多的局势和居民，这一决定使他在教团内部的上级那里遭到了明显的反对。",al={"德尔格伦说兽人语","德尔格伦会说兽人语吗","德尔格伦 兽人语言"}},{q="德尔格伦在迈斯特拉岗哨与谁共事？",a="他与巴苏尔·影击和费罗·艾隆汉并肩作战，作为一个协调单位，负责监控边境威胁、处理后勤工作，并在灰谷边境清剿暗影邪教徒。",al={"德尔格伦同伴","谁在迈斯特拉岗哨"}}},fp="20,201,35.413.0,23.324.1,18.313.0,28.220.0,25.136.0,52.192.0,55.226.0,29.113.0,45.198.0"}
P.entries["npc:demisette-cloyce"] = {n="德米赛特·克劳斯",s="德米赛特·克劳斯是一位人类术士训练师，隐居在暴风城法师区的“Slaughtered Lamb”地下的地窖中。她在城市的阴影中开展活动，指导邪能法术的修行者，并引导有前途的侍僧去探索更深、更危险的奥术奥秘。",h="德米赛特·克劳斯是一位人类术士训练师，隐居在暴风城法师区的“Slaughtered Lamb”地下的地窖中。她在城市的阴影中开展活动，指导邪能法术的修行者，并引导有前途的侍僧去探索更深、更危险的奥术奥秘。",kw={"克劳斯","德米赛特","mage quarter","梅纳拉·沃伦德","slaughtered lamb","暴风城","术士训练师"},ang={["class:Warlock"]="在侍僧于暴风城的成长过程中，德米赛特是一位至关重要的联络人，她提供基础的法术指导，并在之后派遣术士踏上获取邪能战马和束缚恶魔宝珠的道路。",["race:Human"]="克劳斯隐居在人类文明之都的下方，她展现了人类那种安静而危险的边缘——他们抛弃了圣光，转而挥舞恶魔的力量。"},sec={{t="“Slaughtered Lamb”的地窖",b="虽然暴风城的当局维持着表面上的秩序和神圣的正义，但邪能魔法的修行者们却在法师区“Slaughtered Lamb”下阴暗的地下室里集会。德米赛特·克劳斯就居住在这些地下墓穴中，指导那些敢于接触禁忌法术的术士。她对未经训练或未入门的人没有什么耐心，总是告诫她的学生，黑暗力量只会腐蚀那些缺乏纪律去驾驭它们的人。"},{t="联系各处邪教徒",b="德米赛特不仅仅是一位简单的法术导师；她是艾泽拉斯各地术士行动的重要枢纽。当一名侍僧达到足够的造诣时，她会指引他们前往暴风城之外的地方——将他们与贫瘠之地的梅纳拉·沃伦德等强大的召唤师联系起来，以利用强大的神器并束缚强大的邪能战马。"}},faq={{q="德米赛特·克劳斯是谁？",a="德米赛特·克劳斯是一位人类术士训练师，位于暴风城法师区“Slaughtered Lamb”酒馆下的地窖里。她指导初出茅庐的术士进行恶魔召唤和黑暗法术的学习。",al={"德米赛特是谁","德米赛特·克劳斯背景故事","德米赛特·克劳斯是谁"}},{q="她为什么要躲在酒馆的地窖里？",a="术士集会聚集在“Slaughtered Lamb”的地下室里，远离公众的视线。他们黑暗的修行方式使得这家酒馆成为一个隐蔽的聚会场所。",al={"她为什么在地窖里","为什么是slaughtered lamb","slaughtered lamb地下室"}},{q="她与贫瘠之地有什么联系？",a="德米赛特会派遣经验丰富的术士跨海去寻找梅纳拉·沃伦德，这是一位驻扎在贫瘠之地海岸棘齿城的强大召唤师，去追求更高阶的仪式、强大的宝珠以及束缚仪式。",al={"德米赛特贫瘠之地","寻找梅纳拉·沃伦德","梅纳拉·沃伦德的联系"}},{q="她对非术士有什么反应？",a="德米赛特对局外人嗤之以鼻。除非你走的是术士之路，否则她会警告你，黑暗不会拥抱你，并命令你停止废话，离开她的视线。",al={"德米赛特对话","与德米赛特交谈"}}},fp="16,166,34.342.0,21.235.0,24.137.0,37.139.0,38.175.0,35.171.0"}
P.entries["npc:denalan"] = {n="德纳兰",s="德纳兰是一位造诣深厚的暗夜精灵草药学家和植物学家，在奥拉密斯湖东岸的一块静谧湖畔地带照料着他的研究园地。他在一个简陋的遮阳棚下工作，整日致力于研究岛上的植物生命，并为影响泰达希尔的离奇腐蚀寻找植物学层面的疗法。他经常雇佣年轻的冒险者去采集样本、研究狂暴的树苗怪，并测试附魔土壤。",h="德纳兰是一位造诣深厚的暗夜精灵草药学家和植物学家，在奥拉密斯湖东岸的一块静谧湖畔地带照料着他的研究园地。他在一个简陋的遮阳棚下工作，整日致力于研究岛上的植物生命，并为影响泰达希尔的离奇腐蚀寻找植物学层面的疗法。他经常雇佣...",kw={"腐臭的黑苔","植物学","德纳兰","草药学家","卡多雷","奥拉密斯湖","橡木之爪","种植花箱","泰达希尔","树苗怪"},ang={["class:Druid"]="德鲁伊们会发现德纳兰的湖畔实验与他们的事业不谋而合，因为他的工作直接协助了塞纳里奥议会追踪并清除在泰达希尔根系中蔓延的污染。",["profession:Herbalism"]="德纳兰展现了卡多雷植物学研究的传统，证明了收集和培育野生植物可以诊断自然界中更深层的病变。",["race:NightElf"]="德纳兰在奥拉密斯湖的研究代表了卡多雷早期试图了解他们的新家园——泰达希尔所面临的意外缺陷和成长阵痛的努力。"},sec={{t="奥拉密斯湖的植物学家",b="许多卡多雷专注于武力戒备或高深的德鲁伊仪式，而德纳兰却选择了草药学这一需要耐心与细致的工作。他驻扎在宁静的奥拉密斯湖东岸，建立了一个简朴的研究营地，里面只有遮阳棚、简单的野外工具和几排整齐的栽培花箱。比起退回达纳苏斯的大型兽穴，他更愿意留在泥土旁，直接观察自新世界之树种下以来就萌发出的那些不同寻常的植物。"},{t="调查泰达希尔的损伤",b="德纳兰的研究远非单纯的好奇心使然，而是旨在解决泰达希尔本地野生生物日益增长的不安。树苗怪原本是温顺的木质和新芽组成的林地生物，现在却变得越来越好斗。德纳兰通过对特殊的土壤施加附魔来培育野外种子，并分析恶性力量是如何渗入根系的。通过研究闪光嫩枝、发光的水果和布满苔藓的心脏这类奇特的标本，他试图分离出困扰森林枝干的黑暗污染。"}},faq={{q="我能在哪里找到德纳兰？",a="德纳兰位于泰达希尔南部、多兰纳尔以南的奥拉密斯湖东岸。他在水边维持着一个小营地，设有一个遮阳棚和几块经过耕作的种植床。",al={"德纳兰位置","德纳兰在哪里","德纳兰地图"}},{q="德纳兰在他的营地里研究什么？",a="德纳兰是一位正在研究泰达希尔异常植物和当地林地精魂攻击行为的草药学家。他利用附魔花箱来培育树苗怪种子、分析奇特的野生植物标本，并寻找净化渗入新世界之树生态系统中的腐蚀的方法。",al={"德纳兰做什么","德纳兰的目的","为什么德纳兰在湖边"}},{q="为什么树苗怪会攻击人？",a="树苗怪是泰达希尔枝干上原生的植物类自然精魂。它们原本是森林生态中和平的一环，但由于一种非自然的腐蚀正在世界之树的土壤和根系中蔓延，导致它们变得暴躁且反常，这促使像德纳兰这样的研究者对它们的种子进行调查。",al={"为什么树苗怪具有攻击性","树苗怪背景","被腐蚀的树苗怪"}},{q="德纳兰的花箱是用来做什么的？",a="德纳兰保留着特制的种植床，里面装满了经过附魔的土壤。他利用这些种植床来培育野生种子和奇特的植物插条，以便安全地观察森林植物在远离野生污染物、处于净化土壤中的反应。",al={"德纳兰的种植花箱","德纳兰的土壤","德纳兰的种植盒"}},{q="德纳兰与谁共事？",a="德纳兰与达纳苏斯的德鲁伊瑞利安·绿脊（Rellian Greenspyre）共事，后者与他一样关注树苗怪的问题；同时，他在多兰纳尔的一位同事会为他转运来自达纳苏斯的稀土。",al={"德纳兰的盟友","德纳兰向谁汇报"}},{q="德纳兰研究的布满苔藓的心脏是什么？",a="布满苔藓的心脏是从泰达希尔的被腐蚀的树苗怪——腐臭的黑苔（Blackmoss the Fetid）身上获得的一枚枯萎的植物核心。德纳兰在附魔土壤中研究它，以了解扭曲岛上植物生命的非自然病变。",al={"布满苔藓的心脏","布满苔藓的心脏任务","黑苔的心脏"}}},fp="7,223,27.391.0,36.422.0,25.176.0,44.260.0,41.268.0,42.211.0,27.165.0,52.232.0"}
